(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-antiquities-3-e", [{"sp": "HDR", "t": "Ἰουδαϊκὴ Ἀρχαιολογία"}, {"sp": "HDR", "t": "Βιβλίον Ηʹ", "st": "8"}, {"sp": "N", "t": "Περὶ μὲν οὖν Δαυίδου καὶ τῆς ἀρετῆς αὐτοῦ καὶ ὅσων ἀγαθῶν αἴτιος γενόμενος τοῖς ὁμοφύλοις πολέμους τε καὶ μάχας ὅσας κατορθώσας γηραιὸς ἐτελεύτησεν, ἐν τῇ πρὸ ταύτης βίβλῳ δεδηλώκαμεν. Σολόμωνος δὲ τοῦ παιδὸς αὐτοῦ νέου τὴν ἡλικίαν ἔτι ὄντος τὴν βασιλείαν παραλαβόντος, ὃν ἔτι ζῶν ἀπέφηνε τοῦ λαοῦ δεσπότην κατὰ τὴν τοῦ θεοῦ βούλησιν, καθίσαντος ἐπὶ τὸν θρόνον ὁ μὲν πᾶς ὄχλος ἐπευφήμησεν, οἷον εἰκὸς ἐπ’ ἀρχομένῳ βασιλεῖ, τελευτῆσαι καλῶς αὐτῷ τὰ πράγματα καὶ πρὸς γῆρας ἀφικέσθαι λιπαρὸν καὶ πανεύδαιμον τὴν ἡγεμονίαν.", "st": "8.1.1"}, {"sp": "N", "t": "Ἀδωνίας δέ, ὃς καὶ τοῦ πατρὸς ἔτι ζῶντος ἐπεχείρησε τὴν ἀρχὴν κατασχεῖν, παρελθὼν πρὸς τὴν τοῦ βασιλέως μητέρα Βερσάβην καὶ φιλοφρόνως αὐτὴν ἀσπασάμενος, πυθομένης εἰ καὶ διὰ χρείαν τινὰ πρὸς αὐτὴν ἀφῖκται καὶ δηλοῦν κελευούσης ὡς ἡδέως παρεξομένης ἤρξατο λέγειν, ὅτι γινώσκει μὲν τὴν βασιλείαν καὶ αὐτὴ καὶ διὰ τὴν ἡλικίαν καὶ διὰ τὴν τοῦ πλήθους προαίρεσιν οὖσαν αὐτοῦ, μεταβάσης δὲ πρὸς Σολόμωνα τὸν υἱὸν αὐτῆς κατὰ τὴν τοῦ θεοῦ γνώμην στέργει καὶ ἀγαπᾷ τὴν ὑπ’ αὐτῷ δουλείαν καὶ τοῖς παροῦσιν [ἥδεται πράγμασιν]. ἐδεῖτο δ’ οὖν διακονῆσαι πρὸς τὸν ἀδελφὸν αὐτῷ καὶ πεῖσαι δοῦναι τὴν τῷ πατρὶ συγκοιμωμένην πρὸς γάμον αὐτῷ Ἀβισάκην· οὐ γὰρ πλησιάσαι τὸν πατέρα διὰ τὸ γῆρας αὐτῇ, μένειν δ’ ἔτι παρθένον. ἡ δὲ Βερσάβη καὶ διακονήσειν σπουδαίως ὑπέσχετο καὶ καταπράξεσθαι τὸν γάμον δι’ ἀμφότερα, τοῦ τε βασιλέως αὐτῷ χαρίσασθαί τι βουλησομένου καὶ δεησομένης αὐτῆς λιπαρῶς. καὶ ὁ μὲν εὔελπις ἀπαλλάττεται περὶ τοῦ γάμου, ἡ δὲ τοῦ Σολόμωνος μήτηρ εὐθὺς ὥρμησεν ἐπὶ τὸν υἱὸν διαλεξομένη περὶ ὧν Ἀδωνίᾳ δεηθέντι κατεπηγγείλατο. καὶ προϋπαντήσαντος αὐτῇ τοῦ παιδὸς καὶ περιπλακέντος, ἐπεὶ παρήγαγεν εἰς τὸν οἶκον, οὗ συνέβαινεν αὐτῷ κεῖσθαι τὸν βασιλικὸν θρόνον, καθίσας ἐκέλευσεν ἕτερον ἐκ δεξιῶν τεθῆναι τῇ μητρί. καθεσθεῖσα δ’ ἡ Βερσάβη μίαν, εἶπεν, ὦ παῖ, χάριν αἰτουμένῃ κατάνευσον καὶ μηδὲν ἐξ ἀρνήσεως δύσκολον μηδὲ σκυθρωπὸν ἀπεργάσῃ. τοῦ δὲ Σολόμωνος προστάττειν κελεύοντος, πάντα γὰρ ὅσιον εἶναι μητρὶ παρέχειν, καί τι προσμεμψαμένου τὴν ἀρχήν, ὅτι μὴ μετ’ ἐλπίδος ἤδη βεβαίας τοῦ τυχεῖν ὧν ἀξιοῖ ποιεῖται τοὺς λόγους ἀλλ’ ἄρνησιν ὑφορωμένη, δοῦναι τὴν παρθένον αὐτὸν Ἀβισάκην Ἀδωνίᾳ τἀδελφῷ πρὸς γάμον παρεκάλει.", "st": "8.1.2"}, {"sp": "N", "t": "Λαβὼν δὲ πρὸς ὀργὴν ὁ βασιλεὺς τὸν λόγον ἀποπέμπεται μὲν τὴν μητέρα μειζόνων ὀρέγεσθαι πραγμάτων εἰπὼν Ἀδωνίαν καὶ θαυμάζειν, πῶς οὐ παραχωρῆσαι καὶ τῆς βασιλείας ὡς πρεσβυτέρῳ παρακαλεῖ τὸν γάμον αὐτῷ τὸν Ἀβισάκης αἰτουμένη φίλους ἔχοντι δυνατοὺς Ἰώαβον τὸν στρατηγὸν καὶ Ἀβιάθαρον τὸν ἱερέα, μεταπεμψάμενος δὲ Βαναίαν τὸν ἐπὶ τῶν σωματοφυλάκων ἀποκτεῖναι προσέταξεν αὐτῷ τὸν ἀδελφὸν Ἀδωνίαν. καλέσας δὲ τὸν Ἀβιάθαρον τὸν ἱερέα θανάτου μέν, εἶπε, ῥύεταί σε τά τε ἄλλα ὅσα τῷ πατρὶ συνέκαμες καὶ ἡ κιβωτός, ἣν σὺν αὐτῷ μετήνεγκας. ταύτην δέ σοι τὴν τιμωρίαν ἐπιτίθημι ταξαμένῳ μετὰ Ἀδωνία καὶ τὰ ἐκείνου φρονήσαντι· μήτε ἐνθάδε ἴσθι μήτε εἰς ὄψιν ἀπάντα τὴν ἐμήν, ἀλλ’ εἰς τὴν πατρίδα πορευθεὶς ἐν τοῖς ἀγροῖς ζῆθι καὶ τοῦτον ἄχρι τελευτῆς ἔχε τὸν βίον ἁμαρτὼν τοῦ μηκέτ’ εἶναι δικαίως ἐν ἀξίᾳ. καταλύεται μὲν οὖν ἀπὸ τῆς ἱερατικῆς τιμῆς ὁ Ἰθαμάρου οἶκος διὰ τὴν προειρημένην αἰτίαν, καθὼς καὶ τῷ Ἀβιαθάρου πάππῳ προεῖπεν ὁ θεὸς Ἠλεί, μετέβη δ’ εἰς τὸ Φιναάσου γένος πρὸς Σάδωκον. οἱ δὲ ἰδιωτεύσαντες ἐκ τοῦ Φιναάσου γένους καθ’ ὃν καιρὸν εἰς τὸν Ἰθαμάρου οἶκον ἡ ἀρχιερωσύνη μετῆλθεν Ἠλεὶ πρώτου ταύτην παραλαβόντος ἦσαν οὗτοι· ὁ τοῦ ἀρχιερέως Ἰησοῦ υἱὸς Βοκίας, τούτου δὲ Ἰώθαμος, Ἰωθάμου δὲ Μαραίωθος, Μαραιώθου δὲ Ἀροφαῖος, Ἀροφαίου δὲ Ἀχίτωβος, Ἀχιτώβου δὲ Σάδωκος, ὃς πρῶτος ἐπὶ Δαυίδου τοῦ βασιλέως ἀρχιερεὺς ἐγένετο.", "st": "8.1.3"}, {"sp": "N", "t": "Ἰώαβος δὲ ὁ στρατηγὸς τὴν ἀναίρεσιν ἀκούσας Ἀδωνία περιδεὴς ἐγένετο, φίλος γὰρ ἦν αὐτῷ μᾶλλον ἢ τῷ βασιλεῖ Σολόμωνι, καὶ κίνδυνον ἐκ τούτου διὰ τὴν πρὸς ἐκεῖνον εὔνοιαν οὐκ ἀλόγως ὑποπτεύων καταφεύγει μὲν ἐπὶ τὸ θυσιαστήριον, ἀσφάλειαν δὲ ἐνόμιζεν αὑτῷ ποριεῖν ἐκ τῆς πρὸς τὸν θεὸν εὐσεβείας τοῦ βασιλέως. ὁ δὲ ἀπαγγειλάντων αὐτῷ τινων τὴν Ἰωάβου γνώμην πέμψας Βαναίαν ἐκέλευσεν ἀναστήσαντα ἄγειν ἐπὶ τὸ δικαστήριον ὡς ἀπολογησόμενον. Ἰώαβος δὲ οὐκ ἔφη καταλείψειν τὸ ἱερόν, ἀλλ’ αὐτοῦ τεθνήξεσθαι μᾶλλον ἢ ἐν ἑτέρῳ χωρίῳ. Βαναίου δὲ τὴν ἀπόκρισιν αὐτοῦ τῷ βασιλεῖ δηλώσαντος προσέταξεν ὁ Σολόμων ἐκεῖ τὴν κεφαλὴν αὐτοῦ ἀποτεμεῖν, καθὼς βούλεται, καὶ ταύτην λαβεῖν τὴν δίκην ὑπὲρ τῶν δύο στρατηγῶν, οὓς ὁ Ἰώαβος ἀνοσίως ἀπέκτεινε, θάψαι δ’ αὐτοῦ τὸ σῶμα, ὅπως τὰ μὲν ἁμαρτήματα μηδέποτε καταλείπῃ τὸ γένος τὸ ἐκείνου, τῆς δὲ Ἰωάβου τελευτῆς αὐτός τε καὶ ὁ πατὴρ ἀθῷοι τυγχάνωσι. καὶ Βαναίας μὲν τὰ κελευσθέντα ποιήσας αὐτὸς ἀποδείκνυται στρατηγὸς πάσης τῆς δυνάμεως, Σάδωκον δὲ ποιεῖ μόνον ἀρχιερέα ὁ βασιλεὺς εἰς τὸν Ἀβιαθάρου τόπον, ὃν μετεστήσατο.", "st": "8.1.4"}, {"sp": "N", "t": "Σουμουίσῳ δὲ προσέταξεν οἰκίαν οἰκοδομήσαντι μένειν ἐν Ἱεροσολύμοις αὐτῷ προσεδρεύοντι καὶ μὴ διαβαίνειν τὸν χειμάρρουν Κεδρῶνα ἔχειν ἐξουσίαν, παρακούσαντι δὲ τούτων θάνατον ἔσεσθαι τὸ πρόστιμον. τῷ δὲ μεγέθει τῆς ἀπειλῆς καὶ ὅρκους αὐτῷ προσηνάγκασε ποιήσασθαι. Σουμούισος δὲ χαίρειν οἷς προσέταξεν αὐτῷ Σολόμων φήσας καὶ ταῦτα ποιήσειν προσομόσας καταλιπὼν τὴν πατρίδα τὴν διατριβὴν ἐν τοῖς Ἱεροσολύμοις ἐποιεῖτο. διελθόντων δὲ τριῶν ἐτῶν ἀκούσας δύο δούλους ἀποδράντας αὐτὸν ἐν Γίττῃ τυγχάνοντας ὥρμησεν ἐπὶ τοὺς οἰκέτας. ἐπανελθόντος δὲ μετ’ αὐτῶν ὁ βασιλεὺς αἰσθόμενος, ὡς καὶ τῶν ἐντολῶν αὐτοῦ καταφρονήσαντος καὶ τὸ μεῖζον τῶν ὅρκων τοῦ θεοῦ μηδεμίαν ποιησαμένου φροντίδα, χαλεπῶς εἶχε καὶ καλέσας αὐτόν οὐ σύ, φησίν, ὤμοσας μὴ καταλείψειν ἐμὲ μηδ’ ἐξελεύσεσθαί ποτ’ ἐκ ταύτης τῆς πόλεως εἰς ἄλλην; οὔκουν ἀποδράσῃ τὴν τῆς ἐπιορκίας δίκην, ἀλλὰ καὶ ταύτης καὶ ὧν τὸν πατέρα μου παρὰ τὴν φυγὴν ὕβρισας τιμωρήσομαί σε πονηρὸν γενόμενον, ἵνα γνῷς ὅτι κερδαίνουσι μὲν οὐδὲν οἱ κακοὶ μὴ παρ’ αὐτὰ τἀδικήματα κολασθέντες, ἀλλὰ παντὶ τῷ χρόνῳ ᾧ νομίζουσιν ἀδεεῖς εἶναι μηδὲν πεπονθότες αὔξεται καὶ γίνεται μείζων ἡ κόλασις αὐτοῖς ἧς ἂν παραυτίκα πλημμελήσαντες ἔδοσαν. καὶ Σουμούισον μὲν κελευσθεὶς Βαναίας ἀπέκτεινεν.", "st": "8.1.5"}, {"sp": "N", "t": "Ἤδη δὲ τὴν βασιλείαν βεβαίως ἔχων Σολόμων καὶ τῶν ἐχθρῶν κεκολασμένων ἄγεται τὴν Φαραώθου τοῦ τῶν Αἰγυπτίων βασιλέως θυγατέρα· καὶ κατασκευάσας τὰ τείχη [τῶν] Ἱεροσολύμων πολλῷ μείζω καὶ ὀχυρώτερα τῶν πρόσθεν ὄντων διεῖπε τὰ πράγματα λοιπὸν ἐπὶ πολλῆς εἰρήνης μηδ’ ὑπὸ τῆς νεότητος πρός τε δικαιοσύνην καὶ φυλακὴν τῶν νόμων καὶ μνήμην ὧν ὁ πατὴρ τελευτῶν ἐπέστειλε βλαπτόμενος, ἀλλὰ πάνθ’ ὅσα οἱ τοῖς χρόνοις προβεβηκότες καὶ πρὸς τὸ φρονεῖν ἀκμάζοντες μετὰ πολλῆς ἀκριβείας ἐπιτελῶν. ἔγνω δ’ εἰς Γιβρῶνα παραγενόμενος ἐπὶ τοῦ χαλκέου θυσιαστηρίου τοῦ κατασκευασθέντος ὑπὸ Μουσείου θῦσαι τῷ θεῷ καὶ χίλια τὸν ἀριθμὸν ὡλοκαύτωσεν ἱερεῖα. τοῦτο δὲ ποιήσας μεγάλως ἔδοξε τὸν θεὸν τετιμηκέναι· φανεὶς γὰρ αὐτῷ κατὰ τοὺς ὕπνους ἐκείνης τῆς νυκτὸς ἐκέλευσεν αἱρεῖσθαι, τίνας ἀντὶ τῆς εὐσεβείας παράσχῃ δωρεὰς αὐτῷ. Σολόμων δὲ τὰ κάλλιστα καὶ μέγιστα καὶ θεῷ παρασχεῖν ἥδιστα καὶ λαβεῖν ἀνθρώπῳ συμφορώτατα τὸν θεὸν ᾔτησεν· οὐ γὰρ χρυσὸν οὐδ’ ἄργυρον οὐδὲ τὸν ἄλλον πλοῦτον ὡς ἄνθρωπος καὶ νέος ἠξίωσεν αὑτῷ προσγενέσθαι, ταῦτα γὰρ σχεδὸν νενόμισται παρὰ τοῖς πλείστοις μόνα σπουδῆς ἄξια καὶ θεοῦ δῶρα εἶναι, ἀλλὰ δός μοι φησί, δέσποτα, νοῦν ὑγιῆ καὶ φρόνησιν ἀγαθήν, οἷς ἂν τὸν λαὸν τἀληθῆ καὶ τὰ δίκαια λαβὼν κρίνοιμι. τούτοις ἥσθη τοῖς αἰτήμασιν ὁ θεὸς καὶ τά τε ἄλλα πάνθ’ ὧν οὐκ ἐμνήσθη παρὰ τὴν ἐκλογὴν δώσειν ἐπηγγείλατο πλοῦτον δόξαν νίκην πολεμίων, καὶ πρὸ πάντων σύνεσιν καὶ σοφίαν οἵαν οὐκ ἄλλος τις ἀνθρώπων ἔσχεν οὔτε βασιλέων οὔτ’ ἰδιωτῶν, φυλάξειν τε καὶ τοῖς ἐκγόνοις αὐτοῦ τὴν βασιλείαν ἐπὶ πλεῖστον ὑπισχνεῖτο χρόνον, ἂν δίκαιός τε ὢν διαμένῃ καὶ πειθόμενος αὐτῷ καὶ τὸν πατέρα μιμούμενος ἐν οἷς ἦν ἄριστος. ταῦτα τοῦ θεοῦ Σολόμων ἀκούσας ἀνεπήδησεν εὐθὺς ἐκ τῆς κοίτης καὶ προσκυνήσας αὐτὸν ὑπέστρεψεν εἰς Ἱεροσόλυμα, καὶ πρὸ τῆς σκηνῆς μεγάλας ἐπιτελέσας θυσίας κατευωχεῖ τοὺς Ἰουδαίους ἅπαντας.", "st": "8.2.1"}, {"sp": "N", "t": "Ταύταις δὲ ταῖς ἡμέραις κρίσις ἐπ’ αὐτὸν ἤχθη δυσχερής, ἧς τὸ τέλος εὑρεῖν ἦν ἐπίπονον· τὸ δὲ πρᾶγμα περὶ οὗ συνέβαινεν εἶναι τὴν δίκην ἀναγκαῖον ἡγησάμην δηλῶσαι, ἵνα τοῖς ἐντυγχάνουσι τό τε δύσκολον τῆς κρίσεως γνώριμον ὑπάρξῃ, καὶ τοιούτων μεταξὺ πραγμάτων γενόμενοι λάβωσιν ὥσπερ ἐξ εἰκόνος τῆς τοῦ βασιλέως ἀγχινοίας τὸ ῥᾳδίως ἀποφαίνεσθαι περὶ τῶν ζητουμένων δυνηθῆναι. δύο γυναῖκες ἑταῖραι τὸν βίον ἧκον ἐπ’ αὐτόν, ὧν ἡ ἀδικεῖσθαι δοκοῦσα πρώτη λέγειν ἤρξατο· οἰκῶ μέν, εἶπεν, ὦ βασιλεῦ, μετὰ ταύτης ἐν ἑνὶ δωματίῳ, συνέβη δ’ ἀμφοτέραις ἡμῖν ἐπὶ μιᾶς ἡμέρας ἀποτεκεῖν κατὰ τὴν αὐτὴν ὥραν ἄρρενα παιδία. τρίτης δὲ ἡμέρας διελθούσης ἐπικοιμηθεῖσα τῷ αὑτῆς παιδίῳ αὕτη τοῦτο μὲν ἀποκτείνει, βαστάσασα δὲ τοὐμὸν ἐκ τῶν γονάτων πρὸς αὑτὴν μεταφέρει καὶ τὸ νεκρὸν ἐμοῦ κοιμωμένης εἰς τὰς ἀγκάλας μου τίθησι. πρωῒ δὲ θηλὴν ὀρέξαι βουλομένη τῷ παιδίῳ τὸ μὲν ἐμὸν οὐχ εὗρον, τὸ δὲ ταύτης νεκρὸν ὁρῶ μοι παρακείμενον· ἀκριβῶς γὰρ κατανοήσασα τοῦτο ἐπέγνων· ὅθεν ἀπαιτῶ τὸν ἐμὸν υἱὸν καὶ οὐκ ἀπολαμβάνουσα καταπέφευγα, δέσποτα, ἐπὶ τὴν παρὰ σοῦ βοήθειαν· τῷ γὰρ εἶναι μόνας καὶ μηδένα τὸν ἐλέγξαι δυνάμενον φοβεῖσθαι καταφρονοῦσα ἰσχυρῶς ἀρνουμένη παραμένει. ταῦτ’ εἰπούσης ὁ βασιλεὺς ἀνέκρινε τὴν ἑτέραν, τί τοῖς εἰρημένοις ἀντιλέγειν ἔχει. τῆς δὲ ἀρνουμένης τοῦτο πεποιηκέναι, τὸ δὲ παιδίον ζῆν τὸ αὑτῆς λεγούσης, τὸ δὲ τῆς ἀντιδίκου τεθνηκέναι, μηδενὸς ἐπινοοῦντος τὴν κρίσιν ἀλλ’ ὥσπερ ἐπ’ αἰνίγματι περὶ τὴν εὕρεσιν αὐτοῦ πάντων τῇ διανοίᾳ τετυφλωμένων μόνος ὁ βασιλεὺς ἐπενόησέ τι τοιοῦτον· κελεύσας κομισθῆναι καὶ τὸ νεκρὸν καὶ τὸ ζῶν παιδίον μεταπέμπεταί τινα τῶν σωματοφυλάκων καὶ σπασάμενον ἐκέλευσε τὴν μάχαιραν ἀμφότερα διχοτομῆσαι τὰ παιδία, ὅπως ἑκάτεραι λάβωσιν ἀνὰ ἥμισυ τοῦ τε ζῶντος καὶ τοῦ τετελευτηκότος. ἐπὶ τούτῳ πᾶς μὲν ὁ λαὸς λανθάνων ἐχλεύαζεν ὡς μειράκιον τὸν βασιλέα, μεταξὺ δὲ τῆς μὲν ἀπαιτούσης καὶ ἀληθοῦς μητρὸς ἀνακραγούσης τοῦτο μὴ ποιεῖν ἀλλὰ παραδιδόναι τῇ ἑτέρᾳ τὸ παιδίον ὡς ἐκείνης, ἀρκεῖσθαι γὰρ τῷ ζῆν αὐτὸ καὶ βλέπειν μόνον κἂν ἀλλότριον δοκῇ, τῆς δ’ ἑτέρας ἑτοίμως ἐχούσης διαιρούμενον ἰδεῖν τὸ παιδίον καὶ προσέτι βασανισθῆναι καὶ αὐτὴν ἀξιούσης, ὁ βασιλεὺς ἐπιγνοὺς τὰς ἑκατέρων φωνὰς ἀπὸ τῆς ἀληθείας γεγενημένας τῇ μὲν ἀνακραγούσῃ τὸ παιδίον προσέκρινε, μητέρα γὰρ αὐτὴν ἀληθῶς εἶναι, τῆς δὲ ἄλλης κατέγνω πονηρίαν τό τε ἴδιον ἀποκτεινάσης καὶ τὸ τῆς φίλης σπουδαζούσης ἀπολλύμενον θεάσασθαι. τοῦτο μέγα δεῖγμα καὶ τεκμήριον τῆς τοῦ βασιλέως φρονήσεως καὶ σοφίας ἐνόμιζε τὸ πλῆθος, κἀξ ἐκείνης τὸ λοιπὸν τῆς ἡμέρας ὡς θείαν ἔχοντι διάνοιαν αὐτῷ προσεῖχον.", "st": "8.2.2"}, {"sp": "N", "t": "Στρατηγοὶ δ’ αὐτῷ καὶ ἡγεμόνες ἦσαν τῆς χώρας ἁπάσης οἵδε· τῆς μὲν Ἐφραίμου κληρουχίας Οὔρης· ἐπὶ δὲ τῆς Βιθιέμες τοπαρχίας ἦν Διόκληρος· τὴν δὲ τῶν Δώρων καὶ τὴν παραλίαν Ἀβινάδαβος εἶχεν ὑπ’ αὐτῷ γεγαμηκὼς τὴν Σολόμωνος θυγατέρα· τὸ δὲ μέγα πεδίον ἦν ὑπὸ Βαναίᾳ τῷ Ἀχίλου παιδί, προσεπῆρχε δὲ καὶ τῆς ἄχρι Ἰορδάνου πάσης· τὴν δὲ Γαλαδῖτιν καὶ Γαυλανῖτιν ἕως τοῦ Λιβάνου ὄρους καὶ πόλεις ἑξήκοντα μεγάλας καὶ ὀχυρωτάτας ἔχων ὑφ’ αὑτὸν Γαβάρης διεῖπεν· Ἀχινάδαβος δὲ τῆς Γαλιλαίας ὅλης ἄχρι Σιδῶνος ἐπετρόπευε συνοικῶν καὶ αὐτὸς θυγατρὶ Σολόμωνος Βασίμα τοὔνομα· τὴν δὲ περὶ Ἀκὴν παραλίαν εἶχε Βανακάτης· Σαφάτης δὲ τὸ Ἰταβύριον ὄρος καὶ Καρμήλιον καὶ τὴν κάτω Γαλιλαίαν ἄχρι τοῦ ποταμοῦ Ἰορδάνου χώραν ἐπὶ τούτῳ πᾶσαν ἐπετέτραπτο· Σουμούις δὲ τὴν τῆς Βενιαμίδος κληρουχίαν ἐγκεχείριστο· Γαβάρης δὲ εἶχε τὴν πέραν τοῦ Ἰορδάνου χώραν· ἐπὶ δὲ τούτων εἷς πάλιν ἄρχων ἀποδέδεικτο. θαυμαστὴν δ’ ἐπίδοσιν ἔλαβεν ὅ τε τῶν Ἑβραίων λαὸς καὶ ἡ Ἰούδα φυλὴ πρὸς γεωργίαν τραπέντων καὶ τὴν τῆς γῆς ἐπιμέλειαν· εἰρήνης γὰρ ἀπολαύοντες καὶ πολέμοις καὶ ταραχαῖς μὴ περισπώμενοι καὶ προσέτι τῆς ποθεινοτάτης ἐλευθερίας ἀκρατῶς ἐμφορούμενοι πρὸς τῷ συναύξειν ἕκαστος τὰ οἰκεῖα καὶ ποιεῖν ἄξια πλείονος ὑπῆρχεν.", "st": "8.2.3"}, {"sp": "N", "t": "Ἦσαν δὲ καὶ ἕτεροι τῷ βασιλεῖ ἡγεμόνες, οἳ τῆς τε Σύρων γῆς καὶ τῶν ἀλλοφύλων ἥτις ἦν ἀπ’ Εὐφράτου ποταμοῦ διήκουσα μέχρι τῆς Αἰγυπτίων ἐπῆρχον ἐκλέγοντες αὐτῷ φόρους παρὰ τῶν ἐθνῶν. συνετέλουν δὲ καὶ τῇ τραπέζῃ καθ’ ἡμέραν καὶ τῷ δείπνῳ τοῦ βασιλέως σεμιδάλεως μὲν κόρους τριάκοντα, ἀλεύρου δὲ ξ, σιτιστοὺς δὲ βόας δέκα καὶ νομάδας βόας εἴκοσι, σιτιστοὺς δὲ ἄρνας ἑκατόν. ταῦτα πάντα πάρεξ τῶν ἀπ’ ἄγρας ἐλάφων λέγω καὶ βουβάλων καὶ τῶν πετεινῶν καὶ ἰχθύων ἐκομίζετο καθ’ ἡμέραν βασιλεῖ παρὰ τῶν ἀλλοφύλων. τοσοῦτον δὲ πλῆθος ἦν ἁρμάτων Σολόμωνι, ὡς τέσσαρας εἶναι μυριάδας φατνῶν τῶν ὑποζευγνυμένων ἵππων· χωρὶς δὲ τούτων ἦσαν ἱππεῖς δισχίλιοι καὶ μύριοι, ὧν οἱ μὲν ἡμίσεις τῷ βασιλεῖ προσήδρευον ἐν Ἱεροσολύμοις, οἱ δὲ λοιποὶ κατὰ τὰς βασιλικὰς διεσπαρμένοι κώμας ἐν αὐταῖς κατέμενον. ὁ δ’ αὐτὸς ἡγεμὼν ὁ τὴν τοῦ βασιλέως δαπάνην πεπιστευμένος καὶ τοῖς ἵπποις ἐχορήγει τὰ ἐπιτήδεια συγκομίζων εἰς ὃν ὁ βασιλεὺς διέτριβε τόπον.", "st": "8.2.4"}, {"sp": "N", "t": "Τοσαύτη δ’ ἦν ἣν ὁ θεὸς παρέσχε Σολόμωνι φρόνησιν καὶ σοφίαν, ὡς τούς τε ἀρχαίους ὑπερβάλλειν ἀνθρώπους καὶ μηδὲ τοὺς Αἰγυπτίους, οἳ πάντων συνέσει διενεγκεῖν λέγονται, συγκρινομένους λείπεσθαι παρ’ ὀλίγον, ἀλλὰ πλεῖστον ἀφεστηκότας τῆς τοῦ βασιλέως φρονήσεως ἐλέγχεσθαι. ὑπερῆρε δὲ καὶ διήνεγκε σοφίᾳ καὶ τῶν κατὰ τὸν αὐτὸν καιρὸν δόξαν ἐχόντων παρὰ τοῖς Ἑβραίοις ἐπὶ δεινότητι, ὧν οὐ παρελεύσομαι τὰ ὀνόματα· ἦσαν δὲ Ἄθανος καὶ Αἱμανὸς καὶ Χάλκεος καὶ Δάρδανος υἱοὶ Ἡμάωνος. συνετάξατο δὲ καὶ βιβλία περὶ ᾠδῶν καὶ μελῶν πέντε πρὸς τοῖς χιλίοις καὶ παραβολῶν καὶ εἰκόνων βίβλους τρισχιλίας· καθ’ ἕκαστον γὰρ εἶδος δένδρου παραβολὴν εἶπεν ἀπὸ ὑσσώπου ἕως κέδρου, τὸν αὐτὸν δὲ τρόπον καὶ περὶ κτηνῶν καὶ τῶν ἐπιγείων ἁπάντων ζῴων καὶ τῶν νηκτῶν καὶ τῶν ἀερίων· οὐδεμίαν γὰρ φύσιν ἠγνόησεν οὐδὲ παρῆλθεν ἀνεξέταστον, ἀλλ’ ἐν πάσαις ἐφιλοσόφησε καὶ τὴν ἐπιστήμην τῶν ἐν αὐταῖς ἰδιωμάτων ἄκραν ἐπεδείξατο. παρέσχε δ’ αὐτῷ μαθεῖν ὁ θεὸς καὶ τὴν κατὰ τῶν δαιμόνων τέχνην εἰς ὠφέλειαν καὶ θεραπείαν τοῖς ἀνθρώποις· ἐπῳδάς τε συνταξάμενος αἷς παρηγορεῖται τὰ νοσήματα καὶ τρόπους ἐξορκώσεων κατέλιπεν, οἷς οἱ ἐνδούμενοι τὰ δαιμόνια ὡς μηκέτ’ ἐπανελθεῖν ἐκδιώξουσι. καὶ αὕτη μέχρι νῦν παρ’ ἡμῖν ἡ θεραπεία πλεῖστον ἰσχύει· ἱστόρησα γάρ τινα Ἐλεάζαρον τῶν ὁμοφύλων Οὐεσπασιανοῦ παρόντος καὶ τῶν υἱῶν αὐτοῦ καὶ χιλιάρχων καὶ ἄλλου στρατιωτικοῦ πλήθους ὑπὸ τῶν δαιμονίων λαμβανομένους ἀπολύοντα τούτων. ὁ δὲ τρόπος τῆς θεραπείας τοιοῦτος ἦν· προσφέρων ταῖς ῥισὶ τοῦ δαιμονιζομένου τὸν δακτύλιον ἔχοντα ὑπὸ τῇ σφραγῖδι ῥίζαν ἐξ ὧν ὑπέδειξε Σολόμων ἔπειτα ἐξεῖλκεν ὀσφρομένῳ διὰ τῶν μυκτήρων τὸ δαιμόνιον, καὶ πεσόντος εὐθὺς τἀνθρώπου μηκέτ’ εἰς αὐτὸν ἐπανήξειν ὥρκου, Σολόμωνός τε μεμνημένος καὶ τὰς ἐπῳδὰς ἃς συνέθηκεν ἐκεῖνος ἐπιλέγων. βουλόμενος δὲ πεῖσαι καὶ παραστῆσαι τοῖς παρατυγχάνουσιν ὁ Ἐλεάζαρος, ὅτι ταύτην ἔχει τὴν ἰσχύν, ἐτίθει μικρὸν ἔμπροσθεν ἤτοι ποτήριον πλῆρες ὕδατος ἢ ποδόνιπτρον καὶ τῷ δαιμονίῳ προσέταττεν ἐξιὸν τἀνθρώπου ταῦτα ἀνατρέψαι καὶ παρασχεῖν ἐπιγνῶναι τοῖς ὁρῶσιν, ὅτι καταλέλοιπε τὸν ἄνθρωπον. γινομένου δὲ τούτου σαφὴς ἡ Σολόμωνος καθίστατο σύνεσις καὶ σοφία δι’ ἣν, ἵνα γνῶσιν ἅπαντες αὐτοῦ τὸ μεγαλεῖον τῆς φύσεως καὶ τὸ θεοφιλὲς καὶ λάθῃ μηδένα τῶν ὑπὸ τὸν ἥλιον ἡ τοῦ βασιλέως περὶ πᾶν εἶδος ἀρετῆς ὑπερβολή, περὶ τούτων εἰπεῖν προήχθημεν.", "st": "8.2.5"}, {"sp": "N", "t": "Ὁ δὲ τῶν Τυρίων βασιλεὺς Εἴρωμος ἀκούσας ὅτι Σολόμων τὴν τοῦ πατρὸς διεδέξατο βασιλείαν ὑπερήσθη, φίλος γὰρ ἐτύγχανε τῷ Δαυίδῃ, καὶ πέμψας πρὸς αὐτὸν ἠσπάζετό τε καὶ συνέχαιρεν ἐπὶ τοῖς παροῦσιν ἀγαθοῖς. ἀποστέλλει δὲ πρὸς αὐτὸν Σολόμων γράμματα δηλοῦντα τάδε· βασιλεὺς Σολόμων Εἱρώμῳ βασιλεῖ. ἴσθι μου τὸν πατέρα βουληθέντα κατασκευάσαι τῷ θεῷ ναὸν ὑπὸ τῶν πολέμων καὶ τῶν συνεχῶν στρατειῶν κεκωλυμένον· οὐ γὰρ ἐπαύσατο πρότερον τοὺς ἐχθροὺς καταστρεφόμενος πρὶν ἢ πάντας αὐτοὺς φόρων ὑποτελεῖς πεποιηκέναι. ἐγὼ δὲ χάριν οἶδα τῷ θεῷ τῆς παρούσης εἰρήνης καὶ διὰ ταύτην εὐσχολῶν οἰκοδομῆσαι τῷ θεῷ βούλομαι τὸν οἶκον· καὶ γὰρ ὑπ’ ἐμοῦ τοῦτον ἔσεσθαι τῷ πατρί μου προεῖπεν ὁ θεός. διὸ παρακαλῶ σε συμπέμψαι τινὰς τοῖς ἐμοῖς εἰς Λίβανον τὸ ὄρος κόψοντας ξύλα· πρὸς γὰρ τομὴν ὕλης ἐπιστημονέστερον ἔχουσι τῶν ἡμετέρων οἱ Σιδώνιοι. μισθὸν δ’ ὃν ἂν ὁρίσῃς ἐγὼ τοῖς ὑλουργοῖς παρέξω.", "st": "8.2.6"}, {"sp": "N", "t": "Ἀναγνοὺς δὲ τὴν ἐπιστολὴν Εἵρωμος καὶ τοῖς ἐπεσταλμένοις ἡσθεὶς ἀντιγράφει τῷ Σολόμωνι· βασιλεὺς Εἵρωμος βασιλεῖ Σολόμωνι. τὸν μὲν θεὸν εὐλογεῖν ἄξιον, ὅτι σοι τὴν πατρῴαν παρέδωκεν ἡγεμονίαν ἀνδρὶ σοφῷ καὶ πᾶσαν ἀρετὴν ἔχοντι, ἐγὼ δὲ τούτοις ἡδόμενος ἅπαντα ὑπουργήσω τὰ ἐπεσταλμένα· τεμὼν γὰρ ξύλα πολλὰ καὶ μεγάλα κέδρου τε καὶ κυπαρίσσου διὰ τῶν ἐμῶν καταπέμψω ἐπὶ θάλασσαν καὶ κελεύσω τοὺς ἐμοὺς σχεδίαν πηξαμένους εἰς ὃν ἂν βουληθῇς τόπον τῆς σαυτοῦ χώρας πλεύσαντας ἀποθέσθαι· ἔπειθ’ οἱ σοὶ διακομίσουσιν εἰς Ἱεροσόλυμα. ὅπως δὲ καὶ σὺ παράσχῃς ἡμῖν ἀντὶ τούτων σῖτον, οὗ διὰ τὸ νῆσον οἰκεῖν δεόμεθα, φρόντισον.", "st": "8.2.7"}, {"sp": "N", "t": "Διαμένει δὲ ἄχρι τῆς τήμερον τὰ τῶν ἐπιστολῶν τούτων ἀντίγραφα οὐκ ἐν τοῖς ἡμετέροις μόνον σωζόμενα βιβλίοις ἀλλὰ καὶ παρὰ Τυρίοις, ὥστε εἴ τις ἐθελήσειε τὸ ἀκριβὲς μαθεῖν, δεηθεὶς τῶν ἐπὶ τοῦ Τυρίων γραμματοφυλακείου δημοσίων εὕροι συμφωνοῦντα τοῖς εἰρημένοις ὑφ’ ἡμῶν τὰ παρ’ ἐκείνοις. ταῦτα μὲν οὖν διεξῆλθον βουλόμενος γνῶναι τοὺς ἐντευξομένους, ὅτι μηδὲν μᾶλλον ἔξω τῆς ἀληθείας λέγομεν, μηδὲ πιθανοῖς τισι καὶ πρὸς ἀπάτην καὶ τέρψιν ἐπαγωγοῖς τὴν ἱστορίαν διαλαμβάνοντες τὴν μὲν ἐξέτασιν φεύγειν πειρώμεθα, πιστεύεσθαι δ’ εὐθὺς ἀξιοῦμεν, οὐδὲ συγκεχωρημένον ἡμῖν κατεξανισταμένοις τοῦ πρέποντος τῇ πραγματείᾳ ἀθῴοις ὑπάρχειν, ἀλλὰ μηδεμιᾶς ἀποδοχῆς τυγχάνειν παρακαλοῦντες, ἂν μὴ μετὰ ἀποδείξεως καὶ τεκμηρίων ἰσχυρῶν ἐμφανίζειν δυνώμεθα τὴν ἀλήθειαν.", "st": "8.2.8"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς Σολόμων ὡς ἐκομίσθη τὰ παρὰ Τυρίων βασιλέως γράμματα τήν τε προθυμίαν αὐτοῦ καὶ τὴν εὔνοιαν ἐπῄνεσε καὶ οἷς ἠξίωσε τούτοις αὐτὸν ἠμείψατο, σίτου μὲν αὐτῷ κατ’ ἔτος πέμψας δισμυρίους κόρους καὶ τοσούτους ἐλαίου βάτους, ὁ δὲ βάτος δύναται ξέστας ἑβδομήκοντα δύο· τὸ δ’ αὐτὸ μέτρον καὶ οἴνου παρεῖχεν. ἡ μὲν οὖν Εἱρώμου φιλία καὶ Σολόμωνος ἀπὸ τούτων ἔτι μᾶλλον ηὔξησε καὶ διαμένειν ὤμοσαν εἰς ἅπαν. ὁ δὲ βασιλεὺς ἐπέταξε παντὶ τῷ λαῷ φόρον ἐργάτας τρισμυρίους, οἷς ἄπονον τὴν ἐργασίαν κατέστησε μερίσας αὐτὴν συνετῶς· μυρίους γὰρ ἐποίησε κόπτοντας ἐπὶ μῆνα ἕνα ἐν Λιβάνῳ ὄρει δύο μῆνας ἀναπαύεσθαι παραγινομένους ἐπὶ τὰ οἰκεῖα, μέχρις οὗ πάλιν οἱ δισμύριοι τὴν ἐργασίαν ἀναπληρώσωσι κατὰ τὸν ὡρισμένον χρόνον ἔπειθ’ οὕτως συνέβαινε τοῖς πρώτοις μυρίοις διὰ τετάρτου μηνὸς ἀπαντᾶν ἐπὶ τὸ ἔργον. ἐγεγόνει δ’ ἐπίτροπος τοῦ φόρου τούτου Ἀδώραμος. ἦσαν δ’ ἐκ τῶν παροίκων οὓς Δαυίδης καταλελοίπει τῶν μὲν παρακομιζόντων τὴν λιθίαν καὶ τὴν ἄλλην ὕλην ἑπτὰ μυριάδες, τῶν δὲ λατομούντων ὀκτάκις μύριοι, τούτων δ’ ἐπιστάται τρισχίλιοι καὶ τριακόσιοι. προστετάχει δὲ λίθους μὲν αὐτοῖς τέμνειν μεγάλους εἰς τοὺς τοῦ ναοῦ θεμελίους, ἁρμόσαντας δὲ πρῶτον καὶ συνδήσαντας ἐν τῷ ὄρει κατακομίζειν οὕτως εἰς τὴν πόλιν. ἐγίνετο δὲ ταῦτ’ οὐ παρὰ τῶν οἰκοδόμων τῶν ἐγχωρίων μόνον, ἀλλὰ καὶ ὧν ὁ Εἵρωμος ἔπεμψε τεχνιτῶν.", "st": "8.2.9"}, {"sp": "N", "t": "Τῆς δ’ οἰκοδομίας τοῦ ναοῦ Σολόμων ἤρξατο τέταρτον ἔτος ἤδη τῆς βασιλείας ἔχων μηνὶ δευτέρῳ, ὃν Μακεδόνες μὲν Ἀρτεμίσιον καλοῦσιν Ἑβραῖοι δὲ Ἰάρ, μετὰ ἔτη πεντακόσια καὶ ἐνενήκοντα καὶ δύο τῆς ἀπ’ Αἰγύπτου τῶν Ἰσραηλιτῶν ἐξόδου, μετὰ δὲ χίλια καὶ εἴκοσι ἔτη τῆς Ἁβράμου εἰς τὴν Χαναναίαν ἐκ τῆς Μεσοποταμίας ἀφίξεως, ἀπὸ δὲ τῆς ἐπομβρίας μετὰ χίλια καὶ τετρακόσια καὶ τεσσαράκοντα· ἀπὸ δὲ τοῦ πρώτου γεννηθέντος Ἀδάμου ἕως οὗ τὸν ναὸν ᾠκοδόμησε Σολόμων διεληλύθει τὰ πάντα ἔτη τρισχίλια καὶ ἑκατὸν δύο. καθ’ ὃν δὲ ὁ ναὸς ἤρξατο οἰκοδομεῖσθαι χρόνον, κατ’ ἐκεῖνον ἔτος ἤδη τῆς ἐν Τύρῳ βασιλείας ἑνδέκατον ἐνειστήκει Εἱρώμῳ, τῆς δὲ οἰκήσεως εἰς τὴν οἰκοδομίαν τοῦ ναοῦ διεγεγόνει χρόνος ἐτῶν τεσσαράκοντα καὶ διακοσίων.", "st": "8.3.1"}, {"sp": "N", "t": "Βάλλεται μὲν οὖν τῷ ναῷ θεμελίους ὁ βασιλεὺς ἐπὶ μήκιστον τῆς γῆς βάθος ὕλης λίθων ἰσχυρᾶς καὶ πρὸς χρόνον ἀντέχειν δυναμένης, οἳ τῇ τε γῇ συμφυέντες ἔμελλον ἔδαφος καὶ ἔρεισμα τῆς ἐποικοδομησομένης κατασκευῆς ἔσεσθαι καὶ διὰ τὴν κάτωθεν ἰσχὺν οἴσειν ἀπόνως μέγεθός τε τῶν ἐπικεισομένων καὶ κάλλους πολυτέλειαν, ᾗ βάρος ἔμελλεν οὐχ ἧττον εἶναι τῶν ἄλλων ὅσα πρὸς ὕψος καὶ πρὸς ὄγκον κόσμου τε χάριν καὶ μεγαλουργίας ἐπενοεῖτο. ἀνήγαγε δὲ αὐτὸν ἄχρι τῆς ὀροφῆς ἐκ λευκοῦ λίθου πεποιημένον. τὸ μὲν οὖν ὕψος ἦν ἑξήκοντα πηχῶν, τῶν δ’ αὐτῶν καὶ τὸ μῆκος, εὖρος δ’ εἴκοσι. κατὰ τούτου δὲ ἄλλος ἦν ἐγηγερμένος ἴσος τοῖς μέτροις, ὥστε εἶναι τὸ πᾶν ὕψος τῷ ναῷ πηχῶν ἑκατὸν καὶ εἴκοσι· τέτραπτο δὲ πρὸς τὴν ἀνατολήν. τὸ δὲ προνάιον αὐτοῦ προύστησαν ἐπὶ πήχεις μὲν εἴκοσι τὸ μῆκος πρὸς τὸ εὖρος τοῦ οἴκου τεταμένον, ἔχον δὲ πλάτος πήχεις δέκα καὶ εἰς ὕψος δὲ ἀνεγηγερμένον πηχῶν ἑκατὸν καὶ εἴκοσι. περιῳκοδόμησε δὲ τὸν ναὸν ἐν κύκλῳ τριάκοντα βραχέσιν οἴκοις, οἳ συνοχή τε τοῦ παντὸς ἔμελλον ἔσεσθαι διὰ πυκνότητα καὶ πλῆθος ἔξωθεν περικείμενοι, καὶ δὴ καὶ τὰς εἰσόδους αὐτοῖς δι’ ἀλλήλων κατεσκεύασεν. ἕκαστος δὲ τῶν οἴκων τούτων εὖρος μὲν εἶχε πέντε πήχεις, μῆκος δὲ τοὺς αὐτούς, ὕψος δὲ εἴκοσιν. ἐπῳκοδόμηντο δὲ τούτοις ἄνωθεν ἕτεροι οἶκοι καὶ πάλιν ἄλλοι κατ’ αὐτῶν ἴσοι καὶ τοῖς μέτροις καὶ τῷ ἀριθμῷ, ὡς τὸ πᾶν ὕψος αὐτοὺς λαβεῖν τῷ κάτωθεν οἴκῳ παραπλήσιον· ὁ γὰρ ὑπερῷος οὐκ ἦν περιῳκοδομημένος. ὄροφος δὲ αὐτοῖς ἐπεβέβλητο κέδρου καὶ τοῖς μὲν οἴκοις ἴδιος ἦν οὗτος ἑκάστῳ πρὸς τοὺς πλησίον οὐ συνάπτων, τοῖς δ’ ἄλλοις ὑπῆρχεν ἡ στέγη κοινὴ δι’ ἀλλήλων δεδομημένη μηκίσταις δοκοῖς καὶ διηκούσαις ἁπάντων, ὡς τοὺς μέσους τοίχους ὑπὸ τῶν αὐτῶν συγκρατουμένους ξύλων ἐρρωμενεστέρους διὰ τοῦτο γίνεσθαι. τὴν δὲ ὑπὸ τὰς δοκοὺς στέγην τῆς αὐτῆς ὕλης ἐβάλετο πᾶσαν ἐξεσμένην εἰς φατνώματα καὶ προσκόλλησιν χρυσοῦ. τοὺς δὲ τοίχους κεδρίναις διαλαβὼν σανίσι χρυσὸν αὐταῖς ἐνετόρευσεν, ὥστε στίλβειν ἅπαντα τὸν ναὸν καὶ περιλάμπεσθαι τὰς ὄψεις τῶν εἰσιόντων ὑπὸ τῆς αὐγῆς τοῦ χρυσοῦ πανταχόθεν φερομένης. ἡ δ’ ὅλη τοῦ ναοῦ οἰκοδομία κατὰ πολλὴν τέχνην ἐκ λίθων ἀκροτόμων ἐγένετο συντεθέντων ἁρμονίως πάνυ καὶ λείως, ὡς μήτε σφύρας μήτε ἄλλου τινὸς ἐργαλείου τεκτονικοῦ τοῖς κατανοοῦσιν ἐργασίαν δηλοῦσθαι, ἀλλὰ δίχα τῆς τούτων χρήσεως πᾶσαν ἡρμόσθαι τὴν ὕλην προσφυῶς, ὡς ἑκούσιον τὴν ἁρμονίαν αὐτῆς δοκεῖν μᾶλλον ἢ τῆς τῶν ἐργαλείων ἀνάγκης. ἐφιλοτέχνησε δὲ ὁ βασιλεὺς ἄνοδον εἰς τὸν ὑπερῷον οἶκον διὰ τοῦ εὔρους τοῦ τοίχου· οὐ γὰρ εἶχε θύραν μεγάλην κατὰ τῆς ἀνατολῆς ὡς εἶχεν ὁ κάτωθεν οἶκος, ἀλλ’ ἐκ τῶν πλευρῶν ἦσαν εἴσοδοι διὰ μικρῶν πάνυ θυρῶν. διέλαβε δὲ τὸν ναὸν καὶ ἔνδοθεν καὶ ἔξωθεν ξύλοις κεδρίνοις ἁλύσεσι παχείαις συνδεδεμένοις, ὥστε ἀντ’ ὀχυρωμάτων καὶ ῥώμης τοῦτο εἶναι.", "st": "8.3.2"}, {"sp": "N", "t": "Διελὼν δὲ τὸν ναὸν εἰς δύο τὸν μὲν ἔνδοθεν οἶκον εἴκοσι πηχῶν ἐποίησεν ἄδυτον, τὸν δὲ τεσσαράκοντα πηχῶν ἅγιον ναὸν ἀπέδειξεν. ἐκτεμὼν δὲ τὸν μέσον τοῖχον θύρας ἐπέστησε κεδρίνας χρυσὸν πολὺν αὐταῖς ἐνεργασάμενος καὶ τορείαν ποικίλην. κατεπέτασε δὲ ταύτας ὕφεσιν εὐανθεστάτοις ἐξ ὑακίνθου καὶ πορφύρας καὶ κόκκου πεποιημένοις, οὐ μὴν ἀλλὰ καὶ βύσσου λαμπροτάτης καὶ μαλακωτάτης. ἀνέθηκε δὲ εἰς τὸ ἄδυτον εἴκοσι πηχῶν τὸ εὖρος τῶν δ’ αὐτῶν καὶ τὸ μῆκος δύο Χερουβεῖς ὁλοχρύσους πηχῶν ἑκατέραν τὸ ὕψος πέντε, δύο δ’ ἦσαν ἑκατέρᾳ πτέρυγες ἐπὶ πέντε πήχεις ἐκτεταμέναι. διὸ καὶ οὐ μακρὰν ἀλλήλων αὐτὰς ἀνέστησεν, ἵνα τῶν πτερύγων τῇ μὲν ἅπτωνται τοῦ κατὰ νότον κειμένου τοίχου τοῦ ἀδύτου, τῇ δὲ κατὰ βορέαν, αἱ δ’ ἄλλαι πτέρυγες αὑταῖς συνάπτουσαι τεθείσῃ μεταξὺ αὐτῶν τῇ κιβωτῷ σκέπη τυγχάνωσι. τὰς δὲ Χερουβεῖς οὐδεὶς ὁποῖαί τινές εἰσιν εἰπεῖν οὐδ’ εἰκάσαι δύναται. κατέστρωσε δὲ καὶ τοῦ ναοῦ τὸ ἔδαφος ἐλάσμασι χρυσοῦ, ἐπέθηκε δὲ καὶ τῷ πυλῶνι τοῦ ναοῦ θύρας πρὸς τὸ ὕψος τοῦ τοίχου συμμεμετρημένας εὖρος ἐχούσας πηχῶν εἴκοσι, καὶ ταύτας κατεκόλλησε χρυσῷ. συνελόντι δ’ εἰπεῖν οὐδὲν εἴασε τοῦ ναοῦ μέρος οὔτε ἔξωθεν οὔτε ἔνδοθεν, ὃ μὴ χρυσὸς ἦν. κατεπέτασε δὲ καὶ ταύτας τὰς θύρας ὁμοίως ταῖς ἐνδοτέρω καταπετάσμασιν. ἡ δὲ τοῦ προναΐου πύλη τούτων οὐδὲν εἶχε.", "st": "8.3.3"}, {"sp": "N", "t": "Μεταπέμπεται δ’ ἐκ Τύρου Σολόμων παρὰ Εἱρώμου τεχνίτην Χείρωμον ὄνομα μητρὸς μὲν ὄντα Νεφθαλίτιδος τὸ γένος, ἐκ γὰρ ταύτης ὑπῆρχε τῆς φυλῆς, πατρὸς δὲ Οὐρίου γένος Ἰσραηλίτου. οὗτος ἅπαντος μὲν ἐπιστημόνως εἶχεν ἔργου, μάλιστα δὲ τεχνίτης ἦν χρυσὸν ἐργάζεσθαι καὶ ἄργυρον καὶ χαλκόν, ὑφ’ οὗ δὴ καὶ πάντα κατὰ τὴν τοῦ βασιλέως βούλησιν τὰ περὶ τὸν ναὸν ἐμηχανήθη. κατεσκεύασε δὲ ὁ Χείρωμος οὗτος καὶ στύλους δύο χαλκοῦς ἔσωθεν τὸ πάχος τεσσάρων δακτύλων. ἦν δὲ τὸ μὲν ὕψος τοῖς κίοσιν ὀκτωκαίδεκα πήχεων, ἡ δὲ περίμετρος δέκα καὶ δύο πηχῶν· χωνευτὸν δ’ ἐφ’ ἑκατέρᾳ κεφαλῇ κρίνον ἐφειστήκει τὸ ὕψος ἐπὶ πέντε πήχεις ἐγηγερμένον, ᾧ περιέκειτο δίκτυον ἐλάτῃ χαλκέᾳ περιπεπλεγμένον καλύπτον τὰ κρίνα. τούτου δὲ ἀπήρτηντο κατὰ διστιχίαν καὶ ῥοιαὶ διακόσιαι. τούτων τῶν κιόνων τὸν μὲν ἕτερον κατὰ τὴν δεξιὰν ἔστησε τοῦ προπυλαίου παραστάδα καλέσας αὐτὸν Ἰαχείν, τὸν δ’ ἕτερον κατὰ τὸ ἀριστερὸν ὀνομάσας αὐτὸν Ἀβαίζ.", "st": "8.3.4"}, {"sp": "N", "t": "Ἐχώνευσε δὲ καὶ θάλασσαν χαλκῆν εἰς ἡμισφαίριον ἐσχηματισμένην· ἐκλήθη δὲ τὸ χαλκούργημα θάλασσα διὸ τὸ μέγεθος· ἦν γὰρ ὁ λουτὴρ τὴν διάμετρον πηχῶν δέκα καὶ ἐπὶ παλαιστιαῖον πάχος κεχωνευμένος. ὑπερήρειστο δὲ κατὰ τὸ μεσαίτατον τοῦ κύτους σπείρᾳ περιαγομένῃ εἰς ἕλικας δέκα· ἦν δὲ τὴν διάμετρον πήχεως, περιειστήκεσαν δὲ περὶ αὐτὴν μόσχοι δώδεκα πρὸς τὰ κλίματα τῶν τεσσάρων ἀνέμων ἀποβλέποντες καθ’ ἕκαστον αὐτῶν τρεῖς, εἰς τὰ ὀπίσθια νενευκότες, ὥστ’ αὐτοῖς ἐπικαθέζεσθαι τὸ ἡμισφαίριον κατὰ περιαγωγὴν ἔνδον ἀπονεῦον. ἐδέχετο δὲ ἡ θάλασσα βάτους τρισχιλίους.", "st": "8.3.5"}, {"sp": "N", "t": "Ἐποίησε δὲ καὶ λουτήρων δέκα βάσεις χαλκᾶς τετραγώνους. τούτων ἑκάστη μῆκος γεγόνει πηχῶν πέντε πλάτος τεσσάρων ὕψος ἕξ. συνεκέκλειτο δὲ τὸ ἔργον κατὰ μέρος τετορευμένον οὕτως· τέσσαρες ἦσαν κιονίσκοι κατὰ γωνίαν ἑστῶτες τετράγωνοι τὰ πλευρὰ τῆς βάσεως ἐξ ἑκατέρου μέρους ἐν αὑτοῖς ἔχοντες ἐξηρμοσμένα. ἦν δὲ ταῦτα τριχῇ διῃρημένα· ἑκάστην δὲ χώραν ὅρος ἐπεῖχεν εἰς ὑπόβασιν κατεσκευασμένος, ἐφ’ οἷς ἐτετόρευτο πῇ μὲν λέων πῇ δὲ ταῦρος καὶ ἀετός, ἐπὶ δὲ τῶν κιονίσκων ὁμοίως ἐξείργαστο τοῖς κατὰ τὰ πλευρὰ τετορευμένοις. τὸ δὲ πᾶν ἔργον ἐπὶ τεσσάρων αἰωρούμενον τροχῶν εἱστήκει. χωνευτοὶ δ’ ἦσαν οὗτοι πλήμνας καὶ ἄντυγας πήχεως καὶ ἡμίσους ἔχοντες τὴν διάμετρον. ἐθαύμασεν ἄν τις τὰς ἀψῖδας τῶν τροχῶν θεασάμενος, ὅπως συντετορευμέναι καὶ τοῖς πλευροῖς τῶν βάσεων προσηνωμέναι ἁρμονίως ταῖς ἄντυξιν ἐνέκειντο· ἦσαν δ’ ὅμως οὕτως ἔχουσαι. τὰς δὲ γωνίας ἄνωθεν συνέκλειον ὦμοι χειρῶν ἀνατεταμένων, οἷς ἐπεκάθητο σπεῖρα κατὰ κοῖλον ἐπικειμένη τὸν λουτῆρα ταῖς χερσὶν ἐπαναπαυόμενον ἀετοῦ καὶ λέοντος αὐτοῖς ἐφηρμοσμένων, ὡς σύμφυτα ταῦτ’ εἶναι δοκεῖν τοῖς ὁρῶσι. μεταξὺ δὲ τούτων φοίνικες ἦσαν τετορευμένοι. τοιαύτη μὲν ἡ κατασκευὴ τῶν δέκα βάσεων ὑπῆρχε. προσεξείργαστο δὲ καὶ χυτρογαύλους δέκα λουτῆρας στρογγύλους χαλκοῦς, ὧν ἕκαστος ἐχώρει τεσσαράκοντα χόας· τὸ γὰρ ὕψος εἶχε τεσσάρων πηχῶν καὶ τοσούτοις ἀλλήλων αὐτοῖς διειστήκει τὰ χείλη. τίθησι δὲ τοὺς λουτῆρας τούτους ἐπὶ τῶν δέκα βάσεων τῶν κληθεισῶν Μεχενώθ. πέντε δὲ λουτῆρας ἵστησιν ἐξ ἀριστεροῦ μέρους τοῦ ναοῦ, τέτραπτο δὲ τοῦτο κατὰ βορέαν ἄνεμον, καὶ τοσούτους ἐκ τοῦ δεξιοῦ πρὸς νότον ἀφορῶντας εἰς τὴν ἀνατολήν· κατὰ δ’ αὐτὸ καὶ τὴν θάλασσαν ἔθηκε. πληρώσας δὲ ὕδατος τὴν μὲν θάλασσαν ἀπέδειξεν εἰς τὸ νίπτειν τοὺς εἰς τὸν ναὸν εἰσιόντας ἱερεῖς ἐν αὐτῇ τὰς χεῖρας καὶ τοὺς πόδας μέλλοντας ἀναβαίνειν ἐπὶ τὸν βωμόν, τοὺς δὲ λουτῆρας εἰς τὸ καθαίρειν τὰ ἐντὸς τῶν ὁλοκαυτουμένων ζῴων καὶ τοὺς πόδας αὐτῶν.", "st": "8.3.6"}, {"sp": "N", "t": "Κατεσκεύασε δὲ καὶ θυσιαστήριον χάλκεον εἴκοσι πηχῶν τὸ μῆκος καὶ τοσούτων τὸ εὖρος τὸ δὲ ὕψος δέκα πρὸς τὰς ὁλοκαυτώσεις. ἐποίησε δὲ αὐτοῦ καὶ τὰ σκεύη πάντα χάλκεα ποδιστῆρας καὶ ἀναλημπτῆρας· οὐ μὴν ἀλλὰ πρὸς τούτοις Χείρωμος καὶ λέβητας καὶ ἅρπαγας καὶ πᾶν σκεῦος ἐδημιούργησεν ἐκ χαλκοῦ τὴν αὐγὴν ὁμοίου χρυσῷ καὶ τὸ κάλλος· τραπεζῶν τε πλῆθος ἀνέθηκεν ὁ βασιλεύς, καὶ μίαν μὲν μεγάλην χρυσέαν, ἐφ’ ἧς ἐτίθεσαν τοὺς ἄρτους τοῦ θεοῦ, καὶ ταύτῃ παραπλησίας μυρίας πρὸς αὐταῖς ἑτέρῳ τρόπῳ γεγενημένας, ἐφ’ ὧν ἐπέκειτο τὰ σκεύη φιάλαι τε καὶ σπονδεῖα χρύσεα μὲν δισμύρια ἀργύρεα δὲ τετρακισμύρια. καὶ λυχνίας δὲ μυρίας ἐποίησε κατὰ τὴν Μωυσέος προσταγήν, ἐξ ὧν μίαν ἀνέθηκεν εἰς τὸν ναόν, ἵνα καίηται καθ’ ἡμέραν ἀκολούθως τῷ νόμῳ, καὶ τράπεζαν μίαν ἐπικειμένην ἄρτους πρὸς τὸ βόρειον τοῦ ναοῦ μέρος ἀντικρὺ τῆς λυχνίας· ταύτην γὰρ κατὰ νότον ἔστησεν, ὁ δὲ χρύσεος βωμὸς μέσος αὐτῶν ἔκειτο. ταῦτα πάντα εἶχεν ὁ τῶν τεσσαράκοντα πηχῶν οἶκος πρὸ τοῦ καταπετάσματος τοῦ ἀδύτου· ἐν τούτῳ δὲ ἡ κιβωτὸς ἔμελλε κεῖσθαι.", "st": "8.3.7"}, {"sp": "N", "t": "Οἰνοχόας δ’ ὁ βασιλεὺς μυριάδας ὀκτὼ κατεσκεύασε καὶ φιαλῶν χρυσέων δέκα ἀργυρέας δὲ διπλασίονας. πινάκων δὲ χρυσέων εἰς τὸ προσφέρειν ἐν αὐτοῖς πεφυραμένην σεμίδαλιν τῷ βωμῷ μυριάδας ὀκτώ, τούτων δ’ ἀργυροῦς διπλασίονας. κρατῆρας δ’ οἷς ἐνεφύρων τὴν σεμίδαλιν μετ’ ἐλαίου χρυσέους μὲν ἑξακισμυρίους, ἀργυρέους δὲ δὶς τοσούτους. τὰ μέτρα δὲ τοῖς Μωυσήου λεγομένοις δὲ ειν καὶ ἐσσάρωνες παραπλήσια, χρυσᾶ μὲν δισμύρια ἀργύρεα δὲ διπλασίονα. θυμιατήρια δὲ χρυσᾶ ἐν οἷς ἐκομίζετο τὸ θυμίαμα εἰς τὸν ναὸν δισμύρια· ὁμοίως ἄλλα θυμιατήρια οἷς ἐκόμιζον ἀπὸ τοῦ μεγάλου βωμοῦ πῦρ ἐπὶ τὸν μικρὸν βωμὸν τὸν ἐν τῷ ναῷ πεντακισμύρια. στολὰς δὲ ἱερατικὰς τοῖς ἀρχιερεῦσι σὺν ποδήρεσιν ἐπωμίσι καὶ λογίῳ καὶ λίθοις χιλίας· ἡ δὲ στεφάνη, εἰς ἣν τὸν θεὸν Μωυσῆς ἔγραψε, μία ἦν καὶ διέμεινεν ἄχρι τῆσδε τῆς ἡμέρας· τὰς δὲ ἱερατικὰς στολὰς ἐκ βύσσου κατεσκεύασε καὶ ζώνας πορφυρᾶς εἰς ἕκαστον μυρίας. καὶ σαλπίγγων κατὰ Μωυσέος ἐντολὴν μυριάδας εἴκοσι, καὶ στολῶν τοῖς ὑμνῳδοῖς Ληουιτῶν ἐκ βύσσου μυριάδας εἴκοσι· καὶ τὰ ὄργανα τὰ μουσικὰ καὶ πρὸς τὴν ὑμνῳδίαν ἐξηυρημένα, ἃ καλεῖται νάβλας καὶ κινύρας, ἐξ ἠλέκτρου κατεσκεύασε τετρακισμύρια.", "st": "8.3.8"}, {"sp": "N", "t": "Ταῦτα πάντα ὁ Σολόμων εἰς τὴν τοῦ θεοῦ τιμὴν πολυτελῶς καὶ μεγαλοπρεπῶς κατεσκεύασε μηδενὸς φεισάμενος ἀλλὰ πάσῃ φιλοτιμίᾳ περὶ τὸν τοῦ ναοῦ κόσμον χρησάμενος, ἃ καὶ κατέθηκεν ἐν τοῖς θησαυροῖς τοῦ θεοῦ. περιέβαλε δὲ τοῦ ναοῦ κύκλῳ γείσιον μὲν κατὰ τὴν ἐπιχώριον γλῶτταν τριγχὸν δὲ παρ’ Ἕλλησι λεγόμενον εἰς τρεῖς πήχεις ἀναγαγὼν τὸ ὕψος, εἴρξοντα μὲν τοὺς πολλοὺς τῆς εἰς τὸ ἱερὸν εἰσόδου, μόνοις δὲ ἀνειμένην αὐτὴν τοῖς ἱερεῦσι σημανοῦντα. τούτου δ’ ἔξωθεν ἱερὸν ᾠκοδόμησεν· ἐν τετραγώνου σχήματι στοὰς ἐγείρας μεγάλας καὶ πλατείας καὶ πύλαις ὑψηλαῖς ἀνεῳγμένας, ὧν ἑκάστη πρὸς ἕκαστον τῶν ἀνέμων τέτραπτο χρυσέαις κλειομένη θύραις. εἰς τοῦτο τοῦ λαοῦ πάντες οἱ διαφέροντες ἁγνείᾳ καὶ παρατηρήσει τῶν νομίμων εἰσῄεσαν. θαυμαστὸν δὲ καὶ λόγου παντὸς ἀπέφηνε μεῖζον, ὡς δὲ εἰπεῖν καὶ τῆς ὄψεως, τὸ τούτων ἔξωθεν ἱερόν· μεγάλας γὰρ ἐγχώσας φάραγγας, ἃς διὰ βάθος ἄπειρον οὐδὲ ἀπόνως ἐννεύσαντας ἦν ἰδεῖν, καὶ ἀναβιβάσας εἰς τετρακοσίους πήχεις τὸ ὕψος ἰσοπέδους τῇ κορυφῇ τοῦ ὄρους ἐφ’ ἧς ὁ ναὸς ᾠκοδόμητο κατεσκεύασε· καὶ διὰ τοῦτο ὕπαιθρον ὂν τὸ ἔξωθεν ἱερὸν ἴσον ὑπῆρχε τῷ ναῷ. περιλαμβάνει δ’ αὐτὸ καὶ στοαῖς διπλαῖς μὲν τὴν κατασκευήν, λίθου δ’ αὐτοφυοῦς τὸ ὕψος κίοσιν ἐπερηρεισμέναις· ὀροφαὶ δ’ αὐταῖς ἦσαν ἐκ κέδρου φατνώμασιν ἀνεξεσμέναι. τὰς δὲ θύρας τῷ ἱερῷ τούτῳ πάσας ἐπέστησεν ἐξ ἀργύρου.", "st": "8.3.9"}, {"sp": "N", "t": "Τὰ μὲν οὖν ἔργα ταῦτα καὶ τὰ μεγέθη καὶ κάλλη τῶν τε οἰκοδομημάτων καὶ τῶν εἰς τὸν ναὸν ἀναθημάτων Σολόμων ὁ βασιλεὺς ἐν ἔτεσιν ἑπτὰ συντελέσας καὶ πλούτου καὶ προθυμίας ἐπίδειξιν ποιησάμενος, ὡς ἄν τις ἰδὼν ἐνόμισεν ὡς ἐν τῷ παντὶ κατασκευασθῆναι χρόνῳ ταῦτα ἐν οὕτως ὀλίγῳ πρὸς τὸ μέγεθος συγκρινόμενα τοῦ ναοῦ συμπερασθῆναι, γράψας τοῖς ἡγεμόσι καὶ τοῖς πρεσβυτέροις τῶν Ἑβραίων ἐκέλευσεν ἅπαντα τὸν λαὸν συναγαγεῖν εἰς Ἱεροσόλυμα ὀψόμενόν τε τὸν ναὸν καὶ μετακομιοῦντα τὴν τοῦ θεοῦ κιβωτὸν εἰς αὐτόν. καὶ περιαγγελθείσης τῆς εἰς τὰ Ἱεροσόλυμα πᾶσιν ἀφίξεως ἑβδόμῳ μηνὶ μόλις συνίασιν, ὑπὸ μὲν τῶν ἐπιχωρίων Ἀθύρει, ὑπὸ δὲ τῶν Μακεδόνων Ὑπερβερεταίῳ λεγομένῳ. συνέδραμε δ’ εἰς τὸν αὐτὸν χρόνον καὶ ὁ τῆς σκηνοπηγίας καιρὸς ἑορτῆς σφόδρα παρὰ τοῖς Ἑβραίοις ἁγιωτάτης καὶ μεγίστης. βαστάσαντες οὖν τὴν κιβωτὸν καὶ τὴν σκηνήν, ἣν Μωυσῆς ἐπήξατο, καὶ πάντα τὰ πρὸς τὴν διακονίαν τῶν θυσιῶν τοῦ θεοῦ σκεύη μετεκόμιζον εἰς τὸν ναόν. προῆγον δὲ μετὰ θυσιῶν αὐτός τε ὁ βασιλεὺς καὶ ὁ λαὸς ἅπας καὶ οἱ Λευῖται σπονδαῖς τε καὶ πολλῶν ἱερείων αἵματι τὴν ὁδὸν καταντλοῦντες καὶ θυμιῶντες ἀπειρόν τι θυμιαμάτων πλῆθος, ὡς ἅπαντα τὸν πέριξ ἀέρα πεπληρωμένον καὶ τοῖς πορρωτάτω τυγχάνουσιν ἡδὺν ἀπαντᾶν καὶ γνωρίζειν ἐπιδημίαν θεοῦ καὶ κατοικισμὸν κατ’ ἀνθρωπίνην δόξαν εἰς νεοδόμητον αὐτῷ καὶ καθιερωμένον χωρίον· καὶ γὰρ οὐδ’ ὑμνοῦντες οὐδὲ χορεύοντες ἕως οὗ πρὸς τὸν ναὸν ἦλθον ἔκαμον. τούτῳ μὲν οὖν τῷ τρόπῳ τὴν κιβωτὸν μετήνεγκαν. ὡς δ’ εἰς τὸ ἄδυτον αὐτὴν εἰσενεγκεῖν ἔδει, τὸ μὲν ἄλλο πλῆθος μετέστη, μόνοι δὲ κομίσαντες οἱ ἱερεῖς μεταξὺ τῶν δύο Χερουβὶμ κατέθεσαν· αἱ δὲ τοὺς ταρσοὺς συμπλέξασαι, καὶ γὰρ οὕτως ἦσαν ὑπὸ τοῦ τεχνίτου κατεσκευασμέναι, τὴν κιβωτὸν ὡς ὑπὸ σκηνῇ τινι καὶ θόλῳ κατεσκέπασαν. εἶχε δὲ ἡ κιβωτὸς οὐδὲν ἕτερον ἢ δύο λιθίνας πλάκας, αἳ τοὺς δέκα λόγους τοὺς ὑπὸ τοῦ θεοῦ Μωυσεῖ λαληθέντας ἐν Σιναίῳ ὄρει ἐγγεγραμμένους αὐταῖς ἔσωζον. τὴν δὲ λυχνίαν καὶ τὴν τράπεζαν καὶ τὸν βωμὸν τὸν χρύσεον ἔστησαν ἐν τῷ ναῷ πρὸ τοῦ ἀδύτου κατὰ τοὺς αὐτοὺς τόπους, οὓς καὶ τότε ἐν τῇ σκηνῇ κείμενοι κατεῖχον, καὶ τὰς καθημερινὰς θυσίας ἀνέφερον. τὸ δὲ θυσιαστήριον τὸ χάλκεον ἵστησι πρὸ τοῦ ναοῦ ἀντικρὺ τῆς θύρας, ὡς ἀνοιχθείσης αὐτὸ κατὰ πρόσωπον εἶναι καὶ βλέπεσθαι τὰς ἱερουργίας καὶ τὴν τῶν θυσιῶν πολυτέλειαν. τὰ δὲ λοιπὰ σκεύη πάντα συναλίσας ἔνδον εἰς τὸν ναὸν κατέθετο.", "st": "8.4.1"}, {"sp": "N", "t": "Ἐπεὶ δὲ πάντα διακοσμήσαντες οἱ ἱερεῖς τὰ περὶ τὴν κιβωτὸν ἐξῆλθον, ἄφνω πίλημα νεφέλης οὐ σκληρὸν οὐδ’ οἷον ὥρᾳ χειμῶνος ὑετοῦ γέμον ἵσταται κεχυμένον δὲ καὶ κεκραμένον εἰς τὸν ναὸν εἰσερρύη, καὶ ταῖς μὲν ὄψεσι τῶν ἱερέων ὡς μὴ καθορᾶν ἀλλήλους ἐπεσκότει, ταῖς δὲ διανοίαις ταῖς ἁπάντων φαντασίαν καὶ δόξαν παρεῖχεν ὡς τοῦ θεοῦ κατεληλυθότος εἰς τὸ ἱερὸν καὶ κατεσκηνωκότος ἡδέως ἐν αὐτῷ. καὶ οἱ μὲν ἐπὶ ταύτης εἶχον αὑτοὺς τῆς ἐννοίας ὁ δὲ βασιλεὺς Σολόμων ἐξεγερθείς, ἔτυχε γὰρ καθεζόμενος, ἐποιήσατο λόγους πρὸς τὸν θεόν, οὓς τῇ θείᾳ φύσει πρέποντας ὑπελάμβανε καὶ καλῶς εἶχεν αὐτῷ λέγειν· σοὶ γάρ, εἶπεν, οἶκον μὲν αἰώνιον, ὦ δέσποτα, καὶ ἄξιον αὑτῷ εἰργάσω γεγονότα τὸν οὐρανὸν οἴδαμεν καὶ ἀέρα καὶ γῆν καὶ θάλασσαν, δι’ ὧν ἁπάντων οὐδὲ τούτοις ἀρκούμενος κεχώρηκας, τοῦτον δέ σοι κατεσκεύακα τὸν ναὸν ἐπώνυμον, ὡς ἂν ἀπ’ αὐτοῦ σοι τὰς εὐχὰς θύοντες καὶ καλλιεροῦντες ἀναπέμπωμεν εἰς τὸν ἀέρα καὶ πεπεισμένοι διατελοίημεν, ὅτι πάρει καὶ μακρὰν οὐκ ἀφέστηκας [οὐδὲ σαυτῶ]· τῷ μὲν γὰρ πάντ’ ἐφορᾶν καὶ πάντ’ ἀκούειν οὐδὲ νῦν ὅπου σοι θέμις οἰκῶν ἀπολείπεις τοῦ πᾶσιν ἔγγιστα εἶναι, μᾶλλον δ’ ἑκάστῳ καὶ βουλευομένῳ καὶ διὰ νυκτὸς καὶ ἡμέρας συμπάρει. ταῦτα ἐπιθειάσας πρὸς τὸν θεὸν ἀπέστρεψεν εἰς τὸ πλῆθος τοὺς λόγους ἐμφανίζων τοῦ θεοῦ τὴν δύναμιν αὐτοῖς καὶ τὴν πρόνοιαν, ὅτι Δαυίδῃ τῷ πατρὶ περὶ τῶν μελλόντων ἅπαντα καθὼς ἀποβέβηκεν ἤδη τὰ πολλὰ καὶ γενήσεται τὰ λείποντα δηλώσειε, καὶ ὡς αὐτὸς ἐπιθείη τὸ ὄνομα μήπω γεγεννημένῳ καὶ τίς μέλλοι καλεῖσθαι προείποι καὶ ὅτι τὸν ναὸν οὗτος οἰκοδομήσει αὐτῷ βασιλεὺς μετὰ τὴν τοῦ πατρὸς τελευτὴν γενόμενος· ἃ βλέποντας κατὰ τὴν ἐκείνου προφητείαν ἐπιτελῆ τὸν θεὸν εὐλογεῖν ἠξίου καὶ περὶ μηδενὸς ἀπογινώσκειν ὧν ὑπέσχηται πρὸς εὐδαιμονίαν ὡς οὐκ ἐσομένου πιστεύοντας ἐκ τῶν ἤδη βλεπομένων.", "st": "8.4.2"}, {"sp": "N", "t": "Ταῦτα διαλεχθεὶς πρὸς τὸν ὄχλον ὁ βασιλεὺς ἀφορᾷ πάλιν εἰς τὸν ναὸν καὶ τὴν δεξιὰν εἰς τὸν ὄχλον ἀνασχών ἔργοις μέν, εἶπεν, οὐ δυνατὸν ἀνθρώποις ἀποδοῦναι θεῷ χάριν ὑπὲρ ὧν εὖ πεπόνθασιν· ἀπροσδεὲς γὰρ τὸ θεῖον ἁπάντων καὶ κρεῖττον τοιαύτης ἀμοιβῆς· ᾧ δὲ τῶν ἄλλων ζῴων ὑπὸ σοῦ, δέσποτα, κρείττονες γεγόναμεν, τούτῳ τὴν σὴν εὐλογεῖν μεγαλειότητα καὶ περὶ τῶν ὑπηργμένων εἰς τὸν ἡμέτερον οἶκον καὶ τὸν Ἑβραίων εὐχαριστεῖν ἀνάγκη. τίνι γὰρ ἄλλῳ μᾶλλον ἱλάσασθαι μηνίοντα καὶ δυσμεναίνοντα εὐμενῆ δεξιώτερόν ἐστιν ἡμῖν ἢ φωνῇ, ἣν ἐξ ἀέρος τε ἔχομεν καὶ δι’ αὐτοῦ πάλιν ἀνιοῦσαν οἴδαμεν; χάριν οὖν ἔχειν δι’ αὐτῆς ὁμολογῶ σοι περί τε τοῦ πατρὸς πρῶτον, ὃν ἐξ ἀφανοῦς εἰς τοσαύτην ἀνήγαγες δόξαν, ἔπειθ’ ὑπὲρ ἐμαυτοῦ πάντα μέχρι τῆς παρούσης ἡμέρας ἃ προεῖπας πεποιηκότι, δέομαί τε τοῦ λοιποῦ χορηγεῖν ὅσα θεῷ δύναμις ἀνθρώποις ὑπὸ σοῦ τετιμημένοις, καὶ τὸν οἶκον τὸν ἡμέτερον αὔξειν εἰς πᾶν, ὡς καθωμολόγησας Δαυίδῃ τῷ πατρί μου καὶ ζῶντι καὶ παρὰ τὴν τελευτήν, ὅτι παρ’ ἡμῖν ἡ βασιλεία μενεῖ καὶ τὸ ἐκείνου γένος αὐτὴν διαδοχαῖς ἀμείψει μυρίαις. ταῦτ’ οὖν ἡμῖν ἐπάρκεσον καὶ παισὶ τοῖς ἐμοῖς ἀρετὴν ᾗ σὺ χαίρεις παράσχου. πρὸς δὲ τούτοις ἱκετεύω καὶ μοῖράν τινα τοῦ σοῦ πνεύματος εἰς τὸν ναὸν ἀποικίσαι, ὡς ἂν καὶ ἐπὶ γῆς ἡμῖν εἶναι δοκῇς. σοὶ μὲν γὰρ μικρὸν οἰκητήριον καὶ τὸ πᾶν οὐρανοῦ καὶ τῶν κατὰ τοῦτον ὄντων κύτος, οὐχ ὅτι γε οὗτος ὁ τυχὼν ναός, ἀλλὰ φυλάσσειν τε ἀπόρθητον ἐκ πολεμίων ὡς ἴδιον εἰς ἅπαν καὶ προνοεῖν ὡς οἰκείου κτήματος παρακαλῶ. κἂν ἁμαρτών ποτε ὁ λαὸς ἔπειτα πληγῇ τινι κακῷ διὰ τὴν ἁμαρτίαν ἐκ σοῦ γῆς ἀκαρπίᾳ καὶ φθορᾷ λοιμικῇ ἤ τινι τούτων τῶν παθημάτων, οἷς σὺ τοὺς παραβάντας τι τῶν ὁσίων μετέρχῃ, καὶ καταφεύγῃ πᾶς ἀθροισθεὶς ἐπὶ τὸν ναὸν ἱκετεύων σε καὶ σωθῆναι δεόμενος, ἐπήκοος αὐτοῦ γενόμενος ὡς ἔνδον ὢν ἐλεήσῃς καὶ τῶν συμφορῶν ἀπαλλάξῃς. ταύτην δὲ οὐχ Ἑβραίοις μόνον δέομαι παρὰ σοῦ τὴν βοήθειαν εἶναι σφαλεῖσιν, ἀλλὰ κἂν ἀπὸ περάτων τῆς οἰκουμένης τινὲς ἀφίκωνται κἂν ὁποθενδηποτοῦν προστρεπόμενοι καὶ τυχεῖν τινος ἀγαθοῦ λιπαροῦντες, δὸς αὐτοῖς ἐπήκοος γενόμενος. οὕτως γὰρ ἂν μάθοιεν πάντες, ὅτι σὺ μὲν αὐτὸς ἐβουλήθης παρ’ ἡμῖν κατασκευασθῆναί σοι τὸν οἶκον, ἡμεῖς δ’ οὐκ ἀπάνθρωποι τὴν φύσιν ἐσμὲν οὐδ’ ἀλλοτρίως πρὸς τοὺς οὐχ ὁμοφύλους ἔχομεν, ἀλλὰ πᾶσι κοινὴν τὴν ἀπὸ σοῦ βοήθειαν καὶ τὴν τῶν ἀγαθῶν ὄνησιν ὑπάρχειν ἠθελήσαμεν.", "st": "8.4.3"}, {"sp": "N", "t": "Εἰπὼν ταῦτα καὶ ῥίψας αὑτὸν ἐπὶ τὴν γῆν καὶ ἐπὶ πολλὴν ὥραν προσκυνήσας ἀναστὰς θυσίας τῷ θεῷ προσήνεγκε καὶ γεμίσας τῶν ὁλοκλήρων ἱερείων ἐναργέστατα τὸν θεὸν ἡδέως ἔγνω τὴν θυσίαν προσδεχόμενον· πῦρ γὰρ ἐξ ἀέρος διαδραμὸν καὶ πάντων ὁρώντων ἐπὶ τὸν βωμὸν ᾆξαν ἅπασαν τὴν θυσίαν ἀνήρπασε καὶ κατεδαίσατο. ταύτης δὲ τῆς ἐπιφανείας γενομένης ὁ μὲν λαὸς δήλωσιν εἶναι τοῦτ’ εἰκάσας τῆς ἐν τῷ ναῷ τοῦ θεοῦ διατριβῆς ἐσομένης καὶ ἡσθεὶς προσεκύνει πεσὼν ἐπὶ τοὔδαφος, ὁ δὲ βασιλεὺς εὐλογεῖν τε ἤρξατο καὶ τὸ πλῆθος ταὐτὸ ποιεῖν παρώρμα δείγματα μὲν ἔχοντας ἤδη τῆς τοῦ θεοῦ πρὸς αὐτοὺς εὐμενείας, εὐχομένους δὲ τοιαῦτα ἀποβαίνειν ἀεὶ τὰ παρ’ ἐκείνου, καὶ τὴν διάνοιαν αὐτοῖς καθαρὰν ἀπὸ πάσης φυλάττεσθαι κακίας ἐν δικαιοσύνῃ καὶ θρησκείᾳ καὶ τῷ τὰς ἐντολὰς τηρεῖν ἃς διὰ Μωυσέος αὐτοῖς ἔδωκεν ὁ θεὸς διαμενούσας· ἔσεσθαι γὰρ οὕτως εὔδαιμον τὸ Ἑβραίων ἔθνος καὶ παντὸς ἀνθρώπων γένους μακαριώτερον. παρεκάλει τε μνημονεύειν, ὡς οἷς ἐκτήσαντο τὰ παρόντα ἀγαθὰ τούτοις αὐτὰ καὶ βέβαια ἕξειν καὶ μείζω καὶ πλείω καταστήσειν· οὐ γὰρ λαβεῖν αὐτὰ μόνον δι’ εὐσέβειαν καὶ δικαιοσύνην, ἀλλὰ καὶ καθέξειν διὰ ταῦτα προσῆκεν ὑπολαμβάνειν· εἶναι δὲ τοῖς ἀνθρώποις οὐχ οὕτως μέγα τὸ κτήσασθαί τι τῶν [οὐχ] ὑπαρχόντων, ὡς τὸ σῶσαι τὰ πορισθέντα καὶ μηδὲν ἁμαρτεῖν εἰς. βλάβην αὐτῶν.", "st": "8.4.4"}, {"sp": "N", "t": "Ὁ μὲν οὖν βασιλεὺς διαλεχθεὶς ταῦτα πρὸς τὸ πλῆθος διαλύει τὴν ἐκκλησίαν τελέσας θυσίας ὑπέρ τε αὑτοῦ καὶ πάντων Ἑβραίων, ὡς μόσχους μὲν καταθῦσαι μυρίους καὶ δισχιλίους, προβάτων δὲ μυριάδας δώδεκα. τὸν μὲν γὰρ ναὸν τότε πρῶτον ἔγευσεν ἱερουργημάτων καὶ κατευωχήθησαν ἐν αὐτῷ πάντες σὺν γυναιξὶν Ἑβραῖοι καὶ τέκνοις, ἔτι δὲ καὶ τὴν σκηνοπηγίαν καλουμένην ἑορτὴν πρὸ τοῦ ναοῦ λαμπρῶς καὶ μεγαλοπρεπῶς ἐπὶ δὶς ἑπτὰ ἡμέρας ἤγαγεν ὁ βασιλεὺς σὺν ἅπαντι τῷ λαῷ κατευωχούμενος.", "st": "8.4.5"}, {"sp": "N", "t": "Ἐπεὶ δ’ εἶχεν αὐτοῖς ἀποχρώντως ταῦτα καὶ μηδὲν ἐνέδει τῇ περὶ τὸν θεὸν εὐσεβείᾳ πρὸς αὑτοὺς ἕκαστος τοῦ βασιλέως ἀπολύσαντος ἀπῄεσαν εὐχαριστήσαντες τῷ βασιλεῖ τῆς τε περὶ αὐτοὺς προνοίας καὶ ὧν ἐπεδείξατο ἔργων, καὶ εὐξάμενοι τῷ θεῷ παρασχεῖν αὐτοῖς εἰς πολὺν χρόνον Σολόμωνα βασιλέα τὴν πορείαν ἐποιοῦντο μετὰ χαρᾶς καὶ παιδιᾶς ὕμνους εἰς τὸν θεὸν ᾄδοντες, ὡς ὑπὸ τῆς ἡδονῆς ἀπόνως τὴν ὁδὸν τὴν ἐπὶ τὰ οἰκεῖα πάντας ἀνύσαι. καὶ οἱ μὲν τὴν κιβωτὸν εἰς τὸν ναὸν εἰσαγαγόντες καὶ τὸ μέγεθος καὶ τὸ κάλλος ἱστορήσαντες αὐτοῦ καὶ θυσιῶν ἐπ’ αὐτῷ μεγάλων καὶ ἑορτῶν μεταλαβόντες εἰς τὰς αὑτῶν ἕκαστοι πόλεις ὑπέστρεψαν. ὄναρ δ’ ἐπιφανὲν τῷ βασιλεῖ κατὰ τοὺς ὕπνους ἐσήμαινεν αὐτῷ τῆς εὐχῆς ἐπήκοον τὸν θεὸν γεγονέναι, καὶ ὅτι φυλάξει τε τὸν ναὸν καὶ διὰ παντὸς ἐν αὐτῷ μενεῖ τῶν ἐκγόνων αὐτοῦ καὶ αὐτοῦ καὶ τῆς ἁπάσης πληθύος τὰ δίκαια ποιούσης, αὐτόν τε πρῶτον ἐμμένοντα ταῖς τοῦ πατρὸς ὑποθήκαις ἔλεγεν εἰς ὕψος καὶ μέγεθος εὐδαιμονίας ἀνοίσειν ἄπειρον καὶ βασιλεύσειν ἀεὶ τῆς χώρας τοὺς ἐκ τοῦ γένους αὐτοῦ καὶ τῆς Ἰούδα φυλῆς· προδόντα μέντοι τὰ ἐπιτηδεύματα καὶ λήθην αὐτῶν ποιησάμενον καὶ ξενικοὺς θεοὺς θρησκεύειν μεταβαλόμενον πρόρριζον ἐκκόψειν καὶ μήτε τοῦ γένους τι λείψανον αὐτῶν ἐάσειν μήτε τὸν τῶν Ἰσραηλιτῶν λαὸν ἀπαθῆ παρόψεσθαι, πολέμοις δ’ αὐτοὺς καὶ κακοῖς ἐξαφανίσειν μυρίοις κἀκ τῆς γῆς, ἣν τοῖς πατράσιν αὐτῶν ἔδωκεν, ἐκβαλὼν ἐπήλυδας ἀλλοτρίας καταστήσειν, τὸν δὲ ναὸν τὸν νῦν οἰκοδομηθέντα καταπρησθησόμενον τοῖς ἐχθροῖς παραδώσειν καὶ διαρπαγησόμενον, κατασκάψειν δὲ καὶ τὴν πόλιν χερσὶ τῶν πολεμίων καὶ ποιήσειν μύθων ἄξια τὰ παρ’ αὐτοῖς κακὰ καὶ πολλῆς δι’ ὑπερβολὴν μεγέθους ἀπιστίας, ὡς τοὺς προσοίκους ἀκούοντας τὴν συμφορὰν θαυμάζειν καὶ τὴν αἰτίαν πολυπραγμονεῖν δι’ ἣν οὕτως ἐμισήθησαν Ἑβραῖοι τῷ θεῷ πρότερον εἰς δόξαν καὶ πλοῦτον ὑπ’ αὐτοῦ παραχθέντες, καὶ παρὰ τῶν ὑπολειπομένων ἀκούειν ἐξομολογουμένων τὰς ἁμαρτίας αὐτῶν καὶ τὰς τῶν πατρίων νομίμων παραβάσεις. ταῦτα μὲν αὐτῷ τὸν θεὸν εἰπεῖν κατὰ τοὺς ὕπνους ἀναγέγραπται.", "st": "8.4.6"}, {"sp": "N", "t": "Μετὰ δὲ τὴν τοῦ ναοῦ κατασκευὴν ἐν ἔτεσιν ἑπτὰ καθὼς προειρήκαμεν γενομένην τὴν τῶν βασιλείων οἰκοδομὴν κατεβάλετο, ἣν ἔτεσι τρισὶ καὶ δέκα μόγις ἀπήρτισεν· οὐ γὰρ τὸν αὐτὸν ἐσπουδάζετο τρόπον ὅνπερ καὶ τὸ ἱερόν, ἀλλὰ τὸ μὲν καίπερ ὂν μέγα καὶ θαυμαστῆς ἐργασίας καὶ παραδόξου τετυχηκὸς ἔτι καὶ θεοῦ συνεργοῦντος, εἰς ὃν ἐγίνετο, τοῖς προειρημένοις ἔτεσιν ἔλαβε πέρας· τὰ δὲ βασίλεια πολὺ τῆς ἀξίας τοῦ ναοῦ καταδεέστερα τυγχάνοντα τῷ μήτε τὴν ὕλην ἐκ τοσούτου χρόνου καὶ τῆς αὐτῆς ἡτοιμάσθαι φιλοτιμίας καὶ βασιλεῦσιν οἰκητήριον ἀλλ’ οὐ θεῷ γίνεσθαι, βράδιον ἠνύσθη. καὶ αὐτὰ μὲν οὖν ἄξια λόγου καὶ κατὰ τὴν εὐδαιμονίαν τῆς Ἑβραίων χώρας καὶ τοῦ βασιλέως ᾠκοδομήθη, τὴν δὲ ὅλην αὐτῶν διάταξιν καὶ τὴν διάθεσιν εἰπεῖν ἀναγκαῖον, ἵν’ οὕτως ἐκ τούτου στοχάζεσθαι καὶ συνορᾶν ἔχωσι τὸ μέγεθος οἱ τῇ γραφῇ μέλλοντες ἐντυγχάνειν.", "st": "8.5.1"}, {"sp": "N", "t": "Οἶκος ἦν μέγας καὶ καλὸς πολλοῖς στύλοις ἐρηρεισμένος, ὃν εἰς τὰς κρίσεις καὶ τὴν τῶν πραγμάτων διάγνωσιν πλῆθος ὑποδέξασθαι καὶ χωρῆσαι σύνοδον ἀνθρώπων ἐπὶ δίκας συνεληλυθότων κατεσκεύασεν ἑκατὸν μὲν πηχῶν τὸ μῆκος εὖρος δὲ πεντήκοντα τὸ δ’ ὕψος τριάκοντα, κίοσι μὲν τετραγώνοις ἀνειλημμένον ἐκ κέδρου πᾶσιν, ἐστεγασμένον δὲ Κορινθίως, ἰσομέτροις δὲ φλιαῖς καὶ θυρώμασι τριγλύφοις ἀσφαλῆ τε ὁμοῦ καὶ κεκαλλωπισμένον. ἕτερος δὲ οἶκος ἦν ἐν μέσῳ κατὰ ὅλου τοῦ πλάτους τεταγμένος [τετράγωνος] εὖρος πηχῶν τριάκοντα, ἄντικρυς ἔχων ναὸν παχέσι στύλοις ἀνατεταμένον· ἦν δὲ ἐν αὐτῷ ἐξέδρα διαπρεπής, ἐν ᾗ καθεζόμενος ὁ βασιλεὺς ἔκρινεν, ᾗ παρέζευκτο κατεσκευασμένος ἄλλος οἶκος τῇ βασιλίσσῃ καὶ τὰ λοιπὰ τὰ πρὸς τὴν δίαιταν καὶ τὰς ἀναπαύσεις οἰκήματα μετὰ τὴν τῶν πραγμάτων ἀπόλυσιν, ἐστρωμένα πάντα σανίσι τετμημέναις ἐκ κέδρου. καὶ τὰ μὲν ᾠκοδομήσατο λίθοις δεκαπήχεσιν, ἑτέρῳ δὲ πριστῷ τοὺς τοίχους καὶ πολυτελεῖ κατημφίεσεν, ὃν εἰς κόσμον ἱερῶν καὶ βασιλείων οἴκων θεωρίων γῆ μεταλλεύεται τοῖς φέρουσιν αὐτὸν τόποις ἐπαινουμένη. καὶ τὸ μὲν ἀπ’ αὐτοῦ κάλλος ἐπὶ τριστιχίαν ἦν ἐνυφασμένον, τετάρτη δὲ μοῖρα γλυφέων παρεῖχε θαυμάζειν ἐπιστήμην, ὑφ’ ὧν πεποίητο δένδρα καὶ φυτὰ παντοῖα σύσκια τοῖς κλάδοις καὶ τοῖς ἐκκρεμαμένοις αὐτῶν πετάλοις, ὡς ὑπονοεῖν αὐτὰ καὶ σαλεύεσθαι δι’ ὑπερβολὴν λεπτότητος καλύπτοντα τὸν ὑπ’ αὐτοῖς λίθον. τὸ δὲ ἄλλο μέχρι τῆς στέγης χριστὸν ἦν καὶ καταπεποικιλμένον χρώμασι καὶ βαφαῖς. προσκατεσκεύασε δὲ τούτοις ἄλλα τε πρὸς τρυφὴν οἰκήματα καὶ δὴ καὶ στοὰς μηκίστας καὶ ἐν καλῷ τῶν βασιλείων κειμένας, ἐν αἷς λαμπρότατον οἶκον εἰς ἑστίασιν καὶ συμπόσια χρυσοῦ περίπλεων· καὶ τἆλλα δὲ ὅσα τοῦτον ἔχειν ἔδει πρὸς τὴν τῶν ἑστιωμένων ὑπηρεσίαν σκεύη πάντ’ ἐκ χρυσοῦ κατεσκεύαστο. δύσκολον δ’ ἐστὶν καταριθμήσασθαι τὸ μέγεθος καὶ τὴν ποικιλίαν τῶν βασιλείων, ὅσα μὲν ἦν αὐτοῖς τὰ μέγιστα οἰκήματα, πόσα δὲ τὰ τούτων ὑποδεέστερα καὶ πόσα ὑπόγεια καὶ ἀφανῆ, τά τε τῶν ἀνειμένων εἰς ἀέρα κάλλη καὶ τὰ ἄλση πρὸς θεωρίαν ἐπιτερπεστάτην καὶ θέρους ὑποφυγὴν καὶ σκέπην εἶναι τοῖς σώμασιν. ἐν κεφαλαίῳ δ’ εἰπεῖν τὴν ὅλην οἰκοδομίαν ἐκ λίθου λευκοῦ καὶ κέδρου καὶ χρυσοῦ καὶ ἀργύρου πᾶσαν ἐποιήσατο τοὺς ὀρόφους καὶ τοὺς τοίχους τοῖς ἐγκλειομένοις χρυσῷ λίθοις διανθίσας τὸν αὐτὸν τρόπον, ὡς καὶ τὸν τοῦ θεοῦ ναὸν τούτοις κατηγλάισεν. εἰργάσατο δὲ καὶ ἐξ ἐλέφαντος θρόνον παμμεγεθέστατον ἐν κατασκευῇ βήματος ἔχοντα μὲν ἓξ βαθμούς, ἑκάστῳ δὲ τούτων ἐξ ἑκατέρου μέρους δύο λέοντες ἐφειστήκεσαν τοσούτων ἄνωθεν ἄλλων παρεστώτων. τὸ δ’ ἐνήλατον τοῦ θρόνου χεῖρες ἦσαν δεχόμεναι τὸν βασιλέα, ἀνακέκλιτο δ’ εἰς μόσχου προτομὴν τὰ κατόπιν αὐτοῦ βλέποντος, χρυσῷ δὲ ἅπας ἦν δεδεμένος.", "st": "8.5.2"}, {"sp": "N", "t": "Ταῦτα Σολόμων εἰκοσαετίᾳ κατασκευάσας, ἐπεὶ πολὺν μὲν αὐτῷ χρυσὸν πλείω δ’ ἄργυρον ὁ τῶν Τυρίων βασιλεὺς Εἴρωμος εἰς τὴν οἰκοδομίαν συνήνεγκεν ἔτι δὲ καὶ ξύλα κέδρου καὶ πίτυος, ἀντεδωρήσατο καὶ αὐτὸς μεγάλαις δωρεαῖς τὸν Εἴρωμον σῖτόν τε κατ’ ἔτος πέμπων αὐτῷ καὶ οἶνον καὶ ἔλαιον, ὧν μάλιστα διὰ τὸ νῆσον οἰκεῖν, ὡς καὶ προειρήκαμεν ἤδη, χρῄζων διετέλει. πρὸς τούτοις δὲ καὶ πόλεις αὐτῷ τῆς Γαλιλαίας εἴκοσι μὲν τὸν ἀριθμὸν οὐ πόρρω δὲ τῆς Τύρου κειμένας ἐχαρίσατο, ἃς ἐπελθὼν καὶ κατανοήσας Εἴρωμος καὶ δυσαρεστήσας τῇ δωρεᾷ πέμψας πρὸς Σολόμωνα μὴ δεῖσθαι τῶν πόλεων ἔλεγε κἄκτοτε προσηγορεύθησαν Χαβαλὼν γῆ· μεθερμηνευόμενον δὲ τὸ χάβαλον κατὰ Φοινίκων γλῶτταν οὐκ ἀρέσκον σημαίνει. καὶ σοφίσματα δὲ καὶ λόγους αἰνιγματώδεις διεπέμψατο πρὸς Σολόμωνα ὁ τῶν Τυρίων βασιλεὺς παρακαλῶν, ὅπως αὐτῷ σαφηνίσῃ τούτους καὶ τῆς ἀπορίας τῶν ἐν αὐτοῖς ζητουμένων ἀπαλλάξῃ. τὸν δὲ δεινὸν ὄντα καὶ συνετὸν οὐδὲν τούτων παρῆλθεν, ἀλλὰ πάντα νικήσας τῷ λογισμῷ καὶ μαθὼν αὐτῶν τὴν διάνοιαν ἐφώτισε.", "st": "8.5.3"}, {"sp": "N", "t": "Μέμνηται τούτων τῶν δύο βασιλέων καὶ Μένανδρος ὁ μεταφράσας ἀπὸ τῆς Φοινίκων διαλέκτου τὰ Τυρίων ἀρχεῖα εἰς τὴν Ἑλληνικὴν φωνὴν λέγων οὕτως· τελευτήσαντος δὲ Ἀβιβάλου διεδέξατο τὴν βασιλείαν παρ’ αὐτοῦ υἱὸς Εἴρωμος, ὃς βιώσας ἔτη πεντηκοντατρία ἐβασίλευσε τριάκοντα καὶ τέσσαρα. οὗτος ἔχωσε τὸ Εὐρύχωρον τόν τε χρυσοῦν κίονα τὸν ἐν τοῖς τοῦ Διὸς ἀνέθηκεν· ἔτι [τε] ὕλην ξύλων ἀπελθὼν ἔκοψεν ἀπὸ τοῦ ὄρους τοῦ λεγομένου Λιβάνου εἰς τὰς τῶν ἱερῶν στέγας· καθελών τε τὰ ἀρχαῖα ἱερὰ καὶ ναὸν ᾠκοδόμησε τοῦ Ἡρακλέους καὶ τῆς Ἀστάρτης, πρῶτός τε τοῦ Ἡρακλέους ἔγερσιν ἐποιήσατο ἐν τῷ Περιτίῳ μηνί· τοῖς τε Ἰτυκαίοις ἐπεστρατεύσατο μὴ ἀποδιδοῦσι τοὺς φόρους καὶ ὑποτάξας πάλιν αὑτῷ ἀνέστρεψεν. ἐπὶ τούτου ἦν Ἀβδήμονος παῖς νεώτερος, ὃς ἀεὶ ἐνίκα τὰ προβλήματα, ἃ ἐπέτασσε Σολόμων ὁ Ἱεροσολύμων βασιλεύς. μνημονεύει δὲ καὶ Δῖος λέγων οὕτως· Ἀβιβάλου τελευτήσαντος ὁ υἱὸς αὐτοῦ Εἴρωμος ἐβασίλευσεν. οὗτος τὰ πρὸς ἀνατολὰς μέρη τῆς πόλεως προσέχωσε καὶ μεῖζον τὸ ἄστυ ἐποίησε καὶ τοῦ Ὀλυμπίου Διὸς τὸ ἱερὸν καθ’ ἑαυτὸ ὂν ἐγχώσας τὸν μεταξὺ τόπον συνῆψε τῇ πόλει καὶ χρυσοῖς ἀναθήμασιν ἐκόσμησεν· ἀναβὰς δὲ εἰς τὸν Λίβανον ὑλοτόμησε πρὸς τὴν τῶν ἱερῶν κατασκευήν. τὸν δὲ τυραννοῦντα Ἱεροσολύμων Σολόμωνα πέμψαι φησὶ πρὸς Εἴρωμον αἰνίγματα καὶ παρ’ αὐτοῦ λαβεῖν ἀξιοῦντα, τὸν δὲ μὴ δυνηθέντα διακρῖναι τῷ λύσαντι χρήματα ἀποτίνειν. ὁμολογήσαντα δὲ τὸν Εἴρωμον καὶ μὴ δυνηθέντα λῦσαι τὰ αἰνίγματα πολλὰ τῶν χρημάτων εἰς τὸ ἐπιζήμιον ἀναλῶσαι· εἶτα δὲ Ἀβδήμονά τινα Τύριον ἄνδρα τὰ προτεθέντα λῦσαι καὶ αὐτὸν ἄλλα προβαλεῖν, ἃ μὴ λύσαντα τὸν Σολόμωνα πολλὰ τῷ Εἰρώμῳ προσαποτῖσαι χρήματα. καὶ Δῖος μὲν οὕτως εἴρηκεν.", "st": "8.6.1"}, {"sp": "N", "t": "Ἐπεὶ δ’ ἑώρα τὰ τῶν Ἱεροσολύμων τείχη ὁ βασιλεὺς πύργων πρὸς ἀσφάλειαν δεόμενα καὶ τῆς ἄλλης ὀχυρότητος, πρὸς γὰρ τἀξίωμα τῆς πόλεως ἡγεῖτο δεῖν καὶ τοὺς περιβόλους εἶναι, ταῦτά τε προσεπεσκεύαζε καὶ πύργοις αὐτὰ μεγάλοις προσεξῇρεν. ᾠκοδόμησε δὲ καὶ πόλεις ταῖς βαρυτάταις ἐναρίθμους Ἄσωρόν τε καὶ Μαγέδω, τὴν τρίτην δὲ Γάζαρα, ἣν τῆς Παλαιστίνων χώρας ὑπάρχουσαν Φαραώνης ὁ τῶν Αἰγυπτίων βασιλεὺς στρατευσάμενος καὶ πολιορκήσας αἱρεῖ κατὰ κράτος· ἀποκτείνας δὲ πάντας τοὺς ἐνοικοῦντας αὐτὴν κατέσκαψεν, εἶτα δωρεὰν ἔδωκεν τῇ θυγατρὶ Σολόμωνι γεγαμημένῃ. διὸ καὶ ἀνήγειρεν αὐτὴν ὁ βασιλεὺς οὖσαν ὀχυρὰν φύσει καὶ πρὸς πολέμους καὶ τὰς τῶν καιρῶν μεταβολὰς χρησίμην εἶναι δυναμένην. οὐ πόρρω δ’ αὐτῆς ἄλλας ᾠκοδόμησε δύο πόλεις· Βητχώρα τῇ ἑτέρᾳ ὄνομα ἦν, ἡ δ’ ἑτέρα Βελὲθ ἐκαλεῖτο. προσκατεσκεύασε δὲ ταύταις καὶ ἄλλας εἰς ἀπόλαυσιν καὶ τρυφὴν ἐπιτηδείως ἐχούσας τῇ τε τῶν ἀέρων εὐκρασίᾳ καὶ τοῖς ὡραίοις εὐφυεῖς καὶ νάμασιν ὑδάτων ἐνδρόσους. ἐμβαλὼν δὲ καὶ εἰς τὴν ἔρημον τῆς ἐπάνω Συρίας καὶ κατασχὼν αὐτὴν ἔκτισεν ἐκεῖ πόλιν μεγίστην δύο μὲν ἡμερῶν [ὁδὸν] ἀπὸ τῆς ἄνω Συρίας διεστῶσαν, ἀπὸ δ’ Εὐφράτου μιᾶς, ἀπὸ δὲ τῆς μεγάλης Βαβυλῶνος ἓξ ἡμερῶν ἦν τὸ μῆκος. αἴτιον δὲ τοῦ τὴν πόλιν οὕτως ἀπὸ τῶν οἰκουμένων μερῶν τῆς Συρίας ἀπῳκίσθαι τὸ κατωτέρω μὲν μηδαμοῦ τῆς γῆς ὕδωρ εἶναι, πηγὰς δ’ ἐν ἐκείνῳ τῷ τόπῳ μόνον εὑρεθῆναι καὶ φρέατα. ταύτην οὖν τὴν πόλιν οἰκοδομήσας καὶ τείχεσιν ὀχυρωτάτοις περιβαλὼν Θαδάμοραν ὠνόμασε καὶ τοῦτ’ ἔτι νῦν καλεῖται παρὰ τοῖς Σύροις, οἱ δ’ Ἕλληνες αὐτὴν προσαγορεύουσι Πάλμυραν.", "st": "8.6.2"}, {"sp": "N", "t": "Σολόμων μὲν οὖν ὁ βασιλεὺς ταῦτα κατ’ ἐκεῖνον τὸν καιρὸν πράττων διετέλει. πρὸς δὲ τοὺς ἐπιζητήσαντας, ὅτι πάντες οἱ Αἰγυπτίων βασιλεῖς ἀπὸ Μιναίου τοῦ Μέμφιν οἰκοδομήσαντος, ὃς ἔτεσι πολλοῖς ἔμπροσθεν ἐγένετο τοῦ πάππου ἡμῶν Ἁβράμου, μέχρι Σολόμωνος πλειόνων ἐτῶν τριακοσίων καὶ χιλίων μεταξὺ διεληλυθότων Φαραῶθαι ἐκλήθησαν ἀπὸ τοῦ μετ’ αὐτοὺς ἐν τοῖς μεταξὺ χρόνοις ἄρξαντος βασιλέως Φαραώθου τὴν προσηγορίαν λαβόντες, ἀναγκαῖον ἡγησάμην εἰπεῖν, ἵνα τὴν ἄγνοιαν αὐτῶν ἀφέλω καὶ ποιήσω τοῦ ὀνόματος φανερὰν τὴν αἰτίαν, ὅτι Φαραὼ κατ’ Αἰγυπτίους βασιλέα σημαίνει. οἶμαι δ’ αὐτοὺς ἐκπαίδων ἄλλοις χρωμένους ὀνόμασιν ἐπειδὰν βασιλεῖς γένωνται τὸ σημαῖνον αὐτῶν τὴν ἐξουσίαν κατὰ τὴν πάτριον γλῶτταν μετονομάζεσθαι· καὶ γὰρ οἱ τῆς Ἀλεξανδρείας βασιλεῖς ἄλλοις ὀνόμασι καλούμενοι πρότερον ὅτε τὴν βασιλείαν ἔλαβον Πτολεμαῖοι προσηγορεύθησαν ἀπὸ τοῦ πρώτου βασιλέως. καὶ οἱ Ῥωμαίων δὲ αὐτοκράτορες ἐκ γενετῆς ἀπ’ ἄλλων χρηματίσαντες ὀνομάτων Καίσαρες καλοῦνται τῆς ἡγεμονίας καὶ τῆς τιμῆς τὴν προσηγορίαν αὐτοῖς θεμένης ἀλλ’ οὐχ οἷς ὑπὸ τῶν πατέρων ἐκλήθησαν τούτοις ἐπιμένοντες. νομίζω δὲ καὶ Ἡρόδοτον τὸν Ἁλικαρνασέα διὰ τοῦτο μετὰ Μιναίαν τὸν οἰκοδομήσαντα Μέμφιν τριάκοντα καὶ τριακοσίους βασιλεῖς Αἰγυπτίων γενέσθαι λέγοντα μὴ δηλῶσαι αὐτῶν τὰ ὀνόματα, ὅτι κοινῶς Φαραῶθ’ ἐκαλοῦντο· καὶ γὰρ μετὰ τὴν τούτων τελευτὴν γυναικὸς βασιλευσάσης λέγει τοὔνομα Νικαύλην καλῶν δηλῶν, ὡς τῶν μὲν ἀρρένων βασιλέων τὴν αὐτὴν προσηγορίαν ἔχειν δυναμένων, τῆς δὲ γυναικὸς οὐκέτι κοινωνεῖν ἐκείνης, καὶ διὰ τοῦτ’ εἶπεν αὐτῆς τὸ φύσει δεῆσαν ὄνομα. ἐγὼ δὲ καὶ ἐν τοῖς ἐπιχωρίοις ἡμῶν βιβλίοις εὗρον, ὅτι μετὰ Φαραώθην τὸν Σολόμωνος πενθερὸν οὐκέτ’ οὐδεὶς τοῦτο τὸ ὄνομα βασιλεὺς Αἰγυπτίων ἐκλήθη, καὶ ὅτι ὕστερον ἧκε πρὸς Σολόμωνα ἡ προειρημένη γυνὴ βασιλεύουσα τῆς Αἰγύπτου καὶ τῆς Αἰθιοπίας. περὶ μὲν οὖν ταύτης μετ’ οὐ πολὺ δηλώσομεν· νῦν δὲ τούτων ἐπεμνήσθην, ἵνα παραστήσω τὰ ἡμέτερα βιβλία καὶ τὰ παρ’ Αἰγυπτίοις περὶ πολλῶν ὁμολογοῦντα.", "st": "8.6.3"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς Σολόμων τοὺς ἔτι τῶν Χαναναίων οὐχ ὑπακούοντας, οἳ ἐν τῷ Λιβάνῳ διέτριβον ὄρει καὶ μέχρι πόλεως Ἀμάθης, ὑποχειρίους ποιησάμενος φόρον αὐτοῖς προσέταξε καὶ πρὸς τὸ θητεύειν αὐτῷ καὶ τὰς οἰκετικὰς χρείας ἐκτελεῖν καὶ πρὸς γεωργίαν κατ’ ἔτος ἐξ αὐτῶν ἐπελέγετο. τῶν γὰρ Ἑβραίων οὐδεὶς ἐδούλευεν οὐδ’ ἦν εὔλογον ἔθνη πολλὰ τοῦ θεοῦ δεδωκότος αὐτοῖς ὑποχείρια, δέον ἐκ τούτων ποιεῖσθαι τὸ θητικόν, αὐτοὺς κατάγειν εἰς τοῦτο τὸ σχῆμα, ἀλλὰ πάντες ἐν ὅπλοις ἐφ’ ἁρμάτων καὶ ἵππων στρατευόμενοι μᾶλλον ἢ δουλεύοντες διῆγον. τῶν δὲ Χαναναίων, οὓς εἰς τὴν οἰκετείαν ἀπήγαγεν. ἄρχοντας ἀπέδειξε πεντακοσίους καὶ πεντήκοντα τὸν ἀριθμόν, οἳ τὴν ὅλην αὐτῶν ἐπιτροπὴν εἰλήφεσαν παρὰ τοῦ βασιλέως, ὥστε διδάσκειν αὐτοὺς τὰ ἔργα καὶ τὰς πραγματείας, ἐφ’ ἃς ἂν αὐτῶν ἔχρῃζεν.", "st": "8.6.4"}, {"sp": "N", "t": "Ἐναυπηγήσατο δὲ ὁ βασιλεὺς ἐν τῷ Αἰγυπτιακῷ κόλπῳ σκάφη πολλὰ τῆς Ἐρυθρᾶς θαλάσσης ἔν τινι τόπῳ λεγομένῳ Γασίων Γάβελος οὐ πόρρω Ἰλάνεως πόλεως, ἣ νῦν Βερενίκη καλεῖται· αὕτη γὰρ ἡ χώρα τὸ πρὶν Ἰουδαίων ἦν. ἔτυχε δὲ καὶ τῆς ἁρμοζούσης εἰς τὰς ναῦς δωρεᾶς παρ’ Εἰρώμου τοῦ Τυρίων βασιλέως· ἄνδρας γὰρ αὐτῷ κυβερνήτας καὶ τῶν θαλασσίων ἐπιστήμονας ἔπεμψεν ἱκανούς, οἷς ἐκέλευσε πλεύσαντας μετὰ τῶν ἰδίων οἰκονόμων εἰς τὴν πάλαι μὲν Σώφειραν νῦν δὲ χρυσῆν γῆν καλουμένην, τῆς Ἰνδικῆς ἐστιν αὕτη, χρυσὸν αὐτῷ κομίσαι. καὶ συναθροίσαντες ὡς τετρακόσια τάλαντα πάλιν ἀνεχώρησαν πρὸς τὸν βασιλέα.", "st": "8.6.5"}, {"sp": "N", "t": "Τὴν δὲ τῆς Αἰγύπτου καὶ τῆς Αἰθιοπίας τότε βασιλεύουσαν γυναῖκα σοφίᾳ διαπεπονημένην καὶ τἆλλα θαυμαστὴν ἀκούουσαν τὴν Σολόμωνος ἀρετὴν καὶ φρόνησιν ἐπιθυμία τῆς ὄψεως αὐτοῦ ἐκ τῶν ὁσημέραι περὶ τῶν ἐκεῖ λεγομένων πρὸς αὐτὸν ἤγαγε· πεισθῆναι γὰρ ὑπὸ τῆς πείρας ἀλλ’ οὐχ ὑπὸ τῆς ἀκοῆς, ἣν εἰκός ἐστι καὶ ψευδεῖ δόξῃ συγκατατίθεσθαι καὶ μεταπεῖσαι πάλιν, ὅλη γὰρ ἐπὶ τοῖς ἀπαγγέλλουσι κεῖται, θέλουσα πρὸς αὐτὸν ἐλθεῖν διέγνω, μάλιστα καὶ τῆς σοφίας αὐτοῦ βουλομένη λαβεῖν πεῖραν αὐτὴ προτείνασα καὶ λῦσαι τὸ ἄπορον τῆς διανοίας δεηθεῖσα ἧκεν εἰς Ἱεροσόλυμα μετὰ πολλῆς δόξης καὶ πλούτου παρασκευῆς· ἐπηγάγετο γὰρ καμήλους χρυσίου μεστὰς καὶ ἀρωμάτων ποικίλων καὶ λίθων πολυτελῶν. ὡς δ’ ἀφικομένην αὐτὴν ἡδέως ὁ βασιλεὺς προσεδέξατο. τά τε ἄλλα περὶ αὐτὴν φιλότιμος ἦν καὶ τὰ προβαλλόμενα σοφίσματα ῥᾳδίως τῇ συνέσει καταλαμβανόμενος θᾶττον ἢ προσεδόκα τις ἐπελύετο. ἡ δ’ ἐξεπλήσσετο μὲν καὶ τὴν σοφίαν τοῦ Σολόμωνος οὕτως ὑπερβάλλουσαν αὐτὴν καὶ τῆς ἀκουομένης τῇ πείρᾳ κρείττω καταμαθοῦσα, μάλιστα δ’ ἐθαύμαζε τὰ βασίλεια τοῦ τε κάλλους καὶ τοῦ μεγέθους οὐχ ἧττον δὲ τῆς διατάξεως τῶν οἰκοδομημάτων· καὶ γὰρ ἐν ταύτῃ πολλὴν τοῦ βασιλέως καθεώρα φρόνησιν. ὑπερεξέπληττε δ’ αὐτὴν ὅ τε οἶκος ὁ δρυμὼν ἐπικαλούμενος Λιβάνου καὶ ἡ τῶν καθ’ ἡμέραν δείπνων πολυτέλεια καὶ τὰ τῆς παρασκευῆς αὐτοῦ καὶ διακονίας ἥ τε τῶν ὑπηρετούντων ἐσθὴς καὶ τὸ μετ’ ἐπιστήμης αὐτῶν περὶ τὴν διακονίαν εὐπρεπές, οὐχ ἥκιστα δὲ καὶ αἱ καθ’ ἡμέραν ἐπιτελούμεναι τῷ θεῷ θυσίαι καὶ τὸ τῶν ἱερέων καὶ Λευιτῶν περὶ αὐτὰς ἐπιμελές. ταῦθ’ ὁρῶσα καθ’ ἡμέραν ὑπερεθαύμαζε, καὶ κατασχεῖν οὐ δυνηθεῖσα τὴν ἔκπληξιν τῶν βλεπομένων φανερὰν ἐποίησεν αὑτὴν θαυμαστικῶς διακειμένην· πρὸς γὰρ τὸν βασιλέα προήχθη λόγους εἰπεῖν, ὑφ’ ὧν ἠλέγχθη σφόδρα τὴν διάνοιαν ἐπὶ τοῖς προειρημένοις ἡττημένη· πάντα μὲν γάρ, εἶπεν, ὦ βασιλεῦ, τὰ δι’ ἀκοῆς εἰς γνῶσιν ἐρχόμενα μετ’ ἀπιστίας παραγίνεται, τῶν δὲ σῶν ἀγαθῶν, ὧν αὐτός τε ἔχεις ἐν αὑτῷ, λέγω δὲ τὴν σοφίαν καὶ τὴν φρόνησιν, καὶ ὧν ἡ βασιλεία σοι δίδωσιν, οὐ ψευδὴς ἄρα ἡ φήμη πρὸς ἡμᾶς διῆλθεν, ἀλλ’ οὖσα ἀληθὴς πολὺ καταδεεστέραν τὴν εὐδαιμονίαν ἀπέφηνεν ἧς ὁρῶ νῦν παροῦσα τὰς μὲν γὰρ ἀκοὰς πείθειν ἐπεχείρει μόνον, τὸ δὲ ἀξίωμα τῶν πραγμάτων οὐχ οὕτως ἐποίει γνώριμον, ὡς ἡ ὄψις αὐτὸ καὶ τὸ παρ’ αὐτοῖς εἶναι συνίστησιν. ἐγὼ γοῦν οὐδὲ τοῖς ἀπαγγελλομένοις διὰ πλῆθος καὶ μέγεθος ὧν ἐπυνθανόμην πιστεύουσα πολλῷ πλείω τούτων ἱστόρηκα. καὶ μακάριόν τε τὸν Ἑβραίων λαὸν εἶναι κρίνω δούλους τε τοὺς σοὺς καὶ φίλους, οἳ καθ’ ἡμέραν τῆς σῆς ἀπολαύουσιν ὄψεως καὶ τῆς σῆς σοφίας ἀκροώμενοι διατελοῦσιν. εὐλογήσειεν ἄν τις τὸν θεὸν ἀγαπήσαντα τήνδε τὴν χώραν καὶ τοὺς ἐν αὐτῇ κατοικοῦντας οὕτως, ὥστε σὲ ποιῆσαι βασιλέα.", "st": "8.6.6"}, {"sp": "N", "t": "Παραστήσασα δὲ καὶ διὰ τῶν λόγων, πῶς αὐτὴν διέθηκεν ὁ βασιλεύς, ἔτι καὶ ταῖς δωρεαῖς τὴν διάνοιαν αὐτῆς ἐποίησε φανεράν· εἴκοσι μὲν γὰρ αὐτῷ τάλαντα ἔδωκε χρυσίου ἀρωμάτων τε πλῆθος ἀσυλλόγιστον καὶ λίθον πολυτελῆ· λέγουσι δ’ ὅτι καὶ τὴν τοῦ ὀποβαλσάμου ῥίζαν, ἣν ἔτι νῦν ἡμῶν ἡ χώρα φέρει, δούσης ταύτης τῆς γυναικὸς ἔχομεν. ἀντεδωρήσατο δ’ αὐτὴν καὶ Σολόμων πολλοῖς ἀγαθοῖς καὶ μάλισθ’ ὧν κατ’ ἐπιθυμίαν ἐξελέξατο· οὐδὲν γὰρ ἦν, ὅ τι δεηθείσῃ λαβεῖν οὐ παρέσχεν, ἀλλ’ ἑτοιμότερον ὧν αὐτὸς κατὰ τὴν οἰκείαν ἐχαρίζετο προαίρεσιν ἅπερ ἐκείνη τυχεῖν ἠξίου προϊέμενος τὴν μεγαλοφροσύνην ἐπεδείκνυτο. καὶ ἡ μὲν τῶν Αἰγυπτίων καὶ τῆς Αἰθιοπίας βασίλισσα ὧν προειρήκαμεν τυχοῦσα καὶ μεταδοῦσα πάλιν τῷ βασιλεῖ τῶν παρ’ αὐτῆς εἰς τὴν οἰκείαν ὑπέστρεψε.", "st": "8.7.1"}, {"sp": "N", "t": "Κατὰ δὲ τὸν αὐτὸν καιρὸν κομισθέντων ἀπὸ τῆς χρυσῆς καλουμένης γῆς λίθου πολυτελοῦς τῷ βασιλεῖ καὶ ξύλων πευκίνων, τοῖς ξύλοις εἰς ὑποστήριγμα τοῦ τε ναοῦ καὶ τῶν βασιλείων κατεχρήσατο καὶ πρὸς τὴν τῶν μουσικῶν ὀργάνων κατασκευὴν κινύρας τε καὶ νάβλας, ὅπως ὑμνῶσιν οἱ Ληουῖται τὸν θεόν· πάντων δὲ τῶν ποτε κομισθέντων αὐτῷ τὰ κατ’ ἐκείνην τὴν ἡμέραν ἐνεχθέντα καὶ μεγέθει καὶ κάλλει διέφερεν. ὑπολάβῃ δὲ μηδείς, ὅτι τὰ τῆς πεύκης ξύλα τοῖς νῦν εἶναι λεγομένοις καὶ ταύτην ὑπὸ τῶν πιπρασκόντων τὴν προσηγορίαν ἐπὶ καταπλήξει τῶν ὠνουμένων λαμβάνουσίν ἐστι παραπλήσια. ἐκεῖνα γὰρ τὴν μὲν ἰδέαν ἐμφερῆ τοῖς συκίνοις γίνεται, λευκότερα δέ ἐστι καὶ στίλβει πλέον. τοῦτο μὲν πρὸς τὸ μηδένα τὴν διαφορὰν ἀγνοῆσαι μηδὲ τὴν φύσιν τῆς ἀληθοῦς πεύκης, ἐπεὶ διὰ τὴν τοῦ βασιλέως χρείαν ἐμνήσθημεν αὐτῆς, εὔκαιρον εἶναι καὶ φιλάνθρωπον δηλῶσαι νομίσαντες εἰρήκαμεν.", "st": "8.7.2"}, {"sp": "N", "t": "Ὁ δὲ τοῦ χρυσοῦ σταθμὸς τοῦ κομισθέντος αὐτῷ τάλαντα ἑξακόσια καὶ ἑξήκοντα καὶ ἕξ, μὴ συγκαταριθμουμένου καὶ τοῦ ὑπὸ τῶν ἐμπόρων ὠνηθέντος μηδ’ ὧν οἱ τῆς Ἀραβίας τοπάρχαι καὶ βασιλεῖς ἔπεμπον αὐτῷ δωρεῶν. ἐχώνευσε δὲ τὸν χρυσὸν εἰς διακοσίων κατασκευὴν θυρεῶν ἀνὰ σίκλους ἀγόντων ἑξακοσίους. ἐποίησε δὲ καὶ ἀσπίδας τριακοσίας ἀγούσης ἑκάστης χρυσίου μνᾶς τρεῖς· ἀνέθηκε δὲ ταύτας φέρων εἰς τὸν οἶκον τὸν δρυμῶνα Λιβάνου καλούμενον. οὐ μὴν ἀλλὰ καὶ τὰ ἐκπώματα διὰ χρυσοῦ καὶ λίθου τὰ πρὸς τὴν ἑστίασιν ὡς ἔνι μάλιστα φιλοτεχνῶν κατεσκεύασε καὶ τὴν ἄλλην τῶν σκευῶν δαψίλειαν χρυσέαν ἅπασαν ἐμηχανήσατο· οὐδὲν γὰρ ἦν ὅ τις ἀργύρῳ ἐπίπρασκεν ἢ πάλιν ἐωνεῖτο, ἀλλὰ πολλαὶ γὰρ ἦσαν ναῦς, ἃς ὁ βασιλεὺς ἐν τῇ Ταρσικῇ λεγομένῃ θαλάττῃ καταστήσας παραγαγεῖν εἰς τὰ ἐνδοτέρω τῶν ἐθνῶν παντοίαν ἐμπορίαν προσέταξεν, ὧν ἐξεμπολουμένων ἄργυρός τε καὶ χρυσὸς ἐκομίζετο τῷ βασιλεῖ καὶ πολὺς ἐλέφας Αἰθίοπές τε καὶ πίθηκοι. τὸν δὲ πλοῦν ἀπιοῦσαί τε καὶ ἐπανερχόμεναι τρισὶν ἔτεσιν ἤνυον.", "st": "8.7.3"}, {"sp": "N", "t": "Φήμη δὲ λαμπρὰ πᾶσαν ἐν κύκλῳ τὴν χώραν περιήρχετο διαβοῶσα τὴν Σολόμωνος ἀρετὴν καὶ σοφίαν, ὡς τούς τε πανταχοῦ βασιλεῖς ἐπιθυμεῖν εἰς ὄψιν αὐτῷ παραγενέσθαι τοῖς λεγομένοις δι’ ὑπερβολὴν ἀπιστοῦντας, καὶ δωρεαῖς μεγάλαις προσεμφανίζειν τὴν περὶ αὐτὸν σπουδήν· ἔπεμπον γὰρ αὐτῷ σκεύη χρυσᾶ καὶ ἀργυρᾶ καὶ ἁλουργεῖς ἐσθῆτας καὶ ἀρωμάτων γένη πολλὰ καὶ ἵππους καὶ ἅρματα καὶ τῶν ἀχθοφόρων ἡμιόνων ὅσους καὶ ῥώμῃ καὶ κάλλει τὴν τοῦ βασιλέως ὄψιν εὖ διαθήσειν ἐπελέγοντο, ὥστε τοῖς οὖσιν αὐτῷ πρότερον ἅρμασι καὶ ἵπποις ἐκ τῶν πεμπομένων προσθέντα ποιῆσαι τὸν μὲν τῶν ἁρμάτων ἀριθμὸν τετρακοσίοις περισσότερον, ἦν γὰρ αὐτῷ πρότερον χίλια, τὸν δὲ τῶν ἵππων δισχιλίοις, ὑπῆρχον γὰρ αὐτῷ δισμύριοι ἵπποι. ἤσκηντο δ’ οὗτοι πρὸς εὐμορφίαν καὶ τάχος, ὡς μήτ’ εὐπρεπεστέρους ἄλλους εἶναι συμβαλεῖν αὐτοῖς μήτε ὠκυτέρους, ἀλλὰ καλλίστους τε πάντων ὁρᾶσθαι καὶ ἀπαραμίλλητον αὐτῶν εἶναι τὴν ὀξύτητα. ἐπεκόσμουν δὲ αὐτοὺς καὶ οἱ ἀναβαίνοντες νεότητι μὲν πρῶτον ἀνθοῦντες ἐπιτερπεστάτῃ τὸ δὲ ὕψος ὄντες περίοπτοι καὶ πολὺ τῶν ἄλλων ὑπερέχοντες, μηκίστας μὲν καθειμένοι χαίτας ἐνδεδυμένοι δὲ χιτῶνας τῆς Τυρίας πορφύρας. ψῆγμα δὲ χρυσοῦ καθ’ ἡμέραν αὐτῶν ἐπέσηθον ταῖς κόμαις, ὡς στίλβειν αὐτῶν τὰς κεφαλὰς τῆς αὐγῆς τοῦ χρυσοῦ πρὸς τὸν ἥλιον ἀντανακλωμένης. τούτων περὶ αὐτὸν ὄντων ὁ βασιλεὺς καθωπλισμένων καὶ τόξα ἐξηρτημένων ἐφ’ ἅρματος αὐτὸς ὀχούμενος καὶ λευκὴν ἠμφιεσμένος ἐσθῆτα πρὸς αἰώραν ἔθος εἶχεν ἐξορμᾶν. ἦν δέ τι χωρίον ἀπὸ δύο σχοίνων Ἱεροσολύμων, ὃ καλεῖται μὲν Ἠτάν, παραδείσοις δὲ καὶ ναμάτων ἐπιρροαῖς ἐπιτερπὲς ὁμοῦ καὶ πλούσιον· εἰς τοῦτο τὰς ἐξόδους αἰωρούμενος ἐποιεῖτο.", "st": "8.7.4"}, {"sp": "N", "t": "Θείᾳ τε περὶ πάντα χρώμενος ἐπινοίᾳ τε καὶ σπουδῇ καὶ λίαν ὢν φιλόκαλος οὐδὲ τῶν ὁδῶν ἠμέλησεν, ἀλλὰ καὶ τούτων τὰς ἀγούσας εἰς Ἱεροσόλυμα βασίλειον οὖσαν λίθῳ κατέστρωσε μέλανι, πρός τε τὸ ῥᾳστώνην εἶναι τοῖς βαδίζουσι, καὶ πρὸς τὸ δηλοῦν τὸ ἀξίωμα τοῦ πλούτου καὶ τῆς ἡγεμονίας. διαμερίσας δὲ τὰ ἅρματα καὶ διατάξας, ὥστε ἐν ἑκάστῃ πόλει τούτων ἀριθμὸν ὡρισμένον ὑπάρχειν, αὐτὸς μὲν περὶ αὑτὸν ἐτήρησεν ὀλίγα, τὰς δὲ πόλεις ταύτας ἁρμάτων προσηγόρευσε. τοῦ δ’ ἀργυρίου τοσοῦτον ἐποιήσατο πλῆθος ἐν Ἱεροσολύμοις ὁ βασιλεύς, ὅσον ἦν καὶ τῶν λίθων, καὶ τῶν κεδρίνων ξύλων οὐ πρότερον ὄντων, ὥσπερ καὶ τῶν δένδρων τῶν συκαμινίνων, ὧν πληθύει τὰ τῆς Ἰουδαίας πεδία. προσέταξε δὲ καὶ τοῖς ἐμπόροις Αἰγύπτου κομίζουσιν αὐτῷ πιπράσκειν τὸ μὲν ἅρμα σὺν ἵπποις δυσὶν ἑξακοσίων δραχμῶν ἀργυρίου, αὐτὸς δὲ τοῖς τῆς Συρίας βασιλεῦσι καὶ τοῖς πέραν Εὐφράτου διέπεμπεν αὐτούς.", "st": "8.7.5"}, {"sp": "N", "t": "Γενόμενος δὲ πάντων βασιλέων ἐνδοξότατος καὶ θεοφιλέστατος καὶ φρονήσει καὶ πλούτῳ διενεγκὼν τῶν πρὸ αὐτοῦ τὴν Ἑβραίων ἀρχὴν ἐσχηκότων οὐκ ἐπέμεινε τούτοις ἄχρι τελευτῆς, ἀλλὰ καταλιπὼν τὴν τῶν πατρίων ἐθισμῶν φυλακὴν οὐκ εἰς ὅμοιον οἷς προειρήκαμεν αὐτοῦ τέλος κατέστρεψεν, εἰς δὲ γυναῖκας ἐκμανεὶς καὶ τὴν τῶν ἀφροδισίων ἀκρασίαν οὐ ταῖς ἐπιχωρίαις μόνον ἠρέσκετο, πολλὰς δὲ καὶ ἐκ τῶν ἀλλοτρίων ἐθνῶν γήμας Σιδωνίας καὶ Τυρίας καὶ Ἀμμανίτιδας καὶ Ἰδουμαίας παρέβη μὲν τοὺς Μωσήους νόμους, ὃς ἀπηγόρευσε συνοικεῖν ταῖς οὐχ ὁμοφύλοις, τοὺς δ’ ἐκείνων ἤρξατο θρησκεύειν θεοὺς ταῖς γυναιξὶ καὶ τῷ πρὸς αὐτὰς ἔρωτι χαριζόμενος, τοῦτ’ αὐτὸ ὑπιδομένου τοῦ νομοθέτου προειπόντος μὴ γαμεῖν τὰς ἀλλοτριοχώρους, ἵνα μὴ τοῖς ξένοις ἐπιπλακέντες ἔθεσι τῶν πατρίων ἀποστῶσι, μηδὲ τοὺς ἐκείνων σέβωνται θεοὺς παρέντες τιμᾶν τὸν ἴδιον. ἀλλὰ τούτων μὲν κατημέλησεν ὑπενεχθεὶς εἰς ἡδονὴν ἀλόγιστον Σολόμων, ἀγαγόμενος δὲ γυναῖκας ἀρχόντων καὶ διασήμων θυγατέρας ἑπτακοσίας τὸν ἀριθμὸν καὶ παλλακὰς τριακοσίας, πρὸς δὲ ταύταις καὶ τὴν τοῦ βασιλέως τῶν Αἰγυπτίων θυγατέρα, εὐθὺς μὲν ἐκρατεῖτο πρὸς αὐτῶν, ὥστε μιμεῖσθαι τὰ παρ’ ἐκείναις, καὶ τῆς εὐνοίας καὶ φιλοστοργίας ἠναγκάζετο παρέχειν αὐταῖς δεῖγμα τὸ βιοῦν ὡς αὐταῖς πάτριον ἦν· προβαινούσης δὲ τῆς ἡλικίας καὶ τοῦ λογισμοῦ διὰ τὸν χρόνον ἀσθενοῦντος ἀντέχειν πρὸς τὴν μνήμην τῶν ἐπιχωρίων ἐπιτηδευμάτων ἔτι μᾶλλον τοῦ μὲν ἰδίου θεοῦ κατωλιγώρησε, τοὺς δὲ τῶν γάμων τῶν ἐπεισάκτων τιμῶν διετέλει. καὶ πρὸ τούτων δὲ ἁμαρτεῖν αὐτὸν ἔτυχε καὶ σφαλῆναι περὶ τὴν φυλακὴν τῶν νομίμων, ὅτε τὰ τῶν χαλκῶν βοῶν ὁμοιώματα κατεσκεύασε τῶν ὑπὸ τῇ θαλάττῃ τῷ ἀναθήματι καὶ τῶν λεόντων τῶν περὶ τὸν θρόνον τὸν ἴδιον· οὐδὲ γὰρ ταῦτα ποιεῖν ὅσιον εἰργάσατο. κάλλιστον δ’ ἔχων καὶ οἰκεῖον παράδειγμα τῆς ἀρετῆς τὸν πατέρα καὶ τὴν ἐκείνου δόξαν, ἣν αὐτῷ συνέβη καταλιπεῖν διὰ τὴν πρὸς τὸν θεὸν εὐσέβειαν, οὐ μιμησάμενος αὐτὸν καὶ ταῦτα δὶς αὐτῷ τοῦ θεοῦ κατὰ τοὺς ὕπνους φανέντος καὶ τὸν πατέρα μιμεῖσθαι παραινέσαντος ἀκλεῶς ἀπέθανεν. ἧκεν οὖν εὐθὺς ὁ προφήτης ὑπὸ θεοῦ πεμφθεὶς οὔτε λανθάνειν αὐτὸν ἐπὶ τοῖς παρανομήμασι λέγων οὔτ’ ἐπὶ πολὺ χαιρήσειν τοῖς πραττομένοις ἀπειλῶν, ἀλλὰ ζῶντος μὲν οὐκ ἀφαιρεθήσεσθαι τὴν βασιλείαν ἐπεὶ τῷ πατρὶ Δαυίδῃ τὸ θεῖον ὑπέσχετο διάδοχον αὐτὸν ποιήσειν ἐκείνου, τελευτήσαντος δὲ τὸν υἱὸν αὐτοῦ ταῦτα διαθήσειν οὐχ ἅπαντα μὲν τὸν λαὸν ἀποστήσας αὐτοῦ, δέκα δὲ φυλὰς παραδοὺς αὐτοῦ τῷ δούλῳ, δύο δὲ μόνας καταλιπὼν τῷ υἱωνῷ τῷ Δαυίδου δι’ αὐτὸν ἐκεῖνον, ὅτι τὸν θεὸν ἠγάπησε, καὶ διὰ τὴν πόλιν Ἱεροσόλυμα, ἐν ᾗ ναὸν ἔχειν ἠβουλήθη.", "st": "8.7.6"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας Σολόμων ἤλγησε καὶ σφοδρῶς συνεχύθη πάντων αὐτῷ σχεδὸν τῶν ἀγαθῶν ἐφ’ οἷς ζηλωτὸς ἦν εἰς μεταβολὴν ἐρχομένων πονηράν. οὐ πολὺς δὲ διῆλθε χρόνος ἀφ’ οὗ κατήγγειλεν ὁ προφήτης αὐτῷ τὰ συμβησόμενα καὶ πολέμιον εὐθὺς ἐπ’ αὐτὸν ἤγειρεν ὁ θεὸς Ἄδερον μὲν ὄνομα τὴν δ’ αἰτίαν τῆς ἔχθρας λαβόντα τοιαύτην· παῖς οὗτος ἦν Ἰδουμαῖος γένος ἐκ βασιλικῶν σπερμάτων. καταστρεψαμένου δὲ τὴν Ἰδουμαίαν Ἰωάβου τοῦ Δαυίδου στρατηγοῦ καὶ πάντας τοὺς ἐν ἀκμῇ καὶ φέρειν ὅπλα δυναμένους διαφθείραντος μησὶν ἕξ, φυγὼν ἧκε πρὸς Φαραῶνα τὸν Αἰγυπτίων βασιλέα. ὁ δὲ φιλοφρόνως αὐτὸν δεξάμενος οἶκόν τε αὐτῷ δίδωσι καὶ χώραν εἰς διατροφὴν καὶ γενόμενον ἐν ἡλικίᾳ λίαν ἠγάπα, ὡς καὶ τῆς αὑτοῦ γυναικὸς αὐτῷ δοῦναι πρὸς γάμον τὴν ἀδελφὴν ὄνομα Θαφίνην, ἐξ ἧς αὐτῷ υἱὸς γενόμενος τοῖς τοῦ βασιλέως παισὶ συνετράφη. ἀκούσας οὖν τὸν Δαυίδου θάνατον ἐν Αἰγύπτῳ καὶ τὸν Ἰωάβου προσελθὼν ἐδεῖτο τοῦ Φαραῶνος ἐπιτρέπειν αὐτῷ βαδίζειν εἰς τὴν πατρίδα. τοῦ δὲ βασιλέως ἀνακρίναντος, τίνος ἐνδεὴς ὢν ἢ τί παθὼν ἐσπούδακε καταλιπεῖν αὐτόν, ἐνοχλῶν πολλάκις καὶ παρακαλῶν τότε μὲν οὐκ ἀφείθη· κατ’ ἐκεῖνον δὲ τὸν καιρόν, καθ’ ὃν ἤδη Σολόμωνι τὰ πράγματα κακῶς ἔχειν ἤρχετο διὰ τὰς προειρημένας παρανομίας καὶ τὴν ὀργὴν τὴν ἐπ’ αὐτοῖς τοῦ θεοῦ, συγχωρήσαντος τοῦ Φαραῶνος ὁ Ἄδερος ἧκεν εἰς τὴν Ἰδουμαίαν· καὶ μὴ δυνηθεὶς αὐτὴν ἀποστῆσαι τοῦ Σολόμωνος, κατείχετο γὰρ φρουραῖς πολλαῖς καὶ οὐκ ἦν ἐλεύθερος δι’ αὐτὰς οὐδ’ ἐπ’ ἀδείας ὁ νεωτερισμός, ἄρας ἐκεῖθεν εἰς τὴν Συρίαν ἀφίκετο. συμβαλὼν δὲ ἐκεῖ τινι Ῥάζῳ μὲν τοὔνομα τὸν δὲ τῆς Σωφηνῆς ἀποδεδρακότι βασιλέα Ἀδραάζαρον δεσπότην ὄντα καὶ λῃστεύοντι τὴν χώραν εἰς φιλίαν αὐτῷ συνάψας ἔχοντι περὶ αὑτὸν στῖφος λῃστρικὸν ἀναβαίνει, καὶ κατασχὼν τὴν ἐκεῖ Συρίαν βασιλεὺς αὐτῆς ἀποδείκνυται καὶ κατατρέχων τὴν τῶν Ἰσραηλιτῶν γῆν ἐποίει κακῶς καὶ διήρπαζε Σολόμωνος ζῶντος ἔτι. καὶ ταῦτα μὲν ἐκ τοῦ Ἀδέρου συνέβαινε πάσχειν τοῖς Ἑβραίοις.", "st": "8.7.7"}, {"sp": "N", "t": "Ἐπιτίθεται δὲ Σολόμωνι καὶ τῶν ὁμοφύλων τις Ἱεροβόαμος υἱὸς Ναβαταίου κατὰ προφητείαν πάλαι γενομένην αὐτῷ τοῖς πράγμασιν ἐπελπίσας· παῖδα γὰρ αὐτὸν ὑπὸ τοῦ πατρὸς καταλειφθέντα καὶ ὑπὸ τῇ μητρὶ παιδευόμενον ὡς εἶδε γενναῖον καὶ τολμηρὸν Σολόμων ὄντα τὸ φρόνημα τῆς τῶν τειχῶν οἰκοδομίας ἐπιμελητὴν κατέστησεν, ὅτε τοῖς Ἱεροσολύμοις τὸν κύκλον περιέβαλεν. οὕτως δὲ τῶν ἔργων προενόησεν, ὥστε ὁ βασιλεὺς αὐτὸν ἀπεδέξατο καὶ γέρας αὐτῷ στρατηγίαν ἐπὶ τῆς Ἰωσήπου φυλῆς ἔδωκεν. ἀπερχομένῳ δὲ τῷ Ἱεροβοάμῳ κατ’ ἐκεῖνον τὸν καιρὸν ἐκ τῶν Ἱεροσολύμων συνεβόλησε προφήτης ἐκ πόλεως μὲν Σιλὼ Ἀχίας δὲ ὄνομα. καὶ προσαγορεύσας αὐτὸν ἀπήγαγεν ἐκ τῆς ὁδοῦ μικρὸν ἀπονεύσας εἴς τι χωρίον, εἰς ὃ παρῆν μηδὲ εἷς ἄλλος. σχίσας δὲ εἰς δώδεκα φάρση τὸ ἱμάτιον, ὅπερ ἦν αὐτὸς περιβεβλημένος, ἐκέλευσε τὸν Ἱεροβόαμον λαβεῖν τὰ δέκα προσειπών, ὅτι ταῦτα ὁ θεὸς βούλεται καὶ σχίσας τὴν Σολόμωνος ἀρχὴν τῷ παιδὶ μὲν τῷ τούτου διὰ τὴν πρὸς Δαυίδην γεγενημένην ὁμολογίαν αὐτῷ μίαν φυλὴν καὶ τὴν ἑξῆς αὐτῇ δίδωσι, σοὶ δὲ τὰς δέκα Σολόμωνος εἰς αὐτὸν ἐξαμαρτόντος καὶ ταῖς γυναιξὶ καὶ τοῖς ἐκείνων θεοῖς αὑτὸν ἐκδεδωκότος. εἰδὼς οὖν τὴν αἰτίαν δι’ ἣν μετατίθησι τὴν αὑτοῦ γνώμην ἀπὸ Σολόμωνος ὁ θεὸς δίκαιος εἶναι πειρῶ καὶ φύλαττε τὰ νόμιμα, προκειμένου σοι τῆς εὐσεβείας καὶ τῆς πρὸς τὸν θεὸν τιμῆς ἄθλου μεγίστου τῶν ἁπάντων, γενήσεσθαι τηλικούτῳ ἡλίκον οἶσθα Δαυίδην γενόμενον.", "st": "8.7.8"}, {"sp": "N", "t": "Ἐπαρθεὶς οὖν τοῖς τοῦ προφήτου λόγοις Ἱεροβόαμος φύσει θερμὸς ἂν νεανίας καὶ μεγάλων ἐπιθυμητὴς πραγμάτων οὐκ ἠρέμει. γενόμενος δ’ ἐν τῇ στρατηγίᾳ καὶ μεμνημένος τῶν ὑπὸ Ἀχία δεδηλωμένων εὐθὺς ἀναπείθειν ἐπεχείρει τὸν λαὸν ἀφίστασθαι Σολόμωνος καὶ κινεῖν καὶ παράγειν εἰς αὑτὸν τὴν ἡγεμονίαν. μαθὼν δὲ τὴν διάνοιαν αὐτοῦ καὶ τὴν ἐπιβολὴν Σολόμων ἐζήτει συλλαβὼν αὐτὸν ἀνελεῖν. φθάσας δὲ γνῶναι τοῦτο Ἱεροβόαμος πρὸς Ἴσακον φεύγει τὸν Αἰγυπτίων βασιλέα, καὶ μέχρι τῆς Σολόμωνος τελευτῆς ἐκεῖ μείνας τό τε μηδὲν ὑπ’ αὐτοῦ παθεῖν ἐκέρδησε καὶ τὸ τῇ βασιλείᾳ φυλαχθῆναι. ἀποθνήσκει δὲ Σολόμων ἤδη γηραιὸς ὢν βασιλεύσας μὲν ὀγδοήκοντα ἔτη, ζήσας δὲ ἐνενήκοντα καὶ τέσσαρα· θάπτεται δὲ ἐν Ἱεροσολύμοις ἅπαντας ὑπερβαλὼν εὐδαιμονίᾳ τε καὶ πλούτῳ καὶ φρονήσει τοὺς βασιλεύσαντας, εἰ μὴ ὅσα γε πρὸς τὸ γῆρας ὑπὸ τῶν γυναικῶν ἀπατηθεὶς παρηνόμησε· περὶ ὧν καὶ τῶν δι’ αὐτὰς κακῶν συμπεσόντων Ἑβραίοις εὐκαιρότερον ἕξομεν διασαφῆσαι.", "st": "8.8.1"}, {"sp": "N", "t": "Μετὰ δὲ τὴν Σολόμωνος τελευτὴν διαδεξαμένου τοῦ παιδὸς αὐτοῦ τὴν βασιλείαν Ῥοβοάμου, ὃς ἐκ γυναικὸς Ἀμμανίτιδος ὑπῆρχεν αὐτῷ γεγονὼς Νοομᾶς τοὔνομα, πέμψαντες εὐθὺς εἰς τὴν Αἴγυπτον οἱ τῶν ὄχλων ἄρχοντες ἐκάλουν τὸν Ἱεροβόαμον. ἀφικομένου δὲ πρὸς αὐτοὺς εἰς Σίκιμα πόλιν καὶ Ῥοβόαμος εἰς αὐτὴν παραγίνεται· δέδοκτο γὰρ αὐτὸν ἐκεῖσε συνελθοῦσι τοῖς Ἰσραηλίταις ἀποδεῖξαι βασιλέα. προσελθόντες οὖν οἵ τε ἄρχοντες αὐτῷ τοῦ λαοῦ καὶ Ἱεροβόαμος παρεκάλουν λέγοντες ἀνεῖναί τι τῆς δουλείας αὐτοῖς καὶ γενέσθαι χρηστότερον τοῦ πατρός· βαρὺν γὰρ ὑπ’ ἐκείνῳ ζυγὸν αὐτοὺς ὑπενεγκεῖν· εὐνούστεροι δὲ ἔσεσθαι πρὸς αὐτὸν καὶ ἀγαπήσειν τὴν δουλείαν διὰ τὴν ἐπιείκειαν ἢ διὰ τὸν φόβον. ὁ δὲ μετὰ τρεῖς ἡμέρας εἰπὼν αὐτοῖς ἀποκρινεῖσθαι περὶ ὧν ἀξιοῦσιν ὕποπτος μὲν εὐθὺς γίνεται μὴ παραχρῆμα ἐπινεύσας αὐτοῖς τὰ πρὸς ἡδονήν, πρόχειρον γὰρ ἠξίουν εἶναι τὸ χρηστὸν καὶ φιλάνθρωπον καὶ ταῦτ’ ἐν νέῳ, ἐδόκει δ’ ὅμως καὶ τὸ βουλεύσασθαι τοῦ μὴ παραυτίκα ἀπειπεῖν ἀγαθῆς ἐλπίδος ἔχεσθαι.", "st": "8.8.2"}, {"sp": "N", "t": "Συγκαλέσας δὲ τοὺς πατρῴους φίλους ἐσκοπεῖτο μετ’ αὐτῶν, ποδαπὴν δεῖ ποιήσασθαι τὴν ἀπόκρισιν πρὸς τὸ πλῆθος. οἱ δ’ ἅπερ εἰκὸς τοὺς εὔνους καὶ φύσιν ὄχλων εἰδότας παρῄνουν αὐτῷ φιλοφρόνως ὁμιλῆσαι τῷ λαῷ καὶ δημοτικώτερον ἢ κατὰ βασιλείας ὄγκον· χειρώσεσθαι γὰρ οὕτως εἰς εὔνοιαν αὐτὸν φύσει τῶν ὑπηκόων ἀγαπώντων τὸ προσηνὲς καὶ παρὰ μικρὸν ἰσότιμον τῶν βασιλέων. ὁ δ’ ἀγαθὴν οὕτως καὶ συμφέρουσαν ἴσως πρὸς τὸ πᾶν, εἰ δὲ μή, πρός γε τὸν τότε καιρὸν ὅτ’ ἔδει γενέσθαι βασιλέα γνώμην ἀπεστράφη τοῦ θεοῦ ποιήσαντος οἶμαι κατακριθῆναι τὸ συμφέρον ὑπ’ αὐτοῦ· καλέσας δὲ μειράκια τὰ συντεθραμμένα καὶ τὴν τῶν πρεσβυτέρων αὐτοῖς συμβουλίαν εἰπών, τί δοκεῖ ποιεῖν αὐτοῖς ἐκέλευσε λέγειν. τὰ δέ, οὔτε γὰρ ἡ νεότης οὔτε ὁ θεὸς ἠφίει νοεῖν τὰ κρείττω, παρῄνεσαν ἀποκρίνασθαι τῷ λαῷ τὸν βραχύτατον αὐτοῦ δάκτυλον τῆς τοῦ πατρὸς ὀσφύος εἶναι παχύτερον καί, εἰ σκληροῦ λίαν ἐπειράθησαν ἐκείνου, πολὺ μᾶλλον αὐτοῦ λήψεσθαι πεῖραν δυσκόλου· καὶ εἰ μάστιξιν αὐτοὺς ἐκεῖνος ἐνουθέτει, σκορπίοις τοῦτο ποιήσειν αὐτὸν προσδοκᾶν. τούτοις ἡσθεὶς ὁ βασιλεὺς καὶ δόξας προσήκειν τῷ τῆς ἀρχῆς ἀξιώματι τὴν ἀπόκρισιν, ὡς συνῆλθεν ἀκουσόμενον τὸ πλῆθος τῇ τρίτῃ τῶν ἡμερῶν, μετεώρου τοῦ λαοῦ παντὸς ὄντος καὶ λέγοντος ἀκοῦσαί τι τοῦ βασιλέως ἐσπουδακότος, οἰομένου δέ τι καὶ φιλάνθρωπον, τὴν τῶν μειρακίων αὐτοῖς συμβουλίαν παρεὶς τὴν τῶν φίλων ἀπεκρίνατο. ταῦτα δ’ ἐπράττετο κατὰ τὴν τοῦ θεοῦ βούλησιν, ἵνα λάβῃ τέλος ἃ προεφήτευσεν Ἀχίας.", "st": "8.8.3"}, {"sp": "N", "t": "Πληγέντες δ’ ὑπὸ τῶν λόγων καὶ ἀλγήσαντες ὡς ἐπὶ πείρᾳ τοῖς εἰρημένοις ἠγανάκτησαν καὶ μέγα πάντες ἐκβοήσαντες οὐκέτι οὐδὲν αὐτοῖς οὐδὲ συγγενὲς πρὸς Δαυίδην καὶ τοὺς ἀπ’ αὐτοῦ μετ’ ἐκείνην ἔφασαν τὴν ἡμέραν· παραχωρεῖν δ’ αὐτῷ μόνον τὸν ναὸν ὃν ὁ πάππος αὐτοῦ κατεσκεύασεν εἰπόντες καταλείψειν ἠπείλησαν. οὕτως δ’ ἔσχον πικρῶς καὶ τὴν ὀργὴν ἐτήρησαν, ὡς πέμψαντος αὐτοῦ τὸν ἐπὶ τῶν φόρων Ἀδώραμον, ἵνα καταπραΰνῃ καὶ συγγνόντας τοῖς εἰρημένοις, εἴ τι προπετὲς καὶ δύσκολον ἦν ἐν αὐτοῖς, ποιήσῃ μαλακωτέρους, οὐχ ὑπέμειναν, ἀλλὰ βάλλοντες αὐτὸν λίθοις ἀπέκτειναν. ταῦτ’ ἰδὼν Ῥοβόαμος καὶ νομίσας αὑτὸν βεβλῆσθαι τοῖς λίθοις, οἷς τὸν ὑπηρέτην ἀπέκτεινεν αὐτοῦ τὸ πλῆθος, δείσας μὴ καὶ ἔργῳ πάθῃ τὸ δεινὸν ἐπιβὰς εὐθὺς ἐπὶ ἅρματος ἔφυγεν εἰς Ἱεροσόλυμα. καὶ ἡ μὲν Ἰούδα φυλὴ καὶ ἡ Βενιαμίδος χειροτονοῦσιν αὐτὸν βασιλέα, τὸ δὲ ἄλλο πλῆθος ἀπ’ ἐκείνης τῆς ἡμέρας τῶν Δαυίδου παίδων ἀποστὰν τὸν Ἱεροβόαμον ἀπέδειξε τῶν πραγμάτων κύριον. Ῥοβόαμος δὲ ὁ Σολόμωνος παῖς ἐκκλησίαν ποιήσας τῶν δύο φυλῶν, ἃς εἶχεν ὑπηκόους, οἷός τε ἦν λαβὰν ὀκτωκαίδεκα παρ’ αὐτῶν στρατοῦ μυριάδας ἐπιλέκτους ἐξελθεῖν ἐπὶ τὸν Ἱεροβόαμον καὶ τὸν λαόν, ὅπως πολεμήσας ἀναγκάσῃ δουλεύειν αὐτῷ. κωλυθεὶς δ’ ὑπὸ τοῦ θεοῦ διὰ τοῦ προφήτου ποιήσασθαι τὴν στρατείαν, οὐ γὰρ εἶναι δίκαιον τοὺς ὁμοφύλους πολεμεῖν οὗτος ἔλεγε καὶ ταῦτα κατὰ τὴν τοῦ θεοῦ προαίρεσιν τῆς τοῦ πλήθους ἀποστάσεως γεγενημένης, οὐκέτ’ ἐξῆλθε. διηγήσομαι δὲ πρῶτον ὅσα Ἱεροβόαμος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς ἔπραξεν, εἶτα δὲ τούτων ἐχόμενα τὰ ὑπὸ Ῥοβοάμου τοῦ τῶν δύο φυλῶν βασιλέως γεγενημένα δηλώσομεν· φυλαχθείη γὰρ ἂν οὕτως ἄχρι παντὸς τῆς ἱστορίας τὸ εὔτακτον.", "st": "8.8.4"}, {"sp": "N", "t": "Ὁ τοίνυν Ἱεροβόαμος οἰκοδομήσας βασίλειον ἐν Σικίμῃ πόλει ἐν ταύτῃ τὴν δίαιταν εἶχε, κατεσκεύασε δὲ καὶ ἐν Φανουὴλ πόλει λεγομένῃ. μετ’ οὐ πολὺ δὲ τῆς σκηνοπηγίας ἑορτῆς ἐνίστασθαι μελλούσης λογισάμενος, ὡς ἐὰν ἐπιτρέψῃ τῷ πλήθει προσκυνῆσαι τὸν θεὸν εἰς Ἱεροσόλυμα πορευθέντι καὶ ἐκεῖ τὴν ἑορτὴν διαγαγεῖν, μετανοῆσαν ἴσως καὶ δελεασθὲν ὑπὸ τοῦ ναοῦ καὶ τῆς θρησκείας τῆς ἐν αὐτῷ τοῦ θεοῦ καταλείψει μὲν αὐτόν, προσχωρήσει δὲ τῷ πρώτῳ βασιλεῖ, καὶ κινδυνεύσει τούτου γενομένου τὴν ψυχὴν ἀποβαλεῖν, ἐπιτεχνᾶταί τι τοιοῦτον· δύο ποιήσας δαμάλεις χρυσᾶς καὶ οἰκοδομήσας ναΐσκους τοσούτους ἕνα μὲν ἐν Βηθήλῃ πόλει, τὸν ἕτερον δὲ ἐν Δάνῃ, ἡ δ’ ἐστὶ πρὸς ταῖς πηγαῖς τοῦ μικροῦ Ἰορδάνου, τίθησι τὰς δαμάλεις ἐν ἑκατέρῳ τῶν ἐν ταῖς προειρημέναις πόλεσι ναΐσκων, καὶ συγκαλέσας τὰς δέκα φυλὰς ὧν αὐτὸς ἦρχεν ἐδημηγόρησε τούτους ποιησάμενος τοὺς λόγους· ἄνδρες ὁμόφυλοι, γινώσκειν ὑμᾶς νομίζω τοῦτο, ὅτι πᾶς τόπος ἔχει τὸν θεὸν καὶ οὐκ ἔστιν ἓν ἀποδεδειγμένον χωρίον ἐν ᾧ πάρεστιν, ἀλλὰ πανταχοῦ τε ἀκούει καὶ τοὺς θρησκεύοντας ἐφορᾷ. ὅθεν οὔ μοι δοκεῖ νῦν ἐπείγειν ὑμᾶς εἰς Ἱεροσόλυμα πορευθέντας εἰς τὴν τῶν ἐχθρῶν πόλιν μακρὰν οὕτως ὁδὸν προσκυνεῖν· ἄνθρωπος γὰρ κατεσκεύακε τὸν ναόν, πεποίηκα δὲ κἀγὼ δύο χρυσᾶς δαμάλεις ἐπωνύμους τῷ θεῷ καὶ τὴν μὲν ἐν Βηθήλῃ πόλει καθιέρωσα τὴν δ’ ἐν Δάνῃ, ὅπως ὑμῶν οἱ τούτων ἔγγιστα τῶν πόλεων κατῳκημένοι προσκυνῶσιν εἰς αὐτὰς ἀπερχόμενοι τὸν θεόν. ἀποδείξω δέ τινας ὑμῖν καὶ ἱερεῖς ἐξ ὑμῶν αὐτῶν καὶ Ληουίτας, ἵνα μὴ χρείαν ἔχητε τῆς Ληουίτιδος φυλῆς καὶ τῶν υἱῶν Ἀαρῶνος, ἀλλ’ ὁ βουλόμενος ὑμῶν ἱερεὺς εἶναι προσενεγκάτω μόσχον τῷ θεῷ καὶ κριόν, ὃ καὶ τὸν πρῶτον ἱερέα φασὶν Ἀαρῶνα πεποιηκέναι. ταῦτ’ εἰπὼν ἐξηπάτησε τὸν λαὸν καὶ τῆς πατρίου θρησκείας ἀποστάντας ἐποίησε παραβῆναι τοὺς νόμους. ἀρχὴ κακῶν ἐγένετο τοῦτο τοῖς Ἑβραίοις καὶ τοῦ πολέμῳ κρατηθέντας ὑπὸ τῶν ἀλλοφύλων αἰχμαλωσίᾳ περιπεσεῖν. ἀλλὰ ταῦτα μὲν κατὰ χώραν δηλώσομεν.", "st": "8.8.5"}, {"sp": "N", "t": "Ἐνστάσης δὲ τῆς ἑορτῆς ἑβδόμῳ μηνὶ βουλόμενος καὶ αὐτὸς ἐν Βηθήλῃ ταύτην ἀγαγεῖν, ὥσπερ ἑώρταζον καὶ αἱ δύο φυλαὶ ἐν Ἱεροσολύμοις, οἰκοδομεῖ μὲν θυσιαστήριον πρὸ τῆς δαμάλεως, γενόμενος δὲ αὐτὸς ἀρχιερεὺς ἐπὶ τὸν βωμὸν ἀναβαίνει σὺν τοῖς ἰδίοις ἱερεῦσι. μέλλοντος δ’ ἐπιφέρειν τὰς θυσίας καὶ τὰς ὁλοκαυτώσεις ἐν ὄψει τοῦ λαοῦ παντὸς παραγίνεται πρὸς αὐτὸν ἐξ Ἱεροσολύμων προφήτης Ἰάδων ὄνομα τοῦ θεοῦ πέμψαντος, ὃς σταθεὶς ἐν μέσῳ τῷ πλήθει τοῦ βασιλέως ἀκούοντος εἶπε τάδε πρὸς τὸ θυσιαστήριον ποιούμενος τοὺς λόγους· ὁ θεὸς ἔσεσθαί τινα προλέγει ἐκ τοῦ Δαυίδου γένους Ἰωσίαν ὄνομα, ὃς ἐπὶ σοῦ θύσει τοὺς ψευδιερεῖς τοὺς κατ’ ἐκεῖνον τὸν καιρὸν γενησομένους καὶ τὰ ὀστᾶ τῶν λαοπλάνων τούτων καὶ ἀπατεώνων καὶ ἀσεβῶν ἐπὶ σοῦ καύσει. ἵνα μέντοι γε πιστεύσωσιν οὗτοι τοῦθ’ οὕτως ἕξειν, σημεῖον αὐτοῖς προερῶ γενησόμενον· ῥαγήσεται τὸ θυσιαστήριον παραχρῆμα καὶ πᾶσα ἡ ἐπ’ αὐτοῦ πιμελὴ τῶν ἱερείων ἐπὶ γῆν χυθήσεται. ταῦτ’ εἰπόντος τοῦ προφήτου παροξυνθεὶς ὁ Ἱεροβόαμος ἐξέτεινε τὴν χεῖρα κελεύων συλλαβεῖν αὐτόν. ἐκτεταμένη δ’ ἡ χεὶρ εὐθέως παρείθη καὶ οὐκέτ’ ἴσχυε ταύτην πρὸς αὑτὸν ἀναγαγεῖν, ἀλλὰ νεναρκηκυῖαν καὶ νεκρὰν εἶχεν ἀπηρτημένην. ἐρράγη δὲ καὶ τὸ θυσιαστήριον καὶ κατηνέχθη πάντα ἀπ’ αὐτοῦ, καθὼς προεῖπεν ὁ προφήτης. μαθὼν δὲ ἀληθῆ τὸν ἄνθρωπον καὶ θείαν ἔχοντα πρόγνωσιν παρεκάλεσεν αὐτὸν δεηθῆναι τοῦ θεοῦ ἀναζωπυρῆσαι τὴν δεξιὰν αὐτῷ. καὶ ὁ μὲν ἱκέτευσε τὸν θεὸν τοῦτ’ αὐτῷ παρασχεῖν, ὁ δὲ τῆς χειρὸς τὸ κατὰ φύσιν ἀπολαβούσης χαίρων ἐπ’ αὐτῇ τὸν προφήτην παρεκάλει δειπνῆσαι παρ’ αὐτῷ. Ἰάδων δέ φησιν οὐχ ὑπομένειν εἰσελθεῖν πρὸς αὐτὸν οὐδὲ γεύσασθαι ἄρτου καὶ ὕδατος ἐν ταύτῃ τῇ πόλει· τοῦτο γὰρ αὐτῷ τὸν θεὸν ἀπειρηκέναι καὶ τὴν ὁδὸν ἣν ἦλθεν ὅπως μὴ δι’ αὐτῆς ποιήσηται τὴν ἐπιστροφήν, ἀλλὰ δι’ ἄλλης ἔφασκεν· τοῦτον μὲν οὖν ὁ βασιλεὺς ἐθαύμαζεν τῆς ἐγκρατείας, αὐτὸς δ’ ἦν ἐν φόβῳ μεταβολὴν αὐτοῦ τῶν πραγμάτων ἐκ τῶν προειρημένων οὐκ ἀγαθὴν ὑπονοῶν.", "st": "8.9.1"}, {"sp": "N", "t": "Ἦν δέ τις ἐν τῇ πόλει πρεσβύτης πονηρὸς ψευδοπροφήτης, ὃν εἶχεν ἐν τιμῇ Ἱεροβόαμος ἀπατώμενος ὑπ’ αὐτοῦ τὰ πρὸς ἡδονὴν λέγοντος. οὗτος τότε μὲν κλινήρης ἦν διὰ τὴν ἀπὸ τοῦ γήρως ἀσθένειαν, τῶν δὲ παίδων αὐτῷ δηλωσάντων τὰ περὶ τοῦ παρόντος ἐξ Ἱεροσολύμων προφήτου καὶ τῶν σημείων τῶν γενομένων, καὶ ὡς παρεθεῖσαν αὐτῷ τὴν δεξιὰν Ἱεροβόαμος εὐξαμένου πάλιν ἐκείνου ζῶσαν ἀπολάβοι, δείσας μὴ παρευδοκιμήσειεν αὐτὸν ὁ ξένος παρὰ τῷ βασιλεῖ καὶ πλείονος ἀπολαύοι τιμῆς προσέταξε τοῖς παισὶν εὐθὺς ἐπιστρώσασι τὸν ὄνον ἕτοιμον πρὸς ἔξοδον αὐτῷ παρασκευάσαι. τῶν δὲ σπευσάντων ὃ προσετάγησαν ἐπιβὰς ἐδίωξε τὸν προφήτην καὶ καταλαβὼν ἀναπαυόμενον ὑπὸ δένδρῳ δασεῖ καὶ σκιὰν ἔχοντι δρυὸς εὐμεγέθους ἠσπάσατο πρῶτον, εἶτ’ ἐμέμφετο μὴ παρ’ αὐτὸν εἰσελθόντα καὶ ξενίων μεταλαβόντα. τοῦ δὲ φήσαντος κεκωλῦσθαι πρὸς τοῦ θεοῦ γεύσασθαι παρά τινι τῶν ἐν ἐκείνῃ τῇ πόλει, ἀλλ’ οὐχὶ παρ’ ἐμοὶ πάντως, εἶπεν, ἀπηγόρευκέ σοι τὸ θεῖον παραθέσθαι τράπεζαν· προφήτης γάρ εἰμι κἀγὼ καὶ τῆς αὐτῆς σοι κοινωνὸς πρὸς αὐτὸν θρησκείας, καὶ πάρειμι νῦν ὑπ’ αὐτοῦ πεμφθείς. ὅπως ἀγάγω σε πρὸς ἐμαυτὸν ἑστιασόμενον. ὁ δὲ ψευσαμένῳ πεισθεὶς ἀνέστρεψεν· ἀριστώντων δ’ ἔτι καὶ φιλοφρονουμένων ὁ θεὸς ἐπιφαίνεται τῷ Ἰάδωνι καὶ παραβάντα τὰς ἐντολὰς αὐτοῦ τιμωρίαν ὑφέξειν ἔλεγεν καὶ ποδαπὴν ἐδήλου· λέοντα γὰρ αὐτῷ κατὰ τὴν ὁδὸν ἀπερχομένῳ συμβαλεῖν ἔφραζεν, ὑφ’ οὗ διαφθαρήσεσθαι καὶ τῆς ἐν τοῖς πατρῴοις μνήμασι ταφῆς ἀμοιρήσειν. ταῦτα δ’ ἐγένετο οἶμαι κατὰ τὴν τοῦ θεοῦ βούλησιν, ὅπως μὴ προσέχοι τοῖς τοῦ Ἰάδωνος λόγοις Ἱεροβόαμος ἐληλεγμένῳ ψευδεῖ. πορευομένῳ τοίνυν τῷ Ἰάδωνι πάλιν εἰς Ἱεροσόλυμα συμβάλλει λέων καὶ κατασπάσας αὐτὸν ἀπὸ τοῦ κτήνους ἀπέκτεινε, καὶ τὸν μὲν ὄνον οὐδὲν ὅλως ἔβλαψε, παρακαθεζόμενος δ’ ἐφύλαττε κἀκεῖνον καὶ τὸ τοῦ προφήτου σῶμα, μέχρις οὗ τινες τῶν ὁδοιπόρων ἰδόντες ἀπήγγειλαν ἐλθόντες εἰς τὴν πόλιν τῷ ψευδοπροφήτῃ. ὁ δὲ τοὺς υἱοὺς πέμψας ἐκόμισε τὸ σῶμα εἰς τὴν πόλιν καὶ πολυτελοῦς κηδείας ἠξίωσεν ἐντειλάμενος τοῖς παισὶ καὶ αὐτὸν ἀποθανόντα σὺν ἐκείνῳ θάψαι, λέγων ἀληθῆ μὲν εἶναι πάνθ’ ὅσα προεφήτευσε κατὰ τῆς πόλεως ἐκείνης καὶ τοῦ θυσιαστηρίου καὶ τῶν ἱερέων καὶ τῶν ψευδοπροφητῶν, ὑβρισθήσεσθαι δ’ αὐτὸς μετὰ τὴν τελευτὴν οὐδὲν σὺν ἐκείνῳ ταφεὶς τῶν ὀστῶν οὐ γνωρισθησομένων. κηδεύσας οὖν τὸν προφήτην καὶ ταῦτα τοῖς υἱοῖς ἐντειλάμενος πονηρὸς ὢν καὶ ἀσεβὴς πρόσεισι τῷ Ἱεροβοάμῳ καὶ τί δήποτ’ ἐταράχθης, εἰπών, ὑπὸ τῶν τοῦ ἀνοήτου λόγων; ὡς τὰ περὶ τὸ θυσιαστήριον αὐτῷ καὶ τὴν αὑτοῦ χεῖρα διηγήσαθ’ ὁ βασιλεὺς θεῖον ἀληθῶς καὶ προφήτην ἄριστον ἀποκαλῶν, ἤρξατο ταύτην αὐτοῦ τὴν δόξαν ἀναλύειν [κακουργῶν] καὶ πιθανοῖς περὶ τῶν γεγενημένων χρώμενος λόγοις βλάπτειν αὐτῶν τὴν ἀλήθειαν. ἐπεχείρει γὰρ πείθειν αὐτόν, ὡς ὑπὸ κόπου μὲν ἡ χεὶρ αὐτοῦ ναρκήσειε βαστάζουσα τὰς θυσίας, εἶτ’ ἀνεθεῖσα πάλιν εἰς τὴν αὑτῆς ἐπανέλθοι φύσιν, τὸ δὲ θυσιαστήριον καινὸν ὂν καὶ δεξάμενον θυσίας πολλὰς καὶ μεγάλας ῥαγείη καὶ πέσοι διὰ βάρος τῶν ἐπενηνεγμένων. ἐδήλου δ’ αὐτῷ καὶ τὸν θάνατον τοῦ τὰ σημεῖα [ταῦτα] προειρηκότος ὡς ὑπὸ λέοντος ἀπώλετο· οὕτως οὐδὲ ἓν οὔτ’ εἶχεν οὔτ’ ἐφθέγξατο προφήτου. ταῦτα εἰπὼν πείθει τὸν βασιλέα καὶ τὴν διάνοιαν αὐτοῦ τελέως ἀποστρέψας ἀπὸ τοῦ θεοῦ καὶ τῶν ὁσίων ἔργων καὶ δικαίων ἐπὶ τὰς ἀσεβεῖς πράξεις παρώρμησεν. οὕτως δ’ ἐξύβρισεν εἰς τὸ θεῖον καὶ παρηνόμησεν, ὡς οὐδὲν ἄλλο καθ’ ἡμέραν ζητεῖν ἢ τί καινὸν καὶ μιαρώτερον τῶν ἤδη τετολμημένων ἐργάσηται. καὶ τὰ μὲν περὶ Ἱεροβόαμον ἐπὶ τοῦ παρόντος ἐν τούτοις ἡμῖν δεδηλώσθω.", "st": "8.10.1"}, {"sp": "N", "t": "Ὁ δὲ Σολόμωνος υἱὸς Ῥοβόαμος ὁ τῶν δύο φυλῶν βασιλεύς, ὡς προειρήκαμεν, ᾠκοδόμησε πόλεις ὀχυράς τε καὶ μεγάλας Βηθλεὲμ καὶ Ἠταμὲ καὶ Θεκωὲ καὶ Βηθσοὺρ καὶ Σωχὼ καὶ Ὀδολλὰμ καὶ Εἰπὰν καὶ Μάρισαν καὶ τὴν Ζιφὰ καὶ Ἀδωραὶμ καὶ Λάχεις καὶ Ἀζηκὰ καὶ Σαρὰμ καὶ Ἠλὼμ καὶ Χεβρῶνα. ταύτας μὲν ἐν τῇ Ἰουδαίᾳ φυλῇ [καὶ κληρουχίᾳ] πρώτας ᾠκοδόμησε, κατεσκεύασε δὲ καὶ ἄλλας μεγάλας ἐν τῇ Βενιαμίδι κληρουχίᾳ, καὶ τειχίσας φρουράς τε κατέστησεν ἐν ἁπάσαις καὶ ἡγεμόνας σῖτόν τε πολὺν καὶ οἶνον καὶ ἔλαιον τά τε ἄλλα πρὸς διατροφὴν ἐν ἑκάστῃ τῶν πόλεων δαψιλῶς ἀπέθετο, πρὸς δὲ τούτοις θυρεοὺς καὶ σιρομάστας εἰς πολλὰς μυριάδας. συνῆλθον δὲ οἱ παρὰ πᾶσι τοῖς Ἰσραηλίταις ἱερεῖς πρὸς αὐτὸν εἰς Ἱεροσόλυμα καὶ Ληουῖται καὶ εἴ τινες ἄλλοι τοῦ πλήθους ἦσαν ἀγαθοὶ καὶ δίκαιοι καταλιπόντες αὑτῶν τὰς πόλεις, ἵνα θρησκεύσωσιν ἐν Ἱεροσολύμοις τὸν θεόν· οὐ γὰρ ἡδέως εἶχον προσκυνεῖν ἀναγκαζόμενοι τὰς δαμάλεις, ἃς Ἱεροβόαμος κατεσκεύασε· καὶ ηὔξησαν τὴν Ῥοβοάμου βασιλείαν ἐπ’ ἔτη τρία. γήμας δὲ συγγενῆ τινα καὶ τρεῖς ποιησάμενος ἐξ αὐτῆς παῖδας ἤγετο ὕστερον καὶ τὴν ἐκ τῆς Ἀψαλώμου θυγατρὸς Θαμάρης Μαχάνην ὄνομα καὶ αὐτὴν οὖσαν συγγενῆ· καὶ παῖς ἐξ αὐτῆς ἄρρην αὐτῷ γίνεται, ὃν Ἀβίαν προσηγόρευσεν. τεκνοῖ δὲ καὶ ἐξ ἄλλων γυναικῶν πλειόνων, ἁπασῶν δὲ μᾶλλον ἔστερξε τὴν Μαχάνην. εἶχε δὲ τὰς μὲν νόμῳ συνοικούσας αὐτῷ γυναῖκας ὀκτωκαίδεκα παλλακὰς δὲ τριάκοντα, καὶ υἱοὶ μὲν αὐτῷ γεγόνεισαν ὀκτὼ καὶ εἴκοσι θυγατέρες δ’ ἑξήκοντα. διάδοχον δὲ ἀπέδειξε τῆς βασιλείας τὸν ἐκ τῆς Μαχάνης Ἀβίαν καὶ τοὺς θησαυροὺς αὐτῷ καὶ τὰς ὀχυρωτάτας πόλεις ἐπίστευσεν.", "st": "8.10.2"}, {"sp": "N", "t": "Αἴτιον δ’ οἶμαι πολλάκις γίνεται κακῶν καὶ παρανομίας τοῖς ἀνθρώποις τὸ τῶν πραγμάτων μέγεθος καὶ ἡ πρὸς τὸ βέλτιον αὐτῶν τροπή· τὴν γὰρ βασιλείαν αὐξανομένην οὕτω βλέπων Ῥοβόαμος εἰς ἀδίκους καὶ ἀσεβεῖς ἐξετράπη πράξεις καὶ τῆς τοῦ θεοῦ θρησκείας κατεφρόνησεν, ὡς καὶ τὸν ὑπ’ αὐτῷ λαὸν μιμητὴν γενέσθαι τῶν ἀνομημάτων. συνδιαφθείρεται γὰρ τὰ τῶν ἀρχομένων ἤθη τοῖς τῶν ἡγουμένων τρόποις, καὶ ὡς ἔλεγχον τῆς ἐκείνων ἀσελγείας τὴν αὑτῶν σωφροσύνην παραπέμποντες ὡς ἀρετῇ ταῖς κακίαις αὐτῶν ἕπονται· οὐ γὰρ ἔνεστιν ἀποδέχεσθαι δοκεῖν τὰ τῶν βασιλέων ἔργα μὴ ταὐτὰ πράττοντας. τοῦτο τοίνυν συνέβαινε καὶ τοῖς ὑπὸ Ῥοβοάμῳ τεταγμένοις ἀσεβοῦντος αὐτοῦ καὶ παρανομοῦντος σπουδάζειν, μὴ προσκρούσωσι τῷ βασιλεῖ θέλοντες εἶναι δίκαιοι. τιμωρὸν δὲ τῶν εἰς αὐτὸν ὕβρεων ὁ θεὸς ἐπιπέμπει τὸν Αἰγυπτίων βασιλέα Ἴσωκον, περὶ οὗ πλανηθεὶς Ἡρόδοτος τὰς πράξεις αὐτοῦ Σεσώστρει προσάπτει. οὗτος γὰρ ὁ Ἴσωκος πέμπτῳ ἔτει τῆς Ῥοβοάμου βασιλείας ἐπιστρατεύεται μετὰ πολλῶν αὐτῷ μυριάδων· ἅρματα μὲν γὰρ αὐτῷ χίλια καὶ διακόσια τὸν ἀριθμὸν ἠκολούθει, ἱππέων δὲ μυριάδες ἕξ, πεζῶν δὲ μυριάδες τεσσαράκοντα. τούτων τοὺς πλείστους Λίβυας ἐπήγετο καὶ Αἰθίοπας. ἐμβαλὼν οὖν εἰς τὴν χώραν τῶν Ἑβραίων καταλαμβάνει τε τὰς ὀχυρωτάτας τῆς Ῥοβοάμου βασιλείας πόλεις ἀμαχητὶ καὶ ταύτας ἀσφαλισάμενος ἔσχατον ἐπῆλθε τοῖς Ἱεροσολύμοις ἐγκεκλεισμένου τοῦ Ῥοβοάμου καὶ τοῦ πλήθους ἐν αὐτοῖς διὰ τὴν Ἰσώκου στρατείαν καὶ τὸν θεὸν ἱκετευόντων δοῦναι νίκην καὶ σωτηρίαν· ἀλλ’ οὐκ ἔπεισαν τὸν θεὸν ταχθῆναι μετ’ αὐτῶν· ὁ δὲ προφήτης Σαμαίας ἔφησεν αὐτοῖς τὸν θεὸν ἀπειλεῖν ἐγκαταλείψειν αὐτούς, ὡς καὶ αὐτοὶ τὴν θρησκείαν αὐτοῦ κατέλιπον. ταῦτ’ ἀκούσαντες εὐθὺς ταῖς ψυχαῖς ἀνέπεσον καὶ μηδὲν ἔτι σωτήριον ὁρῶντες ἐξομολογεῖσθαι πάντες ὥρμησαν, ὅτι δικαίως αὐτοὺς ὁ θεὸς ὑπερόψεται γενομένους περὶ αὐτὸν ἀσεβεῖς καὶ συγχέοντας τὰ νόμιμα. κατιδὼν δ’ αὐτοὺς ὁ θεὸς οὕτω διακειμένους καὶ τὰς ἁμαρτίας ἀνθομολογουμένους οὐκ ἀπολέσειν αὐτοὺς εἶπε πρὸς τὸν προφήτην, ποιήσειν μέντοι γε τοῖς Αἰγυπτίοις ὑποχειρίους, ἵνα μάθωσι πότερον ἀνθρώπῳ δουλεύειν ἐστὶν ἀπονώτερον ἢ θεῷ. παραλαβὼν δὲ Ἴσωκος ἀμαχητὶ τὴν πόλιν δεξαμένου Ῥοβοάμου διὰ τὸν φόβον οὐκ ἐνέμεινε ταῖς γενομέναις συνθήκαις, ἀλλ’ ἐσύλησε τὸ ἱερὸν καὶ τοὺς θησαυροὺς ἐξεκένωσε τοῦ θεοῦ καὶ τοὺς βασιλικοὺς χρυσοῦ καὶ ἀργύρου μυριάδας ἀναριθμήτους βαστάσας καὶ μηδὲν ὅλως ὑπολιπών. περιεῖλε δὲ καὶ τοὺς χρυσοῦς θυρεοὺς καὶ τὰς ἀσπίδας, ἃς κατεσκεύασε Σολόμων ὁ βασιλεύς, οὐκ εἴασε δὲ οὐδὲ τὰς χρυσᾶς φαρέτρας, ἃς ἀνέθηκε Δαυίδης τῷ θεῷ λαβὼν παρὰ τοῦ τῆς Σωφηνῆς βασιλέως, καὶ τοῦτο ποιήσας ἀνέστρεψεν εἰς τὰ οἰκεῖα. μέμνηται δὲ ταύτης τῆς στρατείας καὶ ὁ Ἁλικαρνασεὺς Ἡρόδοτος περὶ μόνον τὸ τοῦ βασιλέως πλανηθεὶς ὄνομα, καὶ ὅτι ἄλλοις τε πολλοῖς ἐπῆλθεν ἔθνεσι καὶ τὴν Παλαιστίνην Συρίαν ἐδουλώσατο λαβὼν ἀμαχητὶ τοὺς ἀνθρώπους τοὺς ἐν αὐτῇ. φανερὸν δ’ ἐστίν, ὅτι τὸ ἡμέτερον ἔθνος βούλεται δηλοῦν κεχειρωμένον ὑπὸ τοῦ Αἰγυπτίου· ἐπάγει γάρ, ὅτι στήλας κατέλιπεν ἐν τῇ τῶν ἀμαχητὶ παραδόντων ἑαυτοὺς αἰδοῖα γυναικῶν ἐγγράψας· Ῥοβόαμος δ’ αὐτῷ παρέδωκεν ὁ ἡμέτερος βασιλεὺς ἀμαχητὶ τὴν πόλιν. φησὶ δὲ καὶ Αἰθίοπας παρ’ Αἰγυπτίων μεμαθηκέναι τὴν τῶν αἰδοίων περιτομήν· Φοίνικες γὰρ καὶ Σύροι οἱ ἐν τῇ Παλαιστίνῃ ὁμολογοῦσι παρ’ Αἰγυπτίων μεμαθηκέναι. δῆλον οὖν ἐστιν, ὅτι μηδένες ἄλλοι περιτέμνονται τῶν ἐν τῇ Παλαιστίνῃ Σύρων ἢ μόνοι ἡμεῖς. ἀλλὰ περὶ μὲν τούτων ἕκαστοι λεγέτωσαν ὅ τι ἂν αὐτοῖς δοκῇ.", "st": "8.10.3"}, {"sp": "N", "t": "Ἀναχωρήσαντος δὲ Ἰσώκου Ῥοβόαμος ὁ βασιλεὺς ἀντὶ μὲν τῶν χρυσέων θυρεῶν καὶ τῶν ἀσπίδων χάλκεα ποιήσας τὸν αὐτὸν ἀριθμὸν παρέδωκε τοῖς τῶν βασιλείων φύλαξιν. ἀντὶ δὲ τοῦ μετὰ στρατηγίας ἐπιφανοῦς καὶ τῆς ἐν τοῖς πράγμασι λαμπρότητος διάγειν ἐβασίλευσεν ἐν ἡσυχίᾳ πολλῇ καὶ δέει πάντα τὸν χρόνον ἐχθρὸς ὢν Ἱεροβοάμῳ. ἐτελεύτησε δὲ βιώσας ἔτη πεντήκοντα καὶ ἑπτὰ βασιλεύσας δ’ αὐτῶν ἑπτακαίδεκα, τὸν τρόπον ἀλαζὼν ἀνὴρ καὶ ἀνόητος καὶ διὰ τὸ μὴ προσέχειν τοῖς πατρῴοις φίλοις τὴν ἀρχὴν ἀπολέσας· ἐτάφη δ’ ἐν Ἱεροσολύμοις ἐν ταῖς θήκαις τῶν βασιλέων. διεδέξατο δ’ αὐτοῦ τὴν βασιλείαν ὁ υἱὸς Ἀβίας ὄγδοον ἤδη καὶ δέκατον ἔτος Ἱεροβοάμου τῶν δέκα φυλῶν βασιλεύοντος. καὶ ταῦτα μὲν τοιοῦτον ἔσχε τὸ τέλος· τὰ δὲ περὶ Ἱεροβόαμον ἀκόλουθα τούτων ἔχομεν πῶς κατέστρεψε τὸν βίον διεξελθεῖν· οὗτος γὰρ οὐ διέλιπεν οὐδ’ ἠρέμησεν εἰς τὸν θεὸν ἐξυβρίζων, ἀλλὰ καθ’ ἑκάστην ἐπὶ τῶν ὑψηλῶν ὀρῶν βωμοὺς ἀνιστὰς καὶ ἱερεῖς ἐκ τοῦ πλήθους ἀποδεικνὺς διετέλει.", "st": "8.10.4"}, {"sp": "N", "t": "Ταῦτα δ’ ἔμελλεν οὐκ εἰς μακρὰν τἀσεβήματα καὶ τὴν ὑπὲρ αὐτῶν δίκην εἰς τὴν αὐτοῦ κεφαλὴν καὶ πάσης αὐτοῦ τῆς γενεᾶς τρέψειν τὸ θεῖον. κάμνοντος δ’ αὐτῷ κατ’ ἐκεῖνον τὸν καιρὸν τοῦ παιδός, ὃν Ὀβίμην ἐκάλουν, τὴν γυναῖκα αὐτοῦ προσέταξε τὴν στολὴν ἀποθεμένην καὶ σχῆμα λαβοῦσαν ἰδιωτικὸν πορευθῆναι πρὸς Ἀχίαν τὸν προφήτην· εἶναι γὰρ θαυμαστὸν ἄνδρα περὶ τῶν μελλόντων προειπεῖν· καὶ γὰρ περὶ τῆς βασιλείας αὐτῷ τοῦτον δεδηλωκέναι· παραγενομένην δ’ ἐκέλευσε περὶ τοῦ παιδὸς ἀνακρίνειν ὡς ξένην, εἰ διαφεύξεται τὴν νόσον. ἡ δὲ μετασχηματισαμένη, καθὼς αὐτῇ προσέταξεν ὁ ἀνήρ, ἧκεν εἰς Σιλὼ πόλιν· ἐκεῖ γὰρ διέτριβεν ὁ Ἀχίας. καὶ μελλούσης εἰς τὴν οἰκίαν αὐτοῦ εἰσιέναι τὰς ὄψεις ἠμαυρωμένου διὰ τὸ γῆρας ἐπιφανεὶς ὁ θεὸς ἀμφότερα αὐτῷ μηνύει τήν τε Ἱεροβοάμου γυναῖκα πρὸς αὐτὸν ἀφιγμένην καὶ τί δεῖ περὶ ὧν πάρεστιν ἀποκρίνασθαι. παριούσης δὲ τῆς γυναικὸς εἰς τὴν οἰκίαν ὡς ἰδιώτιδος καὶ ξένης ἀνεβόησεν εἴσελθε, ὦ γύναι Ἱεροβοάμου· τί κρύπτεις σαυτήν; τὸν γὰρ θεὸν οὐ λανθάνεις, ὃς ἀφιξομένην τέ μοι ἐδήλωσε καὶ προσέταξε τίνας ποιήσομαι τοὺς λόγους. ἀπελθοῦσα οὖν πρὸς τὸν ἄνδρα φράζε αὐτῷ ταῦτα λέγειν· ἐπεί σε μέγαν ἐκ μικροῦ καὶ μηδενὸς ὄντος ἐποίησα καὶ ἀποσχίσας τὴν βασιλείαν ἀπὸ τοῦ Δαυίδου γένους σοὶ ταύτην ἔδωκα, σὺ δὲ τούτων ἠμνημόνησας καὶ τὴν ἐμὴν θρησκείαν καταλιπὼν χωνευτοὺς θεοὺς κατασκευάσας ἐκείνους τιμᾷς, οὕτω σε πάλιν καθαιρήσω καὶ πᾶν ἐξολέσω σου τὸ γένος καὶ κυσὶ καὶ ὄρνισι βορὰν ποιήσω γενέσθαι. βασιλεὺς γὰρ ἐξεγείρεθ’ ὑπ’ ἐμοῦ τοῦ λαοῦ παντός, ὃς οὐδένα ὑπολείψει τοῦ Ἱεροβοάμου γένους· μεθέξει δὲ τῆς τιμωρίας καὶ τὸ πλῆθος ἐκπεσὸν τῆς ἀγαθῆς γῆς καὶ διασπαρὲν εἰς τοὺς πέραν Εὐφράτου τόπους, ὅτι τοῖς τοῦ βασιλέως ἀσεβήμασι κατηκολούθησε καὶ τοὺς ὑπ’ αὐτοῦ γενομένους προσκυνεῖ θεοὺς τὴν ἐμὴν θυσίαν ἐγκαταλιπόν. σὺ δέ, ὦ γύναι, ταῦτα ἀπαγγέλλουσα σπεῦδε πρὸς τὸν ἄνδρα. τὸν δὲ υἱὸν καταλήψῃ τεθνηκότα· σοῦ γὰρ εἰσιούσης εἰς τὴν πόλιν ἀπολείψει τὸ ζῆν αὐτόν. ταφήσεται δὲ κλαυθεὶς ὑπὸ τοῦ πλήθους παντὸς κοινῷ τιμηθεὶς πένθει· καὶ γὰρ μόνος τῶν ἐκ τοῦ Ἱεροβοάμου γένους ἀγαθὸς οὗτος ἦν. ταῦτ’ αὐτοῦ προφητεύσαντος ἐκπηδήσασα ἡ γυνὴ τεταραγμένη καὶ τῷ τοῦ προειρημένου παιδὸς θανάτῳ περιαλγής, θρηνοῦσα διὰ τῆς ὁδοῦ καὶ τὴν μέλλουσαν τοῦ τέκνου κοπτομένη τελευτὴν ἀθλία τοῦ πάθους ἠπείγετο κακοῖς ἀμηχάνοις καὶ σπουδῇ μὲν ἀτυχεῖ χρωμένη διὰ τὸν υἱὸν αὐτῆς, ἔμελλε γὰρ αὐτὸν ἐπειχθεῖσα θᾶττον ὄψεσθαι νεκρόν, ἀναγκαίᾳ δὲ διὰ τὸν ἄνδρα. καὶ παραγενομένη τὸν μὲν ἐκπεπνευκότα καθὼς εἶπεν ὁ προφήτης εὗρε, τῷ δὲ βασιλεῖ πάντα ἀπήγγειλεν.", "st": "8.11.1"}, {"sp": "N", "t": "Ἱεροβόαμος δ’ οὐδενὸς τούτων φροντίσας πολλὴν ἀθροίσας στρατιὰν ἐπὶ τὸν Ῥοβοάμου παῖδα τῶν δύο φυλῶν τὴν βασιλείαν τοῦ πατρὸς διαδεξάμενον Ἀβίαν ἐξεστράτευσε πολεμήσων· κατεφρόνει γὰρ αὐτοῦ διὰ τὴν ἡλικίαν. ὁ δὲ ἀκούσας τὴν ἔφοδον τὴν Ἱεροβοάμου πρὸς αὐτὴν οὐ κατεπλάγη, γενόμενος δ’ ἐπάνω καὶ τῆς νεότητος τῷ φρονήματι καὶ τῆς ἐλπίδος τοῦ πολεμίου στρατιὰν ἐπιλέξας ἐκ τῶν δύο φυλῶν ἀπήντησε τῷ Ἱεροβοάμῳ εἰς τόπον τινὰ καλούμενον ὄρος Σαμαρῶν καὶ στρατοπεδευσάμενος ἐγγὺς αὐτοῦ τὰ πρὸς τὴν μάχην εὐτρέπιζεν. ἦν δ’ ἡ δύναμις αὐτοῦ μυριάδες τεσσαράκοντα, ἡ δὲ τοῦ Ἱεροβοάμου στρατιὰ διπλασίων ἐκείνης. ὡς δὲ τὰ στρατεύματα πρὸς τὰ ἔργα καὶ τοὺς κινδύνους ἀντιπαρετάσσετο καὶ συμβαλεῖν ἔμελλε, στὰς ἐφ’ ὑψηλοῦ τινος Ἀβίας τόπου καὶ τῇ χειρὶ κατασείσας τὸ πλῆθος καὶ τὸν Ἱεροβόαμον ἀκοῦσαι πρῶτον αὐτοῦ μεθ’ ἡσυχίας ἠξίωσε. γενομένης δὲ σιωπῆς ἤρξατο λέγειν· ὅτι μὲν τὴν ἡγεμονίαν ὁ θεὸς Δαυίδῃ καὶ τοῖς ἐκγόνοις αὐτοῦ κατένευσεν εἰς ἅπαντα χρόνον, οὐδ’ ὑμεῖς ἀγνοεῖτε, θαυμάζω δέ, πῶς ἀποστάντες τοὐμοῦ πατρὸς τῷ δούλῳ Ἱεροβοάμῳ προσέθεσθε καὶ μετ’ ἐκείνου πάρεστε νῦν ἐπὶ τοὺς ὑπὸ τοῦ θεοῦ βασιλεύειν κεκριμένους πολεμήσοντες καὶ τὴν ἀρχὴν ἀφαιρησόμενοι τὴν ὑπάρχουσαν· τὴν μὲν γὰρ πλείω μέχρι νῦν Ἱεροβόαμος ἀδίκως ἔχει. ἀλλ’ οὐκ οἶμαι καὶ ταύτης αὐτὸν ἀπολαύσειν ἐπὶ πλείονα χρόνον, ἀλλὰ δοὺς καὶ τοῦ παρεληλυθότος δίκην τῷ θεῷ παύσεται τῆς παρανομίας καὶ τῶν ὕβρεων, ἃς οὐ διαλέλοιπεν εἰς αὐτὸν ὑβρίζων καὶ ταὐτὰ ποιεῖν ὑμᾶς ἀναπεπεικώς, οἳ μηδὲν ἀδικηθέντες ὑπὸ τοῦ πατρός, ἀλλ’ ὅτι μὴ πρὸς ἡδονὴν ἐκκλησιάζων ὡμίλησεν ἀνθρώπων πονηρῶν συμβουλίᾳ πεισθείς, ἐγκατελίπετε τῷ δοκεῖν ὑπ’ ὀργῆς ἐκεῖνον, ταῖς δ’ ἀληθείαις αὑτοὺς ἀπὸ τοῦ θεοῦ καὶ τῶν ἐκείνου νόμων ἀπεσπάσατε. καίτοι συνεγνωκέναι καλῶς εἶχεν ὑμᾶς οὐ λόγων μόνον δυσκόλων ἀνδρὶ νέῳ καὶ δημαγωγίας ἀπείρῳ, ἀλλ’ εἰ καὶ πρός τι δυσχερὲς ἡ νεότης αὐτὸν καὶ ἡ ἀμαθία τῶν πραττομένων ἐξῆγεν ἔργον, διά τε Σολόμωνα τὸν πατέρα καὶ τὰς εὐεργεσίας τὰς ἐκείνου· παραίτησιν γὰρ εἶναι δεῖ τῆς τῶν ἐγγόνων ἁμαρτίας τὰς τῶν πατέρων εὐποιίας. ὑμεῖς δ’ οὐδὲν τούτων ἐλογίσασθε οὔτε τότ’ οὔτε νῦν, ἀλλ’ ἧκε στρατὸς ἐφ’ ἡμᾶς τοσοῦτος· τίνι καὶ πεπιστευκὼς περὶ τῆς νίκης; ἦ ταῖς χρυσαῖς δαμάλεσι καὶ τοῖς ἐπὶ τῶν ὀρῶν βωμοῖς, ἃ δείγματα τῆς ἀσεβείας ἐστὶν ὑμῶν ἀλλ’ οὐχὶ τῆς θρησκείας; ἢ τὸ πλῆθος ὑμᾶς εὐέλπιδας ἀπεργάζεται τὴν ἡμετέραν στρατιὰν ὑπερβάλλον; ἀλλ’ οὐδ’ ἥτις ἰσχὺς μυριάδων στρατοῦ μετ’ ἀδικημάτων πολεμοῦντος· ἐν γὰρ μόνῳ τῷ δικαίῳ καὶ πρὸς τὸ θεῖον εὐσεβεῖ τὴν βεβαιοτάτην ἐλπίδα τοῦ κρατεῖν τῶν ἐναντίων ἀποκεῖσθαι συμβέβηκεν, ἥτις ἐστὶ παρ’ ἡμῖν τετηρηκόσιν ἀπ’ ἀρχῆς τὰ νόμιμα καὶ τὸν ἴδιον θεὸν σεβομένοις, ὃν οὐ χεῖρες ἐποίησαν ἐξ ὕλης φθαρτῆς οὐδ’ ἐπίνοια πονηροῦ βασιλέως ἐπὶ τῇ τῶν ὄχλων ἀπάτῃ κατεσκεύασεν, ἀλλ’ ὃς ἔργον ἐστὶν αὑτοῦ καὶ ἀρχὴ καὶ τέλος τῶν ἁπάντων. συμβουλεύω τοιγαροῦν ὑμῖν ἔτι καὶ νῦν μεταγνῶναι καὶ λαβόντας ἀμείνω λογισμὸν παύσασθαι τοῦ πολεμεῖν καὶ τὰ πάτρια καὶ τὸ προαγαγὸν ὑμᾶς ἐπὶ τοσοῦτον μέγεθος εὐδαιμονίας γνωρίσαι.", "st": "8.11.2"}, {"sp": "N", "t": "Ταῦτα μὲν Ἀβίας διελέχθη πρὸς τὸ πλῆθος· ἔτι δὲ αὐτοῦ λέγοντος λάθρα τινὰς τῶν στρατιωτῶν Ἱεροβόαμος ἔπεμψε περικυκλωσομένους τὸν Ἀβίαν ἔκ τινων οὐ φανερῶν τοῦ στρατοπέδου μερῶν. μέσου δ’ αὐτοῦ περιληφθέντος τῶν πολεμίων ἡ μὲν στρατιὰ κατέδεισε καὶ ταῖς ψυχαῖς ἀνέπεσεν, ὁ δ’ Ἀβίας παρεθάρρυνε καὶ τὰς ἐλπίδας ἔχειν ἐν τῷ θεῷ παρεκάλει· τοῦτον γὰρ οὐ κεκυκλῶσθαι πρὸς τῶν πολεμίων. οἱ δὲ ὁμοῦ πάντες ἐπικαλεσάμενοι τὴν παρὰ τοῦ θεοῦ συμμαχίαν τῶν ἱερέων τῇ σάλπιγγι σημανάντων ἀλαλάξαντες ἐχώρησαν ἐπὶ τοὺς πολεμίους· καὶ τῶν μὲν ἔθραυσε τὰ φρονήματα καὶ τὰς ἀκμὰς αὐτῶν ἐξέλυσεν ὁ θεός, τὴν δὲ Ἀβία στρατιὰν ὑπερτέραν ἐποίησεν· ὅσος γὰρ οὐδέποτ’ ἐμνημονεύθη φόνος ἐν πολέμῳ γεγονέναι οὔθ’ Ἑλλήνων οὔτε βαρβάρων, τοσούτους ἀποκτείναντες τῆς Ἱεροβοάμου δυνάμεως θαυμαστὴν καὶ διαβόητον νίκην παρὰ τοῦ θεοῦ λαβεῖν ἠξιώθησαν· πεντήκοντα γὰρ μυριάδας τῶν ἐχθρῶν κατέβαλον καὶ τὰς πόλεις αὐτῶν διήρπασαν τὰς ὀχυρωτάτας ἑλόντες κατὰ κράτος, τήν τε Βηθήλην καὶ τὴν τοπαρχίαν αὐτῆς καὶ τὴν Ἰσανὰν καὶ τὴν τοπαρχίαν αὐτῆς. καὶ Ἱεροβόαμος μὲν οὐκέτι μετὰ ταύτην τὴν ἧτταν ἴσχυσεν ἐφ’ ὅσον Ἀβίας περιῆν χρόνον. τελευτᾷ δ’ οὗτος ὀλίγον τῇ νίκῃ χρόνον ἐπιζήσας ἔτη βασιλεύσας τρία, καὶ θάπτεται μὲν ἐν Ἱεροσολύμοις ἐν ταῖς προγονικαῖς θήκαις, ἀπολείπει δὲ υἱοὺς μὲν δύο καὶ εἴκοσι θυγατέρας δὲ ἓξ καὶ δέκα. πάντας τούτους ἐκ γυναικῶν δεκατεσσάρων ἐτεκνώσατο. διεδέξατο δ’ αὐτοῦ τὴν βασιλείαν ὁ υἱὸς αὐτοῦ Ἄσανος· καὶ ἡ μήτηρ τοῦ νεανίσκου Μαχαία τοὔνομα. τούτου κρατοῦντος εἰρήνης ἀπέλαυεν ἡ χώρα τῶν Ἰσραηλιτῶν ἐπὶ ἔτη δέκα.", "st": "8.11.3"}, {"sp": "N", "t": "Καὶ τὰ μὲν περὶ Ἀβίαν τὸν Ῥοβοάμου τοῦ Σολόμωνος οὕτως παρειλήφαμεν. ἐτελεύτησε δὲ καὶ Ἱεροβόαμος ὁ τῶν δέκα φυλῶν βασιλεὺς ἄρξας ἔτη δύο καὶ εἴκοσι. διαδέχεται δ’ αὐτὸν ὁ παῖς Νάβαδος δευτέρου ἔτους ἤδη τῆς βασιλείας Ἀσάνου διεληλυθότος. ἦρξε δὲ ὁ τοῦ Ἱεροβοάμου παῖς ἔτη δύο τῷ πατρὶ τὴν ἀσέβειαν καὶ τὴν πονηρίαν ἐμφερὴς ὤν. ἐν δὲ τούτοις τοῖς δυσὶν ἔτεσι στρατευσάμενος ἐπὶ Γαβαθῶνα πόλιν Παλαιστίνων οὖσαν πολιορκίᾳ λαβεῖν αὐτὴν προσέμενεν· ἐπιβουλευθεὶς δ’ ἐκεῖ ὑπὸ φίλου τινὸς Βασάνου ὄνομα Σειδοῦ δὲ παιδὸς ἀποθνήσκει, ὃς μετὰ τὴν τελευτὴν αὐτοῦ τὴν βασιλείαν παραλαβὼν ἅπαν τὸ Ἱεροβοάμου γένος διέφθειρε. καὶ συνέβη κατὰ τὴν τοῦ θεοῦ προφητείαν τοὺς μὲν ἐν τῇ πόλει τῶν Ἱεροβοάμου συγγενῶν ἀποθανόντας ὑπὸ κυνῶν σπαραχθῆναι καὶ δαπανηθῆναι, τοὺς δ’ ἐν τοῖς ἀγροῖς ὑπ’ ὀρνίθων. ὁ μὲν οὖν Ἱεροβοάμου οἶκος τῆς ἀσεβείας αὐτοῦ καὶ τῶν ἀνομημάτων ἀξίαν ὑπέσχε δίκην.", "st": "8.11.4"}, {"sp": "N", "t": "Ὁ δὲ τῶν Ἱεροσολύμων βασιλεὺς Ἄσανος ἦν τὸν τρόπον ἄριστος καὶ πρὸς τὸ θεῖον ἀφορῶν καὶ μηδὲν μήτε πράττων μήτ’ ἐννοούμενος, ὃ μὴ πρὸς τὴν εὐσέβειαν εἶχε καὶ τὴν τῶν νομίμων φυλακὴν τὴν ἀναφοράν. κατώρθωσε δὲ τὴν αὑτοῦ βασιλείαν ἐκκόψας εἴ τι πονηρὸν ἦν ἐν αὐτῇ καὶ καθαρεύσας ἁπάσης κηλῖδος. στρατοῦ δ’ εἶχεν ἐπιλέκτων ἀνδρῶν ὡπλισμένων θυρεὸν καὶ σιρομάστην ἐκ μὲν τῆς Ἰούδα φυλῆς μυριάδας τριάκοντα, ἐκ δὲ τῆς Βενιαμίτιδος ἀσπίδας φορούντων καὶ τοξοτῶν μυριάδας πέντε καὶ εἴκοσι. ἤδη δὲ αὐτοῦ δέκα ἔτη βασιλεύοντος στρατεύει μεγάλῃ δυνάμει Ζαραῖος ἐπ’ αὐτὸν ὁ τῆς Αἰθιοπίας βασιλεὺς ἐνενήκοντα μὲν πεζῶν μυριάσιν ἱππέων δὲ δέκα τριακοσίοις δ’ ἅρμασι. καὶ μέχρι πόλεως Μαρήσας, ἔστι δ’ αὕτη τῆς Ἰούδα φυλῆς, ἐλάσαντος αὐτοῦ μετὰ τῆς οἰκείας δυνάμεως ἀπήντησεν Ἄσανος, καὶ ἀντιπαρατάξας αὐτῷ τὴν στρατιὰν ἔν τινι φάραγγι Σαβαθὰ λεγομένῃ τῆς πόλεως οὐκ ἄπωθεν, ὡς κατεῖδε τὸ τῶν Αἰθιόπων πλῆθος ἀναβοήσας νίκην ᾔτει παρὰ τοῦ θεοῦ καὶ τὰς πολλὰς ἑλεῖν μυριάδας τῶν πολεμίων· οὐδὲ γὰρ ἄλλῳ τινὶ θαρσήσας ἔλεγεν ἢ τῇ παρ’ αὐτοῦ βοηθείᾳ δυναμένῃ καὶ τοὺς ὀλίγους ἀπεργάσασθαι κρείττους τῶν πλειόνων καὶ τοὺς ἀσθενεῖς τῶν ὑπερεχόντων ἀπαντῆσαι πρὸς μάχην τῷ Ζαραίῳ.", "st": "8.12.1"}, {"sp": "N", "t": "Ταῦτα λέγοντος Ἀσάνου νίκην ἐσήμαινεν ὁ θεός, καὶ συμβαλὼν μετὰ χαρᾶς τῶν προδεδηλωμένων ὑπὸ τοῦ θεοῦ πολλοὺς ἀποκτείνει τῶν Αἰθιόπων καὶ τραπέντας εἰς φυγὴν ἐδίωξεν ἄχρι τῆς Γεραρίτιδος χώρας. ἀφέμενοι δὲ τῆς ἀναιρέσεως ἐπὶ τὴν διαρπαγὴν τῶν πόλεων, ἥλω γὰρ ἡ Γεράρων, ἐχώρησαν καὶ τῆς παρεμβολῆς αὐτῶν, ὡς πολὺν μὲν ἐκφορῆσαι χρυσὸν πολὺν δὲ ἄργυρον λείαν τε ἀπαγαγεῖν καμήλους τε καὶ ὑποζύγια καὶ βοσκημάτων ἀγέλας. Ἄσανος μὲν οὖν καὶ ἡ παρ’ αὐτῷ στρατιὰ τοιαύτην παρὰ τοῦ θεοῦ νίκην λαβόντες καὶ ὠφέλειαν ἀνέστρεφον εἰς Ἱεροσόλυμα, παραγενομένοις δὲ αὐτοῖς ἀπήντησε κατὰ τὴν ὁδὸν προφήτης Ἀζαρίας ὄνομα. οὗτος ἐπισχεῖν κελεύσας τῆς ὁδοιπορίας ἤρξατο λέγειν πρὸς αὐτούς, ὅτι ταύτης εἶεν τῆς νίκης παρὰ τοῦ θεοῦ τετυχηκότες, ὅτι δικαίους καὶ ὁσίους ἑαυτοὺς παρέσχον καὶ πάντα κατὰ βούλησιν θεοῦ πεποιηκότας. ἐπιμένουσι μὲν οὖν ἔφασκεν ἀεὶ κρατεῖν αὐτοὺς τῶν ἐχθρῶν καὶ τὸ ζῆν μετ’ εὐδαιμονίας παρέξειν τὸν θεόν, ἀπολιποῦσι δὲ τὴν θρησκείαν ἅπαντα τούτων ἐναντία συμβήσεσθαι καὶ γενήσεσθαι χρόνον ἐκεῖνον, ἐν ᾧ μηδεὶς ἀληθὴς εὑρεθήσεται προφήτης ἐν τῷ ὑμετέρῳ ὄχλῳ οὐδὲ ἱερεὺς τὰ δίκαια χρηματίζων, ἀλλὰ καὶ αἱ πόλεις ἀνάστατοι γενήσονται καὶ τὸ ἔθνος κατὰ πάσης σπαρήσεται γῆς ἔπηλυν βίον καὶ ἀλήτην βιωσόμενον. καιρὸν δ’ αὐτοῖς ἔχουσι συνεβούλευεν ἀγαθοῖς γίνεσθαι καὶ μὴ φθονῆσαι τῆς εὐμενείας αὑτοῖς τοῦ θεοῦ. ταῦτ’ ἀκούσας ὁ βασιλεὺς καὶ ὁ λαὸς ἐχάρησαν καὶ πολλὴν πρόνοιαν ἐποιοῦντο κοινῇ τε πάντες καὶ κατ’ ἰδίαν τοῦ δικαίου· διέπεμψε δ’ ὁ βασιλεὺς καὶ τοὺς ἐν τῇ χώρᾳ τῶν νομίμων ἐπιμελησομένους.", "st": "8.12.2"}, {"sp": "N", "t": "Καὶ τὰ μὲν Ἀσάνου τοῦ βασιλέως τῶν δύο φυλῶν ἐν τούτοις ὑπῆρχεν. ἐπάνειμι δ’ ἐπὶ τὸ πλῆθος τῶν Ἰσραηλιτῶν καὶ τὸν βασιλέα αὐτῶν Βασάνην τὸν ἀποκτείναντα τὸν Ἱεροβοάμου υἱὸν Νάβαδον καὶ κατασχόντα τὴν ἀρχήν. οὗτος γὰρ ἐν Θαρσάλῃ πόλει διατρίβων καὶ ταύτην οἰκητήριον πεποιηκὼς εἴκοσι μὲν ἐβασίλευσεν ἔτη καὶ τέσσαρα, πονηρὸς δὲ καὶ ἀσεβὴς ὑπὲρ Ἱεροβόαμον καὶ τὸν υἱὸν αὐτοῦ γενόμενος πολλὰ καὶ τὸ πλῆθος κακὰ διέθηκε καὶ τὸν θεὸν ἐξύβρισεν· ὃς αὐτῷ πέμψας Ἰηοῦν τὸν προφήτην προεῖπε διαφθερεῖν αὐτοῦ πᾶν τὸ γένος καὶ τοῖς αὐτοῖς οἷς καὶ τὸν Ἱεροβοάμου κακοῖς περιέβαλεν οἶκον ἐξολέσειν, ὅτι βασιλεὺς ὑπ’ αὐτοῦ γενόμενος οὐκ ἠμείψατο τὴν εὐεργεσίαν τῷ δικαίως προστῆναι τοῦ πλήθους καὶ εὐσεβῶς, ἅπερ αὐτοῖς πρῶτον τοῖς οὖσι τοιούτοις ἀγαθὰ ἔπειτα τῷ θεῷ φίλα, τὸν δὲ κάκιστον Ἱεροβόαμον ἐμιμήσατο καὶ τῆς ψυχῆς ἀπολομένης τῆς ἐκείνου ζῶσαν αὐτοῦ τὴν πονηρίαν ἐνεδείξατο· πεῖραν οὖν ἕξειν εἰκότως τῆς ὁμοίας συμφορᾶς αὐτὸν ἔλεγεν ὅμοιον αὐτῷ γενόμενον. Βασάνης δὲ προακηκοὼς τὰ μέλλοντα αὐτῷ συμβήσεσθαι κακὰ μεθ’ ὅλης τῆς γενεᾶς ἐπὶ τοῖς τετολμημένοις οὐ πρὸς τὸ λοιπὸν ἡσύχασεν, ἵνα μὴ μᾶλλον πονηρὸς δόξας ἀποθάνῃ καὶ περὶ τῶν παρῳχημένων ἔκτοτε γοῦν μετανοήσας συγγνώμης τύχῃ, ἀλλ’ ὥσπερ οἱ προκειμένων αὐτοῖς ἄθλων ἐπὰν περί τι σπουδάσωσιν οὐ διαλείπουσι περὶ τοῦτο ἐνεργοῦντες, οὕτω καὶ Βασάνης προειρηκότος αὐτῷ τοῦ προφήτου τὰ μέλλοντα ὡς ἐπ’ ἀγαθοῖς τοῖς μεγίστοις κακοῖς ὀλέθρῳ γένους καὶ οἰκίας ἀπωλείᾳ χείρων ἐγένετο, καὶ καθ’ ἑκάστην ἡμέραν ὥσπερ ἀθλητὴς κακίας τοῖς περὶ ταύτην πόνοις προσετίθει. καὶ τελευταῖον τὴν στρατιὰν παραλαβὼν πάλιν ἐπῆλθε πόλει τινὶ τῶν οὐκ ἀφανῶν Ἀρμαθῶνι τοὔνομα σταδίους ἀπεχούσῃ Ἱεροσολύμων τεσσαράκοντα, καὶ καταλαβόμενος αὐτὴν ὠχύρου προδιεγνωκὼς καταλιπεῖν ἐν αὐτῇ δύναμιν, ἵν’ ἐκεῖθεν ὡρμημένοι τὴν Ἀσάνου βασιλείαν κακώσωσι.", "st": "8.12.3"}, {"sp": "N", "t": "Φοβηθεὶς δὲ Ἄσανος τὴν ἐπιχείρησιν τοῦ πολεμίου καὶ λογισάμενος, ὡς πολλὰ διαθήσει κακὰ τὴν ὑπ’ αὐτῷ βασιλευομένην ἅπασαν ὁ καταλειφθεὶς ἐν Ἀρμαθῶνι στρατός, ἔπεμψε πρὸς τὸν Δαμασκηνῶν βασιλέα πρέσβεις καὶ χρυσὸν καὶ ἄργυρον παρακαλῶν συμμαχίαν καὶ ὑπομιμνήσκων, ὅτι καὶ πατρῴα φιλία πρὸς ἀλλήλους ἐστὶν αὐτοῖς. ὁ δὲ τῶν χρημάτων τὸ πλῆθος ἀσμένως ἐδέξατο καὶ συμμαχίαν ἐποιήσατο πρὸς αὐτὸν διαλύσας τὴν πρὸς τὸν Βασάνην φιλίαν, καὶ πέμψας εἰς τὰς ὑπ’ αὐτοῦ βασιλευομένας πόλεις τοὺς ἡγεμόνας τῆς ἰδίας δυνάμεως ἐκέλευσε κακοῦν αὐτάς. οἱ δὲ τὰς μὲν ἐνεπίμπρασαν τὰς δὲ διήρπασαν πορευθέντες, τήν τε Ἰωάνου λεγομένην καὶ Δάνα καὶ Ἀβελάνην καὶ ἄλλας πολλάς. ταῦτ’ ἀκούσας ὁ τῶν Ἰσραηλιτῶν βασιλεὺς τοῦ μὲν οἰκοδομεῖν καὶ ὀχυροῦν τὸν Ἀραμαθῶνα ἐπαύσατο καὶ μετὰ σπουδῆς ὡς βοηθήσων τοῖς οἰκείοις κακουμένοις ἀνέστρεψεν, ὁ δ’ Ἄσανος ἐκ τῆς παρεσκευασμένης ὑπ’ αὐτοῦ πρὸς οἰκοδομίαν ὕλης πόλεις ἀνήγειρεν ἐν αὐτῷ τῷ τόπῳ δύο καρτεράς, ἡ μὲν Γαβαὰ ἐκαλεῖτο, ἡ δὲ Μασταφάς. καὶ μετὰ ταῦτα καιρὸν οὐκ ἔσχεν ὁ Βασάνης τῆς ἐπὶ τὸν Ἄσανον στρατείας· ἐφθάσθη γὰρ ὑπὸ τοῦ χρεὼν καὶ θάπτεται μὲν ἐν Θαρσῇ πόλει, παραλαμβάνει δ’ αὐτοῦ τὴν ἀρχὴν παῖς Ἤλανος. οὗτος ἄρξας ἐπ’ ἔτη δύο τελευτᾷ φονεύσαντος αὐτὸν ἐξ ἐπιβουλῆς Ζαμβρίου τοῦ ἱππάρχου τῆς ἡμισείας τάξεως· κατευωχηθέντα γὰρ αὐτὸν παρὰ τῷ οἰκονόμῳ αὐτοῦ Ὠσᾶ τοὔνομα πείσας ἐπιδραμεῖν τῶν ὑφ’ αὑτὸν ἱππέων τινὰς ἀπέκτεινε δι’ αὐτῶν μεμονωμένον τῶν περὶ αὐτὸν ὁπλιτῶν καὶ ἡγεμόνων· οὗτοι γὰρ ἅπαντες περὶ τὴν πολιορκίαν τῆς Γαβαθώνης ἐγίνοντο τῆς Παλαιστίνων.", "st": "8.12.4"}, {"sp": "N", "t": "Φονεύσας δὲ τὸν Ἤλανον ὁ ἵππαρχος Ζαμβρίας αὐτὸς βασιλεύει καὶ πᾶσαν τὴν Βασάνου γενεὰν κατὰ τὴν Ἰηοῦς προφητείαν διαφθείρει· τῷ γὰρ αὐτῷ τρόπῳ συνέβη τὸν οἶκον αὐτοῦ πρόρριζον ἀπολέσθαι διὰ τὴν ἀσέβειαν, ὡς καὶ τὸν Ἱεροβοάμου διαφθαρέντα γεγράφαμεν. ἡ δὲ πολιορκοῦσα τὴν Γαβαθώνην στρατιὰ πυθομένη τὰ περὶ τὸν βασιλέα καὶ ὅτι Ζαμβρίας ἀποκτείνας αὐτὸν ἔχει τὴν βασιλείαν καὶ αὐτὴ τὸν ἡγούμενον αὐτῆς Ἀμαρῖνον ἀπέδειξε βασιλέα, ὃς ἀπὸ τῆς Γαβαθώνης ἀναστήσας τὸν στρατὸν εἰς Θαρσὴν παραγίνεται τὸ βασίλειον καὶ προσβαλὼν τῇ πόλει κατὰ κράτος αἱρεῖ. Ζαμβρίας δὲ τὴν πόλιν ἰδὼν ἠρημωμένην συνέφυγεν εἰς τὸ μυχαίτατον τῶν βασιλείων καὶ ὑποπρήσας αὐτὸ συγκατέκαυσεν ἑαυτὸν βασιλεύσας ἡμέρας ἑπτά. διέστη δ’ εὐθὺς ὁ τῶν Ἰσραηλιτῶν λαὸς καὶ οἱ μὲν αὐτῶν Θαμαναῖον βασιλεύειν ἤθελον, οἱ δὲ τὸν Ἀμαρῖνον. νικήσαντες δ’ οἱ τοῦτον ἄρχειν ἀξιοῦντες ἀποκτείνουσι τὸν Θαμαναῖον, καὶ παντὸς βασιλεύει ὁ Ἀμαρῖνος τοῦ ὄχλου. τριακοστῷ δὲ ἔτει τῆς Ἀσάνου βασιλείας ἦρξεν ὁ Ἀμαρῖνος ἔτη δώδεκα· τούτων τὰ μὲν ἓξ ἐν Θάρσῳ πόλει, τὰ δὲ λοιπὰ ἐν Σωμαρεῶνι λεγομένῃ πόλει ὑπὸ δὲ Ἑλλήνων Σαμαρείᾳ καλουμένῃ. προσηγόρευσε δ’ αὐτὴν αὐτὸς Σωμαραῖος ἀπὸ τοῦ τὸ ὄρος ἀποδομένου αὐτῷ ἐφ’ ᾧ κατεσκεύασε τὴν πόλιν Σωμάρου. διέφερε δ’ οὐδὲν τῶν πρὸ αὐτοῦ βασιλευσάντων ἢ τῷ χείρων αὐτῶν εἶναι· ἅπαντες γὰρ ἐζήτουν πῶς ἀποστήσουσιν ἀπὸ τοῦ θεοῦ τὸν λαὸν τοῖς καθ’ ἡμέραν ἀσεβήμασι καὶ διὰ τοῦτο δι’ ἀλλήλων αὐτοὺς ὁ θεὸς ἐποίησεν ἐλθεῖν καὶ μηδένα τοῦ γένους ὑπολιπεῖν. ἐτελεύτησε δὲ καὶ οὗτος ἐν Σαμαρείᾳ, διαδέχεται δ’ αὐτὸν ὁ παῖς Ἄχαβος.", "st": "8.12.5"}, {"sp": "N", "t": "Μαθεῖν δ’ ἔστιν ἐκ τούτων, ὅσην τὸ θεῖον ἐπιστροφὴν ἔχει τῶν ἀνθρωπίνων πραγμάτων, καὶ πῶς μὲν ἀγαπᾷ τοὺς ἀγαθούς, μισεῖ δὲ τοὺς πονηροὺς καὶ προρρίζους ἀπόλλυσιν· οἱ μὲν γὰρ τῶν Ἰσραηλιτῶν βασιλεῖς ἄλλος ἐπ’ ἄλλῳ διὰ τὴν παρανομίαν καὶ τὰς ἀδικίας ἐν ὀλίγῳ χρόνῳ πολλοὶ κακῶς διαφθαρέντες ἐγνώσθησαν καὶ τὸ γένος αὐτῶν, ὁ δὲ τῶν Ἱεροσολύμων καὶ τῶν δύο φυλῶν βασιλεὺς Ἄσανος δι’ εὐσέβειαν καὶ δικαιοσύνην εἰς μακρὸν καὶ εὔδαιμον ὑπὸ τοῦ θεοῦ προήχθη γῆρας καὶ τεσσαράκοντα καὶ ἓν ἄρξας ἔτος εὐμοίρως ἀπέθανε. τελευτήσαντος δ’ αὐτοῦ διεδέξατο τὴν ἡγεμονίαν ὁ υἱὸς Ἰωσαφάτης ἐκ γυναικὸς Ἀβιδᾶς τοὔνομα γεγενημένος. τοῦτον μιμητὴν Δαυίδου τοῦ προπάππου κατά τε ἀνδρείαν καὶ εὐσέβειαν ἅπαντες ἐν τοῖς ἔργοις ὑπέλαβον. ἀλλὰ περὶ μὲν τούτου τοῦ βασιλέως οὐ κατεπείγει νῦν λέγειν.", "st": "8.12.6"}, {"sp": "N", "t": "Ὁ δὲ Ἄχαβος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς κατῴκει μὲν ἐν Σαμαρείᾳ, τὴν δ’ ἀρχὴν κατέσχεν ἕως ἐτῶν εἴκοσι καὶ δύο μηδὲν καινίσας τῶν πρὸ αὐτοῦ βασιλέων, εἰ μὴ ὅσα [γε] πρὸς τὸ χεῖρον καθ’ ὑπερβολὴν πονηρίας ἐπενόησεν, ἅπαντα δ’ αὐτῶν τὰ κακουργήματα καὶ τὴν πρὸς τὸ θεῖον ὕβριν ἐκμιμησάμενος καὶ μάλιστα τὴν Ἱεροβοάμου ζηλώσας παρανομίαν· καὶ γὰρ οὗτος δαμάλεις τὰς ὑπ’ ἐκείνου κατασκευασθείσας προσεκύνησε καὶ τούτοις ἄλλα παράδοξα προσεμηχανήσατο. ἔγημε δὲ γυναῖκα θυγατέρα μὲν Εἰθωβάλου τοῦ Τυρίων καὶ Σιδωνίων βασιλέως Ἰεζαβέλην δὲ ὄνομα, ἀφ’ ἧς τοὺς ἰδίους αὐτῆς θεοὺς προσκυνεῖν ἔμαθεν. ἦν δὲ τὸ γύναιον δραστήριόν τε καὶ τολμηρόν, εἰς τοσαύτην δὲ ἀσέλγειαν καὶ μανίαν προύπεσεν, ὥστε καὶ ναὸν τῷ Τυρίων θεῷ ὃν Βελίαν προσαγορεύουσιν ᾠκοδόμησε καὶ ἄλσος παντοίων δένδρων κατεφύτευσε· κατέστησε δὲ [καὶ] ἱερεῖς καὶ ψευδοπροφήτας τούτῳ τῷ θεῷ· καὶ αὐτὸς δ’ ὁ βασιλεὺς πολλοὺς τοιούτους περὶ αὑτὸν εἶχεν ἀνοίᾳ καὶ πονηρίᾳ πάντας ὑπερβεβληκὼς τοὺς πρὸ αὐτοῦ.", "st": "8.13.1"}, {"sp": "N", "t": "Προφήτης δέ τις τοῦ μεγάλου θεοῦ ἐκ πόλεως Θεσσεβώνης τῆς Γαλααδίτιδος χώρας προσελθὼν Ἀχάβῳ προλέγειν αὐτῷ τὸν θεὸν ἔφασκε μήθ’ ὕσειν αὐτὸν ἐν ἐκείνοις τοῖς ἔτεσι μήτε δρόσον καταπέμψειν εἰς τὴν χώραν, εἰ μὴ φανέντος αὐτοῦ. καὶ τούτοις ἐπομόσας ἀνεχώρησεν εἰς τὰ πρὸς νότον μέρη ποιούμενος παρὰ χειμάρρῳ τινὶ τὴν διατριβήν, ἐξ οὗ καὶ τὸ ποτὸν εἶχε· τὴν γὰρ τροφὴν αὐτῷ καθ’ ἡμέραν κόρακες προσέφερον. ἀναξηρανθέντος δὲ τοῦ ποταμοῦ δι’ ἀνομβρίαν εἰς Σαριφθὰν πόλιν οὐκ ἄπωθεν τῆς Σιδῶνος καὶ Τύρου, μεταξὺ γὰρ κεῖται, παραγίνεται τοῦ θεοῦ κελεύσαντος· εὑρήσειν γὰρ ἐκεῖ γυναῖκα χήραν, ἥτις αὐτῷ παρέξει τροφάς. ὢν δ’ οὐ πόρρω τῆς πύλης ὁρᾷ γυναῖκα χερνῆτιν ξυλιζομένην· τοῦ δὲ θεοῦ δηλώσαντος ταύτην εἶναι τὴν μέλλουσαν αὐτὸν διατρέφειν προσελθὼν ἠσπάσατο καὶ κομίσαι ὕδωρ παρεκάλεσεν, ὅπως πίῃ, καὶ πορευομένης μετακαλεσάμενος καὶ ἄρτον ἐνεγκεῖν ἐκέλευσε. τῆς δ’ ὀμοσάσης μηδὲν ἔχειν ἢ μίαν ἀλεύρου δράκα καὶ ὀλίγον ἐλαίου, πορεύεσθαι δὲ συνειλεχυῖαν τὰ ξύλα, ἵνα φυράσασα ποιήσῃ αὑτῇ καὶ τῷ τέκνῳ ἄρτον, μεθ’ ὃν ἀπολεῖσθαι λιμῷ δαπανηθέντα μηκέτι μηδενὸς ὄντος ἔλεγεν, ἀλλὰ θαρσοῦσα, εἶπεν, ἄπιθι καὶ τὰ κρείττω προσδοκῶσα, καὶ ποιήσασα πρῶτον ἐμοὶ βραχὺ κόμισον· προλέγω γάρ σοι μηδέποτ’ ἐπιλείψειν ἀλεύρων ἐκεῖνο τὸ ἄγγος μηδ’ ἐλαίου τὸ κεράμιον, μέχρις οὗ ἂν ὕσῃ ὁ θεός. ταῦτ’ εἰπόντος τοῦ προφήτου παραγενομένη πρὸς αὑτὴν ἐποίησε τὰ εἰρημένα καὶ αὐτή τε ἔσχε καὶ τῷ τέκνῳ χορηγεῖ τὴν διατροφὴν καὶ τῷ προφήτῃ, ἐπέλιπε δ’ οὐδὲν αὐτοὺς τούτων, ἄχρις οὗ καὶ ὁ αὐχμὸς ἐπαύσατο. μέμνηται δὲ τῆς ἀνομβρίας ταύτης καὶ Μένανδρος ἐν ταῖς Ἰθωβάλου τοῦ Τυρίων βασιλέως πράξεσι λέγων οὕτως· ἀβροχία τ’ ἐπ’ αὐτοῦ ἐγένετο ἀπὸ τοῦ Ὑπερβερεταίου μηνὸς ἕως τοῦ ἐχομένου ἔτους Ὑπερβερεταίου, ἱκετείαν δ’ αὐτοῦ ποιησαμένου κεραυνοὺς ἱκανοὺς βεβληκέναι. οὗτος πόλιν Βότρυν ἔκτισε τὴν ἐπὶ Φοινίκῃ καὶ Αὖζαν τὴν ἐν Λιβύῃ. καὶ ταῦτα μὲν δηλῶν τὴν ἐπ’ Ἀχάβου γενομένην ἀνομβρίαν, κατὰ γὰρ τοῦτον καὶ Ἰθώβαλος ἐβασίλευε Τυρίων, ὁ Μένανδρος ἀναγέγραφεν.", "st": "8.13.2"}, {"sp": "N", "t": "Ἡ δὲ γυνὴ περὶ ἧς πρὸ τούτων εἴπομεν, ἡ τὸν προφήτην διατρέφουσα, τοῦ παιδὸς αὐτῇ καταπεσόντος εἰς νόσον, ὡς καὶ τὴν ψυχὴν ἀφεῖναι καὶ δόξαι νεκρόν, ἀνακλαιομένη καὶ ταῖς τε χερσὶν αὑτὴν αἰκιζομένη καὶ φωνὰς οἵας ὑπηγόρευε τὸ πάθος ἀφιεῖσα κατῃτιᾶτο τῆς παρ’ αὐτῇ παρουσίας τὸν προφήτην ὡς ἐλέγξαντα τὰς ἁμαρτίας αὐτῆς καὶ διὰ τοῦτο τοῦ παιδὸς τετελευτηκότος. ὁ δὲ παρεκελεύετο θαρρεῖν καὶ παραδοῦναι τὸν υἱὸν αὐτῷ· ζῶντα γὰρ αὐτὸν ἀποδώσειν. παραδούσης οὖν βαστάσας εἰς τὸ δωμάτιον, ἐν ᾧ διέτριβεν αὐτός, καὶ καταθεὶς ἐπὶ τῆς κλίνης ἀνεβόησε πρὸς τὸν θεὸν οὐ καλῶς ἀμείψασθαι τὴν ὑποδεξαμένην καὶ θρέψασαν τὸν υἱὸν αὐτῆς ἀφαιρησόμενον, ἐδεῖτό τε τὴν ψυχὴν εἰσπέμψαι πάλιν τῷ παιδὶ καὶ παρασχεῖν αὐτῷ τὸν βίον. τοῦ δὲ θεοῦ κατοικτείραντος μὲν τὴν μητέρα, βουληθέντος δὲ καὶ τῷ προφήτῃ χαρίσασθαι τὸ μὴ δόξαι πρὸς αὐτὴν ἐπὶ κακῷ παρεῖναι, παρὰ πᾶσαν τὴν προσδοκίαν ἀνεβίωσεν. ἡ δ’ εὐχαρίστει τῷ προφήτῃ καὶ τότε σαφῶς ἔλεγε μεμαθηκέναι, ὅτι τὸ θεῖον αὐτῷ διαλέγεται.", "st": "8.13.3"}, {"sp": "N", "t": "Χρόνου δ’ ὀλίγου διελθόντος παραγίνεται πρὸς Ἄχαβον τὸν βασιλέα κατὰ βούλησιν τοῦ θεοῦ δηλώσων αὐτῷ τὸν γενησόμενον ὑετόν. λιμὸς δὲ τότε κατεῖχε τὴν χώραν ἅπασαν καὶ πολλὴ τῶν ἀναγκαίων ἀπορία, ὡς μὴ μόνον ἀνθρώπους αὐτῶν σπανίζειν, ἀλλὰ καὶ τὴν γῆν μηδ’ ὅσα τοῖς ἵπποις καὶ τοῖς ἄλλοις κτήνεσι πρὸς νομήν ἐστι χρήσιμα διὰ τὴν ἀνομβρίαν ἀναδιδόναι. τὸν οὖν ἐπιμελόμενον αὐτοῦ τῶν κτημάτων ὁ βασιλεὺς καλέσας Ὠβεδίαν ἀπιέναι βούλεσθαι πρὸς αὐτὸν εἶπεν ἐπὶ τὰς πηγὰς τῶν ὑδάτων καὶ τοὺς χειμάρρους, ἵν’ εἴ που παρ’ αὐτοῖς εὑρεθείη πόα ταύτην εἰς τροφὴν ἀμησάμενοι τοῖς κτήνεσιν ἔχωσι. καὶ περιπέμψαντα κατὰ πᾶσαν τὴν οἰκουμένην τοὺς ζητήσοντας τὸν προφήτην Ἠλίαν οὐχ εὑρηκέναι· συνέπεσθαι δ’ ἐκέλευσε κἀκεῖνον αὐτῷ. δόξαν οὖν ἐξορμᾶν αὐτοῖς μερισάμενοι τὰς ὁδοὺς ὅ τε Ὠβεδίας καὶ ὁ βασιλεὺς ἀπῄεσαν ἕτερος ἑτέραν τῶν ὁδῶν. συνεβεβήκει δὲ καθ’ ὃν Ἰεζαβέλη ἡ βασίλισσα καιρὸν τοὺς προφήτας ἀπέκτεινε τοῦτον ἑκατὸν ἐν τοῖς ὑπὸ Γάρις σπηλαίοις κρύψαι προφήτας καὶ τρέφειν αὐτοὺς ἄρτον χορηγοῦντα μόνον καὶ ὕδωρ. μονωθέντι δ’ ἀπὸ τοῦ βασιλέως Ὠβεδίᾳ συνήντησεν ὁ προφήτης Ἠλίας· καὶ πυθόμενος παρ’ αὐτοῦ τίς εἴη καὶ μαθὼν προσεκύνησεν αὐτόν· ὁ δὲ πρὸς τὸν βασιλέα βαδίζειν ἐκέλευσε καὶ λέγειν, ὅτι παρείη πρὸς αὐτόν. ὁ δὲ τί κακὸν ὑπ’ αὐτοῦ πεπονθότα πρὸς τὸν ἀποκτεῖναι ζητοῦντα καὶ πᾶσαν ἐρευνήσαντα γῆν πέμπειν αὐτὸν ἔλεγεν· ἢ τοῦτ’ ἀγνοεῖν αὐτόν, ὅτι μηδένα τόπον κατέλιπεν, εἰς ὃν οὐκ ἀπέστειλε τοὺς ἀνάξοντας εἰ λάβοιεν ἐπὶ θανάτῳ; καὶ γὰρ εὐλαβεῖσθαι πρὸς αὐτὸν ἔφασκε, μὴ τοῦ θεοῦ φανέντος αὐτῷ πάλιν εἰς ἄλλον ἀπέλθῃ τόπον, εἶτα διαμαρτὼν αὐτοῦ πέμψαντος τοῦ βασιλέως μὴ δυνάμενος εὑρεῖν ὅπου ποτ’ εἴη γῆς ἀποθάνῃ. προνοεῖν οὖν αὐτοῦ τῆς σωτηρίας παρακαλεῖ τὴν περὶ τοὺς ὁμοτέχνους αὐτοῦ σπουδὴν λέγων, ὅτι σώσειεν ἑκατὸν προφήτας Ἱεζαβέλης πάντας τοὺς ἄλλους ἀνῃρηκυίας καὶ ἔχοι κεκρυμμένους αὐτοὺς καὶ τρεφομένους ὑπ’ αὐτοῦ. ὁ δὲ μηδὲν δεδιότα βαδίζειν ἐκέλευε πρὸς τὸν βασιλέα δοὺς αὐτῷ πίστεις ἐνόρκους, ὅτι πάντως κατ’ ἐκείνην Ἀχάβῳ φανήσεται τὴν ἡμέραν.", "st": "8.13.4"}, {"sp": "N", "t": "Μηνύσαντος δὲ τῷ βασιλεῖ Ὠβεδίου τὸν Ἠλίαν ὑπήντησεν ὁ Ἄχαβος καὶ ἤρετο μετ’ ὀργῆς, εἰ αὐτὸς εἴη ὁ τὸν Ἑβραίων λαὸν κακώσας καὶ τῆς ἀκαρπίας αἴτιος γεγενημένος. ὁ δ’ οὐδὲν ὑποθωπεύσας αὐτὸν εἶπεν ἅπαντα τὰ δεινὰ πεποιηκέναι καὶ τὸ γένος αὐτοῦ ξενικοὺς ἐπεισενηνοχότας τῇ χώρᾳ θεοὺς καὶ τούτους σέβοντας, τὸν δ’ ἴδιον αὐτῶν, ὃς μόνος ἐστὶ θεός, ἀπολελοιπότας καὶ μηδεμίαν ἔτι πρόνοιαν αὐτοῦ ποιουμένους. νῦν μέντοι γε ἀνελθόντα ἐκέλευε πάντα τὸν λαὸν εἰς τὸ Καρμήλιον ὄρος ἀθροῖσαι πρὸς αὐτὸν καὶ τοὺς προφήτας αὐτοῦ καὶ τῆς γυναικός, εἰπὼν ὅσοι τὸν ἀριθμὸν εἴησαν, καὶ τοὺς τῶν ἀλσῶν προφήτας ὡς τετρακοσίους τὸ πλῆθος ὄντας. ὡς δὲ συνέδραμον πάντες εἰς τὸ προειρημένον ὄρος Ἀχάβου διαπέμψαντος, σταθεὶς αὐτῶν ὁ προφήτης Ἠλίας μεταξύ, μέχρι πότε διῃρημένους αὐτοὺς τῇ διανοίᾳ καὶ ταῖς δόξαις οὕτως βιώσειν ἔφασκε· νομίσαντας μὲν γὰρ τὸν ἐγχώριον θεὸν ἀληθῆ καὶ μόνον ἕπεσθαι τούτῳ καὶ ταῖς ἐντολαῖς αὐτοῦ παρῄνει, μηδὲν δὲ τοῦτον ἡγουμένους ἀλλὰ περὶ τῶν ξενικῶν ὑπειληφότας ὡς ἐκείνους δεῖ θρησκεύειν αὐτοῖς συνεβούλευε κατακολουθεῖν. τοῦ δὲ πλήθους μηδὲν πρὸς ταῦτ’ ἀποκριναμένου ἠξίωσεν Ἠλίας πρὸς διάπειραν τῆς τε τῶν ξενικῶν θεῶν ἰσχύος καὶ τῆς τοῦ ἰδίου, μόνος ὢν αὐτοῦ προφήτης ἐκείνων δὲ τετρακοσίους ἐχόντων, λαβεῖν αὐτός τε βοῦν καὶ ταύτην θύσας ἐπιθεῖναι ξύλοις πυρὸς οὐχ ὑπαφθέντος, κἀκείνους ταὐτὸ ποιήσαντας ἐπικαλέσασθαι τοὺς ἰδίους θεοὺς ἀνακαῦσαι τὰ ξύλα· γενομένου γὰρ τούτου μαθήσεσθαι αὐτοὺς τὴν ἀληθῆ φύσιν τοῦ θεοῦ. ἀρεσάσης δὲ τῆς γνώμης ἐκέλευσεν Ἠλίας τοὺς προφήτας ἐκλεξαμένους βοῦν πρώτους θῦσαι καὶ τοὺς αὑτῶν ἐπικαλέσασθαι θεούς. ἐπεὶ δ’ οὐδὲν ἀπήντα παρὰ τῆς εὐχῆς καὶ τῆς ἐπικλήσεως θύσασι τοῖς προφήταις, σκώπτων ὁ Ἠλίας μεγάλῃ βοῇ καλεῖν αὐτοὺς ἐκέλευε τοὺς θεούς· ἢ γὰρ ἀποδημεῖν αὐτοὺς ἢ καθεύδειν. τῶν δ’ ἀπ’ ὄρθρου τοῦτο ποιούντων μέχρι μέσης ἡμέρας καὶ τεμνόντων αὑτοὺς μαχαίραις καὶ σιρομάσταις κατὰ τὸ πάτριον ἔθος, μέλλων αὐτὸς ἐπιτελεῖν ἐκέλευσε τοὺς μὲν ἀναχωρῆσαι, τοὺς δ’ ἐγγὺς προσελθόντας τηρεῖν αὐτόν, μὴ πῦρ λάθρα τοῖς ξύλοις ἐμβάλῃ. τοῦ δὲ ὄχλου προσελθόντος λαβὼν δώδεκα λίθους κατὰ φυλὴν τοῦ λαοῦ τῶν Ἑβραίων ἀνέστησεν ἐξ αὐτῶν θυσιαστήριον καὶ περὶ αὐτὸ δεξαμενὴν ὤρυξε βαθυτάτην, καὶ συνθεὶς τὰς σχίζας ἐπὶ τοῦ βωμοῦ καὶ κατ’ αὐτῶν ἐπιθεὶς τὰ ἱερεῖα τέσσαρας ἀπὸ τῆς κρήνης ἐκέλευσεν ὑδρίας ὕδατος κατασκεδάσαι τοῦ θυσιαστηρίου, ὡς ὑπερβαλεῖν αὐτὸ καὶ τὴν δεξαμενὴν ἅπασαν γεμισθῆναι ὕδατος πηγῆς ἀναδοθείσης. ταῦτα δὲ ποιήσας ἤρξατο εὔχεσθαι τῷ θεῷ καὶ καλεῖν αὐτὸν καὶ ποιεῖν τῷ πεπλανημένῳ πολὺν ἤδη χρόνον λαῷ φανερὰν τὴν αὑτοῦ δύναμιν. καὶ ταῦτα λέγοντος ἄφνω πῦρ ἐξ οὐρανοῦ τοῦ πλήθους ὁρῶντος ἐπὶ τὸν βωμὸν ἔπεσε καὶ τὴν θυσίαν ἐδαπάνησεν, ὡς ἀνακαῆναι καὶ τὸ ὕδωρ καὶ ψαφαρὸν γενέσθαι τὸν τόπον.", "st": "8.13.5"}, {"sp": "N", "t": "Οἱ δ’ Ἰσραηλῖται τοῦτ’ ἰδόντες ἔπεσον ἐπὶ τῆς γῆς καὶ προσεκύνουν ἕνα θεὸν καὶ μέγιστον καὶ ἀληθῆ μόνον ἀποκαλοῦντες, τοὺς δ’ ἄλλους ὀνόματι ὑπὸ φαύλης καὶ ἀνοήτου δόξης πεποιημένους· συλλαβόντες δ’ αὐτῶν καὶ τοὺς προφήτας ἀπέκτειναν Ἠλία παραινέσαντος. ἔφη δὲ καὶ τῷ βασιλεῖ πορεύεσθαι πρὸς ἄριστον μηδὲν ἔτι φροντίσαντα· μετ’ ὀλίγον γὰρ ὄψεσθαι τὸν θεὸν ὕοντα. καὶ ὁ μὲν Ἄχαβος ἀπηλλάγη, Ἠλίας δ’ ἐπὶ τὸ ἀκρωτήριον τοῦ Καρμηλίου ἀναβὰς ὄρους καὶ καθίσας ἐπὶ τῆς γῆς προσηρείσατο τοῖς γόνασι τὴν κεφαλήν, τὸν δὲ θεράποντα ἐκέλευσεν ἀνελθόντα ἐπί τινα σκοπὴν εἰς τὴν θάλασσαν ἀποβλέπειν, κἂν ἴδῃ νεφέλην ἐγειρομένην ποθέν, φράζειν αὐτῷ· μέχρι γὰρ τότε καθαρῷ συνέβαινε τῷ ἀέρι εἶναι. τοῦ δὲ ἀναβάντος καὶ μηδὲν πολλάκις ὁρᾶν φήσαντος, ἕβδομον ἤδη βαδίσας ἑωρακέναι μελαινόμενον εἶπέ τι τοῦ ἀέρος οὐ πλέον ἴχνους ἀνθρωπίνου. ὁ δὲ Ἠλίας ταῦτ’ ἀκούσας πέμπει πρὸς τὸν Ἄχαβον κελεύων αὐτὸν εἰς τὴν πόλιν ἀπέρχεσθαι πρὶν ἢ καταρραγῆναι τὸν ὄμβρον. καὶ ὁ μὲν εἰς Ἱερέζηλα πόλιν παραγίνεται· μετ’ οὐ πολὺ δὲ τοῦ ἀέρος ἀχλύσαντος καὶ νέφεσι καλυφθέντος πνεῦμά τε λάβρον ἐπιγίνεται καὶ πολὺς ὄμβρος. ὁ δὲ προφήτης ἔνθεος γενόμενος τῷ τοῦ βασιλέως ἅρματι μέχρι τῆς Ἱερέζηλας πόλεως συνέδραμε.", "st": "8.13.6"}, {"sp": "N", "t": "Μαθοῦσα δὲ ἡ τοῦ Ἀχάβου γυνὴ Ἰεζάβηλα τά τε σημεῖα τὰ ὑπὸ Ἠλία γενόμενα καὶ ὅτι τοὺς προφήτας αὐτῶν ἀπέκτεινεν, ὀργισθεῖσα πέμπει πρὸς αὐτὸν ἀγγέλους ἀπειλοῦσα δι’ αὐτῶν ἀποκτείνειν αὐτόν, ὡς κἀκεῖνος τοὺς προφήτας αὐτῆς ἀπολέσειε. φοβηθεὶς δ’ ὁ Ἠλίας φεύγει εἰς πόλιν Βερσουβεὲ λεγομένην, ἐπ’ ἐσχάτης δ’ ἔστιν αὕτη τῆς χώρας τῶν τῆς Ἰούδα φυλῆς ἐχόντων κατὰ τὴν Ἰδουμαίων γῆν, καταλιπὼν δ’ ἐκεῖ τὸν θεράποντα εἰς τὴν ἔρημον ἀνεχώρησεν εὐξάμενος ἀποθανεῖν· οὐ γὰρ δὴ κρείττων εἶναι τῶν πατέρων, ἵνα ἐκείνων ἀπολωλότων αὐτὸς ζῆν γλίχηται· κατακοιμηθεὶς δὲ πρός τινι δένδρῳ διεγείραντος αὐτόν τινος ἀναστὰς εὑρίσκει παρακειμένην αὑτῷ τροφὴν καὶ ὕδωρ· φαγὼν δὲ καὶ συλλεξάμενος ἐκ τῆς τροφῆς ἐκείνης τὴν δύναμιν εἰς τὸ Σιναῖον καλούμενον ὄρος παραγίνεται, οὗ Μωυσῆς τοὺς νόμους παρὰ τοῦ θεοῦ λέγεται λαβεῖν. εὑρὼν δ’ ἐν αὐτῷ σπήλαιόν τι κοῖλον εἴσεισι καὶ διετέλει ποιούμενος ἐν αὐτῷ τὴν μονήν. ἐρομένης δέ τινος αὐτὸν φωνῆς ἐξ ἀδήλου, τί παρείη καταλελοιπὼς τὴν πόλιν ἐκεῖσε, διὰ τὸ κτεῖναι μὲν τοὺς προφήτας τῶν ξενικῶν θεῶν, πεῖσαι δὲ τὸν λαὸν ὅτι μόνος εἴη θεὸς ὁ ὤν, ὃν ἀπ’ ἀρχῆς ἐθρήσκευσαν, ἔφησε· ζητεῖσθαι γὰρ ἐπὶ τούτῳ πρὸς τιμωρίαν ὑπὸ τῆς γυναικὸς τοῦ βασιλέως. πάλιν δὲ ἀκούσας προελθεῖν εἰς τὸ ὕπαιθρον τῇ ἐπιούσῃ, γνώσεσθαι γὰρ οὕτως τί δεῖ ποιεῖν, προῆλθεν ἐκ τοῦ σπηλαίου μεθ’ ἡμέραν καὶ σεισμοῦ τε ἐπακούει καὶ λαμπρὰν πυρὸς αὐγὴν ὁρᾷ. καὶ γενομένης ἡσυχίας φωνὴ θεία μὴ ταράττεσθαι τοῖς γινομένοις αὐτὸν παρακελεύεται, κρατήσειν γὰρ οὐδένα τῶν ἐχθρῶν αὐτοῦ, προσέταξέ τε ὑποστρέψαντα εἰς τὴν οἰκείαν ἀποδεῖξαι τοῦ πλήθους βασιλέα Ἰηοῦν τὸν Νεμεσαίου παῖδα, ἐκ Δαμασκοῦ δὲ τῶν Σύρων Ἀζάηλον· ἀντ’ αὐτοῦ δὲ προφήτην Ἐλισσαῖον ὑπ’ αὐτοῦ γενήσεσθαι ἐκ πόλεως Ἀβέλας· διαφθερεῖ δὲ τοῦ ἀσεβοῦς ὄχλου τοὺς μὲν Ἀζάηλος τοὺς δὲ Ἰηοῦς. ὁ δ’ Ἠλίας ὑποστρέφει ταῦτ’ ἀκούσας εἰς τὴν Ἑβραίων χώραν καὶ τὸν Σαφάτου παῖδα Ἐλισσαῖον καταλαβὼν ἀροῦντα καὶ μετ’ αὐτοῦ τινας ἄλλους ἐλαύνοντας ζεύγη δώδεκα προσελθὼν ἐπέρριψεν αὐτῷ τὸ ἴδιον ἱμάτιον. ὁ δ’ Ἐλισσαῖος εὐθέως προφητεύειν ἤρξατο καὶ καταλιπὼν τοὺς βόας ἠκολούθησεν Ἠλίᾳ. δεηθεὶς δὲ συγχωρῆσαι αὐτῷ τοὺς γονεῖς ἀσπάσασθαι κελεύοντος τοῦτο ποιεῖν ἀποταξάμενος αὐτοῖς εἵπετο καὶ ἦν Ἠλίου τὸν ἅπαντα χρόνον τοῦ ζῆν καὶ μαθητὴς καὶ διάκονος. καὶ τὰ μὲν περὶ τοῦ προφήτου τούτου τοιαῦτα ἦν.", "st": "8.13.7"}, {"sp": "N", "t": "Ναβώθης δέ τις ἐξ Ἱεζαρήλου πόλεως ἀγρογείτων ὢν τοῦ βασιλέως παρακαλοῦντος αὐτὸν ἀποδόσθαι τιμῆς ὅσης βούλεται τὸν πλησίον αὐτοῦ τῶν ἰδίων ἀγρόν, ἵνα συνάψας ἓν αὐτὸ ποιήσῃ κτῆμα, εἰ δὲ μὴ βούλοιτο χρήματα λαβεῖν ἐπιτρέποντος ἐκλέξασθαι τῶν ἀγρῶν τινα τῶν ἐκείνου, τοῦτο μὲν οὔ φησι ποιήσειν, αὐτὸς δὲ τὴν ἰδίαν καρπώσεσθαι γῆν, ἣν ἐκληρονόμησε τοῦ πατρός. λυπηθεὶς δ’ ὡς ἐφ’ ὕβρει τῷ μὴ τἀλλότρια λαβεῖν ὁ βασιλεὺς οὔτε λουτρὸν προσηνέγκατο οὔτε τροφήν, τῆς δ’ Ἰεζαβέλης τῆς γυναικὸς αὐτοῦ πυνθανομένης, ὅ τι λυπεῖται καὶ μήτε λούεται μήτε ἄριστον αὑτῷ παρατίθεται μήτε δεῖπνον, διηγήσατο αὐτῇ τὴν Ναβώθου σκαιότητα καὶ ὡς χρησάμενος ἐπιεικέσι πρὸς αὐτὸν λόγοις καὶ βασιλικῆς ἐξουσίας ὑποδεεστέροις ὑβρισθείη μὴ τυχὼν ὧν ἠξίου. ἡ δὲ μὴ μικροψυχεῖν ἐπὶ τούτοις παρεκάλει, παυσάμενον δὲ τῆς λύπης ἐπὶ τὴν συνήθη τρέπεσθαι τοῦ σώματος πρόνοιαν· μελήσειν γὰρ αὐτῇ περὶ τῆς Ναβώθου τιμωρίας. καὶ παραχρῆμα πέμπει γράμματα πρὸς τοὺς ὑπερέχοντας τῶν Ἰσραηλιτῶν ἐκ τοῦ Ἀχάβου ὀνόματος νηστεῦσαί τε κελεύουσα καὶ ποιησαμένους ἐκκλησίαν προκαθίσαι μὲν αὐτῶν Νάβωθον, εἶναι γὰρ αὐτὸν γένους ἐπιφανοῦς, παρασκευασαμένους δὲ τρεῖς τολμηρούς τινας τοὺς καταμαρτυρήσοντας αὐτοῦ, ὡς τὸν θεόν τε εἴη βλασφημήσας καὶ τὸν βασιλέα, καταλεῦσαι καὶ τούτῳ διαχρήσασθαι τῷ τρόπῳ. καὶ Νάβωθος μέν, ὡς ἔγραψεν ἡ βασίλισσα, οὕτως καταμαρτυρηθεὶς βλασφημῆσαι τὸν θεόν τε καὶ Ἄχαβον βαλλόμενος ὑπὸ τοῦ πλήθους ἀπέθανεν, ἀκούσασα δὲ ταῦτα Ἰεζάβηλα εἴσεισι πρὸς τὸν βασιλέα καὶ κληρονομεῖν τὸν Ναβώθου ἀμπελῶνα προῖκα ἐκέλευσεν. ὁ δὲ Ἄχαβος ἥσθη τοῖς γεγενημένοις καὶ ἀναπηδήσας ἀπὸ τῆς κλίνης ὀψόμενος ἧκε τὸν ἀμπελῶνα τὸν Ναβώθου. ἀγανακτήσας δ’ ὁ θεὸς πέμπει τὸν προφήτην Ἠλίαν εἰς τὸ Ναβώθου χωρίον Ἀχάβῳ συμβαλοῦντα καὶ περὶ τῶν πεπραγμένων ἐρησόμενον, ὅτι κτείνας τὸν ἀληθῆ δεσπότην τοῦ χωρίου κληρονομήσειεν αὐτὸς ἀδίκως. ὡς δ’ ἧκε πρὸς αὐτὸν εἰπόντος τοῦ βασιλέως, ὅ τι βούλεται χρήσασθαι αὐτῷ, αἰσχρὸν γὰρ ὄντα ἐπὶ ἁμαρτήματι ληφθῆναι ὑπ’ αὐτοῦ, κατ’ ἐκεῖνον ἔφη τὸν τόπον, ἐν ᾧ τὸν Ναβώθου νεκρὸν ὑπὸ κυνῶν δαπανηθῆναι συνέβη, τό τε αὐτοῦ καὶ τὸ τῆς γυναικὸς χυθήσεσθαι αἷμα καὶ πᾶν αὐτοῦ τὸ γένος ἀπολεῖσθαι τοιαῦτα ἀσεβῆσαι τετολμηκότος καὶ παρὰ τοὺς πατρίους νόμους πολίτην ἀδίκως ἀνῃρηκότος. Ἀχάβῳ δὲ λύπη τῶν πεπραγμένων εἰσῆλθε καὶ μετάμελος, καὶ σακκίον ἐνδυσάμενος γυμνοῖς τοῖς ποσὶ διῆγεν οὐχ ἁπτόμενος τροφῆς ἀνθομολογούμενός τε τὰ ἡμαρτημένα καὶ τὸν θεὸν οὕτως ἐξευμενίζων. ὁ δὲ ζῶντος μὲν αὐτοῦ πρὸς τὸν προφήτην ὑπερβαλεῖσθαι τὴν τοῦ γένους τιμωρίαν εἶπεν ἐφ’ οἷς ἐπὶ τοῖς τετολμημένοις μετανοεῖ, τελέσειν δὲ τὴν ἀπειλὴν ἐπὶ τῷ υἱῷ Ἀχάβου. καὶ ὁ μὲν προφήτης ταῦτ’ ἐδήλωσε τῷ βασιλεῖ.", "st": "8.13.8"}, {"sp": "N", "t": "Τῶν δὲ περὶ τὸν Ἄχαβον ὄντων τοιούτων κατὰ τὸν αὐτὸν καιρὸν ὁ τοῦ Ἀδάδου βασιλεύων τῶν Σύρων καὶ Δαμασκοῦ δύναμιν ἐξ ἁπάσης τῆς χώρας συναγαγὼν καὶ συμμάχους τοὺς πέραν Εὐφράτου βασιλέας ποιησάμενος τριάκοντα καὶ δύο ἐστράτευσεν ἐπὶ τὸν Ἄχαβον. ὁ δ’ οὐκ ὢν ὅμοιος αὐτῷ τῇ στρατιᾷ πρὸς μάχην μὲν οὐ παρετάξατο, πάντα δ’ εἰς τὰς ὀχυρωτάτας πόλεις ἐγκλείσας τὰ ἐν τῇ χώρᾳ αὐτὸς μὲν ἔμεινεν ἐν Σαμαρείᾳ· τείχη γὰρ αὕτη λίαν ἰσχυρὰ περιεβέβλητο καὶ τὰ ἄλλα δυσάλωτος ἐδόκει· ὁ δὲ Σύρος ἀναλαβὼν τὴν δύναμιν ἧκεν ἐπὶ τὴν Σαμάρειαν καὶ περικαθίσας αὐτῇ τὸν στρατὸν ἐπολιόρκει. πέμψας δὲ κήρυκα πρὸς Ἄχαβον ἠξίου πρεσβευτὰς δέξασθαι παρ’ αὐτοῦ, δι’ ὧν αὐτῷ δηλώσει τί βούλεται. τοῦ δὲ τῶν Ἰσραηλιτῶν βασιλέως πέμπειν ἐπιτρέψαντος ἐλθόντες οἱ πρέσβεις ἔλεγον κατ’ ἐντολὴν τοῦ βασιλέως τὸν Ἀχάβου πλοῦτον καὶ τὰ τέκνα αὐτοῦ καὶ τὰς γυναῖκας Ἀδάδου τυγχάνειν· ἂν δ’ ὁμολογήσῃ καὶ λαβεῖν αὐτὸν τούτων ὅσα βούλεται συγχωρήσῃ, τὴν στρατιὰν ἀπάξει καὶ παύσεται πολιορκῶν αὐτόν. ὁ δ’ Ἄχαβος τοῖς πρέσβεσιν ἐκέλευσε πορευθεῖσι λέγειν τῷ βασιλεῖ αὐτῶν, ὅτι καὶ αὐτὸς καὶ οἱ ἑκείνου πάντες κτήματά εἰσιν αὐτοῦ. ταῦτα δ’ ἀπαγγειλάντων πέμπει πάλιν πρὸς αὐτὸν ἀξιῶν ἀνωμολογηκότα πάντα εἶναι ἐκείνου δέξασθαι τοὺς πεμφθησομένους εἰς τὴν ἐπιοῦσαν ὑπ’ αὐτοῦ δούλους, οἷς ἐρευνήσασι τά τε βασίλεια καὶ τοὺς τῶν φίλων καὶ συγγενῶν οἴκους ἐκέλευε διδόναι πᾶν ὅ τι ἂν ἐν αὐτοῖς εὕρωσι κάλλιστον, τὰ δ’ ἀπαρέσαντα σοὶ καταλείψουσιν. Ἄχαβος δ’ ἀγασθεὶς ἐπὶ τῇ δευτέρᾳ πρεσβείᾳ τοῦ τῶν Σύρων βασιλέως συναγαγὼν εἰς ἐκκλησίαν τὸ πλῆθος ἔλεγεν, ὡς αὐτὸς μὲν ἑτοίμως εἶχεν ὑπὲρ σωτηρίας αὐτοῦ καὶ εἰρήνης καὶ γυναῖκας τὰς ἰδίας προέσθαι τῷ πολεμίῳ καὶ τὰ τέκνα καὶ πάσης παραχωρῆσαι κτήσεως· ταῦτα γὰρ ἐπιζητῶν ἐπρεσβεύσατο πρῶτον ὁ Σύρος. νῦν δ’ ἠξίωκε δούλους πέμψαι τάς τε πάντων οἰκίας ἐρευνῆσαι καὶ μηδὲν ἐν αὐταῖς καταλιπεῖν τῶν καλλίστων κτημάτων πρόφασιν βουλόμενος πολέμου λαβεῖν, εἰδὼς ὅτι τῶν μὲν ἐμαυτοῦ δι’ ὑμᾶς οὐκ ἂν φεισαίμην, ἀφορμὴν δ’ ἐκ τοῦ περὶ τῶν ὑμετέρων ἀηδοῦς πραγματευόμενος εἰς τὸ πολεμεῖν· ποιήσω γε μὴν τὰ ὑμῖν δοκοῦντα. τὸ δὲ πλῆθος μὴ δεῖν ἀκούειν τῶν κατ’ αὐτὸν ἔλεγεν, ἀλλὰ καταφρονεῖν καὶ πρὸς τὸ πολεμεῖν ἑτοίμως ἔχειν. τοῖς οὖν πρεσβευταῖς ἀποκρινάμενος λέγειν ἀπελθοῦσιν, ὅτι τοῖς τὸ πρῶτον ἀξιωθεῖσιν ὑπ’ αὐτοῦ καὶ νῦν ἐμμένει τῆς τῶν πολιτῶν ἀσφαλείας ἕνεκα πρὸς δὲ τὴν δευτέραν ἀξίωσιν οὐχ ὑπακούει, ἀπέλυσεν αὐτούς.", "st": "8.14.1"}, {"sp": "N", "t": "Ὁ δ’ Ἄδαδος ἀκούσας ταῦτα καὶ δυσχεράνας τρίτον ἔπεμψε πρὸς Ἄχαβον τοὺς πρέσβεις ἀπειλῶν ὑψηλότερον τῶν τειχῶν οἷς καταφρονεῖ χῶμα τούτοις ἐπεγείρειν αὐτοῦ τὴν στρατιὰν κατὰ δράκα λαμβάνουσαν, ἐμφανίζων αὐτῷ τῆς δυνάμεως τὸ πλῆθος καὶ καταπληττόμενος. τοῦ δ’ Ἀχάβου μὴ καυχᾶσθαι δεῖν ἀποκριναμένου καθωπλισμένον ἀλλὰ τῇ μάχῃ κρείττω γενόμενον, ἐλθόντες οἱ πρέσβεις καὶ δειπνοῦντα καταλαβόντες τὸν βασιλέα μετὰ τριάκοντα καὶ δύο βασιλέων συμμάχων ἐδήλωσαν αὐτῷ τὴν ἀπόκρισιν· ὁ δ’ εὐθέως τοῦτο προσέταξε καὶ περιχαρακοῦν τὴν πόλιν καὶ χώματα βάλλεσθαι καὶ μηδένα τρόπον ἀπολιπεῖν πολιορκίας. ἦν δ’ Ἄχαβος τούτων πραττομένων ἐν ἀγωνίᾳ δεινῇ σὺν παντὶ τῷ λαῷ· θαρρεῖ δὲ καὶ τῶν φόβων ἀπολύεται προφήτου τινὸς αὐτῷ προσελθόντος καὶ φήσαντος αὐτῷ τὸν θεὸν ὑπισχνεῖσθαι ποιήσειν τὰς τοσαύτας τῶν πολεμίων μυριάδας ὑποχειρίους. πυθομένῳ δέ, διὰ τίνων ἂν ἡ νίκη γένοιτο, διὰ τῶν παίδων, εἶπε, τῶν ἡγεμόνων ἡγουμένου σοῦ διὰ τὴν ἀπειρίαν ἐκείνων. καλέσαντος δὲ τοὺς τῶν ἡγεμόνων υἱούς, εὑρέθησαν δ’ ὡς διακόσιοι καὶ τριακονταδύο, μαθὼν τὸν Σύρον πρὸς εὐωχίαν καὶ ἄνεσιν τετραμμένον ἀνοίξας τὰς πύλας ἐξέπεμψε τοὺς παῖδας. τῶν δὲ σκοπῶν δηλωσάντων τοῦτο τῷ Ἀδάδῳ πέμπει τινὰς ὑπαντησομένους ἐντειλάμενος, ἂν μὲν εἰς μάχην ὦσι προεληλυθότες, ἵνα δήσαντες ἀγάγωσι πρὸς αὐτόν, ἂν δ’ εἰρηνικῶς, ὅπως ταὐτὸ ποιῶσιν. εἶχε δ’ ἑτοίμην Ἄχαβος καὶ τὴν ἄλλην στρατιὰν ἐντὸς τῶν τειχῶν. οἱ δὲ τῶν ἀρχόντων παῖδες συμβαλόντες τοῖς φύλαξι πολλοὺς αὐτῶν ἀποκτείνουσι καὶ τοὺς ἄλλους ἄχρι τοῦ στρατοπέδου διώκουσιν. ἰδὼν δὲ τούτους νικῶντας ὁ βασιλεὺς ἐξαφίησι καὶ τὴν ἄλλην στρατιὰν ἅπασαν. ἡ δ’ αἰφνιδίως ἐπιπεσοῦσα τοῖς Σύροις ἐκράτησεν αὐτῶν, οὐ γὰρ προσεδόκων αὐτοὺς ἐπεξελεύσεσθαι, καὶ διὰ τοῦτο γυμνοῖς καὶ μεθύουσι προσέβαλλον, ὥστε τὰς πανοπλίας ἐκ τῶν στρατοπέδων φεύγοντας καταλιπεῖν καὶ τὸν βασιλέα σωθῆναι μόλις ἐφ’ ἵππου ποιησάμενον τὴν φυγήν. Ἄχαβος δὲ πολλὴν ὁδὸν διώκων τοὺς Σύρους ἤνυσεν ἀναιρῶν αὐτούς, διαρπάσας δὲ τὰ ἐν τῇ παρεμβολῇ, πλοῦτος δ’ ἦν οὐκ ὀλίγος, ἀλλὰ καὶ χρυσοῦ πλῆθος καὶ ἀργύρου τά τε ἅρματα τοῦ Ἀδάδου καὶ τοὺς ἵππους λαβὼν ἀνέστρεψεν εἰς τὴν πόλιν. τοῦ δὲ προφήτου παρασκευάζεσθαι φήσαντος καὶ τὴν δύναμιν ἑτοίμην ἔχειν, ὡς τῷ ἐπιόντι πάλιν ἔτει στρατεύσοντος ἐπ’ αὐτὸν τοῦ Σύρου, ὁ μὲν Ἄχαβος πρὸς τούτοις ἦν.", "st": "8.14.2"}, {"sp": "N", "t": "Ὁ δὲ Ἄδαδος διασωθεὶς ἐκ τῆς μάχης μεθ’ ὅσης ἠδυνήθη στρατιᾶς συνεβουλεύσατο τοῖς αὑτοῦ φίλοις, πῶς ἂν ἐπιστρατεύσηται τοῖς Ἰσραηλίταις. οἱ δὲ ἐν μὲν τοῖς ὄρεσιν οὐκ ἐδίδοσαν γνώμην συμβαλεῖν αὐτοῖς· τὸν γὰρ θεὸν αὐτῶν ἐν τοῖς τοιούτοις δύνασθαι τόποις καὶ διὰ τοῦτο νῦν ὑπ’ αὐτῶν νενικῆσθαι· κρατήσειν δὲ ἔλεγον ἐν πεδίῳ ποιησαμένους τὴν μάχην. συνεβούλευον δὲ πρὸς τούτῳ τοὺς μὲν βασιλέας οὓς ἐπηγάγετο συμμάχους ἀπολῦσαι πρὸς τὰ οἰκεῖα, τὴν δὲ στρατιὰν αὐτῶν κατασχεῖν ἀντ’ ἐκείνων σατράπας καταστήσαντα· εἰς δὲ τὴν τῶν ἀπολωλότων τάξιν στρατολογῆσαι δύναμιν ἐκ τῆς χώρας τῆς αὐτῶν καὶ ἵππους καὶ ἅρματα. δοκιμάσας οὖν ταῦτα εἰρῆσθαι καλῶς οὕτως διεκόσμησε τὴν δύναμιν.", "st": "8.14.3"}, {"sp": "N", "t": "Ἀρξαμένου δὲ ἔαρος ἀναλαβὼν τὴν στρατιὰν ἦγεν ἐπὶ τοὺς Ἑβραίους, καὶ γενόμενος πρὸς πόλει τινί, Ἀφεκὰ δ’ αὐτὴν καλοῦσιν, ἐν μεγάλῳ στρατοπεδεύεται πεδίῳ. Ἄχαβος δ’ ἀπαντήσας αὐτῷ μετὰ τῆς δυνάμεως ἀντεστρατοπεδεύσατο· σφόδρα δ’ ἦν ὀλίγον αὐτοῦ τὸ στράτευμα πρὸς τοὺς πολεμίους ἀντιπαραβαλλόμενον. τοῦ δὲ προφήτου προσελθόντος αὐτῷ πάλιν καὶ νίκην τὸν θεὸν αὐτῷ διδόναι φήσαντος, ἵνα τὴν ἰδίαν ἰσχὺν ἐπιδείξηται μὴ μόνον ἐν τοῖς ὄρεσιν ἀλλὰ κἀν τοῖς πεδίοις ὑπάρχουσαν, ὅπερ οὐκ εἶναι δοκεῖ τοῖς Σύροις, ἑπτὰ μὲν ἡμέρας ἀντεστρατοπεδευκότες ἡσύχαζον, τῇ δὲ ὑστάτῃ τούτων ὑπὸ τὸν ὄρθρον προελθόντων ἐκ τοῦ στρατοπέδου τῶν πολεμίων καὶ παραταξαμένων εἰς μάχην ἀντεπεξῆγε καὶ Ἄχαβος τὴν [οἰκείαν] δύναμιν. καὶ συμβαλὼν καρτερᾶς τῆς μάχης γενομένης τρέπεται τοὺς πολεμίους εἰς φυγὴν καὶ διώκων ἐπέκειτο. οἱ δὲ καὶ ὑπὸ τῶν ἁρμάτων καὶ ὑπ’ ἀλλήλων ἀπώλοντο, ἴσχυσαν δ’ ὀλίγοι διαφυγεῖν εἰς τὴν Ἀφεκὰ πόλιν αὐτῶν. ἀπέθανον δὲ καὶ αὐτοὶ τῶν τειχῶν αὐτοῖς ἐπιπεσόντων ὄντες δισμύριοι ἑπτακισχίλιοι. διεφθάρησαν δ’ ἐν ἐκείνῃ τῇ μάχῃ ἄλλαι μυριάδες δέκα. ὁ δὲ βασιλεὺς τῶν Σύρων Ἄδαδος φεύγων μετά τινων πιστοτάτων οἰκετῶν εἰς ὑπόγειον οἶκον ἐκρύβη. τούτων φιλανθρώπους καὶ ἐλεήμονας εἶναι φησάντων τοὺς τῶν Ἰσραηλιτῶν βασιλέας καὶ δυνήσεσθαι τῷ συνήθει τρόπῳ τῆς ἱκετείας χρησαμένους τὴν σωτηρίαν αὐτῷ παρ’ Ἀχάβου λαβεῖν, εἰ συγχωρήσειεν αὐτοῖς πρὸς αὐτὸν ἀπελθεῖν, ἀφῆκεν· οἱ δὲ σάκκους ἐνδυσάμενοι καὶ σχοινία ταῖς κεφαλαῖς περιθέμενοι, οὕτως γὰρ τὸ παλαιὸν ἱκέτευον οἱ Σύροι, πρὸς Ἄχαβον παρεγένοντο καὶ δεῖσθαι τὸν Ἄδαδον σώζειν αὐτὸν ἔλεγον εἰς ἀεὶ δοῦλον αὐτοῦ τῆς χάριτος γενησόμενον. ὁ δὲ συνήδεσθαι φήσας αὐτῷ περιόντι καὶ μηδὲν ἐν τῇ μάχῃ πεπονθότι τιμὴν καὶ εὔνοιαν, ἣν ἄν τις ἀδελφῷ παράσχοι, κατεπηγγείλατο. λαβόντες δὲ ὅρκους παρ’ αὐτοῦ μηδὲν ἀδικήσειν φανέντα προάγουσι πορευθέντες ἐκ τοῦ οἴκου ἐν ᾧ κέκρυπτο καὶ προσάγουσι τῷ Ἀχάβῳ ἐφ’ ἅρματος καθεζομένῳ· ὁ δὲ προσεκύνησεν αὐτόν. Ἄχαβος δ’ ἐπιδοὺς αὐτῷ τὴν δεξιὰν ἀναβιβάζει ἐπὶ τὸ ἅρμα καὶ καταφιλήσας θαρρεῖν ἐκέλευε καὶ μηδὲν τῶν ἀτόπων προσδοκᾶν, Ἄδαδος δ’ εὐχαρίστει καὶ παρ’ ὅλον τὸν τοῦ ζῆν χρόνον ἀπομνημονεύσειν τῆς εὐεργεσίας ὡμολόγει καὶ τὰς πόλεις τῶν Ἰσραηλιτῶν, ἃς ἀπήνεγκαν οἱ πρὸ αὐτοῦ βασιλεῖς, ἀποδώσειν ἐπηγγείλατο καὶ Δαμασκὸν ὥστε ἐξελαύνειν εἰς αὐτήν, καθὼς καὶ οἱ πατέρες αὐτοῦ εἰς Σαμάρειαν εἶχον τοῦτο ποιεῖν, ἀνήσειν. γενομένων δ’ αὐτοῖς ὅρκων καὶ συνθηκῶν πολλὰ δωρησάμενος αὐτῷ Ἄχαβος ἀπέπεμψεν εἰς τὴν ἰδίαν βασιλείαν. καὶ τὰ μὲν περὶ τῆς Ἀδάδου τοῦ Σύρων βασιλέως στρατείας ἐπὶ Ἄχαβον καὶ τοὺς Ἰσραηλίτας τοιοῦτον ἔσχε τὸ τέλος.", "st": "8.14.4"}, {"sp": "N", "t": "Προφήτης δέ τις τοὔνομα Μιχαίας προσελθών τινι τῶν Ἰσραηλιτῶν ἐκέλευεν αὐτὸν εἰς τὴν κεφαλὴν πλῆξαι· τοῦτο γὰρ ποιήσειν κατὰ βούλησιν τοῦ θεοῦ. τοῦ δὲ μὴ πεισθέντος προεῖπε παρακούσαντα τῶν τοῦ θεοῦ προσταγμάτων λέοντι περιτυχόντα διαφθαρήσεσθαι. συμβάντος τούτου τἀνθρώπῳ πρόσεισιν ἑτέρῳ πάλιν ὁ προφήτης ταὐτὸ προστάσσων. πλήξαντος δ’ ἐκείνου καὶ θραύσαντος αὐτοῦ τὸ κρανίον καταδησάμενος τὴν κεφαλὴν προσῆλθε τῷ βασιλεῖ λέγων αὐτῷ συνεστρατεῦσθαι καὶ παραλαβεῖν ἐπὶ φυλακῇ τινα τῶν αἰχμαλώτων παρὰ τοῦ ταξιάρχου, φυγόντος δ’ αὐτοῦ κινδυνεύειν ὑπὸ τοῦ παραδεδωκότος ἀποθανεῖν· ἀπειλῆσαι γὰρ αὐτὸν εἰ διαφύγοι ὁ αἰχμάλωτος ἀποκτείνειν. δίκαιον δὲ φήσαντος Ἀχάβου τὸν θάνατον εἶναι λύσας τὴν κεφαλὴν ἐπιγινώσκεται ὑπ’ αὐτοῦ Μιχαίας ὁ προφήτης ὤν. ἐκέχρητο δὲ σοφίσματι πρὸς αὐτὸν τῷ γενομένῳ πρὸς τοὺς μέλλοντας λόγους· εἶπε γάρ, [ὡς] ὁ θεὸς ἀφέντ’ αὐτὸν διαδράναι τὴν τιμωρίαν Ἄδαδον τὸν βλασφημήσαντα εἰς αὐτὸν μετελεύσεται καὶ ποιήσει σεαυτὸν μὲν ἀποθανεῖν ὑπ’ ἐκείνου, τὸν δὲ λαὸν ὑπὸ τῆς στρατιᾶς αὐτοῦ. παροξυνθεὶς δ’ Ἄχαβος πρὸς τὸν προφήτην τὸν μὲν ἐγκλεισθέντα φυλάττεσθαι ἐκέλευσε, συγκεχυμένος δ’ αὐτὸς ἐπὶ τοῖς Μιχαίου λόγοις ἀνεχώρησεν εἰς τὴν οἰκείαν.", "st": "8.14.5"}, {"sp": "N", "t": "Καὶ Ἄχαβος μὲν ἐν τούτοις ἦν· ἐπάνειμι δὲ ἐπὶ τὸν Ἱεροσολύμων βασιλέα Ἰωσάφατον, ὃς αὐξήσας τὴν βασιλείαν καὶ δυνάμεις ἐν ταῖς πόλεσι ταῖς ἐν τῇ τῶν ὑπηκόων χώρᾳ καταστήσας οὐδὲν ἧττον Ἀβία τοῦ πάππου καταληφθείσης τῆς Ἐφράμου κληρουχίας Ἱεροβάμου βασιλεύοντος τῶν δέκα φυλῶν φρουρὰς ἐγκαθίδρυσεν. ἀλλ’ εἶχεν εὐμενές τε καὶ συνεργὸν τὸ θεῖον δίκαιος ὢν καὶ εὐσεβὴς καὶ τί καθ’ ἑκάστην ἡμέραν ἡδὺ ποιήσει καὶ προσηνὲς τῷ θεῷ ζητῶν. ἐτίμων δ’ αὐτὸν οἱ πέριξ βασιλικαῖς δωρεαῖς, ὡς πλοῦτόν τε ποιῆσαι βαθύτατον καὶ δόξαν ἄρασθαι μεγίστην.", "st": "8.15.1"}, {"sp": "N", "t": "Τρίτῳ δ’ ἔτει τῆς βασιλείας συγκαλέσας τοὺς ἡγεμόνας τῆς χώρας καὶ τοὺς ἱερεῖς ἐκέλευε τὴν γῆν περιελθόντας ἅπαντα τὸν λαὸν τὸν ἐπ’ αὐτῇ διδάξαι κατὰ πόλιν τοὺς Μωσείους νόμους καὶ φυλάσσειν τούτους καὶ σπουδάζειν περὶ τὴν θρησκείαν τοῦ θεοῦ. καὶ ἥσθη πᾶν τὸ πλῆθος οὕτως, ὡς μηδὲν ἄλλο φιλοτιμεῖσθαι μηδὲ ἀγαπᾶν ὡς τὸ τηρεῖν τὰ νόμιμα. οἵ τε προσχώριοι διετέλουν στέργοντες τὸν Ἰωσάφατον καὶ πρὸς αὐτὸν εἰρήνην ἄγοντες· οἱ δὲ Παλαιστῖνοι τακτοὺς ἐτέλουν αὐτῷ φόρους καὶ Ἄραβες ἐχορήγουν κατ’ ἔτος ἄρνας ἑξήκοντα καὶ τριακοσίους καὶ ἐρίφους τοσούτους. πόλεις τε μεγάλας ὠχύρωσεν ἄλλας τε καὶ βαρεῖς, καὶ δύναμιν στρατιωτικὴν πρὸς πολέμους ηὐτρέπιστο. ἦν δὲ ἐκ μὲν τῆς Ἰούδα φυλῆς στρατὸς ὁπλιτῶν μυριάδες τριάκοντα, ὧν Ἐδναῖος τὴν ἡγεμονίαν εἶχεν, Ἰωάννης δὲ μυριάδων εἴκοσι. ὁ δ’ αὐτὸς οὗτος ἡγεμὼν κἀκ τῆς Βενιαμίτιδος φυλῆς εἶχε τοξοτῶν πεζῶν μυριάδας εἴκοσι, ἄλλος δ’ ἡγεμὼν ᾧ Χάβαθος ὄνομα μυριάδας ὁπλιτῶν ὀκτωκαίδεκα τὸ πλῆθος τῷ βασιλεῖ προσένειμε, πάρεξ ὧν εἰς τὰς ὀχυρωτάτας διέπεμψε πόλεις.", "st": "8.15.2"}, {"sp": "N", "t": "Ἠγάγετο δὲ τῷ παιδὶ Ἰωράμῳ τὴν Ἀχάβου θυγατέρα τοῦ τῶν δέκα φυλῶν βασιλέως Ὀθλίαν ὄνομα. πορευθέντα δ’ αὐτὸν μετὰ χρόνον τινὰ εἰς Σαμάρειαν φιλοφρόνως Ἄχαβος ὑπεδέξατο καὶ τὸν ἀκολουθήσαντα στρατὸν ἐξένισε λαμπρῶς σίτου τε καὶ οἴνου καὶ θυμάτων ἀφθονίᾳ, παρεκάλεσέ τε συμμαχῆσαι κατὰ τοῦ Σύρων βασιλέως, ἵνα τὴν ἐν τῇ Γαλαδηνῇ πόλιν Ἀραμαθὰν ἀφέληται· τοῦ γὰρ πατρὸς αὐτὴν τοῦ αὐτοῦ πρῶτον τυγχάνουσαν ἀφῃρῆσθαι τὸν ἐκείνου πατέρα. τοῦ δὲ Ἰωσαφάτου τὴν βοήθειαν ἐπαγγειλαμένου, καὶ γὰρ εἶναι δύναμιν αὐτῷ μὴ ἐλάττω τῆς ἐκείνου, καὶ μεταπεμψαμένου τὴν δύναμιν ἐξ Ἱεροσολύμων εἰς Σαμάρειαν, προεξελθόντες ἔξω τῆς πόλεως οἱ δύο βασιλεῖς καθίσαντες ἐπὶ τοῦ ἰδίου θρόνου ἑκάτερος τοῖς οἰκείοις στρατιώταις τὸ στρατιωτικὸν διένεμον. Ἰωσαφάτης δ’ ἐκέλευσεν εἴ τινές εἰσι προφῆται καλέσαντ’ αὐτοὺς ἀνακρῖναι περὶ τῆς ἐπὶ τὸν Σύρον ἐξόδου, εἰ συμβουλεύουσι κατ’ ἐκεῖνον τὸν καιρὸν αὐτῷ ποιήσασθαι τὴν στρατείαν· καὶ γὰρ εἰρήνη τε καὶ φιλία τότε τῷ Ἀχάβῳ πρὸς τὸν Σύρον ὑπῆρχεν ἐπὶ τρία ἔτη διαμείνασα, ἀφ’ οὗ λαβὼν αὐτὸν αἰχμάλωτον ἀπέλυσεν ἄχρις ἐκείνης τῆς ἡμέρας.", "st": "8.15.3"}, {"sp": "N", "t": "Καλέσας δὲ Ἄχαβος τοὺς αὑτοῦ προφήτας ὡσεὶ τετρακοσίους τὸν ἀριθμὸν ὄντας ἐκέλευσεν ἔρεσθαι τοῦ θεοῦ, εἰ δίδωσιν αὐτῷ στρατευσαμένῳ ἐπὶ Ἄδερα νίκην καὶ καθαίρεσιν τῆς πόλεως, δι’ ἣν ἐκφέρειν μέλλει τὸν πόλεμον. τῶν δὲ προφητῶν συμβουλευσάντων ἐκστρατεῦσαι, κρατήσειν γὰρ τοῦ Σύρου καὶ λήψεσθαι ὑποχείριον αὐτὸν ὡς καὶ τὸ πρῶτον, συνεὶς ἐκ τῶν λόγων Ἰωσάφατος, ὅτι ψευδοπροφῆται τυγχάνουσιν, ἐπύθετο τοῦ Ἀχάβου εἰ καὶ ἕτερός τίς ἐστι προφήτης τοῦ θεοῦ, ἵνα ἀκριβέστερον μάθωμεν περὶ τῶν μελλόντων. ὁ δ’ Ἄχαβος εἶναι μὲν ἔφη, μισεῖν δ’ αὐτὸν κακὰ προφητεύσαντα καὶ προειπόντα ὅτι τεθνήξεται νικηθεὶς ὑπὸ τοῦ Σύρου, ἐν φρουρᾷ δὲ νῦν αὐτὸν ἔχειν· καλεῖσθαι δὲ Μιχαίαν, υἱὸν δ’ εἶναι Ὀμβλαίου· τοῦ δ’ Ἰωσαφάτου κελεύσαντος αὐτὸν προαχθῆναι πέμψας εὐνοῦχον ἄγει τὸν Μιχαίαν. κατὰ δὲ τὴν ὁδὸν ἐδήλωσεν αὐτῷ ὁ εὐνοῦχος πάντας τοὺς ἄλλους προφήτας νίκην τῷ βασιλεῖ προειρηκέναι. ὁ δὲ οὐκ ἐξὸν αὐτῷ καταψεύσασθαι τοῦ θεοῖ φήσας, ἀλλ’ ἐρεῖν ὅτι ἂν αὐτῷ περὶ τοῦ βασιλέως [αὐτὸς] εἴπῃ, ὡς ἧκε πρὸς τὸν Ἄχαβον καὶ λέγειν αὐτῷ τἀληθὲς οὗτος ἐνωρκίσατο, δεῖξαι τὸν θεὸν αὐτῷ φεύγοντας τοὺς Ἰσραηλίτας ἔφη καὶ διωκομένους ὑπὸ τῶν Σύρων καὶ διασκορπιζομένους ὑπ’ αὐτῶν εἰς τὰ ὄρη, καθάπερ ποιμένων ἠρημωμένα ποίμνια. ἔλεγε δὲ σημαίνειν τοὺς μὲν μετ’ εἰρήνης ἀναστρέψειν εἰς τὰ ἴδια, πεσεῖσθαι δ’ αὐτὸν μόνον ἐν τῇ μάχῃ. ταῦτα φήσαντος τοῦ Μιχαία πρὸς Ἰωσάφατον ὁ Ἄχαβος ἀλλ’ ἔγωγε μικρὸν ἔμπροσθεν ἐδήλωσά σοι τὴν τἀνθρώπου πρός με διάθεσιν, καὶ ὅτι μοι τὰ χείρω προεφήτευσε. τοῦ δὲ Μιχαία εἰπόντος, ὡς προσῆκεν αὐτῷ πάντων ἀκροᾶσθαι τῶν ὑπὸ τοῦ θεοῦ προλεγομένων, καὶ ὡς παρορμῶσιν αὐτὸν οἱ ψευδοπροφῆται ποιήσασθαι τὸν πόλεμον ἐλπίδι νίκης, καὶ ὅτι δεῖ πεσεῖν αὐτὸν μαχόμενον, αὐτὸς μὲν ἦν ἐπ’ ἐννοίᾳ, Σεδεκίας δέ τις τῶν ψευδοπροφητῶν προσελθὼν Μιχαίᾳ μὲν μὴ προσέχειν παρῄνει· λέγειν γὰρ αὐτὸν οὐδὲν ἀληθές· τεκμηρίῳ δὲ ἐχρήσατο οἷς Ἠλίας προεφήτευσεν ὁ τούτου κρείττων τὰ μέλλοντα συνιδεῖν· καὶ γὰρ τοῦτον ἔλεγε προφητεύσαντα ἐν Ἱεζερήλα πόλει ἐν τῷ Ναβώθου ἀγρῷ τὸ αἷμα αὐτοῦ κύνας ἀναλιχμήσεσθαι προειπεῖν, καθὼς καὶ Ναβώθου τοῦ δι’ αὐτὸν καταλευσθέντος ὑπὸ τοῦ ὄχλου. δῆλον οὖν, ὅτι οὗτος ψεύδεται τῷ κρείττονι προφήτῃ τἀναντία λέγων ἀπὸ ἡμερῶν τριῶν φάσκων τεθνήξεσθαι. γνώσεσθε δ’ εἴπερ ἐστὶν ἀληθὴς καὶ τοῦ θείου πνεύματος ἔχει τὴν δύναμιν· εὐθὺς γὰρ ῥαπισθεὶς ὑπ’ ἐμοῦ βλαψάτω μου τὴν χεῖρα, ὥσπερ Ἰάδαος τὴν Ἱεροβοάμου τοῦ βασιλέως συλλαβεῖν θελήσαντος ἀπεξήρανε δεξιάν· ἀκήκοας γὰρ οἶμαι τοῦτο πάντως γενόμενον. ὡς οὖν πλήξαντος αὐτοῦ τὸν Μιχαίαν μηδὲν συνέβη παθεῖν, Ἄχαβος θαρρήσας ἄγειν τὴν στρατιὰν πρόθυμος ἦν ἐπὶ τὸν Σύρον· ἐνίκα γὰρ οἶμαι τὸ χρεὼν καὶ πιθανωτέρους ἐποίει τοῦ ἀληθοῦς τοὺς ψευδοπροφήτας, ἵνα λάβῃ τὴν ἀφορμὴν τοῦ τέλους. Σεδεκίας σιδήρεα ποιήσας κέρατα λέγει πρὸς Ἄχαβον, ὡς θεὸν αὐτῷ σημαίνειν τούτοις ἅπασαν καταστρέψεσθαι τὴν Συρίαν. Μιχαίαν δὲ μετ’ οὐ πολλὰς ἡμέρας εἰπόντα τὸν Σεδεκίαν ταμιεῖον ἐκ ταμιείου κρυβόμενον ἀμείψειν ζητοῦντα φυγεῖν τῆς ψευδολογίας τὴν δίκην, ἐκέλευσεν ὁ βασιλεὺς ἀπαχθέντα φυλάττεσθαι πρὸς Ἀχάμωνα τὸν τῆς πόλεως ἄρχοντα καὶ χορηγεῖσθαι μηδὲν ἄρτου καὶ ὕδατος αὐτῷ περισσότερον.", "st": "8.15.4"}, {"sp": "N", "t": "Καὶ Ἄχαβος μὲν καὶ Ἰωσάφατος ὁ τῶν Ἱεροσολύμων βασιλεὺς ἀναλαβόντες τὰς δυνάμεις ἤλασαν εἰς Ῥαμάθην πόλιν τῆς Γαλαδίτιδος. ὁ δὲ τῶν Σύρων βασιλεὺς ἀκούσας αὐτῶν τὴν στρατείαν ἀντεπήγαγεν αὐτοῖς τὴν αὑτοῦ στρατιὰν καὶ οὐκ ἄπωθεν τῆς Ἀραμάθης στρατοπεδεύεται. συνέθεντο δὲ ὅ τε Ἄχαβος καὶ Ἰωσάφατος ἀποθέσθαι μὲν τὸν Ἄχαβον τὸ βασιλικὸν σχῆμα, τὸν δὲ τῶν Ἱεροσολύμων βασιλέα τὴν αὐτοῦ στολὴν ἔχοντα στῆναι ἐν τῇ παρατάξει, κατασοφιζόμενοι τὰ ὑπὸ τοῦ Μιχαία προειρημένα. εὗρε δ’ αὐτὸν τὸ χρεὼν καὶ δίχα τοῦ σχήματος· ὁ μὲν γὰρ Ἄδαδος ὁ τῶν Σύρων βασιλεὺς παρήγγειλε τῇ στρατιᾷ διὰ τῶν ἡγεμόνων μηδένα τῶν ἄλλων ἀναιρεῖν, μόνον δὲ τὸν βασιλέα τῶν Ἰσραηλιτῶν. οἱ δὲ Σύροι τῆς συμβολῆς γενομένης ἰδόντες τὸν Ἰωσάφατον ἑστῶτα πρὸ τῆς τάξεως καὶ τοῦτον εἰκάσαντες εἶναι τὸν Ἄχαβον ὥρμησαν ἐπ’ αὐτὸν καὶ περικυκλωσάμενοι, ὡς ἐγγὺς ὄντες ἔγνωσαν οὐκ ὄντα τοῦτον, ἀνεχώρησαν ὀπίσω, ἀπό τε ἀρχομένης ἠοῦς ἄχρι δείλης μαχόμενοι καὶ νικῶντες ἀπέκτειναν οὐδένα κατὰ τὴν τοῦ βασιλέως ἐντολὴν ζητοῦντες τὸν Ἄχαβον ἀνελεῖν μόνον καὶ εὑρεῖν οὐ δυνάμενοι. παῖς δέ τις βασιλικὸς τοῦ Ἀδάδου Ἀμανὸς ὄνομα τοξεύσας εἰς τοὺς πολεμίους τιτρώσκει τὸν βασιλέα διὰ τοῦ θώρακος κατὰ τοῦ πνεύμονος. Ἄχαβος δὲ τὸ μὲν συμβεβηκὸς οὐκ ἔγνω ποιῆσαι τῷ στρατεύματι φανερὸν μὴ τραπείησαν, τὸν δ’ ἡνίοχον ἐκέλευσεν ἐκτρέψαντα τὸ ἅρμα ἐξάγειν τῆς μάχης· χαλεπῶς γὰρ βεβλῆσθαι καὶ καιρίως. ὀδυνώμενος δὲ ἔστη ἐπὶ τοῦ ἅρματος ἄχρι δύνοντος ἡλίου καὶ λιφαιμήσας ἀπέθανε.", "st": "8.15.5"}, {"sp": "N", "t": "Καὶ τὸ μὲν τῶν Σύρων στράτευμα νυκτὸς ἤδη γενομένης ἀνεχώρησεν εἰς τὴν παρεμβολήν, καὶ δηλώσαντος τοῦ στρατοκήρυκος ὅτι τέθνηκεν Ἄχαβος ἀνέζευξαν εἰς τὰ ἴδια, κομίσαντες δὲ τὸν Ἀχάβου νεκρὸν εἰς Σαμάρειαν ἐκεῖ θάπτουσι. καὶ τὸ ἅρμα ἀποπλύναντες ἐν τῇ Ἱεζερήλα κρήνῃ καθῃμαγμένον τῷ τοῦ βασιλέως φόνῳ ἀληθῆ τὴν Ἠλία προφητείαν ἐπέγνωσαν· οἱ μὲν γὰρ κύνες ἀνελιχμήσαντο τὸ αἷμα, αἱ δὲ ἑταιριζόμεναι ἐν τῇ κρήνῃ τὸ λοιπὸν λουόμεναι τούτῳ διετέλουν. ἀπέθανε δ’ ἐν Ἀραμάθῃ, Μιχαία τοῦτο προειπόντος. συμβάντων οὖν Ἀχάβῳ τῶν ὑπὸ τῶν δύο προφητῶν εἰρημένων μέγα τὸ θεῖον ἡγεῖσθαι καὶ σέβειν καὶ τιμᾶν αὐτὸ πανταχοῦ, καὶ τῆς ἀληθείας μὴ τὰ πρὸς ἡδονὴν καὶ βούλησιν πιθανώτερα δοκεῖν, ὑπολαμβάνειν δ’ ὅτι προφητείας καὶ τῆς διὰ τῶν τοιούτων προγνώσεως οὐδέν ἐστι συμφορώτερον παρέχοντος οὕτω τοῦ θεοῦ τί δεῖ φυλάξασθαι, λογίζεσθαί τε πάλιν ἐκ τῶν περὶ τὸν βασιλέα γεγενημένων στοχαζομένους προσῆκε τὴν τοῦ χρεὼν ἰσχύν, ὅτι μηδὲ προγινωσκόμενον αὐτὸ διαφυγεῖν ἔστιν, ἀλλ’ ὑπέρχεται τὰς ἀνθρωπίνας ψυχὰς ἐλπίσι κολακεῦον χρησταῖς, αἷς εἰς τὸ πόθεν αὐτῶν κρατήσει περιάγει. φαίνεται οὖν καὶ Ἄχαβος ὑπὸ τούτου τὴν διάνοιαν ἀπατηθείς, ὥστε ἀπιστῆσαι μὲν τοῖς προλέγουσι τὴν ἧτταν, τοῖς δὲ πρὸς χάριν προφητεύσασι πεισθεὶς ἀποθανεῖν. τοῦτον μὲν οὖν ὁ παῖς Ὀχοζίας διεδέξατο.", "st": "8.15.6"}, {"sp": "HDR", "t": "Βιβλίον Θʹ", "st": "9"}, {"sp": "N", "t": "Ἰωσαφάτῃ δὲ τῷ βασιλεῖ παραγενομένῳ εἰς Ἱεροσόλυμα ἀπὸ τῆς συμμαχίας τῆς πρὸς Ἄχαβον τὸν τῶν Ἰσραηλιτῶν βασιλέα, ἣν Ἄδερι τῷ Σύρων πολεμοῦντι βασιλεῖ παρασχὼν ἦν ὡς προειρήκαμεν, Ἰηοῦς ὁ προφήτης συντυχὼν ᾐτιᾶτο τῆς πρὸς Ἄχαβον συμμαχίας ἄνθρωπον ἀσεβῆ καὶ πονηρόν· τὸν γὰρ θεὸν ἀηδῶς μὲν ἐπὶ τούτῳ διατεθῆναι, ῥύσασθαι μέντοι καίπερ ἡμαρτηκότα διὰ τὴν ἰδίαν αὐτοῦ φύσιν οὖσαν ἀγαθὴν ἔλεγεν ἐκ τῶν πολεμίων. καὶ τότε μὲν ἐπ’ εὐχαριστίας καὶ θυσίας ὁ βασιλεὺς τρέπεται τοῦ θεοῦ· μετὰ ταῦτα δὲ τὴν χώραν ὥρμησεν περιερχόμενος ἐν κύκλῳ πᾶσαν ὅσης αὐτὸς ἐπῆρχε τὸν λαὸν ἐκδιδάσκειν τά τε νόμιμα τὰ διὰ Μωσήους ὑπὸ θεοῦ δοθέντα καὶ τὴν εὐσέβειαν τὴν πρὸς αὐτόν. καὶ δικαστὰς ἀποδείξας ἐν ἑκάστῃ πόλει τῶν βασιλευομένων ὑπ’ αὐτοῦ παρεκελεύσατο μηδενὸς οὕτως ὡς τοῦ δικαίου προνοουμένους κρίνειν τοῖς ὄχλοις μήτε δώρων μήτε ἀξιώματος τῶν ἐν ὑπεροχῇ διὰ πλοῦτον ἢ γένος εἶναι δοκούντων, βραβεύειν δὲ ἅπασι τὸ ἴσον ἐπισταμένους, ὅτι καὶ τῶν κρύφα πραττομένων ἕκαστον ὁ θεὸς βλέπει. ταῦτα διδάξας κατὰ πόλιν ἑκάστην τῶν δύο φυλῶν ὑπέστρεψεν εἰς Ἱεροσόλυμα, κατέστησε δὲ καὶ ἐν τούτοις κριτὰς ἐκ τῶν ἱερέων καὶ τῶν Ληουιτῶν καὶ τῶν τὰ πρῶτα τοῦ πλήθους φερομένων παραινέσας ἐπιμελεῖς καὶ δικαίας ποιεῖσθαι πάσας τὰς κρίσεις· ἂν δὲ περὶ μειζόνων διαφορὰν ἔχοντες τῶν ὁμοφύλων τινὲς ἐκ τῶν ἄλλων πρὸς αὐτοὺς πέμψωσι πόλεων, τούτοις δὲ μετὰ πλείονος σπουδῆς ἀποφαίνεσθαι δικαίως περὶ τῶν πραγμάτων· μάλιστα γὰρ τὰς ἐν ταύτῃ τῇ πόλει κρίσεις, ἐν ᾗ τόν τε ναὸν εἶναι τοῦ θεοῦ συμβέβηκε καὶ δίαιταν ὁ βασιλεὺς ἔχει, προσῆκε σπουδαίας εἶναι καὶ δικαιοτάτας. ἄρχοντας δ’ αὐτῶν ἀποδείκνυσιν Ἀμασίαν τὸν ἱερέα καὶ Ζαβαδίαν ἐκ τῆς Ἰούδα φυλῆς ἑκατέρους. καὶ ὁ μὲν βασιλεὺς τοῦτον τὸν τρόπον διέτασσε τὰ πράγματα.", "st": "9.1.1"}, {"sp": "N", "t": "Κατὰ δὲ τὸν αὐτὸν καιρὸν ἐστράτευον ἐπ’ αὐτὸν Μωαβῖται καὶ Ἀμμανῖται συμπαραλαβόντες καὶ Ἀράβων μεγάλην μοῖραν, καὶ καταστρατοπεδεύονται πρὸς Ἐγγάδῃ πόλει κειμένῃ πρὸς τῇ Ἀσφαλτίδι λίμνῃ τριακοσίους ἀπεχούσῃ σταδίους τῶν Ἱεροσολύμων· γεννᾶται δ’ ἐν αὐτῇ φοίνιξ ὁ κάλλιστος καὶ ὀποβάλσαμον. ἀκούσας δ’ Ἰωσαφάτης, ὅτι τὴν λίμνην διαβάντες οἱ πολέμιοι ἐμβεβλήκασιν ἤδη εἰς τὴν βασιλευομένην ὑπ’ αὐτοῦ χώραν, δείσας εἰς ἐκκλησίαν συνάγει τὸν δῆμον τῶν Ἱεροσολυμιτῶν εἰς τὸ ἱερόν, καὶ στὰς κατὰ πρόσωπον τοῦ ναοῦ ηὔχετο καὶ ἐπεκαλεῖτο τὸν θεὸν παρασχεῖν αὐτῷ δύναμιν καὶ ἰσχύν, ὥστε τιμωρήσασθαι τοὺς ἐπιστρατεύσαντας· καὶ γὰρ τοῦτο δεηθῆναι τοὺς τὸ ἱερὸν κατασκευασαμένους αὐτοῦ, ὅπως ὑπερμάχηται τῆς πόλεως ἐκείνης καὶ τοὺς ἐπ’ αὐτὸ τολμήσαντας ἐλθεῖν ἀμύνηται, οἳ τὴν ὑπ’ αὐτοῦ δοθεῖσαν γῆν εἰς κατοίκησιν ἀφελέσθαι πάρεισιν αὐτούς. ταῦτ’ εὐχόμενος ἐδάκρυε καὶ σύμπαν δὲ τὸ πλῆθος γυναιξὶν ἅμα καὶ τέκνοις ἱκέτευεν. Ἰαζίηλος δέ τις προφήτης παρελθὼν εἰς μέσην τὴν ἐκκλησίαν ἀνεβόησε τῷ τε πλήθει λέγων καὶ τῷ βασιλεῖ, τὸν θεὸν ἐπακοῦσαι τῶν εὐχῶν καὶ πολεμήσειν αὐτὸν τοῖς ἐχθροῖς ἐπαγγέλλεσθαι. προσέταξε δὲ τῇ ἐπιούσῃ τὴν στρατιὰν ἐξελάσαντα τοῖς πολεμίοις ὑπαντᾶν· εὑρήσειν γὰρ αὐτοὺς ἐπὶ τῆς μεταξὺ Ἱεροσολύμων καὶ Ἐγγάδης ἀναβάσεως λεγομένης δ’ Ἐξοχῆς· καὶ μὴ συμβαλεῖν μὲν αὐτοῖς, στάντας δὲ μόνον ὁρᾶν, πῶς αὐτοῖς μάχεται τὸ θεῖον. τοῦ δὲ προφήτου ταῦτ’ εἰπόντος ὁ μὲν βασιλεὺς καὶ τὸ πλῆθος πεσόντες ἐπὶ πρόσωπον ηὐχαρίστουν τῷ θεῷ καὶ προσεκύνουν, οἱ δὲ Ληουῖται τοῖς ὀργάνοις διετέλουν ὑμνοῦντες.", "st": "9.1.2"}, {"sp": "N", "t": "Ἅμα δ’ ἡμέρᾳ προελθὼν ὁ βασιλεὺς εἰς τὴν ἔρημον τὴν ὑποκάτω Θεκώας πόλεως ἔλεγε πρὸς τὸ πλῆθος, ὡς δεῖ πιστεύειν τοῖς ὑπὸ τοῦ προφήτου εἰρημένοις καὶ μὴ παρατάσσεσθαι μὲν αὐτοὺς εἰς μάχην, προστησαμένους δὲ τοὺς ἱερεῖς μετὰ τῶν σαλπίγγων καὶ Ληουιτῶν εὐχαριστεῖν ὡς ἤδη ῥυσαμένῳ τὴν χώραν ἡμῶν παρὰ τῶν πολεμίων. ἤρεσε δὲ ἡ τοῦ βασιλέως γνώμη, καὶ ἅπερ συνεβούλευσε ταῦτ’ ἔπραττον. ὁ δὲ θεὸς εἰς φόβον ἐνέβαλε καὶ ταραχὴν τοὺς Ἀμμανίτας· οἱ δὲ δόξαντες ἀλλήλους πολεμίους ἀπέκτεινον, ὡς ἐκ τῆς τοσαύτης στρατιᾶς ἀνασωθῆναι μηδένα. Ἰωσαφάτης δὲ ἀποβλέψας εἰς τὴν φάραγγα, ἐν ᾗ συνέβαιν’ ἐστρατοπεδευκέναι τοὺς πολεμίους, καὶ πλήρη νεκρῶν ἰδὼν ἥσθη μὲν ἐπὶ τῷ παραδόξῳ τῆς τοῦ θεοῦ βοηθείας, ὅτι μηδὲ πονήσασιν αὐτοῖς αὐτὸς δι’ αὑτοῦ τὴν νίκην ἔδωκεν, ἐπέτρεψε δὲ τῇ στρατιᾷ διαρπάσαι τὴν παρεμβολὴν τῶν ἐχθρῶν καὶ σκυλεῦσαι τοὺς νεκρούς. καὶ οἱ μὲν ἐπὶ τρεῖς ἡμέρας σκυλεύοντες ἔκαμον· τοσοῦτον ἦν τὸ τῶν ἀνῃρημένων πλῆθος· τῇ τετάρτῃ δὲ συναθροισθεὶς πᾶς ὁ λαὸς εἴς τινα κοῖλον καὶ φαραγγώδη τόπον τὴν τοῦ θεοῦ δύναμιν καὶ τὴν συμμαχίαν εὐλόγησαν, ἀφ’ οὗ καὶ προσηγορίαν ἔσχεν ὁ τόπος κοιλὰς εὐλογίας.", "st": "9.1.3"}, {"sp": "N", "t": "Ἐκεῖθεν δὲ ἀναγαγὼν τὴν στρατιὰν ὁ βασιλεὺς εἰς Ἱεροσόλυμα τρέπεται πρὸς εὐωχίαν καὶ θυσίας ἐπὶ πολλὰς ἡμέρας. μετὰ μέντοι γε τὴν τῶν πολεμίων αὐτοῦ διαφθορὰν ἀκουσθεῖσαν τοῖς ἀλλοφύλοις ἔθνεσι πάντες οὗτοι κατεπλάγησαν αὐτόν, ὡς φανερῶς αὐτῷ τοῦ θεοῦ τὸ λοιπὸν συμμαχοῦντος. καὶ Ἰωσαφάτης μὲν ἔκτοτε μετὰ λαμπρᾶς δόξης ἐπί τε δικαιοσύνῃ καὶ τῇ πρὸς τὸ θεῖον εὐσεβείᾳ διῆγεν· ἦν δὲ φίλος καὶ τῷ τοῦ Ἀχάβου παιδὶ βασιλεύοντι τῶν Ἰσραηλιτῶν, πρὸς ὃν κοινωνήσας ἐπὶ κατασκευῇ νεῶν εἴς τε Πόντον πλεουσῶν καὶ τὰ ἐπὶ Θρᾴκης ἐμπόρια διήμαρτε τοῦ κτήματος· ὑπὸ γὰρ μεγέθους ἀπώλετο τὰ σκάφη· καὶ διὰ τοῦτο οὐκέτι περὶ ναῦς ἐφιλοτιμήσατο. τὰ μὲν οὖν περὶ τὸν Ἱεροσολύμων βασιλέα Ἰωσαφάτην οὕτως εἶχεν.", "st": "9.1.4"}, {"sp": "N", "t": "Ὁ δ’ Ἀχάβου παῖς Ὀχοζίας ἐβασίλευε τῶν Ἰσραηλιτῶν ἐν Σαμαρείᾳ ποιούμενος τὴν δίαιταν, πονηρὸς ὢν καὶ πάντα ὅμοιος τοῖς γονεῦσιν ἀμφοτέροις καὶ Ἱεροβοάμῳ τῷ πρώτῳ παρανομήσαντι καὶ τὸν λαὸν ἀπατᾶν ἀρξαμένῳ. τὴν δὲ βασιλείαν ἔτος ἤδη δεύτερον ἔχοντος ὁ τῶν Μωαβιτῶν ἀφίσταται βασιλεὺς αὐτοῦ καὶ τοὺς φόρους, οὓς ἔμπροσθεν ἐτέλει τῷ πατρὶ αὐτοῦ Ἀχάβῳ, χορηγῶν ἐπαύσατο. συνέβη δὲ τὸν Ὀχοζίαν καταβαίνοντα ἀπὸ τοῦ τέγους τῆς οἰκίας κατενεχθῆναι καὶ νοσήσαντα πέμψαι πρὸς τὴν Ἀκκάρων θεὸν Μυῖαν, τοῦτο γὰρ ἦν ὄνομα τῇ θεῷ, πυνθάνεσθαι περὶ τῆς σωτηρίας. φανεὶς δὲ ὁ τῶν Ἑβραίων θεὸς Ἠλίᾳ τῷ προφήτῃ προσέταξεν αὐτῷ τοῖς πεμφθεῖσιν ἀγγέλοις ὑπαντήσαντι πυνθάνεσθαι αὐτῶν, εἰ θεὸν ὁ Ἰσραηλιτῶν λαὸς ἴδιον οὐκ ἔχει, ὅτι πέμπει πρὸς τὸν ἀλλότριον βασιλεὺς αὐτῶν περὶ τῆς σωτηρίας ἐρησομένους, κελεῦσαί τε αὐτοὺς ὑποστρέψαι καὶ φράσαι τῷ βασιλεῖ, ὅτι μὴ διαφεύξεται τὴν νόσον. τοῦ δὲ Ἠλία ποιήσαντος ἃ προσέταξεν ὁ θεὸς ἀκούσαντες οἱ ἄγγελοι τὰ παρ’ αὐτοῦ παραχρῆμα ὑπέστρεψαν πρὸς τὸν βασιλέα. θαυμάζοντος δὲ τὸ τάχος τῆς ἐπανόδου καὶ τὴν αἰτίαν ἐρωτήσαντος ἔφασαν ἀπαντῆσαί τινα αὐτοῖς ἄνθρωπον καὶ κωλῦσαι μὲν προσωτέρω χωρεῖν, ἀναστρέψαντας δέ σοι λέγειν ἐξ ἐντολῆς τοῦ Ἰσραηλιτῶν θεοῦ, ὅτι κάκιον ἕξει ἡ νόσος. τοῦ δὲ βασιλέως σημαίνειν αὐτῷ τὸν ταῦτ’ εἰρηκότα κελεύσαντος, ἄνθρωπον ἔλεγον δασὺν καὶ ζώνην περιειλημμένον δερματίνην. συνεὶς δὲ ἐκ τούτων Ἠλίαν εἶναι τὸν σημαινόμενον ὑπὸ τῶν ἀγγέλων πέμψας πρὸς αὐτὸν ταξίαρχον καὶ πεντήκοντα ὁπλίτας ἀχθῆναι αὐτὸν ἐκέλευσεν. εὑρὼν δὲ τὸν Ἠλίαν ὁ πεμφθεὶς ταξίαρχος ἐπὶ τῆς κορυφῆς τοῦ ὄρους καθεζόμενον καταβάντα ἥκειν ἐκέλευε πρὸς τὸν βασιλέα· κελεύειν γὰρ τοῦτο ἐκεῖνον· εἰ δὲ μὴ θελήσειεν, ἄκοντα βιάσεσθαι. ὁ δὲ εἰπὼν πρὸς αὐτὸν ἐπὶ πείρᾳ τοῦ προφήτης ἀληθὴς ὑπάρχειν εὔξεσθαι πῦρ ἀπ’ οὐρανοῦ πεσὸν ἀπολέσαι τούς τε στρατιώτας καὶ αὐτὸν εὔχεται, καὶ πρηστὴρ κατενεχθεὶς διαφθείρει τόν τε ταξίαρχον καὶ τοὺς σὺν αὐτῷ. τῆς δὲ ἀπωλείας τῆς τούτων δηλωθείσης τῷ βασιλεῖ παροξυνθεὶς ἄλλον ταξίαρχον πέμπει ἐπὶ τὸν Ἠλίαν σὺν ὁπλίταις τοσούτοις, ὅσοις καὶ τὸν πρότερον συναπέστειλεν. ἀπειλήσαντος δὲ καὶ τούτου τῷ προφήτῃ βίᾳ λαβόντα ἄξειν αὐτὸν εἰ μὴ κατέλθοι βουλόμενος, εὐξαμένου κατ’ αὐτοῦ πῦρ διεχρήσατο καθὼς καὶ τὸν πρὸ αὐτοῦ ταξίαρχον. πυνθανόμενος δὲ καὶ τὰ περὶ τοῦτον ὁ βασιλεὺς τρίτον ἐξέπεμψεν. ὁ δὲ φρόνιμος ὢν καὶ λίαν ἐπιεικὴς τὸ ἦθος ἐλθὼν ἐπὶ τὸν τόπον, οὗ συνέβαινεν εἶναι τὸν Ἠλίαν, φιλοφρόνως προσεῖπεν αὐτόν· γινώσκειν δ’ ἔλεγεν, ὅτι μὴ βουλόμενος βασιλικῷ διακονῶν προστάγματι παρείη πρὸς αὐτόν, καὶ οἱ πρὸ αὐτοῦ πεμφθέντες οὐχ ἑκόντες ἀλλὰ κατὰ τὴν αὐτὴν αἰτίαν ἦλθον· ἐλεῆσαι τοιγαροῦν αὐτὸν ἠξίου τούς τε σὺν αὐτῷ παρόντας ὁπλίτας καὶ καταβάντα ἕπεσθαι πρὸς τὸν βασιλέα. ἀποδεξάμενος δὲ τὴν δεξιότητα τῶν λόγων καὶ τὸ ἀστεῖον τοῦ ἤθους ὁ Ἠλίας καταβὰς ἠκολούθησε. παραγενόμενος δὲ πρὸς τὸν βασιλέα προεφήτευσεν αὐτῷ καὶ τὸν θεὸν ἐδήλου λέγειν· ἐπειδὴ κατέγνως μὲν αὐτοῦ ὡς οὐκ ὄντος θεοῦ καὶ περὶ τῆς νόσου οὐ τἀληθὲς προειπεῖν δυναμένου, πρὸς δὲ τὸν Ἀκκαρωνιτῶν ἔπεμπες παρ’ αὐτοῦ πυνθανόμενος ποδαπὸν ἔσται σοι τῆς νόσου τέλος, γίνωσκε ὅτι τεθνήξῃ.", "st": "9.2.1"}, {"sp": "N", "t": "Καὶ ὁ μὲν ὀλίγου σφόδρα χρόνου διελθόντος καθὼς προεῖπεν Ἠλίας ἀπέθανε, διαδέχεται δ’ αὐτοῦ τὴν βασιλείαν ὁ ἀδελφὸς Ἰώραμος· ἄπαις γὰρ κατέστρεψε τὸν βίον. ὁ δὲ Ἰώραμος οὗτος τῷ πατρὶ Ἀχάβῳ τὴν πονηρίαν παραπλήσιος γενόμενος ἐβασίλευσεν ἔτη δώδεκα πάσῃ παρανομίᾳ χρησάμενος καὶ ἀσεβείᾳ πρὸς τὸν θεόν· παρεὶς γὰρ τοῦτον θρησκεύειν τοὺς ξενικοὺς ἐσέβετο· ἦν δὲ τἆλλα δραστήριος. κατ’ ἐκεῖνον δὲ τὸν καιρὸν Ἠλίας ἐξ ἀνθρώπων ἠφανίσθη καὶ οὐδεὶς ἔγνω μέχρι τῆς σήμερον αὐτοῦ τὴν τελευτήν· μαθητὴν δὲ Ἐλισσαῖον κατέλιπεν, ὡς καὶ πρότερον ἐδηλώσαμεν. περὶ μέντοι γε Ἠλία καὶ Ἐνώχου τοῦ γενομένου πρὸ τῆς ἐπομβρίας ἐν ταῖς ἱεραῖς ἀναγέγραπται βίβλοις, ὅτι γεγόνασιν ἀφανεῖς, θάνατον δ’ αὐτῶν οὐδεὶς οἶδεν.", "st": "9.2.2"}, {"sp": "N", "t": "Παραλαβὼν δὲ τὴν βασιλείαν Ἰώραμος ἐπὶ τὸν Μωαβιτῶν ἔγνω στρατεύειν βασιλέα Μεισὰν ὄνομα· τοῦ γὰρ ἀδελφοῦ αὐτοῦ, καθὼς προείπαμεν, ἔτυχεν ἀποστὰς φόρους τελῶν Ἀχάβῳ τῷ πατρὶ αὐτοῦ μυριάδας εἴκοσι προβάτων σὺν τοῖς πόκοις. συναθροίσας οὖν τὴν οἰκείαν δύναμιν ἔπεμψε πρὸς Ἰωσαφάτην παρακαλῶν αὐτόν, ἐπεὶ φίλος ἀπ’ ἀρχῆς ὑπῆρχεν αὐτοῦ τῷ πατρί, συμμαχῆσαι πόλεμον ἐπὶ τοὺς Μωαβίτας ἐκφέρειν μέλλοντι ἀποστάντας αὐτοῦ τῆς βασιλείας. ὁ δ’ οὐ μόνον αὐτὸς βοηθήσειν ὑπέσχετο, ἀλλὰ καὶ τὸν Ἰδουμαίων βασιλέα συναναγκάσειν ὄντα ὑφ’ ἑαυτὸν συστρατεύσασθαι. Ἰώραμος δὲ τοιούτων αὐτῷ τῶν παρὰ Ἰωσαφάτου περὶ τῆς συμμαχίας κομισθέντων ἀναλαβὼν αὑτοῦ τὴν στρατιὰν ἧκεν εἰς Ἱεροσόλυμα, καὶ ξενισθεὶς λαμπρῶς ὑπὸ τοῦ βασιλέως τῶν Ἱεροσολυμιτῶν, δόξαν αὐτοὺς διὰ τῆς ἐρήμου τῆς Ἰδουμαίας ποιήσασθαι τὴν πορείαν ἐπὶ τοὺς πολεμίους, οὐ γὰρ προσδοκήσειν αὐτοὺς ταύτῃ ποιήσεσθαι τὴν ἔφοδον, ὥρμησαν οἱ τρεῖς βασιλεῖς ἐκ τῶν Ἱεροσολύμων, ὅ τε τούτων αὐτῶν καὶ ὁ τῶν Ἰσραηλιτῶν καὶ ὁ τῆς Ἰδουμαίας, καὶ κυκλεύσαντες ἑπτὰ ἡμερῶν ὁδὸν εἰς ἀπορίαν ὕδατος τοῖς τε κτήνεσι καὶ τῇ στρατιᾷ περιέστησαν πλανηθέντων τὰς ὁδοὺς αὐτοῖς τῶν ἡγουμένων, ὡς ἀγωνιᾶν μὲν ἅπαντας, μάλιστα δὲ τὸν Ἰώραμον καὶ ὑπὸ λύπης ἐκβοῆσαι πρὸς τὸν θεόν, τί κακὸν αἰτιασάμενος ἀγάγοι τοὺς τρεῖς βασιλεῖς ἀμαχητὶ παραδώσοντας ἑαυτοὺς τῷ Μωαβιτῶν βασιλεῖ; παρεθάρρυνε δ’ αὐτὸν ὁ Ἰωσαφάτης δίκαιος ὢν καὶ πέμψαντα εἰς τὸ στρατόπεδον ἐκέλευσε γνῶναι, εἴ τις αὐτοῖς τοῦ θεοῦ προφήτης συνελήλυθεν, ἵνα δι’ αὐτοῦ μάθωμεν παρὰ τοῦ θεοῦ, τί ποιητέον ἡμῖν. οἰκέτου δέ τινος φήσαντος τῶν Ἰωράμου ἰδεῖν αὐτόθι τὸν Ἠλία μαθητὴν Ἐλισσαῖον Σαφάτου παῖδα πρὸς αὐτὸν ἀπίασιν οἱ τρεῖς βασιλεῖς Ἰωσαφάτου παραινέσαντος. ἐλθόντες δ’ ἐπὶ τὴν σκηνὴν τοῦ προφήτου, ἔτυχε δ’ ἔξω τῆς παρεμβολῆς κατεσκηνωκώς, ἐπηρώτων τὸ μέλλον ἐπὶ τῆς στρατιᾶς, μάλιστα δὲ ὁ Ἰώραμος. τοῦ δὲ μὴ διοχλεῖν αὐτῷ φράσαντος ἀλλὰ πρὸς τοὺς τοῦ πατρὸς αὐτοῦ καὶ τῆς μητρὸς βαδίζειν προφήτας, εἶναι γὰρ ἐκείνους ἀληθεῖς, ἐδεῖτο προφητεύειν καὶ σώζειν αὐτούς. ὁ δὲ ὀμόσας τὸν θεὸν οὐκ ἂν ἀποκριθῆναι αὐτῷ, εἰ μὴ διὰ Ἰωσαφάτην ὅσιον ὄντα καὶ δίκαιον, ἀχθέντος ἀνθρώπου τινὸς ψάλλειν εἰδότος, ἐπεζήτησε γὰρ αὐτός, πρὸς τὸν ψαλμὸν ἔνθεος γενόμενος προσέταξε τοῖς βασιλεῦσιν ἐν τῷ χειμάρρῳ πολλοὺς ὀρύξαι βόθρους· οὔτε γὰρ νέφους οὔτε πνεύματος γενομένου οὔτε ὑετοῦ καταρραγέντος ὄψεσθε πλήρη τὸν ποταμὸν ὕδατος, ὡς ἂν καὶ τὸν στρατὸν καὶ τὰ ὑποζύγια διασωθῆναι ὑμῖν ἀπὸ τοῦ ποτοῦ. ἔσται δὲ ὑμῖν οὐ τοῦτο μόνον παρὰ θεοῦ, ἀλλὰ καὶ κρατήσετε τῶν ἐχθρῶν καὶ καλλίστας καὶ ὀχυρωτάτας πόλεις λήψεσθε τῶν Μωαβιτῶν, καὶ δένδρα μὲν αὐτῶν ἥμερα κόψετε, τὴν δὲ χώραν δῃώσετε, πηγὰς δὲ καὶ ποταμοὺς ἐμφράξετε.", "st": "9.3.1"}, {"sp": "N", "t": "Ταῦτα εἰπόντος τοῦ προφήτου τῇ ἐπιούσῃ πρὶν ἥλιον ἀνασχεῖν ὁ χειμάρρους πολὺς ἐρρύη, σφοδρῶς γὰρ ἀπὸ τριῶν ἡμερῶν ὁδοῦ ἐν τῇ Ἰδουμαίᾳ τὸν θεὸν ὗσαι συνέπεσεν, ὥστε εὑρεῖν τὴν στρατιὰν καὶ τὰ ὑποζύγια ποτὸν ἄφθονον. ὡς δὲ ἤκουσαν οἱ Μωαβῖται τοὺς τρεῖς βασιλέας ἐπ’ αὐτοὺς βαδίζοντας καὶ διὰ τῆς ἐρήμου ποιουμένους τὴν ἔφοδον, ὁ βασιλεὺς αὐτῶν εὐθὺς συλλέξας στρατιὰν ἐκέλευσεν ἐπὶ τῶν ὅρων βάλλεσθαι τὸ στρατόπεδον, ἵνα αὐτοὺς μὴ λάθωσιν εἰς τὴν χώραν ἐμβαλόντες οἱ πολέμιοι. θεασάμενοι δὲ ὑπὸ τὴν ἀνατολὴν ἡλίου τὸ ἐν τῷ χειμάρρῳ ὕδωρ, καὶ γὰρ οὐδὲ μακρὰν ἦν τῆς Μωαβίτιδος, αἵματι τὴν χροὰν ὅμοιον, τότε γὰρ μάλιστα πρὸς τὴν αὐγὴν τὸ ὕδωρ ἐρυθραίνεται, ψευδῆ δόξαν περὶ τῶν πολεμίων ἐλάμβανον ὡς ἀπεκτονότων ἑαυτοὺς διὰ δίψος καὶ τοῦ ποταμοῦ αἷμα αὐτοῖς ῥέοντος. τοῦτο τοίνυν οὕτως ἔχειν ὑπολαβόντες ἠξίωσαν αὐτοὺς ἐπὶ διαρπαγὴν τῶν πολεμίων ἐκπέμψαι τὸν βασιλέα καὶ πάντες ἐξορμήσαντες ὡς ἐπὶ ἑτοίμην ὠφέλειαν ἦλθον εἰς τὸ τῶν ἐχθρῶν στρατόπεδον ὡς ἀπολωλότων. καὶ διαψεύδεται μὲν αὐτοῖς ἡ ἐλπὶς αὕτη, περιστάντων δὲ τῶν πολεμίων οἱ μὲν αὐτῶν κατεκόπησαν οἱ δὲ διεσπάρησαν εἰς τὴν ἰδίαν χώραν φεύγοντες. ἐμβαλόντες δὲ εἰς τὴν Μωαβιτῶν οἱ βασιλεῖς τάς τε πόλεις κατεστρέψαντο τὰς ἐν αὐτῇ καὶ τοὺς ἀγροὺς αὐτῶν διήρπασαν καὶ ἠφάνισαν πληροῦντες τῶν ἐκ τῶν χειμάρρων λίθων, καὶ τὰ κάλλιστα τῶν δένδρων ἔκοψαν, καὶ τὰς πηγὰς ἐνέφραξαν τῶν ὑδάτων, καὶ τὰ τείχη καθεῖλον ἕως ἐδάφους. ὁ δὲ βασιλεὺς τῶν Μωαβιτῶν συνδιωκόμενος τῇ πολιορκίᾳ καὶ τὴν πόλιν ὁρῶν κινδυνεύουσαν αἱρεθῆναι κατὰ κράτος ὥρμησε μεθ’ ἑπτακοσίων ἐξελθὼν διὰ τοῦ τῶν πολεμίων ἐξιππάσασθαι στρατοπέδου, καθ’ ὃ μέρος ἐνόμιζεν αὐτοὺς τὰς φυλακὰς ἀνεῖσθαι. καὶ πειραθεὶς οὐκ ἠδυνήθη φυγεῖν· ἐπιτυγχάνει γὰρ ἐπιμελῶς φρουρουμένῳ τῷ τόπῳ. ὑποστρέψας δὲ εἰς τὴν πόλιν ἔργον ἀπογνώσεως καὶ δεινῆς ἀνάγκης διεπράξατο· τῶν υἱῶν τὸν πρεσβύτατον, ὃς μετ’ αὐτὸν βασιλεύειν ἤμελλεν, ἀναγαγὼν ἐπὶ τὸ τεῖχος ὥστε ἅπασι φανερὸν γενέσθαι τοῖς πολεμίοις ἱερούργησεν εἰς ὁλοκαύτωσιν τῷ θεῷ. θεασάμενοι δ’ αὐτὸν οἱ βασιλεῖς κατῴκτειραν τῆς ἀνάγκης καὶ παθόντες ἀνθρώπινόν τι καὶ ἐλεεινὸν διέλυσαν τὴν πολιορκίαν καὶ ἕκαστος εἰς τὴν οἰκείαν ἀνέστρεψαν. Ἰωσαφάτης δὲ παραγενόμενος εἰς Ἱεροσόλυμα καὶ μετ’ εἰρήνης διαγαγὼν ὀλίγον ἐπιβιώσας χρόνον μετὰ τὴν στρατείαν ἐκείνην ἀπέθανε, ζήσας μὲν ἐτῶν ἀριθμὸν ἑξήκοντα, βασιλεύσας δὲ ἐξ αὐτῶν πέντε καὶ εἴκοσι. ταφῆς δὲ ἔτυχε μεγαλοπρεποῦς ἐν Ἱεροσολύμοις· καὶ γὰρ ἦν μιμητὴς τῶν Δαυίδου ἔργων.", "st": "9.3.2"}, {"sp": "N", "t": "Κατέλιπε δὲ καὶ παῖδας ἱκανούς, διάδοχον δ’ ἀπέδειξε τὸν πρεσβύτατον Ἰώραμον· ταὐτὸ γὰρ εἶχεν ὄνομα τῷ τῆς γυναικὸς ἀδελφῷ, βασιλεύοντι δὲ τῶν Ἰσραηλιτῶν, Ἀχάβου δὲ παιδί. παραγενόμενος δ’ ἐκ τῆς Μωαβίτιδος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς εἰς Σαμάρειαν εἶχε σὺν αὑτῷ τὸν προφήτην Ἐλισσαῖον, οὗ τὰς πράξεις βούλομαι διελθεῖν, λαμπραὶ γάρ εἰσι καὶ ἱστορίας ἄξιαι, καθὼς ἐν ταῖς ἱεραῖς βίβλοις ἐπεγνώκαμεν.", "st": "9.4.1"}, {"sp": "N", "t": "Προσελθοῦσαν γὰρ αὐτῷ φασι τὴν Ὠβεδίου τοῦ Ἀχάβου οἰκονόμου γυναῖκα εἰπεῖν, ὡς οὐκ ἀγνοεῖ πῶς ὁ ἀνὴρ αὐτῆς τοὺς προφήτας περιέσωσεν ὑπὸ τῆς Ἀχάβου γυναικὸς Ἰεζαβέλας ἀναιρουμένους· ἑκατὸν γὰρ ἔλεγεν ὑπ’ αὐτοῦ δανεισαμένου τραφῆναι κεκρυμμένους· καὶ μετὰ τὴν τἀνδρὸς τελευτὴν ἄγεσθαι νῦν ὑπὸ τῶν δανειστῶν αὐτήν τε καὶ τέκνα πρὸς δουλείαν, παρεκάλει τε διὰ ταύτην τὴν ἐργασίαν τἀνδρὸς ἐλεῆσαί τε καὶ παρασχεῖν τινα βοήθειαν. πυθομένῳ δ’ αὐτῷ, τί ἔχει ἐπὶ τῆς οἰκίας, ἄλλο μὲν οὐδὲν ἔφη, ἔλαιον δὲ βραχὺ λίαν ἐν κεραμίῳ. ὁ δὲ προφήτης ἀπελθοῦσαν ἐκέλευσεν ἀγγεῖα χρήσασθαι πολλὰ παρὰ τῶν γειτόνων κενὰ καὶ τὰς θύρας ἀποκλείσασαν τοῦ δωματίου μεταχεῖν εἰς ἅπαντα τὸ ἔλαιον· τὸν γὰρ θεὸν πληρώσειν αὐτά. τῆς δὲ γυναικὸς τὰ κελευσθέντα ποιούσης καὶ τοῖς τέκνοις προσφέρειν ἕκαστον τῶν ἀγγείων προσταττούσης, ἐπεὶ πάντα ἐπληρώθη καὶ μηδὲν ἦν κενόν, ἐλθοῦσα πρὸς τὸν προφήτην ταῦτα ἀπήγγειλεν. ὁ δὲ συνεβούλευε τοὔλαιον ἀπελθούσῃ ἀποδόσθαι καὶ τοῖς δανεισταῖς ἀποδοῦναι τὰ ὀφειλόμενα· γενήσεσθαι δέ τι καὶ περισσὸν ἐκ τῆς τιμῆς τοῦ ἐλαίου, ᾧ πρὸς διατροφὴν τὴν τῶν τέκνων καταχρήσεται. καὶ Ἐλισσαῖος μὲν οὕτως ἀπήλλαξε τῶν χρεῶν τὴν γυναῖκα καὶ τῆς ἀπὸ τῶν δανειστῶν ὕβρεως ἠλευθέρωσεν.", "st": "9.4.2"}, {"sp": "N", "t": "Ἐλισσαῖος δὲ ταχέως πρὸς Ἰώραμον ἐξαπέστειλε φυλάττεσθαι τὸν τόπον ἐκεῖνον αὐτῷ παραινῶν· εἶναι γὰρ ἐν αὐτῷ Σύρους τινὰς τοὺς ἐκεῖ λοχῶντας αὐτὸν ἀνελεῖν. καὶ ὁ μὲν βασιλεὺς οὐκέτ’ ἐπὶ τὴν θήραν ἐξώρμησε τῷ προφήτῃ πειθόμενος· Ἄδερ δὲ τῆς ἐπιβουλῆς διαμαρτὼν ὡς τῶν ἰδίων αὐτοῦ καταμηνυσάντων πρὸς τὸν Ἰώραμον τὴν ἐνέδραν, ὠργίζετό τε καὶ μεταπεμψάμενος αὐτοὺς προδότας ἔλεγε τῶν ἀπορρήτων αὐτοῦ καὶ θάνατον ἠπείλει φανερᾶς τῆς ἐπιχειρήσεως, ἣν μόνοις ἐκείνοις ἐπίστευσε, τῷ πολεμίῳ γεγενημένης. φήσαντος δέ τινος τῶν παρόντων ψευδοδοξεῖν αὐτόν, μηδὲ ὑπονοεῖν αὐτὸν ὡς πρὸς τὸν ἐχθρὸν αὐτοῦ κατειρηκότας τὴν ἔκπεμψιν τῶν ἀναιρησόντων αὐτούς, ἀλλὰ γινώσκειν ὅτι Ἐλισσαῖός ἐστιν ὁ προφήτης ὁ πάντα μηνύων αὐτῷ καὶ φανερὰ ποιῶν τὰ ὑπ’ αὐτοῦ βουλευόμενα, προσέταξε πέμψας μαθεῖν ἐν τίνι πόλει τυγχάνει διατρίβων Ἐλισσαῖος. οἱ δὲ πεμφθέντες ἧκον ἀγγέλλοντες αὐτὸν ἐν Δωθαεὶν ὑπάρχοντα. πέμπει τοιγαροῦν Ἄδερ ἐπὶ τὴν πόλιν δύναμιν πολλὴν ἱππέων καὶ ἁρμάτων, ὅπως τὸν Ἐλισσαῖον λάβωσιν. οἱ δὲ νυκτὸς κύκλῳ τὴν πόλιν πᾶσαν περιλαβόντες εἶχον ἐν φρουρᾷ. ἅμα δὲ ἕῳ τοῦτο μαθὼν ὁ τοῦ προφήτου διάκονος καὶ ὅτι ζητοῦσιν οἱ πολέμιοι λαβεῖν Ἐλισσαῖον ἐδήλωσεν αὐτῷ μετὰ βοῆς καὶ ταραχῆς δραμὼν πρὸς αὐτόν. ὁ δὲ τὸν θεράποντα μὴ δεδιέναι παρεθάρρυνε καὶ τὸν θεόν, ᾧ συμμάχῳ καταφρονῶν ἀδεὴς ἦν, παρεκάλει τῷ διακόνῳ πρὸς τὸ λαβεῖν αὐτὸν εὔελπι θάρσος ἐμφανίσαι τὴν αὑτοῦ δύναμιν καὶ παρουσίαν, ὡς δυνατόν. ὁ δὲ θεὸς ἐπήκοος τῶν εὐχῶν τοῦ προφήτου γενόμενος πλῆθος ἁρμάτων καὶ ἵππων τῷ θεράποντι περὶ τὸν Ἐλισσαῖον κεκυκλωμένον θεάσασθαι παρέσχεν, ὡς αὐτὸν ἀφιέναι μὲν τὸ δέος, ἀναθαρσῆσαι δὲ πρὸς τὴν ὄψιν τῆς νομιζομένης συμμαχίας. Ἐλισσαῖος δὲ μετὰ ταῦτα καὶ τὰς τῶν πολεμίων ὄψεις ἀμαυρῶσαι τὸν θεὸν παρεκάλει ἀχλὺν αὐταῖς ἐπιβαλόντα ἀφ’ ἧς ἀγνοήσειν αὐτὸν ἔμελλον. γενομένου δὲ καὶ τούτου προελθὼν εἰς μέσους τοὺς ἐχθροὺς ἐπηρώτησε, τίνα ἐπιζητοῦντες ἦλθον· τῶν δὲ τὸν προφήτην Ἐλισσαῖον εἰπόντων παραδώσειν ὑπέσχετο, εἰ πρὸς τὴν πόλιν ἐν ᾗ τυγχάνει ὢν ἀκολουθήσειαν αὐτῷ. καὶ οἱ μὲν ἡγουμένῳ τῷ προφήτῃ τὰς ὄψεις ὑπὸ θεοῦ καὶ τὴν διάνοιαν ἐπεσκοτημένοι σπουδάζοντες εἵποντο, ἀγαγὼν δὲ αὐτοὺς Ἐλισσαῖος εἰς Σαμάρειαν Ἰωράμῳ μὲν τῷ βασιλεῖ προσέταξε κλεῖσαι τὰς πύλας καὶ περιστῆσαι τοῖς Σύροις τὴν αὑτοῦ δύναμιν, τῷ θεῷ δὲ ηὔξατο καθᾶραι τὰς ὄψεις τῶν πολεμίων καὶ τὴν ἀχλὺν αὐτῶν ἀνελεῖν. οἱ δ’ ἐκ τῆς ἀμαυρώσεως ἐκείνης ἀφεθέντες ἑώρων αὑτοὺς ἐν μέσοις τοῖς ἐχθροῖς ὑπάρχοντας. ἐν ἐκπλήξει δὲ δεινῇ καὶ ἀμηχανίᾳ τῶν Σύρων οἷον εἰκὸς ἐφ’ οὕτως θείῳ καὶ παραδόξῳ πράγματι κειμένων καὶ τοῦ βασιλέως Ἰωράμου πυθομένου τὸν προφήτην, εἰ κελεύσειεν αὐτοὺς κατακοντισθῆναι, τοῦτο μὲν ἐκώλυσε ποιεῖν Ἐλισσαῖος· τοὺς γὰρ νόμῳ πολέμου ληφθέντας ἀποκτείνειν εἶναι δίκαιον ἔλεγε, τούτους δὲ μηδὲν κακὸν ἐργάσασθαι τὴν ἐκείνου χώραν, θείᾳ δὲ δυνάμει πρὸς αὐτοὺς οὐκ εἰδότας ἐλθεῖν. συνεβούλευέ τε ξενίων αὐτοῖς μεταδόντα καὶ τραπέζης ἀπολύειν ἀβλαβεῖς. Ἰώραμος μὲν οὖν τῷ προφήτῃ πειθόμενος ἑστιάσας λαμπρῶς πάνυ καὶ φιλοτίμως τοὺς Σύρους ἀπέλυσε πρὸς Ἄδερα τὸν αὑτῶν βασιλέα.", "st": "9.4.3"}, {"sp": "N", "t": "Τῶν δὲ ἀφικομένων καὶ δηλωσάντων αὐτῷ τὰ συμβεβηκότα θαυμάσας ὁ Ἄδερ τὸ παράδοξον καὶ τὴν τοῦ θεοῦ τῶν Ἰσραηλιτῶν ἐπιφάνειαν καὶ δύναμιν καὶ τὸν προφήτην, ᾧ τὸ θεῖον οὕτως ἐναργῶς παρῆν, κρύφα μὲν οὐκέτι διέγνω τῷ τῶν Ἰσραηλιτῶν ἐπιχειρεῖν βασιλεῖ τὸν Ἐλισσαῖον δεδοικώς, φανερῶς δὲ πολεμεῖν ἔκρινε τῷ πλήθει τῆς στρατιᾶς καὶ τῇ δυνάμει νομίζων περιέσεσθαι τῶν πολεμίων. καὶ στρατεύει μετὰ μεγάλης δυνάμεως ἐπὶ τὸν Ἰώραμον, ὃς οὐχ ἡγούμενος αὑτὸν ἀξιόμαχον εἶναι τοῖς Σύροις ἐνέκλεισεν αὑτὸν εἰς τὴν Σαμάρειαν θαρρῶν τῇ τῶν τειχῶν ὀχυρότητι. Ἄδερ δὲ λογισάμενος αἱρήσειν τὴν πόλιν, εἰ καὶ μὴ τοῖς μηχανήμασι, λιμῷ μέντοι καὶ σπάνει τῶν ἐπιτηδείων παραστήσεσθαι τοὺς Σαμαρεῖς, προσβαλὼν ἐπολιόρκει τὴν πόλιν. οὕτω δὲ ἐπέλιπε τὸν Ἰώραμον ἡ τῶν ἀναγκαίων εὐπορία, ὡς δι’ ὑπερβολὴν τῆς ἐνδείας ἐν τῇ Σαμαρείᾳ πραθῆναι ὀγδοήκοντα μὲν ἀργυρῶν νομίσματος κεφαλὴν ὄνου, πέντε δὲ ἀργυρῶν νομίσματος ξέστην κόπρου περιστερῶν ἀντὶ ἁλῶν ὠνεῖσθαι τοὺς Ἑβραίους. ἦν δ’ ἐν φόβῳ μὴ διὰ τὸν λιμὸν προδῷ τις τοῖς ἐχθροῖς τὴν πόλιν ὁ Ἰώραμος καὶ καθ’ ἑκάστην ἡμέραν ἐκπεριήρχετο τὰ τείχη καὶ τοὺς φύλακας, μή τις ἔνδον εἴη παρ’ αὐτῶν σκεπτόμενος καὶ τῷ βλέπεσθαι καὶ φροντίζειν ἀφαιρούμενος καὶ τὸ βούλεσθαί τι τοιοῦτον καὶ τὸ ἔργον, εἰ ταύτην τις τὴν γνώμην ἤδη λαμβάνειν ἔφθασεν. ἀνακραγούσης δέ τινος γυναικός δέσποτα ἐλέησον νομίσας αἰτεῖν τι μέλλειν αὐτὴν τῶν πρὸς τροφὴν ὀργισθεὶς ἐπηράσατο αὐτῇ τὸν θεὸν καὶ μήτε ἅλως αὐτῷ μήτε ληνοὺς ὑπάρχειν ἔλεγεν, ὅθεν τι καὶ παράσχοι ἂν αὐτῇ δεομένῃ. τῆς δ’ οὐδενὸς μὲν τούτων χρῄζειν εἰπούσης οὐδ’ ἐνοχλεῖν τροφῆς ἕνεκα, κριθῆναι δὲ ἀξιούσης πρὸς ἄλλην γυναῖκα, κελεύσαντος λέγειν καὶ διδάσκειν περὶ ὧν ἐπιζητεῖ συνθήκας ἔφη ποιήσασθαι μετὰ τῆς ἑτέρας γυναικὸς γειτνιώσης καὶ φίλης αὐτῇ τυγχανούσης, ὅπως ἐπεὶ τὰ τοῦ λιμοῦ καὶ τῆς ἐνδείας ἦν ἀμήχανα διαχρησάμενοι τὰ τέκνα, ἦν δὲ ἄρρεν ἑκατέρᾳ παιδίον, ἀνὰ μίαν ἡμέραν θρέψωμεν ἀλλήλας. κἀγὼ μέν, φησί, πρώτη τοὐμὸν κατέσφαξα καὶ τὴν παρελθοῦσαν ἡμέραν τοὐμὸν ἐτράφημεν ἀμφότεραι· νῦν δ’ οὐ βούλεται ταὐτὸ ποιεῖν, ἀλλὰ παραβαίνει τὴν συνθήκην καὶ τὸν υἱὸν ἀφανῆ πεποίηκε. τοῦτ’ ἐλύπησε σφοδρῶς Ἰώραμον ἀκούσαντα, καὶ περιρρηξάμενος τὴν ἐσθῆτα καὶ δεινὸν ἐκβοήσας ἔπειτα ὀργῆς ἐπὶ τὸν προφήτην Ἐλισσαῖον πληρωθεὶς ἀνελεῖν αὐτὸν ὥρμησεν, ὅτι μὴ δεῖται τοῦ θεοῦ πόρον τ’ αὐτοῖς καὶ διαφυγὴν τῶν περιεχόντων κακῶν δοῦναι· τόν τε ἀποτεμοῦντα αὐτοῦ τὴν κεφαλὴν εὐθὺς ἐξέπεμψε. καὶ ὁ μὲν ἐπὶ τὴν ἀναίρεσιν ἠπείγετο τοῦ προφήτου· τὸν δ’ Ἐλισσαῖον οὐκ ἔλαθεν ἡ τοῦ βασιλέως ὀργή, καθεζόμενος δὲ οἴκαδε παρ’ αὑτῷ σὺν τοῖς μαθηταῖς ἐμήνυσεν αὐτοῖς, ὅτι Ἰώραμος ὁ τοῦ φονέως υἱὸς πέμψειε τὸν ἀφαιρήσοντα αὐτοῦ τὴν κεφαλήν. ἀλλ’ ὑμεῖς, φησίν, ὅταν ὁ τοῦτο προσταχθεὶς ἀφίκηται, παραφυλάξαντες εἰσιέναι μέλλοντα προσαποθλίψατε τῇ θύρᾳ καὶ κατάσχετε· ἀκολουθήσει γὰρ αὐτῷ πρός με παραγινόμενος ὁ βασιλεὺς μεταβεβουλευμένος. καὶ οἱ μὲν τὸ κελευσθὲν ὡς ἧκεν ὁ πεμφθεὶς ὑπὸ τοῦ βασιλέως ἐπὶ τὴν ἀναίρεσιν τὴν Ἐλισσαίου ἐποίησαν· Ἰώραμος δὲ καταγνοὺς τῆς ἐπὶ τὸν προφήτην ὀργῆς καὶ δείσας, μὴ φθάσῃ κτείνας αὐτὸν ὁ τοῦτο προσταχθείς, ἔσπευσε κωλῦσαι γενέσθαι τὸν φόνον καὶ διασῶσαι τὸν προφήτην. ἀφικόμενος δὲ πρὸς αὐτὸν ᾐτιᾶτο, ὅτι μὴ παρὰ τοῦ θεοῦ λύσιν αὐτοῖς τῶν παρόντων αἰτεῖται κακῶν, ἀλλ’ οὕτως ὑπ’ αὐτῶν φθειρομένους ὑπερορᾷ. Ἐλισσαῖος δὲ εἰς τὴν ἐπιοῦσαν ἐπηγγέλλετο κατ’ ἐκείνην τὴν ὥραν, καθ’ ἣν ὁ βασιλεὺς ἀφίκετο πρὸς αὐτόν, ἔσεσθαι πολλὴν εὐπορίαν τροφῆς καὶ πραθήσεσθαι μὲν ἐν τῇ ἀγορᾷ σίκλου δύο κριθῆς σάτα, ὠνήσεσθαι δὲ σεμιδάλεως σάτον σίκλου. ταῦτα τόν τε Ἰώραμον καὶ τοὺς παρόντας εἰς χαρὰν περιέτρεψε· πιστεύειν γὰρ τῷ προφήτῃ διὰ τὴν ἐπὶ τοῖς προπεπειραμένοις ἀλήθειαν οὐκ ὤκνουν, ἀλλὰ καὶ τὸ ἐπ’ ἐκείνης ἐνδεὲς τῆς ἡμέρας καὶ ταλαίπωρον ἡ προσδοκωμένη κοῦφον αὐτοῖς ἐποίει. ὁ δὲ τῆς τρίτης μοίρας ἡγεμὼν τῷ βασιλεῖ φίλος ὢν καὶ τότε φέρων αὐτὸν ἐπερηρεισμένον ἄπιστα, εἶπε, λέγεις, ὦ προφῆτα· καὶ ὥσπερ ἀδύνατον ἐκχέαι τὸν θεὸν ἐξ οὐρανοῦ καταρράκτας κριθῆς ἢ σεμιδάλεως, οὕτως ἀμήχανον καὶ τὰ ὑπὸ σοῦ νῦν εἰρημένα γενέσθαι. καὶ ὁ προφήτης πρὸς αὐτόν ταῦτα μέν, εἶπεν, ὄψει τοῦτο λαμβάνοντα τὸ τέλος, οὐ μεταλήψῃ δ’ οὐδενὸς τῶν ὑπαρξόντων.", "st": "9.4.4"}, {"sp": "N", "t": "Ἐξέβη τοίνυν τοῦτον τὸν τρόπον τὰ ὑπὸ Ἐλισσαίου προειρημένα· νόμος ἦν ἐν Σαμαρείᾳ τοὺς λέπραν ἔχοντας καὶ μὴ καθαροὺς ἀπὸ τῶν τοιούτων τὰ σώματα μένειν ἔξω τῆς πόλεως. ἄνδρες οὖν τὸν ἀριθμὸν τέσσαρες διὰ ταύτην τὴν αἰτίαν πρὸ τῶν πυλῶν μένοντες μηκέτι μηδενὸς αὐτοῖς διὰ τὴν ὑπερβολὴν τοῦ λιμοῦ τροφὴν ἐκφέροντος εἰσελθεῖν μὲν εἰς τὴν πόλιν διὰ τὸν νόμον κεκωλυμένοι, κἂν ἐπιτραπῇ δ’ αὐτοῖς διαφθαρήσεσθαι κακῶς ὑπὸ τοῦ λιμοῦ λογισάμενοι, τοῦτο δὲ πείσεσθαι κἂν αὐτόθι μείνωσιν ἀπορίᾳ τροφῆς, παραδοῦναι τοῖς πολεμίοις αὑτοὺς ἔκριναν ὡς εἰ μὲν φείσαιντο αὐτῶν ζησόμενοι, εἰ δ’ ἀναιρεθεῖεν εὐθανατήσοντες. ταύτην κυρώσαντες τὴν βουλὴν νυκτὸς ἧκον εἰς τὸ στρατόπεδον τῶν πολεμίων. ἤρχετο δ’ ἤδη τοὺς Σύρους ἐκφοβεῖν καὶ ταράττειν ὁ θεὸς καὶ κτύπον ἁρμάτων καὶ ἵππων ὡς ἐπερχομένης στρατιᾶς ταῖς ἀκοαῖς αὐτῶν ἐνηχεῖν καὶ ταύτην ἐγγυτέρω προσφέρειν αὐτοῖς τὴν ὑπόνοιαν. ἀμέλει τοῦτον τὸν τρόπον ὑπ’ αὐτῆς διετέθησαν, ὥστε τὰς σκηνὰς ἐκλιπόντες συνέδραμον πρὸς τὸν Ἄδερα λέγοντες, ὡς Ἰώραμος ὁ τῶν Ἰσραηλιτῶν μισθωσάμενος συμμάχους τόν τε τῶν Αἰγυπτίων βασιλέα καὶ τὸν τῶν νήσων ἐπ’ αὐτοὺς ἄγει· προσιόντων γὰρ αὐτῶν ἐπακούειν τοῦ κτύπου. ταῦτα λέγουσιν ὁ Ἄδερ, καὶ γὰρ αὐτὸς περιεψοφεῖτο ἤδη τὰς ἀκοὰς ὁμοίως τῷ πλήθει, προσέσχε καὶ μετὰ πολλῆς ἀταξίας καὶ θορύβου καταλιπόντες ἐν τῇ παρεμβολῇ τοὺς ἵππους καὶ τὰ ὑποζύγια καὶ πλοῦτον ἄφθονον εἰς φυγὴν ἐχώρησαν. οἱ λεπροὶ δὲ οἱ ἐκ τῆς Σαμαρείας ἀναχωρήσαντες εἰς τὸ τῶν Σύρων στρατόπεδον, ὧν μικρὸν ἔμπροσθεν ἐπεμνήσθημεν, ὡς γενόμενοι πρὸς τῇ παρεμβολῇ πολλὴν ἡσυχίαν καὶ ἀφωνίαν ἔβλεπον οὖσαν καὶ παρελθόντες δὲ εἴσω καὶ ὁρμήσαντες εἰς μίαν σκηνὴν οὐδένα ἑώρων, ἐμφαγόντες καὶ πιόντες ἐβάστασαν ἐσθῆτα καὶ πολὺν χρυσὸν κομίσαντες ἔξω τῆς παρεμβολῆς ἔκρυψαν· ἔπειτ’ εἰς ἑτέραν σκηνὴν παρελθόντες ὁμοίως τὰ ἐν αὐτῇ πάλιν ἐξεκόμισαν, καὶ τοῦτ’ ἐποίησαν τετράκις μηδενὸς αὐτοῖς ὅλως ἐντυγχάνοντος. ὅθεν εἰκάσαντες ἀνακεχωρηκέναι τοὺς πολεμίους κατεγίνωσκον αὑτῶν μὴ ταῦτα δηλούντων τῷ Ἰωράμῳ καὶ τοῖς πολίταις. καὶ οἱ μὲν ἐλθόντες πρὸς τὸ τῆς Σαμαρείας τεῖχος καὶ ἀναβοήσαντες πρὸς τοὺς φύλακας ἐμήνυον αὐτοῖς τὰ περὶ τοὺς πολεμίους, ἐκεῖνοι δὲ ταῦτ’ ἀπήγγειλαν τοῖς τοῦ βασιλέως φύλαξι, παρ’ ὧν μαθὼν Ἰώραμος μεταπέμπεται τοὺς φίλους καὶ τοὺς ἡγεμόνας. πρὸς οὓς ἐλθόντας ἐνέδραν καὶ τέχνην ὑπονοεῖν ἔλεγε τὴν ἀναχώρησιν τοῦ τῶν Σύρων βασιλέως ἀπογνόντος ἡμᾶς τῷ λιμῷ διαφθαρήσεσθαι, ἵνα ὡς πεφευγότων εἰς διαρπαγὴν ἐξελθόντων τῆς παρεμβολῆς αἰφνιδίως ἐπιπέσῃ καὶ κτείνῃ μὲν αὐτούς, ἀμαχητὶ δὲ ἕλῃ τὴν πόλιν· ὅθεν ὑμῖν παραινῶ διὰ φυλακῆς ἔχειν αὐτὴν μὴ καταφρονήσαντας τῷ τοὺς πολεμίους ἀνακεχωρηκέναι· φήσαντος δέ τινος, ὡς ἄριστα μὲν καὶ συνετώτατα ὑπονοήσειε, πέμψαι γε μὴν συμβουλεύσαντος δύο τῶν ἱππέων τοὺς τὴν ἄχρι Ἰορδάνου πᾶσαν ἐξερευνήσοντας, ἵν’ εἰ ληφθέντες ὑπὸ λοχώντων τῶν πολεμίων διαφθαρεῖεν φυλακὴ τῇ στρατιᾷ γένωνται τοῦ μηδὲν ὅμοιον παθεῖν αὐτὴν ἀνυπόπτως προελθοῦσαν· προσαριθμήσεις δέ, φησί, τοῖς ὑπὸ τοῦ λιμοῦ τεθνηκόσι τοὺς ἱππεῖς, κἂν ὑπὸ τῶν ἐχθρῶν ληφθέντες ἀπόλωνται. ἀρεσθεὶς δὲ τῇ γνώμῃ τότε τοὺς κατοψομένους ἐξέπεμψεν· οἱ δὲ κενὴν μὲν πολεμίων τὴν ὁδὸν ἤνυσαν, μεστὴν δὲ σιτίων καὶ ὅπλων εὗρον, ἃ διὰ τὸ κοῦφοι πρὸς τὸ φεύγειν εἶναι ῥίπτοντες κατέλιπον. ταῦτ’ ἀκούσας ὁ βασιλεὺς ἐπὶ διαρπαγὴν τῶν ἐν τῷ στρατοπέδῳ τὸ πλῆθος ἐξαφῆκεν. εὐτελὲς δὲ οὐδὲν οὐδ’ ὀλίγον ὠφελοῦντο, ἀλλὰ πολὺν μὲν χρυσόν, πολὺν δὲ ἄργυρον, ἀγέλας δὲ παντοδαπῶν κτηνῶν, ἔτι γε μὴν σίτου μυριάσι καὶ κριθῆς αἷς οὐδ’ ὄναρ ἤλπισαν ἐπιτυχόντες τῶν μὲν προτέρων κακῶν ἀπηλλάγησαν, ἀφθονίαν δ’ εἶχον, ὡς ὠνεῖσθαι δύο μὲν σάτα κριθῆς σίκλου σεμιδάλεως δὲ σάτον σίκλου κατὰ τὴν Ἐλισσαίου προφητείαν· ἰσχύει δὲ τὸ σάτον μόδιον καὶ ἥμισυ Ἰταλικόν. μόνος δὲ τούτων οὐκ ὤνατο τῶν ἀγαθῶν ὁ τῆς τρίτης μοίρας ἡγεμών· κατασταθεὶς γὰρ ἐπὶ τῆς πύλης ὑπὸ τοῦ βασιλέως, ἵνα τὸ πλῆθος ἐπέχῃ τῆς πολλῆς ὁρμῆς καὶ μὴ κινδυνεύσωσιν ὑπ’ ἀλλήλων ὠθούμενοι συμπατηθέντες ἀπολέσθαι, τοῦτ’ αὐτὸς ἔπαθε καὶ τοῦτον ἀποθνήσκει τὸν τρόπον τὴν τελευτὴν αὐτῷ προφητεύσαντος Ἐλισσαίου, ὅτε τοῖς ὑπ’ αὐτοῦ περὶ τῆς ἐσομένης εὐπορίας τῶν ἐπιτηδείων λεγομένοις μόνος ἐξ ἁπάντων οὐκ ἐπίστευσεν.", "st": "9.4.5"}, {"sp": "N", "t": "Ὁ δὲ τῶν Σύρων βασιλεὺς Ἄδερος διασωθεὶς εἰς Δαμασκὸν καὶ μαθών, ὅτι τὸ θεῖον αὐτόν τε καὶ τὴν στρατιὰν αὐτοῦ πᾶσαν εἰς τὸ δέος καὶ τὴν ταραχὴν ἐκείνην ἐνέβαλεν, ἀλλ’ οὐκ ἐξ ἐφόδου πολεμίων ἐγένετο, σφόδρα τῷ δυσμενῆ τὸν θεὸν ἔχειν ἀθυμήσας εἰς νόσον κατέπεσεν. ἐκδημήσαντος δὲ κατ’ ἐκεῖνον τὸν καιρὸν εἰς Δαμασκὸν Ἐλισσαίου τοῦ προφήτου γνοὺς ὁ Ἄδερ τὸν πιστότατον τῶν οἰκετῶν Ἀζάηλον ἔπεμψεν ὑπαντησόμενον αὐτῷ καὶ δῶρα κομίζοντα, κελεύσας ἔρεσθαι περὶ τῆς νόσου καὶ εἰ διαφεύξεται τὸν ἐξ αὐτῆς κίνδυνον. Ἀζάηλος δὲ μετὰ καμήλων τεσσαράκοντα τὸν ἀριθμόν, αἳ τὰ κάλλιστα καὶ τιμιώτατα τῶν ἐν Δαμασκῷ γινομένων καὶ ὄντων ἐν τῷ βασιλείῳ ἔφερον δῶρα, συμβαλὼν τῷ Ἐλισσαίῳ προσαγορεύσας αὐτὸν φιλοφρόνως ἔλεγεν ὑπὸ Ἄδερος τοῦ βασιλέως πεμφθῆναι πρὸς αὐτὸν δῶρά τε κομίσαι καὶ πυθέσθαι περὶ τῆς νόσου καὶ εἰ ῥᾴων ἀπ’ αὐτῆς ἔσοιτο. ὁ δὲ προφήτης τὸν μὲν Ἀζάηλον ἐκέλευε μηδὲν ἀπαγγέλλειν τῷ βασιλεῖ κακόν, ἔλεγε δ’ ὅτι τεθνήξεται. καὶ ὁ μὲν οἰκέτης τοῦ βασιλέως ἐλυπεῖτο ταῦτ’ ἀκούσας, ὁ δ’ Ἐλισσαῖος ἔκλαιε καὶ πολλοῖς ἐρρεῖτο δακρύοις προορώμενος ἃ πάσχειν ὁ λαὸς ἔμελλε κακὰ μετὰ τὴν Ἄδερος τελευτήν. ἀνακρίναντος δ’ αὐτὸν Ἀζαήλου τὴν αἰτίαν τῆς συγχύσεως κλαίω, φησί, τὸ πλῆθος τῶν Ἰσραηλιτῶν ἐλεῶν, ὧν ἐκ σοῦ πείσεται δεινῶν· ἀποκτενεῖς γὰρ αὐτῶν τοὺς ἀρίστους καὶ τὰς ὀχυρωτάτας πόλεις ἐμπρήσεις, καὶ παιδία μὲν ἀπολεῖς προσρηγνὺς πέτραις τὰς δ’ ἐγκύους ἀναρρήξεις γυναῖκας. τοῦ δὲ Ἀζαήλου λέγοντος· τίνα γὰρ ἰσχὺν ἐμοὶ τηλικαύτην εἶναι συμβέβηκεν, ὥστε ταῦτα ποιῆσαι; τὸν θεὸν ἔφησεν αὐτῷ δεδηλωκέναι τοῦθ’, ὅτι τῆς Συρίας μέλλει βασιλεύειν. Ἀζάηλος μὲν οὖν παραγενόμενος πρὸς τὸν Ἄδερα τῷ μὲν τὰ βελτίω περὶ τῆς νόσου κατήγγελλε, τῇ δ’ ἐπιούσῃ δίκτυον ἐπιβαλὼν αὐτῷ διάβροχον τὸν μὲν στραγγάλῃ διέφθειρε, τὴν δ’ ἀρχὴν αὐτὸς παρέλαβε δραστήριός τε ὢν ἀνὴρ καὶ πολλὴν ἔχων παρὰ τῶν Σύρων εὔνοιαν καὶ τοῦ δήμου τῶν Δαμασκηνῶν, ὑφ’ οὗ μέχρι νῦν αὐτός τε ὁ Ἄδερ καὶ Ἀζάηλος ὁ μετ’ αὐτὸν ἄρξας ὡς θεοὶ τιμῶνται διὰ τὰς εὐεργεσίας καὶ τῶν ναῶν οἰκοδομίας, οἷς ἐκόσμησαν τὴν τῶν Δαμασκηνῶν πόλιν. πομπεύουσι δ’ αὐτοὶ καθ’ ἑκάστην ἡμέραν ἐπὶ τῇ τιμῇ τῶν βασιλέων καὶ σεμνύνονται τὴν τούτων ἀρχαιότητα οὐκ εἰδότες, ὅτι νεώτεροί εἰσι καὶ οὐκ ἔχοντες οὗτοι οἱ βασιλεῖς ἔτη χίλια καὶ ἑκατόν. ὁ δὲ τῶν Ἰσραηλιτῶν βασιλεὺς Ἰώραμος ἀκούσας τὴν Ἄδερος τελευτὴν ἀνέπνευσεν ἐκ τῶν φόβων καὶ τοῦ δέους ὃ δι’ αὐτὸν εἶχεν ἀσμένως εἰρήνης λαμβανόμενος.", "st": "9.4.6"}, {"sp": "N", "t": "Ἰώραμος δὲ ὁ τῶν Ἱεροσολύμων βασιλεύς, καὶ τούτῳ γὰρ ἦν ταὐτὸν καθὼς προειρήκαμεν ἔμπροσθεν ὄνομα, παραλαβὼν τὴν ἀρχὴν εὐθὺς ἐπὶ σφαγὴν τῶν ἀδελφῶν αὐτοῦ καὶ τῶν πατρῴων φίλων οἳ καὶ ἡγεμόνες ἦσαν ἐχώρησε, τὴν ἀρχὴν καὶ τὴν ἐπίδειξιν τῆς πονηρίας ἐντεῦθεν ποιησάμενος καὶ μηδὲν διενεγκὼν τῶν τοῦ λαοῦ βασιλέων, οἳ πρῶτοι παρηνόμησαν εἰς τὰ πάτρια τῶν Ἑβραίων ἔθη καὶ τὴν τοῦ θεοῦ θρησκείαν. ἐδίδαξε δ’ αὐτὸν τά τ’ ἄλλα εἶναι κακὸν καὶ δὴ καὶ ξενικοὺς θεοὺς προσκυνεῖν Γοθολία θυγάτηρ μὲν Ἀχάβου συνοικοῦσα δ’ αὐτῷ. καὶ ὁ μὲν θεὸς διὰ τὴν πρὸς Δαυίδην ὁμολογίαν οὐκ ἐβούλετο τούτου τὸ γένος ἐξαφανίσαι, Ἰώραμος δ’ οὐ διέλειπεν ἑκάστης ἡμέρας καινουργῶν ἐπ’ ἀσεβείᾳ καὶ λύμῃ τῶν ἐπιχωρίων ἐθισμῶν. ἀποστάντων δὲ αὐτοῦ κατ’ ἐκεῖνον τὸν καιρὸν τῶν Ἰδουμαίων καὶ τὸν μὲν πρότερον ἀποκτεινάντων βασιλέα, ὃς ὑπήκουεν αὐτοῦ τῷ πατρί, ὃν δ’ ἐβούλοντο αὐτοὶ καταστησάντων Ἰώραμος μετὰ τῶν περὶ αὐτὸν ἱππέων καὶ τῶν ἁρμάτων νυκτὸς εἰς τὴν Ἰδουμαίαν ἐνέβαλε, καὶ τοὺς μὲν πέριξ τῆς αὑτοῦ βασιλείας διέφθειρε, περαιτέρω δ’ οὐ προῆλθεν. ὤνησε μέντοι τοῦτο ποιήσας οὐδὲ ἕν· πάντες γὰρ ἀπέστησαν αὐτοῦ καὶ οἱ τὴν χώραν τὴν καλουμένην Λαβίναν νεμόμενοι. ἦν δ’ οὕτως ἐμμανής, ὥστε τὸν λαὸν ἠνάγκαζεν ἐπὶ τὰ ὑψηλότατα τῶν ὀρῶν ἀναβαίνοντα προσκυνεῖν τοὺς ἀλλοτρίους θεούς.", "st": "9.5.1"}, {"sp": "N", "t": "Ταῦτα δ’ αὐτῷ πράττοντι καὶ τελέως ἐκβεβληκότι τῆς διανοίας τὰ πάτρια νόμιμα κομίζεται παρ’ Ἠλίου τοῦ προφήτου ἐπιστολή, ἣ τὸν θεὸν ἐδήλου μεγάλην παρ’ αὐτοῦ ληψόμενον δίκην, ὅτι τῶν μὲν ἰδίων πατέρων μιμητὴς οὐκ ἐγένετο, τοῖς δὲ τῶν Ἰσραηλιτῶν βασιλέων κατηκολούθησεν ἀσεβήμασι καὶ συνηνάγκασε τὴν Ἰούδα φυλὴν καὶ τοὺς πολίτας Ἱεροσολύμων ἀφέντας τὴν ὁσίαν τοῦ ἐπιχωρίου θεοῦ σέβειν τὰ εἴδωλα, καθὼς καὶ Ἄχαβος τοὺς Ἰσραηλίτας ἐβιάσατο, ὅτι τε τοὺς ἀδελφοὺς διεχρήσατο καὶ τοὺς ἀγαθοὺς ἄνδρας καὶ δικαίους ἀπέκτεινεν· τήν τε τιμωρίαν ἣν ἀντὶ τούτων ὑφέξειν ἔμελλεν ἐσήμαινε τοῖς γράμμασιν ὁ προφήτης, ὄλεθρον τοῦ λαοῦ καὶ φθορὰν γυναικῶν αὐτοῦ [τοῦ βασιλέως] καὶ τέκνων, καὶ ὅτι τεθνήξεται νόσῳ τῆς νηδύος ἐπὶ πολὺ βασανισθεὶς καὶ τῶν ἐντέρων αὐτοῦ δι’ ὑπερβολὴν τῆς τῶν ἐντὸς διαφθορᾶς ἐκρυέντων, ὥστ’ αὐτὸν ὁρῶντα τὴν αὑτοῦ συμφορὰν καὶ μηδὲν βοηθῆσαι δυνάμενον ἔπειθ’ οὕτως ἀποθανεῖν. ταῦτα μὲν ἐδήλου διὰ τῆς ἐπιστολῆς ὁ Ἠλίας.", "st": "9.5.2"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ στρατὸς Ἀράβων τῶν ἔγγιστα τῆς Αἰθιοπίας κατοικούντων καὶ τῶν ἀλλοφύλων εἰς τὴν Ἰωράμου βασιλείαν ἐνέβαλε καὶ τήν τε χώραν διήρπασαν καὶ τὸν οἶκον τοῦ βασιλέως, ἔτι δὲ καὶ τοὺς υἱοὺς αὐτοῦ κατέσφαξαν καὶ τὰς γυναῖκας. εἷς δὲ αὐτῷ περιλείπεται τῶν παίδων διαφυγὼν τοὺς πολεμίους Ὀχοζίας ὄνομα. μετὰ δὲ ταύτην τὴν συμφορὰν αὐτὸς τὴν προειρημένην ὑπὸ τοῦ προφήτου νόσον ἐπὶ πλεῖστον νοσήσας χρόνον, ἐπέσκηψε γὰρ εἰς τὴν γαστέρα τὸ θεῖον αὐτοῦ τὴν ὀργήν, ἐλεεινῶς ἀπέθανεν ἐπιδὼν αὐτοῦ τὰ ἐντὸς ἐκρυέντα. περιύβρισε δ’ αὐτοῦ καὶ τὸν νεκρὸν ὁ λαός· λογισάμενος γὰρ οἶμαι τὸν οὕτως ἀποθανόντα κατὰ μῆνιν θεοῦ μηδὲ κηδείας τῆς βασιλεῦσι πρεπούσης ἄξιον εἶναι τυχεῖν, οὔτε ταῖς πατρῴαις ἐνεκήδευσεν αὐτὸν θήκαις οὔτε ἄλλης τιμῆς ἠξίωσεν, ἀλλ’ ὡς ἰδιώτην ἔθαψε, βιώσαντα μὲν ἔτη τεσσαράκοντα, βασιλεύσαντα δὲ ὀκτώ. παραδίδωσι δὲ τὴν ἀρχὴν ὁ δῆμος ὁ τῶν Ἱεροσολυμιτῶν τῷ παιδὶ αὐτοῦ Ὀχοζίᾳ.", "st": "9.5.3"}, {"sp": "N", "t": "Ἰώραμος δὲ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς μετὰ τὴν Ἄδερος τελευτὴν ἐλπίσας Ἀραμώθα πόλιν τῆς Γαλαδίτιδος ἀφαιρήσεσθαι τοὺς Σύρους στρατεύει μὲν ἐπ’ αὐτὴν μετὰ μεγάλης παρασκευῆς, ἐν δὲ τῇ πολιορκίᾳ τοξευθεὶς ὑπό τινος τῶν Σύρων οὐ καιρίως ἀνεχώρησεν εἰς Ἱεζερήλην πόλιν ἰαθησόμενος ἐν αὐτῇ τὸ τραῦμα, καταλιπὼν ἐν τῇ Ἀραμώθα τὴν στρατιὰν ἅπασαν καὶ ἡγεμόνα τὸν Ἀμασῆ παῖδα Ἰηοῦν· ἤδη γὰρ αὐτὴν ᾑρήκει κατὰ κράτος. προύκειτο δ’ αὐτῷ μετὰ τὴν θεραπείαν πολεμεῖν τοῖς Σύροις. Ἐλισσαῖος δ’ ὁ προφήτης ἕνα τῶν αὑτοῦ μαθητῶν δοὺς αὐτῷ τὸ ἅγιον ἔλαιον ἔπεμψεν εἰς Ἀραμώθα χρίσοντα τὸν Ἰηοῦν καὶ φράσοντα, ὅτι τὸ θεῖον αὐτὸν ᾕρηται βασιλέα· ἄλλα τε πρὸς τούτοις εἰπεῖν ἐπιστείλας ἐκέλευε τρόπῳ φυγῆς ποιήσασθαι τὴν πορείαν, ὅπως λάθῃ πάντας ἐκεῖθεν ἀπιών. ὁ δὲ γενόμενος ἐν τῇ πόλει τὸν μὲν Ἰηοῦν εὑρίσκει καθεζόμενον μετὰ τῶν τῆς στρατιᾶς ἡγεμόνων μέσον αὐτῶν καθὼς Ἐλισσαῖος αὐτῷ προεῖπε, προσελθὼν δὲ ἔφη βούλεσθαι περί τινων αὐτῷ διαλεχθῆναι. τοῦ δὲ ἀναστάντος καὶ ἀκολουθήσαντος εἰς τὸ ταμιεῖον λαβὼν ὁ νεανίσκος τὸ ἔλαιον κατέχεεν αὐτοῦ τῆς κεφαλῆς καὶ τὸν θεὸν ἔφη βασιλέα χειροτονεῖν αὐτὸν ἐπ’ ὀλέθρῳ τοῦ γένους τοῦ Ἀχάβου, καὶ ὅπως ἐκδικήσῃ τὸ αἷμα τῶν προφητῶν τῶν ὑπὸ Ἰεζαβέλας παρανόμως ἀποθανόντων, ἵν’ ὁ τούτων οἶκος τὸν αὐτὸν τρόπον ὅνπερ Ἱεροβάμου τοῦ Ναβαταίου παιδὸς καὶ Βασὰ πρόρριζος διὰ τὴν ἀσέβειαν αὐτῶν ἀφανισθῇ καὶ μηδὲν ὑπολειφθῇ σπέρμα τῆς Ἀχάβου γενεᾶς. καὶ ὁ μὲν ταῦτ’ εἰπὼν ἐξεπήδησεν ἐκ τοῦ ταμιείου σπουδάζων μηδενὶ τῶν ἐπὶ τῆς στρατιᾶς ὁραθῆναι.", "st": "9.6.1"}, {"sp": "N", "t": "Ὁ δὲ Ἰηοῦς προελθὼν ἧκεν ἐπὶ τὸν τόπον ἔνθα μετὰ τῶν ἡγεμόνων ἐκαθέζετο. πυνθανομένων δὲ καὶ φράζειν αὐτοῖς παρακαλούντων τί πρὸς αὐτὸν ἀφίκοιτο ὁ νεανίσκος καὶ προσέτι μαίνεσθαι λεγόντων αὐτόν, ἀλλ’ ὀρθῶς γε εἰκάσατε, εἶπε, καὶ γὰρ τοὺς λόγους μεμηνότος ἐποιήσατο. σπουδαζόντων δ’ ἀκοῦσαι καὶ δεομένων ἔφη τὸν θεὸν αὐτὸν ᾑρῆσθαι βασιλέα τοῦ πλήθους εἰρηκέναι. ταῦτ’ εἰπόντος ἕκαστος περιδύων αὑτὸν ὑπεστρώννυεν αὐτῷ τὸ ἱμάτιον καὶ σαλπίζοντες τοῖς κέρασιν ἐσήμαινον Ἰηοῦν εἶναι βασιλέα. ὁ δὲ ἀθροίσας τὴν στρατιὰν ἔμελλεν ἐξορμᾶν ἐπὶ Ἰώραμον εἰς Ἰεζέρελαν πόλιν, ἐν ᾗ καθὼς προεῖπον ἐθεραπεύετο τὴν πληγήν, ἣν ἔλαβε πρὸς τῇ Ἀραμώθα πολιορκίᾳ. ἔτυχε δὲ καὶ ὁ τῶν Ἱεροσολυμιτῶν βασιλεὺς Ὀχοζίας ἀφιγμένος πρὸς τὸν Ἰώραμον· υἱὸς γὰρ ἦν αὐτοῦ τῆς ἀδελφῆς ὡς καὶ προειρήκαμεν· ἐπισκέψασθαι δὲ πῶς ἐκ τοῦ τραύματος ἔχοι διὰ τὴν συγγένειαν ἐληλύθει. Ἰηοῦς δὲ βουλόμενος αἰφνιδίως τοῖς περὶ τὸν Ἰώραμον προσπεσεῖν ἠξίου μηδὲ τῶν στρατιωτῶν ἀποδράντα τινὰ μηνῦσαι ταῦτα τῷ Ἰωράμῳ· τοῦτο γὰρ ἔσεσθαι λαμπρὰν ἐπίδειξιν αὐτῷ τῆς εὐνοίας καὶ τοῦ διακειμένους οὕτως ἀποδεῖξαι αὐτὸν βασιλέα.", "st": "9.6.2"}, {"sp": "N", "t": "Οἱ δὲ τοῖς εἰρημένοις ἡσθέντες ἐφύλαττον τὰς ὁδούς, μή τις εἰς Ἱεζέρελαν διαλαθὼν μηνύσῃ αὐτὸν τοῖς ἐκεῖ. καὶ ὁ μὲν Ἰηοῦς τῶν ἱππέων τοὺς ἐπιλέκτους παραλαβὼν καὶ καθίσας ἐφ’ ἅρματος εἰς τὴν Ἱεζέρελαν ἐπορεύετο, γενομένου δὲ ἐγγὺς ὁ σκοπός, ὃν ὁ βασιλεὺς Ἰώραμος καθεστάκει τοὺς ἐρχομένους εἰς τὴν πόλιν ἀφορᾶν, ἰδὼν μετὰ πλήθους προσελαύνοντα τὸν Ἰηοῦν ἀπήγγειλεν Ἰωράμῳ προσελαύνουσαν ἱππέων ἴλην. ὁ δ’ εὐθὺς ἐκέλευσεν ἐκπεμφθῆναί τινα τῶν ἱππέων ὑπαντησόμενον καὶ τίς ἐστιν ὁ προσιὼν γνωσόμενον. ἐλθὼν οὖν πρὸς τὸν Ἰηοῦν ὁ ἱππεὺς ἐπερωτᾷ περὶ τῶν ἐν τῷ στρατοπέδῳ· πυνθάνεσθαι γὰρ ταῦτα τὸν βασιλέα. ὁ δὲ μηδὲν μὲν περὶ τούτων πολυπραγμονεῖν ἐκέλευσεν, ἕπεσθαι δ’ αὐτῷ. ταῦτα ὁ σκοπὸς ὁρῶν ἀπήγγειλεν Ἰωράμῳ τὸν ἱππέα συγκαταμιγέντα τῷ πλήθει τῶν προσιόντων σὺν ἐκείνοις παραγίνεσθαι. πέμψαντος δὲ καὶ δεύτερον τοῦ βασιλέως ταὐτὸ ποιεῖν προσέταξεν Ἰηοῦς. ὡς δὲ καὶ τοῦτ’ ἐδήλωσεν ὁ σκοπὸς Ἰωράμῳ, τελευταῖον αὐτὸς ἐπιβὰς ἅρματος σὺν Ὀχοζίᾳ τῷ τῶν Ἱεροσολυμιτῶν βασιλεῖ, παρῆν γὰρ αὐτὸς ὡς ἔφην ἔμπροσθεν ὀψόμενος αὐτὸν πῶς ἐκ τοῦ τραύματος ἔχοι διὰ συγγένειαν, ἐξῆλθεν ὑπαντησόμενος. σχολαίτερον δὲ καὶ μετ’ εὐταξίας ὥδευεν Ἰηοῦς. καταλαβὼν δὲ ἐν ἀγρῷ Ναβώθου τοῦτον Ἰώραμος ἐπυνθάνετο, εἰ πάντα ἔχοι καλῶς τὰ κατὰ τὸ στρατόπεδον· βλασφημήσαντος δὲ πικρῶς αὐτὸν Ἰηοῦ, ὡς καὶ τὴν μητέρα αὐτοῦ φαρμακὸν ἀποκαλέσαι, δείσας ὁ βασιλεὺς τὴν διάνοιαν αὐτοῦ καὶ μηδὲν ὑγιὲς φρονεῖν αὐτὸν ὑπονοήσας στρέψας ὡς εἶχε τὸ ἅρμα ἔφυγε, φήσας πρὸς Ὀχοζίαν ἐνέδρᾳ καὶ δόλῳ κατεστρατηγῆσθαι. Ἰηοῦς δὲ τοξεύσας αὐτὸν καταβάλλει τοῦ βέλους διὰ τῆς καρδίας ἐνεχθέντος. καὶ Ἰώραμος μὲν εὐθὺς πεσὼν ἐπὶ γόνυ τὴν ψυχὴν ἀφῆκεν, Ἰηοῦς δὲ προσέταξε Βαδάκῳ τῷ τῆς τρίτης μοίρας ἡγεμόνι ῥῖψαι τὸν Ἰωράμου νεκρὸν εἰς τὸν ἀγρὸν τὸν Ναβώθου ἀναμνήσας αὐτὸν τῆς Ἠλία προφητείας, ἣν Ἀχάβῳ τῷ πατρὶ αὐτοῦ τὸν Νάβωθον ἀποκτείναντι προεφήτευσεν, ὡς ἀπολεῖται αὐτός τε καὶ τὸ γένος αὐτοῦ ἐν τῷ ἐκείνου χωρίῳ· ταῦτα γὰρ καθεζόμενος ὄπισθεν τοῦ ἅρματος Ἀχάβου λέγοντος ἀκοῦσαι τοῦ προφήτου. καὶ δὴ τοῦτο συνέβη γενέσθαι κατὰ τὴν πρόρρησιν τὴν ἐκείνου. πεσόντος δὲ Ἰωράμου δείσας περὶ τῆς αὑτοῦ σωτηρίας Ὀχοζίας τὸ ἅρμα εἰς ἑτέραν [ὁδὸν] ἐξένευσε λήσεσθαι τὸν Ἰηοῦν ὑπολαβών. ὁ δ’ ἐπιδιώξας καὶ καταλαβὼν ἔν τινι προσβάσει τοξεύσας ἔτρωσε, καταλιπὼν δὲ τὸ ἅρμα καὶ ἀναβὰς ἵππῳ φεύγει τὸν Ἰηοῦν εἰς Μαγιαδδὼ κἀκεῖ θεραπευόμενος μετ’ ὀλίγον ἐκ τῆς πληγῆς τελευτᾷ. κομισθεὶς δ’ εἰς Ἱεροσόλυμα τῆς ἐκεῖ ταφῆς τυγχάνει βασιλεύσας μὲν ἐνιαυτὸν ἕνα, πονηρὸς δὲ καὶ χείρων τοῦ πατρὸς γενόμενος.", "st": "9.6.3"}, {"sp": "N", "t": "Τοῦ δὲ Ἰηοῦ εἰσελθόντος εἰς τὰ Ἱεζέρελα κοσμησαμένη Ἰεζαβέλα καὶ στᾶσα ἐπὶ τοῦ πύργου καλός, εἶπε, δοῦλος ὃς ἀποκτείνει τὸν δεσπότην. ὁ δὲ ἀναβλέψας πρὸς αὐτὴν ἐπυνθάνετο τίς εἴη καὶ καταβᾶσαν ἥκειν πρὸς αὑτὸν ἐκέλευσεν καὶ τέλος τοῖς εὐνούχοις προσέταξεν αὐτὴν ἀπὸ τοῦ πύργου βαλεῖν. καταφερομένη δ’ ἤδη τό τε τεῖχος περιέρρανε τῷ αἵματι καὶ συμπατηθεῖσα ὑπὸ τῶν ἵππων οὕτως ἀπέθανε. τούτων δὴ γενομένων παρελθὼν Ἰηοῦς εἰς τὰ βασίλεια σὺν τοῖς φίλοις ἑαυτὸν ἐκ τῆς ὁδοῦ ἀνεκτᾶτο τοῖς τε ἄλλοις καὶ τραπέζῃ. προσέταξε δὲ τοῖς οἰκέταις ἀνελομένοις τὴν Ἰεζαβέλαν θάψαι διὰ τὸ γένος· ἦν γὰρ ἐκ βασιλέων. εὗρον δ’ οὐδὲν τοῦ σώματος αὐτῆς οἱ προσταχθέντες τὴν κηδείαν ἢ μόνα τὰ ἀκρωτήρια, τὸ δὲ ἄλλο πᾶν ὑπὸ κυνῶν ἦν δεδαπανημένον. ταῦτ’ ἀκούσας Ἰηοῦς ἐθαύμαζε τὴν Ἠλίου προφητείαν· οὗτος γὰρ αὐτὴν ἐν Ἱεζερέλα προεῖπε τοῦτον ἀπολεῖσθαι τὸν τρόπον.", "st": "9.6.4"}, {"sp": "N", "t": "Ὄντων δ’ Ἀχάβῳ παίδων ἑβδομήκοντα τρεφομένων δ’ αὐτῶν ἐν Σαμαρείᾳ πέμπει δύο ἐπιστολὰς Ἰηοῦς τὴν μὲν τοῖς παιδαγωγοῖς τὴν ἑτέραν δὲ τοῖς ἄρχουσι τῶν Σαμαρέων, λέγων τὸν ἀνδρειότατον τῶν Ἀχάβου παίδων ἀποδεῖξαι βασιλέα· καὶ γὰρ ἁρμάτων αὐτῷ εἶναι πλῆθος καὶ ἵππων καὶ ὅπλων καὶ στρατιᾶς καὶ πόλεις ὀχυρὰς ἔχειν· καὶ τοῦτο ποιήσαντας εἰσπράττεσθαι δίκην ὑπὲρ τοῦ δεσπότου. ταῦτα δὲ γράφει διάπειραν βουλόμενος λαβεῖν τῆς τῶν Σαμαρέων διανοίας. ἀναγνόντες δὲ τὰ γράμματα οἵ τε ἄρχοντες καὶ οἱ παιδαγωγοὶ κατέδεισαν, καὶ λογισάμενοι μηδὲν δύνασθαι ποιεῖν πρὸς τοῦτο, δύο γὰρ μεγίστων ἐκράτησε βασιλέων, ἀντέγραψαν ὁμολογοῦντες αὐτὸν ἔχειν δεσπότην καὶ ποιήσειν ὃ ἂν κελεύῃ. ὁ δὲ πρὸς ταῦτα ἀντέγραψεν αὑτῷ τε ὑπακούειν κελεύων καὶ τῶν Ἀχάβου παίδων τὰς κεφαλὰς ἀποτεμόντας πέμψαι πρὸς αὐτόν. οἱ δὲ ἄρχοντες μεταπεμψάμενοι τοὺς τροφεῖς τῶν παίδων προσέταξαν ἀποκτείνασιν αὐτοὺς τὰς κεφαλὰς ἀποτεμεῖν καὶ πέμψαι πρὸς Ἰηοῦν. οἱ δ’ οὐδὲν ὅλως φεισάμενοι τοῦτο ἔπραξαν καὶ συνθέντες εἴς τινα πλεκτὰ ἀγγεῖα τὰς κεφαλὰς ἀπέπεμψαν εἰς Ἰεζέρελαν. κομισθεισῶν δὲ τούτων ἀγγέλλεται μετὰ τῶν φίλων δειπνοῦντι τῷ Ἰηοῦ, ὅτι κομισθεῖεν αἱ τῶν Ἀχάβου παίδων κεφαλαί. ὁ δὲ πρὸ τῆς πύλης ἐξ ἑκατέρου μέρους ἐκέλευσεν ἐξ αὐτῶν ἀναστῆσαι βουνούς. γενομένου δὲ τούτου ἅμα ἡμέρᾳ πρόεισιν ὀψόμενος καὶ θεασάμενος ἤρξατο πρὸς τὸν παρόντα λαὸν λέγειν, ὡς αὐτὸς μὲν ἐπὶ τὸν δεσπότην στρατεύσαιτο τὸν αὑτοῦ κἀκεῖνον ἀποκτείνειε, τούτους δὲ οὐκ αὐτὸς ἀνέλοι· γινώσκειν δὲ αὐτοὺς ἠξίου περὶ τῆς Ἀχάβου γενεᾶς, ὅτι πάντα κατὰ τὴν τοῦ θεοῦ προφητείαν γέγονε καὶ ὁ οἶκος αὐτοῦ, καθὼς καὶ Ἠλίας προεῖπεν, ἀπόλωλε. προσδιαφθείρας δὲ καὶ τοὺς παρὰ τοῖς Ἰεζερελίταις εὑρεθέντας ἐκ τῆς Ἀχάβου συγγενείας [ἱππεῖς] εἰς Σαμάρειαν ἐπορεύετο. κατὰ δὲ τὴν ὁδὸν τοῖς Ὀχοζία συμβαλὼν οἰκείοις τοῦ βασιλέως τῶν Ἱεροσολυμιτῶν ἀνέκρινεν αὐτούς, τί δή ποτε παρεγένοντο. οἱ δ’ ἀσπασόμενοί τε Ἰώραμον καὶ τὸν αὑτῶν βασιλέα Ὀχοζίαν ἥκειν ἔφασκον· οὐ γὰρ ᾔδεσαν αὐτοὺς ἀμφοτέρους ὑπ’ αὐτοῦ πεφονευμένους. Ἰηοῦς δὲ καὶ τούτους συλληφθέντας ἀναιρεθῆναι προσέταξεν ὄντας τὸν ἀριθμὸν τεσσαράκοντα καὶ δύο.", "st": "9.6.5"}, {"sp": "N", "t": "Συναντᾷ δ’ αὐτῷ μετὰ τούτους ἀνὴρ ἀγαθὸς καὶ δίκαιος Ἰωνάδαβος ὄνομα φίλος αὐτῷ πάλαι γεγονώς, ὃς ἀσπασάμενος αὐτὸν ἐπαινεῖν ἤρξατο τῷ πάντα κατὰ βούλησιν πεποιηκέναι τοῦ θεοῦ τὴν οἰκίαν ἐξαφανίσας τὴν Ἀχάβου. Ἰηοῦς δὲ ἀναβάντα ἐπὶ τὸ ἅρμα συνεισελθεῖν αὐτὸν εἰς Σαμάρειαν παρεκάλει λέγων ἐπιδείξειν, πῶς οὐδενὸς φείσεται πονηροῦ, ἀλλὰ καὶ τοὺς ψευδοπροφήτας καὶ τοὺς ψευδιερεῖς καὶ τοὺς ἐξαπατήσαντας τὸ πλῆθος, ὡς τὴν μὲν τοῦ μεγίστου θεοῦ θρησκείαν ἐγκαταλιπεῖν τοὺς δὲ ξενικοὺς προσκυνεῖν, τιμωρήσεται· κάλλιστον δ’ εἶναι θεαμάτων καὶ ἥδιστον ἀνδρὶ χρηστῷ καὶ δικαίῳ κολαζομένους πονηρούς. τούτοις πεισθεὶς ὁ Ἰωνάδαβος ἀναβὰς εἰς τὸ ἅρμα εἰς Σαμάρειαν παραγίνεται. ἀναζητήσας δὲ πάντας τοὺς Ἀχάβου συγγενεῖς Ἰηοῦς ἀποκτείνει. βουλόμενος δὲ μηδένα τῶν ψευδοπροφητῶν μηδ’ ἱερέων τῶν Ἀχάβου θεῶν τὴν τιμωρίαν διαφυγεῖν ἀπάτῃ καὶ δόλῳ πάντας αὐτοὺς συνέλαβεν· ἀθροίσας γὰρ τὸν λαὸν ἔφη βούλεσθαι διπλασίονας ὧν Ἄχαβος εἰσηγήσατο θεῶν προσκυνεῖν καὶ τοὺς ἐκείνων ἱερεῖς καὶ προφήτας ἠξίου καὶ δούλους αὐτῶν παρεῖναι· θυσίας γὰρ πολυτελεῖς καὶ μεγάλας ἐπιτελεῖν μέλλειν τοῖς Ἀχάβου θεοῖς· τὸν δ’ ἀπολειφθέντα τῶν ἱερέων θανάτῳ ζημιώσειν. ὁ δὲ θεὸς Ἀχάβου Βαὰλ ἐκαλεῖτο. τάξας δὲ ἡμέραν, καθ’ ἣν ἔμελλε ποιήσειν τὰς θυσίας διέπεμπεν ἀνὰ πᾶσαν τὴν Ἰσραηλιτῶν χώραν τοὺς ἄξοντας πρὸς αὐτὸν τοὺς ἱερεῖς τοῦ Βαάλ. ἐκέλευσε δ’ Ἰηοῦς τῷ ἱερεῖ δοῦναι πᾶσιν ἐνδύματα· λαβόντων δὲ παρελθὼν εἰς τὸν οἶκον μετὰ τοῦ φίλου Ἰωναδάβου μή τις ἐν αὐτοῖς ἀλλόφυλος εἴη καὶ ξένος ἐρευνῆσαι προσέταξεν· οὐ βούλεσθαι γὰρ τοῖς ἱεροῖς αὐτῶν ἀλλότριον παρατυγχάνειν. τῶν δὲ εἰπόντων μὲν οὐδένα παρεῖναι ξένον καταρξαμένων δὲ τῶν θυσιῶν περιέστησεν ὀγδοήκοντα τὸν ἀριθμὸν ἄνδρας, οὓς ᾔδει πιστοτάτους τῶν ὁπλιτῶν, κελεύσας αὐτοῖς ἀποκτεῖναι τοὺς ψευδοπροφήτας καὶ νῦν τοῖς πατρίοις ἔθεσι τιμωρεῖν πολὺν ἤδη χρόνον ὠλιγωρημένοις, ὑπὲρ τῶν διαφυγόντων τὰς ἐκείνων ἀφαιρεθήσεσθαι ψυχὰς ἀπειλήσας. οἱ δὲ τούς τε ἄνδρας ἅπαντας κατέσφαξαν καὶ τὸν οἶκον τοῦ Βαὰλ ἐμπρήσαντες ἐκάθηραν οὕτως ἀπὸ τῶν ξενικῶν ἐθισμῶν τὴν Σαμάρειαν. οὗτος ὁ Βαὰλ Τυρίων ἦν θεός. Ἄχαβος δὲ τῷ πενθερῷ βουλόμενος χαρίσασθαι Εἰθωβάλῳ Τυρίων ὄντι βασιλεῖ καὶ Σιδωνίων ναόν τε αὐτῷ κατεσκεύασεν ἐν Σαμαρείᾳ καὶ προφήτας ἀπέδειξε καὶ πάσης θρησκείας ἠξίου. ἀφανισθέντος δὲ τούτου τοῦ θεοῦ τὰς χρυσᾶς δαμάλεις προσκυνεῖν τοῖς Ἰσραηλίταις Ἰηοῦς ἐπέτρεψε. ταῦτα δὲ διαπραξαμένῳ καὶ προνοήσαντι τῆς κολάσεως τῶν ἀσεβῶν ὁ θεὸς διὰ τοῦ προφήτου προεῖπεν ἐπὶ τέσσαρας γενεὰς τοὺς παῖδας αὐτοῦ βασιλεύσειν τῶν Ἰσραηλιτῶν. καὶ τὰ μὲν περὶ Ἰηοῦν ἐν τούτοις ὑπῆρχεν.", "st": "9.6.6"}, {"sp": "N", "t": "Ὀθλία δ’ ἡ Ἀχάβου θυγάτηρ ἀκούσασα τήν τ’ Ἰωράμου τἀδελφοῦ τελευτὴν καὶ τὴν Ὀχοζία τοῦ παιδὸς καὶ τοῦ γένους τῶν βασιλέων τὴν ἀπώλειαν ἐσπούδαζε μηδένα τῶν ἐκ τοῦ Δαυίδου καταλιπεῖν οἴκου, πᾶν δ’ ἐξαφανίσαι τὸ γένος, ὡς ἂν μηδὲ εἷς ἐξ αὐτοῦ βασιλεὺς ἔτι γένοιτο. καὶ τοῦθ’ ὡς μὲν ᾤετο διεπράξατο, διεσώθη δὲ εἷς υἱὸς Ὀχοζίου, τρόπῳ δὲ τοιούτῳ τὴν τελευτὴν διέφυγεν· ἦν Ὀχοζίᾳ ὁμοπάτριος ἀδελφὴ Ὠσαβέθη ὄνομα· ταύτῃ συνῆν ὁ ἀρχιερεὺς Ἰώδας. εἰσελθοῦσα δ’ εἰς τὸ βασίλειον καὶ τοῖς ἀπεσφαγμένοις τὸν Ἰώασον, τοῦτο γὰρ προσηγορεύετο τὸ παιδίον ἐνιαύσιον, ἐγκεκρυμμένον εὑροῦσα μετὰ τῆς τρεφούσης βαστάσασα μετ’ αὐτῆς εἰς τὸ ταμιεῖον ἀπέκλεισε τῶν κλινῶν καὶ λανθάνοντες ἀνέθρεψαν αὐτή τε καὶ ὁ ἀνὴρ αὐτῆς Ἰώδας ἐν τῷ ἱερῷ ἔτεσιν ἕξ, οἷς ἐβασίλευσεν Ὀθλία τῶν Ἱεροσολύμων καὶ τῶν δύο φυλῶν.", "st": "9.7.1"}, {"sp": "N", "t": "Τῷ δὲ ἑβδόμῳ κοινολογησάμενός τισιν Ἰώδας πέντε τὸν ἀριθμὸν ἑκατοντάρχαις καὶ πείσας αὐτοὺς συνεπιθέσθαι μὲν τοῖς κατὰ τῆς Ὀθλίας ἐγχειρουμένοις, τὴν δὲ βασιλείαν τῷ παιδὶ περιποιῆσαι, λαβὼν ὅρκους οἷς τὸ ἀδεὲς παρὰ τῶν συνεργούντων βεβαιοῦται τὸ λοιπὸν ἐθάρρει ταῖς κατὰ τῆς Ὀθλίας ἐλπίσιν. οἱ δ’ ἄνδρες, οὓς ὁ ἱερεὺς Ἰώδας κοινωνοὺς τῆς πράξεως παρειλήφει, περιπορευθέντες ἅπασαν τὴν χώραν τοὺς ἱερεῖς καὶ τοὺς Ληουίτας ἐξ αὐτῆς ἀθροίσαντες καὶ τοὺς τῶν φυλῶν προεστηκότας ἧκον ἄγοντες εἰς Ἱεροσόλυμα πρὸς τὸν ἀρχιερέα. ὁ δὲ πίστιν ᾔτησεν αὐτοὺς ἔνορκον, ἦ μὴν φυλάξειν ὅπερ ἂν μάθωσιν ἀπόρρητον παρ’ αὐτοῦ σιωπῆς ἅμα καὶ συμπράξεως δεόμενον. ὡς δ’ ἀσφαλὲς αὐτῷ λέγειν ὀμωμοκότων ἐγένετο παραγαγὼν ὃν ἐκ τοῦ Δαυίδου γένους ἔτρεφεν οὗτος ἡμῖν, εἶπε, βασιλεὺς ἐξ ἐκείνης τῆς οἰκίας, ἣν ἴστε τὸν θεὸν ἡμῖν προφητεύσαντα βασιλεύσειν ἄχρι τοῦ παντὸς χρόνου. παραινῶ δὲ τὴν τρίτην ὑμῶν μοῖραν φυλάττειν αὐτὸν ἐν τῷ ἱερῷ, τὴν δὲ τρίτην ταῖς πύλαις ἐφεστάναι τοῦ τεμένους ἁπάσαις, ἡ δὲ μετὰ ταύτην ἐχέτω τὴν τῆς ἀνοιγομένης καὶ φερούσης εἰς τὸ βασίλειον πύλης φυλακήν· τὸ δὲ ἄλλο πλῆθος ἄοπλον ἐν τῷ ἱερῷ τυγχανέτω· μηδένα δ’ εἰσελθεῖν ὁπλίτην ἐάσητε ἢ μόνον ἱερέα. προσδιέταξε δὲ τούτοις μέρος τι τῶν ἱερέων καὶ Ληουίτας περὶ αὐτὸν εἶναι τὸν βασιλέα ταῖς μαχαίραις ἐσπασμέναις αὐτὸν δορυφοροῦντας, τὸν δὲ τολμήσαντα παρελθεῖν εἰς τὸ ἱερὸν ὡπλισμένον ἀναιρεῖσθαι παραυτίκα· δείσαντας δὲ μηδὲν παραμεῖναι τῇ φυλακῇ τοῦ βασιλέως. καὶ οἱ μὲν οἷς ὁ ἀρχιερεὺς συνεβούλευσεν τούτοις πεισθέντες ἔργῳ τὴν προαίρεσιν ἐδήλουν. ἀνοίξας δὲ Ἰώδας τὴν ἐν τῷ ἱερῷ ὁπλοθήκην, ἣν Δαυίδης κατεσκεύασε, διεμέρισε τοῖς ἑκατοντάρχαις ἅμα καὶ ἱερεῦσι καὶ Ληουίταις ἅπανθ’ ὅσ’ εὗρεν ἐν αὐτῇ δόρατά τε καὶ φαρέτρας καὶ εἴ τι ἕτερον εἶδος ὅπλου κατέλαβε, καὶ καθωπλισμένους ἔστησεν ἐν κύκλῳ περὶ τὸ ἱερὸν συναψαμένους τὴν χεῖρα καὶ τὴν εἴσοδον τοῖς οὐ προσήκουσιν οὕτως ἀποτειχίσοντας. συναγαγόντες δὲ τὸν παῖδα εἰς τὸ μέσον ἐπέθεσαν αὐτῷ τὸν στέφανον τὸν βασιλικὸν καὶ τῷ ἐλαίῳ χρίσας Ἰώδας ἀπέδειξε βασιλέα· τὸ δὲ πλῆθος χαῖρον καὶ κροταλίζον ἐβόα σώζεσθαι τὸν βασιλέα.", "st": "9.7.2"}, {"sp": "N", "t": "Τοῦ δὲ θορύβου καὶ τῶν ἐπαίνων Ὀθλία παρ’ ἐλπίδας ἀκούσασα τεταραγμένη σφόδρα τῇ διανοίᾳ μετὰ τῆς ἰδίας ἐξεπήδησε στρατιᾶς ἐκ τοῦ βασιλείου. καὶ παραγενομένην εἰς τὸ ἱερὸν αὐτὴν οἱ μὲν ἱερεῖς εἰσδέχονται, τοὺς δ’ ἑπομένους ὁπλίτας εἶρξαν εἰσελθεῖν οἱ περιεστῶτες ἐν κύκλῳ ὑπὸ τοῦ ἀρχιερέως τοῦτο προστεταγμένοι. ἰδοῦσα δὲ Ὀθλία τὸν παῖδα ἐπὶ τῆς σκηνῆς ἑστῶτα καὶ τὸν βασίλειον ἐπικείμενον στέφανον περιρρηξαμένη καὶ δεινὸν ἀνακραγοῦσα φονεύειν ἐκέλευε τὸν ἐπιβουλεύσαντα αὐτῇ καὶ τὴν ἀρχὴν ἀφελέσθαι σπουδάσαντα. Ἰώδας δὲ καλέσας τοὺς ἑκατοντάρχας ἐκέλευσεν αὐτοὺς ἀπαγαγόντας τὴν Ὀθλίαν εἰς τὴν φάραγγα τὴν Κεδρῶνος ἀνελεῖν αὐτὴν ἐκεῖ· μὴ γὰρ βούλεσθαι μιᾶναι τὸ ἱερὸν αὐτόθι τὴν ἀλιτήριον τιμωρησάμενον. προσέταξε δὲ κἂν βοηθῶν τις προσέλθῃ κἀκεῖνον ἀνελεῖν. ἐλλαβόμενοι τοίνυν τῆς Ὀθλίας οἱ προστεταγμένοι τὴν ἀναίρεσιν αὐτῆς ἐπὶ τὴν πύλην τῶν ἡμιόνων τοῦ βασιλέως ἤγαγον κἀκεῖ διεχρήσαντο.", "st": "9.7.3"}, {"sp": "N", "t": "Ὡς δὲ τὰ περὶ τὴν Ὀθλίαν τοῦτον ἐστρατηγήθη τὸν τρόπον συγκαλέσας τόν τε δῆμον καὶ τοὺς ὁπλίτας ὁ Ἰώδας εἰς τὸ ἱερὸν ἐξώρκωσεν εὐνοεῖν τῷ βασιλεῖ καὶ προνοεῖν αὐτοῦ τῆς σωτηρίας καὶ τῆς ἐπὶ πλεῖον ἀρχῆς· ἔπειτ’ αὐτὸν τὸν βασιλέα τιμήσειν τὸν θεὸν καὶ μὴ παραβῆναι τοὺς Μωσήους νόμους δοῦναι πίστιν ἠνάγκασε. καὶ μετὰ ταῦτ’ εἰσδραμόντες τὸν τοῦ Βαὰλ οἶκον, ὃν Ὀθλία τε καὶ ὁ ἀνὴρ αὐτῆς Ἰώραμος κατεσκεύασεν ἐφ’ ὕβρει μὲν τοῦ πατρίου θεοῦ τιμῇ δὲ Ἀχάβου κατέσκαψαν καὶ τὸν ἔχοντα τὴν ἱερωσύνην αὐτοῦ Μάθαν ἀπέκτειναν. τὴν δ’ ἐπιμέλειαν καὶ φυλακὴν τοῦ ἱεροῦ τοῖς ἱερεῦσι καὶ Ληουίταις ἐπέτρεψεν Ἰώδας κατὰ τὴν Δαυίδου τοῦ βασιλέως διάταξιν κελεύσας αὐτοὺς δὶς τῆς ἡμέρας ἐπιφέρειν τὰς νενομισμένας τῶν ὁλοκαυτώσεων θυσίας καὶ θυμιᾶν ἀκολούθως τῷ νόμῳ. ἀπέδειξε δέ τινας τῶν Ληουιτῶν καὶ πυλωροὺς ἐπὶ φυλακῇ τοῦ τεμένους, ὡς μηδένα μεμιασμένον παριέναι λανθάνοντα.", "st": "9.7.4"}, {"sp": "N", "t": "Τούτων δ’ ἕκαστα διατάξας μετὰ τῶν ἑκατοντάρχων καὶ ἡγεμόνων καὶ τοῦ λαοῦ παντὸς ἐκ τοῦ ἱεροῦ παραλαβὼν ἄγει τὸν Ἰώασον εἰς τὸ βασίλειον, καὶ καθίσαντος ἐπὶ τὸν βασιλικὸν θρόνον ἐπευφήμησέ τε τὸ πλῆθος καὶ πρὸς εὐωχίαν τραπέντες ἐπὶ πολλὰς ἑώρτασαν ἡμέρας· ἡ μέντοι γε πόλις ἐπὶ τῷ τὴν Ὀθλίαν ἀποθανεῖν ἡσυχίαν ἤγαγεν. ἦν δὲ Ἰώασος ὅτε τὴν βασιλείαν παρέλαβεν ἐτῶν ἑπτά, μήτηρ δὲ ἦν αὐτῷ τὸ μὲν ὄνομα Σαβιὰ πατρίδος δὲ Βηρσαβεέ. πολλὴν δ’ ἐποιήσατο τῶν νομίμων φυλακὴν καὶ περὶ τὴν τοῦ θεοῦ θρησκείαν φιλοτιμίαν παρὰ πάντα τὸν χρόνον ὃν Ἰώδας ἐβίωσεν. ἔγημε δὲ καὶ γυναῖκας δύο παρελθὼν εἰς ἡλικίαν δόντος τοῦ ἀρχιερέως, ἐξ ὧν καὶ ἄρρενες αὐτῷ καὶ θήλειαι παῖδες ἐγένοντο. τὰ μὲν οὖν περὶ τοῦ βασιλέως Ἰωάσου, ὡς τὴν τῆς Ὀθλίας ἐπιβουλὴν διέφυγε καὶ τὴν βασιλείαν παρέλαβεν, ἐν τούτοις δεδηλώκαμεν.", "st": "9.7.5"}, {"sp": "N", "t": "Ἀζάηλος δ’ ὁ τῶν Σύρων βασιλεὺς πολεμῶν τοῖς Ἰσραηλίταις καὶ τῷ βασιλεῖ αὐτῶν Ἰηοῦ διέφθειρε τῆς πέραν Ἰορδάνου χώρας τὰ πρὸς τὴν ἀνατολὴν τῶν Ῥουβηνιτῶν καὶ Γαδιτῶν καὶ Μανασσιτῶν ἔτι δὲ καὶ τὴν Γαλαδῖτιν καὶ Βαταναίαν πυρπολῶν πάντα καὶ διαρπάζων καὶ τοῖς εἰς χεῖρας ἀπαντῶσι βίαν προσφέρων. οὐ γὰρ ἔφθη αὐτὸν Ἰηοῦς ἀμύνασθαι κακοῦντα τὴν χώραν, ἀλλὰ καὶ τῶν εἰς τὸ θεῖον ὑπερόπτης γενόμενος καὶ καταφρονήσας τῆς ὁσίας καὶ τῶν νόμων ἀπέθανε βασιλεύσας ἔτη τῶν Ἰσραηλιτῶν ἑπτὰ καὶ εἴκοσι. ἐτάφη δὲ ἐν Σαμαρείᾳ τῆς ἀρχῆς διάδοχον Ἰώαζον τὸν υἱὸν καταλιπών.", "st": "9.8.1"}, {"sp": "N", "t": "Τὸν δὲ τῶν Ἱεροσολυμιτῶν βασιλέα Ἰώασον ὁρμή τις ἔλαβε τὸν ναὸν ἀνακαινίσαι τοῦ θεοῦ, καὶ τὸν ἀρχιερέα καλέσας Ἰώδαν εἰς ἅπασαν ἐκέλευσε πέμψαι τὴν χώραν τοὺς Ληουίτας καὶ ἱερέας αἰτήσοντας ὑπὲρ ἑκάστης κεφαλῆς ἡμίσικλον ἀργύρου εἰς ἐπισκευὴν καὶ ἀνανέωσιν τοῦ ναοῦ καταλυθέντος ὑπὸ Ἰωράμου καὶ Ὀθλίας καὶ τῶν παίδων αὐτῆς. ὁ δ’ ἀρχιερεὺς τοῦτο μὲν οὐκ ἐποίησε συνεὶς ὡς οὐδεὶς προεῖται τἀργύριον, τρίτῳ δὲ καὶ εἰκοστῷ τῆς βασιλείας ἔτει μεταπεμψαμένου τοῦ βασιλέως αὐτόν τε καὶ Ληουίτας καὶ ὡς παρακούσαντας ὧν προσέταξεν αἰτιωμένου καὶ κελεύσαντος εἰς τὸ μέλλον προνοεῖσθαι τῆς ἐπισκευῆς τοῦ ναοῦ, στρατηγήματι χρῆται πρὸς τὴν συλλογὴν τῶν χρημάτων ὁ ἀρχιερεὺς ᾧ τὸ πλῆθος ἡδέως ἔσχε τοιούτῳ· ξύλινον κατασκευάσας θησαυρὸν καὶ κλείσας πανταχόθεν ὀπὴν αὐτῷ μίαν ἤνοιξεν. ἔπειτα θεὶς εἰς τὸ ἱερὸν παρὰ τὸν βωμὸν ἐκέλευσεν ἕκαστον ὅσον βούλεται βάλλειν εἰς αὐτὸν διὰ τῆς ὀπῆς εἰς τὴν ἐπισκευὴν τοῦ ναοῦ. πρὸς τοῦτο πᾶς ὁ λαὸς εὖ διετέθη καὶ πολὺν ἄργυρον καὶ χρυσὸν φιλοτιμούμενοι καὶ συνεισφέροντες ἤθροισαν. κενοῦντες δὲ τὸν θησαυρὸν καὶ παρόντος τοῦ βασιλέως ἀριθμοῦντες τὸ συνειλεγμένον ὅ τε γραμματεὺς [καὶ ἱερεὺς] τῶν γαζοφυλακίων ἔπειτ’ εἰς τὸν αὐτὸν ἐτίθεσαν τόπον. καὶ τοῦτ’ ἐποίουν ἑκάστης ἡμέρας. ὡς δ’ ἀποχρῶν τὸ πλῆθος ἐδόκει τῶν χρημάτων ἔπεμψαν μισθούμενοι λατόμους καὶ οἰκοδόμους ὁ ἀρχιερεὺς Ἰώδας καὶ ὁ βασιλεὺς Ἰώασος καὶ ἐπὶ ξύλα μεγάλα καὶ τῆς καλλίστης ὕλης. ἐπισκευασθέντος δὲ τοῦ ναοῦ τὸν ὑπολειφθέντα χρυσὸν καὶ ἄργυρον, οὐκ ὀλίγος δὲ ἦν, εἴς τε κρατῆρας καὶ οἰνοχόας καὶ ἐκπώματα καὶ τὰ λοιπὰ σκεύη κατεχρήσαντο θυσίαις τε πολυτελέσιν ὁσημέραι τὸν βωμὸν πιαίνοντες διετέλουν. καὶ ταῦτα μὲν ἐφ’ ὅσον Ἰώδας χρόνον ἔζη τῆς προσηκούσης ἐτύγχανε σπουδῆς.", "st": "9.8.2"}, {"sp": "N", "t": "Ὡς δ’ ἐτελεύτησεν οὗτος ἔτη μὲν βιώσας ἑκατὸν καὶ τριάκοντα δίκαιος δὲ καὶ πάντα χρηστὸς γενόμενος, ἐτάφη δ’ ἐν ταῖς βασιλικαῖς θήκαις ἐν Ἱεροσολύμοις, ὅτι τῷ Δαυίδου γένει τὴν βασιλείαν ἀνεκτήσατο, προέδωκεν ὁ βασιλεὺς τὴν ἐπιμέλειαν τὴν πρὸς τὸν θεόν. συνδιεφθάρησαν δ’ αὐτῷ καὶ οἱ τοῦ πλήθους πρωτεύοντες, ὥστε πλημμελεῖν εἰς τὰ δίκαια καὶ νενομισμένα παρ’ αὐτοῖς ἄριστα εἶναι. δυσχεράνας δὲ ὁ θεὸς ἐπὶ τῇ μεταβολῇ τοῦ βασιλέως καὶ τῶν ἄλλων πέμπει τοὺς προφήτας διαμαρτυρησομένους τε τὰ πραττόμενα καὶ παύσοντας τῆς πονηρίας αὐτούς. οἱ δ’ ἰσχυρὸν ἔρωτα καὶ δεινὴν ἐπιθυμίαν ἄρα ταύτης εἶχον, ὡς μήτε οἷς οἱ πρὸ αὐτῶν ἐξυβρίσαντες εἰς τὰ νόμιμα πανοικὶ κολασθέντες ἔπαθον, μήθ’ οἷς οἱ προφῆται προύλεγον πεισθέντες μετανοῆσαι καὶ μετελθεῖν ἐξ ὧν εἰς ἐκεῖνα παρανομήσαντες ἐτράπησαν· ἀλλὰ καὶ Ζαχαρίαν υἱὸν τοῦ ἀρχιερέως Ἰώδα λίθοις ὁ βασιλεὺς ἐκέλευσε βληθέντα ἀποθανεῖν ἐν τῷ ἱερῷ τῶν τοῦ πατρὸς εὐεργεσιῶν αὐτοῦ λαθόμενος, ὅτι τοῦ θεοῦ προφητεύειν αὐτὸν ἀποδείξαντος στὰς ἐν μέσῳ τῷ πλήθει συνεβούλευεν αὐτῷ τε καὶ τῷ βασιλεῖ τὰ δίκαια πράττειν καὶ τιμωρίαν ὅτι μεγάλην ὑφέξουσι μὴ πειθόμενοι προύλεγε. τελευτῶν μέντοι Ζαχαρίας μάρτυρα καὶ δικαστὴν ὧν ἔπασχε τὸν θεὸν ἐποιεῖτο ἀντὶ χρηστῆς συμβουλίας καὶ ὧν ὁ πατὴρ αὐτοῦ παρέσχεν Ἰωάσῳ πικρῶς καὶ βιαίως ἀπολλύμενος.", "st": "9.8.3"}, {"sp": "N", "t": "Ἔδωκε μέντοι γε οὐκ εἰς μακρὰν ὁ βασιλεὺς δίκην ὧν παρηνόμησεν· ἐμβαλόντος γὰρ Ἀζαήλου τοῦ Σύρων βασιλέως εἰς τὴν χώραν αὐτοῦ καὶ τὴν Γίτταν καταστρεψαμένου καὶ λεηλατήσαντος ἐπ’ αὐτὸν στρατεύειν εἰς Ἱεροσόλυμα φοβηθεὶς ὁ Ἰώασος πάντας ἐκκενώσας τοὺς τοῦ θεοῦ θησαυροὺς καὶ τοὺς τῶν βασιλείων καὶ τὰ ἀναθήματα καθελών, ἔπεμψε τῷ Σύρῳ τούτοις ὠνούμενος τὸ μὴ πολιορκηθῆναι μηδὲ κινδυνεύειν περὶ τῶν ὅλων. ὁ δὲ πεισθεὶς τῇ τῶν χρημάτων ὑπερβολῇ τὴν στρατιὰν οὐκέτ’ ἤγαγεν ἐπὶ τὰ Ἱεροσόλυμα. νόσῳ μέντοι χαλεπῇ περιπεσὼν ὁ Ἰώασος ἐπιθεμένων αὐτῷ τῶν φίλων, οἳ τὸν Ζαχαρίου θάνατον ἐκδικοῦντες τοῦ Ἰώδα παιδὸς ἐπεβούλευσαν τῷ βασιλεῖ, διεφθάρη πρὸς αὐτῶν· καὶ θάπτεται μὲν ἐν Ἱεροσολύμοις, οὐκ ἐν ταῖς θήκαις δὲ τῶν προγόνων ἀσεβὴς γενόμενος. ἐβίωσε δὲ ἔτη ἑπτὰ καὶ τεσσαράκοντα, τὴν δὲ βασιλείαν αὐτοῦ διαδέχεται Ἀμασίας ὁ παῖς.", "st": "9.8.4"}, {"sp": "N", "t": "Εἰκοστῷ δὲ καὶ πρώτῳ τῆς Ἰωάσου βασιλείας παρέλαβε τὴν τῶν Ἰσραηλιτῶν ἡγεμονίαν Ἰώαζος ὁ τοῦ Ἰηοῦδος υἱὸς ἐν Σαμαρείᾳ καὶ κατέσχεν αὐτὴν ἔτεσιν ἑπτὰ καὶ δέκα τοῦ μὲν πατρὸς οὐδ’ αὐτὸς μιμητὴς γενόμενος, ἀσεβήσας δ’ ὅσα καὶ οἱ πρῶτοι τοῦ θεοῦ καταφρονήσαντες. ἐταπείνωσε δ’ αὐτὸν καὶ συνέστειλεν ἐκ τῆς τοσαύτης δυνάμεως ὁ τῶν Σύρων βασιλεὺς εἰς ὁπλίτας μυρίους καὶ πεντήκοντα ἱππεῖς στρατεύσας ἐπ’ αὐτὸν καὶ πόλεις τε μεγάλας καὶ πολλὰς αὐτοῦ ἀφελόμενος καὶ τὴν στρατιὰν αὐτοῦ διαφθείρας. ταῦτα δ’ ἔπαθεν ὁ τῶν Ἰσραηλιτῶν λαὸς κατὰ τὴν Ἐλισσαίου προφητείαν, ὅτε Ἀζάηλον βασιλεύσειν προεῖπε τῶν Σύρων καὶ Δαμασκηνῶν ἀποκτείναντα τὸν δεσπότην. ὢν δὲ ἐν οὕτως ἀπόροις κακοῖς Ἰώαζος ἐπὶ δέησιν καὶ ἱκετείαν τοῦ θεοῦ κατέφυγε ῥύσασθαι τῶν Ἀζαήλου χειρῶν αὐτὸν παρακαλῶν καὶ μὴ περιϊδεῖν ὑπ’ ἐκείνῳ γενόμενον. ὁ δὲ θεὸς καὶ τὴν μετάνοιαν ὡς ἀρετὴν ἀποδεχόμενος καὶ νουθετεῖν μᾶλλον τοὺς δυναμένους τελέως μὴ ἀπολλύειν δοκοῦν αὐτῷ, δίδωσιν αὐτῷ τὴν ἐκ τοῦ πολέμου καὶ τῶν κινδύνων ἄδειαν. εἰρήνης δ’ ἡ χώρα λαβομένη ἀνέδραμέ τε πάλιν εἰς τὴν προτέραν κατάστασιν καὶ εὐθήνησε.", "st": "9.8.5"}, {"sp": "N", "t": "Μετὰ δὲ τὴν Ἰωάζου τελευτὴν ἐκδέχεται τὴν ἀρχὴν ὁ υἱὸς αὐτοῦ Ἰώασος. ἕβδομον ἤδη καὶ τριακοστὸν ἔτος βασιλεύοντος Ἰωάσου τῆς Ἰούδα φυλῆς παρέλαβε τὴν ἀρχὴν οὗτος ὁ Ἰώασος ἐν Σαμαρείᾳ τῶν Ἰσραηλιτῶν· καὶ γὰρ αὐτὸς τὴν αὐτὴν εἶχε προσηγορίαν τῷ τῶν Ἱεροσολυμιτῶν βασιλεῖ· καὶ κατέσχεν αὐτὴν ἔτεσιν ἑκκαίδεκα. ἀγαθὸς δ’ ἦν καὶ οὐδὲν ὅμοιος τῷ πατρὶ τὴν φύσιν. κατ’ ἐκεῖνον δὲ τὸν καιρὸν Ἐλισσαίου τοῦ προφήτου γηραιοῦ μὲν ἤδη τυγχάνοντος εἰς δὲ νόσον ἐμπεπτωκότος ἧκεν ὁ τῶν Ἰσραηλιτῶν βασιλεὺς πρὸς αὐτὸν ἐπισκεψόμενος. καταλαβὼν δὲ αὐτὸν ἐν ἐσχάτοις ὄντα κλαίειν ἤρξατο [βλέποντος αὐτοῦ] καὶ ποτνιᾶσθαι καὶ πατέρα τε ἀποκαλεῖν καὶ ὅπλον· δι’ αὐτὸν γὰρ μηδέποτε χρήσασθαι πρὸς τοὺς ἐχθροὺς ὅπλοις, ἀλλὰ ταῖς ἐκείνου προφητείαις ἀμαχητὶ κρατεῖν τῶν πολεμίων· νῦν δ’ ἀπιέναι μὲν αὐτὸν ἐκ τοῦ ζῆν, καταλείπειν δ’ ἐξωπλισμένον τοῖς Σύροις καὶ τοῖς ἀπ’ αὐτῶν πολεμίοις. οὐδ’ αὐτῷ τοίνυν ζῆν ἔτι ἀσφαλὲς ἔλεγεν, ἀλλὰ καλῶς ἔχειν συνεξορμᾶν αὐτῷ καὶ συναπαίρειν ἐκ τοῦ βίου. ταῦτ’ ὀδυρόμενον Ἐλισσαῖος παρεμυθεῖτο τὸν βασιλέα καὶ τόξον ἐκέλευσεν αὐτῷ κομισθὲν ἐντεῖναι τοῦτο. ποιήσαντος οὖν εὐτρεπὲς τοῦ βασιλέως τὸ τόξον, ἐπιλαβόμενον τῶν χειρῶν αὐτοῦ ἐκέλευσεν αὐτὸν τοξεύειν. τρία βέλη δ’ αὐτοῦ προεμένου εἶτα δ’ ἀναπαυσαμένου πλείω μέν, εἶπεν, ἀφεὶς ἐκ ῥιζῶν ἂν τὴν τῶν Σύρων βασιλείαν ἐξεῖλες, ἐπεὶ δὲ τρισὶν ἠρκέσθης μόνοις, τοσαύταις καὶ μάχαις κρατήσεις συμβαλὼν τοῖς Σύροις, ἵνα τὴν χώραν ἣν ἀπετέμοντο τοῦ σοῦ πατρὸς ἀνακτήσῃ· καὶ ὁ μὲν βασιλεὺς τοῦτ’ ἀκούσας ἀπηλλάγη. μετ’ οὐ πολὺ δὲ καὶ ὁ προφήτης ἀπέθανεν ἀνὴρ ἐπὶ δικαιοσύνῃ διαβόητος καὶ φανερῶς σπουδασθεὶς ὑπὸ τοῦ θεοῦ· θαυμαστὰ γὰρ καὶ παράδοξα διὰ τῆς προφητείας ἐπεδείξατο ἔργα καὶ μνήμης λαμπρᾶς παρὰ τοῖς Ἑβραίοις ἀξιωθέντα. ἔτυχε δὲ καὶ ταφῆς μεγαλοπρεποῦς καὶ οἵας εἰκὸς ἦν τὸν οὕτω θεοφιλῆ μεταλαβεῖν. συνέβη δὲ καὶ τότε, λῃστῶν τινων ῥιψάντων εἰς τὸν Ἐλισσαίου τάφον ὃν ἦσαν ἀνῃρηκότες, τὸν νεκρὸν τῷ σώματι αὐτοῦ προσκολληθέντα ἀναζωπυρῆσαι. καὶ τὰ μὲν περὶ Ἐλισσαίου τοῦ προφήτου, ζῶν τε ὅσα προεῖπε καὶ ὡς μετὰ τὴν τελευτὴν ἔτι δύναμιν εἶχε θείαν, ἤδη δεδηλώκαμεν.", "st": "9.8.6"}, {"sp": "N", "t": "Τελευτήσαντος δὲ τοῦ Σύρων βασιλέως Ἀζαήλου εἰς Ἀδδὰν τὸν υἱὸν αὐτοῦ ἡ βασιλεία παραγίνεται· πρὸς τοῦτον συνάπτει πόλεμον Ἰώασος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς καὶ τρισὶ μάχαις νικήσας αὐτὸν ἀφείλετο τὴν χώραν ἅπασαν καὶ ὅσας ὁ πατὴρ αὐτοῦ Ἀζάηλος πόλεις καὶ κώμας τῆς Ἰσραηλιτῶν βασιλείας παρέλαβε. τοῦτο μέντοι κατὰ τὴν Ἐλισσαίου προφητείαν ἐγένετο. ἐπεὶ δὲ συνέβη καὶ Ἰώασον ἀποθανεῖν, ὁ μὲν ἐν Σαμαρείᾳ κηδεύεται, καθῆκε δὲ εἰς Ἰώασον ἡ ἀρχὴ τὸν υἱὸν αὐτοῦ.", "st": "9.8.7"}, {"sp": "N", "t": "Δευτέρῳ δ’ ἔτει τῆς Ἰωάσου βασιλείας τῶν Ἰσραηλιτῶν ἐβασίλευσεν Ἀμασίας τῆς Ἰούδα φυλῆς ἐν Ἱεροσολύμοις μητρὸς ὢν Ἰωάδη τοὔνομα πολίτιδος δὲ τὸ γένος· θαυμαστῶς δὲ τοῦ δικαίου προυνόει καὶ ταῦτα νέος ὤν. παρελθὼν δ’ ἐπὶ τὰ πράγματα καὶ τὴν ἀρχὴν ἔγνω δεῖν πρῶτον Ἰωάσῳ τιμωρῆσαι τῷ πατρὶ καὶ τοὺς ἐπιθεμένους αὐτῷ φίλους κολάσαι. καὶ τούτους μὲν συλλαβὼν ἅπαντας ἐφόνευσε, τοὺς δὲ παῖδας αὐτῶν οὐδὲν εἰργάσατο δεινὸν ἀκόλουθα ποιῶν τοῖς Μωσήους νόμοις, ὃς οὐκ ἐδικαίωσε διὰ πατέρων ἁμαρτίας τέκνα κολάζειν. ἔπειτα στρατιὰν ἐπιλέξας ἐκ τῆς Ἰούδα φυλῆς καὶ Βενιαμίδος τῶν ἐν ἀκμῇ καὶ περὶ εἴκοσι ἔτη γεγονότων καὶ συναθροίσας ὡς τριάκοντα μυριάδας τούτων μὲν ἑκατοντάρχους κατέστησε, πέμψας δὲ καὶ πρὸς τὸν Ἰσραηλιτῶν βασιλέα μισθοῦται δέκα μυριάδας ὁπλιτῶν ἑκατὸν ἀργυρίου ταλάντων· διεγνώκει γὰρ τοῖς Ἀμαληκιτῶν ἔθνεσι καὶ Ἰδουμαίων καὶ Γαβαλιτῶν ἐπιστρατεύσασθαι. παρασκευασαμένου δὲ πρὸς τὴν στρατείαν καὶ μέλλοντος ἐξορμᾶν ὁ προφήτης τὸν τῶν Ἰσραηλιτῶν στρατὸν ἀπολῦσαι συνεβούλευσεν· εἶναι γὰρ ἀσεβῆ καὶ τὸν θεὸν ἧτταν αὐτῷ προλέγειν χρησαμένῳ τούτοις συμμάχοις· περιέσεσθαι δὲ τῶν πολεμίων καὶ μετ’ ὀλίγων αὐτοῖς ἀγωνιζόμενον βουλομένου τοῦ θεοῦ. δυσφοροῦντος δὲ τοῦ βασιλέως ἐπὶ τῷ φθῆναι τὸν μισθὸν δεδωκέναι τοῖς Ἰσραηλίταις παρῄνει ποιεῖν ὁ προφήτης ὅ τι τῷ θεῷ δοκεῖ, χρήματα δ’ αὐτῷ πολλὰ παρ’ αὐτοῦ γενήσεσθαι. καὶ τοὺς μὲν ἀπολύει χαρίζεσθαι τὸν μισθὸν εἰπών, αὐτὸς δὲ μετὰ τῆς οἰκείας δυνάμεως ἐπὶ τὰ προειρημένα τῶν ἐθνῶν ἐστράτευσε· καὶ κρατήσας αὐτῶν τῇ μάχῃ μυρίους μὲν ἀπέκτεινε, τοσούτους δὲ ζῶντας ἔλαβεν, οὓς ἐπὶ τὴν μεγάλην ἀγαγὼν πέτραν, ἥπερ ἐστὶ κατὰ τὴν Ἀραβίαν, ἀπ’ αὐτῆς κατεκρήμνισεν, ἀπήγαγέ τε λείαν πολλὴν καὶ πλοῦτον ἄφθονον ἐκ τῶν ἐθνῶν. Ἀμασίου δ’ ἐν τούτοις ὑπάρχοντος οἱ τῶν Ἰσραηλιτῶν οὓς ἀπέλυσε μισθωσάμενος ἀγανακτήσαντες ἐπὶ τούτῳ καὶ νομίσαντες ὕβριν εἶναι τὴν ἀπόλυσιν, οὐ γὰρ ἂν τοῦτο παθεῖν μὴ κατεγνωσμένους, ἐπῆλθον αὐτοῦ τῇ βασιλείᾳ καὶ μέχρι Βηθσεμήρων προελθόντες διήρπασαν τὴν χώραν καὶ πολλὰ μὲν ἔλαβον ὑποζύγια, τρισχιλίους δὲ ἀνθρώπους ἀπέκτειναν.", "st": "9.9.1"}, {"sp": "N", "t": "Ἀμασίας δὲ τῇ νίκῃ καὶ τοῖς κατορθώμασιν ἐπαρθεὶς τὸν μὲν τούτων αἴτιον θεὸν αὐτῷ γενόμενον ὑπερορᾶν ἤρξατο, οὓς δ’ ἐκ τῆς Ἀμαληκιτῶν χώρας ἐκόμισεν, τούτους σεβόμενος διετέλει. προσελθὼν δὲ ὁ προφήτης αὐτῷ θαυμάζειν ἔλεγεν, εἰ τούτους ἡγεῖται θεούς, οἳ τοὺς ἰδίους παρ’ οἷς ἐτιμῶντο μηδὲν ὤνησαν μηδ’ ἐκ χειρῶν ἐρρύσαντο τῶν ἐκείνου, ἀλλ’ ὑπερεῖδον πολλούς τε αὐτῶν ἀπολλυμένους καὶ αὑτοὺς αἰχμαλωτισθέντας· κεκομίσθαι γὰρ εἰς Ἱεροσόλυμα τούτῳ τῷ τρόπῳ, καθὼς ἄν τις τῶν πολεμίων τινὰ ζωγρήσας ἤγαγεν. τῷ δὲ βασιλεῖ ταῦτ’ ὀργὴν ἐκίνησε καὶ προσέταξεν ἡσυχίαν ἄγειν τὸν προφήτην ἀπειλήσας αὐτὸν κολάσειν, ἂν πολυπραγμονῇ. καὶ ὁ μὲν ἡσυχάζειν εἶπεν, οὐκ ἀμελήσειν δὲ ὧν ἐπικεχείρηκε νεωτερίζων τὸν θεὸν προύλεγεν. Ἀμασίας δὲ κατέχειν ἑαυτὸν ἐπὶ ταῖς εὐπραγίαις οὐ δυνάμενος, ἃς παρὰ τοῦ θεοῦ λαβὼν εἰς αὐτὸν ἐξύβριζεν, ἀλλὰ φρονηματισθεὶς ἔγραψεν Ἰωάσῳ τῷ τῶν Ἰσραηλιτῶν βασιλεῖ κελεύων ὑπακούειν αὐτῷ σὺν ἅπαντι τῷ λαῷ, ὡς καὶ πρότερον ὑπήκουσε τοῖς προγόνοις αὐτοῦ Δαυίδῃ καὶ Σολόμωνι, ἢ μὴ βουλόμενον εὐγνωμονεῖν εἰδέναι πολέμῳ περὶ τῆς ἀρχῆς διακριθησόμενον. ἀντέγραψε δ’ ὁ Ἰώασος τάδε· βασιλεὺς Ἰώασος βασιλεῖ Ἀμασίᾳ. ἦν ἐν τῷ Λιβάνῳ ὄρει κυπάρισσος παμμεγέθης καὶ ἄκανος. αὕτη πρὸς τὴν κυπάρισσον ἔπεμψε μνηστευομένη τὴν θυγατέρα αὐτῆς πρὸς γάμον τῷ παιδί. μεταξὺ ταῦτα λέγουσαν θηρίον τι παρερχόμενον κατεπάτησε τὴν ἄκανον. τοῦτο οὖν ἔσται σοι παράδειγμα τοῦ μὴ μειζόνων ἐφίεσθαι, μηδ’ ὅτι τὴν πρὸς Ἀμαληκίτας μάχην εὐτύχησας ἐπὶ ταύτῃ γαυρούμενος σαυτῷ καὶ τῇ βασιλείᾳ σου κινδύνους ἐπισπῶ.", "st": "9.9.2"}, {"sp": "N", "t": "Ταῦτα δὲ ἀναγνοὺς Ἀμασίας ἔτι μᾶλλον ἐπὶ τὴν στρατείαν παρωξύνθη τοῦ θεοῦ παρορμῶντος αὐτὸν οἶμαι πρὸς αὐτήν, ἵνα τῶν παρανομηθέντων εἰς αὐτὸν δίκην ἀπολάβῃ. ὡς δ’ ἐξήγαγε μετὰ τῆς δυνάμεως ἐπὶ τὸν Ἰώασον καὶ συνάπτειν μάχην ἔμελλον, τὸ Ἀμασίου στράτευμα φόβος αἰφνίδιος καὶ κατάπληξις οἵαν θεὸς οὐκ εὐμενὴς ἐντίθησιν εἰς φυγὴν ἔτρεψε, καὶ πρὶν εἰς χεῖρας ἐλθεῖν διασπαρέντων ὑπὸ τοῦ δέους αὐτῶν μονωθέντα τὸν Ἀμασίαν ληφθῆναι συνέβη πρὸς τῶν πολεμίων αἰχμάλωτον· ἠπείλησε δ’ αὐτῷ θάνατον Ἰώασος, εἰ μὴ πείσειε τοὺς Ἱεροσολυμίτας ἀνοίξαντας αὐτῷ τὰς πύλας δέξασθαι μετὰ τῆς στρατιᾶς εἰς τὴν πόλιν. καὶ Ἀμασίας μὲν ὑπὸ ἀνάγκης καὶ τοῦ περὶ τὸ ζῆν δέους ἐποίησεν εἰσδεχθῆναι τὸν πολέμιον· ὁ δὲ διακόψας τι τοῦ τείχους ὡς τετρακοσίων πηχῶν ἐφ’ ἅρματος εἰσήλασε διὰ τῆς διακοπῆς εἰς Ἱεροσόλυμα τὸν Ἀμασίαν ἄγων αἰχμάλωτον. κύριος δὲ τούτῳ τῷ τρόπῳ γενόμενος τῶν Ἱεροσολυμιτῶν τούς τε τοῦ θεοῦ θησαυροὺς ἀνείλετο καὶ ὅσος ἦν τῷ Ἀμασίᾳ χρυσὸς καὶ ἄργυρος ἐν τοῖς βασιλείοις ἐξεφόρησε, καὶ οὕτως αὐτὸν ἀπολύσας τῆς αἰχμαλωσίας ἀνέζευξεν εἰς Σαμάρειαν. ταῦτα δ’ ἐγένετο περὶ τοὺς Ἱεροσολυμίτας ἔτει τετάρτῳ καὶ δεκάτῳ τῆς Ἀμασία βασιλείας, ὃς μετὰ ταῦτα ἐπιβουλευθεὶς ὑπὸ τῶν φίλων φεύγει μὲν εἰς Λάχισαν πόλιν, ἀναιρεῖται δὲ ὑπὸ τῶν ἐπιβούλων πεμψάντων ἐκεῖ τοὺς ἀποκτενοῦντας αὐτόν. καὶ τὸ μὲν σῶμα κομίσαντες εἰς Ἱεροσόλυμα βασιλικῶς ἐκήδευσαν· κατέστρεψε δὲ οὕτως Ἀμασίας τὸν βίον καὶ διὰ τὸν νεωτερισμὸν τῆς πρὸς τὸν θεὸν ὀλιγωρίας, βιώσας μὲν ἔτη τέσσαρα καὶ πεντήκοντα βασιλεύσας δὲ ἐννέα καὶ εἴκοσι. διαδέχεται δ’ αὐτὸν ὁ παῖς Ὀζίας τοὔνομα.", "st": "9.9.3"}, {"sp": "N", "t": "Πεντεκαιδεκάτῳ ἔτει τῆς Ἀμασία βασιλείας ἐβασίλευσε τῶν Ἰσραηλιτῶν ὁ Ἰωάσου υἱὸς Ἱερόβαμος ἐν Σαμαρείᾳ ἔτη τεσσαράκοντα. οὗτος ὁ βασιλεὺς τὰ μὲν εἰς τὸν θεὸν ὑβριστὴς καὶ παράνομος δεινῶς ἐγένετο εἴδωλά τε σεβόμενος καὶ πολλοῖς ἀτόποις καὶ ξένοις ἐγχειρῶν ἔργοις, τῷ δὲ λαῷ τῶν Ἰσραηλιτῶν μυρίων ἀγαθῶν αἴτιος ὑπῆρχε. τούτῳ προεφήτευσέ τις Ἰωνᾶς, ὡς δεῖ πολεμήσαντα τοῖς Σύροις αὐτὸν κρατῆσαι τῆς ἐκείνων δυνάμεως καὶ πλατῦναι τὴν αὑτοῦ βασιλείαν τοῖς μὲν κατὰ τὴν ἄρκτον μέρεσιν ἕως Ἀμάθου πόλεως, τοῖς δὲ κατὰ τὴν μεσημβρίαν ἕως τῆς Ἀσφαλτίδος λίμνης· τὸ γὰρ ἀρχαῖον οἱ ὅροι τῆς Χαναναίας ἦσαν οὗτοι, καθὼς ὁ στρατηγὸς Ἰησοῦς περιώρισε. στρατεύσας οὖν ἐπὶ τοὺς Σύρους ὁ Ἱερόβαμος καταστρέφεται πᾶσαν αὐτῶν τὴν χώραν, ὡς προεφήτευσεν Ἰωνᾶς.", "st": "9.10.1"}, {"sp": "N", "t": "Ἀναγκαῖον δὲ ἡγησάμην τὴν ἀκρίβειαν τῶν πραγμάτων παραδώσειν ὑπεσχημένος ὅσα καὶ περὶ τούτου τοῦ προφήτου εὗρον ἐν ταῖς Ἑβραϊκαῖς βίβλοις ἀναγεγραμμένα διεξελθεῖν· κελευσθεὶς γὰρ οὗτος ὑπὸ τοῦ θεοῦ πορευθῆναι μὲν εἰς τὴν Νινύου βασιλείαν κηρῦξαι δ’ ἐκεῖ γενόμενον ἐν τῇ πόλει ὅτι τὴν ἀρχὴν ἀπολέσει, δείσας οὐκ ἀπῆλθεν, ἀλλ’ ἀποδιδράσκει τὸν θεὸν εἰς Ἰόπην πόλιν καὶ πλοῖον εὑρὼν ἐμβὰς εἰς Ταρσὸν ἔπλει τῆς Κιλικίας. ἐπιγενομένου δὲ χειμῶνος σφοδροτάτου καὶ κινδυνεύοντος καταδῦναι τοῦ σκάφους οἱ μὲν ναῦται καὶ οἱ κυβερνῆται καὶ αὐτὸς ὁ ναύκληρος εὐχὰς ἐποιοῦντο χαριστηρίους, εἰ διαφύγοιεν τὴν θάλασσαν, ὁ δὲ Ἰωνᾶς συγκαλύψας αὑτὸν ἐβέβλητο μηδὲν ὧν τοὺς ἄλλους ἑώρα ποιοῦντας μιμούμενος. αὔξοντος δ’ ἔτι μᾶλλον τοῦ κλύδωνος καὶ βιαιοτέρας γενομένης ὑπὸ τῶν πνευμάτων τῆς θαλάσσης ὑπονοήσαντες, ὡς ἐνδέχεταί τινα τῶν ἐμπλεόντων αἴτιον αὐτοῖς εἶναι τοῦ χειμῶνος, συνέθεντο κλήρῳ τοῦτον ὅστις ποτὲ ἦν μαθεῖν. κληρωσαμένων οὖν ὁ προφήτης λαγχάνει πυνθανομένων τε πόθεν τε εἴη καὶ τί μετέρχεται τὸ μὲν γένος ἔλεγεν Ἑβραῖος εἶναι προφήτης τοῦ μεγίστου θεοῦ· συνεβούλευσεν οὖν αὐτοῖς, εἰ θέλουσιν ἀποδράναι τὸν παρόντα κίνδυνον, ἐκβαλεῖν αὐτὸν εἰς τὸ πέλαγος· αἴτιον γὰρ αὐτοῖς εἶναι τοῦ χειμῶνος. οἱ δὲ τὸ μὲν πρῶτον οὐκ ἐτόλμων κρίναντες ἀσέβημα ξένον ἄνθρωπον καὶ πεπιστευκότα αὐτοῖς τὸ ζῆν εἰς φανερὰν αὐτοὺς ἀπώλειαν ἐκρῖψαι, τελευταῖον δ’ ὑπερβιαζομένου τοῦ κακοῦ καὶ ὅσον οὔπω μέλλοντος βαπτίζεσθαι τοῦ σκάφους, ὑπό τε τοῦ προφήτου παρορμηθέντες αὐτοῦ καὶ ὑπὸ τοῦ δέους τοῦ περὶ τῆς αὑτῶν σωτηρίας ῥίπτουσιν αὐτὸν εἰς τὴν θάλασσαν. καὶ ὁ μὲν χειμὼν ἐστάλη, τὸν δὲ λόγος ὑπὸ τοῦ κήτους καταποθέντα τρεῖς ἡμέρας καὶ τοσαύτας νύκτας εἰς τὸν Εὔξεινον ἐκβρασθῆναι πόντον ζῶντα καὶ μηδὲν τοῦ σώματος λελωβημένον. ἔνθα τοῦ θεοῦ δεηθεὶς συγγνώμην αὐτῷ παρασχεῖν τῶν ἡμαρτημένων ἀπῆλθεν εἰς τὴν Νίνου πόλιν καὶ σταθεὶς εἰς ἐπήκοον ἐκήρυσσεν, ὡς μετ’ ὀλίγον πάλιν ἀποβαλοῦσι τὴν ἀρχὴν τῆς Ἀσίας, καὶ ταῦτα δηλώσας ὑπέστρεψε. διεξῆλθον δὲ τὴν περὶ αὐτοῦ διήγησιν, ὡς εὗρον ἀναγεγραμμένην.", "st": "9.10.2"}, {"sp": "N", "t": "Ἱερόβαμος δ’ ὁ βασιλεὺς μετὰ πάσης εὐδαιμονίας τὸν βίον διαγαγὼν καὶ ἄρξας ἔτη τεσσαράκοντα ἐτελεύτησε καὶ θάπτεται μὲν ἐν Σαμαρείᾳ, διαδέχεται δὲ αὐτοῦ τὴν βασιλείαν υἱὸς Ζαχαρίας. τὸν αὐτὸν δὲ τρόπον καὶ Ὀζίας ὁ τοῦ Ἀμασία υἱός, ἔτος ἤδη τέταρτον πρὸς τοῖς δέκα βασιλεύοντος Ἱεροβοάμου, τῶν δύο φυλῶν ἐβασίλευσεν ἐν Ἱεροσολύμοις μητρὸς ὢν Ἀχίας μὲν τοὔνομα ἀστῆς δὲ τὸ γένος. ἀγαθὸς δὲ ἦν καὶ δίκαιος τὴν φύσιν καὶ μεγαλόφρων καὶ προνοῆσαι τῶν πραγμάτων φιλοπονώτατος. στρατευσάμενος δὲ καὶ ἐπὶ Παλαιστίνους καὶ νικήσας μάχῃ πόλεις αὐτῶν ἔλαβε κατὰ κράτος Γίτταν καὶ Ἰάμνειαν καὶ κατέσκαψεν αὐτῶν τὰ τείχη. μετὰ δὲ ταύτην τὴν στρατείαν ἐπῆλθε τοῖς τῇ Αἰγύπτῳ γειτνιῶσιν Ἄραψι καὶ πόλιν κτίσας ἐπὶ τῆς Ἐρυθρᾶς θαλάσσης ἐγκατέστησεν αὐτῇ φρουράν. ἔπειτα τοὺς Ἀμμανίτας καταστρεψάμενος καὶ φόρους αὐτοῖς ὁρίσας τελεῖν καὶ πάντα τὰ μέχρι τῶν Αἰγυπτίων ὅρων χειρωσάμενος τῶν Ἱεροσολύμων ἤρχετο ποιεῖσθαι τὸ λοιπὸν τὴν ἐπιμέλειαν· ὅσα γὰρ τῶν τειχῶν ἢ ὑπὸ τοῦ χρόνου καταβέβλητο ἢ ὑπὸ τῆς ὀλιγωρίας τῶν πρὸ αὐτοῦ βασιλέων, ταῦτά τε ἀνῳκοδόμει καὶ κατεσκεύαζεν, ὅσα τε ἦν καταβεβλημένα ὑπὸ τοῦ τῶν Ἰσραηλιτῶν βασιλέως, ὅτε τὸν πατέρα αὐτοῦ λαβὼν αἰχμάλωτον τὸν Ἀμασίαν εἰσῆλθεν εἰς τὴν πόλιν. προσῳκοδόμησε δὲ καὶ πύργους πολλοὺς πεντήκοντα πηχῶν ἕκαστον. καὶ φρουροὺς δὲ ἐνετείχισε τοῖς ἐρήμοις χωρίοις καὶ πολλοὺς ὀχετοὺς ὤρυξεν ὑδάτων. ἦν δ’ αὐτῷ καὶ ὑποζυγίων καὶ τῶν ἄλλων θρεμμάτων ἄπειρόν τι πλῆθος· εὐφυὴς γὰρ ἦν ἡ χώρα πρὸς νομάς. γεωργικὸς δὲ ὢν σφόδρα τῆς γῆς ἐπεμελεῖτο φυτοῖς αὐτὴν καὶ παντοδαποῖς τιθηνῶν σπέρμασι. στρατιᾶς δ’ εἶχεν ἐπιλέκτου περὶ αὑτὸν μυριάδας ἑπτὰ καὶ τριάκοντα, ἧς ἡγεμόνες ἦσαν καὶ ταξίαρχοι καὶ χιλίαρχοι γενναῖοι καὶ τὴν ἀλκὴν ἀνυπόστατοι τὸν ἀριθμὸν δισχίλιοι. διέταξε δ’ εἰς φάλαγγας τὴν ὅλην στρατιὰν καὶ ὥπλισε ῥομφαίαν δοὺς ἑκάστῳ καὶ θυρεοὺς καὶ θώρακας χαλκέους καὶ τόξα καὶ σφενδόνας. ἔτι δὲ πρὸς τούτοις μηχανήματα πολλὰ πρὸς πολιορκίας κατεσκεύασε πετρόβολά τε καὶ δορύβολα καὶ ἅρπαγας [καὶ ἀρτῆρας] καὶ ὅσα τούτοις ὅμοια.", "st": "9.10.3"}, {"sp": "N", "t": "Γενόμενος δ’ ἐν ταύτῃ τῇ συντάξει καὶ παρασκευῇ διεφθάρη τὴν διάνοιαν ὑπὸ τύφου καὶ χαυνωθεὶς θνητῇ περιουσίᾳ τῆς ἀθανάτου καὶ πρὸς ἅπαντα διαρκοῦς τὸν χρόνον ἰσχύος ὠλιγώρησεν· αὕτη δὲ ἦν ἡ πρὸς τὸν θεὸν εὐσέβεια καὶ τὸ τηρεῖν τὰ νόμιμα. ὤλισθε δὲ ὑπ’ εὐπραξίας καὶ κατηνέχθη πρὸς τὰ τοῦ πατρὸς ἁμαρτήματα, πρὸς ἃ κἀκεῖνον ἡ τῶν ἀγαθῶν λαμπρότης καὶ τὸ μέγεθος τῶν πραγμάτων οὐ δυνηθέντα προστῆναι καλῶς αὐτῶν ἤγαγεν. ἐνστάσης δ’ ἡμέρας ἐπισήμου καὶ πάνδημον ἑορτὴν ἐχούσης ἐνδὺς ἱερατικὴν στολὴν εἰσῆλθεν εἰς τὸ τέμενος θυσιάσων ἐπὶ τοῦ χρυσοῦ βωμοῦ τῷ θεῷ. τοῦ δ’ ἀρχιερέως Ἀζαρία ὄντων σὺν αὐτῷ ἱερέων ὀγδοήκοντα κωλύοντος αὐτόν, οὐ γὰρ ἐξὸν ἐπιθύειν εἶπον, μόνοις δ’ ἐφεῖσθαι τοῦτο ποιεῖν τοῖς ἐκ τοῦ Ἀαρῶνος γένους, καταβοώντων δ’ ἐξιέναι καὶ μὴ παρανομεῖν εἰς τὸν θεόν, ὀργισθεὶς ἠπείλησεν αὐτοῖς θάνατον, εἰ μὴ τὴν ἡσυχίαν ἄξουσι. μεταξὺ δὲ σεισμὸς ἐκλόνησε τὴν γῆν μέγας καὶ διαστάντος τοῦ ναοῦ φέγγος ἡλίου λαμπρὸν ἐξέλαμψε καὶ τῇ τοῦ βασιλέως ὄψει προσέπεσεν, ὡς τῷ μὲν εὐθέως λέπραν ἐπιδραμεῖν, πρὸ δὲ τῆς πόλεως πρὸς τῇ καλουμένῃ Ἐρωγῇ τοῦ ὄρους ἀπορραγῆναι τὸ ἥμισυ τοῦ κατὰ τὴν δύσιν καὶ κυλισθὲν τέσσαρας σταδίους ἐπὶ τὸ ἀνατολικὸν ὄρος στῆναι, ὡς τάς τε παρόδους ἐμφραγῆναι καὶ τοὺς παραδείσους τοὺς βασιλικούς. ἐπεὶ δὲ κατειλημμένην τὴν ὄψιν τοῦ βασιλέως ὑπὸ τῆς λέπρας εἶδον οἱ ἱερεῖς, ἔφραζόν τε αὐτῷ τὴν συμφορὰν καὶ ἐκέλευον ἐξιέναι τῆς πόλεως ὡς ἐναγῆ. ὁ δ’ ὑπ’ αἰσχύνης τε τοῦ συμβεβηκότος δεινοῦ καὶ τοῦ μηκέτ’ αὐτῷ παρρησίαν εἶναι τὸ κελευόμενον ἐποίει, τῆς ὑπὲρ ἄνθρωπον διανοίας καὶ τῶν διὰ τοῦτο εἰς τὸν θεὸν ἀσεβημάτων ταλαίπωρον οὕτως καὶ οἰκτρὰν ὑπομείνας δίκην. καὶ χρόνον μέν τινα διῆγεν ἔξω τῆς πόλεως ἰδιώτην ἀποζῶν βίον τοῦ παιδὸς αὐτῷ Ἰωθάμου τὴν ἀρχὴν παραλαβόντος, ἔπειτα ὑπὸ λύπης καὶ ἀθυμίας τῆς ἐπὶ τοῖς γεγενημένοις ἀπέθανεν, ἔτη μὲν βιώσας ὀκτὼ καὶ ἑξήκοντα, τούτων δὲ βασιλεύσας πεντηκονταδύο. ἐκηδεύθη δὲ μόνος ἐν τοῖς ἑαυτοῦ κήποις.", "st": "9.10.4"}, {"sp": "N", "t": "Ὁ δὲ τοῦ Ἱεροβάμου παῖς Ζαχαρίας ἓξ μῆνας βασιλεύσας τῶν Ἰσραηλιτῶν δολοφονηθεὶς ἀπέθανεν ὑπὸ φίλου τινὸς Σελλήμου μὲν τοὔνομα Ἰαβήσου δὲ υἱοῦ, ὃς καὶ τὴν βασιλείαν μετ’ αὐτὸν παραλαβὼν οὐ πλείονα χρόνον ἡμερῶν αὐτὴν κατέσχε τριάκοντα. ὁ γὰρ στρατηγὸς Μαναῆμος κατ’ ἐκεῖνον τὸν καιρὸν ὢν ἐν Θάρσῃ πόλει καὶ τὰ περὶ τὸν Ζαχαρίαν ἀκούσας ἄρας μετὰ πάσης τῆς στρατιᾶς ἧκεν εἰς τὴν Σαμάρειαν, καὶ συμβαλὼν εἰς μάχην ἀναιρεῖ τὸν Σέλλημον καὶ βασιλέα καταστήσας ἑαυτὸν ἐκεῖθεν εἰς Θαψὰν παραγίνεται πόλιν. οἱ δ’ ἐν αὐτῇ τὰς πύλας μοχλῷ κλείσαντες οὐκ εἰσεδέξαντο τὸν βασιλέα. ὁ δὲ ἀμυνόμενος αὐτοὺς τὴν πέριξ ἐδῄου χώραν καὶ τὴν πόλιν κατὰ κράτος λαμβάνει πολιορκίᾳ. φέρων δὲ χαλεπῶς ἐπὶ τοῖς ὑπὸ τῶν Θαψίων πραχθεῖσι πάντας αὐτοὺς διεχρήσατο μηδὲ νηπίων φεισάμενος ὠμότητος ὑπερβολὴν οὐ καταλιπὼν οὐδὲ ἀγριότητος· ἃ γὰρ οὐδὲ τῶν ἀλλοφύλων τινὰς συγγνωστὸν διαθεῖναι γενομένους ὑποχειρίους, ταῦτα τοὺς ὁμοφύλους οὗτος εἰργάσατο. βασιλεύσας οὖν τῷ τρόπῳ τούτῳ ὁ Μαναῆμος ἐπ’ ἔτη μὲν δέκα σκαιὸς καὶ πάντων ὠμότατος διέμενεν ὤν, στρατεύσαντος δ’ ἐπ’ αὐτὸν Φούλου τοῦ Ἀσσυρίων βασιλέως εἰς μὲν ἀγῶνα καὶ μάχην οὐκ ἀπαντᾷ τοῖς Ἀσσυρίοις, πείσας δὲ χίλια τάλαντα ἀργυρίου λαβόντα ἀναχωρῆσαι διαλύεται τὸν πόλεμον. τὸ δὲ κεφάλαιον τοῦτο συνήνεγκε τὸ πλῆθος Μαναήμῳ πραχθὲν κατὰ κεφαλὴν δραχμὰς πεντήκοντα. τελευτήσας δὲ μετὰ ταῦτα κηδεύεται μὲν ἐν Σαμαρείᾳ, καταλείπει δὲ τῆς βασιλείας τὸν υἱὸν Φακέαν διάδοχον, ὃς τῇ τοῦ πατρὸς κατακολουθήσας ὠμότητι δυσὶν ἔτεσι μόνοις ἦρξεν. ἔπειτα δολοφονηθεὶς ἐν συμποσίῳ μετὰ φίλων ἀπέθανε Φακέου τινός, ὃς ἦν χιλίαρχος, ἐπιβουλεύσαντος αὐτῷ, παιδὸς δὲ Ῥομελία. κατασχὼν δὲ καὶ οὗτος ὁ Φακέας τὴν ἀρχὴν ἔτεσιν εἴκοσιν ἀσεβής τε ἦν καὶ παράνομος. ὁ δὲ τῶν Ἀσσυρίων βασιλεὺς Θαγλαθφαλλάσαρ τοὔνομα ἐπιστρατευσάμενος τοῖς Ἰσραηλίταις καὶ τήν τε Γαλαδηνὴν ἅπασαν καταστρεψάμενος καὶ τὴν πέραν τοῦ Ἰορδάνου χώραν καὶ τὴν πρὸς αὐτῇ τὴν Γαλιλαίαν καλουμένην καὶ Κύδισσα καὶ Ἄσωρα τοὺς οἰκήτορας αἰχμαλωτίσας μετέστησεν εἰς τὴν αὑτοῦ βασιλείαν. καὶ τὰ μὲν περὶ τοῦ Ἀσσυρίων βασιλέως ἐν τούτοις ἡμῖν δεδηλώσθω.", "st": "9.11.1"}, {"sp": "N", "t": "Ἰωσᾶς δὲ Ὀζία παῖς ἐβασίλευσε τῆς Ἰούδα φυλῆς ἐν Ἱεροσολύμοις ἐκ μητρὸς μὲν ἀστῆς γεγονὼς καλουμένης δὲ Ἰεράσης. οὗτος ὁ βασιλεὺς οὐδεμιᾶς ἀρετῆς ἀπελείπετο, ἀλλ’ εὐσεβὴς μὲν τὰ πρὸς τὸν θεόν, δίκαιος δὲ τὰ πρὸς ἀνθρώπους ὑπῆρχεν, ἐπιμελὴς δὲ τῶν κατὰ πόλιν· ὅσα γὰρ ἐπισκευῆς ἐδεῖτο καὶ κόσμου ταῦτα φιλοτίμως ἐξειργάσατο, στοὰς μὲν τὰς ἐν τῷ ναῷ ἱδρύσας καὶ προπύλαια, τὰ δὲ καταπεπτωκότα τῶν τειχῶν ἀνέστησε πύργους παμμεγέθεις καὶ δυσαλώτους οἰκοδομήσας, καὶ τῶν ἄλλων εἴ τι κατὰ τὴν βασιλείαν ἠμέλητο πολλὴν ἐπιστροφὴν ἐποιεῖτο. στρατευσάμενος δὲ καὶ ἐπὶ τοὺς Ἀμμανίτας καὶ κρατήσας αὐτῶν τῇ μάχῃ προσέταξεν αὐτοῖς φόρους κατὰ πᾶν ἔτος αὐτῷ τελεῖν ἑκατὸν τάλαντα καὶ σίτου κόρους μυρίους, τοσούτους δὲ καὶ κριθῆς. ηὔξησε δ’ οὕτω τὴν βασιλείαν, ὥστε ἀκαταφρόνητον μὲν αὐτὴν ἐκ τῶν πολεμίων εἶναι, τοῖς δ’ οἰκείοις εὐδαίμονα.", "st": "9.11.2"}, {"sp": "N", "t": "Ἦν δέ τις κατὰ τοῦτον τὸν καιρὸν προφήτης Ναοῦμος ὄνομα, ὃς περὶ τῆς Ἀσσυρίων καταστροφῆς καὶ τῆς Νίνου προφητεύων ἔλεγεν, ὡς ἔσται Νινύας κολυμβήθρα ὕδατος κινουμένη· οὕτως καὶ ὁ δῆμος ἅπας ταρασσόμενος καὶ κλυδωνιζόμενος οἰχήσεται φεύγων λεγόντων πρὸς ἀλλήλους στῆτε καὶ μείνατε καὶ χρυσὸν αὑτοῖς καὶ ἄργυρον ἁρπάσατε. ἔσται δ’ οὐδεὶς βουλησόμενος· σώζειν γὰρ αὑτῶν ἐθελήσουσι τὰς ψυχὰς μᾶλλον ἢ τὰ κτήματα· δεινὴ γὰρ αὐτοὺς ἐν ἀλλήλοις ἔρις ἕξει καὶ θρῆνος πάρεσίς τε τῶν μελῶν, αἵ τε ὄψεις ὑπὸ τοῦ φόβου μέλαιναι τελέως αὐτοῖς γενήσονται. ποῦ δὲ ἔσται τὸ κατοικητήριον τῶν λεόντων καὶ ἡ μήτηρ σκύμνων; λέγει δέ σοι ὁ θεός, Νινύα, ὅτι ἀφανιῶ σε καὶ οὐκέτι λέοντες ἐκ σοῦ πορευόμενοι ἐπιτάξουσι τῷ κόσμῳ. καὶ ἄλλα δὲ πολλὰ πρὸς τούτοις ἐπροφήτευσεν οὗτος ὁ προφήτης περὶ Νινύης, ἃ λέγειν οὐκ ἀναγκαῖον ἡγησάμην, ἵνα δὲ μὴ τοῖς ἐντυγχάνουσιν ὀχληρὸς δοκῶ παρέλιπον. συνέβη δὲ πάντα τὰ προειρημένα περὶ Νινύης μετὰ ἔτη ἑκατὸν καὶ πεντεκαίδεκα. περὶ μὲν τούτων ἀποχρώντως ἡμῖν δεδήλωται.", "st": "9.11.3"}, {"sp": "N", "t": "Ὁ δὲ Ἰώθαμος μετήλλαξεν ἔτη βιώσας ἓν καὶ τεσσαράκοντα βασιλεύσας δ’ ἐξ αὐτῶν ἑκκαίδεκα, θάπτεται δὲ ἐν ταῖς βασιλικαῖς θήκαις. ἔρχεται δ’ εἰς τὸν υἱὸν αὐτοῦ Ἄχαζον ἡ βασιλεία, ὃς ἀσεβέστατος εἰς τὸν θεὸν γενόμενος καὶ τοὺς πατρίους παραβὰς νόμους τοὺς Ἰσραηλιτῶν βασιλέας ἐμιμήσατο βωμοὺς ἐν Ἱεροσολύμοις ἀναστήσας καὶ θύων ἐπ’ αὐτῶν τοῖς εἰδώλοις, οἷς καὶ ἴδιον ὡλοκαύτωσε παῖδα κατὰ τὰ Χαναναίων ἔθη, καὶ τούτοις ἄλλα παραπλήσια διεπράττετο. ἔχοντος δ’ οὕτως καὶ μεμηνότος ἐστράτευσεν ἐπ’ αὐτὸν ὁ τῶν Σύρων καὶ Δαμασκηνῶν βασιλεὺς Ῥαασὴς καὶ Φακέας ὁ τῶν Ἰσραηλιτῶν· φίλοι γὰρ ἦσαν· καὶ συνελάσαντες αὐτὸν εἰς τὰ Ἱεροσόλυμα ἐπὶ πολὺν ἐπολιόρκουν χρόνον διὰ τὴν τῶν τειχῶν ὀχυρότητα μηδὲν ἀνύοντες. ὁ δὲ τῶν Σύρων βασιλεὺς λαβὼν τὴν πρὸς τῇ Ἐρυθρᾷ θαλάσσῃ πόλιν Ἠλαθοὺς καὶ τοὺς ἐνοικοῦντας ἀποκτείνας ἐγκατῴκισεν αὐτῇ Σύρους. τοὺς δ’ ἐντοῖς φρουρίοις ὁμοίως καὶ τοὺς πέριξ Ἰουδαίους διαφθείρας καὶ λείαν πολλὴν ἀπελάσας εἰς Δαμασκὸν μετὰ τῆς στρατιᾶς ἀνέζευξεν. ὁ δὲ τῶν Ἱεροσολυμιτῶν βασιλεὺς γνοὺς τοὺς Σύρους ἐπ’ οἴκου κεχωρηκότας καὶ νομίσας ἀξιόμαχος εἶναι τῷ τῶν Ἰσραηλιτῶν βασιλεῖ τὴν δύναμιν ἐπ’ αὐτὸν ἐξήγαγε, καὶ συμβαλὼν ἐνικήθη κατὰ μῆνιν τοῦ θεοῦ, ἣν ἐπὶ τοῖς ἀσεβήμασιν αὐτοῦ πολλοῖς ἅμα καὶ μεγάλοις εἶχεν· δώδεκα γὰρ μυριάδες κατ’ ἐκείνην αὐτοῦ τὴν ἡμέραν ὑπὸ τῶν Ἰσραηλιτῶν ἀνῃρέθησαν, ὧν ὁ στρατηγὸς Ζαχάριν τὸν υἱὸν ἀπέκτεινεν ἐν τῇ συμβολῇ τοῦ βασιλέως Ἀχάζου Ἀμασίας ὄνομα, καὶ τὸν ἐπίτροπον τῆς βασιλείας ἁπάσης Ἐρκὰμ καὶ τὸν τῆς Ἰούδα φυλῆς στρατηγὸν Ἐλικὰν αἰχμάλωτον ἔλαβον, καὶ ἐκ τῆς Βενιαμίτιδος φυλῆς γυναῖκας καὶ παῖδας ἀπήγαγον, καὶ πολλὴν λείαν διαρπάσαντες ἀνεχώρησαν εἰς Σαμάρειαν.", "st": "9.12.1"}, {"sp": "N", "t": "Ὠδηδὰς δέ τις, ὃς κατ’ ἐκεῖνο καιροῦ προφήτης ὑπῆρχεν ἐν Σαμαρείᾳ, τῷ στρατῷ πρὸ τῶν τειχῶν ἀπαντήσας μεγάλῃ βοῇ τὴν νίκην αὐτοῖς οὐ διὰ τὴν οἰκείαν ἰσχὺν αὐτῶν ἐδήλου γενέσθαι, διὰ δὲ τὸν τοῦ θεοῦ χόλον, ὃν εἶχεν ἐπ’ Ἄχαζον τὸν βασιλέα. καὶ κατεμέμφετο τῇ μὲν εὐπραγίᾳ τῇ κατ’ αὐτοῦ μὴ ἀρκεσθέντας, ἀλλὰ τολμήσαντας τοὺς ἐκ τῆς Ἰούδα φυλῆς καὶ Βενιαμίτιδος συγγενεῖς ὄντας αἰχμαλωτίσαι. συνεβούλευέ τε αὐτοῖς ἀπολῦσαι τούτους εἰς τὴν οἰκείαν ἀπαθεῖς· ἀπειθήσαντας γὰρ τῷ θεῷ δίκην ὑφέξειν. ὁ δὲ τῶν Ἰσραηλιτῶν λαὸς εἰς ἐκκλησίαν συνελθὼν ἐπεσκέπτετο περὶ τούτων. ἀναστὰς δέ τις Βαραχίας ὄνομα τῶν εὐδοκιμούντων ἐν τῇ πολιτείᾳ καὶ ἄλλοι μετ’ αὐτοῦ τρεῖς ἔλεγον οὐκ ἐπιτρέψειν τοῖς ὁπλίταις εἰσαγαγεῖν εἰς τὴν πόλιν, ἵνα μὴ πάντες ἀπολώμεθα ὑπὸ τοῦ θεοῦ· μόνον γὰρ ἀπόχρη τὸ πρὸς αὐτὸν ἡμᾶς ἐξαμαρτεῖν, ὡς οἱ προφῆται λέγουσιν, ἀλλὰ μὴ καινότερα τούτων ἀσεβήματα δρᾶν. ταῦτ’ ἀκούσαντες οἱ στρατιῶται συνεχώρησαν ἐκείνοις ποιεῖν ὃ ἐδόκει συμφέρειν. παραλαβόντες οὖν οἱ προειρημένοι ἄνδρες τοὺς αἰχμαλώτους ἔλυσάν τε καὶ ἐπιμελείας ἠξίωσαν καὶ δόντες ἐφόδια εἰς τὴν οἰκείαν ἀπέλυσαν ἀβλαβεῖς, οὐδὲν δ’ ἧττον καὶ τέσσαρες αὐτοῖς συνῆλθον καὶ μέχρις Ἱεριχοῦντος προπέμψαντες οὐκ ἄπωθεν τῶν Ἱεροσολύμων ἀνέστρεψαν εἰς Σαμάρειαν.", "st": "9.12.2"}, {"sp": "N", "t": "Ἄχαζος δ’ ὁ βασιλεὺς ταῦτα παθὼν ὑπὸ τῶν Ἰσραηλιτῶν πέμψας πρὸς τὸν τῶν Ἀσσυρίων βασιλέα Θαγλαθφαλλασάρην συμμαχίαν αὐτὸν παρασχεῖν παρεκάλει πρὸς τὸν πόλεμον τὸν πρὸς τοὺς Ἰσραηλίτας καὶ Σύρους καὶ Δαμασκηνοὺς χρήματα πολλὰ δώσειν ὑπισχνούμενος, ἔπεμψε δ’ αὐτῷ καὶ λαμπρὰς δωρεάς. ὁ δὲ τῶν πρέσβεων ἀφικομένων ὡς αὐτὸν ἧκε σύμμαχος Ἀχάζῳ, καὶ στρατεύσας ἐπὶ τοὺς Σύρους τήν τε χώραν αὐτῶν ἐπόρθησε καὶ τὴν Δαμασκὸν κατὰ κράτος εἷλε καὶ τὸν βασιλέα Ἀρασὴν ἀπέκτεινε. τοὺς δὲ Δαμασκηνοὺς ἀπῴκισεν εἰς τὴν ἄνω Μηδίαν καὶ ἐκ τῶν ἐθνῶν τῶν Ἀσσυρίων μεταστήσας τινὰς εἰς τὴν Δαμασκὸν κατῴκισε. τὴν δὲ τῶν Ἰσραηλιτῶν γῆν κακώσας πολλοὺς ἐξ αὐτῆς αἰχμαλώτους συνέλαβε. ταῦτ’ αὐτοῦ διαπραξαμένου τοὺς Σύρους ὁ βασιλεὺς ἄρας τὸν χρυσὸν ὃς ἦν ἐν τοῖς βασιλικοῖς θησαυροῖς καὶ τὸν ἄργυρον τὸν ἐν τῷ ναῷ τοῦ θεοῦ καὶ εἴ τι κάλλιστον ἀνάθημα, τοῦτο βαστάσας ἧκεν ἔχων εἰς Δαμασκὸν καὶ ἔδωκε τῷ τῶν Ἀσσυρίων βασιλεῖ κατὰ τὰς ὁμολογίας· καὶ πάντων αὐτῷ χάριν ἔχειν ὁμολογήσας ὑπέστρεψεν εἰς Ἱεροσόλυμα. ἦν δ’ οὕτως ἀνόητος καὶ τοῦ συμφέροντος ἀσυλλόγιστος ὁ βασιλεὺς, ὥστε οὐδὲ πολεμούμενος ὑπὸ τῶν Σύρων ἐπαύσατο τοὺς θεοὺς αὐτῶν προσκυνῶν, ἀλλὰ διετέλει τούτους σεβόμενος ὡς παρεξομένους αὐτῷ τὴν νίκην. ἡττηθεὶς δὲ πάλιν τοὺς Ἀσσυρίων ἤρξατο τιμᾶν θεοὺς καὶ πάντας ἐῴκει μᾶλλον τιμήσων ἢ τὸν πατρῷον καὶ ἀληθῶς θεόν, ὃς αὐτῷ καὶ τῆς ἥττης ὀργιζόμενος ἦν αἴτιος. ἐπὶ τοσοῦτον δ’ ὀλιγωρίας καὶ καταφρονήσεως ἦλθεν, ὡς καὶ τέλεον ἀποκλεῖσαι τὸν ναὸν καὶ τὰς νενομισμένας ἀπαγορεῦσαι θυσίας ἐπιφέρειν καὶ περιδῦσαι τῶν ἀναθημάτων αὐτόν. ταῦθ’ ὑβρίσας τὸν θεὸν ἐτελεύτησεν ἔτη μὲν βιώσας ἓξ καὶ τριάκοντα, βασιλεύσας δ’ ἐξ αὐτῶν ἑκκαίδεκα, τὸν δ’ υἱὸν Ἐζεκίαν διάδοχον καταλιπών.", "st": "9.12.3"}, {"sp": "N", "t": "Ἀπέθανε δ’ ὑπὸ τὸν αὐτὸν καιρὸν καὶ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς Φακέας ἐπιβουλεύσαντος αὐτῷ φίλου τινὸς Ὠσήου ὄνομα, ὃς κατασχὼν τὴν βασιλείαν ἐπ’ ἔτη ἐννέα πονηρός τε ἦν καὶ τῶν πρὸς τὸν θεὸν ὀλίγωρος. στρατεύει δ’ ἐπ’ αὐτὸν ὁ τῶν Ἀσσυρίων βασιλεὺς Σαλμανάσσας καὶ κρατήσας αὐτοῦ, τὸν γὰρ θεὸν οὐκ εἶχεν Ὠσῆος εὐμενῆ, καὶ σύμμαχον ἐποιήσατο καὶ φόρους ἐπέταξεν αὐτῷ τελεῖν ὡρισμένους. ἔτει δὲ τετάρτῳ Ὠσήου τῆς βασιλείας ἐβασίλευσεν Ἐζεκίας ἐν Ἱεροσολύμοις Ἀχάζου υἱὸς καὶ Ἀβίας ἀστῆς τὸ γένος. φύσις δ’ ἦν αὐτῷ χρηστὴ καὶ δικαία καὶ εὐσεβής· οὐδὲν γὰρ ἄλλο πρῶτον εἰς τὴν βασιλείαν παρελθὼν οὐδ’ ἀναγκαιότερον οὐδὲ συμφορώτερον αὑτῷ τε καὶ τοῖς ἀρχομένοις ὑπέλαβε τοῦ θρησκεύειν τὸν θεόν, ἀλλὰ συγκαλέσας τὸν λαὸν καὶ τοὺς ἱερεῖς καὶ τοὺς Ληουίτας ἐδημηγόρησεν ἐν αὐτοῖς λέγων· οὐκ ἀγνοεῖτε μέν, ὡς διὰ τὰς τοῦ πατρὸς ἁμαρτίας τοὐμοῦ παραβάντος τὴν πρὸς θεὸν ὁσίαν καὶ τιμὴν πολλῶν ἐπειράθητε καὶ μεγάλων κακῶν, διαφθαρέντες ὑπ’ αὐτοῦ τὴν διάνοιαν καὶ ἀναπεισθέντες οὓς αὐτὸς ἐδοκίμαζεν εἶναι θεοὺς τούτοις προσκυνεῖν· παραινῶ δὲ ὑμῖν ἔργῳ μεμαθηκότας, ὡς ἔστι δεινὸν τὸ ἀσεβεῖν, τούτου μὲν ἤδη λήθην ποιήσασθαι, καθᾶραι δ’ αὑτοὺς ἐκ τῶν προτέρων μιασμάτων τούς τε ἱερεῖς καὶ Ληουίτας καὶ συνελθόντας οὕτως ἀνοῖξαι τὸ ἱερόν, καὶ καθάραντας αὐτὸ ταῖς ἐξ ἔθους θυσίαις εἰς τὴν ἀρχαίαν καὶ πάτριον ἀνακαλέσασθαι τιμήν. οὕτως γὰρ τὸν θεὸν εὐμενῆ ποιήσαιμεν ἀφέντα τὴν ὀργήν.", "st": "9.13.1"}, {"sp": "N", "t": "Ταῦτ’ εἰπόντος τοῦ βασιλέως οἱ ἱερεῖς ἀνοίγουσί τε τὸ ἱερὸν καὶ ἀνοίξαντες τὰ σκεύη τοῦ θεοῦ καὶ τὰ μιάσματα ἐκβαλόντες τὰς ἐξ ἔθους τῷ βωμῷ θυσίας ἐπέφερον. διαπέμψας δ’ ὁ βασιλεὺς εἰς τὴν ὑπ’ αὐτὸν χώραν ἐκάλει τὸν λαὸν εἰς Ἱεροσόλυμα τὴν τῶν ἀζύμων ἑορτὴν ἄξοντα· πολὺν γὰρ ἐκλελοίπει χρόνον διὰ τὰς τῶν προειρημένων βασιλέων παρανομίας. ἐξαπέστειλε δὲ καὶ πρὸς τοὺς Ἰσραηλίτας προτρεπόμενος αὐτοὺς ἀφέντας τὸν ἄρτι βίον εἰς τὴν ἀρχαίαν ἐπανελθεῖν συνήθειαν καὶ σέβειν τὸν θεόν· καὶ γὰρ ἐπιτρέπειν αὐτοῖς παραγενομένοις εἰς Ἱεροσόλυμα τὴν τῶν ἀζύμων ἑορτὴν ἄγειν καὶ συμπανηγυρίζειν αὐτοῖς. ταῦτα δ’ ἔλεγε παραινεῖν, οὐχ ὅπως ὑπακούσωσιν αὐτοῦ εἰ μὴ θέλουσι, τοῦ δ’ ἐκείνοις συμφέροντος ἕνεκα· μακαρίους γὰρ ἔσεσθαι. οἱ δὲ Ἰσραηλῖται παραγενομένων τῶν πρέσβεων καὶ δηλωσάντων αὐτοῖς τὰ παρὰ τοῦ ἰδίου βασιλέως οὐ μόνον οὐκ ἐπείσθησαν, ἀλλὰ καὶ τοὺς πρέσβεις ὡς ἀνοήτους ἐχλεύασαν, καὶ τοὺς προφήτας δὲ ὁμοίως ταῦτα παραινοῦντας καὶ προλέγοντας ἃ πείσονται μὴ μεταθέμενοι πρὸς τὴν εὐσέβειαν τοῦ θεοῦ διέπτυον καὶ τελευταῖον συλλαβόντες αὐτοὺς ἀπέκτειναν. καὶ οὐδὲ μέχρι τούτων αὐτοῖς ἤρκεσε παρανομοῦσιν, ἀλλὰ χείρω τῶν προειρημένων ἐπενοοῦντο καὶ οὐ πρότερον ἐπαύσαντο, πρὶν ἢ τοῖς πολεμίοις αὐτοὺς ἀμυνόμενος τῆς ἀσεβείας ὁ θεὸς ἐποίησεν ὑποχειρίους. καὶ περὶ μὲν τούτων αὖθις δηλώσομεν. πολλοὶ μέντοι τῆς Μανασσίτιδος φυλῆς καὶ Ζαβούλου καὶ Ἰσσαχάρου πεισθέντες οἷς οἱ προφῆται παρῄνεσαν εἰς εὐσέβειαν μετεβάλοντο. καὶ οὗτοι πάντες εἰς Ἱεροσόλυμα πρὸς Ἐζεκίαν συνέδραμον, ὅπως τῷ θεῷ προσκυνήσωσιν.", "st": "9.13.2"}, {"sp": "N", "t": "Ἀφικομένων δὲ τούτων ὁ βασιλεὺς Ἐζεκίας ἀναβὰς εἰς τὸ ἱερὸν μετὰ τῶν ἡγεμόνων καὶ τοῦ λαοῦ παντὸς ἔθυσεν ὑπὲρ αὑτοῦ ταύρους ἑπτὰ καὶ κριοὺς τοσούτους καὶ ἄρνας ἑπτὰ καὶ ἐρίφους τοσούτους. ἐπιθέντες δὲ τὰς χεῖρας ταῖς κεφαλαῖς τῶν ἱερείων αὐτός τε ὁ βασιλεὺς καὶ οἱ ἡγεμόνες τοῖς ἱερεῦσι καλλιερεῖν ἐφῆκαν. καὶ οἱ μὲν ἔθυόν τε καὶ ὡλοκαύτουν, οἱ δὲ Λευῖται περιεστῶτες ἐν κύκλῳ μετὰ τῶν μουσικῶν ὀργάνων ᾖδον ὕμνους εἰς τὸν θεὸν καὶ ἔψαλλον ὡς ἐδιδάχθησαν ὑπὸ Δαυίδου, οἱ δὲ λοιποὶ ἱερεῖς βυκάνας ἔχοντες ἐπεσάλπιζον τοῖς ὑμνῳδοῦσι. τούτων δὲ γινομένων ἐπὶ πρόσωπον ῥίψαντες αὑτοὺς ὅ τε βασιλεὺς καὶ τὸ πλῆθος προσεκύνουν τὸν θεόν. ἔπειτα θύει μὲν βοῦς ἑβδομήκοντα κριοὺς ἑκατὸν ἄρνας διακοσίους, τῷ πλήθει δὲ πρὸς εὐωχίαν ἐχαρίσατο βοῦς μὲν ἑξακοσίους τὰ δὲ λοιπὰ θρέμματα τρισχίλια· καὶ πάντα μὲν οἱ ἱερεῖς ἀκολούθως ἐποίησαν τῷ νόμῳ. τούτοις δ’ ὁ βασιλεὺς ἡδόμενος εὐωχεῖτο μετὰ τοῦ λαοῦ τῷ θεῷ χάριν ἔχειν ὁμολογῶν. ἐνστάσης δὲ τῆς τῶν ἀζύμων ἑορτῆς θύσαντες τὴν λεγομένην φάσκα τὰς ἄλλας τὸ λοιπὸν θυσίας ἐπετέλουν ἐπὶ ἡμέρας ἑπτά. τῷ δὲ πλήθει πάρεξ ὧν ἐκαλλιέρησαν αὐτοὶ ταύρους μὲν δισχιλίους θρέμματα δὲ ἑπτακισχίλια ὁ βασιλεὺς ἐχαρίσατο. τὸ δ’ αὐτὸ καὶ οἱ ἡγεμόνες ἐποίησαν· χιλίους μὲν γὰρ ταύρους ἔδοσαν αὐτοῖς θρέμματα δὲ χίλια καὶ τεσσαράκοντα. καὶ τοῦτον τὸν τρόπον ἀπὸ Σολόμωνος τοῦ βασιλέως οὐκ ἀχθεῖσα ἡ ἑορτὴ τότε πρῶτον λαμπρῶς καὶ φιλοτίμως ἐπετελέσθη. ὡς δὲ τὰ περὶ τὴν ἑορτὴν αὐτοῖς πέρας εἶχεν, ἐξελθόντες εἰς τὴν χώραν ἥγνισαν αὐτήν· καὶ τὴν πόλιν δὲ παντὸς ἐκάθηραν μιάσματος εἰδώλων, τάς τε καθημερινὰς θυσίας ὁ βασιλεὺς ἐκ τῶν ἰδίων ἐπιτελεῖσθαι διέταξε κατὰ τὸν νόμον, καὶ τοῖς ἱερεῦσι καὶ Ληουίταις τὰς δεκάτας ὥρισε παρὰ τοῦ πλήθους δίδοσθαι καὶ τὰς ἀπαρχὰς τῶν καρπῶν, ἵν’ ἀεὶ τῇ θρησκείᾳ παραμένωσι καὶ τῆς θεραπείας ὦσιν ἀχώριστοι τοῦ θεοῦ. καὶ τὸ μὲν πλῆθος συνεισέφερε παντοδαπὸν καρπὸν τοῖς ἱερεῦσι καὶ Λευίταις, ἀποθήκας δὲ καὶ ταμιεῖα τούτων ὁ βασιλεὺς κατασκευάσας ἑκάστῳ διένειμε τῶν ἱερέων καὶ Ληουιτῶν καὶ παισὶν αὐτῶν καὶ γυναιξί· καὶ οὕτω πάλιν εἰς τὴν ἀρχαίαν θρησκείαν ἐπανῆλθον. ταῦτα δὲ τὸν προειρημένον τρόπον ὁ βασιλεὺς καταστησάμενος πόλεμον ἐξήνεγκε πρὸς τοὺς Παλαιστίνους καὶ νικήσας κατέσχεν ἁπάσας ἀπὸ Γάζης μέχρι Γίττης πόλεις τῶν πολεμίων. ὁ δὲ τῶν Ἀσσυρίων βασιλεὺς πέμψας ἠπείλει πᾶσαν αὐτοῦ καταστρέψεσθαι τὴν ἀρχήν, εἰ μὴ τοὺς φόρους, οὓς ὁ πατὴρ αὐτοῦ τὸ πρῶτον ἐτέλει, τούτους ἀποδώσει. Ἐζεκίας δὲ τῶν μὲν ἀπειλῶν οὐκ ἐφρόντισ’, ἐθάρρει δὲ ἐπὶ τῇ πρὸς τὸ θεῖον εὐσεβείᾳ καὶ τῷ προφήτῃ Ἡσαΐᾳ, παρ’ οὗ πάντ’ ἀκριβῶς τὰ μέλλοντα ἐπυνθάνετο. καὶ ὧδε μὲν ἡμῖν ἐπὶ τοῦ παρόντος ἐχέτω τὰ περὶ τούτου τοῦ βασιλέως.", "st": "9.13.3"}, {"sp": "N", "t": "Σαλμανάσσης δὲ ὁ τῶν Ἀσσυρίων βασιλεύς, ἐπεὶ ἠγγέλη αὐτῷ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς Ὠσείης πέμψας κρύφα πρὸς Σώαν τὸν τῶν Αἰγυπτίων βασιλέα παρακαλῶν αὐτὸν ἐπὶ συμμαχίαν τὴν κατ’ αὐτοῦ, παροξυνθεὶς ἐστράτευσεν ἐπὶ τὴν Σαμάρειαν ἔτει ἑβδόμῳ τῆς Ὠσήου βασιλείας. οὐ δεξαμένου δ’ αὐτὸν τοῦ βασιλέως ἔτεσι πολιορκήσας τρισὶν εἷλε κατὰ κράτος τὴν Σαμάρειαν, ἔνατον μὲν ἔτος Ὠσήου βασιλεύοντος ἕβδομον δὲ Ἐζεκίου τοῦ τῶν Ἱεροσολυμιτῶν βασιλέως, καὶ τὴν τῶν Ἰσραηλιτῶν ἡγεμονίαν ἄρδην ἠφάνισε καὶ πάντα τὸν λαὸν μετῴκισεν εἰς τὴν Μηδίαν καὶ Περσίδα, ἐν οἷς καὶ τὸν βασιλέα Ὠσῆν ζῶντα ἔλαβε. καὶ μεταστήσας ἄλλα ἔθνη ἀπὸ Χούθου τόπου τινός, ἔστι γὰρ ἐν τῇ Περσίδι ποταμὸς τοῦτ’ ἔχων τοὔνομα, κατῴκισεν εἰς τὴν Σαμάρειαν καὶ τὴν τῶν Ἰσραηλιτῶν χώραν. μετῴκησαν οὖν αἱ δέκα φυλαὶ τῶν Ἰσραηλιτῶν ἐκ τῆς Ἰουδαίας μετὰ ἐτῶν ἀριθμὸν ἐνακοσίων τεσσαρακονταεπτά, ἀφ’ οὗ χρόνου τὴν Αἴγυπτον ἐξῆλθον αὐτῶν οἱ πρόγονοι, ὃν δὲ κατέσχον τὴν χώραν ταύτην στρατηγοῦντος Ἰησοῦ ἔστιν ἐτῶν ὀκτακοσίων· ἀφ’ οὗ δ’ ἀποστάντες ἀπὸ Ῥοβοάμου τοῦ Δαυίδου υἱωνοῦ τὴν βασιλείαν Ἱεροβοάμῳ παρέδοσαν, ὥς μοι καὶ πρότερον δεδήλωται, ἔτη ἐστὶ διακόσια τεσσαράκοντα μῆνες ἑπτὰ ἡμέραι ἑπτά. καὶ τέλος μὲν τοὺς Ἰσραηλίτας τοιοῦτο κατέλαβε παραβάντας τοὺς νόμους καὶ παρακούσαντας τῶν προφητῶν, οἳ προύλεγον ταύτην αὐτοῖς τὴν συμφορὰν μὴ παυσαμένοις τῶν ἀσεβημάτων. ἦρξε δ’ αὐτοῖς τῶν κακῶν ἡ στάσις, ἣν ἐστασίασαν πρὸς Ῥοβόαμον τὸν Δαυίδου υἱωνὸν Ἱερόβαμον τὸν τούτου δοῦλον αὑτῶν ἀποδείξαντες βασιλέα, ὃς εἰς τὸ θεῖον ἐξαμαρτὼν ἐχθρὸν αὐτοῖς τοῦτο ἐποίησε μιμησαμένοις τὴν ἐκείνου παρανομίαν. ἀλλ’ ὁ μὲν ἧς ἦν ἄξιος δίκης ταύτην ὑπέσχεν.", "st": "9.14.1"}, {"sp": "N", "t": "Ὁ δὲ τῶν Ἀσσυρίων βασιλεὺς ἐπῆλθε πολεμῶν τήν τε Συρίαν πᾶσαν τήν τε Φοινίκην, τό τε ὄνομα τούτου τοῦ βασιλέως ἐν τοῖς Τυρίων ἀρχείοις ἀναγέγραπται· ἐστράτευσε γὰρ ἐπὶ Τύρον βασιλεύοντος αὐτῆς Ἐλουλαίου. μαρτυρεῖ δὲ καὶ τούτοις Μένανδρος ὁ τῶν χρονικῶν ποιησάμενος τὴν ἀναγραφὴν καὶ τὰ τῶν Τυρίων ἀρχεῖα μεταφράσας εἰς τὴν Ἑλληνικὴν γλῶτταν, ὃς οὕτως ἐδήλωσε· καὶ Ἐλουλαῖος θεμένων αὐτῷ Πύας ὄνομα ἐβασίλευσεν ἔτη τριακονταέξ. οὗτος ἀποστάντων Κιτταίων ἀναπλεύσας προσηγάγετο αὐτοὺς πάλιν. ἐπὶ τούτου Σελάμψας ὁ τῶν Ἀσσυρίων βασιλεὺς ἐπῆλθε Φοινίκην πολεμῶν ἅπασαν, ὅστις σπεισάμενος εἰρήνην μετὰ πάντων ἀνεχώρησεν ὀπίσω· ἀπέστη τε Τυρίων Σιδὼν καὶ Ἄρκη καὶ ἡ πάλαι Τύρος καὶ πολλαὶ ἄλλαι πόλεις, αἳ τῷ Ἀσσυρίων ἑαυτὰς βασιλεῖ παρέδοσαν. δι’ ἃ Τυρίων οὐχ ὑποταγέντων πάλιν ὁ βασιλεὺς ἐπ’ αὐτοὺς ὑπέστρεψε Φοινίκων συμπληρωσάντων αὐτῷ ναῦς ἑξήκοντα καὶ ἐπικώπους ὀκτακοσίους. αἷς ἐπιπλεύσαντες οἱ Τύριοι ναυσὶ δεκαδύο τῶν νεῶν τῶν ἀντιπάλων διασπαρεισῶν λαμβάνουσιν αἰχμαλώτους ἄνδρας εἰς πεντακοσίους· ἐπετάθη δὴ πάντων ἐν Τύρῳ τιμή. διὰ ταῦτ’ ἀναζεύξας ὁ τῶν Ἀσσυρίων βασιλεὺς κατέστησε φύλακας ἐπὶ τοῦ ποταμοῦ καὶ τῶν ὑδραγωγείων, οἳ διακωλύσουσι Τυρίους ἀρύεσθαι, καὶ τοῦτο ἔτεσι πέντε γενόμενον ἐκαρτέρησαν πίνοντες ἐκ φρεάτων ὀρυκτῶν. καὶ τὰ μὲν ἐν τοῖς Τυρίων ἀρχείοις γεγραμμένα κατὰ Σαλμανάσσου τοῦ Ἀσσυρίων βασιλέως ταῦτ’ ἐστίν.", "st": "9.14.2"}, {"sp": "N", "t": "Οἱ δὲ μετοικισθέντες εἰς τὴν Σαμάρειαν Χουθαῖοι, ταύτῃ γὰρ ἐχρῶντο μέχρι δεῦρο τῇ προσηγορίᾳ διὰ τὸ ἐκ τῆς Χουθᾶ καλουμένης χώρας μεταχθῆναι, αὕτη δ’ ἐστὶν ἐν τῇ Περσίδι καὶ ποταμὸς τοῦτ’ ἔχων ὄνομα, ἕκαστοι κατὰ ἔθνος ἴδιον θεὸν εἰς τὴν Σαμάρειαν κομίσαντες, πέντε δ’ ἦσαν, καὶ τούτους καθὼς ἦν πάτριον αὐτοῖς σεβόμενοι παροξύνουσι τὸν μέγιστον θεὸν εἰς ὀργὴν καὶ χόλον. λοιμὸν γὰρ αὐτοῖς ἐνέσκηψεν, ὑφ’ οὗ φθειρόμενοι οὐδεμίαν τῶν κακῶν θεραπείαν ἐπινοοῦντες χρησμῷ θρησκεύειν τὸν μέγιστον θεόν, ὡς τοῦτο σωτήριον αὐτοῖς ὄν, ἔμαθον. πέμψαντες οὖν πρὸς τὸν Ἀσσυρίων βασιλέα πρέσβεις ἐδέοντο ἱερεῖς αὐτοῖς ὧν ἔλαβεν αἰχμαλώτων τοὺς Ἰσραηλίτας πολεμήσας ἀποστεῖλαι. πέμψαντός τε τὰ νόμιμα καὶ τὴν περὶ τὸν θεὸν τοῦτον ὁσίαν διδαχθέντες ἐθρήσκευον αὐτὸν φιλοτίμως καὶ τοῦ λοιμοῦ παραχρῆμα ἐπαύσαντο. χρώμενοί τε τοῖς αὐτοῖς ἔτι καὶ νῦν ἔθεσι διατελοῦσιν οἱ κατὰ μὲν τὴν Ἑβραίων γλῶτταν Χουθαῖοι, κατὰ δὲ τὴν Ἑλλήνων Σαμαρεῖται, οἳ πρὸς μεταβολὴν συγγενεῖς μὲν ὅταν εὖ πράττοντας βλέπωσι τοὺς Ἰουδαίους ἀποκαλοῦσιν ὡς ἐξ Ἰωσήπου φύντες καὶ τὴν ἀρχὴν ἐκεῖθεν τῆς πρὸς αὐτοὺς ἔχοντες οἰκειότητος, ὅταν δὲ πταίσαντας ἴδωσιν, οὐδαμόθεν αὐτοῖς προσήκειν λέγουσιν οὐδ’ εἶναι δίκαιον οὐδὲν αὐτοῖς εὐνοίας ἢ γένους, ἀλλὰ μετοίκους ἀλλοεθνεῖς ἀποφαίνουσιν αὑτούς. περὶ μὲν τούτων ἕξομεν εὐκαιρότερον εἰπεῖν.", "st": "9.14.3"}, {"sp": "HDR", "t": "Βιβλίον Ιʹ", "st": "10"}, {"sp": "N", "t": "Ἐζεκίου δὲ τοῦ τῶν δύο φυλῶν βασιλέως τέταρτον ἤδη καὶ δέκατον ἔτος τῆς ἡγεμονίας ἔχοντος ὁ τῶν Βαβυλωνίων βασιλεὺς Σεναχείριμος ὄνομα στρατεύει μετὰ πολλῆς παρασκευῆς ἐπ’ αὐτὸν κατὰ κράτος τε ἁπάσας αἱρεῖ τὰς πόλεις τὰς τῆς Ἰούδα φυλῆς καὶ Βενιαμίτιδος. μέλλοντος δ’ ἄγειν τὴν δύναμιν καὶ ἐπὶ Ἱεροσόλυμα φθάνει πρεσβευσάμενος πρὸς αὐτὸν καὶ ὑπακούσεσθαι καὶ φόρον ὃν ἂν τάξῃ τελέσειν ὑπισχνούμενος. Σεναχείριμος δὲ μαθὼν τὰ παρὰ τῶν πρέσβεων ἔγνω μὴ πολεμεῖν, ἀλλὰ τὴν ἀξίωσιν προσδέχεται καὶ ἀργυρίου μὲν τάλαντα τριακόσια χρυσίου δὲ τριάκοντα λαβὼν φίλος ἀναχωρήσειν ὡμολόγει πίστεις δοὺς τοῖς πρεσβευταῖς ἐνόρκους, ἦ μὴν ἀδικήσας μηδὲν αὐτὸν οὕτως ἀναστρέψειν. ὁ δ’ Ἐζεκίας πεισθεὶς καὶ κενώσας τοὺς θησαυροὺς πέμπει τὰ χρήματα νομίζων ἀπαλλαγήσεσθαι τοῦ πολέμου καὶ τοῦ περὶ τῆς βασιλείας ἀγῶνος. ὁ δὲ Ἀσσύριος λαβὼν ταῦτα τῶν μὲν ὡμολογημένων οὐδὲν ἐφρόντισεν, ἀλλ’ αὐτὸς μὲν ἐστράτευσεν ἐπ’ Αἰγυπτίους καὶ Αἰθίοπας, τὸν δὲ στρατηγὸν Ῥαψάκην μετὰ πολλῆς ἰσχύος σὺν καὶ δυσὶν ἄλλοις τῶν ἐν τέλει κατέλιπε πορθήσοντας τὰ Ἱεροσόλυμα. τούτων δὲ τὰ ὀνόματα Θαρατὰ καὶ Ἀράχαρις ἦν.", "st": "10.1.1"}, {"sp": "N", "t": "Ὡς δ’ ἐλθόντες πρὸ τῶν τειχῶν ἐστρατοπεδεύσαντο, πέμψαντες πρὸς τὸν Ἐζεκίαν ἠξίουν αὐτὸν ἐλθεῖν εἰς λόγους. ὁ δὲ αὐτὸς μὲν ὑπὸ δειλίας οὐ πρόεισι, τρεῖς δὲ τοὺς ἀναγκαιοτάτους φίλους αὐτῷ ἐξέπεμψε, τὸν τῆς βασιλείας ἐπίτροπον Ἐλιακίαν ὄνομα καὶ Σουβαναῖον καὶ Ἰώανον τὸν ἐπὶ τῶν ὑπομνημάτων. οὗτοι μὲν οὖν προελθόντες ἀντικρὺ τῶν ἡγεμόνων τῆς στρατιᾶς τῶν Ἀσσυρίων ἔστησαν, θεασάμενος δ’ αὐτοὺς ὁ στρατηγὸς Ῥαψάκης ἐκέλευσεν ἀπελθόντας Ἐζεκίᾳ λέγειν, ὅτι βασιλεὺς μέγας Σεναχείριμος πυνθάνεται αὐτοῦ, τίνι θαρρῶν καὶ πεποιθὼς φεύγει δεσπότην αὐτοῦ καὶ ἀκροάσασθαι μὴ θέλει καὶ τὴν στρατιὰν οὐ δέχεται τῇ πόλει; ἦ διὰ τοὺς Αἰγυπτίους τὴν αὐτοῦ στρατιὰν ἐλπίζων ὑπ’ ἐκείνων αὐτῶν καταγωνίσασθαι; εἰ δὲ τοῦτο προσδοκᾷ, δηλοῦν αὐτῷ, ὅτι ἀνόητός ἐστι καὶ ὅμοιος ἀνθρώπῳ, ὃς καλάμῳ ἐπερειδόμενος τεθλασμένῳ πρὸς τῷ καταπεσεῖν ἔτι καὶ τὴν χεῖρα διαπαρεὶς ᾔσθετο τῆς βλάβης. εἰδέναι δ’ ὅτι καὶ βουλήσει θεοῦ τὴν ἐπ’ αὐτὸν στρατείαν πεποίηται, ὃς αὐτῷ καταστρέψασθαι καὶ τὴν τῶν Ἰσραηλιτῶν βασιλείαν δέδωκεν, ἵνα τὸν αὐτὸν τρόπον καὶ τοὺς ἀρχομένους ὑπ’ αὐτοῦ διαφθείρῃ. ταῦτα δὲ τὸν Ῥαψάκην ἑβραϊστὶ λέγοντα, τῆς γὰρ γλώττης εἶχεν ἐμπείρως, ὁ Ἐλιάκειμος φοβούμενος, μὴ τὸ πλῆθος ἐπακοῦσαν εἰς ταραχὴν ἐμπέσῃ, συριστὶ φράζειν ἠξίου. συνεὶς δ’ ὁ στρατηγὸς τὴν ὑπόνοιαν αὐτοῦ καὶ τὸ ἐπ’ αὐτῷ δέος μείζονι καὶ διατόρῳ τῇ φωνῇ χρώμενος ἀπεκρίνατο αὐτῷ ἑβραϊστὶ λέγειν, ὅπως ἀκούσαντες τὰ τοῦ βασιλέως προστάγματα πάντες τὸ συμφέρον ἕλωνται παραδόντες αὑτοὺς ἡμῖν· δῆλον γὰρ ὡς τὸν λαὸν ὑμεῖς τε καὶ ὁ βασιλεὺς ἐλπίσι παρακρουόμενοι ματαίαις ἀντέχειν πείθετε. εἰ δὲ θαρρεῖτε καὶ τὴν δύναμιν ἡμῶν ἀπώσεσθαι νομίζετε, δισχιλίους ἐκ τῆς ἐμοὶ παρούσης ἵππους ἕτοιμός εἰμι ὑμῖν παρέχειν, οἷς ἰσαρίθμους ἐπιβάτας δόντες ἐμφανίσατε τὴν αὑτῶν δύναμιν· ἀλλ’ οὐκ ἂν οὕς γε μὴ ἔχετε τούτους δῴητε. τί τοιγαροῦν βραδύνετε παραδιδόναι σφᾶς αὐτοὺς τοῖς κρείττοσι καὶ ληψομένοις ὑμᾶς καὶ μὴ θέλοντας; καίτοι τὸ μὲν ἑκούσιον τῆς παραδόσεως ἀσφαλὲς ὑμῖν, τὸ δὲ ἀκούσιον πολεμουμένοις ἐπικίνδυνον καὶ συμφορῶν αἴτιον φανεῖται.", "st": "10.1.2"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσαντες ὅ τε δῆμος καὶ οἱ πρέσβεις τοῦ στρατηγοῦ τῶν Ἀσσυρίων λέγοντος ἀπήγγειλαν Ἐζεκίᾳ. ὁ δὲ πρὸς ταῦτα τὴν βασιλικὴν ἀποδὺς ἐσθῆτα, ἀμφιασάμενος δὲ σάκκους καὶ σχῆμα ταπεινὸν ἀναλαβὼν τῷ πατρίῳ νόμῳ πεσὼν ἐπὶ πρόσωπον τὸν θεὸν ἱκέτευε καὶ βοηθῆσαι τῷ μηδεμίαν ἄλλην ἐλπίδα ἔχοντι σωτηρίας ἠντιβόλει. πέμψας δὲ καὶ τῶν φίλων τινὰς καὶ τῶν ἱερέων πρὸς Ἡσαΐαν τὸν προφήτην ἠξίου δεηθῆναι τοῦ θεοῦ καὶ ποιησάμενον θυσίας ὑπὲρ τῆς κοινῆς σωτηρίας παρακαλεῖν αὐτὸν νεμεσῆσαι μὲν ταῖς τῶν πολεμίων ἐλπίσιν, ἐλεῆσαι δὲ τὸν αὐτοῦ λαόν. ὁ δὲ προφήτης ταῦτα ποιήσας χρηματίσαντος αὐτῷ τοῦ θεοῦ παρεθάρρυνεν αὐτόν τε τὸν βασιλέα καὶ τοὺς περὶ αὐτὸν φίλους προλέγων ἀμαχητὶ τοὺς πολεμίους ἡττηθέντας ἀναχωρήσειν αἰσχρῶς καὶ οὐχὶ μεθ’ οἵου νῦν εἰσι θράσους· τὸν γὰρ θεὸν προνοεῖν ὅπως διαφθαρῶσι· καὶ αὐτὸν δὲ τὸν βασιλέα τῶν Ἀσσυρίων Σεναχείριμον διαμαρτόντα τῶν ἐπὶ τὴν Αἴγυπτον πραγμάτων καὶ ἐπανερχόμενον εἰς τὴν οἰκείαν ἀπολεῖσθαι σιδήρῳ προύλεγεν.", "st": "10.1.3"}, {"sp": "N", "t": "Ἔτυχε δ’ ὑπὸ τὸν αὐτὸν καιρὸν καὶ γεγραφὼς τῷ Ἐζεκίᾳ ὁ Ἀσσύριος ἐπιστολάς, ἐν αἷς ἀνόητον μὲν αὐτὸν ἔλεγεν ὑπολαμβάνοντα τὴν ὑπ’ αὐτῷ διαφεύξεσθαι δουλείαν ἔθνη πολλὰ καὶ μεγάλα κεχειρωμένῳ, ἠπείλει δὲ πανωλεθρίᾳ διαφθερεῖν αὐτὸν παραλαβών, εἰ μὴ τὰς πύλας ἀνοίξας ἑκὼν αὐτοῦ δέξεται τὴν στρατιὰν εἰς τὰ Ἱεροσόλυμα. ταῦτ’ ἀναγνοὺς καταφρονεῖ διὰ τὴν ἀπὸ τοῦ θεοῦ πεποίθησιν, τὰς δ’ ἐπιστολὰς πτύξας εἰς τὸν ναὸν ἔσω κατέθετο. πάλιν δὲ τῷ θεῷ τὰς εὐχὰς αὐτοῦ ποιησαμένου περὶ τῆς πόλεως καὶ τῆς ἁπάντων σωτηρίας Ἡσαΐας ὁ προφήτης ἐπήκοον αὐτὸν ἔφασκε γεγονέναι καὶ κατὰ τὸν παρόντα καιρὸν μὴ πολιορκηθήσεσθαι ὑπὸ τοῦ Σύρου, μέλλοντι πάντων ἀδεεῖς τῶν ὑπ’ αὐτοῦ γενομένων γεωργήσειν μετ’ εἰρήνης καὶ τῶν ἰδίων ἐπιμελήσεσθαι κτημάτων οὐδὲν φοβουμένους. ὀλίγου δὲ χρόνου διελθόντος καὶ ὁ τῶν Ἀσσυρίων βασιλεὺς διαμαρτὼν τῆς ἐπὶ τοὺς Αἰγυπτίους ἐπιβολῆς ἄπρακτος ἀνεχώρησεν ἐπ’ οἴκου δι’ αἰτίαν τοιαύτην· πολὺς αὐτῷ χρόνος ἐτρίβετο πρὸς τὴν Πηλουσίου πολιορκίαν, καὶ τῶν χωμάτων ἤδη μετεώρων ὄντων, ἃ πρὸς τοῖς τείχεσιν ἤγειρε, καὶ ὅσον οὔπω μέλλοντος προσβαλεῖν αὐτοῖς, ἀκούει τὸν τῶν Αἰθιόπων βασιλέα Θαρσικὴν πολλὴν ἄγοντα δύναμιν ἐπὶ συμμαχίᾳ τοῖς Αἰγυπτίοις ἥκειν διεγνωκότα ποιήσασθαι τὴν πορείαν διὰ τῆς ἐρήμου καὶ ἐξαίφνης εἰς τὴν τῶν Ἀσσυρίων ἐμβαλεῖν. ταραχθεὶς οὖν ὑπὸ τούτων ὁ βασιλεὺς Σεναχείριμος ἐπὶ τὸν ἱερέα τὸν Ἡφαίστου στρατεῦσαι ἔλεγεν ὡς οὗτος ὁ βασιλεὺς ἐπὶ τὸν τῶν Αἰγυπτίων ἔλθοι βασιλέα ἱερέα ὄντα τοῦ Ἡφαίστου, πολιορκῶν δὲ τὸ Πηλούσιον ἔλυσε τὴν πολιορκίαν ἐξ αἰτίας τοιαύτης· ηὔξατο ὁ βασιλεὺς τῶν Αἰγυπτίων τῷ θεῷ, ᾧ γενόμενος ἐπήκοος ὁ θεὸς πληγὴν ἐνσκήπτει τῷ Ἄραβι· πλανᾶται γὰρ κἀν τούτῳ οὐκ Ἀσσυρίων λέγων τὸν βασιλέα ἀλλ’ Ἀράβων· μυῶν γὰρ πλῆθός φησι μιᾷ νυκτὶ τὰ τόξα καὶ τὰ λοιπὰ ὅπλα διαφαγεῖν τῶν Ἀσσυρίων, καὶ διὰ τοῦτο μὴ ἔχοντα τόξα τὸν βασιλέα τὴν στρατιὰν ἀπάγειν ἀπὸ τοῦ Πηλουσίου. καὶ Ἡρόδοτος μὲν οὕτως ἱστορεῖ, Βηρωσὸς δὲ ὁ τὰ Χαλδαϊκὰ συγγραψάμενος μνημονεύει τοῦ βασιλέως τοῦ Σεναχειρίμου, καὶ ὅτι τῶν Ἀσσυρίων ἦρχε καὶ ὅτι πάσῃ ἐπεστρατεύσατο τῇ Ἀσίᾳ [καὶ τῇ Αἰγύπτῳ] λέγων οὕτως·", "st": "10.1.4"}, {"sp": "N", "t": "Ὑποστρέψας δ’ ὁ Σεναχείριμος ἀπὸ τῶν Αἰγυπτίων πολέμων εἰς τὰ Ἱεροσόλυμα, καταλαβὼν ἐκεῖ τὴν ὑπὸ τῷ στρατηγῷ Ῥαψάκῃ δύναμιν τοῦ θεοῦ λοιμικὴν ἐνσκήψαντος αὐτοῦ τῷ στρατῷ νόσον κατὰ τὴν πρώτην νύκτα τῆς πολιορκίας διαφθείρονται μυριάδες ὀκτωκαίδεκα καὶ πεντακισχίλιοι σὺν ἡγεμόσι καὶ ταξιάρχαις. ὑπὸ ταύτης δὲ τῆς συμφορᾶς εἰς φόβον καὶ δεινὴν ἀγωνίαν καταστὰς καὶ δείσας περὶ τῷ στρατῷ παντὶ φεύγει μετὰ τῆς λοιπῆς δυνάμεως εἰς τὴν αὑτοῦ βασιλείαν τὴν Νίνου προσαγορευθεῖσαν. καὶ διατρίψας ἐν αὐτῇ ὀλίγον χρόνον δολοφονηθεὶς ὑπὸ τῶν πρεσβυτέρων παίδων Ἀνδρομάχου καὶ Σελευκάρου τελευτᾷ τὸν βίον καὶ ἀνετέθη τῷ ἰδίῳ ναῷ Ἀράσκῃ λεγομένῳ. καὶ οἱ μὲν φυγαδευθέντες ἐπὶ τῷ φόνῳ τοῦ πατρὸς ὑπὸ τῶν πολιτῶν εἰς τὴν Ἀρμενίαν ἀπῆραν, διαδέχεται δὲ τὴν βασιλείαν τῶν μετ’ αὐτοὺς καταφρονῶν τοῦ Σεναχειρίμου Ἀσαραχόδδας. καὶ τὸ μὲν τῆς Ἀσσυρίων στρατείας τῆς ἐπὶ τοὺς Ἱεροσολυμίτας τέλος τοιοῦτο συνέβη γενέσθαι.", "st": "10.1.5"}, {"sp": "N", "t": "Ἐζεκίας δ’ ὁ βασιλεὺς παραδόξως ἀπαλλαγεὶς τῶν φόβων χαριστηρίους σὺν ἅπαντι τῷ λαῷ θυσίας ἐπετέλεσε τῷ θεῷ, μηδεμιᾶς ἄλλης αἰτίας τῶν πολεμίων τοὺς μὲν διαφθειράσης τοὺς δὲ φόβῳ τῆς ὁμοίας τελευτῆς ἀπαλλαξάσης ἀπὸ τῶν Ἱεροσολυμιτῶν ἢ τῆς συμμαχίας τῆς ἀπὸ τοῦ θεοῦ. πάσῃ δὲ χρησάμενος σπουδῇ καὶ φιλοτιμίᾳ περὶ τὸν θεὸν μετ’ οὐ πολὺ νόσῳ χαλεπῇ περιπεσὼν ἀπέγνωστο μὲν ὑπὸ τῶν ἰατρῶν, χρηστὸν δὲ περὶ αὑτοῦ οὐδὲν προσδοκῶν, οὐδὲ γὰρ οἱ φίλοι. τῇ δὲ νόσῳ προσετίθετο καὶ ἀθυμία δεινὴ ὑπὸ τοῦ βασιλέως αὐτοῦ τὴν ἀπαιδίαν λογιζομένου, καὶ ὅτι μέλλοι τελευτᾶν ἔρημον καταλιπὼν τὸν οἶκον καὶ τὴν ἀρχὴν γνησίας διαδοχῆς. κάμνων οὖν ὑπ’ αὐτῆς τῆς ἐννοίας μάλιστα καὶ ὀδυρόμενος ἱκέτευε τὸν θεὸν αὐτῷ ζωῆς ὀλίγον χρόνον προσεπιδοῦναι μέχρι τέκνων γονῆς, καὶ μὴ πρότερον ἢ πατὴρ γένηται τὴν ψυχὴν αὐτὸν ἐᾶσαι καταλιπεῖν. ἐλεήσας δὲ αὐτὸν ὁ θεὸς καὶ τῆς αἰτήσεως ἀποδεξάμενος, ὅτι μὴ διὰ τὸ μέλλειν στέρεσθαι τῶν ἐκ τῆς βασιλείας ἀγαθῶν ὠδύρετο τὴν ὑπονοηθεῖσαν τελευτὴν ἔτι τε χρόνον ζωῆς αὐτῷ δεηθείη παρασχεῖν, ἀλλὰ τοῦ παῖδας αὐτῷ γενέσθαι τοὺς ὑποδεξομένους τὴν ἡγεμονίαν ἐκείνου, πέμψας Ἡσαΐαν τὸν προφήτην ἐκέλευσε δηλοῦν αὐτῷ, ὅτι καὶ διαφεύξεται τὴν νόσον μετὰ τρίτην ἡμέραν καὶ βιώσεται μετ’ αὐτὴν ἔτη πεντεκαίδεκα καὶ παῖδες αὐτῷ γενήσονται. ταῦτα τοῦ προφήτου φήσαντος κατ’ ἐντολὴν τοῦ θεοῦ διὰ τὴν ὑπερβολὴν τῆς νόσου καὶ τὸ παράδοξον τῶν ἀπηγγελμένων ἀπιστῶν σημεῖόν τι καὶ τεράστιον ἠξίου ποιῆσαι τὸν Ἡσαΐαν, ἵνα αὐτῷ πιστεύσῃ λέγοντι ταῦτα ἥκοντι παρὰ τοῦ θεοῦ· τὰ γὰρ παράλογα καὶ μείζω τῆς ἐλπίδος τοῖς ὁμοίοις πιστοῦται πράγμασιν. ἐρωτήσαντος δ’ αὐτὸν τί βούλεται σημεῖον γενέσθαι, τὸν ἥλιον ἠξίωσεν, ἐπειδὴ σκιὰν ἐπὶ δέκα βαθμοὺς ἀποκλίνας ἤδη πεποίηκεν ἐν τῇ οἰκίᾳ, ἐπὶ τὸν αὐτὸν ἀναστρέψαι τόπον ποιήσας αὐτὴν πάλιν παρασχεῖν. τοῦ δὲ προφήτου τὸν θεὸν παρακαλέσαντος, ὥστε τὸ σημεῖον τοῦτ’ ἐπιδεῖξαι τῷ βασιλεῖ, ἰδὼν ὅπερ ἤθελεν εὐθὺς λυθεὶς τῆς νόσου ἄνεισιν εἰς τὸ ἱερὸν καὶ τῷ θεῷ προσκυνήσας εὐχὰς ἐποιήσατο.", "st": "10.2.1"}, {"sp": "N", "t": "Ἐν τούτῳ δὲ τῷ χρόνῳ συνέβη τὴν τῶν Ἀσσυρίων ἀρχὴν ὑπὸ Μήδων καταλυθῆναι· δηλώσω δὲ περὶ τούτων ἐν ἑτέροις. ὁ δὲ τῶν Βαβυλωνίων βασιλεὺς Βαλάδας ὄνομα πέμψας πρὸς τὸν Ἐζεκίαν πρέσβεις δῶρα κομίζοντας σύμμαχόν τε αὐτὸν εἶναι παρεκάλει καὶ φίλον. ὁ δὲ τοὺς πρεσβευτὰς ἡδέως ἀποδεξάμενος ἑστιασάμενός τε καὶ τοὺς θησαυροὺς ἐπιδείξας αὐτοῖς καὶ τὴν τῶν ὅπλων παρασκευὴν καὶ τὴν ἄλλην πολυτέλειαν, ὅσην ἐν λίθοις εἶχε καὶ χρυσῷ, δῶρά τε δοὺς κομίζειν τῷ Βαλάδῳ πρὸς αὐτὸν ἀπέλυσεν. Ἡσαΐου δὲ τοῦ προφήτου πρὸς αὐτὸν ἀφικομένου καὶ πυνθανομένου πόθεν εἶεν οἱ παρόντες, ἐκ Βαβυλῶνος ἔλεγε παρὰ τοῦ θεοῦ ἐλθεῖν αὐτούς· ἐπιδεῖξαι δὲ πάντ’ αὐτοῖς, ὅπως ἰδόντες τὸν πλοῦτον καὶ τὴν δύναμιν ἐκ τούτου στοχαζόμενοι σημαίνειν ἔχωσι τῷ βασιλεῖ. ὁ δὲ προφήτης ὑποτυχών ἴσθι, φησίν, οὐ μετ’ ὀλίγον χρόνον εἰς Βαβυλῶνά σου τοῦτον μετατεθησόμενον τὸν πλοῦτον καὶ τοὺς ἐκγόνους εὐνουχισθησομένους καὶ ἀπολέσαντας τὸ ἄνδρας εἶναι τῷ Βαβυλωνίῳ δουλεύσοντας βασιλεῖ· ταῦτα γὰρ προλέγειν τὸν θεόν. ὁ δ’ Ἐζεκίας λυπηθεὶς ἐπὶ τοῖς εἰρημένοις ἔφη μὲν οὐκ ἂν βούλεσθαι τοιαύταις συμφοραῖς τὸ ἔθνος αὐτοῦ περιπεσεῖν, ἐπεὶ δ’ οὐκ εἶναι δυνατὸν τὰ τῷ θεῷ δεδογμένα μεταβαλεῖν, ηὔχετο μέχρι τῆς αὐτοῦ ζωῆς εἰρήνην ὑπάρξαι. μνημονεύει δὲ τοῦ τῶν Βαβυλωνίων βασιλέως Βαλαδᾶ Βηρωσός. ὢν δ’ οὗτος ὁ προφήτης θεῖος ὁμολογουμένως καὶ θαυμάσιος τὴν ἀλήθειαν, πεποιθὼς τῷ μηδὲν ὅλως ψευδὲς εἰπεῖν ἅπανθ’ ὅσα προεφήτευσεν ἐγγράψας βίβλοις κατέλιπεν ἐκ τοῦ τέλους γνωρισθησόμενα τοῖς αὖθις ἀνθρώποις. καὶ οὐχ οὗτος μόνος ὁ προφήτης, ἀλλὰ καὶ ἄλλοι δώδεκα τὸν ἀριθμὸν τὸ αὐτὸ ἐποίησαν, καὶ πᾶν εἴ τι φαῦλον γίνεται παρ’ ἡμῖν κατὰ τὴν ἐκείνων ἀποβαίνει προφητείαν. ἀλλὰ τούτων μὲν αὖθις ἐξαγγελοῦμεν ἕκαστον.", "st": "10.2.2"}, {"sp": "N", "t": "Ἐπιβιοὺς δ’ ὃν προειρήκαμεν χρόνον ὁ βασιλεὺς Ἐζεκίας καὶ πάντα τοῦτον ἐν εἰρήνῃ διαγαγὼν τελευτᾷ πεντηκοστὸν μὲν καὶ τέταρτον ἔτος τῆς ζωῆς διανύσας, εἴκοσι δὲ βασιλεύσας καὶ ἐννέα. διαδεξάμενος δὲ τὴν βασιλείαν ὁ παῖς αὐτοῦ Μανασσῆς ἐκ μητρὸς μὲν Ἐχίβας τοὔνομα πολίτιδος γεγονώς, ἀπέρρηξεν ἑαυτὸν τῶν τοῦ πατρὸς ἐπιτηδευμάτων καὶ τὴν ἐναντίαν ἐτράπετο πᾶν εἶδος πονηρίας ἐπιδειξάμενος ἐν τῷ τρόπῳ καὶ μηδὲν ἀσεβὲς παραλιπών, ἀλλὰ μιμούμενος τὰς τῶν Ἰσραηλιτῶν παρανομίας, οἳ εἰς τὸν θεὸν ἁμαρτόντες ἀπώλοντο· μιᾶναι δὲ καὶ τὸν ναὸν ἐτόλμησε τοῦ θεοῦ καὶ τὴν πόλιν καὶ τὴν χώραν ἅπασαν. ἀπὸ γὰρ τῆς εἰς τὸν θεὸν καταφρονήσεως ὁρμώμενος πάντας τοὺς δικαίους τοὺς ἐν τοῖς Ἑβραίοις ἀπέκτεινεν, ἀλλ’ οὐδὲ τῶν προφητῶν ἔσχε φειδὼ καὶ τούτων δέ τινας καθ’ ἡμέραν ἀπέσφαζεν, ὥστε αἵματι ῥεῖσθαι τὰ Ἱεροσόλυμα. λαβὼν οὖν ὀργὴν ἐπὶ τούτοις ὁ θεὸς πέμπει προφήτας πρὸς τὸν βασιλέα καὶ τὸ πλῆθος, δι’ ὧν αὐτοῖς ἠπείλησε τὰς αὐτὰς συμφοράς, αἷς συνέβη περιπεσεῖν τοὺς ἀδελφοὺς αὐτῶν Ἰσραηλίτας εἰς αὐτὸν ἐξυβρίζοντας. οἱ δὲ τοῖς μὲν λόγοις οὐκ ἐπίστευον, παρ’ ὧν ἠδύναντο κερδῆσαι τὸ μηδενὸς πειραθῆναι κακοῦ, τοῖς δ’ ἔργοις ἔμαθον ἀληθῆ τὰ παρὰ τῶν προφητῶν.", "st": "10.3.1"}, {"sp": "N", "t": "Ὡς γὰρ τοῖς αὐτοῖς ἐπέμενον, πόλεμον ἐπ’ αὐτοὺς ἐκίνει παρά τε τοῦ τῶν Βαβυλωνίων καὶ Χαλδαίων βασιλέως, ὃς στρατιὰν πέμψας εἰς τὴν Ἰουδαίαν τήν τε χώραν αὐτῶν ἐλεηλάτησε καὶ τὸν βασιλέα Μανασσῆν δόλῳ ληφθέντα καὶ πρὸς αὐτὸν ἀχθέντα πρὸς ἣν ἠβούλετο τιμωρίαν εἶχεν ὑποχείριον. ὁ δὲ Μανασσῆς τότε συνεὶς ἐν οἵοις κακοῖς ἐστι καὶ πάντων ἑαυτὸν αἴτιον νομίζων ἐδεῖτο τοῦ θεοῦ παρέχειν αὐτῷ φιλάνθρωπον καὶ ἐλεήμονα τὸν πολέμιον. χαρίζεται τοῦτο τῆς ἱκεσίας ἐπακούσας ὁ θεὸς αὐτῷ καὶ πάλιν εἰς τὴν οἰκείαν ὁ Μανασσῆς ἀπολυθεὶς ὑπὸ τοῦ τῶν Βαβυλωνίων βασιλέως ἀνασώζεται. γενόμενος δ’ εἰς τὰ Ἱεροσόλυμα τῶν μὲν προτέρων ἁμαρτημάτων περὶ τὸν θεὸν καὶ τὴν μνήμην ἐσπούδαζεν, εἰ δυνατὸν αὐτῷ γένοιτο, τῆς ψυχῆς ἐκβαλεῖν, ὧν ἐπιβουλεύειν ὥρμησε καὶ πάσῃ χρῆσθαι περὶ αὐτὸν δεισιδαιμονίᾳ· καὶ τὸν ναὸν ἥγνισε καὶ τὴν πόλιν ἐκάθηρε καὶ πρὸς μόνῳ τὸ λοιπὸν ἦν τῷ χάριν τε τῆς σωτηρίας ἐκτείνειν τῷ θεῷ καὶ διατηρεῖν αὐτὸν εὐμενῆ παρ’ ὅλον τὸν βίον. τὰ δὲ αὐτὰ πράττειν καὶ τὸ πλῆθος ἐδίδασκε μεμαθηκώς, οἵᾳ παρὰ μικρὸν ἐχρήσατο συμφορᾷ διὰ τὴν ἐναντίαν πολιτείαν. ἐπισκευάσας δὲ καὶ τὸν βωμὸν τὰς νομίμους θυσίας ἐπετέλει, καθὼς διέταξε Μωυσῆς. διοικησάμενος δὲ τὰ περὶ τὴν θρησκείαν ὃν δεῖ τρόπον καὶ τῆς τῶν Ἱεροσολύμων ἀσφαλείας προενόησεν, ὥστε τὰ παλαιὰ τείχη μετὰ πολλῆς ἐπισκευάσας σπουδῆς καὶ ἕτερον αὐτοῖς ἐπιβαλεῖν, ἀναστῆσαί τε καὶ πύργους ὑψηλοτάτους τά τε πρὸ τῆς πόλεως φρούρια τοῖς τ’ ἄλλοις καὶ δὴ καὶ σιτίων πάντων τῶν εἰς αὐτὰ χρησίμων ὀχυρώτερα ποιῆσαι. ἀμέλει δὲ τῇ πρὸς ταῦτα μεταβολῇ χρησάμενος οὕτω τὸν μεταξὺ διῆγε βίον, ὡς μακαριστὸς εἶναι καὶ ζηλωτὸς ἐκείνου τοῦ χρόνου λογιζομένου, ἀφ’ οὗ τὸν θεὸν εὐσεβεῖν ἤρξατο. ζήσας οὖν ἔτη ἑξήκοντα ἑπτὰ κατέστρεψε τὸν βίον βασιλεύσας ἔτη πέντε καὶ πεντήκοντα. καὶ θάπτεται μὲν αὐτὸς ἐν τοῖς αὐτοῦ παραδείσοις, ἡ βασιλεία δὲ εἰς τὸν υἱὸν αὐτοῦ παραγίνεται Ἀμμῶνα μητρὸς Ἐμασέλμης μὲν ὄνομα τετυχηκότα, ἐκ δὲ πόλεως Ἰαζαβάτης ὑπαρχούσης.", "st": "10.3.2"}, {"sp": "N", "t": "Οὗτος μιμησάμενος τὰ τοῦ πατρὸς ἔργα, ἃ νέος ὢν ἐκεῖνος ἐτόλμησεν, ἐπιβουλευθεὶς ὑπὸ τῶν ἰδίων οἰκετῶν ἀπέθανεν ἐπὶ τῆς οἰκίας τῆς αὑτοῦ βιώσας ἔτη τέσσαρα καὶ εἴκοσι, βασιλεύσας δ’ ἐξ αὐτῶν δύο. μετῆλθε δ’ αὐτοῦ τὸ πλῆθος τοὺς φονεῖς καὶ τῷ πατρὶ συνθάπτουσι τὸν Ἀμμῶνα, τὴν δὲ βασιλείαν τῷ παιδὶ αὐτοῦ Ἰωσίᾳ παραδιδοῦσιν ὀκταετεῖ τὴν ἡλικίαν ὄντι, ᾧ μήτηρ ἐκ πόλεως μὲν ἦν Βοσκέθ, Ἰέδις δὲ τοὔνομα. τὴν δὲ φύσιν αὐτὸς ἄριστος ὑπῆρχε καὶ πρὸς ἀρετὴν εὖ γεγονὼς Δαυίδου τοῦ βασιλέως ἐπιτηδευμάτων καὶ σκοπῷ καὶ κανόνι τῆς ὅλης περὶ τὸν βίον ἐπιτηδεύσεως ἐκείνῳ κεχρημένος. γενόμενος δὲ ἐτῶν δυοκαίδεκα τὴν εὐσέβειαν καὶ τὴν δικαιοσύνην ἐπεδείξατο· τὸν γὰρ λαὸν ἐσωφρόνιζε καὶ παρῄνει τῆς περὶ τῶν εἰδώλων δόξης ὡς οὐχὶ θεῶν ὄντων ἀποστάντας σέβειν τὸν πάτριον θεόν, τά τε τῶν προγόνων ἐπισκοπῶν ἔργα τὰ μὲν ἁμαρτηθέντα διώρθου συνετῶς ὡς ἂν πρεσβύτατος καὶ νοῆσαι τὸ δέον ἱκανώτατος, ὅσα δ’ εὕρισκεν εὖ γεγονότα κατὰ χώραν ἐφύλαττέ τε καὶ ἐμιμεῖτο. ταῦτα δ’ ἔπραττε σοφίᾳ καὶ ἐπινοίᾳ τῆς φύσεως χρώμενος καὶ τῇ τῶν πρεσβυτέρων πειθόμενος συμβουλίᾳ καὶ παραδόσει· τοῖς γὰρ νόμοις κατακολουθῶν ὡς περὶ τὴν τάξιν τῆς πόλεως καὶ περὶ τὸ θεῖον εὐσεβείας εὐοδεῖν τε συνέβαινε διὰ τὴν τῶν πρώτων παρανομίαν μὴ τυγχάνειν ἀλλ’ ἐξηφανίσθαι· περιιὼν γὰρ ὁ βασιλεὺς καὶ τὴν πόλιν καὶ τὴν χώραν ἅπασαν τά τε ἄλση τὰ τοῖς ξενικοῖς ἀνειμένα θεοῖς ἐξέκοψε καὶ τοὺς βωμοὺς αὐτῶν κατέσκαψεν, εἴ τι δ’ ἀνάθημα τούτοις ὑπὸ τῶν προγόνων ἀνέκειτο περιυβρίζων κατέσπα. καὶ τούτῳ τῷ τρόπῳ τὸν λαὸν ἀπὸ τῆς περὶ αὐτοὺς δόξης εἰς τὴν τοῦ θεοῦ θρησκείαν ἐπέστρεψε καὶ τὰς συνήθεις ἐπέφερε θυσίας αὐτοῦ τῷ βωμῷ καὶ τὰς ὁλοκαυτώσεις. ἀπέδειξε δέ τινας κριτὰς καὶ ἐπισκόπους, ὡς ἂν διοικοῖεν τὰ παρ’ ἑκάστοις πράγματα περὶ παντὸς τὸ δίκαιον ποιούμενοι καὶ τῆς ψυχῆς οὐκ ἔλασσον αὐτὸ περιέποντες. διαπέμψας δὲ κατὰ πᾶσαν τὴν χώραν χρυσὸν καὶ ἄργυρον τοὺς βουλομένους ἐκέλευε κομίζειν εἰς ἐπισκευὴν τοῦ ναοῦ, ὅσον τις ἢ προαιρέσεως ἢ δυνάμεως ἔχει. κομισθέντων δὲ τῶν χρημάτων τῆς ἐπιμελείας τοῦ ναοῦ καὶ τῆς εἰς τοῦτο δαπάνης προύστησε τόν τ’ ἐπὶ τῆς πόλεως Ἀμασίαν καὶ τὸν γραμματέα Σαφᾶν καὶ τὸν γραφέα τῶν ὑπομνημάτων Ἰωάτην καὶ τὸν ἀρχιερέα Ἐλιακίαν, οἳ μηδὲν ὑπερθέσει μηδὲ ἀναβολῇ δόντες ἀρχιτέκτονας καὶ πάνθ’ ὅσα πρὸς τὴν ἐπισκευὴν χρήσιμα παρασκευάσαντες εἴχοντο τῶν ἔργων. καὶ ὁ μὲν ναὸς οὕτως ἐπισκευασθεὶς τὴν τοῦ βασιλέως εὐσέβειαν φανερὰν ἐποίησεν.", "st": "10.4.1"}, {"sp": "N", "t": "Ὄγδοον δ’ ἤδη καὶ δέκατον τῆς βασιλείας ἔτος ἔχων πέμπει πρὸς Ἐλιακίαν τὸν ἀρχιερέα κελεύων τὸ περισσὸν χωνεύσαντα ποιῆσαι κρατῆρας καὶ σπονδεῖα καὶ φιάλας εἰς τὴν διακονίαν, ἔτι δὲ καὶ ὅσος ἂν ᾖ χρυσὸς ἐν τοῖς θησαυροῖς καὶ ἄργυρος καὶ τοῦτον προκομίσαντας εἰς τοὺς κρατῆρας ὁμοίως καὶ τὰ τοιαῦτα σκεύη δαπανῆσαι. προκομίζων δὲ τὸν χρυσὸν ὁ ἀρχιερεὺς Ἐλιακίας ἐντυγχάνει ταῖς ἱεραῖς βίβλοις ταῖς Μωυσέος ἐν τῷ ναῷ κειμέναις καὶ προκομίσας δίδωσι τῷ γραμματεῖ Σαφᾷ. ὁ δὲ ἀναγνοὺς παραγίνεται πρὸς τὸν βασιλέα καὶ πάντα ὅσα κελεύει γενέσθαι τέλος ἔχοντα ἐδήλου, παρανέγνω δ’ αὐτῷ καὶ τὰς βίβλους [αὐτῶν]. ἀκούσας δὲ καὶ περιρρηξάμενος τὴν ἐσθῆτα τὸν ἀρχιερέα καλέσας Ἐλιακίαν καὶ αὐτὸν τὸν γραμματέα καὶ τῶν ἀναγκαιοτάτων φίλων τινὰς ἔπεμψε πρὸς τὴν προφῆτιν Ὀολδά, γυναῖκα δὲ Σαλλούμου τῶν ἐν δόξῃ τινὸς καὶ δι’ εὐγένειαν ἐπιφανοῦς, καὶ προσελθόντας ἐκέλευε λέγειν ἱλάσκεσθαι τὸν θεὸν καὶ πειρᾶσθαι ποιεῖν εὐμενῆ· δέος γὰρ εἶναι, μὴ παραβάντων τοὺς Μωυσέος νόμους τῶν προγόνων αὐτῶν κινδυνεύσωσιν ἀνάστατοι γενέσθαι καὶ τῆς οἰκείας ἐκπεσόντες ἐπ’ ἀλλοτρίας ἔρημοι πάντων καταστρέψωσιν οἰκτρῶς τὸν βίον. ἀκούσασα δ’ ἡ προφῆτις παρὰ τῶν πεμφθέντων ταῦτα δι’ αὐτῶν ὧν ἐπέστειλεν ὁ βασιλεὺς ἐκέλευσεν αὐτοὺς ἀπελθόντας πρὸς τὸν βασιλέα λέγειν, ὅτι τὸ μὲν θεῖον ἤδη κατ’ αὐτῶν ψῆφον ἤνεγκεν, ἣν οὐχ ἱκεσίαις ἄν τις ἄκυρον ποιήσειεν, ἀπολέσαι τὸν λαὸν καὶ τῆς χώρας ἐκβαλεῖν καὶ πάντων ἀφελέσθαι τῶν νῦν παρόντων ἀγαθῶν παραβάντας τοὺς νόμους καὶ τοσούτῳ μεταξὺ χρόνῳ μὴ μετανοήσαντας, τῶν τε προφητῶν τοῦτο παραινούντων σωφρονεῖν καὶ τὴν ἐπὶ τοῖς ἀσεβήμασι τιμωρίαν προλεγόντων· ἥν, ἵνα πεισθῶσιν, ὅτι θεός ἐστι καὶ οὐδὲν ἐψεύδετο τούτων ὧν αὐτοῖς διὰ τῶν προφητῶν κατήγγειλε, πάντως αὐτοῖς ποιήσειν. δι’ αὐτὸν μέντοι δίκαιον γενόμενον ἐφέξειν ἔτι τὰς συμφοράς, μετὰ δὲ τὴν ἐκείνου τελευτὴν τὰ κατεψηφισμένα πάθη τοῖς ὄχλοις ἐπιπέμψειν.", "st": "10.4.2"}, {"sp": "N", "t": "Οἱ μὲν οὖν τῆς γυναικὸς προφητευσάσης ἐλθόντες ἀπήγγειλαν τῷ βασιλεῖ. ὁ δὲ περιπέμψας πανταχοῦ τὸν λαὸν ἐκέλευε συνελθεῖν εἰς Ἱεροσόλυμα τούς θ’ ἱερεῖς καὶ τοὺς Λευίτας, πᾶσαν ἡλικίαν παρεῖναι προστάξας. ἀθροισθέντων δὲ αὐτῶν πρῶτον μὲν αὐτοῖς ἀνέγνω τὰς ἱερὰς βίβλους, ἔπειτα στὰς ἐπὶ τοῦ βήματος ἐν μέσῳ τῷ πλήθει ὅρκους ποιήσασθαι καὶ πίστεις ἠνάγκασεν, ἦ μὴν θρησκεύσειν τὸν θεὸν καὶ φυλάξειν τοὺς Μωυσέος νόμους. οἱ δὲ προθύμως τ’ ἐπῄνεσαν καὶ τὰ παραινεθέντα ὑπὸ τοῦ βασιλέως ποιήσειν ὑπέστησαν θύοντές τε παραχρῆμα καὶ καλλιεροῦντες ἤδη τὸν θεὸν ἱκέτευον εὐμενῆ καὶ ἵλεων αὐτοῖς ὑπάρχειν. τὸν δὲ ἀρχιερέα προσέταξεν εἴ τι περισσὸν ὑπὸ τῶν προγόνων σκεῦος τοῖς εἰδώλοις καὶ ξενικοῖς θεοῖς κατασταθὲν ἦν ἐν τῷ ναῷ, τοῦτο ἐκβαλεῖν. συναθροισθέντων δὲ πολλῶν καταπρήσας αὐτὰ τὴν σποδὸν αὐτῶν διέσπειρε καὶ τοὺς ἱερεῖς τῶν εἰδώλων οὐκ ὄντας ἐκ τοῦ Ἀαρῶνος γένους ἀπέκτεινε.", "st": "10.4.3"}, {"sp": "N", "t": "Ταῦτα δὲ ἐν τοῖς Ἱεροσολύμοις διαπραξάμενος ἧκεν εἰς τὴν χώραν καὶ τὰ κατασκευασθέντα ἐν αὐτῇ ὑπὸ Ἱεροβοάμου τοῦ βασιλέως εἰς τιμὴν τῶν ξενικῶν θεῶν ἠφάνισε καὶ τὰ ὀστᾶ τῶν ψευδοπροφητῶν ἐπὶ τοῦ βωμοῦ, ὃν κατεσκεύασε πρῶτος Ἱερόβαμος, κατέκαυσε. ταῦτα δὲ προφήτην κατελθόντα πρὸς Ἱερόβαμον θυσιάζοντος αὐτοῦ καὶ παντὸς ἀκούοντος τοῦ λαοῦ προκαταγγεῖλαι τὰ γενησόμενα, ὅτι τις ἐκ τοῦ Δαυίδου γένους Ἰωσίας τοὔνομα ποιήσει τὰ προειρημένα. συνέβη δὲ ταῦτα λαβεῖν τέλος μετὰ ἔτη τριακόσια καὶ ἑξηκονταέν.", "st": "10.4.4"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα ὁ βασιλεὺς Ἰωσίας πορευθεὶς καὶ πρὸς τοὺς ἄλλους τῶν Ἰσραηλιτῶν, ὅσοι τὴν αἰχμαλωσίαν καὶ τὴν δουλείαν τὴν ὑπὸ τῶν Ἀσσυρίων διέφυγον, ἀφεῖναι μὲν τὰς ἀσεβεῖς πράξεις καὶ τὰς τιμὰς τὰς πρὸς τοὺς ἀλλοτρίους θεοὺς ἐγκαταλιπεῖν ἔπεισε, τὸν δὲ πάτριον καὶ μέγιστον θεὸν εὐσεβεῖν καὶ τούτῳ προσανέχειν· τὰς οἰκίας τε καὶ τὰς κώμας ἠρεύνησε καὶ τὰς πόλεις, μή τις ἔνδον ἔχοι τι τῶν εἰδώλων ὑπονοῶν. οὐ μὴν ἀλλὰ καὶ τὰ τοῖς βασιλευομένοις ἐφεστῶτα ἅρματα, ἃ κατεσκεύασαν οἱ πρόγονοι, καὶ εἴ τι ἄλλο τοιοῦτον ἦν ᾧ προσεκύνουν ὡς θεῷ ἐβάστασε· καὶ καθαρίσας οὕτω τὴν χώραν ἅπασαν εἰς Ἱεροσόλυμα τὸν λαὸν συνεκάλεσε κἀκεῖ τὴν ἀζύμων ἑορτὴν καὶ τὴν πάσχα λεγομένην ἤγαγεν· ἐδωρήσατό τε τῷ λαῷ τὸ πάσχα νεογνοὺς ἐρίφους καὶ ἄρνας δισμυρίους, βοῦς δ’ εἰς ὁλοκαυτώματα τρισχιλίους. παρεῖχον δὲ καὶ τῶν ἱερέων οἱ πρῶτοι διὰ τὸ πάσχα τοῖς ἱερεῦσιν ἄρνας δισχιλίους ἑξακοσίους καὶ τοῖς Λευίταις πεντακισχιλίους ἄρνας ἔδοσαν οἱ προεστῶτες αὐτῶν, βοῦς δὲ πεντακοσίους. καὶ γενομένης οὕτως ἀφθόνου τῆς τῶν ἱερείων εὐπορίας τὰς θυσίας ἐπετέλουν τοῖς Μωυσέος νόμοις, ἑκάστῳ τῶν ἱερέων ἐξηγουμένων καὶ διακονουμένων τοῖς ὄχλοις, καὶ τοῦ μηδεμίαν ἄλλην οὕτως ἀχθῆναι τοῖς Ἑβραίοις ἑορτὴν ἀπὸ τῶν Σαμουήλου τοῦ προφήτου χρόνων αἴτιον ἦν τὸ πάντα κατὰ νόμους καὶ κατὰ τὴν ἀρχαίαν παρατήρησιν τῆς πατρίου συνηθείας ἐπιτελεσθῆναι. ζήσας δ’ ἐν εἰρήνῃ μετὰ ταῦτα ὁ Ἰωσίας ἔτι δὲ καὶ πλούτῳ καὶ τῇ παρὰ πᾶσιν εὐδοξίᾳ κατέστρεψε τούτῳ τῷ τρόπῳ τὸν βίον·", "st": "10.4.5"}, {"sp": "N", "t": "Νεχαῦς ὁ τῶν Αἰγυπτίων βασιλεὺς ἐγείρας στρατιὰν ἐπὶ τὸν Εὐφράτην ἤλασε ποταμὸν Μήδους πολεμήσων καὶ τοὺς Βαβυλωνίους, οἳ τὴν Ἀσσυρίων κατέλυσαν ἀρχήν· τῆς γὰρ Ἀσίας βασιλεῦσαι πόθον εἶχε. γενομένου δ’ αὐτοῦ κατὰ Μένδην πόλιν, ἦν δ’ αὕτη τῆς Ἰωσίου βασιλείας, μετὰ δυνάμεως εἶργεν αὐτὸν διὰ τῆς ἰδίας ποιεῖσθαι χώρας τὴν ἐπὶ τοὺς Μήδους ἔλασιν. πέμψας δὲ κήρυκα πρὸς αὐτὸν Νεχαῦς οὐκ ἐπ’ αὐτὸν στρατεύειν ἔλεγεν, ἀλλ’ ἐπὶ τὸν Εὐφράτην ὡρμηκέναι· μὴ παροξύνειν δ’ αὐτὸν ἐκέλευεν, ὥστε πολεμεῖν αὐτῷ κωλύοντι βαδίζειν ἐφ’ οὗ διέγνωκεν. Ἰωσίας δὲ οὐ προσίετο τὰ παρὰ τοῦ Νεχαῦ, ἀλλ’ οὕτως εἶχεν ὡς μὴ συγχωρεῖν αὐτῷ τὴν οἰκείαν διέρχεσθαι, τῆς πεπρωμένης οἶμαι εἰς τοῦτ’ αὐτὸν παρορμησάσης, ἵνα λάβῃ πρόφασιν κατ’ αὐτοῦ. διατάσσοντος γὰρ αὐτοῦ τὴν δύναμιν καὶ ἐφ’ ἅρματος ἀπὸ κέρως ἐπὶ κέρας ὀχουμένου τοξεύσας τις αὐτὸν τῶν Αἰγυπτίων ἔπαυσε τῆς πρὸς τὴν μάχην σπουδῆς· τῷ τραύματι γὰρ περιαλγὴς ὢν ἐκέλευσεν ἀνακληθῆναι τὸ στράτευμα καὶ ὑπέστρεψεν εἰς τὰ Ἱεροσόλυμα. τελευτᾷ δ’ ἐκ τῆς πληγῆς ἐκεῖ τὸν βίον καὶ κηδεύεται ἐν ταῖς πατρῴαις θήκαις μεγαλοπρεπῶς βιώσας μὲν ἔτη τριακονταεννέα, βασιλεύσας δὲ τούτων ἓν καὶ τριάκοντα. πένθος δ’ ἐπ’ αὐτῷ μέγα τοῦ λαοῦ παντὸς ἤχθη πολλαῖς ἡμέραις ὀδυρομένου καὶ κατηφοῦντος· Ἱερεμίας δὲ ὁ προφήτης ἐπικήδειον αὐτοῦ συνέταξε μέλος [θρηνητικόν], ὃ καὶ μέχρι νῦν διαμένει. οὗτος ὁ προφήτης καὶ τὰ μέλλοντα τῇ πόλει δεινὰ προεκήρυξεν ἐν γράμμασι καταλιπὼν καὶ τὴν νῦν ἐφ’ ἡμῶν γενομένην ἅλωσιν τήν τε Βαβυλῶνος αἵρεσιν. οὐ μόνον δὲ οὗτος προεθέσπισε ταῦτα τοῖς ὄχλοις, ἀλλὰ καὶ ὁ προφήτης Ἰεζεκίηλος, ὃς πρῶτος περὶ τούτων δύο βίβλους γράψας κατέλιπεν. ἦσαν δὲ οἱ δύο τῷ γένει ἱερεῖς, ἀλλ’ ὁ μὲν Ἱερεμίας ἐν Ἱεροσολύμοις διῆγεν ἀπὸ τρισκαιδεκάτου ἔτους τῆς Ἰωσίου βασιλείας ἕως οὗ κατεσκάφη ἡ πόλις καὶ ὁ ναός. τὰ μέντοι γε συμβάντα περὶ τοῦτον τὸν προφήτην κατὰ χώραν δηλώσομεν.", "st": "10.5.1"}, {"sp": "N", "t": "Τελευτήσαντος δὲ Ἰωσίου, καθὼς προειρήκαμεν, τὴν βασιλείαν ὁ παῖς αὐτοῦ διαδέχεται Ἰώαζος τοὔνομα τρίτον καὶ εἰκοστὸν ἤδη ἔτος γεγονώς. καὶ οὗτος μὲν ἐν Ἱεροσολύμοις ἐβασίλευσε μητρὸς Ἀμιτάλης καὶ πόλεως Τομάνης ἀσεβὴς δὲ καὶ μιαρὸς τὸν τρόπον· ὁ δὲ τῶν Αἰγυπτίων βασιλεὺς ὑποστρέψας ἀπὸ τῆς μάχης μεταπέμπεται τὸν Ἰώαζον πρὸς αὑτὸν εἰς Ἀμαθὰ καλουμένην πόλιν, ἥτις ἐστὶ τῆς Συρίας, καὶ τὸν μὲν ἐλθόντα ἔδησε, τῷ δὲ πρεσβυτέρῳ αὐτοῦ ἀδελφῷ ὁμοπατρίῳ ὄντι Ἐλιακείμῳ τοὔνομα τὴν βασιλείαν παραδίδωσι μετονομάσας αὐτὸν Ἰωάκειμον· τῇ δὲ χώρᾳ ἐπέταξεν ἑκατὸν ἀργυρίου τάλαντα, ἓν δὲ χρυσίου. καὶ τοῦτο μὲν ἐτέλει ὁ Ἰωάκειμος τὸ πλῆθος τῶν χρημάτων, τὸν δὲ Ἰώαζον ἀπήγαγεν εἰς Αἴγυπτον, ὃς καὶ ἐτελεύτησεν ἐν αὐτῇ βασιλεύσας μῆνας τρεῖς ἡμέρας δέκα. ἡ δὲ τοῦ Ἰωακείμου μήτηρ ἐκαλεῖτο Ζαβουδᾶ, ἐκ πόλεως δ’ ἦν Ἀβουμᾶς. ἐτύγχανε δ’ ὢν τὴν φύσιν ἄδικος καὶ κακοῦργος καὶ μήτε πρὸς θεὸν ὅσιος μήτε πρὸς ἀνθρώπους ἐπιεικής.", "st": "10.5.2"}, {"sp": "N", "t": "Ἔτος δ’ αὐτοῦ τῆς βασιλείας τέταρτον ἤδη ἔχοντος τὴν Βαβυλωνίων ἀρχὴν παραλαμβάνει Ναβουχοδονόσορος ὄνομα, ὃς ὑπὸ τὸν αὐτὸν καιρὸν μετὰ μεγάλης παρασκευῆς ἐπὶ Καρχάμισσαν ἀναβαίνει πόλιν, ἔστι δ’ αὕτη πρὸς τῷ Εὐφράτῃ ποταμῷ, διεγνωκὼς πολεμεῖν τῷ τῶν Αἰγυπτίων Νεχαῦ· ὑπὸ τούτῳ γὰρ ἦν ἅπασα ἡ Συρία. μαθὼν δὲ τὴν τοῦ Βαβυλωνίου προαίρεσιν καὶ τὴν ἐπ’ αὐτὸν στρατείαν ὁ Νεχαῦς οὐδὲ αὐτὸς ὠλιγώρησεν, ἀλλὰ σὺν πολλῇ χειρὶ τὸν Ναβουχοδονόσορον ἀμυνούμενος ὥρμησεν ἐπὶ τὸν Εὐφράτην. συμβολῆς δὲ γενομένης ἡττήθη καὶ πολλὰς ἀπέβαλε μυριάδας ἐν τῇ μάχῃ. διαβὰς δὲ τὸν Εὐφράτην ὁ Βαβυλώνιος τὴν ἄχρι Πηλουσίου παραλαμβάνει Συρίαν πάρεξ τῆς Ἰουδαίας. τέσσαρα δ’ ἔτη βασιλεύοντος ἤδη τοῦ Ναβουχοδονοσόρου ὄγδοον ἦν τῷ Ἰωακείμῳ τῷ τῶν Ἑβραίων ἔχοντι τὴν ἀρχήν, καὶ στρατεύει μετὰ πολλῆς δυνάμεως ἐπὶ τοὺς Ἰουδαίους ὁ Βαβυλώνιος φόρους αἰτῶν τὸν Ἰωάκειμον ἢ πολεμήσειν ἀπειλῶν. ὁ δὲ δείσας τὴν ἀπειλὴν καὶ τὴν εἰρήνην ἀντικαταλλαξάμενος τῶν χρημάτων ἤνεγκεν αὐτῷ φόρους οὓς ἔταξεν ἐπὶ ἔτη τρία.", "st": "10.6.1"}, {"sp": "N", "t": "Τῷ δὲ τρίτῳ στρατεύειν τοὺς Αἰγυπτίους ἀκούσας ἐπὶ τὸν Βαβυλώνιον καὶ τοὺς φόρους αὐτῷ μὴ δοὺς διεψεύσθη τῆς ἐλπίδος· οἱ γὰρ Αἰγύπτιοι ποιήσασθαι τὴν στρατείαν οὐκ ἐθάρρησαν. ταῦτα δὲ ὁ προφήτης Ἱερεμίας κατὰ πᾶσαν ἡμέραν προύλεγεν, ὡς μάτην ταῖς παρὰ τῶν Αἰγυπτίων ἐλπίσι προσανέχουσι, καὶ ὡς δεῖ τὴν πόλιν ὑπὸ τοῦ Βαβυλωνίων βασιλέως ἀνάστατον γενέσθαι, καὶ Ἰωακείμῳ τῷ βασιλεῖ χειρωθῆναι ὑπ’ αὐτοῦ. ἀλλὰ ταῦτ’ οὐδὲν χρήσιμον οὐκ ὄντων τῶν σωθησομένων ἐλέγετο· καὶ γὰρ τὸ πλῆθος καὶ οἱ ἄρχοντες ἀκούοντες παρημέλουν, καὶ πρὸς ὀργὴν λαμβάνοντες τὰ λεγόμενα ὡς οἰωνιζομένου κατὰ τοῦ βασιλέως τοῦ προφήτου τὸν Ἱερεμίαν ᾐτιῶντο, καὶ ὑπάγοντες δίκῃ καταψηφισθῆναι πρὸς τιμωρίαν ἠξίουν. καὶ οἱ μὲν ἄλλοι πάντες ἤνεγκαν τὰς ψήφους κατ’ αὐτοῦ οἳ καὶ ἀπέγνωσαν τῶν πρεσβυτέρων, οἱ δὲ σοφῆς ὄντες διανοίας ἀπέλυσαν τὸν προφήτην ἀπὸ τῆς αὐλῆς καὶ τοῖς ἄλλοις συνεβούλευσαν μηδὲν διαθεῖναι κακὸν τὸν Ἱερεμίαν. ἔλεγον γὰρ οὐ μόνον τοῦτον προλέγειν τῇ πόλει τὰ μέλλοντα, ἀλλὰ καὶ Μιχαίαν πρὸ αὐτοῦ ταῦτα κατηγγελκέναι καὶ πολλοὺς ἄλλους, ὧν οὐδεὶς ὑπὸ τῶν τότε βασιλέων οὐδὲν ἔπαθεν, ἀλλ’ ὡς προφήτης τοῦ θεοῦ τιμῆς ἔτυχε. τούτοις καταπραΰναντες τὸ πλῆθος τοῖς λόγοις ἐρρύσαντο τῆς κατεψηφισμένης αὐτοῦ κολάσεως τὸν Ἱερεμίαν, ὃς ἁπάσας αὑτοῦ τὰς προφητείας συγγραψάμενος νηστεύοντος τοῦ δήμου καὶ ἐκκλησιάζοντος ἐν τῷ ἱερῷ μηνὶ ἐνάτῳ τοῦ πέμπτου ἔτους τῆς Ἰωακείμου βασιλείας ἀνέγνω τὴν βίβλον, ἣν περὶ τῶν μελλόντων συμβήσεσθαι τῇ πόλει καὶ τῷ ναῷ καὶ τοῖς ὄχλοις ἦν συντεταχώς. ἀκούσαντες δ’ οἱ ἡγεμόνες λαμβάνουσι παρ’ αὐτοῦ τὸ βιβλίον καὶ κελεύουσιν αὐτόν τε καὶ τὸν γραμματέα Βαροῦχον ἐκποδὼν αὑτοὺς ποιῆσαι, μή τισι δῆλοι γένωνται, τὸ δὲ βιβλίον αὐτοὶ φέροντες τῷ βασιλεῖ διδόασιν. ὁ δὲ παρόντων αὐτῷ τῶν φίλων ἐκέλευσε τὸν αὑτοῦ γραμματέα λαβόντα ἀναγνῶναι. ἀκούσας δὲ τῶν ἐν τῷ βιβλίῳ καὶ ὀργισθεὶς ὁ βασιλεὺς διέρρηξέ τε καὶ βαλὼν εἰς πῦρ ἠφάνισε, ζητηθέντας δὲ τόν τε Ἱερεμίαν καὶ τὸν γραμματέα Βαροῦχον ἐκέλευσεν ἀχθῆναι πρὸς αὐτὸν κολασθησομένους. οὗτοι μὲν οὖν διαφεύγουσιν αὐτοῦ τὴν ὀργήν.", "st": "10.6.2"}, {"sp": "N", "t": "Μετ’ οὐ πολὺν δὲ χρόνον στρατευόμενον ἐπ’ αὐτὸν τὸν τῶν Βαβυλωνίων βασιλέα δέχεται κατὰ δέος τῶν προειρημένων ὑπὸ τοῦ προφήτου τούτου, οὐδὲν νομίζων πείσεσθαι δεινὸν μηδὲ ἀποκλείσας μηδὲ πολεμήσας, ἀπελθὼν δ’ εἰς αὐτὸν ὁ Βαβυλώνιος οὐκ ἐφύλαξε τὰς πίστεις, ἀλλὰ τοὺς ἀκμαιοτάτους καὶ κάλλει διαφέροντας τῶν Ἱεροσολυμιτῶν ἀπέκτεινε μετὰ τοῦ βασιλέως Ἰωακείμου, ὃν ἄταφον ἐκέλευσε ῥιφῆναι πρὸ τῶν τειχῶν· τὸν δὲ υἱὸν αὐτοῦ Ἰωάκειμον κατέστησε βασιλέα τῆς χώρας καὶ τῆς πόλεως. τοὺς δ’ ἐν ἀξιώματι τρισχιλίους ὄντας τὸν ἀριθμὸν αὐτοῦ αἰχμαλώτους λαβὼν ἀπήγαγεν εἰς τὴν Βαβυλῶνα· ἐν δὲ τούτοις ἦν καὶ ὁ προφήτης Ἰεζεκίηλος παῖς ὤν. καὶ τέλος μὲν τοιοῦτον Ἰωάκειμον τὸν βασιλέα κατέσχε βιώσαντα μὲν ἓξ καὶ τριάκοντα ἔτη βασιλεύσαντα δὲ τούτων ἕνδεκα, ὁ δὲ διαδεξάμενος αὐτοῦ τὴν βασιλείαν Ἰωάκειμος, ἐκ μητρὸς μὲν Νοόστης ὄνομα πολίτιδος δέ, ἐβασίλευσε μῆνας τρεῖς ἡμέρας δέκα.", "st": "10.6.3"}, {"sp": "N", "t": "Τὸν δὲ τῶν Βαβυλωνίων βασιλέα δόντα τὴν βασιλείαν Ἰωακείμῳ παραχρῆμα ἔλαβε δέος· ἔδεισε γάρ, μὴ μνησικακήσας αὐτῷ τῆς τοῦ πατρὸς ἀναιρέσεως ἀποστήσῃ τὴν χώραν αὐτοῦ· πέμψας τοιγαροῦν δύναμιν ἐπολιόρκει τὸν Ἰωάκειμον ἐν τοῖς Ἱεροσολύμοις. ὁ δὲ φύσει χρηστὸς ὢν καὶ δίκαιος οὐκ ἠξίου τὴν πόλιν κινδυνεύουσαν δι’ αὐτὸν περιορᾶν, ἀλλ’ ἀπάρας τὴν μητέρα καὶ τοὺς συγγενεῖς παραδίδωσι τοῖς πεμφθεῖσιν ὑπὸ τοῦ Βαβυλωνίου στρατηγοῖς ὅρκους παρ’ αὐτῶν λαβὼν ὑπὲρ τοῦ μηδὲν μήτ’ αὐτοὺς παθεῖν μήτε τὴν πόλιν. οἷς οὐδ’ ἐνιαυτὸν ἡ πίστις ἔμεινεν· οὐ γὰρ ἐφύλαξεν αὐτὴν ὁ τῶν Βαβυλωνίων βασιλεύς, ἀλλὰ τοῖς στρατηγοῖς ἐπέστειλεν ἅπαντας τοὺς ἐν τῇ πόλει λαβόντας αἰχμαλώτους νέους τὴν ἡλικίαν καὶ τεχνίτας δεδεμένους ἄγειν πρὸς αὑτόν, ἦσαν δὲ οὗτοι πάντες εἰς μυρίους ὀκτακοσίους τριακονταδύο, καὶ τὸν Ἰωάκειμον μετὰ τῆς μητρὸς καὶ τῶν φίλων. τούτους δὴ κομισθέντας πρὸς αὑτὸν εἶχεν ἐν φυλακῇ· τὸν δὲ θεῖον τοῦ Ἰωακείμου Σαχχίαν ἀπέδειξε βασιλέα ὅρκους παρ’ αὐτοῦ λαβών, ἦ μὴν φυλάξειν αὐτῷ τὴν χώραν καὶ μηδὲν νεωτερίσειν μηδὲ τοῖς Αἰγυπτίοις εὐνοήσειν.", "st": "10.7.1"}, {"sp": "N", "t": "Σαχχίας δ’ ἦν ἐτῶν μὲν εἴκοσι καὶ ἑνός, ὅτε τὴν ἀρχὴν παρέλαβεν, ὁμομήτριος μὲν Ἰωακείμου τοῦ ἀδελφοῦ αὐτοῦ, τῶν δὲ δικαίων καὶ τοῦ δέοντος ὑπερόπτης· καὶ γὰρ τὴν ἡλικίαν ἦσαν ἀσεβεῖς περὶ αὐτὸν καὶ ὁ πᾶς ὄχλος ἐπ’ ἐξουσίας ὕβριζεν ἃ ἤθελεν· διὸ καὶ ὁ προφήτης Ἱερεμίας πρὸς αὐτὸν ἐλθὼν πολλάκις ἐμαρτύρατο κελεύων τὰς μὲν ἄλλας ἀσεβείας καὶ παρανομίας καταλιπεῖν, προνοεῖν δὲ τοῦ δικαίου, καὶ μήτε τοῖς ἡγεμόσι τῷ εἶναι ἐν αὐτοῖς πονηροὺς προσανέχειν μήτε τοῖς ψευδοπροφήταις ἀπατῶσιν αὐτὸν πεπιστευκέναι, ὡς οὐκέτι πολεμήσει τὴν πόλιν ὁ Βαβυλώνιος καὶ ὡς Αἰγύπτιοι στρατεύσουσιν ἐπ’ αὐτὸν καὶ νικήσουσι· ταῦτα γὰρ οὐκ ἀληθῆ λέγειν οὐδ’ οὕτως ὀφείλοντα γενέσθαι. ὁ δὲ Σαχχίας ἐφ’ ὅσον μὲν ἤκουσε τοῦ προφήτου ταῦτα λέγοντος ἐπείθετο αὐτῷ καὶ συνῄδει πᾶσιν ὡς ἀληθεύουσι καὶ συμφέρον αὐτῷ πεπιστευκέναι· διέφθειρον δὲ πάλιν αὐτὸν οἱ φίλοι καὶ διῆγον ἀπὸ τῶν τοῦ προφήτου πρὸς ἅπερ ἤθελον. προεφήτευσε δὲ καὶ Ἰεζεκίηλος ἐν Βαβυλῶνι τὰς μελλούσας τῷ λαῷ συμφορὰς καὶ γράψας ταῦτα ἔπεμψεν εἰς Ἱεροσόλυμα. ταῖς δὲ προφητείαις αὐτῶν Σαχχίας ἠπίστησεν ἐκ τοιαύτης αἰτίας· τὰ μὲν ἄλλα πάντα συμφωνοῦντα εἰπεῖν συνέβη, ὡς ἥ τε πόλις ἁλώσεται καὶ Σαχχίας αὐτὸς αἰχμάλωτος ἔσται, διεφώνησε δὲ Ἰεζεκίηλος εἰπὼν οὐκ ὄψεσθαι Βαβυλῶνα τὸν Σαχχίαν τοῦ Ἱερεμίου φάσκοντος αὐτῷ, ὅτι δεδεμένον αὐτὸν ὁ Βαβυλώνιος ἄξει βασιλεύς. καὶ διὰ τὸ μὴ ταὐτὸν αὐτοὺς ἑκατέρους λέγειν καὶ περὶ ὧν συμφωνεῖν ἐδόκουν ὡς οὐδ’ ἐκεῖνα ἀληθῆ λέγουσι καταγνούς· καίτοι πάντ’ αὐτῷ κατὰ τὰς προφητείας ἀπήντησεν, ἅπερ εὐκαιρότερον δηλώσομεν.", "st": "10.7.2"}, {"sp": "N", "t": "Τὴν συμμαχίαν δὲ τὴν πρὸς τοὺς Βαβυλωνίους ἐπ’ ἔτη ὀκτὼ κατασχὼν διέλυσε τὰς πρὸς αὐτοὺς πίστεις καὶ τοῖς Αἰγυπτίοις προστίθεται καταλύσειν τοὺς Βαβυλωνίους ἐλπίσας, αἳ μετ’ ἐκείνων ἐγένοντο. μαθὼν δὲ τοῦτο ὁ τῶν Βαβυλωνίων βασιλεὺς ἐστράτευσεν ἐπ’ αὐτὸν καὶ τὴν χώραν κακώσας αὐτοῦ καὶ τὰ φρούρια λαβὼν ἐπ’ αὐτὴν ἧκε τὴν τῶν Ἱεροσολυμιτῶν πόλιν πολιορκήσων αὐτήν. ὁ δ’ Αἰγύπτιος ἀκούσας ἐν οἷς ἐστιν ὁ σύμμαχος αὐτοῦ Σαχχίας ἀναλαβὼν πολλὴν δύναμιν ἧκεν εἰς τὴν Ἰουδαίαν ὡς λύσων τὴν πολιορκίαν. ὁ δὲ Βαβυλώνιος ἀφίσταται τῶν Ἱεροσολύμων, ἀπαντήσας δὲ τοῖς Αἰγυπτίοις καὶ συμβαλὼν αὐτοῖς τῇ μάχῃ νικᾷ καὶ τρεψάμενος αὐτοὺς εἰς φυγὴν ἐξ ὅλης διώκει τῆς Συρίας. ὡς δ’ ἀνεχώρησεν ὁ τῶν Βαβυλωνίων βασιλεὺς ἀπὸ τῶν Ἱεροσολύμων, ἐξηπάτησαν οἱ ψευδοπροφῆται τὸν Σαχχίαν λέγοντες οὔτε τὸν Βαβυλώνιον ἔτι αὐτὸν πολεμήσειν καὶ τοὺς ὁμοφύλους, οὓς ἀναστήσειεν ἐκ τῆς οἰκείας εἰς τὴν Βαβυλῶνα, μετὰ πάντων ἀνήξειν τῶν τοῦ ναοῦ σκευῶν, ὧν ἐσύλησεν ὁ βασιλεὺς ἐκ τοῦ νεώ. τἀναντία δὲ τούτων καὶ ἀληθῆ προελθὼν Ἱερεμίας προεφήτευσεν, ὡς ποιοῦσι μὲν κακῶς καὶ ἐξαπατῶσι τὸν βασιλέα, παρὰ δὲ τῶν Αἰγυπτίων οὐδὲν αὐτοῖς ἐστιν ὄφελος, ἀλλὰ νικήσας αὐτοὺς ὁ Βαβυλώνιος ἐπιστρατεύσειν εἰς τὰ Ἱεροσόλυμα μέλλει, καὶ πολιορκήσει τε καὶ τῷ λιμῷ διαφθερεῖ τὸν δῆμον, καὶ τοὺς περιλειφθέντας αἰχμαλώτους ἄξει, καὶ τὰς οὐσίας διαρπάσει, καὶ τὸν ἐν τῷ ναῷ πλοῦτον ἐκφορήσας ἔτι καὶ αὐτὸν ἐμπρήσει καὶ κατασκάψει τὴν πόλιν, καὶ δουλεύσομεν αὐτῷ καὶ τοῖς ἐγγόνοις αὐτοῦ ἐπ’ ἔτη ἑβδομήκοντα. παύσουσι δ’ ἡμᾶς τότε τῆς ὑπ’ αὐτοῖς δουλείας Πέρσαι τε καὶ Μῆδοι καταλύσαντες Βαβυλωνίους, ἀφ’ ὧν εἰς τήνδε ἀπολυθέντες οἰκοδομήσομεν τὸν ναὸν πάλιν καὶ τὰ Ἱεροσόλυμα καταστήσομεν. ταῦτα λέγων ὁ Ἱερεμίας ὑπὸ μὲν τῶν πλειόνων ἐπιστεύετο, οἱ δὲ ἡγεμόνες καὶ οἱ ἀσεβεῖς ὡς ἐξεστηκότα τῶν φρενῶν αὐτὸν οὕτως ἐξεφαύλιζον. δόξαν δὲ αὐτῷ που καὶ εἰς τὴν πατρίδα παραγενέσθαι λεγομένην Ἀναθὼθ σταδίους δ’ ἀπέχουσαν τῶν Ἱεροσολύμων εἴκοσι, συντυχὼν κατὰ τὴν ὁδὸν τῶν ἀρχόντων τις συλλαβὼν κατέσχε συκοφαντῶν ὡς πρὸς τοὺς Βαβυλωνίους αὐτομολοῦντα. ὁ δὲ ψευδῆ μὲν ἐκεῖνον ἔλεγεν αἰτίαν ἐπιφέρειν αὐτῷ, βαδίζειν δ’ αὑτὸν ἔφασκεν εἰς τὴν πατρίδα. ὁ δ’ οὐ πεισθεὶς ἀλλὰ λαβὼν αὐτὸν ἤγαγεν εἰς δίκην πρὸς τοὺς ἄρχοντας, ὑφ’ ὧν πᾶσαν αἰκίαν καὶ βασάνους ὑπομείνας ἐφυλάττετο πρὸς τιμωρίαν. καὶ χρόνον μέν τινα διῆγεν οὕτως ἀδίκως πάσχων τὰ προειρημένα.", "st": "10.7.3"}, {"sp": "N", "t": "Ἔτει δ’ ἐνάτῳ τῆς Σαχχίου βασιλείας καὶ ἡμέρᾳ δεκάτῃ τοῦ δεκάτου μηνὸς στρατεύει τὸ δεύτερον ὁ τῶν Βαβυλωνίων βασιλεὺς ἐπὶ τὰ Ἱεροσόλυμα καὶ προσκαθίσας αὐτῇ μῆνας ὀκτωκαίδεκα μετὰ πάσης πολιορκεῖ φιλοτιμίας. συνεπέθετο δὲ εἰς ταὐτὸ πολιορκουμένοις τοῖς Ἱεροσολύμοις δύο τὰ μέγιστα τῶν παθῶν, λιμὸς καὶ φθορὰ λοιμικὴ ἐνσκήψαντα σφοδρῶς. ἐν δὲ τῇ εἱρκτῇ τυγχάνων ὁ προφήτης Ἱερεμίας οὐχ ἡσύχαζεν, ἀλλ’ ἐκεκράγει καὶ ἐκήρυσσε παραινῶν τῷ πλήθει δέξασθαι τὸν Βαβυλώνιον ἀνοίξαντας τὰς πύλας· σωθήσεσθαι γὰρ αὐτοὺς πανοικὶ τοῦτο πράξαντας, εἰ δὲ μή, διαφθαρήσεσθαι. προύλεγεν δ’ ὡς εἰ μὲν ἐπιμένοι τις ἐν τῇ πόλει πάντως ἀπολεῖται θατέρῳ ἢ λιμῷ δαπανηθεὶς ἢ σιδήρῳ τῷ τῶν πολεμίων, εἰ δὲ φύγοι πρὸς τοὺς πολεμίους, διαδράσεται τὸν θάνατον. οὐδὲ ἐν αὐτοῖς δὲ ὄντες τοῖς δεινοῖς ἐπίστευον οἱ ταῦτ’ ἀκούοντες τῶν ἡγεμόνων, ἀλλὰ μετ’ ὀργῆς ἀπήγγελλον ἐλθόντες πρὸς τὸν βασιλέα, καὶ κατηγοροῦντες κατῃτιῶντο κτεῖναι τὸν προφήτην ὡς μεμηνότα καὶ τὰς ψυχὰς αὐτῶν προκατακλῶντα καὶ ταῖς τῶν χειρόνων καταγγελίαις τὸ πρόθυμον ἐκλύοντα τοῦ πλήθους· ἕτοιμον γὰρ εἶναι αὐτὸ ὑπὲρ αὐτοῦ καὶ τῆς πατρίδος κινδυνεῦσαι, ὁ δὲ παρῄνει πρὸς τοὺς πολεμίους φεύγειν ἁλώσεσθαι λέγων τὴν πόλιν καὶ πάντας ἀπολεῖσθαι.", "st": "10.7.4"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς αὐτὸς μὲν ὑπὸ χρηστότητος καὶ δικαιοσύνης οὐδὲν ἰδίᾳ παρωξύνθη, ἵνα δὲ μὴ τοῖς ἡγεμόσιν ἀπεχθάνηται παρὰ τοιοῦτον καιρὸν ἀντιπράττων αὐτῶν τῇ προαιρέσει, τὸν προφήτην ἐφῆκεν αὐτοῖς ποιεῖν ὅτι ἂν θέλωσιν. ὡς δὲ τοῦτο ἐφέντος αὐτοῖς τοῦ βασιλέως εὐθὺς εἰς τὴν εἱρκτὴν εἰσελθόντες καὶ παραλαβόντες αὐτὸν εἴς τινα λάκκον βορβόρου πλήρη καθίμησαν, ὅπως ἰδίῳ θανάτῳ πνιγεὶς ἀποθάνῃ. ὁ δὲ πρὸ τοῦ αὐχένος ὑπὸ τοῦ πηλοῦ περισχεθεὶς ἐν τούτοις ἦν. τῶν δ’ οἰκετῶν τις τοῦ βασιλέως ἐν τιμῇ τυγχάνων Αἰθίοψ τὸ γένος τὸ περὶ τὸν προφήτην πάθος ἀπήγγειλε τῷ βασιλεῖ φάσκων οὐκ ὀρθῶς ταῦτα τοὺς φίλους καὶ τοὺς ἡγεμόνας αὐτοῦ πεποιηκέναι καταποντίσαντας εἰς βόρβορον τὸν προφήτην καὶ τοῦ διὰ τῶν δεσμῶν θανάτου πικρότερον οὕτως ἐσόμενον ἐπινοήσαντας κατ’ αὐτοῦ. ταῦτ’ ἀκούσας ὁ βασιλεὺς καὶ μετανοήσας ἐν τῷ παραδοῦναι τὸν προφήτην τοῖς ἡγεμόσιν ἐκέλευσε τὸν Αἰθίοπα τριάκοντα τῶν βασιλικῶν παραλαβόντα καὶ σχοίνους καὶ πᾶν ὃ πρὸς τὴν τοῦ προφήτου σωτηρίαν ἐπινοεῖν χρήσιμον μετὰ σπουδῆς ἀνελκύσαι τὸν Ἱερεμίαν. ὁ δ’ Αἰθίοψ παραλαβὼν οὓς ἐπετάγη ἀνέσπασεν ἐκ τοῦ βορβόρου τὸν προφήτην καὶ διαφῆκεν ἀφύλακτον.", "st": "10.7.5"}, {"sp": "N", "t": "Μεταπεμψαμένου δ’ αὐτὸν κρύφα τοῦ βασιλέως καὶ τί δύναται φράζειν αὐτῷ παρὰ τοῦ θεοῦ καὶ πρὸς τὰ παρόντα σημαίνειν ἐρομένου, ἔχειν μὲν ἔλεγεν, οὐ πιστευθήσεσθαι δ’ εἰπὼν οὐδὲ παραινέσας ἀκουσθήσεσθαι, ἀλλ’ ὡς δὴ μέγα κακόν τι εἰργασμένον ἀπολέσαι διέγνωσαν οἱ σοὶ φίλοι, φησί, καὶ ποῦ νῦν εἰσιν οἱ τὸν Βαβυλώνιον οὐκέθ’ ἡμῖν ἐπιστρατεύσειν φάσκοντες καὶ ἀπατῶντες ὑμᾶς; εὐλαβοῦμαι δὲ νῦν γε τὴν ἀλήθειαν εἰπεῖν, μή με κατακρίνῃς θανάτῳ. τοῦ δὲ βασιλέως ὅρκους αὐτῷ δόντος, ὡς οὔτε αὐτὸς αὐτὸν ἀναιρήσει οὔτε τοῖς ἡγεμόσιν ἐκδώσει, θαρσήσας τῇ δεδομένῃ πίστει συνεβούλευσεν αὐτῷ παραδοῦναι τὴν πόλιν τοῖς Βαβυλωνίοις· ταῦτα δὲ αὐτῷ τὸν θεὸν δι’ αὐτοῦ προφητεύειν ἔλεγεν, εἴ γε βούλεται σώζεσθαι καὶ τὸν ἐφεστῶτα κίνδυνον διαφυγεῖν καὶ μήτε τὴν πόλιν εἰς ἔδαφος πεσεῖν, μήτε τὸν ναὸν ἐμπρησθέντα γὰρ αὐτὸν τούτων παραίτιον ἔσεσθαι τῶν κακῶν τοῖς πολίταις καὶ αὑτῷ πανοικὶ τῆς συμφορᾶς. ὁ δὲ ταῦτ’ ἀκούσας βούλεσθαι μὲν αὐτὸς ἔφη ποιεῖν ἃ παραινεῖ καὶ λέγει συνοίσειν αὐτῷ γινόμενα, δεδιέναι δὲ τοὺς αὐτομολήσαντας τῶν ὁμοφύλων πρὸς τοὺς Βαβυλωνίους, μὴ διαβληθεὶς ὑπ’ αὐτῶν τῷ βασιλεῖ κολασθῇ. παρεθάρσυνε δὲ αὐτὸν ὁ προφήτης καὶ μάτην ὑπονοεῖν τὴν τιμωρίαν ἔλεγεν· οὐδενὸς γὰρ κακοῦ πειραθήσεσθαι παραδόντα τοῖς Βαβυλωνίοις οὔτ’ αὐτὸν οὔτε τὰ τέκνα οὔτε τὰς γυναῖκας, μενεῖν δὲ καὶ τὸν ναὸν ἀπαθῆ. καὶ τὸν μὲν Ἱερεμίαν ταῦτ’ εἰπόντα ὁ βασιλεὺς ἀπέλυσεν προστάξας αὐτῷ πρὸς μηδένα τῶν πολιτῶν ἐξενεγκεῖν τὰ δόξαντ’ αὐτοῖς, ἀλλὰ μηδὲ τοῖς ἡγεμόσιν, εἰ μαθόντες αὐτὸν ὑπ’ αὐτοῦ μετάπεμπτον γεγονέναι πυνθάνονται τί κληθεὶς εἴποι πρὸς αὐτόν, φράζειν τι τούτων, ἀλλὰ σκήπτεσθαι πρὸς αὐτούς, ὅτι δεηθείη μὴ ἐν δεσμῷ τυγχάνειν καὶ φυλακῇ. καὶ δὴ τοῦτο πρὸς αὐτοὺς ἔλεγεν· ἐπυνθάνοντο γὰρ ἐλθόντες πρὸς τὸν προφήτην, τί περὶ αὐτῶν ἀφίκοιτο πρὸς τὸν βασιλέα σκήπτεσθαι. ταῦτα μὲν οὕτως ἐλέχθη.", "st": "10.7.6"}, {"sp": "N", "t": "Τῆς δὲ πολιορκίας τῶν Ἱεροσολύμων ὁ Βαβυλώνιος ἐντεταμένως σφόδρα καὶ προθύμως εἴχετο· πύργους τε γὰρ μεγάλων οἰκοδομήσας χωμάτων ἀπ’ αὐτῶν ἀνεῖργε τοὺς τοῖς τείχεσιν ἐφεστῶτας, καὶ πολλὰ περὶ τὸν κύκλον ὅλον ἤγειρε χώματα τοῖς τείχεσι τὸ ὕψος ἴσα. καρτερῶς δὲ καὶ προθύμως ἔφερον οἱ ἐντὸς τὴν πολιορκίαν· ἔκαμνον γὰρ οὔτε πρὸς τὸν λιμὸν οὔτε πρὸς τὴν νόσον τὴν λοιμικήν, ἀλλὰ καίπερ ἔνδον ὑπὸ τούτων ἐλαυνόμενοι τῶν παθῶν τὰς ψυχὰς ἔρρωντο πρὸς τὸν πόλεμον, μήτε πρὸς τὰς ἐπινοίας τῶν ἐχθρῶν καὶ τὰ μηχανήματα καταπληττόμενοι, ἀλλ’ ἀντιμηχανήματα πρὸς πάντα τὰ παρ’ ἐκείνων ἀντεπινοοῦντες· ὡς εἶναι τὸν ὅλον ἀγῶνα καὶ τοῖς Βαβυλωνίοις καὶ τοῖς Ἱεροσολυμίταις τῆς ὀξύτητος καὶ συνέσεως, τῶν μὲν πλέον ἐν ταύτῃ δυνηθῆναι τὴν ἀναίρεσιν οἰομένων εἶναι τῆς πόλεως, τῶν δὲ τὴν σωτηρίαν ἐν οὐκ ἄλλῳ τιθεμένων ἢ ἐν τῷ μὴ καμεῖν μηδ’ ἀπειπεῖν ἀντεφευρίσκοντας οἷς μάταια τὰ τῶν ἐχθρῶν ἀπελεγχθήσεται μηχανήματα. καὶ ταῦθ’ ὑπέμειναν ἐπὶ μῆνας ὀκτωκαίδεκα ἕως οὗ διεφθάρησαν ὑπὸ τοῦ λιμοῦ καὶ τῶν βελῶν, ἅπερ ἀπὸ τῶν πύργων εἰς αὐτοὺς ἠκόντιζον οἱ πολέμιοι.", "st": "10.8.1"}, {"sp": "N", "t": "Ἡιρέθη δ’ ἡ πόλις ἑνδεκάτῳ ἔτει τῆς Σαχχίου βασιλείας τοῦ τετάρτου μηνὸς τῇ ἐνάτῃ ἡμέρᾳ. εἷλον δ’ οὖν οἱ ἡγεμόνες τῶν Βαβυλωνίων, οἷς ἐπίστευσε τὴν πολιορκίαν ὁ Ναβουχοδονόσορος· αὐτὸς γὰρ ἐν Ἀραβαθᾶ διέτριβε πόλει. τὰ δὲ τῶν ἡγεμόνων ὀνόματα, εἴ τις ἐπιζητήσειε γνῶναι, οἵτινες τὰ Ἱεροσόλυμα πορθήσαντες ὑπέταξαν, ἦν Ῥεγάλσαρος, Ἀρέμαντος, Σεμέγαρος, Ναβώσαρις, Ἀχαράμψαρις. ἁλούσης δὲ τῆς πόλεως περὶ μέσην νύκτα καὶ τῶν ἡγεμόνων τῶν πολεμίων εἰσελθόντων εἰς τὸ ἱερὸν γνοὺς ὁ Σαχχίας ὁ βασιλεύς, παραλαβὼν τὰς γυναῖκας καὶ τὰ τέκνα καὶ τοὺς ἡγεμόνας καὶ τοὺς φίλους φεύγει μετ’ αὐτῶν ἐκ τῆς πόλεως διὰ τῆς καρτερᾶς φάραγγος καὶ διὰ τῆς ἐρήμου. φρασάντων δὲ τοῦτό τινων αὐτομόλων τοῖς Βαβυλωνίοις ὑπὸ τὸν ὄρθρον ὥρμησαν διώκειν αὐτόν, καταλαβόντες δὲ οὐκ ἄπωθεν Ἱεριχοῦντος ἐκυκλώσαντο αὐτόν· οἱ δὲ φίλοι καὶ οἱ ἡγεμόνες οἱ συμφυγόντες τῷ Σαχχίᾳ ἐπεὶ τοὺς πολεμίους ἐγγὺς ὄντας εἶδον, καταλιπόντες αὐτὸν διεσπάρησαν ἄλλος ἀλλαχοῦ καὶ σώζειν ἑαυτὸν ἕκαστος ἔγνω. περιλειφθέντα τε αὐτὸν σὺν ὀλίγοις ζωγρήσαντες οἱ πολέμιοι μετὰ τῶν τέκνων καὶ τῶν γυναικῶν ἤγαγον πρὸς τὸν βασιλέα. παραγενόμενον δ’ αὐτὸν ὁ Ναβουχοδονόσαρος ἀσεβῆ καὶ παράσπονδον ἀποκαλεῖν ἤρξατο καὶ ἀμνήμονα τῶν πρόσω λόγων, οὓς ἐποιήσατο σώζειν αὐτῷ τὴν χώραν ὑποσχόμενος. ὠνείδιζε δὲ καὶ ἀχαριστίαν παρ’ αὐτοῦ μὲν λαβόντι τὴν βασιλείαν, Ἰωακείμου γὰρ αὐτὴν οὖσαν ἀφελόμενον ἐκείνῳ δοῦναι, χρησαμένῳ δὲ τῇ δυνάμει κατὰ τοῦ παρασχόντος· ἀλλὰ μέγας, εἶπεν, ὁ θεός, ὃς μισήσας σου τὸν τρόπον ὑποχείριον ἡμῖν ἔθηκε. χρησάμενος δὲ τούτοις πρὸς Σαχχίαν τοῖς λόγοις τοὺς υἱοὺς ἐκέλευσεν ἀνελεῖν καὶ τοὺς φίλους παραχρῆμα αὐτοῦ τε Σαχχίου καὶ τῶν ἄλλων αἰχμαλώτων βλεπόντων, ἔπειτα τοὺς ὀφθαλμοὺς ἐκκόψας τοῦ Σαχχίου δήσας ἤγαγεν εἰς Βαβυλῶνα. καὶ ταῦτ’ αὐτῷ συνέβη, ἃ Ἱερεμίας τε καὶ Ἰεζεκίηλος προεφήτευσαν αὐτῷ, ὅτι συλληφθεὶς ἀχθήσεται πρὸς τὸν Βαβυλώνιον καὶ λαλήσει αὐτῷ κατὰ στόμα καὶ ὄψεται τοῖς ὀφθαλμοῖς τοὺς ὀφθαλμοὺς αὐτοῦ. καὶ ταῦτα μὲν Ἱερεμίας εἶπε, τυφλωθεὶς δὲ καὶ ἀχθεὶς εἰς Βαβυλῶνα ταύτην οὐκ εἶδε καθὼς Ἰεζεκίηλος προεῖπε.", "st": "10.8.2"}, {"sp": "N", "t": "Ταῦτα μὲν οὖν ἱκανῶς ἐμφανίσαι δυνάμενα τὴν τοῦ θεοῦ φύσιν τοῖς ἀγνοοῦσιν εἰρήκαμεν, ὅτι ποικίλη τέ ἐστι καὶ πολύτροπος καὶ καθ’ ὥραν ἀπαντᾷ τεταγμένως, ἅ τε δεῖ γενέσθαι προλέγει, τήν τε τῶν ἀνθρώπων ἄγνοιαν καὶ ἀπιστίαν, ὑφ’ ἧς οὐδὲν προϊδεῖν εἰάθησαν τῶν ἀποβησομένων, ἀφύλακτοι δὲ ταῖς συμφοραῖς παρεδόθησαν, ὡς ἀμήχανον αὐτοῖς εἶναι τὴν ἐξ αὐτῶν πεῖραν διαφυγεῖν.", "st": "10.8.3"}, {"sp": "N", "t": "Οἱ μὲν οὖν ἐκ τοῦ Δαυίδου γένους βασιλεύσαντες οὕτως κατέστρεψαν τὸν βίον, εἴκοσι μὲν καὶ εἷς γενόμενοι μέχρι τοῦ τελευταίου βασιλέως, ἔτη δὲ πάντες βασιλεύσαντες πεντακόσια καὶ δεκατέσσαρα καὶ μῆνας ἓξ καὶ ἡμέρας δέκα, ἐξ ὧν εἴκοσι τὴν ἀρχὴν κατέσχεν ὁ πρῶτος αὐτῶν βασιλεὺς Σαοῦλος οὐκ ἐκ τῆς αὐτῆς φυλῆς ὑπάρχων.", "st": "10.8.4"}, {"sp": "N", "t": "Ὁ δὲ Βαβυλώνιος πέμπει τὸν αὑτοῦ στρατηγὸν Ναβουζαρδάνην εἰς Ἱεροσόλυμα συλήσοντα τὸν ναόν, προστάξας ἅμα καὶ καταπρῆσαι αὐτόν τε καὶ τὰ βασίλεια τήν τε πόλιν εἰς ἔδαφος καθελεῖν καὶ τὸν λαὸν εἰς τὴν Βαβυλωνίαν μεταστῆσαι. ὃς γενόμενος ἐν τοῖς Ἱεροσολύμοις ἑνδεκάτῳ ἔτει τῆς Σαχχίου βασιλείας συλᾷ τε τὸν ναὸν καὶ βαστάζει τὰ σκεύη τοῦ θεοῦ χρυσᾶ τε καὶ ἀργυρᾶ καὶ δὴ καὶ τὸν μέγαν λουτῆρα, ὃν Σολόμων ἀνέθηκεν, ἔτι γε μὴν τοὺς στύλους τοὺς χαλκοῦς καὶ τὰς κεφαλὰς αὐτῶν τάς τε χρυσᾶς τραπέζας καὶ τὰς λυχνίας. βαστάσας δὴ ταῦτα ἀνῆψε τὸν ναὸν μηνὶ πέμπτῳ τῇ νουμηνίᾳ ἑνδεκάτῳ ἔτει τῆς Σαχχίου βασιλείας, ὀκτωκαιδεκάτῳ δὲ τῆς Ναβουχοδονοσόρου· ἐνέπρησε δὲ καὶ τὰ βασίλεια καὶ τὴν πόλιν κατέστρεψεν. ἐνεπρήσθη δὲ ὁ ναὸς μετὰ τετρακόσια ἔτη καὶ ἑβδομήκοντα καὶ μῆνας ἓξ καὶ δέκα ἡμέρας, ἀφ’ οὗ κατεσκευάσθη· τῇ δ’ ἐξ Αἰγύπτου μεταναστάσει τοῦ λαοῦ τότε ἦν ἔτη χίλια ἑξηκονταδύο μῆνες ἓξ ἡμέραι δέκα· τῷ δὲ κατακλυσμῷ μέχρι τῆς τοῦ ναοῦ πορθήσεως χρόνος ἦν ὁ πᾶς ἐτῶν χιλίων ἐνακοσίων πεντηκονταεπτὰ μηνῶν ἓξ ἡμερῶν δέκα· ἐξ οὗ δ’ ἐγεννήθη ὁ Ἄδαμος μέχρι τῶν περὶ τὸν ναὸν συμβάντων ἔτη ἐστὶ τετρακισχίλια πεντακόσια δεκατρία μῆνες ἓξ ἡμέραι δέκα. τοσοῦτον μὲν οὖν τὸ τούτων τῶν ἐτῶν πλῆθος· ὅσα γε μὴν ἐπράχθη καθ’ ἕκαστον τῶν συμβεβηκότων δεδηλώκαμεν. ὁ δὲ στρατηγὸς τοῦ Βαβυλωνίων βασιλέως κατασκάψας τὰ Ἱεροσόλυμα καὶ τὸν λαὸν μεταναστήσας ἔλαβεν αἰχμαλώτους τὸν ἀρχιερέα Σεβαῖον καὶ τὸν μετ’ αὐτὸν ἱερέα Σεφενίαν καὶ τοὺς φυλάσσοντας τὸ ἱερὸν ἡγεμόνας, τρεῖς δὲ ἦσαν οὗτοι, καὶ τὸν ἐπὶ τῶν ὁπλιτῶν εὐνοῦχον καὶ τοὺς φίλους τοῦ Σαχχίου ἑπτὰ καὶ τὸν γραμματέα αὐτοῦ καὶ ἄλλους ἡγεμόνας ἑξήκοντα, οὓς ἅπαντας μεθ’ ὧν ἐσύλησε σκευῶν ἐκόμισε πρὸς τὸν βασιλέα εἰς Σαλάβαθα πόλιν τῆς Συρίας. ὁ δὲ βασιλεὺς τοῦ μὲν ἀρχιερέως καὶ τῶν ἡγεμόνων ἐκέλευσεν ἐκεῖ τὰς κεφαλὰς ἀποτεμεῖν, αὐτὸς δὲ πάντας τοὺς αἰχμαλώτους καὶ τὸν Σαχχίαν εἰς Βαβυλῶνα δέσμιον ἐπήγετο καὶ Ἰωσάδακον τὸν ἀρχιερέα ὄντα υἱὸν Σαραία τοῦ ἀρχιερέως, ὃν ἀπέκτεινεν ὁ Βαβυλώνιος ἐν Ἀριβαθᾶ πόλει τῆς Συρίας, ὡς καὶ πρότερον ἡμῖν δεδήλωται.", "st": "10.8.5"}, {"sp": "N", "t": "Ἐπεὶ δὲ τὸ γένος διεξήλθομεν τὸ τῶν βασιλέων καὶ τίνες ἦσαν δεδηλώκαμεν καὶ τοὺς χρόνους αὐτῶν, ἀναγκαῖον ἡγησάμην καὶ τῶν ἀρχιερέων εἰπεῖν τὰ ὀνόματα καὶ τίνες ἦσαν οἱ τὴν ἀρχιερωσύνην καταδείξαντες ἐπὶ τοῖς βασιλεῦσι. πρῶτος μὲν οὖν Σάδωκος ἀρχιερεὺς ἐγένετο τοῦ ναοῦ, ὃν Σολόμων ᾠκοδόμησε· μετ’ αὐτὸν δ’ ὁ υἱὸς Ἀχιμᾶς διαδέχεται τὴν τιμὴν καὶ μετὰ Ἀχιμᾶν Ἀζαρίας, τούτου δὲ Ἰώραμος, τοῦ δὲ Ἰωράμου Ἴως, μετ’ αὐτὸν δὲ Ἀξιώραμος, τοῦ δὲ Ἀξιωράμου Φιδέας, τοῦ δὲ Φιδέα Σουδαίας, τοῦ δὲ Σουδαία Ἰουῆλος, τοῦ δὲ Ἰώθαμος, Ἰωθάμου δὲ Οὐρίας, Οὐρία δὲ Νηρίας, Νηρία δὲ Ὠδαίας, τοῦ δὲ Σαλοῦμος, Σαλούμου δὲ Ἐλκίας, Ἐλκία δ’ Ἄζαρος, τοῦ δὲ Ἰωσάδακος ὁ αἰχμαλωτισθεὶς εἰς Βαβυλῶνα. οὗτοι πάντες παῖς παρὰ πατρὸς διεδέξαντο τὴν ἀρχιερωσύνην.", "st": "10.8.6"}, {"sp": "N", "t": "Παραγενόμενος δ’ εἰς Βαβυλῶνα ὁ βασιλεὺς Σαχχίαν μὲν εἶχεν ἄχρις οὗ καὶ ἐτελεύτησεν ἐν εἱρκτῇ, θάψας δ’ αὐτὸν βασιλικῶς τὰ σκεύη τὰ ἐκ τοῦ Ἱεροσολύμων συληθέντα ναοῦ ἀνέθηκε τοῖς ἰδίοις θεοῖς, τὸν δὲ λαὸν κατῴκισεν ἐν τῇ Βαβυλωνίτιδι χώρᾳ, τὸν δὲ ἀρχιερέα ἀπέλυσε τῶν δεσμῶν.", "st": "10.8.7"}, {"sp": "N", "t": "Ὁ δὲ στρατηγὸς Ναβουζαρδάνης αἰχμαλωτίσας τὸν τῶν Ἑβραίων λαὸν τοὺς πένητας καὶ αὐτομόλους ἐκεῖ κατέλιπεν ἀποδείξας αὐτῶν ἡγεμόνα Γαδαλίαν ὄνομ’ Ἀϊκάμου παῖδα τῶν εὖ γεγονότων ἐπιεικῆ καὶ δίκαιον, ἐπέταξε δ’ αὐτοῖς τὴν χώραν ἐργαζομένοις τῷ βασιλεῖ τελεῖν φόρον ὡρισμένον. Ἱερεμίαν δὲ τὸν προφήτην λαβὼν ἐκ τῆς εἱρκτῆς ἔπειθεν εἰς Βαβυλῶνα σὺν αὐτῷ παραγενέσθαι· κεκελεῦσθαι γὰρ ὑπὸ τοῦ βασιλέως πάντ’ αὐτῷ χορηγεῖν· εἰ δὲ τοῦτο μὴ βούλεται, δηλοῦν αὐτῷ ποῦ μένειν διέγνωκεν, ἵνα τοῦτο ἐπισταλῇ τῷ βασιλεῖ. ὁ δὲ προφήτης οὔθ’ ἕπεσθαι ἤθελεν οὔτ’ ἀλλαχόσε που μένειν, ἡδέως δ’ εἶχεν ἐπὶ τοῖς ἐρειπίοις τῆς πατρίδος καὶ τοῖς ταλαιπώροις αὐτῆς διαζῆσαι λειψάνοις. γνοὺς δ’ αὐτοῦ τὴν προαίρεσιν ὁ στρατηγός, τῷ Γαδαλίᾳ προστάξας, ὃν κατέλιπεν, αὐτίκα πᾶσαν αὐτοῦ ποιεῖσθαι πρόνοιαν καὶ χορηγίαν ὅσων ἂν δέηται δωρησάμενός τε αὐτὸν δωρεαῖς πολυτελέσιν ἀπέλυσεν. καὶ Ἱερεμίας μὲν κατέμεινεν [εἰς Δάναν] ἐν πόλει τῆς χώρας Μοσφοθᾶ καλουμένῃ παρακαλέσας τὸν Ναβουζαρδάνην, ἵν’ αὐτῷ συναπολύσῃ τὸν μαθητὴν Βαροῦχον Νήρου δὲ παῖδα ἐξ ἐπισήμου σφόδρα οἰκίας ὄντα καὶ τῇ πατρίῳ γλώττῃ διαφερόντως πεπαιδευμένον.", "st": "10.9.1"}, {"sp": "N", "t": "Ναβουζαρδάνης δὲ ταῦτα διαπραξάμενος ὥρμησεν εἰς Βαβυλῶνα. οἱ δὲ πολιορκουμένων Ἱεροσολύμων φυγόντες διασκεδασθέντες κατὰ τὴν χώραν, ἐπειδὴ τοὺς Βαβυλωνίους ἤκουσαν ἀνακεχωρηκότας καὶ λείψανά τινα καταλελοιπότας ἐν τῇ τῶν Ἱεροσολυμιτῶν γῇ [καὶ] τοὺς ταύτην ἐργασομένους, συλλεχθέντες πανταχόθεν ἧκον πρὸς τὸν Γαδαλίαν εἰς Μασαφθά. ἡγεμόνες δ’ ἦσαν ἐν αὐτοῖς Ἰωάδης υἱὸς Καρίου καὶ Σερέας καὶ Ἰωαζανίας καὶ ἕτεροι πρὸς τούτοις, ἐκ δὲ τοῦ βασιλικοῦ γένους ἦν τις Ἰσμάηλος πονηρὸς ἀνὴρ καὶ δολιώτατος, ὃς πολιορκουμένων τῶν Ἱεροσολύμων ἔφυγε πρὸς τὸν Ἀμμανιτῶν βασιλέα Βααλεὶμ καὶ συνδιήγαγεν αὐτῷ τὸν χρόνον ἐκεῖνον. τούτους τοίνυν γενομένους αὐτοῦ Γαδαλίας ἔπεισε μένειν αὐτίκα μηδὲν δεδιότας τοὺς Βαβυλωνίους· γεωργοῦντας γὰρ τὴν χώραν οὐδὲν πείσεσθαι δεινόν. ταῦτα ὀμνὺς αὐτοῖς διεβεβαιοῦτο καὶ προστάτην αὐτὸν ἔχειν λέγων, ὥστε εἴ τις ἐνοχλοίη τεύξεσθαι τῆς προθυμίας· καὶ συνεβούλευε κατοικεῖν [εἰς] ἣν ἕκαστος βούλεται πόλιν ἀποστέλλοντα μετὰ τῶν ἰδίων καὶ ἀνακτίζειν τὰ ἐδάφη καὶ κατοικεῖν· προεῖπέ τε παρασκευάζεσθαι αὐτοὺς ἕως ἔτι καιρός ἐστι σῖτον καὶ οἶνον καὶ ἔλαιον, ὅπως ἔχωσι διὰ τοῦ χειμῶνος τρέφεσθαι. ταῦτα διαλεχθεὶς πρὸς αὐτοὺς ἀπέλυσε [διὰ] τῆς χώρας εἰς ὃν ἕκαστος ἐβούλετο τόπον.", "st": "10.9.2"}, {"sp": "N", "t": "Διαδραμούσης δὲ φήμης εἰς τὰ περὶ τὴν Ἰουδαίαν ἔθνη, ὅτι τοὺς ἀπὸ τῆς φυγῆς παρ’ αὐτὸν ἐλθόντας Γαδαλίας ἐδέξατο φιλανθρώπως καὶ τὴν γῆν αὐτοῖς γεωργοῦσι κατοικεῖν ἐφῆκεν, ἐφ’ ᾧ τελεῖν φόρον τῷ Βαβυλωνίῳ, συνέδραμον αὐτοὶ πρὸς τὸν Γαδαλίαν καὶ τὴν χώραν κατῴκησαν. κατανοήσαντες δὲ τὴν χώραν καὶ τὴν τοῦ Γαδαλίου χρηστότητα καὶ φιλανθρωπίαν Ἰωάννης καὶ οἱ μετ’ αὐτοῦ ἡγεμόνες ὑπερηγάπησαν αὐτὸν καὶ Βαάλιμον τὸν τῶν Ἀμμανιτῶν βασιλέα ἔλεγον πέμψαι Ἰσμάηλον ἀποκτενοῦντα αὐτὸν δόλῳ κρυφίως, ὅπως αὐτὸς ἄρχῃ τῶν Ἰσραηλιτῶν· εἶναι γὰρ αὐτὸν ἐκ τοῦ γένους τοῦ βασιλικοῦ. ῥύσεσθαί γε μὴν ἔλεγον αὐτὸν τῆς ἐπιβουλῆς, ἂν αὐτοῖς ἐφῇ κτεῖναι τὸν Ἰσμάηλον, ὡς οὐδενὸς γνωσομένου· δεδιέναι γὰρ ἔφασκον, μὴ φονευθεὶς αὐτὸς ὑπ’ ἐκείνου παντελὴς ἀπώλεια γένηται τῶν ὑπολελειμμένων τῆς τῶν Ἰσραηλιτῶν ἰσχύος. ὁ δ’ ἀπιστεῖν αὐτοῖς ὡμολόγει κατ’ ἀνδρὸς εὖ πεπονθότος ἐπιβουλὴν τοιαύτην ἐμφανίσασιν· οὐ γὰρ εἰκὸς εἶναι παρὰ τηλικαύτην ἐρημίαν ὧν ἔχρῃζε μὴ διαμαρτόντα οὕτως πονηρὸν εἰς τὸν εὐεργετήσαντα καὶ ἀνόσιον εὑρεθῆναι, ὡς τῷ μὲν τὸ ἀδίκημα τὸ μὴ ὑπ’ ἄλλων ἐπιβουλευόμενον σῶσαι, σπουδάζειν δὲ αὐτὸν αὐτόχειρα ζητεῖν αὐτοῦ γενέσθαι. οὐ μὴν ἀλλ’ εἰ ταῦτ’ ἀληθῆ δεῖ δοκεῖν, ἄμεινον ἔφασκεν ἀποθανεῖν αὐτὸν ὑπ’ ἐκείνου μᾶλλον, ἢ καταφυγόντα πρὸς αὐτὸν ἄνθρωπον καὶ πιστεύσαντα τὴν ἰδίαν σωτηρίαν καὶ παρακαταθέμενον αὐτῷ διαφθεῖραι.", "st": "10.9.3"}, {"sp": "N", "t": "Καὶ ὁ μὲν Ἰωάννης καὶ οἱ σὺν αὐτῷ τῶν ἡγεμόνων μὴ δυνηθέντες πεῖσαι τὸν Γαδαλίαν ἀπῆλθον. χρόνου δὲ διελθόντος ἡμερῶν τριάκοντα παραγίνεται πρὸς Γαδαλίαν εἰς Μασφαθὰ πόλιν Ἰσμάηλος μετ’ ἀνδρῶν δέκα, οὓς λαμπρᾷ τραπέζῃ καὶ ξενίοις ὑποδεξάμενος εἰς μέθην προήχθη φιλοφρονούμενος τὸν Ἰσμάηλον καὶ τοὺς σὺν αὐτῷ. θεασάμενος δ’ αὐτὸν οὕτως ἔχοντα καὶ βεβαπτισμένον εἰς ἀναισθησίαν καὶ ὕπνον ὑπὸ τῆς μέθης ὁ Ἰσμάηλος ἀναπηδήσας μετὰ τῶν δέκα φίλων ἀποσφάττει τὸν Γαδαλίαν καὶ τοὺς κατακειμένους σὺν αὐτῷ ἐν τῷ συμποσίῳ. καὶ μετὰ τὴν τούτων ἀναίρεσιν ἐξελθὼν νυκτὸς ἅπαντας φονεύει τοὺς ἐν τῇ πόλει Ἰουδαίους καὶ τοὺς ὑπὸ τῶν Βαβυλωνίων καταλειφθέντας ἐν αὐτῇ τῶν στρατιωτῶν. τῇ δ’ ἐπιούσῃ μετὰ δώρων ἧκον πρὸς Γαδαλίαν τῶν ἀπὸ τῆς χώρας ὀγδοήκοντα μηδενὸς τὰ περὶ αὐτὸν ἐγνωκότος. ἰδὼν δὲ αὐτοὺς Ἰσμάηλος εἴσω τε αὐτοὺς καλεῖ ὡς πρὸς Γαδαλίαν, καὶ παρελθόντων ἀποκλείσας τὴν αὔλειον ἐφόνευσε καὶ τὰ σώματα αὐτῶν εἰς λάκκον τινὰ βαθύν, ὡς ἂν ἀφανῆ γένοιτο, κατεπόντισε. διεσώθησαν δὲ τῶν ὀγδοήκοντα τούτων ἀνδρῶν οἳ μὴ πρότερον ἀναιρεθῆναι παρεκάλεσαν πρὶν ἢ τὰ κεκρυμμένα ἐν τοῖς ἀγροῖς αὐτῷ παραδῶσιν ἔπιπλά τε καὶ ἐσθῆτα καὶ σῖτον. ταῦτ’ ἀκούσας ἐφείσατο τῶν ἀνδρῶν τούτων Ἰσμάηλος· τὸν δ’ ἐν τῇ Μασφάθῃ λαὸν σὺν γυναιξὶ καὶ νηπίοις ᾐχμαλώτισεν, ἐν οἷς καὶ τοῦ βασιλέως Σαχχίου θυγατέρας, ἃς Ναβουζαρδάνης ὁ τῶν Βαβυλωνίων στρατηγὸς παρὰ Γαδαλίᾳ καταλελοίπει. ταῦτα διαπραξάμενος ἀφικνεῖται πρὸς τὸν Ἀμμανιτῶν βασιλέα.", "st": "10.9.4"}, {"sp": "N", "t": "Ἀκούσας δ’ ὁ Ἰωάννης καὶ οἱ σὺν αὐτῷ ἡγεμόνες [τὰ ἐν τῇ Μασφαθῇ] τὰ πεπραγμένα ὑπὸ Ἰσμαήλου καὶ τὸν Γαδαλίου θάνατον ἠγανάκτησαν, καὶ τοὺς ἰδίους ἕκαστος ὁπλίτας παραλαβὼν ὥρμησαν πολεμήσοντες τὸν Ἰσμάηλον καὶ καταλαμβάνουσιν αὐτὸν πρὸς τῇ πηγῇ ἐν Ἰβρῶνι. οἱ δὲ αἰχμαλωτισθέντες ὑπὸ Ἰσμαήλου τὸν Ἰωάννην ἰδόντες καὶ τοὺς ἡγεμόνας εὐθύμως διετέθησαν βοήθειαν αὑτοῖς ἥκειν ὑπολαμβάνοντες, καὶ καταλιπόντες τὸν αἰχμαλωτίσαντα πρὸς Ἰωάννην ἀνεχώρησαν. Ἰσμάηλος μὲν οὖν μετ’ ἀνδρῶν ὀκτὼ φεύγει πρὸς τὸν τῶν Ἀμμανιτῶν βασιλέα. ὁ δὲ Ἰωάννης παραλαβὼν οὓς ἀνέσωσεν ἐκ τῶν Ἰσμαήλου χειρῶν καὶ τοὺς εὐνούχους καὶ τὰς γυναῖκας καὶ τὰ νήπια εἴς τινα τόπον Μάνδρα λεγόμενον παραγίνεται. καὶ τὴν μὲν ἡμέραν ἐκείνην ἐπέμεινεν αὐτόθι, διεγνώκεισαν δ’ ἐκεῖθεν ἄραντες εἰς Αἴγυπτον ἐλθεῖν φοβούμενοι, μὴ κτείνωσιν αὐτοὺς οἱ Βαβυλώνιοι μείναντας ἐν τῇ χώρᾳ ὑπὲρ Γαδαλία τοῦ κατασταθέντος ὑπ’ αὐτῶν ἡγεμόνος ὀργισθέντες πεφονευμένου.", "st": "10.9.5"}, {"sp": "N", "t": "Ὄντων δ’ ἐπὶ ταύτης τῆς βουλῆς προσίασιν Ἱερεμίᾳ τῷ προφήτῃ Ἰωάννης ὁ τοῦ Καρίου καὶ οἱ ἡγεμόνες οἱ σὺν αὐτῷ παρακαλοῦντες δεηθῆναι τοῦ θεοῦ, ὅπως ἀμηχανοῦσιν αὐτοῖς περὶ τοῦ τί χρὴ ποιεῖν τοῦτ’ αὐτοῖς ὑποδείξῃ, ὀμόσαντες ποιήσειν ὅ τι ἂν αὐτοῖς Ἱερεμίας εἴπῃ. ὑποσχομένου δὲ τοῦ προφήτου διακονήσειν αὐτοῖς πρὸς τὸν θεὸν συνέβη μετὰ δέκα ἡμέρας αὐτῷ φανέντα τὸν θεὸν εἰπεῖν δηλῶσαι Ἰωάννῃ καὶ τοῖς ἄλλοις ἡγεμόσι καὶ τῷ λαῷ παντί, ὅτι μένουσι μὲν αὐτοῖς ἐν ἐκείνῃ τῇ χώρᾳ παρέσται καὶ πρόνοιαν ἕξει καὶ τηρήσει παρὰ τῶν Βαβυλωνίων οὓς δεδίασιν ἀπαθεῖς, πορευομένους δὲ εἰς Αἴγυπτον ἀπολείψει καὶ ταὐτὰ διαθήσει ὀργισθείς, ἃ καὶ τοὺς ἀδελφοὺς αὑτῶν ἔμπροσθεν οἴδατε πεπονθότας. ταῦτα εἰπὼν τῷ Ἰωάννῃ καὶ τῷ λαῷ τὸν θεὸν αὐτοῖς προλέγειν ὁ προφήτης οὐκ ἐπιστεύετο, ὡς κατὰ ἐντολὴν τὴν ἐκείνου μένειν αὐτοὺς ἐν τῇ χώρᾳ κελεύει, χαριζόμενον δὲ Βαρούχῳ τῷ ἰδίῳ μαθητῇ καταψεύδεσθαι μὲν τοῦ θεοῦ, πείθειν δὲ μένειν αὐτόθι, ὡς ἂν ὑπὸ τῶν Βαβυλωνίων διαφθαρῶσι. παρακούσας οὖν ὅ τε λαὸς καὶ Ἰωάννης τῆς τοῦ θεοῦ συμβουλίας, ἣν αὐτοῖς διὰ τοῦ προφήτου παρῄνεσεν, ἀπῆρεν εἰς τὴν Αἴγυπτον ἄγων καὶ τὸν Ἱερεμίαν καὶ τὸν Βαροῦχον.", "st": "10.9.6"}, {"sp": "N", "t": "Γενομένων δὲ αὐτῶν ἐκεῖ σημαίνει τὸ θεῖον τῷ προφήτῃ μέλλοντα στρατεύειν ἐπὶ τοὺς Αἰγυπτίους τὸν βασιλέα τῶν Βαβυλωνίων, καὶ προειπεῖν ἐκέλευε τῷ λαῷ τήν τε ἅλωσιν τῆς Αἰγύπτου, καὶ ὅτι τοὺς μὲν αὐτῶν ἀποκτενεῖ, τοὺς δὲ αἰχμαλώτους λαβὼν εἰς Βαβυλῶνα ἄξει. καὶ ταῦτα συνέβη· τῷ γὰρ πέμπτῳ τῆς Ἱεροσολύμων πορθήσεως ἔτει, ὅ ἐστι τρίτον καὶ εἰκοστὸν τῆς Ναβουχοδονοσόρου βασιλείας, στρατεύει Ναβουχοδονόσορος ἐπὶ τὴν κοίλην Συρίαν, καὶ κατασχὼν αὐτὴν ἐπολέμησε καὶ Μωαβίταις καὶ Ἀμμανίταις. ποιησάμενος δὲ ὑπήκοα ταῦτα τὰ ἔθνη ἐνέβαλεν εἰς τὴν Αἴγυπτον καταστρεψόμενος αὐτήν, καὶ τὸν μὲν τότε βασιλέα κτείνει, καταστήσας δὲ ἕτερον τοὺς ἐν αὐτῇ πάλιν Ἰουδαίους αἰχμαλωτίσας ἤγαγεν εἰς Βαβυλῶνα. καὶ τὸ μὲν Ἑβραίων γένος ἐν τοιούτῳ τέλει γενόμενον παρειλήφαμεν δὶς ἐλθὸν πέραν Εὐφράτου· ὑπὸ Ἀσσυρίων μὲν γὰρ ἐξέπεσεν ὁ τῶν δέκα φυλῶν λαὸς ἀπὸ Σαμαρείας βασιλεύοντος αὐτῶν Ὠσήου, ἔπειτα τῶν δύο φυλῶν ὑπὸ Ναβουχοδονοσόρου τοῦ τῶν Βαβυλωνίων βασιλέως καὶ τῶν Χαλδαίων ὃς ὑπελείφθη τῶν Ἱεροσολύμων ἁλόντων. Σαλμανάσσης μὲν οὖν ἀναστήσας τοὺς Ἰσραηλίτας κατῴκισεν ἀντ’ αὐτῶν τὸ τῶν Χουθαίων ἔθνος, οἳ πρότερον ἐνδοτέρω τῆς Περσίδος καὶ τῆς Μηδίας ἦσαν, τότε μέντοι Σαμαρεῖς ἐκλήθησαν τὴν τῆς χώρας εἰς ἣν κατῳκίσθησαν προσηγορίαν ἀναλαβόντες· ὁ δὲ τῶν Βαβυλωνίων βασιλεὺς τὰς δύο φυλὰς ἐξαγαγὼν οὐδὲν ἔθνος εἰς τὴν χώραν αὐτῶν κατῴκισε καὶ διὰ τοῦτο ἔρημος ἡ Ἰουδαία πᾶσα καὶ Ἱεροσόλυμα καὶ ὁ ναὸς διέμεινεν ἔτεσιν ἑβδομήκοντα. τὸν δὲ σύμπαντα χρόνον, ὃς ἀπὸ τῆς τῶν Ἰσραηλιτῶν αἰχμαλωσίας ἐπὶ τὴν τῶν δύο φυλῶν ἀνάστασιν ἐληλύθει, ἑκατὸν ἔτη καὶ τριάκοντα καὶ μῆνας ἓξ καὶ δέκα ἡμέρας συνέβη γενέσθαι.", "st": "10.9.7"}, {"sp": "N", "t": "Ὁ δὲ τῶν Βαβυλωνίων βασιλεὺς Ναβουχοδονόσορος τοὺς εὐγενεστάτους λαβὼν τῶν Ἰουδαίων παῖδας καὶ τοὺς Σαχχίου τοῦ βασιλέως αὐτῶν συγγενεῖς, οἳ καὶ ταῖς ἀκμαῖς τῶν σωμάτων καὶ ταῖς εὐμορφίαις τῶν ὄψεων ἦσαν περίβλεπτοι, παιδαγωγοῖς καὶ τῇ δι’ αὐτῶν θεραπείᾳ παραδίδωσι ποιήσας τινὰς αὐτῶν ἐκτομίας· τὸ δ’ αὐτὸ καὶ τοὺς ἄλλων ἐθνῶν ὅσα κατεστρέψατο ληφθέντας ἐν ὥρᾳ τῆς ἡλικίας διαθεὶς ἐχορήγει μὲν αὐτοῖς τὰ ἀπὸ τῆς τραπέζης αὐτοῦ εἰς δίαιταν, ἐπαίδευε δὲ καὶ τὰ ἐπιχώρια καὶ τὰ τῶν Χαλδαίων ἐξεδίδασκε γράμματα· ἦσαν δὲ οὗτοι σοφίαν ἱκανοὶ περὶ ἣν ἐκέλευε διατρίβειν. ἦσαν δ’ ἐν τούτοις τῶν ἐκ τοῦ Σαχχίου γένους τέσσαρες καλοί τε καὶ ἀγαθοὶ τὰς φύσεις, ὧν ὁ μὲν Δανίηλος ἐκαλεῖτο, ὁ δὲ Ἀνανίας, ὁ δὲ Μισάηλος, ὁ δὲ τέταρτος Ἀζαρίας. τούτους ὁ Βαβυλώνιος μετωνόμασε καὶ χρῆσθαι προσέταξεν ἑτέροις ὀνόμασι. καὶ τὸν μὲν Δανίηλον ἐκάλουν Βαλτάσαρον, τὸν δ’ Ἀνανίαν Σεδράχην, Μισάηλον δὲ Μισάχην, τὸν δ’ Ἀζαρίαν Ἀβδεναγώ. τούτους ὁ βασιλεὺς δι’ ὑπερβολὴν εὐφυΐας καὶ σπουδῆς τῆς περὶ τὴν παίδευσιν καὶ σοφίας ἐν προκοπῇ γενομένους εἶχεν ἐν τιμῇ καὶ στέργων διετέλει.", "st": "10.10.1"}, {"sp": "N", "t": "Δόξαν δὲ Δανιήλῳ μετὰ τῶν συγγενῶν σκληραγωγεῖν ἑαυτὸν καὶ τῶν ἀπὸ τῆς βασιλικῆς τραπέζης ἐδεσμάτων ἀπέχεσθαι καὶ καθόλου πάντων τῶν ἐμψύχων, προσελθὼν Ἀσχάνῃ τῷ τὴν ἐπιμέλειαν αὐτῶν ἐμπεπιστευμένῳ εὐνούχῳ τὰ μὲν παρὰ τοῦ βασιλέως αὐτοῖς κομιζόμενα παρεκάλεσεν αὐτὸν ἀναλίσκειν λαμβάνοντα, παρέχειν δ’ αὐτοῖς ὄσπρια καὶ φοίνικας εἰς διατροφὴν καὶ εἴ τι τῶν ἀψύχων ἕτερον βούλοιτο· πρὸς γὰρ τὴν τοιαύτην δίαιταν αὐτοὺς κεκινῆσθαι, τῆς δ’ ἑτέρας περιφρονεῖν. ὁ δ’ εἶναι μὲν ἕτοιμος ἔλεγεν ὑπηρετεῖν αὐτῶν τῇ προαιρέσει, ὑφορᾶσθαι δέ, μὴ κατάδηλοι τῷ βασιλεῖ γενηθέντες ἐκ τῆς τῶν σωμάτων ἰσχνότητος καὶ τῆς τροπῆς τῶν χαρακτήρων, συμμεταβάλλειν γὰρ αὐτοῖς ἀνάγκη τὰ σώματα καὶ τὰς χρόας ἅμα τῇ διαίτῃ, καὶ μάλιστα τῶν ἄλλων παίδων εὐπαθούντων ἐλεγχθέντες αἴτιοι κινδύνου καὶ τιμωρίας αὐτῷ καταστῶσιν. ἔχοντα τοίνυν πρὸς τοῦτ’ εὐλαβῶς τὸν Ἀσχάνην πείθουσιν ἐπὶ δέκα ἡμέρας ταῦτα παρασχεῖν αὐτοῖς πείρας ἕνεκα καὶ μὴ μεταβαλούσης μὲν αὐτοῖς τῆς τῶν σωμάτων ἕξεως ἐπιμένειν τοῖς αὐτοῖς, ὡς οὐδὲν ἔτι εἰς αὐτὴν βλαβησομένων, εἰ δὲ μειωθέντας ἴδοι καὶ κάκιον τῶν ἄλλων ἔχοντας, ἐπὶ τὴν προτέραν αὐτοὺς δίαιταν ἄγειν. ὡς δὲ οὐ μόνον οὐδὲν αὐτοὺς ἐλύπει τὴν τροφὴν ἐκείνην προσφερομένους, ἀλλὰ καὶ τῶν ἄλλων εὐτραφέστεροι τὰ σώματα καὶ μείζονες ἐγίνοντο, ὡς τοὺς μὲν ἐνδεεστέρους ὑπολαμβάνειν οἷς τὴν βασιλικὴν συνέβαινεν εἶναι χορηγίαν, τοὺς δὲ μετὰ τοῦ Δανιήλου δοκεῖν ἐν ἀφθονίᾳ καὶ τρυφῇ τῇ πάσῃ βιοῦν, ἔκτοτε μετ’ ἀδείας ὁ Ἀσχάνης ἃ μὲν ἀπὸ τοῦ δείπνου καθ’ ἡμέραν συνήθως ἔπεμπε τοῖς παισὶν ὁ βασιλεὺς αὐτὸς ἐλάμβανεν, ἐχορήγει δ’ αὐτοῖς τὰ προειρημένα. οἱ δὲ ὡς καὶ τῶν ψυχῶν αὐτοῖς διὰ τοῦτο καθαρῶν καὶ πρὸς τὴν παιδείαν ἀκραιφνῶν γεγενημένων καὶ τῶν σωμάτων πρὸς φιλοπονίαν εὐτονωτέρων, οὔτε γὰρ ἐκείνας ἐφείλκοντο καὶ βαρείας εἶχον ὑπὸ τροφῆς ποικίλης οὔτε ταῦτα μαλακώτερα διὰ τὴν αὐτὴν αἰτίαν, πᾶσαν ἑτοίμως ἐξέμαθον παιδείαν ἥτις ἦν παρὰ τοῖς Ἑβραίοις καὶ τοῖς Χαλδαίοις. μάλιστα δὲ Δανίηλος ἱκανῶς ἤδη σοφίας ἐμπείρως ἔχων περὶ κρίσεις ὀνείρων ἐσπουδάκει, καὶ τὸ θεῖον αὐτῷ φανερὸν ἐγίνετο.", "st": "10.10.2"}, {"sp": "N", "t": "Μετὰ δ’ ἔτος δεύτερον τῆς Αἰγύπτου πορθήσεως ὁ βασιλεὺς Ναβουχοδονόσορος ὄναρ ἰδὼν θαυμαστόν, οὗ τὴν ἔκβασιν κατὰ τοὺς ὕπνους αὐτὸς αὐτῷ ἐδήλωσεν ὁ θεός, τούτου μὲν ἐπιλανθάνεται διαναστὰς ἐκ τῆς κοίτης, μεταπεμψάμενος δὲ τοὺς Χαλδαίους καὶ τοὺς μάγους καὶ τοὺς μάντεις, ὡς εἴη τι ὄναρ ἑωρακὼς ἔλεγεν αὐτοῖς, καὶ τὸ συμβεβηκὸς περὶ τὴν λήθην ὧν εἶδε μηνύων ἐκέλευεν αὐτοὺς λέγειν, ὅτι τε ἦν τὸ ὄναρ καὶ [τί] τὸ σημεῖον. τῶν δὲ ἀδύνατον εἶναι λεγόντων ἀνθρώποις τοῦτο εὑρεῖν, εἰ δὲ αὐτοῖς ἐκθοῖτο τὴν ὄψιν τοῦ ἐνυπνίου φράσειν τὸ σημεῖον ὑποσχομένων, θάνατον ἠπείλησεν αὐτοῖς, εἰ μὴ τὸ ὄναρ εἴποιεν, προσέταξε τε πάντας αὐτοὺς ἀναιρεθῆναι ποιῆσαι τὸ κελευσθὲν ὁμολογήσαντας μὴ δύνασθαι. Δανίηλος δ’ ἀκούσας, ὅτι προσέταξε πάντας τοὺς σοφοὺς ὁ βασιλεὺς ἀποθανεῖν, ἐν τούτοις δὲ καὶ αὐτὸν μετὰ τῶν συγγενῶν κινδυνεύειν, πρόσεισιν Ἀριόχῃ τῷ τὴν ἐπὶ τῶν σωματοφυλάκων τοῦ βασιλέως ἀρχὴν πεπιστευμένῳ. δεηθεὶς δὲ παρ’ αὐτοῦ τὴν αἰτίαν μαθεῖν, δι’ ἣν ὁ βασιλεὺς πάντας εἴη προστεταχὼς ἀναιρεθῆναι τοὺς σοφοὺς καὶ Χαλδαίους καὶ μάγους, καὶ μαθὼν τὸ περὶ τὸ ἐνύπνιον καὶ ὅτι κελευσθέντες ὑπὸ τοῦ βασιλέως τοῦτ’ αὐτῷ δηλοῦν ἐπιλελησμένῳ φήσαντες μὴ δύνασθαι παρώξυναν αὐτόν, παρεκάλεσε τὸν Ἀριόχην εἰσελθόντα πρὸς τὸν βασιλέα μίαν αἰτήσασθαι νύκτα τοῖς μάγοις [καὶ ταύτῃ] τὴν ἀναίρεσιν ἐπισχεῖν· ἐλπίζειν γὰρ δι’ αὐτῆς δεηθεὶς τοῦ θεοῦ γνώσεσθαι τὸ ἐνύπνιον. ὁ δὲ Ἀριόχης ταῦτ’ ἀπήγγειλε τῷ βασιλεῖ Δανίηλον ἀξιοῦν. καὶ ὁ μὲν κελεύει τὴν ἀναίρεσιν ἐπισχεῖν τῶν μάγων ἕως γνῷ τὴν ὑπόσχεσιν τὴν Δανιήλου· ὁ δὲ παῖς μετὰ τῶν συγγενῶν ὑποχωρήσας πρὸς ἑαυτὸν δι’ ὅλης ἱκετεύει τὸν θεὸν τῆς νυκτὸς γνωρίσαι καὶ τοὺς μάγους καὶ τοὺς Χαλδαίους, οἷς δεῖ καὶ αὐτοὺς συναπολέσθαι, ῥύσασθαι δὲ τῆς τοῦ βασιλέως ὀργῆς ἐμφανίσαντα τὴν ὄψιν αὐτῷ καὶ ποιήσαντα δήλην, ἧς ὁ βασιλεὺς ἐπελέληστο διὰ τῆς παρελθούσης νυκτὸς ἰδὼν κατὰ τοὺς ὕπνους. ὁ δὲ θεὸς ἅμα τούς τε κινδυνεύοντας ἐλεήσας καὶ τὸν Δανίηλον τῆς σοφίας ἀγασάμενος τό τε ὄναρ αὐτῷ γνώριμον ἐποίησε καὶ τὴν κρίσιν, ὡς ἂν καὶ τὸ σημαινόμενον ὁ βασιλεὺς παρ’ αὐτοῦ μάθοι. Δανίηλος δὲ γνοὺς παρὰ τοῦ θεοῦ ταῦτα περιχαρὴς ἀνίσταται καὶ τοῖς ἀδελφοῖς δηλώσας τοὺς μὲν ἀπεγνωκότας ἤδη τοῦ ζῆν καὶ πρὸς τῷ τεθνάναι τὴν διάνοιαν ἔχοντας εἰς εὐθυμίαν καὶ τὰς περὶ τοῦ βίου διήγειρεν ἐλπίδας, εὐχαριστήσας δὲ τῷ θεῷ μετ’ αὐτῶν ἔλεον λαβόντι τῆς ἡλικίας αὐτῶν γενομένης ἡμέρας παραγίνεται πρὸς Ἀριόχην καὶ ἄγειν αὐτὸν ἠξίου πρὸς τὸν βασιλέα· δηλῶσαι γὰρ αὐτῷ βούλεσθαι τὸ ἐνύπνιον, ὅ φησιν ἰδεῖν πρὸ τῆς παρελθούσης νυκτός.", "st": "10.10.3"}, {"sp": "N", "t": "Εἰσελθὼν δὲ πρὸς τὸν βασιλέα Δανίηλος παρῃτεῖτο πρῶτον μὴ σοφώτερον αὐτὸν δόξαι τῶν ἄλλων Χαλδαίων καὶ μάγων, ὅτι μηδενὸς ἐκείνων τὸ ὄναρ εὑρεῖν δυνηθέντος αὐτὸς αὐτὸ μέλλοι λέγειν· οὐ γὰρ κατ’ ἐμπειρίαν οὐδ’ ὅτι τὴν διάνοιαν αὐτῶν μᾶλλον ἐκπεπόνηται τοῦτο γίνεται, ἀλλ’ ἐλεήσας ἡμᾶς ὁ θεὸς κινδυνεύοντας ἀποθανεῖν δεηθέντι περί τε τῆς ἐμῆς ψυχῆς καὶ τῶν ὁμοεθνῶν καὶ τὸ ὄναρ καὶ τὴν κρίσιν αὐτοῦ φανερὰν ἐποίησεν. οὐχ ἧττον γὰρ τῆς ἐφ’ ἡμῖν αὐτοῖς καταδικασθεῖσιν ὑπὸ σοῦ μὴ ζῆν λύπης περὶ τῆς σῆς αὐτοῦ δόξης ἐφρόντιζον ἀδίκως οὕτως ἄνδρας καὶ ταῦτα καλοὺς κἀγαθοὺς ἀποθανεῖν κελεύσαντος, οἷς οὐδὲν μὲν ἀνθρωπίνης σοφίας ἐχόμενον προσέταξας, ὃ δ’ ἦν θεοῦ τοῦτο ἀπῄτεις παρ’ αὐτῶν. σοὶ τοίνυν φροντίζοντι περὶ τοῦ τίς ἄρξει τοῦ κόσμου παντὸς μετὰ σέ, κοιμηθέντι βουλόμενος δηλῶσαι πάντας ὁ θεὸς τοὺς βασιλεύσοντας ὄναρ ἔδειξε τοιοῦτον· ἔδοξας ὁρᾶν ἀνδριάντα μέγαν ἑστῶτα, οὗ τὴν μὲν κεφαλὴν συνέβαινεν εἶναι χρυσῆν, τοὺς δὲ ὤμους καὶ τοὺς βραχίονας ἀργυροῦς, τὴν δὲ γαστέρα καὶ τοὺς μηροὺς χαλκέους, κνήμας δὲ καὶ πόδας σιδηροῦς. εἶτα λίθον ἐξ ὄρους ἀπορραγέντα ἐμπεσεῖν τῷ ἀνδριάντι καὶ τοῦτον καταβαλόντα συνθρύψαι καὶ μηδὲν αὐτοῦ μέρος ὁλόκληρον ἀφεῖναι, ὡς τὸν μὲν χρυσὸν καὶ τὸν ἄργυρον καὶ τὸν χαλκὸν καὶ τὸν σίδηρον ἀλεύρων λεπτότερον γενέσθαι, καὶ τὰ μὲν ἀνέμου πνεύσαντος σφοδροτέρου ὑπὸ τῆς βίας ἁρπαγέντα διασπαρῆναι, τὸν δὲ λίθον αὐξῆσαι τοσοῦτον, ὡς ἅπασαν δοκεῖν τὴν γῆν ὑπ’ αὐτοῦ πεπληρῶσθαι. τὸ μὲν οὖν ὄναρ, ὅπερ εἶδες, τοῦτ’ ἔστιν, ἡ δὲ κρίσις αὐτοῦ τοῦτον ἔχει τὸν τρόπον· ἡ μὲν χρυσῆ κεφαλὴ σέ τε ἐδήλου καὶ τοὺς πρὸ σοῦ βασιλέας Βαβυλωνίους ὄντας· αἱ δὲ χεῖρες καὶ οἱ ὦμοι σημαίνουσιν ὑπὸ δύο καταλυθήσεσθαι βασιλέων τὴν ἡγεμονίαν ὑμῶν· τὴν δὲ ἐκείνων ἕτερός τις ἀπὸ τῆς δύσεως καθαιρήσει χαλκὸν ἠμφιεσμένος, καὶ ταύτην ἄλλη παύσει τὴν ἰσχὺν ὁμοία σιδήρῳ καὶ κρατήσει δὲ εἰς ἅπαντα διὰ τὴν τοῦ σιδήρου φύσιν· εἶναι γὰρ αὐτὴν στερροτέραν τῆς τοῦ χρυσοῦ καὶ τοῦ ἀργύρου καὶ τοῦ χαλκοῦ. ἐδήλωσε δὲ καὶ περὶ τοῦ λίθου Δανίηλος τῷ βασιλεῖ, ἀλλ’ ἐμοὶ μὲν οὐκ ἔδοξε τοῦτο ἱστορεῖν τὰ παρελθόντα καὶ τὰ γεγενημένα συγγράφειν οὐ τὰ μέλλοντα ὀφείλοντι, εἰ δέ τις τῆς ἀκριβείας γλιχόμενος οὐ περιίσταται πολυπραγμονεῖν, ὡς καὶ περὶ τῶν ἀδήλων τί γενήσεται βούλεσθαι μαθεῖν, σπουδασάτω τὸ βιβλίον ἀναγνῶναι τὸ Δανιήλου· εὑρήσει δὲ τοῦτο ἐν τοῖς ἱεροῖς γράμμασιν.", "st": "10.10.4"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς Ναβουχοδονόσαρος ἀκηκοὼς ταῦτα καὶ ἐπιγνοὺς τὸ ὄναρ ἐξεπλάγη τὴν τοῦ Δανιήλου φύσιν καὶ πεσὼν ἐπὶ πρόσωπον, ᾧ τρόπῳ τὸν θεὸν προσκυνοῦσι, τούτῳ τὸν Δανίηλον ἠσπάζετο· καὶ θύειν δὲ ὡς θεῷ προσέταξεν, οὐ μὴν ἀλλὰ καὶ τὴν προσηγορίαν αὐτῷ τοῦ ἰδίου θεοῦ θέμενος ἁπάσης ἐπίτροπον τῆς βασιλείας ἐποίησε καὶ τοὺς συγγενεῖς αὐτοῦ, οὓς ὑπὸ φθόνου καὶ βασκανίας εἰς κίνδυνον ἐμπεσεῖν συνέβη τῷ βασιλεῖ προσκρούσαντας ἐξ αἰτίας τοιαύτης· ὁ βασιλεὺς κατασκευάσας χρύσεον ἀνδριάντα πηχῶν τὸ μὲν ὕψος ἑξήκοντα τὸ πλάτος δὲ ἕξ, στήσας αὐτὸν ἐν τῷ μεγάλῳ τῆς Βαβυλῶνος πεδίῳ καὶ μέλλων καθιεροῦν αὐτὸν συνεκάλεσεν ἐξ ἁπάσης ἧς ἦρχε γῆς τοὺς πρώτους πρῶτον αὐτοῖς προστάξας, ὅταν σημαινούσης ἀκούσωσι τῆς σάλπιγγος, τότε πεσόντας προσκυνεῖν τὸν ἀνδριάντα· τοὺς δὲ μὴ ποιήσαντας ἠπείλησεν εἰς τὴν τοῦ πυρὸς ἐμβληθῆναι κάμινον. πάντων οὖν μετὰ τὸ σημαινούσης ἐπακοῦσαι τῆς σάλπιγγος προσκυνούντων τὸν ἀνδριάντα τοὺς Δανιήλου συγγενεῖς οὐ ποιῆσαι τοῦτό φασι μὴ βουληθέντας παραβῆναι τοὺς πατρίους νόμους. καὶ οἱ μὲν ἐλεγχθέντες εὐθὺς εἰς τὸ πῦρ ἐμβληθέντες θείᾳ σώζονται προνοίᾳ καὶ παραδόξως διαφεύγουσι τὸν θάνατον. ἀλλὰ κατὰ λογισμὸν οἶμαι τῷ μηδὲν ἀδικήσαντας εἰς αὐτὸ βληθῆναι οὐχ ἥψατο, καίειν δ’ ἀσθενὲς ἦν ἔχον ἐν ἑαυτῷ τοὺς παῖδας τοῦ θεοῦ κρείττονα τὰ σώματα αὐτῶν ὥστε μὴ δαπανηθῆναι ὑπὸ τοῦ πυρὸς παρασκευάσαντος. τοῦτο συνέστησεν αὐτοὺς τῷ βασιλεῖ ὡς δικαίους καὶ θεοφιλεῖς, διὸ μετὰ ταῦτα πάσης ἀξιούμενοι παρ’ αὐτοῦ τιμῆς διετέλουν.", "st": "10.10.5"}, {"sp": "N", "t": "Ὀλίγῳ δ’ ὕστερον χρόνῳ πάλιν ὁρᾷ κατὰ τοὺς ὕπνους ὁ βασιλεὺς ὄψιν ἑτέραν, ὡς ἐκπεσὼν τῆς ἀρχῆς μετὰ θηρίων ἕξει τὴν δίαιταν καὶ διαζήσας οὕτως ἐπὶ τῆς ἐρημίας ἔτεσιν ἑπτὰ αὖθις τὴν ἀρχὴν ἀπολήψεται. τοῦτο θεασάμενος τοὖναρ πάλιν τοὺς μάγους συγκαλέσας ἀνέκρινεν αὐτοὺς περὶ αὐτοῦ καὶ τί σημαίνοι λέγειν ἠξίου. τῶν μὲν οὖν ἄλλων οὐθεὶς ἠδυνήθη τὴν τοῦ ἐνυπνίου διάνοιαν εὑρεῖν οὐδ’ ἐμφανίσαι τῷ βασιλεῖ, Δανίηλος δὲ μόνος καὶ τοῦτ’ ἔκρινε καὶ καθὼς οὗτος αὐτῷ προεῖπεν ἀπέβη. διατρίψας γὰρ ἐπὶ τῆς ἐρημίας τὸν προειρημένον χρόνον οὐδενὸς τολμήσαντος ἐπιθέσθαι τοῖς πράγμασι παρὰ τὴν ἑπταετίαν, δεηθεὶς τοῦ θεοῦ τὴν βασιλείαν ἀπολαβεῖν πάλιν εἰς αὐτὴν ἐπανέρχεται. ἐγκαλέσῃ δέ μοι μηδεὶς οὕτως ἕκαστα τούτων ἀπαγγέλλοντι διὰ τῆς γραφῆς, ὡς ἐν τοῖς ἀρχαίοις εὑρίσκω βιβλίοις· καὶ γὰρ εὐθὺς ἐν ἀρχῇ τῆς ἱστορίας πρὸς τοὺς ἐπιζητήσοντάς τι περὶ τῶν πραγμάτων ἢ μεμψομένους ἠσφαλισάμην, μόνον τε μεταφράζειν τὰς Ἑβραίων βίβλους εἰπὼν εἰς τὴν Ἑλλάδα γλῶτταν καὶ ταῦτα δηλώσειν μήτε προστιθεὶς τοῖς πράγμασιν αὐτὸς ἰδίᾳ μήτ’ ἀφαιρῶν ὑπεισχημένος.", "st": "10.10.6"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς Ναβουχοδονόσορος ἔτη τρία καὶ τεσσαράκοντα βασιλεύσας τελευτᾷ τὸν βίον ἀνὴρ δραστήριος καὶ τῶν πρὸ αὐτοῦ βασιλέων εὐτυχέστερος γενόμενος. μέμνηται δ’ αὐτοῦ τῶν πράξεων καὶ Βηρωσὸς ἐν τῇ τρίτῃ τῶν Χαλδαϊκῶν ἱστοριῶν λέγων οὕτως· ἀκούσας δ’ ὁ πατὴρ αὐτοῦ Ναβουχοδονόσορος, ὅτι ὁ τεταγμένος σατράπης ἐν τῇ Αἰγύπτῳ καὶ τοῖς περὶ τὴν Συρίαν τὴν κοίλην καὶ τὴν Φοινίκην τόποις ἀποστάτης αὐτοῦ γέγονεν, οὐ δυνάμενος αὐτὸς κακοπαθεῖν συστήσας τῷ υἱῷ Ναβουχοδονοσόρῳ ὄντι ἐν ἡλικίᾳ μέρη τινὰ τῆς δυνάμεως ἐξέπεμψεν ἐπ’ αὐτόν. συμμίξας δὲ Ναβουχοδονόσορος τῷ ἀποστάτῃ καὶ παραταξάμενος αὐτοῦ τε ἐκράτησε καὶ τὴν χώραν ἐκ ταύτης τῆς ἀρχῆς ὑπὸ τὴν αὐτοῦ βασιλείαν ἐποιήσατο. τῷ τε πατρὶ αὐτοῦ Ναβουχοδονοσόρῳ συνέβη κατ’ αὐτὸν τὸν καιρὸν ἀρρωστήσαντι ἐν τῇ Βαβυλωνίων πόλει μεταλλάξαι τὸν βίον ἔτη βασιλεύσαντα εἴκοσι καὶ ἕν. αἰσθόμενος δὲ μετ’ οὐ πολὺν χρόνον τὴν τοῦ πατρὸς τελευτὴν Ναβουχοδονοσάρου καὶ καταστήσας τὰ κατὰ τὴν Αἴγυπτον πράγματα καὶ τὴν λοιπὴν χώραν καὶ τοὺς αἰχμαλώτους Ἰουδαίων τε καὶ Φοινίκων καὶ Σύρων καὶ τῶν κατ’ Αἴγυπτον ἐθνῶν συντάξας τισὶ τῶν φίλων μετὰ τῆς βαρυτάτης δυνάμεως καὶ τῆς λοιπῆς ὠφελείας ἀνακομίζειν εἰς τὴν Βαβυλωνίαν, αὐτὸς ὁρμήσας ὀλιγοστὸς διὰ τῆς ἐρήμου παραγίνεται εἰς Βαβυλῶνα. παραλαβὼν δὲ τὰ πράγματα διοικούμενα ὑπὸ Χαλδαίων καὶ διατηρουμένην τὴν βασιλείαν ὑπὸ τοῦ βελτίστου αὐτῶν, κυριεύσας ὁλοκλήρου τῆς πατρικῆς ἀρχῆς τοῖς μὲν αἰχμαλώτοις παραγενομένοις συνέταξεν ἀποικίας ἐν τοῖς ἐπιτηδειοτάτοις τῆς Βαβυλωνίας τόποις ἀποδεῖξαι, αὐτὸς δ’ ἀπὸ τῶν ἐκ τοῦ πολέμου λαφύρων τό τε τοῦ Βήλου ἱερὸν καὶ τὰ λοιπὰ κοσμήσας φιλοτίμως τήν τε ὑπάρχουσαν ἐξ ἀρχῆς πόλιν καὶ ἕτερα καταχαρισάμενος καὶ ἀναγκάσας πρὸς τὸ μηκέτι δύνασθαι τοὺς πολιορκοῦντας τὸν ποταμὸν ἀναστρέψαντας ἐπὶ τὴν πόλιν [κατασκευάζειν] περιεβάλετο τρεῖς μὲν τῆς ἔνδον πόλεως περιβόλους, τρεῖς δ’ ἔξω τούτων δὲ τῆς ὀπτῆς πλίνθου. καὶ τειχίσας ἀξιολόγως τὴν πόλιν καὶ τοὺς πυλῶνας κοσμήσας ἱεροπρεπῶς κατεσκεύασεν ἐν τοῖς πατρικοῖς βασιλείοις ἕτερα βασίλεια ἐχόμενα αὐτῶν, ὧν τὸ μὲν ἀνάστημα καὶ τὴν λοιπὴν πολυτέλειαν περισσὸν ἴσως ἂν εἴη λέγειν, πλὴν ὅσον τὰ μεγάλα καὶ ὑπερήφανα συνετελέσθη ἡμέραις πεντεκαίδεκα. [ἐν δὲ] τοῖς βασιλείοις τούτοις ἀναλήμματα λίθινα ἀνῳκοδόμησε τὴν ὄψιν ἀποδοὺς ὁμοιοτάτην τοῖς ὄρεσι, καταφυτεύσας δένδρεσι παντοδαποῖς ἐξειργάσατο καὶ κατεσκεύασε τὸν καλούμενον κρεμαστὸν παράδεισον διὰ τὸ τὴν γυναῖκα αὐτοῦ ἐπιθυμεῖν τῆς οἰκείας διαθέσεως ὡς τεθραμμένην ἐν τοῖς κατὰ Μηδίαν τόποις. καὶ Μεγασθένης δὲ ἐν τῇ τετάρτῃ τῶν Ἰνδικῶν μνημονεύει αὐτῶν δι’ ἧς ἀποφαίνειν πειρᾶται τοῦτον τὸν βασιλέα τῇ ἀνδρείᾳ καὶ τῷ μεγέθει τῶν πράξεων ὑπερβεβηκότα τὸν Ἡρακλέα· καταστρέψασθαι γὰρ αὐτόν φησι Λιβύης τὴν πολλὴν καὶ Ἰβηρίαν. καὶ Διοκλῆς δ’ ἐν τῇ δευτέρᾳ τῶν Περσικῶν μνημονεύει τούτου τοῦ βασιλέως καὶ Φιλόστρατος ἐν ταῖς Ἰνδικαῖς καὶ Φοινικικαῖς ἱστορίαις, ὅτι οὗτος ὁ βασιλεὺς ἐπολιόρκησε τὴν Τύρον ἔτεσι τρισὶ καὶ δέκα βασιλεύοντος κατ’ ἐκεῖνον τὸν καιρὸν Ἰθωβάλου τῆς Τύρου. καὶ τὰ μὲν ὑπὸ πάντων ἱστορούμενα περὶ τούτου τοῦ βασιλέως ταῦτα ἦν.", "st": "10.11.1"}, {"sp": "N", "t": "Μετὰ δὲ τὴν Ναβουχοδονοσόρου τελευτὴν Ἀβιλμαθαδάχος ὁ παῖς αὐτοῦ τὴν βασιλείαν παραλαμβάνει, ὃς εὐθὺς τὸν τῶν Ἱεροσολύμων βασιλέα Ἰεχονίαν τῶν δεσμῶν ἀφεὶς ἐν τοῖς ἀναγκαιοτάτοις τῶν φίλων εἶχε πολλὰς αὐτῷ δωρεὰς δοὺς καὶ ποιήσας αὐτὸν ἐπὶ τῶν ἐν τῇ Βαβυλωνίᾳ βασιλέων· ὁ γὰρ πατὴρ αὐτοῦ τὴν πίστιν οὐκ ἐφύλαξεν Ἰεχονίᾳ παραδόντι μετὰ γυναικῶν καὶ τέκνων καὶ τῆς συγγενείας ὅλης ἑκουσίως αὑτὸν ὑπὲρ τῆς πατρίδος, ὡς ἂν μὴ κατασκαφείη ληφθεῖσα ὑπὸ τῆς πολιορκίας, καθὼς προειρήκαμεν. τελευτήσαντος δὲ Ἀβιλμαθαδάχου μετὰ ἔτη ὀκτωκαίδεκα τῆς βασιλείας Ἠγλίσαρος ὁ παῖς αὐτοῦ τὴν ἀρχὴν παραλαμβάνει, καὶ κατασχὼν αὐτὴν ἔτη τεσσαράκοντα καταστρέφει τὸν βίον. μετὰ δ’ αὐτὸν εἰς τὸν υἱὸν αὐτοῦ Λαβοσόρδαχον ἀφικνεῖται τῆς βασιλείας ἡ διαδοχή, καὶ μῆνας ποιήσασα παρ’ αὐτῷ τοὺς πάντας ἐννέα τελευτήσαντος αὐτοῦ μεταβαίνει πρὸς Βαλτασάρην τὸν καλούμενον Ναβοάνδηλον παρὰ τοῖς Βαβυλωνίοις. ἐπὶ τοῦτον στρατεύουσι Κῦρός τε ὁ Περσῶν βασιλεὺς καὶ Δαρεῖος ὁ Μήδων. καὶ πολιορκουμένων τοὺς ἐν Βαβυλῶνι θαυμάσιόν τι καὶ τεράστιον θέαμα συνέβη· κατέκειτο δειπνῶν καὶ πίνων ἐν οἴκῳ μεγάλῳ καὶ πρὸς ἑστιάσεις πεποιημένῳ βασιλικὰς μετὰ τῶν παλλακίδων καὶ τῶν φίλων. δόξαν δὲ αὐτῷ κομισθῆναι κελεύει ἐκ τοῦ ἰδίου ναοῦ τὰ τοῦ θεοῦ σκεύη, ἃ συλήσας Ναβουχοδονόσορος ἐκ τῶν Ἱεροσολύμων οὐκ ἐχρῆτο μέν, εἰς δὲ τὸν αὑτοῦ ναὸν κατέθηκεν. αὐτὸς δὲ ὑπὸ θράσους προαχθείς, ὥστε αὐτοῖς χρῆσθαι, μεταξὺ πίνων καὶ βλασφημῶν τὸν θεὸν ἐκ τοῦ τείχους ὁρᾷ χεῖρα προϊοῦσαν καὶ τῷ τοίχῳ τινὰς συλλαβὰς ἐγγράφουσαν. ταραχθεὶς δὲ ὑπὸ τῆς ὄψεως συνεκάλεσε τοὺς μάγους καὶ τοὺς Χαλδαίους, πᾶν τοῦτο τὸ γένος ὅσον ἦν ἐν τοῖς Βαβυλωνίοις τά τε σημεῖα καὶ τὰ ὀνείρατα κρίνειν δυνάμενον, ὡς ἂν αὐτῷ δηλώσωσι τὰ γεγραμμένα. τῶν δὲ μάγων οὐδὲν εὑρίσκειν δυναμένων οὐδὲ συνιέναι λεγόντων ὑπ’ ἀγωνίας ὁ βασιλεὺς καὶ πολλῆς τῆς ἐπὶ τῷ παραδόξῳ λύπης κατὰ πᾶσαν ἐκήρυξε τὴν χώραν τῷ τὰ γράμματα καὶ τὴν ὑπ’ αὐτῶν δηλουμένην διάνοιαν σαφῆ ποιήσαντι δώσειν ὑπισχνούμενος στρεπτὸν περιαυχένιον χρύσεον καὶ πορφυρᾶν ἐσθῆτα φορεῖν, ὡς οἱ τῶν Χαλδαίων βασιλεῖς, καὶ τὸ τρίτον μέρος τῆς ἰδίας ἀρχῆς. τούτου γενομένου τοῦ κηρύγματος ἔτι μᾶλλον οἱ μάγοι συνδραμόντες καὶ φιλοτιμησάμενοι πρὸς τὴν εὕρεσιν τῶν γραμμάτων οὐδὲν ἔλαττον ἠπόρησαν. ἀθυμοῦντα δ’ ἐπὶ τούτῳ θεασαμένη τὸν βασιλέα ἡ μάμμη αὐτοῦ παραθαρσύνειν ἤρξατο καὶ λέγειν, ὡς ἔστι τις ἀπὸ τῆς Ἰουδαίας αἰχμάλωτος ἐκεῖθεν τὸ γένος ἀχθεὶς ὑπὸ τοῦ Ναβουχοδονοσόρου πορθήσαντος Ἱεροσόλυμα Δανίηλος ὄνομα, σοφὸς ἀνὴρ καὶ δεινὸς εὑρεῖν τὰ ἀμήχανα καὶ μόνῳ τῷ θεῷ γνώριμα, ὃς Ναβουχοδονοσόρῳ τῷ βασιλεῖ μηδενὸς ἄλλου δυνηθέντος εἰπεῖν περὶ ὧν ἔχρῃζεν εἰς φῶς ἤγαγε τὰ ζητούμενα. μεταπεμψάμενον οὖν αὐτὸν ἠξίου παρ’ αὐτοῦ πυνθάνεσθαι περὶ τῶν γραμμάτων καὶ τὴν ἀμαθίαν τὴν τῶν οὐχ εὑρόντων αὐτὰ κατακρίνειν, κἂν σκυθρωπὸν ᾖ τὸ ὑπὸ τοῦ θεοῦ σημαινόμενον.", "st": "10.11.2"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας καλεῖ τὸν Δανίηλον ὁ Βαλτασάρης καὶ διαλεχθεὶς ὡς πύθοιτο περὶ αὐτοῦ καὶ τῆς σοφίας, ὅτι θεῖον αὐτῷ πνεῦμα συμπάρεστι καὶ μόνος ἐξευρεῖν ἱκανώτατος ἃ μὴ τοῖς ἄλλοις εἰς ἐπίνοιαν ἔρχεται, φράζειν αὐτῷ τὰ γεγραμμένα καὶ τί σημαίνει μηνύειν ἠξίου· τοῦτο γὰρ ποιήσαντι πορφύραν δώσειν ἐνδεδύσθαι καὶ χρύσεον περὶ αὐχένα στρεπτὸν καὶ τὸ τρίτον τῆς ἀρχῆς αὐτοῦ μέρος τιμὴν καὶ γέρας τῆς σοφίας, ὡς ἂν ἐξ αὐτῶν ἐπισημότατος γένοιτο τοῖς ὁρῶσι καὶ τὴν αἰτίαν ἐφ’ ᾗ τούτων ἔτυχε πυνθανομένοις. Δανίηλος δὲ τὰς μὲν δωρεὰς αὐτὸν ἔχειν ἠξίου· τὸ γὰρ σοφὸν καὶ θεῖον ἀδωροδόκητον εἶναι καὶ προῖκα τοὺς δεομένους ὠφελεῖν, μηνύσειν δ’ αὐτῷ τὰ γεγραμμένα σημαίνοντα καταστροφὴν αὐτῷ τοῦ βίου, ὅτι μηδ’ οἷς ὁ πρόγονος αὐτοῦ διὰ τὰς εἰς θεὸν ὕβρεις ἐκολάσθη τούτοις ἔμαθεν εὐσεβεῖν καὶ μηδὲν ὑπὲρ τὴν ἀνθρωπίνην φύσιν μηχανᾶσθαι· ἀλλὰ καὶ Ναβουχοδονοσόρου μεταστάντος εἰς δίαιταν θηρίων ἐφ’ οἷς ἠσέβησε καὶ μετὰ πολλὰς ἱκεσίας καὶ δεήσεις ἐλεηθέντος ἐπανελθεῖν εἰς τὸν ἀνθρώπινον βίον καὶ τὴν βασιλείαν, καὶ διὰ ταῦτα τὸν θεὸν ὡς τὴν ἅπασαν ἔχοντα δύναμιν καὶ προνοούμενον τῶν ἀνθρώπων μέχρις οὗ καὶ ἐτελεύτησεν ὑμνοῦντος, λήθην αὐτὸς ἔλαβε τούτων καὶ πολλὰ μὲν ἐβλασφήμησε τὸ θεῖον, τοῖς δὲ σκεύεσιν αὐτοῦ μετὰ τῶν παλλακίδων διηκονεῖτο. ταῦτα ὁρῶντα τὸν θεὸν ὀργισθῆναι αὐτῷ καὶ διὰ τῶν γεγραμμένων προκαταγγέλλειν, εἰς οἷον αὐτὸν καταστρέψαι δεῖ τέλος. ἐδήλου δὲ τὰ γράμματα τάδε· μάνη· τούτῳ δὲ ἔλεγεν Ἑλλάδι γλώσσῃ σημαίνοιτο ἂν ἀριθμός, ὥσπερ τῆς ζωῆς σου τὸν χρόνον καὶ τῆς ἀρχῆς ἠρίθμηκεν ὁ θεὸς [καὶ] περισσεύειν ἔτι σοι βραχὺν χρόνον. θέκελ· σημαίνει τοῦτο τὸν σταθμόν· στήσας οὖν σου λέγει τὸν χρόνον τῆς βασιλείας ὁ θεὸς ἤδη καταφερομένην δηλοῖ. φαρές· καὶ τοῦτο κλάσμα δηλοῖ καθ’ Ἑλλάδα γλῶτταν· κλάσει τοιγαροῦν σου τὴν βασιλείαν καὶ Μήδοις αὐτὴν καὶ Πέρσαις διανεμεῖ.", "st": "10.11.3"}, {"sp": "N", "t": "Δανιήλου δὲ ταῦτα τῷ βασιλεῖ σημαίνειν φράσαντος τὰ ἐν τῷ τοίχῳ γράμματα τὸν μὲν Βαλτασάρην, οἷον εἰκὸς ἐφ’ οὕτω χαλεποῖς τοῖς δεδηλωμένοις, λύπη καὶ συμφορὰ κατέλαβεν· οὐ μὴν ὡς προφήτῃ αὐτῷ κακῶν γενομένῳ τὰς δωρεὰς ἃς ὑπέσχετο δώσειν οὐ δίδωσιν, ἀλλὰ πάσας παρέσχε, τὸ μὲν ἐφ’ οἷς δοθήσονται λογιζόμενος ἴδιον αὐτοῦ καὶ τῆς ἀνάγκης, ἀλλ’ οὐχὶ τοῦ προφητεύσαντος εἶναι, τὰ δὲ ὡμολογημένα κρίνων ἀνδρὸς ἀγαθοῦ καὶ δικαίου, κἂν ᾖ σκυθρωπὰ τὰ μέλλοντα συμβαίνειν οὕτως ἔκρινε· μετ’ οὐ πολὺν δὲ χρόνον αὐτός τε ἐλήφθη καὶ ἡ πόλις Κύρου τοῦ Περσῶν βασιλέως ἐπ’ αὐτὸν στρατεύσαντος· Βαλτάσαρος γάρ ἐστιν, ἐφ’ οὗ τὴν αἵρεσιν τῆς Βαβυλῶνος συνέβη γενέσθαι, βασιλεύσαντος αὐτοῦ ἑπτακαίδεκα ἔτη. τῶν μὲν οὖν Ναβουχοδονοσόρου τοῦ βασιλέως ἐγγόνων τὸ τέλος τοιοῦτον παρειλήφαμεν γενόμενον· Δαρείῳ δὲ τῷ καταλύσαντι τὴν Βαβυλωνίων ἡγεμονίαν μετὰ Κύρου τοῦ συγγενοῦς ἔτος ἦν ἑξηκοστὸν καὶ δεύτερον, ὅτε τὴν Βαβυλῶνα εἷλεν, ὃς ἦν Ἀστυάγους υἱός, ἕτερον δὲ παρὰ τοῖς Ἕλλησιν ἐκαλεῖτο ὄνομα· ὃς καὶ Δανίηλον τὸν προφήτην λαβὼν ἤγαγεν εἰς Μηδίαν πρὸς αὑτὸν καὶ πάσης αὐτῷ τιμῆς μεταδιδοὺς εἶχε σὺν αὑτῷ· τῶν τριῶν γὰρ σατραπῶν ἦν, οὓς ἐπὶ τῶν ἑξήκοντα καὶ τριακοσίων σατραπειῶν κατέστησε· τοσούτους γὰρ ἐποίησε Δαρεῖος εἰς αὐτήν.", "st": "10.11.4"}, {"sp": "N", "t": "Δανίηλος τοίνυν ὢν ἐν τοιαύτῃ τιμῇ καὶ λαμπρᾷ σπουδῇ παρὰ τῷ Δαρείῳ καὶ πρὸς ἅπαντα ὑπ’ αὐτοῦ μόνος, ὡς ἂν ἔχων τὸ θεῖον πεπιστευμένος ἐν αὑτῷ, παραλαμβανόμενος ἐφθονήθη· βασκαίνουσι γὰρ οἱ μᾶλλον αὐτῶν ἑτέρους ἐν πλείονι τιμῇ παρὰ τοῖς βασιλεῦσι βλέποντες. ζητούντων δ’ ἐπ’ αὐτὸν ἀφορμὴν διαβολῆς καὶ κατηγορίας τῶν ἀχθομένων ἐπ’ αὐτῷ εὐδοκιμοῦντι παρὰ τῷ Δαρείῳ παρεῖχεν αἰτίαν οὐδεμίαν· ὢν γὰρ καὶ χρημάτων ἐπάνω καὶ παντὸς λήμματος περιορῶν, αἴσχιστον αὐτῷ δοκεῖν κἂν ὑπὲρ ὧν δοθείη καλῶς πρὸς τὸ λαβεῖν, οὐδ’ ἡντιναοῦν τοῖς ζηλοτυποῦσιν αὐτὸν ἐγκλημάτων εὕρεσιν παρεῖχεν. οἱ δ’ ὡς οὐδὲν εἶχον, ὃ κατειπόντες αὐτοῦ πρὸς τὸν βασιλέα ζημιώσουσιν αὐτὸν εἰς τὴν παρ’ αὐτοῦ τιμὴν αἰσχύνῃ καὶ διαβολῇ, τρόπον ἄλλον ἐζήτουν καθ’ ὃν αὐτὸν ἐκποδὼν ποιήσονται. ὁρῶντες οὖν τὸν Δανίηλον τρὶς τῆς ἡμέρας προσευχόμενον τῷ θεῷ πρόφασιν ἔγνωσαν εὑρηκέναι, δι’ ἧς ἀπολέσουσιν αὐτόν. καὶ πρὸς τὸν Δαρεῖον ἐλθόντες ἀπήγγελλον αὐτῷ, ὡς τοῖς σατράπαις αὐτοῦ καὶ τοῖς ἡγεμόσι δόξειεν ἐπὶ τριάκονθ’ ἡμέρας ἀνεῖναι τὸ πλῆθος, ὅπως μήτ’ αὐτῷ τις μήτε τοῖς θεοῖς δεόμενος αὐτῶν καὶ εὐχόμενος εἴη, τὸν μέντοι γε αὐτῶν παραβάντα ταύτην τὴν γνώμην εἰς τὸν τῶν λεόντων ἔκριναν ῥῖψαι λάκκον ἀπολούμενον.", "st": "10.11.5"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς οὐ συνιδὼν τὴν κακουργίαν οὐδ’ ἐπὶ τὸν Δανίηλον ταῦτα κατεσκευασμένους ὑπονοήσας ἀρέσκεσθαι τοῖς ὑπ’ αὐτῶν ἔφη δεδογμένοις, καὶ κυρώσειν τὴν προαίρεσιν αὐτῶν ἐπαγγελλόμενος προτίθησι πρόγραμμα δηλοῦν τῷ πλήθει τὰ δόξαντα τοῖς σατράπαις. καὶ οἱ μὲν ἄλλοι πάντες φυλαττόμενοι τὰ προστεταγμένα μὴ παραβῆναι ἠρέμουν, Δανιήλῳ δὲ φροντὶς οὐδ’ ἡτισοῦν τούτων ἦν, ἀλλ’ ὡς ἔθος εἶχεν ἱστάμενος ηὔχετο τῷ θεῷ πάντων ὁρώντων. οἱ δὲ σατράπαι τῆς ἀφορμῆς αὐτοῖς ἣν ἐσπούδαζον λαβεῖν ἐπὶ τὸν Δανίηλον παραφανείσης εὐθὺς ἧκον πρὸς τὸν βασιλέα καὶ κατηγόρουν ὡς παραβαίνοντος μόνου τοῦ Δανιήλου τὰ προστεταγμένα· μηδενὸς γὰρ τῶν ἄλλων τολμῶντος προσεύχεσθαι τοῖς θεοῖς, καὶ τοῦτ’ οὐ δι’ ἀσέβειαν, ἀλλὰ διὰ φυλακὴν καὶ διατήρησιν ὑπὸ τοῦ φθόνου· ἀπὸ γὰρ μείζονος ἧς προσεδόκων εὐνοίας τοῦτο ποιεῖν τὸν Δαρεῖον ὑπολαμβάνοντες, ὡς καὶ καταφρονήσαντι τῶν ἐκείνου προσταγμάτων συγγνώμην ἑτοίμως νέμειν, καὶ αὐτὸ τοῦτο βασκαίνοντες τῷ Δανιήλῳ, οὔτε μετεβάλλοντο πρὸς τὸ ἡμερώτερον, ῥίπτειν δ’ αὐτὸν ἠξίουν κατὰ τὸν νόμον εἰς τὸν λάκκον τῶν λεόντων. ἐλπίσας δ’ ὁ Δαρεῖος, ὅτι ῥύσεται τὸ θεῖον αὐτὸν καὶ οὐδὲν μὴ πάθῃ δεινὸν ὑπὸ τῶν θηρίων, ἐκέλευσεν αὐτῷ εὐθύμως φέρειν τὰ συμβαίνοντα· καὶ βληθέντος εἰς τὸν λάκκον σφραγίσας τὸν ἐπὶ τοῦ στομίου κείμενον ἀντὶ θύρας λίθον ἀνεχώρησε, δι’ ὅλης δ’ ἄσιτος τῆς νυκτὸς καὶ ἄυπνος διῆγεν ἀγωνιῶν περὶ τοῦ Δανιήλου· μεθ’ ἡμέραν δὲ ἀναστὰς ἐπὶ τὸν λάκκον ἦλθε καὶ σωζομένην τὴν σφραγῖδα εὑρών, ᾗ σημηνάμενος τὸν λίθον κατελελοίπει, ἀνοίξας ἀνεβόησε καλῶν τὸν Δανίηλον καὶ πυνθανόμενος εἰ σώζεται. τοῦ δὲ ἐπακούσαντος τῷ βασιλεῖ καὶ μηδὲν παθεῖν εἰπόντος, ἐκέλευσεν αὐτὸν ἀνελκυσθῆναι ἐκ τοῦ λάκκου τοῦ τῶν θηρίων. οἱ δὲ ἐχθροὶ θεασάμενοι τὸν Δανίηλον μηδὲν πεπονθότα δεινὸν διὰ μὲν τὸ θεῖον καὶ τὴν τούτου πρόνοιαν οὐκ ἠξίουν αὐτὸν σώζεσθαι, πεπληρωμένους δὲ τοὺς λέοντας τροφῆς μὴ ἅψασθαι μηδὲ προσελθεῖν τῷ Δανιήλῳ νομίζοντες τοῦτο ἔλεγον πρὸς τὸν βασιλέα. ὁ δὲ μισήσας αὐτοὺς τῆς πονηρίας παραβληθῆναι μὲν πολλὰ κελεύει τοῖς λέουσι κρέα, κορεσθέντων δ’ αὐτῶν τοὺς ἐχθροὺς τοῦ Δανιήλου προσέταξεν εἰς τὸν λάκκον βληθῆναι, ὅπως εἰ διὰ κόρον αὐτοῖς οὐ προσήξουσιν οἱ λέοντες μάθοι. σαφὲς δ’ ἐγένετο τῷ Δαρείῳ τῶν σατραπῶν παραβληθέντων τοῖς θηρίοις, ὅτι τὸ θεῖον ἔσωσε τὸν Δανίηλον· οὐδενὸς γὰρ αὐτῶν ἐφείσαντο οἱ λέοντες, ἀλλὰ πάντας διεσπάραττον ὡσανεὶ σφόδρα λιμώττοντες καὶ τροφῆς ἐνδεεῖς. ἠρέθισε δ’ αὐτοὺς οὐ τὸ πεινῆν οἶμαι μικρὸν ἔμπροσθεν ἀφθόνων κρεῶν πεπληρωμένους, ἀλλ’ ἡ τῶν ἀνθρώπων κακία, δήλη γὰρ καὶ τοῖς ἀλόγοις ζῴοις ἦν αὕτη, πρὸς τιμωρίαν ἣ γένοιτο τοῦ θεοῦ προαιρουμένου.", "st": "10.11.6"}, {"sp": "N", "t": "Διαφθαρέντων οὖν τῶν ἐπιβουλευσάντων Δανιήλῳ τοῦτον τὸν τρόπον ὁ βασιλεὺς Δαρεῖος καθ’ ὅλην ἔπεμψε τὴν χώραν ἐπαινῶν τὸν θεόν, ὃν Δανίηλος προσκυνεῖ, καὶ μόνον αὐτὸν εἶναι ἔλεγεν ἀληθῆ καὶ τὸ πάντων κράτος ἔχοντα· ἔσχε δὲ καὶ τὸν Δανίηλον ἐν ὑπερβαλλούσῃ τιμῇ πρῶτον αὐτὸν ἀποδείξας τῶν φίλων. ὢν δὲ οὕτως ἐπίσημος καὶ λαμπρὸς ἐπὶ δόξῃ τοῦ θεοφιλὴς εἶναι Δανίηλος ᾠκοδόμησεν ἐν Ἐκβατάνοις τῆς Μηδικῆς βάριν εὐπρεπέστατόν τι κατασκεύασμα καὶ θαυμασίως πεποιημένον, ἣ μέχρι δεῦρο μὲν ἔστι καὶ σώζεται, τοῖς δ’ ὁρῶσι δοκεῖ προσφάτως κατεσκευάσθαι καὶ ἐπ’ αὐτῆς ἐκείνης ἧς ἕκαστος αὐτὴν ἡμέρας ἱστορεῖ γεγονέναι· οὕτως νεαρὸν αὐτῆς καὶ ἀκμαῖον τὸ κάλλος καὶ μηδαμοῦ γεγηρακὸς ὑπὸ τοσούτου χρόνου· πάσχει γὰρ καὶ τὰ κατασκευάσματα ταὐτὸν ἀνθρώποις καὶ πολιοῦται καὶ τὴν ἰσχὺν λυόμενα ὑπὸ τῶν ἐτῶν καὶ τὴν εὐπρέπειαν μαραινόμενα. θάπτουσι δ’ ἐν τῇ βάρει τούς τε Μήδων βασιλέας καὶ Περσῶν καὶ Πάρθων ἄχρι τοῦ δεῦρο, καὶ ὁ ταύτην πεπιστευμένος Ἰουδαῖός ἐστιν ἱερεὺς καὶ τοῦτο γίνεται μέχρι τῆς σήμερον ἡμέρας. ἄξιον δὲ τἀνδρὸς τούτου καὶ ὃ μάλιστ’ ἂν θαυμάσαι τις ἀκούσας διελθεῖν· ἀπαντᾷ γὰρ αὐτῷ παραδόξως ὡς ἑνί τινι τῶν μεγίστων καὶ παρὰ τὸν τῆς ζωῆς χρόνον τιμή τε καὶ δόξα ἡ παρὰ τῶν βασιλέων καὶ τοῦ πλήθους, καὶ τελευτήσας δὲ μνήμην αἰώνιον ἔχει. τὰ γὰρ βιβλία, ὅσα δὴ συγγραψάμενος καταλέλοιπεν, ἀναγινώσκεται παρ’ ἡμῖν ἔτι καὶ νῦν καὶ πεπιστεύκαμεν ἐξ αὐτῶν, ὅτι Δανίηλος ὡμίλει τῷ θεῷ· οὐ γὰρ τὰ μέλλοντα μόνον προφητεύων διετέλει, καθάπερ καὶ οἱ ἄλλοι προφῆται, ἀλλὰ καὶ καιρὸν ὥριζεν, εἰς ὃν ταῦτα ἀποβήσεται· καὶ τῶν προφητῶν τὰ χείρω προλεγόντων καὶ διὰ τοῦτο δυσχεραινομένων ὑπὸ τῶν βασιλέων καὶ τοῦ πλήθους Δανίηλος ἀγαθῶν ἐγίνετο προφήτης αὐτοῖς, ὡς ἀπὸ μὲν τῆς εὐφημίας τῶν προλεγομένων εὔνοιαν ἐπισπᾶσθαι παρὰ πάντων, ἀπὸ δὲ τοῦ τέλους αὐτῶν ἀληθείας πίστιν καὶ δόξαν ὁμοῦ θειότητος παρὰ τοῖς ὄχλοις ἀποφέρεσθαι. κατέλιπε δὲ γράψας, ὅθεν ἡμῖν ἀληθὲς τὸ τῆς προφητείας αὐτοῦ ἀκριβὲς καὶ ἀπαράλλακτον ἐποίησε δῆλον· φησὶ γὰρ αὐτὸν γενόμενον ἐν Σούσοις ἐν τῇ μητροπόλει τῆς Περσίδος, ὡς ἐξῆλθεν εἰς τὸ πεδίον μετὰ ἑταίρων αὐτοῦ, σεισμοῦ καὶ κλόνου τῆς γῆς ἐξαίφνης γενομένου καταλειφθείη μόνος φευγόντων τῶν φίλων καὶ πέσοι μὲν ἐπὶ στόμα ταραχθεὶς ἐπὶ τὰς δύο χεῖρας, τινὸς δ’ ἁψαμένου αὐτοῦ καὶ μεταξὺ κελεύοντος ἀναστῆναι καὶ τὰ μέλλοντα συμβήσεσθαι τοῖς πολίταις ἰδεῖν μετὰ πολλὰς γενεάς. ἀναστάντι δ’ αὐτῷ δειχθῆναι κριὸν ἐσήμαινε μέγαν, πολλὰ μὲν ἐκπεφυκότα κέρατα, τελευταῖον δ’ αὐτῶν ὑψηλότερον ἔχοντα. ἔπειτ’ ἀναβλέψαι μὲν εἰς τὴν δύσιν, θεάσασθαι δὲ τράγον ἀπ’ αὐτῆς δι’ ἀέρος φερόμενον συρράξαντα τῷ κριῷ καὶ τοῖς κέρασι ῥήξαντα δὶς καταβαλεῖν αὐτὸν ἐπὶ τὴν γῆν καὶ πατῆσαι. εἶτα τὸν τράγον ἰδεῖν ἐκ τοῦ μετώπου μέγιστον ἀναφύσαντα κέρας, οὗ κλασθέντος ἀναβλαστῆσαι τέσσαρα καθ’ ἕκαστον τῶν ἀνέμων τετραμμένα. ἐξ αὐτῶν δ’ ἀνασχεῖν καὶ ἄλλο μικρότερον ἀνέγραψεν, ὃ αὐξῆσαν ἔλεγεν αὐτῷ ὁ ταῦτα ἐπιδεικνὺς θεὸς πολεμήσειν αὐτοῦ τὸ ἔθνος καὶ τὴν πόλιν ἀναιρήσειν κατὰ κράτος, καὶ συγχεεῖν τὰ περὶ τὸν ναὸν καὶ τὰς θυσίας κωλύσειν γενέσθαι ἐπὶ ἡμέρας χιλίας διακοσίας ἐνενήκοντα ἕξ. ταῦτα μὲν ἰδεῖν ἐν τῷ πεδίῳ τῷ ἐν Σούσοις ὁ Δανίηλος ἔγραψε, κρῖναι δ’ αὐτὸν τὴν ὄψιν τοῦ φαντάσματος ἐδήλου τὸν θεὸν οὕτως· τὸν μὲν κριὸν βασιλείας τὰς Μήδων καὶ Περσῶν σημαίνειν ἔφασκε, τὰ δὲ κέρατα τοὺς βασιλεύειν μέλλοντας, τὸ δὲ ἔσχατον κέρας σημαίνειν τὸν ἔσχατον βασιλέα· τοῦτον γὰρ διοίσειν ἁπάντων πλούτῳ τε καὶ δόξῃ. τὸν δὲ τράγον δηλοῦν, ὡς ἐκ τῶν Ἑλλήνων τις βασιλεύων ἔσται, ὃς τῷ Πέρσῃ συμβαλὼν δὶς κρατήσει τῇ μάχῃ καὶ παραλήψεται τὴν ἡγεμονίαν ἅπασαν. δηλοῦσθαι δ’ ὑπὸ τοῦ μεγάλου κέρατος τοῦ ἐν τῷ μετώπῳ τοῦ τράγου τὸν πρῶτον βασιλέα καὶ τὴν τῶν τεσσάρων ἀναβλάστησιν ἐκπεσόντος ἐκείνου καὶ τὴν πρὸς τὰ τέσσαρα κλίματα τῆς γῆς αὐτῶν ἀποστροφὴν ἑκάστου τοὺς διαδόχους μετὰ τὸν θάνατον τοῦ πρώτου βασιλέως ἐμφανίζεσθαι καὶ διαμερισμὸν εἰς αὐτοὺς τῆς βασιλείας, οὔτε δὲ παῖδας αὐτοῦ τούτους ὄντας οὔτε συγγενεῖς, πολλοῖς ἔτεσιν ἄρξειν τῆς οἰκουμένης. γενήσεσθαι δ’ ἐκ τούτων τινὰ βασιλέα τὸν ἐκπολεμήσοντα τό τε ἔθνος καὶ τοὺς νόμους αὐτῶν καὶ τὴν κατὰ τούτους ἀφαιρησόμενον πολιτείαν καὶ συλήσοντα τὸν ναὸν καὶ τὰς θυσίας ἐπ’ ἔτη τρία κωλύσοντα ἐπιτελεσθῆναι. καὶ δὴ ταῦτα ἡμῶν συνέβη παθεῖν τῷ ἔθνει ὑπὸ Ἀντιόχου τοῦ Ἐπιφανοῦς, καθὼς εἶδεν ὁ Δανίηλος καὶ πολλοῖς ἔτεσιν ἔμπροσθεν ἀνέγραψε τὰ γενησόμενα. τὸν αὐτὸν δὲ τρόπον ὁ Δανίηλος καὶ περὶ τῆς Ῥωμαίων ἡγεμονίας ἀνέγραψε, καὶ ὅτι ὑπ’ αὐτῶν ἐρημωθήσεται. ταῦτα πάντα ἐκεῖνος θεοῦ δείξαντος αὐτῷ συγγράψας κατέλειψεν· ὥστε τοὺς ἀναγινώσκοντας καὶ τὰ συμβαίνοντα σκοποῦντας θαυμάζειν ἐπὶ τῇ παρὰ θεοῦ τιμῇ τὸν Δανίηλον καὶ τοὺς Ἐπικουρείους ἐκ τούτων εὑρίσκειν πεπλανημένους, οἳ τήν τε πρόνοιαν ἐκβάλλουσι τοῦ βίου καὶ θεὸν οὐκ ἀξιοῦσιν ἐπιτροπεύειν τῶν πραγμάτων, οὐδ’ ὑπὸ τῆς μακαρίας καὶ ἀφθάρτου πρὸς διαμονὴν τῶν ὅλων οὐσίας κυβερνᾶσθαι τὰ σύμπαντα, ἄμοιρον δὲ ἡνιόχου καὶ ἀφρόντιστον τὸν κόσμον αὐτομάτως φέρεσθαι λέγουσιν. ὃς εἰ τοῦτον ἀπροστάτητος ἦν τὸν τρόπον, καθάπερ καὶ τὰς ναῦς ἐρήμους κυβερνητῶν καταδυομένας ὁρῶμεν ὑπὸ πνευμάτων ἢ καὶ τὰ ἅρματα περιτρεπόμενα μὴ ἔχοντα τοὺς ἡνιοχοῦντας, συντριβεὶς ἂν ὑπὸ τῆς ἀπρονοήτου συμφορᾶς ἀπωλώλει καὶ διεφθείρετο. τοῖς οὖν προειρημένοις ὑπὸ Δανιήλου δοκοῦσί μοι σφόδρα τῆς ἀληθοῦς δόξης διαμαρτάνειν οἱ τῷ θεῷ μηδεμίαν εἶναι περὶ τῶν ἀνθρωπίνων ἀποφαινόμενοι πρόνοιαν· οὐ γὰρ ἂν κατὰ τὴν ἐκείνου προφητείαν, εἰ συνέβαινεν αὐτοματισμῷ τινι τὸν κόσμον διάγειν, πάντα ἑωρῶμεν ἀποβαίνοντα. ἐγὼ μὲν περὶ τούτων ὡς εὗρον καὶ ἀνέγνων οὕτως ἔγραψα· εἰ δέ τις ἄλλως δοξάζειν βουλήσεται περὶ αὐτῶν, ἀνέγκλητον ἐχέτω τὴν ἑτερογνωμοσύνην.", "st": "10.11.7"}, {"sp": "HDR", "t": "Βιβλίον ΙΑʹ", "st": "11"}, {"sp": "N", "t": "Τῷ δὲ πρώτῳ τῆς Κύρου βασιλείας ἔτει, τοῦτο δ’ ἦν ἑβδομηκοστὸν ἀφ’ ἧς ἡμέρας μεταναστῆναι τὸν λαὸν ἡμῶν ἐκ τῆς οἰκείας εἰς Βαβυλῶνα συνέπεσεν, ἠλέησεν ὁ θεὸς τὴν αἰχμαλωσίαν καὶ τὴν συμφορὰν ἐκείνων τῶν ταλαιπώρων, καὶ καθὼς προεῖπεν αὐτοῖς διὰ Ἱερεμίου τοῦ προφήτου πρὶν ἢ κατασκαφῆναι τὴν πόλιν, ὡς μετὰ τὸ δουλεῦσαι Ναβουχοδονοσόρῳ καὶ τοῖς ἐκγόνοις αὐτοῦ καὶ ταύτην ὑπομεῖναι τὴν δουλείαν ἐπὶ ἔτη ἑβδομήκοντα πάλιν αὐτοὺς εἰς τὴν πάτριον ἀποκαταστήσει γῆν καὶ τὸν ναὸν οἰκοδομήσουσι καὶ τῆς ἀρχαίας ἀπολαύσουσιν εὐδαιμονίας, ταῦτ’ αὐτοῖς παρέσχεν. παρορμήσας γὰρ τὴν Κύρου ψυχὴν ἐποίησεν αὐτὸν γράψαι κατὰ πᾶσαν τὴν Ἀσίαν, ὅτι Κῦρος ὁ βασιλεὺς λέγει· ἐπεί με ὁ θεὸς ὁ μέγιστος τῆς οἰκουμένης ἀπέδειξε βασιλέα, πείθομαι τοῦτον εἶναι, ὃν τὸ τῶν Ἰσραηλιτῶν ἔθνος προσκυνεῖ. καὶ γὰρ τοὐμὸν προεῖπεν ὄνομα διὰ τῶν προφητῶν, καὶ ὅτι τὸν ναὸν αὐτοῦ οἰκοδομήσω ἐν Ἱεροσολύμοις ἐν τῇ Ἰουδαίᾳ χώρᾳ.", "st": "11.1.1"}, {"sp": "N", "t": "Ταῦτα δ’ ἔγνω Κῦρος ἀναγινώσκων τὸ βιβλίον, ὃ τῆς αὐτοῦ προφητείας ὁ Ἡσαΐας κατέλιπεν πρὸ ἐτῶν διακοσίων καὶ δέκα· οὗτος γὰρ ἐν ἀπορρήτῳ εἶπε ταῦτα λέγειν τὸν θεόν, ὅτι βούλομαι Κῦρον ἐγὼ πολλῶν ἐθνῶν καὶ μεγάλων ἀποδείξας βασιλέα πέμψαι μου τὸν λαὸν εἰς τὴν ἰδίαν γῆν καὶ οἰκοδομῆσαί μου τὸν ναόν. ταῦτα Ἡσαΐας προεφήτευσεν ἔμπροσθεν ἢ κατασκαφῆναι τὸν ναὸν ἔτεσιν ἑκατὸν καὶ τεσσαράκοντα. ταῦτ’ οὖν ἀναγνόντα τὸν Κῦρον καὶ θαυμάσαντα τὸ θεῖον ὁρμή τις ἔλαβεν καὶ φιλοτιμία ποιῆσαι τὰ γεγραμμένα, καὶ καλέσας τοὺς ἐπιφανεστάτους τῶν ἐν Βαβυλῶνι Ἰουδαίων συγχωρεῖν αὐτοῖς ἔφη βαδίζειν εἰς τὴν αὐτῶν πατρίδα καὶ ἀναστῆσαί τε τὴν πόλιν Ἱεροσόλυμα καὶ τὸν τοῦ θεοῦ ναόν· ἔσεσθαι γὰρ αὐτοῖς καὶ τοῦτον σύμμαχον αὐτόν τε γράψειν τοῖς γειτονεύουσιν ἐκείνῃ τῇ χώρᾳ τῶν ἰδίων ἡγεμόνων καὶ σατραπῶν, ἵνα συμβάλωνται χρυσὸν αὐτοῖς καὶ ἄργυρον εἰς τὴν οἰκοδομίαν τοῦ ναοῦ καὶ πρὸς τούτοις θρέμματα πρὸς τὰς θυσίας.", "st": "11.1.2"}, {"sp": "N", "t": "Ταῦτα Κύρου καταγγείλαντος τοῖς Ἰσραηλίταις ἐξώρμησαν οἱ τῶν δύο φυλῶν ἄρχοντες τῆς Ἰούδα καὶ Βενιαμίτιδος οἵ τε Λευῖται καὶ οἱ ἱερεῖς εἰς τὰ Ἱεροσόλυμα. πολλοὶ γὰρ κατέμειναν ἐν τῇ Βαβυλῶνι τὰ κτήματα καταλιπεῖν οὐ θέλοντες. καὶ παραγενομένοις αὐτοῖς οἱ τοῦ βασιλέως φίλοι πάντες ἐβοήθουν καὶ συνεισέφερον εἰς τὴν τοῦ ναοῦ κατασκευὴν οἱ μὲν χρυσὸν οἱ δ’ ἄργυρον οἱ δὲ βοσκημάτων πλῆθος σὺν ἵπποις. καὶ τάς τε εὐχὰς ἀπεδίδοσαν τῷ θεῷ καὶ τὰς νομιζομένας κατὰ τὸ παλαιὸν θυσίας ἐπετέλουν, ὥσπερ ἀνακτιζομένης αὐτοῖς τῆς πόλεως καὶ ἀναβιούσης τῆς ἀρχαίας περὶ τὴν θρησκείαν συνηθείας. ἀπέπεμψε δ’ αὐτοῖς Κῦρος καὶ τὰ σκεύη τοῦ θεοῦ, ἃ συλήσας τὸν ναὸν ὁ βασιλεὺς Ναβουχοδονόσορος εἰς τὴν Βαβυλῶνα ἐκόμισεν. παρέδωκεν δὲ ταῦτα φέρειν Μιθριδάτῃ τῷ γαζοφύλακι αὐτοῦ προστάξας δοῦναι αὐτὰ Ἀβεσσάρῳ, ὅπως φυλάττῃ μέχρι τῆς οἰκοδομίας τοῦ ναοῦ, τελεσθέντος δὲ αὐτοῦ παραδῷ τοῖς ἱερεῦσιν καὶ ἄρχουσιν τοῦ πλήθους εἰς τὸν ναὸν ἀποθησομένοις. πέμπει δὲ καὶ ἐπιστολὴν πρὸς τοὺς ἐν Συρίᾳ σατράπας Κῦρος τάδε λέγουσαν· βασιλεὺς Κῦρος Σισίνῃ καὶ Σαραβασάνῃ χαίρειν. Ἰουδαίων τῶν ἐν τῇ ἐμῇ χώρᾳ κατοικούντων ἐπέτρεψα τοῖς βουλομένοις εἰς τὴν ἰδίαν ἀπελθοῦσι πατρίδα τήν τε πόλιν ἀνακτίζειν καὶ τὸν ναὸν οἰκοδομῆσαι τὸν ἐν Ἱεροσολύμοις τοῦ θεοῦ ἐπὶ τοῦ αὐτοῦ τόπου, ἐφ’ οὗ καὶ πρότερον. κατέπεμψα δέ μου καὶ τὸν γαζοφύλακα Μιθριδάτην καὶ Ζοροβάβηλον τὸν ἄρχοντα τῶν Ἰουδαίων, ἵνα θεμελίους βάλωνται τοῦ ναοῦ καὶ οἰκοδομήσωσιν αὐτὸν ὕψος μὲν ἑξήκοντα πηχῶν τῶν δ’ αὐτῶν καὶ τὸ εὖρος, λίθου μὲν ξεστοῦ τρεῖς ποιησάμενοι δόμους καὶ ἕνα ξύλινον ἐγχώριον, ὁμοίως δὲ καὶ θυσιαστήριον, ἐφ’ οὗ θύσουσιν τῷ θεῷ. τὴν δὲ εἰς ταῦτα δαπάνην ἐκ τῶν ἐμαυτοῦ γενέσθαι βούλομαι. καὶ τὰ σκεύη δέ, ἃ ἐσύλησεν ἐκ τοῦ ναοῦ Ναβουχοδονόσορος ὁ βασιλεύς, ἔπεμψα παραδοὺς Μιθριδάτῃ τῷ γαζοφύλακι καὶ Ζοροβαβήλῳ τῷ ἄρχοντι τῶν Ἰουδαίων, ἵνα διακομίσωσιν εἰς Ἱεροσόλυμα καὶ ἀποκαταστήσωσιν εἰς τὸν ναὸν τοῦ θεοῦ. ὁ δ’ ἀριθμὸς αὐτῶν ἐστιν τοσοῦτος· ψυκτῆρες χρύσεοι πεντήκοντα, ἀργύρεοι τετρακόσιοι, θηρίκλεια χρύσεα πεντήκοντα, ἀργύρεα τετρακόσια, κάδοι χρύσεοι πεντήκοντα, ἀργύρεοι πεντακόσιοι, σπονδεῖα χρύσεα τεσσαράκοντα, ἀργύρεα τριακόσια, φιάλαι χρυσαῖ τριάκοντα, ἀργύρεαι δισχίλιαι τετρακόσιαι, σκεύη τε ἄλλα μεγάλα χίλια. συγχωρῶ δὲ αὐτοῖς καὶ τὴν ἐκ προγόνων εἰθισμένην τιμὴν κτηνῶν καὶ οἴνου καὶ ἐλαίου δραχμὰς εἴκοσιν μυριάδας καὶ πεντακισχιλίας πεντακοσίας καὶ εἰς σεμίδαλιν πυρῶν ἀρτάβας δισμυρίας πεντακοσίας. κελεύω δὲ τὴν τούτων χορηγίαν ἐκ τῶν Σαμαρείας γίνεσθαι φόρων. ἐποίσουσι δὲ τὰ ἱερὰ ταῦτα κατὰ τοὺς Μωυσέως νόμους οἱ ἱερεῖς ἐν Ἱεροσολύμοις καὶ προσφέροντες εὔξονται τῷ θεῷ περὶ σωτηρίας τε τοῦ βασιλέως καὶ τοῦ γένους αὐτοῦ, ὅπως ἡ Περσῶν βασιλεία διαμείνῃ. τοὺς δὲ παρακούσαντας τούτων καὶ ἀκυρώσαντας ἀνασταυρωθῆναι βούλομαι καὶ τὰς οὐσίας αὐτῶν εἶναι βασιλικάς. καὶ ἡ μὲν ἐπιστολὴ ταῦτα ἐδήλου· τῶν δ’ ἐκ τῆς αἰχμαλωσίας συνελθόντων εἰς Ἱεροσόλυμα μυριάδες ἦσαν τέσσαρες καὶ δισχίλιοι τετρακόσιοι ἑξήκοντα δύο.", "st": "11.1.3"}, {"sp": "N", "t": "Βαλλομένων δὲ τοὺς θεμελίους τοῦ ναοῦ καὶ περὶ τὴν οἰκοδομίαν αὐτοῦ λίαν ἐσπουδακότων, τὰ πέριξ ἔθνη καὶ μάλιστα τὸ Χουθαίων, οὓς ἐκ τῆς Περσίδος καὶ Μηδικῆς ἀγαγὼν Σαλμανασσάρης ὁ τῶν Ἀσσυρίων βασιλεὺς κατῴκισεν ἐν Σαμαρείᾳ, ὅτε τὸν τῶν Ἰσραηλιτῶν λαὸν ἀνάστατον ἐποίησεν, παρεκάλουν τοὺς σατράπας καὶ τοὺς ἐπιμελουμένους ἐμποδίζειν τοὺς Ἰουδαίους πρός τε τὴν τῆς πόλεως ἀνάστασιν καὶ τὴν τοῦ ναοῦ κατασκευήν. οἱ δὲ καὶ χρήμασιν διαφθαρέντες ὑπ’ αὐτῶν ἀπημπόλησαν τοῖς Χουθαίοις τὸ περὶ τοὺς Ἰουδαίους ἀμελὲς καὶ ῥᾴθυμον τῆς οἰκοδομῆς· Κύρῳ γὰρ περί τε ἄλλους ἀσχοληθέντι πολέμους ἄγνοια τούτων ἦν καὶ στρατευσαμένῳ γε ἐπὶ Μασσαγέτας εὐθὺς συνέβη τελευτῆσαι τὸν βίον. Καμβύσου δὲ τοῦ Κύρου παιδὸς τὴν βασιλείαν παραλαβόντος οἱ ἐν Συρίᾳ καὶ Φοινίκῃ καὶ Ἀμμανίτιδι καὶ Μωαβίτιδι καὶ Σαμαρείᾳ γράφουσιν ἐπιστολὴν Καμβύσῃ δηλοῦσαν τάδε· δέσποτα, οἱ παῖδές σου Ῥάθυμος ὁ πάντα τὰ πραττόμενα γράφων καὶ Σεμέλιος ὁ γραμματεὺς καὶ οἱ τῆς βουλῆς τῆς ἐν Συρίᾳ καὶ Φοινίκῃ κριταί. γινώσκειν σε δεῖ, βασιλεῦ, ὅτι Ἰουδαῖοι οἱ εἰς Βαβυλῶνα ἀναχθέντες ἐληλύθασιν εἰς τὴν ἡμετέραν καὶ τήν τε πόλιν τὴν ἀποστάτιν καὶ πονηρὰν οἰκοδομοῦσιν καὶ τὰς ἀγορὰς αὐτῆς καὶ ἐπισκευάζουσιν τὰ τείχη καὶ ναὸν ἀνεγείρουσιν. ἴσθι μέντοι γε τούτων γενομένων οὔτε φόρους αὐτοὺς τελεῖν ὑπομενοῦντας οὔτε δὲ ὑπακούειν ἐθελήσοντας, ἀλλὰ καὶ βασιλεῦσιν ἀντιστήσονται καὶ ἄρχειν μᾶλλον ἢ ὑπακούειν ἐθελήσουσιν. ἐνεργουμένων οὖν τῶν περὶ τὸν ναὸν καὶ σπουδαζομένων καλῶς ἔχειν ἔδοξεν ἡμῖν γράψαι σοι, βασιλεῦ, καὶ μὴ περιιδεῖν, ὅπως ἐπισκέψῃ τὰ τῶν πατέρων σου βιβλία· εὑρήσεις γὰρ ἐν αὐτοῖς ἀποστάτας καὶ τῶν βασιλέων ἐχθροὺς Ἰουδαίους καὶ τὴν πόλιν αὐτῶν, ἣ διὰ τοῦτο καὶ νῦν ἠρημώθη. ἔδοξε δ’ ἡμῖν καὶ τοῦτό σοι δηλῶσαι ἀγνοούμενον ἴσως, ὅτι τῆς πόλεως οὕτως συνοικισθείσης καὶ τὸν κύκλον τῶν τειχῶν ἀπολαβούσης ἀποκλείεταί σοι ἡ ὁδὸς ἡ ἐπὶ κοίλην Συρίαν καὶ Φοινίκην.", "st": "11.2.1"}, {"sp": "N", "t": "Ἀναγνοὺς δὲ ὁ Καμβύσης τὴν ἐπιστολὴν καὶ φύσει πονηρὸς ὢν κινεῖται πρὸς τὰ δεδηλωμένα καὶ γράφει τάδε λέγων· βασιλεὺς Καμβύσης Ῥαθύμῳ τῷ γράφοντι τὰ προσπίπτοντα καὶ Βεελζέμῳ καὶ Σεμελίῳ γραμματεῖ καὶ τοῖς λοιποῖς τοῖς συντασσομένοις καὶ οἰκοῦσιν ἐν Σαμαρείᾳ καὶ Φοινίκῃ τάδε λέγει. ἀναγνοὺς τὰ πεμφθέντα παρ’ ὑμῶν γράμματα ἐκέλευσα ἐπισκέψασθαι τὰ τῶν προγόνων μου βιβλία, καὶ εὑρέθη ἡ πόλις ἐχθρὰ βασιλεῦσιν ἀεὶ γεγενημένη, καὶ στάσεις καὶ πολέμους οἱ ἐνοικοῦντες πραγματευσάμενοι, καὶ βασιλεῖς αὐτῶν ἔγνωμεν δυνατοὺς καὶ βιαίους φορολογήσαντας κοίλην Συρίαν καὶ Φοινίκην. ἐγὼ τοίνυν προσέταξα μὴ συγχωρεῖν τοῖς Ἰουδαίοις οἰκοδομεῖν τὴν πόλιν, μὴ ἐπὶ πλέον αὐξηθῇ τὰ τῆς κακίας αὐτῶν, ᾗ χρώμενοι πρὸς τοὺς βασιλεῖς διατετελέκασιν. τούτων ἀναγνωσθέντων τῶν γραμμάτων ὁ Ῥάθυμος καὶ Σεμέλιος ὁ γραμματεὺς καὶ οἱ τούτοις συντεταγμένοι παραχρῆμα ἐπιπηδήσαντες ἵπποις ἔσπευσαν εἰς Ἱεροσόλυμα πλῆθος ἐπαγόμενοι πολύ, καὶ διεκώλυσαν οἰκοδομεῖν τοὺς Ἰουδαίους τὴν πόλιν καὶ τὸν ναόν. καὶ ταῦτα μὲν ἐπεσχέθη τὰ ἔργα μέχρι τοῦ δευτέρου ἔτους τῆς Δαρείου βασιλείας τοῦ Περσῶν ἐπ’ ἄλλα ἔτη ἐννέα· Καμβύσης γὰρ ἓξ ἔτη βασιλεύσας, καταστρεψάμενος ἐν τούτοις τὴν Αἴγυπτον ὑποστρέψας ἐτελεύτησεν ἐν Δαμασκῷ.", "st": "11.2.2"}, {"sp": "N", "t": "Μετὰ δὲ τὴν τῶν μάγων ἀναίρεσιν, οἳ μετὰ τὸν Καμβύσου θάνατον τὴν Περσῶν ἀρχὴν ἐνιαυτῷ κατέσχον οἱ λεγόμενοι ἑπτὰ οἶκοι τῶν Περσῶν τὸν Ὑστάσπου παῖδα Δαρεῖον ἀπέδειξαν βασιλέα. οὗτος ἰδιώτης ὢν ηὔξατο τῷ θεῷ, εἰ γένοιτο βασιλεύς, πάντα τὰ σκεύη τοῦ θεοῦ, ὅσα ἦν ἔτι ἐν Βαβυλῶνι, πέμψειν εἰς τὸν ναὸν τὸν ἐν Ἱεροσολύμοις. ἔτυχεν δὲ κατ’ ἐκεῖνον τὸν καιρὸν ἀφικόμενος πρὸς Δαρεῖον ἐξ Ἱεροσολύμων Ζοροβάβηλος, ὃς τῶν αἰχμαλώτων Ἰουδαίων ἡγεμὼν ἀπεδέδεικτο· πάλαι γὰρ ἦν αὐτῷ φιλία πρὸς τὸν βασιλέα, δι’ ἣν καὶ σωματοφυλακεῖν αὐτὸν μετ’ ἄλλων δύο κριθεὶς ἄξιος ἀπέλαυεν ἧς ἤλπισεν τιμῆς.", "st": "11.3.1"}, {"sp": "N", "t": "Τῷ δὲ πρώτῳ τῆς βασιλείας ἔτει Δαρεῖος ὑποδέχεται λαμπρῶς καὶ μετὰ πολλῆς παρασκευῆς τούς τε περὶ αὐτὸν καὶ τοὺς οἴκοι γεγονότας καὶ τοὺς τῶν Μήδων ἡγεμόνας καὶ σατράπας τῆς Περσίδος καὶ τοπάρχας τῆς Ἰνδικῆς ἄχρι τῆς Αἰθιοπίας καὶ τοὺς στρατηγοὺς τῶν ἑκατὸν εἰκοσιεπτὰ σατραπειῶν. ἐπεὶ δὲ κατευωχηθέντες ἄχρι κόρου καὶ πλησμονῆς ἀνέλυσαν κοιμηθησόμενοι παρ’ αὐτοὺς ἕκαστοι, Δαρεῖος ὁ βασιλεὺς ἐλθὼν ἐπὶ τὴν κοίτην καὶ βραχὺ τῆς νυκτὸς ἀναπαυσάμενος ἔξυπνος γίνεται, καὶ μηκέτι κατακοιμηθῆναι δυνάμενος εἰς ὁμιλίαν τρέπεται μετὰ τῶν τριῶν σωματοφυλάκων, καὶ τῷ λόγον ἐροῦντι περὶ ὧν αὐτὸς ἀνακρίνειν μέλλει τὸν ἀληθέστερον καὶ συνετώτερον, τούτῳ γέρας δώσειν ὑπισχνεῖται νικητήριον πορφύραν ἐνδύσασθαι καὶ ἐν ἐκπώμασιν χρυσοῖς πίνειν καὶ ἐπὶ χρυσίου καθεύδειν καὶ ἅρμα χρυσοχάλινον καὶ κίδαριν βύσσινον καὶ περιαυχένιον χρύσεον, καὶ μετ’ αὐτὸν ἕξειν προεδρίαν διὰ τὴν σοφίαν καὶ συγγενής μου, ἔφη, κληθήσεται. ταύτας ἐπαγγειλάμενος αὐτοῖς παρέξειν τὰς δωρεὰς ἐρωτᾷ μὲν τὸν πρῶτον, εἰ ὁ οἶνος ὑπερισχύει, τὸν δεύτερον δέ, εἰ οἱ βασιλεῖς, τὸν τρίτον δέ, εἰ αἱ γυναῖκες ἢ τούτων μᾶλλον ἡ ἀλήθεια. ταῦτα προθεὶς αὐτοῖς ζητεῖν ἡσύχασεν. ὄρθρου δὲ μεταπεμψάμενος τοὺς μεγιστᾶνας καὶ σατράπας καὶ τοπάρχας τῆς Περσίδος καὶ Μηδικῆς καὶ καθίσας ἐν ᾧ χρηματίζειν εἰώθει, τῶν σωματοφυλάκων ἕκαστον ἐκέλευσεν πάντων ἀκουόντων ἀποφαίνεσθαι τὸ δοκοῦν αὐτῷ περὶ τῶν προκειμένων.", "st": "11.3.2"}, {"sp": "N", "t": "Καὶ ὁ πρῶτος ἤρξατο λέγειν τὴν τοῦ οἴνου δύναμιν οὕτως αὐτὴν ἐμφανίζων· ἄνδρες γὰρ εἶπεν, ἐγὼ τὴν ἰσχὺν τοῦ οἴνου τεκμαιρόμενος πάντα ὑπερβάλλουσαν εὑρίσκω τούτῳ τῷ τρόπῳ· σφάλλει γὰρ τῶν πινόντων αὐτὸν καὶ ἀπατᾷ τὴν διάνοιαν καὶ τὴν τοῦ βασιλέως τῇ τοῦ ὀρφανοῦ καὶ δεομένου κηδεμόνος ὁμοίαν τίθησιν, καὶ τὴν τοῦ δούλου διεγείρει πρὸς παρρησίαν τοῦ ἐλευθέρου, ἥ τε τοῦ πένητος ὁμοία γίνεται τῇ τοῦ πλουσίου· μεταποιεῖ γὰρ καὶ μεταγεννᾷ τὰς ψυχὰς ἐν αὐταῖς ἐγγενόμενος, καὶ τῶν μὲν ἐν συμφορᾷ καθεστηκότων σβέννυσι τὸ λυποῦν, τοὺς δὲ ἀλλότρια χρέα λαβόντας εἰς λήθην ἄγει καὶ ποιεῖ δοκεῖν αὐτοὺς ἁπάντων πλουσιωτάτους, ὡς μηδὲν μικρὸν φθέγγεσθαι, ταλάντων δὲ μεμνῆσθαι καὶ τῶν τοῖς εὐδαίμοσι προσηκόντων ὀνομάτων. ἔτι γε μὴν στρατηγῶν καὶ βασιλέων ἀναισθήτους ἀπεργάζεται καὶ φίλων καὶ συνήθων ἐξαιρεῖ μνήμην· ὁπλίζει γὰρ τοὺς ἀνθρώπους καὶ κατὰ τῶν φιλτάτων καὶ δοκεῖν ποιεῖ πάντων ἀλλοτριωτάτους. καὶ ὅταν νήψαντες τύχωσιν καὶ καταλίπῃ διὰ τῆς νυκτὸς αὐτοὺς ὁ οἶνος κοιμωμένους, ἀνίστανται μηθὲν ὧν ἔπραξαν παρὰ τὴν μέθην εἰδότες. τούτοις ἐγὼ τεκμαιρόμενος εὑρίσκω τὸν οἶνον ὑπερκρατοῦντα πάντων καὶ βιαιότατον.", "st": "11.3.3"}, {"sp": "N", "t": "Ὡς δὲ ὁ πρῶτος ἀποφηνάμενος περὶ τῆς ἰσχύος τοῦ οἴνου τὰ προειρημένα ἐπαύσατο, ὁ μετ’ αὐτὸν ἤρξατο λέγειν περὶ τῆς τοῦ βασιλέως δυνάμεως, ταύτην ἀποδεικνὺς τὴν ἰσχυροτάτην καὶ πλέον τῶν ἄλλων δυναμένην, ὅσα βίαν ἔχειν ἢ σύνεσιν δοκεῖ. τὸν δὲ τρόπον τῆς ἀποδείξεως ἐντεῦθεν ἐλάμβανεν· πάντων μὲν εἶπεν ἀνθρώπους περικρατεῖν, οἳ καὶ τὴν γῆν καταναγκάζουσιν καὶ τὴν θάλασσαν εἶναι χρησίμην αὐτοῖς πρὸς ἃ θέλουσιν, τούτων δ’ ἄρχουσιν οἱ βασιλεῖς καὶ τὴν ἐξουσίαν ἔχουσιν· οἱ δὲ τοῦ κρατίστου καὶ ἰσχυροτάτου ζῴου δεσπόζοντες ἀνυπέρβλητοι τὴν δύναμιν οὗτοι καὶ τὴν ἰσχὺν εἰκότως ἂν εἶεν. ἀμέλει πολέμους ἐπιτάττοντες καὶ κινδύνους τοῖς ἀρχομένοις ἀκούονται, καὶ πέμποντες αὐτοὺς ἐπ’ ἐχθροὺς καταπειθεῖς διὰ τὴν ἰσχὺν τὴν αὐτῶν ἔχουσιν, καὶ ὄρη μὲν κατεργάζεσθαι καὶ τείχη κατασπᾶν καὶ πύργους κελεύουσιν, καὶ κτείνεσθαι δ’ οἱ κελευσθέντες καὶ κτείνειν ὑπομένουσιν, ἵνα μὴ τὰ τοῦ βασιλέως δόξωσι παραβαίνειν προστάγματα, νικήσαντες δὲ τὴν ὠφέλειαν τὴν ἐκ τοῦ πολέμου τῷ βασιλεῖ κομίζουσιν. καὶ οἱ μὴ στρατευόμενοι [δὲ ἀλλὰ] γῆν ἐργαζόμενοι καὶ ἀροῦντες ὅταν πονήσαντες καὶ ἅπασαν τὴν τῶν ἔργων ταλαιπωρίαν ὑπομείναντες θερίσωσιν καὶ τοὺς καρποὺς συνέλωσιν, τοὺς φόρους τῷ βασιλεῖ κομίζουσιν. ὃ δ’ ἂν οὗτος εἴπῃ καὶ κελεύσῃ τοῦτο ἐξ ἀνάγκης οὐδὲν ὑπερβαλομένων γίνεται. ἔτι ὁ μὲν τρυφῆς ἁπάσης καὶ ἡδονῆς ἀναπιμπλάμενος καθεύδει, φυλάσσεται δὲ ὑπὸ γρηγορούντων καὶ ὡσανεὶ δεδεμένων ὑπὸ φόβου· καταλιπεῖν γὰρ οὐδὲ εἷς τολμᾷ κοιμώμενον οὐδὲ τῶν ἰδίων ἀναχωρήσας ποιεῖσθαι πρόνοιαν, ἀλλ’ ἓν ἔργον ἡγούμενος τῶν ἀναγκαίων τὸ φυλάττειν τὸν βασιλέα τούτῳ προσμένει. πῶς οὖν οὐκ ἂν ὁ βασιλεὺς δόξειεν τὴν πάντων ἰσχὺν ὑπερβάλλειν, ᾧ τοσοῦτο πλῆθος πείθεται κελεύοντι;", "st": "11.3.4"}, {"sp": "N", "t": "Σιωπήσαντος δὲ καὶ τούτου περὶ τῆς τῶν γυναικῶν καὶ τῆς ἀληθείας ὁ τρίτος Ζοροβάβηλος διδάσκειν αὐτοὺς ἤρξατο λέγων οὕτως· ἰσχυρὸς μὲν καὶ ὁ οἶνος καὶ ὁ βασιλεύς, ᾧ πάντες ὑπακούουσιν, ἀλλὰ κρείττους τὴν δύναμιν τούτων αἱ γυναῖκες· τόν τε γὰρ βασιλέα γυνὴ παρήγαγεν εἰς τὸ φῶς καὶ τοὺς φυτεύσαντας ἀμπέλους, αἳ ποιοῦσιν τὸν οἶνον, γυναῖκές εἰσιν αἱ τίκτουσαί τε καὶ τρέφουσαι, καθόλου δ’ οὐδέν ἐστιν, ὃ μὴ παρ’ αὐτῶν ἔχομεν· καὶ γὰρ τὰς ἐσθῆτας αὗται ὑφαίνουσιν ἡμῖν καὶ τὰ κατ’ οἶκον διὰ ταύτας ἐπιμελείας καὶ φυλακῆς ἀξιοῦται. καὶ οὐκ ἔστιν ἡμῖν ἀποζευχθῆναι γυναικῶν, ἀλλὰ χρυσὸν πολὺν κτησάμενοι καὶ ἄργυρον καὶ ἄλλο τι τῶν πολυτελῶν καὶ σπουδῆς ἀξίων, ὅταν ἴδωμεν εὔμορφον γυναῖκα, πάντα ἐκεῖνα ἀφέντες τῷ εἴδει τῆς ὁραθείσης προσκεχήναμεν καὶ ὑπομένομεν παραχωρῆσαι τῶν ὄντων ἡμῖν, ἵνα τοῦ κάλλους ἀπολαύσωμεν καὶ μεταλάβωμεν. ἐγκαταλείπομεν δὲ καὶ πατέρας [καὶ μητέρας] καὶ τὴν θρεψαμένην γῆν, καὶ τῶν φιλτάτων πολλάκις λήθην ἔχομεν διὰ τὰς γυναῖκας, καὶ τὰς ψυχὰς ἀφιέναι μετ’ αὐτῶν καρτεροῦμεν. οὕτως δ’ ἂν μάλιστα τὴν ἰσχὺν τῶν γυναικῶν κατανοήσαιτε· οὐχὶ πονοῦντες καὶ πᾶσαν ταλαιπωρίαν ὑπομένοντες καὶ διὰ γῆς καὶ διὰ θαλάττης, ὅταν ἡμῖν ἐκ τῶν πόνων περιγένηταί τινα, αὐτὰ φέροντες ὡς δεσποίναις ταῖς γυναιξὶν διδόαμεν; καὶ τὸν βασιλέα δὲ τὸν τοσούτων κύριον εἶδόν ποτε ὑπὸ τῆς Ῥαβεζάκου τοῦ Θεμασίου παιδὸς Ἀπάμης παλλακῆς δ’ αὐτοῦ ῥαπιζόμενον, καὶ τὸ διάδημα ἀφαιρουμένης καὶ τῇ ἰδίᾳ κεφαλῇ περιτιθείσης ἀνεχόμενον καὶ μειδιώσης μὲν μειδιῶντα ὀργιζομένης δὲ σκυθρωπάζοντα καὶ τῇ τῶν παθῶν μεταβολῇ κολακεύοντα τὴν γυναῖκα καὶ διαλλάττοντα ἐκ τοῦ σφόδρα ταπεινὸν αὑτὸν ποιεῖν, εἴ ποτε δυσχεραίνουσαν ἔβλεπεν.", "st": "11.3.5"}, {"sp": "N", "t": "Εἰς ἀλλήλους δὲ ἀφορώντων τῶν σατραπῶν καὶ ἡγεμόνων περὶ τῆς ἀληθείας ἤρξατο λέγειν ἀπέδειξα μέν, εἰπών, ὅσον αἱ γυναῖκες ἰσχύουσιν, ἀσθενέστεραι δ’ ὅμως καὶ αὗται καὶ ὁ βασιλεὺς τῆς ἀληθείας ὑπάρχουσιν. εἰ γάρ ἐστιν ἡ γῆ μεγίστη καὶ ὑψηλὸς ὁ οὐρανὸς καὶ ταχὺς ὁ ἥλιος, ταῦτα δὲ πάντα κινεῖται κατὰ βούλησιν τοῦ θεοῦ, ἀληθινὸς δέ ἐστιν καὶ δίκαιος οὗτος, ἀπὸ τῆς αὐτῆς αἰτίας δεῖ καὶ τὴν ἀλήθειαν ἰσχυροτάτην ἡγεῖσθαι καὶ μηδὲν πρὸς αὐτὴν τὸ ἄδικον δυνάμενον. ἔτι γε μὴν τὰ μὲν ἄλλα θνητὰ καὶ ὠκύμορα εἶναι συμβέβηκεν τῶν ἰσχὺν ἐχόντων, ἀθάνατον δὲ ἡ ἀλήθεια χρῆμα καὶ ἀίδιον. παρέχει δ’ ἡμῖν οὐ κάλλος χρόνῳ μαραινόμενον οὐδὲ περιουσίαν ἀφαιρετὴν ὑπὸ τύχης, ἀλλὰ τὰ δίκαια καὶ τὰ νόμιμα, διακρίνουσα ἀπ’ αὐτῶν τὰ ἄδικα καὶ ἀπελέγχουσα.", "st": "11.3.6"}, {"sp": "N", "t": "Καταπαύει μὲν ὁ Ζοροβάβηλος τὸν περὶ τῆς ἀληθείας λόγον, ἐπιβοήσαντος δὲ τοῦ πλήθους ὡς ἄριστα εἰπόντος, καὶ ὅτι τὸ ἀληθὲς ἰσχὺν ἄτρεπτον καὶ ἀγήρω μόνον ἔχοι, προσέταξεν αὐτὸν ὁ βασιλεὺς αἰτήσασθαί τι πάρεξ ὧν αὐτὸς ἦν ὑπεσχημένος· δώσειν γὰρ ὄντι σοφῷ καὶ τῶν ἄλλων μᾶλλον φανέντι συνετῷ· συγκαθεσθήσῃ δέ μοι, φησίν, καὶ κεκλήσῃ συγγενὴς ἐμός. ταῦτ’ εἰπόντος ὑπέμνησεν αὐτὸν τῆς εὐχῆς, ἧς ἐποιήσατο, εἰ λάβοι τὴν βασιλείαν· αὕτη δ’ ἂν εἴη οἰκοδομῆσαι μὲν Ἱεροσόλυμα, κατασκευάσαι δὲ ἐν αὐτοῖς τὸν τοῦ θεοῦ ναόν, ἀποκαταστῆσαι δὲ καὶ τὰ σκεύη, ὅσα συλήσας Ναβουχοδονόσορος εἰς Βαβυλῶνα ἐκόμισεν. καὶ τοῦτ’, ἔφη, τοὐμὸν αἴτημά ἐστιν, ὅ μοι νῦν ἐπιτρέπεις αἰτήσασθαι κριθέντι σοφῷ καὶ συνετῷ.", "st": "11.3.7"}, {"sp": "N", "t": "Ἡσθεὶς ἐπὶ τούτοις ὁ βασιλεὺς ἀναστὰς κατεφίλησέν τε αὐτὸν καὶ τοῖς τοπάρχαις καὶ σατράπαις γράφει κελεύων προπέμψαι τὸν Ζοροβάβηλον καὶ τοὺς σὺν αὐτῷ μέλλοντας ἐπὶ τὴν οἰκοδομὴν ἐξιέναι τοῦ ναοῦ. ἐπέστειλε δὲ καὶ τοῖς ἐν Συρίᾳ καὶ Φοινίκῃ ξύλα κέδρινα κατακομίζειν ἐκ τοῦ Λιβάνου τεμόντας εἰς Ἱεροσόλυμα, καὶ συγκατασκευάζειν αὐτῷ τὴν πόλιν, καὶ πάντας ἔγραψεν ἐλευθέρους εἶναι τοὺς εἰς τὴν Ἰουδαίαν τῶν αἰχμαλώτων ἀπελθόντας. καὶ τοὺς ἐπιτρόπους τοὺς αὐτοῦ καὶ σατράπας ἐκώλυσεν ἐπιτάττειν τοῖς Ἰουδαίοις τὰς βασιλικὰς χρείας, ἀνῆκέ τε πᾶσαν ἣν ἂν κατασχεῖν δυνηθῶσιν τῆς χώρας ἀτελῆ φόρων αὐτοῖς νέμεσθαι. προσέταξε δὲ καὶ τοὺς Ἰδουμαίους καὶ Σαμαρείτας καὶ τοὺς ἐκ τῆς κοίλης Συρίας ἀφεῖναι τὰς κώμας, ἃς τῶν Ἰουδαίων κατεῖχον, καὶ προσέτι τάλαντα πεντήκοντα εἰς τὴν οἰκοδομίαν τοῦ ἱεροῦ δοθῆναι. θύειν τε αὐτοῖς τὰς νενομισμένας θυσίας ἐπέτρεψε καὶ τὴν χορηγίαν ἅπασαν καὶ τὴν ἱερὰν στολήν, ᾗ θεραπεύουσι τὸν θεὸν ὅ τε ἀρχιερεὺς καὶ οἱ ἱερεῖς, ἐκ τῶν ἰδίων γίνεσθαι, καὶ τοῖς Λευίταις τὰ ὄργανα, οἷς ὑμνοῦσι τὸν θεόν, καὶ τοῖς φύλαξι τῆς πόλεως καὶ τοῦ ναοῦ προσέταξεν κλήρους γῆς δοθῆναι καὶ κατὰ ἕκαστον ἔτος ὡρισμένον τι πρὸς τὴν τοῦ βίου χρείαν ἀργύριον, πέμψαι δὲ καὶ τὰ σκεύη, καὶ πάντα, ὅσα Κῦρος πρὸ αὐτοῦ ἐβουλήθη περὶ τῆς τῶν Ἰουδαίων ἀποκαταστάσεως, ταῦτα καὶ Δαρεῖος διετάξατο.", "st": "11.3.8"}, {"sp": "N", "t": "Τυχὼν οὖν τούτων παρὰ τοῦ βασιλέως Ζοροβάβηλος ἐξελθὼν ἀπὸ τῶν βασιλείων καὶ ἀναβλέψας εἰς τὸν οὐρανὸν εὐχαριστεῖν ἤρξατο τῷ θεῷ τῆς σοφίας καὶ τῆς ἐπ’ αὐτῇ νίκης, ἣν Δαρείου παρόντος ἔλαβεν· οὐ γὰρ ἂν τούτων ἀξιωθῆναι μὴ σοῦ, φησί, δέσποτα, τυχὼν εὐμενοῦς. ταῦτ’ οὖν περὶ τῶν παρόντων εὐχαριστήσας τῷ θεῷ καὶ πρὸς τὰ μέλλοντα δεηθεὶς αὑτὸν παρέχειν ὅμοιον, ἧκεν εἰς Βαβυλῶνα καὶ τοῖς ὁμοφύλοις εὐηγγελίσατο τὰ παρὰ τοῦ βασιλέως. οἱ δὲ ἀκούσαντες εὐχαριστοῦσι μὲν τῷ θεῷ πάλιν αὐτοῖς ἀποδιδόντι τὴν πάτριον γῆν, εἰς δὲ πότον καὶ κώμους τραπέντες ἐφ’ ἡμέρας ἑπτὰ διήγαγον εὐωχούμενοι καὶ τὴν ἀνάκτησιν καὶ παλιγγενεσίαν τῆς πατρίδος ἑορτάζοντες. ἔπειτα τοὺς ἀναβησομένους εἰς τὰ Ἱεροσόλυμα ἡγεμόνας ἐκ τῶν πατρίων φυλῶν σὺν γυναιξὶ καὶ τέκνοις καὶ ὑποζυγίοις ἐπελέξαντο, οἳ Δαρείου συμπέμψαντος ἕως τῶν Ἱεροσολύμων ὥδευον μετὰ χαρᾶς καὶ τρυφῆς, ψαλλόμενοι καὶ καταυλούμενοι καὶ περιψοφούμενοι τοῖς κυμβάλοις. προέπεμπε δὲ αὐτοὺς καὶ τὸ ὑπολειπόμενον τῶν Ἰουδαίων πλῆθος μετὰ παιδιᾶς.", "st": "11.3.9"}, {"sp": "N", "t": "Καὶ οἱ μὲν οὕτως ἀπῄεσαν ἐξ ἑκάστης πατριᾶς ἀριθμὸς ὄντες ὡρισμένος. ἐμοὶ δὲ οὐκ ἔδοξε τὰ τῶν πατριῶν καταλέγειν ὀνόματα, ἵνα μὴ τὴν τῶν ἀναγινωσκόντων διάνοιαν τῆς συναφῆς τῶν πραγμάτων ἀποσπάσας δυσπαρακολούθητον αὐτοῖς ποιήσω τὴν διήγησιν. τὸ δὲ κεφάλαιον τῶν ἀπερχομένων περὶ ἔτη δώδεκα τὴν ἡλικίαν γεγονότων ἐκ τῆς Ἰούδα φυλῆς καὶ Βενιαμίτιδος ἦν μυριάδες τετρακόσιαι ἑξηκονταδύο καὶ ὀκτακισχίλιοι, Λευῖται δὲ τέσσαρες καὶ ἑβδομήκοντα, γυναικῶν δὲ ἀναμὶξ καὶ νηπίων σώματα ἦν τετρακισμύρια ἑπτακόσια τεσσαρακονταδύο. πάρεξ δὲ τούτων Λευῖται μὲν ἦσαν ὑμνῳδοὶ ἑκατὸν εἰκοσιοκτώ, πυλωροὶ δὲ ἑκατὸν δέκα, δοῦλοι δὲ ἱεροὶ τριακόσιοι ἐνενηκονταδύο, ἄλλοι τε πρὸς τούτοις λέγοντες μὲν εἶναι τῶν Ἰσραηλιτῶν οὐ δυνάμενοι δὲ ἐπιδεῖξαι τὸ γένος αὐτῶν ἑξακόσιοι πεντηκονταδύο. ἐξεβλήθησαν δὲ καὶ τῶν ἱερέων ἐκ τῆς τιμῆς ἠγμένοι γυναῖκας, ὧν οὔτ’ αὐτοὶ τὸ γένος εἶχον εἰπεῖν οὔτ’ ἐν ταῖς γενεαλογίαις τῶν Λευιτῶν καὶ ἱερέων εὑρέθησαν· ἦσαν δὲ ὡς πεντακόσιοι καὶ πέντε καὶ εἴκοσι. τὸ δὲ τῶν θεραπόντων πλῆθος εἵπετο τοῖς ἀναβαίνουσιν εἰς Ἱεροσόλυμα ἑπτακισχιλίων τριακοσίων τριακονταεπτά, ψάλται δὲ καὶ ψάλτριαι διακόσιοι τεσσαρακονταπέντε, κάμηλοι τετρακόσιαι τριακονταπέντε, ὑποζύγια πεντακισχίλια πεντακόσια εἰκοσιπέντε. ἡγεμὼν δὲ τῆς κατηριθμημένης πληθύος ἦν ὁ Σαλαθιήλου παῖς Ζοροβάβηλος ἐκ τῶν υἱῶν ὢν τῶν Δαυίδου γεγονὼς ἐκ τῆς Ἰούδα φυλῆς, καὶ Ἰησοῦς υἱὸς Ἰωσεδέκου τοῦ ἀρχιερέως. πρὸς τούτοις ὁ Μαρδοχαῖος καὶ Σερεβαῖος ἐκ τοῦ πλήθους κεκριμένοι ἄρχοντες ἦσαν, οἳ καὶ συνεβάλοντο μνᾶς μὲν χρυσίου ἑκατὸν ἀργύρου δὲ πεντακισχιλίας. οὕτως μὲν οὖν οἵ τε ἱερεῖς καὶ οἱ Λευῖται καὶ μέρος τι τοῦ παντὸς λαοῦ τῶν Ἰουδαίων, ὃς ἦν ἐν τῇ Βαβυλῶνι, κατῳκίσθησαν εἰς τὰ Ἱεροσόλυμα· τὸ δὲ ἄλλο πλῆθος εἰς τὰς ἰδίας ἀνεχώρησεν πατρίδας.", "st": "11.3.10"}, {"sp": "N", "t": "Ἑβδόμῳ δὲ μηνὶ τῆς ἀπὸ Βαβυλῶνος αὐτῶν ἐξόδου περιπέμψαντες ὅ τε ἀρχιερεὺς Ἰησοῦς καὶ Ζοροβάβηλος ὁ ἄρχων τοὺς ἀπὸ τῆς χώρας συνήγαγον εἰς Ἱεροσόλυμα πανδημεὶ μηδὲν προθυμίας ἀπολιπόντες, κατεσκεύασάν τε θυσιαστήριον ἐφ’ οὗ καὶ πρότερον ἦν ᾠκοδομημένον τόπου, ὅπως τὰς νομίμους ἀναφέρωσι θυσίας ἐπ’ αὐτοῦ τῷ θεῷ κατὰ τοὺς Μωυσέως νόμους. ταῦτα δὲ ποιοῦντες οὐκ ἦσαν ἐν ἡδονῇ τοῖς προσχωρίοις ἔθνεσιν πάντων αὐτοῖς ἀπεχθανομένων. ἤγαγον δὲ καὶ τὴν σκηνοπηγίαν κατ’ ἐκεῖνον τὸν καιρόν, ὡς ὁ νομοθέτης περὶ αὐτῆς διετάξατο, καὶ προσφορὰς μετὰ ταῦτα καὶ τοὺς καλουμένους ἐνδελεχισμοὺς καὶ τὰς θυσίας τῶν σαββάτων καὶ πασῶν τῶν ἁγίων ἑορτῶν, οἵ τε πεποιημένοι τὰς εὐχὰς ἀπεδίδοσαν θύοντες ἀπὸ νουμηνίας τοῦ ἑβδόμου μηνός. ἤρξαντο δὲ καὶ τῆς οἰκοδομίας τοῦ ναοῦ πολλὰ τοῖς τε λατόμοις καὶ τέκτοσι χρήματα δόντες καὶ τὰ πρὸς τροφὴν τῶν εἰσαγομένων, τοῖς τε Σιδωνίοις ἡδὺ καὶ κοῦφον ἦν τά τε κέδρινα κατάγουσιν ἐκ τοῦ Λιβάνου ξύλα δήσασιν αὐτὰ καὶ σχεδίαν πηξαμένοις εἰς τὸν τῆς Ἰόππης κομίζειν λιμένα· τοῦτο γὰρ πρῶτος μὲν Κῦρος ἐκέλευσεν, τότε δὲ Δαρείου κελεύσαντος ἐγίνετο.", "st": "11.4.1"}, {"sp": "N", "t": "Ὧν τῷ δευτέρῳ ἔτει τῆς εἰς Ἱεροσόλυμα καθόδου τῶν Ἰουδαίων μηνὶ δευτέρῳ παραγενομένων συνείχετο ἡ τοῦ ναοῦ κατασκευή· καὶ τοὺς θεμελίους ἐγείραντες τῇ νουμηνίᾳ τοῦ δευτέρου μηνὸς τοῦ δευτέρου ἔτους ἐπῳκοδόμουν, προστησάμενοι τῶν ἔργων Λευιτῶν τε τοὺς εἰκοστὸν ἔτος ἤδη γεγονότας καὶ Ἰησοῦν καὶ τοὺς υἱοὺς αὐτοῦ καὶ τοὺς ἀδελφοὺς καὶ Ζοδμοῆλον τὸν ἀδελφὸν Ἰούδα τοῦ Ἀμιναδάβου καὶ τοὺς υἱοὺς αὐτοῦ. καὶ ὁ μὲν ναὸς πάσῃ χρησαμένων σπουδῇ τῶν τὴν ἐπιμέλειαν ἐγκεχειρισμένων θᾶττον ἢ προσεδόκησεν ἄν τις ἔλαβεν τέλος. ἀπαρτισθέντος δὲ τοῦ ἱεροῦ μετὰ σαλπίγγων οἱ ἱερεῖς ταῖς συνήθεσι στολαῖς κεκοσμημένοι καὶ οἱ Λευῖται καὶ οἱ Ἀσάφου παῖδες ἀναστάντες ὕμνουν τὸν θεόν, ὡς τὴν εἰς αὐτὸν εὐλογίαν Δαυίδης κατέδειξε πρῶτος. οἱ δὲ ἱερεῖς καὶ Λευῖται καὶ τῶν πατριῶν οἱ πρεσβύτεροι τὸν πρότερον [ναὸν] ταῖς μνήμαις ἀναπολοῦντες μέγιστόν τε καὶ πολυτελέστατον, καὶ τὸν γεγενημένον ὁρῶντες ὑπὸ πτωχείας ἐνδεέστερον τοῦ πάλαι κατασκευαζόμενον, ὅσον εἶεν τῆς ἀρχαίας εὐδαιμονίας ὑποβεβηκότες καὶ τῆς ἀξίας τοῦ ναοῦ λογιζόμενοι κατήφουν, καὶ τῆς ἐπὶ τούτῳ λύπης κρατεῖν οὐ δυνάμενοι μέχρι θρήνων καὶ δακρύων προήγοντο. ὁ δὲ λαὸς ἠγάπα τοῖς παροῦσιν καὶ τῷ μόνον οἰκοδομῆσαι τὸ ἱερὸν τοῦ πρότερον ὄντος οὐδένα λόγον ποιούμενος οὐδ’ ἀνάμνησιν οὐδὲ πρὸς τὴν σύγκρισιν τὴν ἐκείνου βασανίζων αὑτὸν ὡς ἐπ’ ἐλάττοσιν οἷς ὑπελάμβανεν. ὑπερεφώνει δὲ τὸν τῶν σαλπίγγων ἦχον καὶ τὴν τοῦ πλήθους χαρὰν ἡ τῶν πρεσβυτέρων καὶ ἱερέων ἐφ’ οἷς ἐδόκουν ἐλαττοῦσθαι τὸν ναὸν τοῦ κατασκαφέντος οἰμωγή.", "st": "11.4.2"}, {"sp": "N", "t": "Τῆς δὲ βοῆς τῶν σαλπίγγων ἀκούσαντες οἱ Σαμαρεῖται, ἐτύγχανον γὰρ ἀπεχθανόμενοι τῇ τε Ἰούδα φυλῇ καὶ τῇ Βενιαμίτιδι, συνέδραμον τὴν αἰτίαν τοῦ θορύβου μαθεῖν θέλοντες. γνόντες δὲ τοὺς αἰχμαλωτισθέντας εἰς Βαβυλῶνα τῶν Ἰουδαίων ἀνακτίζοντας τὸ ἱερόν, προσίασιν τῷ Ζοροβαβήλῳ καὶ Ἰησοῦ καὶ τοῖς ἡγουμένοις τῶν πατριῶν ἀξιοῦντες αὐτοῖς ἐπιτραπῆναι συγκατασκευάσαι τὸν ναὸν καὶ κοινωνῆσαι τῆς οἰκοδομίας· σεβόμεθα γὰρ οὐκ ἔλαττον ἐκείνων τὸν θεόν, ἔφασκον, καὶ τοῦτον ὑπερευχόμεθα καὶ τῆς θρησκείας ἐσμὲν ἐπιθυμηταὶ ἐξ ἐκείνου τοῦ χρόνου, ἀφ’ οὗ Σαλμανασσάρης ὁ τῶν Ἀσσυρίων βασιλεὺς ἐκ τῆς Χουθίας ἡμᾶς μετήγαγεν καὶ Μηδίας ἐνθάδε. τούτους αὐτῶν ποιησαμένων τοὺς λόγους Ζοροβάβηλος καὶ Ἰησοῦς ὁ ἀρχιερεὺς καὶ οἱ τῶν πατριῶν ἡγεμόνες τῶν Ἰσραηλιτῶν πρὸς αὐτοὺς ἔφασαν τῆς μὲν οἰκοδομίας αὐτοῖς ἀδύνατον εἶναι κοινωνεῖν, αὐτῶν προσταχθέντων κατασκευάσαι τὸν ναὸν πρότερον μὲν ὑπὸ Κύρου νῦν δὲ ὑπὸ Δαρείου· προσκυνεῖν δὲ αὐτοῖς ἐφιέναι καὶ τοῦτο μόνον εἶναι κοινόν, εἰ βούλονται, πρὸς αὐτοὺς καὶ πᾶσιν ἀνθρώποις ἀφικνουμένοις εἰς τὸ ἱερὸν σέβειν τὸν θεόν.", "st": "11.4.3"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσαντες οἱ Χουθαῖοι, τὴν γὰρ προσηγορίαν οἱ Σαμαρεῖται ταύτην ἔχουσιν, ἠγανάκτησαν καὶ πείθουσιν τὰ ἐν Συρίᾳ ἔθνη τῶν σατραπῶν δεηθῆναι τὸν αὐτὸν τρόπον, ὅνπερ ἐπὶ Κύρου πρότερον εἶτ’ ἐπὶ Καμβύσου μετ’ αὐτόν, ἐπισχεῖν τὴν τοῦ ναοῦ κατασκευὴν καὶ σπουδάζουσιν περὶ αὐτὸν τοῖς Ἰουδαίοις ἀναβολὴν καὶ τριβὴν πραγματεύσασθαι. κατὰ δὲ τὸν καιρὸν τοῦτον ἀναβάντων εἰς Ἱεροσόλυμα Σισίνου τοῦ τῆς Συρίας καὶ Φοινίκης ἐπάρχου καὶ Σαρωβαζάνου μετὰ καί τινων ἑτέρων καὶ τοὺς ἡγεμόνας τῶν Ἰουδαίων ἐρομένων, τίνος αὐτοῖς συγχωρήσαντος οὕτως οἰκοδομοῦσιν τὸν ναόν, ὡς φρούριον μᾶλλον αὐτὸν εἶναι ἢ ἱερόν, καὶ τί δήποτε τὰς στοὰς καὶ τὰ τείχη περιβεβλήκασιν τῇ πόλει σφόδρα ὀχυρά, Ζοροβάβηλος καὶ ὁ ἀρχιερεὺς Ἰησοῦς δούλους μὲν αὐτοὺς ἔφασαν εἶναι τοῦ μεγίστου θεοῦ, τὸν δὲ ναὸν τοῦτον αὐτῷ κατασκευασθέντα ὑπὸ βασιλέως αὐτῶν εὐδαίμονος καὶ πάντας ὑπερβάλλοντος ἀρετῇ πολὺν διαμεῖναι χρόνον. ἐπεὶ δὲ τῶν πατέρων ἀσεβησάντων εἰς τὸν θεὸν Ναβουχοδονόσορος ὁ Βαβυλωνίων καὶ Χαλδαίων βασιλεὺς ἑλὼν τὴν πόλιν κατὰ κράτος αὐτήν τε καθεῖλεν καὶ τὸν ναὸν συλήσας ἐνέπρησεν καὶ τὸν λαὸν μετῴκισεν αἰχμάλωτον μεταγαγὼν εἰς Βαβυλῶνα, Κῦρος ὁ μετ’ αὐτὸν τῆς Βαβυλωνίας καὶ Περσίδος βασιλεὺς ἔγραψεν οἰκοδομῆσαι τὸν ναόν, καὶ πάνθ’ ὅσα μετήγαγεν ἐξ αὐτοῦ Ναβουχοδονόσορος ἀναθήματα καὶ σκεύη Ζοροβαβήλῳ παραδοὺς καὶ Μιθριδάτῃ τῷ γαζοφύλακι προσέταξεν κομίσαι εἰς Ἱεροσόλυμα καὶ πάλιν εἰς τὸν ἴδιον ἀποκατασταθῆναι ναὸν οἰκοδομηθέντα. τοῦτο γὰρ ἐπέστειλεν ἐν τάχει γενέσθαι Σαβάσηρον κελεύσας ἀναβάντα εἰς Ἱεροσόλυμα τῆς οἰκοδομίας τοῦ ναοῦ ποιήσασθαι πρόνοιαν. ὃς μετὰ τὸ λαβεῖν παρὰ Κύρου γράμματα, παραγενόμενος εὐθὺς τοὺς θεμελίους κατεβάλετο, καὶ ἐξ ἐκείνου τοῦ χρόνου κατασκευαζόμενος μέχρι καὶ τοῦ δεῦρο διὰ τὴν τῶν ἐχθρῶν κακοήθειάν ἐστιν ἀτελής. εἰ τοίνυν βούλεσθε καὶ δοκιμάζετε, γράψατε ταῦτα Δαρείῳ, ὅπως ἐπισκεψάμενος τὰ τῶν βασιλέων ὑπομνήματα εὕρῃ μηδὲν ἡμᾶς ὧν λέγομεν καταψευσαμένους.", "st": "11.4.4"}, {"sp": "N", "t": "Ταῦτ’ εἰπόντων τοῦ τε Ζοροβαβήλου καὶ τοῦ ἀρχιερέως ὁ Σισίννης καὶ οἱ σὺν αὐτῷ τὴν μὲν οἰκοδομίαν ἐπισχεῖν οὐ διέγνωσαν ἕως ἂν ταῦτα δηλωθῇ Δαρείῳ, παραχρῆμα δ’ αὐτῷ περὶ τούτων ἔγραψαν. τῶν δὲ Ἰουδαίων κατεπτηχότων καὶ δεδιότων μὴ μεταδόξῃ τῷ βασιλεῖ περὶ τῆς τῶν Ἱεροσολύμων καὶ τοῦ ναοῦ κατασκευῆς, ὄντες κατὰ τὸν καιρὸν ἐκεῖνον δύο προφῆται παρ’ αὐτοῖς Ἀγγαῖος καὶ Ζαχαρίας θαρρεῖν αὐτοὺς παρώρμων καὶ μηδὲν ἐκ τῶν Περσῶν ὑφορᾶσθαι δύσκολον, ὡς τοῦ θεοῦ ταῦτα προλέγοντος. πιστεύοντες δὲ τοῖς προφήταις ἐντεταμένως εἴχοντο τῆς οἰκοδομίας μηδεμίαν ἡμέραν ἀνιέμενοι.", "st": "11.4.5"}, {"sp": "N", "t": "Δαρεῖος δὲ τῶν Σαμαρειτῶν αὐτῷ γραψάντων καὶ κατηγορούντων διὰ τῆς ἐπιστολῆς τῶν Ἰουδαίων, ὡς τήν τε πόλιν ὀχυροῦσι καὶ τὸν ναὸν φρουρίῳ προσεοικότα μᾶλλον ἢ ἱερῷ κατασκευάζουσιν, λεγόντων δὲ μὴ συνοίσειν αὐτῷ τὰ γινόμενα καὶ προσέτι τὰς ἐπιστολὰς ἐπιδεικνύντων τὰς Καμβύσου, δι’ ὧν ἐκώλυσεν ἐκεῖνος οἰκοδομεῖν τὸν ναόν, μαθὼν παρ’ αὐτῶν οὐκ ἀσφαλῆ τοῖς πράγμασιν αὐτοῦ τὴν τῶν Ἱεροσολύμων ἀποκατάστασιν ἔσεσθαι, ἐπεὶ καὶ τὰ παρὰ τοῦ Σισίννου καὶ τῶν σὺν αὐτῷ κομισθέντα ἀνέγνω γράμματα, προσέταξεν ἐν τοῖς βασιλικοῖς ὑπομνήμασιν ζητηθῆναι τὰ περὶ τούτων. καὶ εὑρέθη ἐν Ἐκβατάνοις τῇ βάρει τῇ ἐν Μηδίᾳ βιβλίον, ἐν ᾧ τάδε ἦν ἀναγεγραμμένα· ἐν τῷ πρώτῳ τῆς βασιλείας ἔτει Κῦρος ὁ βασιλεὺς ἐκέλευσεν τὸν ναὸν οἰκοδομηθῆναι τὸν ἐν Ἱεροσολύμοις καὶ τὸ θυσιαστήριον, ὕψος μὲν πηχῶν ἑξήκοντα εὖρος δὲ τῶν αὐτῶν, διὰ δόμων λιθίνων βία τε ξεστῶν τριῶν καὶ ξυλίνου δόμου ἑνὸς ἐγχωρίου. καὶ τὴν εἰς ταῦτα δαπάνην ἐκ τῶν τοῦ βασιλέως γίνεσθαι διετάξατο, καὶ τὰ σκεύη, ἃ συλήσας Ναβουχοδονόσορος εἰς Βαβυλῶνα ἐκόμισεν, ἀποδοθῆναι τοῖς Ἱεροσολυμίταις, τὴν δὲ ἐπιμέλειαν τούτων εἶναι Ἀναβασσάρου τοῦ ἐπάρχου καὶ τῆς Συρίας τε καὶ Φοινίκης ἡγεμόνος καὶ τῶν ἑταίρων αὐτοῦ, ὅπως αὐτοὶ μὲν ἀφέξονται τοῦ τόπου, τοῖς δὲ δούλοις τοῦ θεοῦ Ἰουδαίοις τε καὶ ἡγεμόσιν αὐτῶν ἐπιτρέψουσιν οἰκοδομηθῆναι τὸν ναόν. καὶ συλλαβέσθαι δὲ πρὸς τὸ ἔργον διετάξατο, κἀκ τοῦ φόρου τοῦ τῆς χώρας ἧς ἐπετροπεύοντο τελεῖν τοῖς Ἰουδαίοις εἰς θυσίας λόγον ταύρους καὶ κριοὺς καὶ ἄρνας καὶ ἐρίφους καὶ σεμίδαλιν καὶ ἔλαιον καὶ οἶνον καὶ τἆλλα, ὅσα ἂν οἱ ἱερεῖς ὑπαγορεύσωσιν, εὔχωνται δὲ ὑπὲρ τῆς σωτηρίας τοῦ βασιλέως καὶ Περσῶν. τοὺς δὲ παραβάντας τι τῶν ἐπεσταλμένων συλληφθέντας ἐκέλευσεν ἀνασταυρωθῆναι καὶ τὴν οὐσίαν αὐτῶν εἰς τὴν βασιλικὴν καταταγῆναι κτῆσιν. καὶ κατηύξατο πρὸς τούτοις τῷ θεῷ, ὅπως εἴ τις ἐπιχειρήσειε διακωλῦσαι τὴν οἰκοδομίαν τοῦ ναοῦ, βαλὼν αὐτὸν ὁ θεὸς ἐπίσχῃ τῆς ἀδικίας.", "st": "11.4.6"}, {"sp": "N", "t": "Ταῦθ’ εὑρὼν ἐν τοῖς ὑπομνήμασιν τοῖς Κύρου Δαρεῖος ἀντιγράφει τῷ Σισίννῃ καὶ τοῖς ἑταίροις αὐτοῦ τάδε λέγων· βασιλεὺς Δαρεῖος Σισίννῃ τῷ ἐπάρχῳ καὶ Σαραβαζάνῃ καὶ τοῖς ἑταίροις αὐτῶν χαίρειν. τὸ ἀντίγραφον τῆς ἐπιστολῆς ὑμῖν ἧς ἐν τοῖς ὑπομνήμασιν εὗρον τοῖς Κύρου ἀπέσταλκα καὶ βούλομαι γίνεσθαι πάντα, καθὼς ἐν αὐτῇ περιέχει. ἔρρωσθε. μαθόντες οὖν ἐκ τῆς ἐπιστολῆς ὁ Σισίννης καὶ οἱ σὺν αὐτῷ τὴν τοῦ βασιλέως προαίρεσιν ταύτῃ τὰ λοιπὰ ἀκόλουθα ποιεῖν διέγνωσαν. ἐπεστάτουν οὖν τῶν ἱερῶν ἔργων συλλαμβανόμενοι τοῖς πρεσβυτέροις τῶν Ἰουδαίων καὶ τῶν γερόντων ἄρχουσιν. καὶ ἠνύετο κατὰ πολλὴν σπουδὴν ἡ κατασκευὴ τοῦ ναοῦ προφητευόντων Ἀγγαίου καὶ Ζαχαρίου κατὰ πρόσταγμα τοῦ θεοῦ καὶ μετὰ βουλήσεως Κύρου τε καὶ Δαρείου τῶν βασιλέων, ᾠκοδομήθη δὲ ἐν ἔτεσιν ἑπτά. τοῦ δ’ ἐνάτου τῆς Δαρείου βασιλείας ἔτους εἰκάδι καὶ τρίτῃ μηνὸς δωδεκάτου, ὃς καλεῖται παρὰ μὲν ἡμῖν Ἄδαρ παρὰ δὲ Μακεδόσιν Δύστρος, προσφέρουσιν θυσίας οἵ τε ἱερεῖς καὶ Λευῖται καὶ τὸ ἄλλο τῶν Ἰσραηλιτῶν πλῆθος ἀνανεωτικὰς τῶν πρότερον ἀγαθῶν μετὰ τὴν αἰχμαλωσίαν τοῦ τὸ ἱερὸν ἀνακαινισθὲν ἀπειληφέναι ταύρους ἑκατὸν κριοὺς διακοσίους ἄρνας τετρακοσίους χιμάρους δώδεκα κατὰ φυλήν, τοσαῦται γάρ εἰσιν αἱ τῶν Ἰσραηλιτῶν φυλαί, ὑπὲρ ὧν ἥμαρτεν ἑκάστη. ἔστησάν τε κατὰ τοὺς Μωυσέως νόμους οἵ τε ἱερεῖς καὶ οἱ Λευῖται θυρωροὺς ἐφ’ ἑκάστου πυλῶνος· ᾠκοδομήκεσαν γὰρ οἱ Ἰουδαῖοι καὶ τὰς ἐν κύκλῳ τοῦ ναοῦ στοὰς τοῦ ἔνδοθεν ἱεροῦ.", "st": "11.4.7"}, {"sp": "N", "t": "Ἐνστάσης δὲ τῆς τῶν ἀζύμων ἑορτῆς μηνὶ τῷ πρώτῳ, κατὰ μὲν Μακεδόνας Ξανθικῷ λεγομένῳ κατὰ δὲ ἡμᾶς Νισάν, συνερρύη πᾶς ὁ λαὸς ἐκ τῶν κωμῶν εἰς τὴν πόλιν, καὶ τὴν ἑορτὴν ἤγαγον ἁγνεύοντες μετὰ γυναικῶν καὶ τέκνων τῷ πατρίῳ νόμῳ, καὶ τὴν πάσχα προσαγορευομένην θυσίαν τῇ τετράδι καὶ δεκάτῃ τοῦ αὐτοῦ μηνὸς ἐπιτελέσαντες κατευωχήθησαν ἐπὶ ἡμέρας ἑπτὰ μηδεμιᾶς φειδόμενοι πολυτελείας, ἀλλὰ καὶ τὰς ὁλοκαυτώσεις ἐπιφέροντες τῷ θεῷ καὶ χαριστηρίους θυσίας ἱερουργοῦντες ἀνθ’ ὧν αὐτοὺς ποθοῦν τὸ θεῖον πάλιν εἰς τὴν πάτριον γῆν καὶ τοὺς ἐν αὐτῇ νόμους ἤγαγεν καὶ τὴν τοῦ Περσῶν βασιλέως διάνοιαν εὐμενῆ κατέστησεν αὐτοῖς. καὶ οἱ μὲν ὑπὲρ τούτων ἐπιδαψιλευόμενοι ταῖς θυσίαις καὶ τῇ περὶ τὸν θεὸν φιλοτιμίᾳ κατῴκησαν ἐν τοῖς Ἱεροσολύμοις πολιτείᾳ χρώμενοι ἀριστοκρατικῇ μετὰ ὀλιγαρχίας· οἱ γὰρ ἀρχιερεῖς προεστήκεσαν τῶν πραγμάτων ἄχρι οὗ τοὺς Ἀσαμωναίου συνέβη βασιλεύειν ἐκγόνους. πρὸ μὲν γὰρ τῆς αἰχμαλωσίας καὶ τῆς ἀναστάσεως ἐβασιλεύοντο ἀπὸ Σαούλου πρῶτον ἀρξάμενοι καὶ Δαυίδου ἐπὶ ἔτη πεντακόσια τριακονταδύο μῆνας ἓξ ἡμέρας δέκα, πρὸ δὲ τῶν βασιλέων τούτων ἄρχοντες αὐτοὺς διεῖπον οἱ προσαγορευόμενοι κριταὶ καὶ μόναρχοι, καὶ τοῦτον πολιτευόμενοι τὸν τρόπον ἔτεσιν πλέον ἢ πεντακοσίοις διήγαγον μετὰ Μωυσῆν ἀποθανόντα καὶ Ἰησοῦν τὸν στρατηγόν. καὶ τὰ μὲν περὶ τῶν ἀνασωθέντων ἐκ τῆς αἰχμαλωσίας Ἰουδαίων ἐν τοῖς Κύρου καὶ Δαρείου χρόνοις ἐν τούτοις ὑπῆρχεν.", "st": "11.4.8"}, {"sp": "N", "t": "Οἱ δὲ Σαμαρεῖς ἀπεχθῶς πρὸς αὐτοὺς καὶ βασκάνως διακείμενοι πολλὰ κακὰ τοὺς Ἰουδαίους εἰργάσαντο πλούτῳ τε πεποιθότες καὶ συγγένειαν προσποιούμενοι τὴν Περσῶν, ἐπειδήπερ ἐκεῖθεν ἦσαν. ὅσα τε γὰρ ἐκελεύσθησαν ἐκ τῶν φόρων ὑπὸ τοῦ βασιλέως εἰς τὰς θυσίας τελεῖν τοῖς Ἰουδαίοις παρέχειν οὐκ ἤθελον τούς τε ἐπάρχους σπουδάζοντας αὐτοῖς πρὸς τοῦτο καὶ συνεργοῦντας εἶχον, ἄλλα τε ὅσα βλάπτειν ἢ δι’ ἑαυτῶν ἢ δι’ ἑτέρων ἠδύναντο τοὺς Ἰουδαίους οὐκ ἀπώκνουν. ἔδοξεν οὖν πρεσβευσαμένοις τοῖς Ἱεροσολυμίταις πρὸς τὸν βασιλέα Δαρεῖον κατηγορῆσαι τῶν Σαμαρειτῶν, καὶ πρεσβεύουσιν Ζοροβάβηλος καὶ ἄλλοι τῶν ἀρχόντων τέσσαρες. ὡς δὲ τὰ ἐγκλήματα καὶ τὰς αἰτίας, ἃς κατὰ τῶν Σαμαρέων ἐπέφερον, ἔγνω παρὰ τῶν πρέσβεων ὁ βασιλεύς, δοὺς αὐτοῖς κομίζειν ἐπιστολὴν πρὸς τοὺς ἐπάρχους τῆς Σαμαρείας καὶ τὴν βουλὴν ἀπέπεμψεν. τὰ δὲ γεγραμμένα ἦν τοιάδε· βασιλεὺς Δαρεῖος Ταγανᾷ καὶ Σαμβᾷ τοῖς ἐπάρχοις καὶ Σαμαρειτῶν Σαδράκῃ καὶ Βουήδωνι καὶ τοῖς λοιποῖς συνδούλοις αὐτῶν τοῖς ἐν Σαμαρείᾳ. Ζοροβάβηλος καὶ Ἀνανίας καὶ Μαρδοχαῖος Ἰουδαίων πρεσβευταὶ ᾐτιῶντο ὑμᾶς ὡς ἐνοχλοῦντας αὐτοῖς πρὸς τὴν οἰκοδομίαν τοῦ ναοῦ καὶ μὴ χορηγοῦντας ἃ προσέταξα ὑμῖν εἰς τὰς θυσίας τελεῖν αὐτοῖς ἀναλώματα. βούλομαι οὖν ὑμᾶς ἀναγνόντας τὴν ἐπιστολὴν χορηγεῖν αὐτοῖς ἐκ τοῦ βασιλικοῦ γαζοφυλακείου τῶν φόρων τῆς Σαμαρείας πάνθ’ ὅσα πρὸς θυσίας ἐστὶν αὐτοῖς χρήσιμα, καθὼς οἱ ἱερεῖς ἀξιοῦσιν, ἵνα μὴ διαλείπωσιν καθ’ ἡμέραν θύοντες μηδ’ ὑπὲρ ἐμοῦ καὶ Περσῶν εὐχόμενοι τῷ θεῷ. καὶ ἡ μὲν ἐπιστολὴ ταῦτα περιεῖχεν.", "st": "11.4.9"}, {"sp": "N", "t": "Δαρείου δὲ τελευτήσαντος παραλαβὼν τὴν βασιλείαν ὁ παῖς αὐτοῦ Ξέρξης ἐκληρονόμησεν αὐτοῦ καὶ τὴν πρὸς τὸν θεὸν εὐσέβειάν τε καὶ τιμήν· ἅπαντα γὰρ ἀκολούθως τῷ πατρὶ τὰ πρὸς τὴν θρησκείαν ἐποίησεν καὶ πρὸς τοὺς Ἰουδαίους ἔσχεν φιλοτιμότατα. κατ’ ἐκεῖνον δὲ τὸν καιρὸν ἀρχιερεὺς ἦν Ἰησοῦ παῖς Ἰωάκειμος ὄνομα. ὑπῆρχεν δὲ καὶ ἐν Βαβυλῶνι δίκαιος ἀνὴρ καὶ δόξης ἀπολαύων ἀγαθῆς παρὰ τῷ πλήθει πρῶτος ἱερεὺς τοῦ θεοῦ καλούμενος Ἔζδρας, ὃς τῶν Μωυσέως νόμων ἱκανῶς ἔμπειρος ὢν γίνεται φίλος τῷ βασιλεῖ Ξέρξῃ. γνοὺς δὲ ἀναβῆναι εἰς τὰ Ἱεροσόλυμα καὶ ἐπαγαγέσθαι τινὰς τῶν ἐν Βαβυλῶνι τυγχανόντων Ἰουδαίων παρεκάλεσεν τὸν βασιλέα δοῦναι αὐτῷ πρὸς τοὺς σατράπας τῆς Συρίας ἐπιστολήν, ὑφ’ ἧς αὐτοῖς γνωρισθήσεται τίς εἴη. ὁ δὲ βασιλεὺς γράφει πρὸς τοὺς σατράπας ἐπιστολὴν τοιάνδε· βασιλεὺς βασιλέων Ξέρξης Ἔζδρᾳ ἱερεῖ καὶ ἀναγνώστῃ τῶν τοῦ θεοῦ νόμων χαίρειν. τῆς ἐμαυτοῦ φιλανθρωπίας ἔργον εἶναι νομίσας τὸ τοὺς βουλομένους ἐκ τοῦ Ἰουδαίων ἔθνους καὶ Λευιτῶν ὄντων ἐν τῇ ἡμετέρᾳ βασιλείᾳ συναπαίρειν εἰς τὰ Ἱεροσόλυμα, τοῦτο προσέταξα, καὶ ὁ βουλόμενος ἀπίτω, καθάπερ ἔδοξέν μοι καὶ τοῖς ἑπτά μου συμβούλοις, ὅπως τὰ κατὰ τὴν Ἰουδαίαν ἐπισκέψωνται τῷ νόμῳ τοῦ θεοῦ ἀκολούθως καὶ ἀπενέγκωσι δῶρα τῷ Ἰσραηλιτῶν θεῷ, ἅπερ ηὐξάμην ἐγώ τε καὶ οἱ φίλοι· καὶ ἀργύριον καὶ χρυσίον ὅσον ἂν εὑρεθῇ ἐν τῇ χώρᾳ τῶν Βαβυλωνίων ὠνομασμένον τῷ θεῷ τοῦτο πᾶν εἰς Ἱεροσόλυμα κομισθῆναι τῷ θεῷ εἰς τὰς θυσίας, πάντα τε, ὅσα βούλει ἐξ ἀργύρου καὶ χρυσοῦ κατασκευάσαι, ποιεῖν ἐξέστω σοι μετὰ τῶν ἀδελφῶν. καὶ τὰ δεδομένα σοι ἱερὰ σκεύη ἀναθήσεις καὶ ὅσων ἂν ἐπίνοιαν λάβῃς καὶ ταῦτα προσεξεργάσῃ τὴν εἰς αὐτὰ δαπάνην ποιούμενος ἐκ τοῦ βασιλικοῦ γαζοφυλακείου. ἔγραψα δὲ καὶ τοῖς γαζοφύλαξιν τῆς Συρίας καὶ τῆς Φοινίκης, ἵνα τῶν ὑπὸ Ἔζδρα τοῦ ἱερέως καὶ ἀναγνώστου τῶν τοῦ θεοῦ νόμων ἐπισταλέντων ἐπιμεληθῶσιν. ὅπως δὲ μηδεμίαν ὀργὴν ἐπ’ ἐμὲ λάβῃ τὸ θεῖον ἢ τοὺς ἐμοὺς ἐκγόνους, πάντ’ ἀξιῶ καὶ μέχρι τοῦ πυροῦ κόρων ἑκατὸν ἐπιτελεῖσθαι τῷ θεῷ κατὰ τὸν νόμον. καὶ ὑμῖν δὲ λέγω, ὅπως τοῖς ἱερεῦσιν καὶ Λευίταις καὶ ἱεροψάλταις καὶ θυρωροῖς καὶ ἱεροδούλοις καὶ γραμματεῦσιν τοῦ ἱεροῦ μήτε φόρους ἐπιτάξητε μήτε ἄλλο μηδὲν ἐπίβουλον ἢ φορτικὸν εἰς αὐτοὺς γένηται. καὶ σὺ δέ, Ἔζδρα, κατὰ τὴν τοῦ θεοῦ σοφίαν ἀπόδειξον κριτάς, ὅπως δικάσωσιν ἐν Συρίᾳ καὶ Φοινίκῃ πάσῃ τοὺς ἐπισταμένους σου τὸν νόμον, καὶ τοῖς ἀγνοοῦσιν δὲ παρέξεις αὐτὸν μαθεῖν, ἵνα ἄν τις τῶν ὁμοεθνῶν σου παραβαίνῃ τὸν τοῦ θεοῦ νόμον ἢ τὸν βασιλικόν, ὑπόσχῃ τιμωρίαν, ὡς οὐ κατ’ ἄγνοιαν αὐτὸν παραβαίνων, ἀλλ’ ὡς ἐπιστάμενος μὲν τολμηρῶς δὲ παρακούων καὶ καταφρονῶν. κολασθήσονται δ’ ἤτοι θανάτῳ ἢ ζημίᾳ χρηματικῇ. ἔρρωσο.", "st": "11.5.1"}, {"sp": "N", "t": "Λαβὼν δὲ Ἔζδρας ταύτην τὴν ἐπιστολὴν ὑπερήσθη καὶ τῷ θεῷ προσκυνεῖν ἤρξατο, τῆς τοῦ βασιλέως πρὸς αὐτὸν χρηστότητος ἐκεῖνον αἴτιον ὁμολογῶν γεγενῆσθαι, καὶ διὰ τοῦτο τὴν πᾶσαν αὐτοῦ χάριν ἔλεγεν εἶναι. ἀναγνοὺς δ’ ἐν Βαβυλῶνι τὴν ἐπιστολὴν τοῖς αὐτόθι παροῦσιν Ἰουδαίοις, αὐτὴν μὲν κατέσχεν, τὸ δ’ ἀντίγραφον αὐτῆς πρὸς ἅπαντας ἔπεμψεν τοὺς ὁμοεθνεῖς τοὺς κατὰ τὴν Μηδίαν ὄντας. μαθόντες δὲ οὗτοι τὴν παρὰ τοῦ βασιλέως καὶ πρὸς τὸν θεὸν εὐσέβειαν καὶ πρὸς τὸν Ἔζδραν εὔνοιαν ἅπαντες μὲν ὑπερηγάπησαν, πολλοὶ δ’ αὐτῶν καὶ τὰς κτήσεις ἀναλαβόντες ἦλθον εἰς Βαβυλῶνα ποθοῦντες τῆς εἰς τὰ Ἱεροσόλυμα καθόδου. ὁ δὲ πᾶς λαὸς τῶν Ἰσραηλιτῶν κατὰ χώραν ἔμεινεν· διὸ καὶ δύο φυλὰς εἶναι συμβέβηκεν ἐπί τε τῆς Ἀσίας καὶ τῆς Εὐρώπης Ῥωμαίοις ὑπακουούσας, αἱ δὲ δέκα φυλαὶ πέραν εἰσὶν Εὐφράτου ἕως δεῦρο, μυριάδες ἄπειροι καὶ ἀριθμῷ γνωσθῆναι μὴ δυνάμεναι. πρὸς δὲ Ἔζδραν ἀφικνοῦνται ἱερέων καὶ Λευιτῶν καὶ θυρωρῶν καὶ ἱεροψαλτῶν καὶ ἱεροδούλων πολλοὶ τὸν ἀριθμόν. συναγαγὼν δὲ τοὺς ἐκ τῆς αἰχμαλωσίας εἰς τὸ πέραν τοῦ Εὐφράτου καὶ τρεῖς ἐπιδιατρίψας ἐκεῖ ἡμέρας νηστείαν αὐτοῖς παρήγγειλεν, ὅπως εὐχὰς ποιήσονται τῷ θεῷ περὶ τῆς αὐτῶν σωτηρίας καὶ τοῦ μηδὲν κατὰ τὴν ὁδὸν παθεῖν ἄτοπον ἢ πρὸς τῶν πολεμίων ἤ τινος ἄλλου δυσκόλου προσπεσόντος αὐτοῖς· φθάσας γὰρ ὁ Ἔζδρας εἰπεῖν τῷ βασιλεῖ, ὅτι διασώσει αὐτοὺς ὁ θεός, οὐ κατηξίωσεν ἱππεῖς αὐτὸν αἰτῆσαι τοὺς προπέμψοντας. ποιησάμενοι δὲ τὰς εὐχάς, ἄραντες ἀπὸ τοῦ Εὐφράτου δωδεκάτῃ τοῦ πρώτου μηνὸς τοῦ ἑβδόμου ἔτους τῆς Ξέρξου βασιλείας παρεγένοντο εἰς Ἱεροσόλυμα μηνὶ πέμπτῳ τοῦ αὐτοῦ ἔτους. καὶ παραχρῆμα τοῖς γαζοφύλαξιν ὁ Ἔζδρας οὖσιν ἐκ τοῦ τῶν ἱερέων γένους παρέστησεν τὰ ἱερὰ χρήματα, ἀργυρίου τάλαντα ἑξακόσια πεντήκοντα, σκεύη ἀργυρᾶ ταλάντων ἑκατόν, καὶ χρύσεα σκεύη ταλάντων εἴκοσι, καὶ χαλκᾶ σκεύη χρυσοῦ κρείττονα σταθμὸν ἔχοντα ταλάντων δώδεκα· ταῦτα γὰρ ἐδωρήσατο ὁ βασιλεὺς καὶ οἱ σύμβουλοι αὐτοῦ καὶ πάντες οἱ ἐν Βαβυλῶνι μένοντες Ἰσραηλῖται. παραδοὺς δὲ ταῦτα τοῖς ἱερεῦσιν ὁ Ἔζδρας ἀπέδωκε τῷ θεῷ τὰς ἐκ τῶν ὁλοκαυτώσεων νενομισμένας γίνεσθαι θυσίας, ταύρους δώδεκα ὑπὲρ κοινῆς τοῦ λαοῦ σωτηρίας, κριοὺς ἐνενήκοντα, ἄρνας ἑβδομηκονταδύο, ἐρίφους εἰς παραίτησιν τῶν ἡμαρτημένων δεκαδύο. τοῖς δὲ τοῦ βασιλέως οἰκονόμοις καὶ τοῖς ἐπάρχοις τῆς κοίλης Συρίας καὶ Φοινίκης τὰ γράμματα τοῦ βασιλέως ἀπέδωκεν. οἱ δὲ τὸ προσταχθὲν ὑπ’ αὐτοῦ ποιεῖν ἀνάγκην ἔχοντες ἐτίμησάν τε τὸ ἔθνος καὶ πρὸς πᾶσαν αὐτῷ χρείαν συνήργησαν.", "st": "11.5.2"}, {"sp": "N", "t": "Ταῦτα μὲν οὖν καὶ αὐτὸς ἐβουλεύσατο Ἔσδρας, προεχώρησεν δ’ αὐτῷ κρίναντος αὐτὸν ἄξιον οἶμαι τοῦ θεοῦ τῶν βουληθέντων διὰ χρηστότητα καὶ δικαιοσύνην. χρόνῳ δὲ ὕστερον προσελθόντων αὐτῷ τινων κατηγορούντων, ὥς τινες τοῦ πλήθους καὶ τῶν ἱερέων καὶ Λευιτῶν παραβεβήκασι τὴν πολιτείαν καὶ λελύκασιν τοὺς πατρίους νόμους ἀλλοεθνεῖς ἠγμένοι γυναῖκας καὶ τὸ ἱερατικὸν γένος συγκεχύκασιν, δεομένων τε βοηθῆσαι τοῖς νόμοις, μὴ κοινὴν ἐπὶ πάντας ὀργὴν λαβὼν πάλιν αὐτοὺς εἰς συμφορὰς ἐμβάλῃ, διέρρηξε μὲν εὐθὺς ὑπὸ λύπης τὴν ἐσθῆτα καὶ τὴν κεφαλὴν ἐσπάρασσεν καὶ τὰ γένεια ὑβρίζων ἐπὶ τὴν γῆν τε ἑαυτὸν ἔρριψεν ἐπὶ τῷ τὴν αἰτίαν ταύτην λαβεῖν τοὺς πρώτους τοῦ λαοῦ. λογιζόμενος δὲ ὅτι, ἐὰν ἐκβαλεῖν αὐτοὺς τὰς γυναῖκας καὶ τὰ ἐξ αὐτῶν προστάξῃ τέκνα, οὐκ ἀκουσθήσεται, διέμενεν ἐπὶ τῆς γῆς κείμενος. συνέτρεχον οὖν πρὸς αὐτὸν οἱ μέτριοι πάντες κλαίοντες καὶ αὐτοὶ καὶ τῆς ἐπὶ τῷ γεγενημένῳ λύπης συμμεταλαμβάνοντες. ἀναστὰς δὲ ἀπὸ τῆς γῆς ὁ Ἔσδρας καὶ τὰς χεῖρας ἀνατείνας εἰς τὸν οὐρανόν, αἰσχύνεσθαι μὲν ἔλεγεν αὐτὸν ἀναβλέψαι διὰ τὰ ἡμαρτημένα τῷ λαῷ, ὃς τῆς μνήμης ἐξέβαλεν τὰ τοῖς πατράσιν ἡμῶν διὰ τὴν ἀσέβειαν αὐτῶν συμπεσόντα, παρεκάλει δὲ τὸν θεὸν σπέρμα τι καὶ λείψανον ἐκ τῆς τότε συμφορᾶς αὐτῶν καὶ αἰχμαλωσίας περισώσαντα καὶ πάλιν εἰς Ἱεροσόλυμα καὶ τὴν οἰκείαν γῆν ἀποκαταστήσαντα [καὶ τοὺς Περσῶν βασιλέας ἀναγκάσαντα] λαβεῖν οἶκτον αὐτῶν, καὶ συγγνωμονῆσαι τοῖς νῦν ἡμαρτημένοις, ἄξια μὲν θανάτου πεποιηκόσιν, ὂν δὲ ἐπὶ τῇ τοῦ θεοῦ χρηστότητι καὶ τοὺς τοιούτους ἀφιέναι τῆς κολάσεως.", "st": "11.5.3"}, {"sp": "N", "t": "Καὶ ὁ μὲν ἐπαύσατο τῶν εὐχῶν· θρηνούντων δὲ πάντων, ὅσοι πρὸς αὐτὸν σὺν γυναιξὶν καὶ τέκνοις συνῆλθον, Ἀχόνιός τις ὀνόματι πρῶτος τῶν Ἱεροσολυμιτῶν, προσελθὼν αὐτοὺς μὲν ἁμαρτεῖν ἔλεγεν ἀλλοεθνεῖς ἐνοικισαμένους γυναῖκας, ἔπειθε δ’ αὐτὸν ἐξορκίσαι πάντας ἐκβαλεῖν αὐτὰς καὶ τὰ ἐξ αὐτῶν γεγενημένα, κολασθήσεσθαι δὲ τοὺς οὐχ ὑπακούσαντας τῷ νόμῳ. πεισθεὶς οὖν τούτοις ὁ Ἔζδρας ἐποίησεν ὀμόσαι τοὺς φυλάρχους τῶν ἱερέων καὶ τῶν Λευιτῶν καὶ Ἰσραηλιτῶν ἀποπέμψασθαι τὰς γυναῖκας καὶ τὰ τέκνα κατὰ τὴν Ἀχονίου συμβουλίαν. λαβὼν δὲ τοὺς ὅρκους εὐθὺς ὥρμησεν ἀπὸ τοῦ ἱεροῦ εἰς τὸ παστοφόριον τὸ Ἰωάννου τοῦ Ἐλιασίβου καὶ μηδενὸς ὅλως διὰ τὴν λύπην γευσάμενος ἐκείνην τὴν ἡμέραν διήγαγεν αὐτόθι. γενομένου δὲ κηρύγματος ὥστε πάντας τοὺς ἀπὸ τῆς αἰχμαλωσίας συνελθεῖν εἰς Ἱεροσόλυμα, ὡς τῶν ἐν δυσὶν ἢ τρισὶν ἡμέραις οὐκ ἀπαντησάντων ἀπαλλοτριωθησομένων τοῦ πλήθους καὶ τῆς οὐσίας αὐτῶν κατὰ τὴν τῶν πρεσβυτέρων κρίσιν ἀφιερωθησομένης, συνῆλθον ἐκ τῆς Ἰουδαϊκῆς καὶ Βενιαμίτιδος ἐν τρισὶν ἡμέραις εἰκάδι τοῦ ἐνάτου μηνός, ὃς κατὰ μὲν Ἑβραίους Ξένιος, κατὰ δὲ Μακεδόνας Ἀπελλαῖος καλεῖται. καθισάντων δὲ ἐν τῷ ὑπαίθρῳ τοῦ ἱεροῦ, παρόντων ἅμα καὶ τῶν πρεσβυτέρων καὶ ὑπὸ τοῦ κρύους ἀηδῶς διακειμένων, ἀναστὰς Ἔζδρας ᾐτιᾶτο ἐκείνους λέγων παρανομῆσαι γήμαντας οὐκ ἐξ ὁμοφύλων· νῦν μέντοι γε ποιήσειν αὐτοὺς τῷ μὲν θεῷ κεχαρισμένα συμφέροντα δὲ αὐτοῖς ἀποπεμψαμένους τὰς γυναῖκας. οἱ δὲ ποιήσειν μὲν τοῦτο πάντες ἐξεβόησαν, τὸ δὲ πλῆθος εἶναι πολύ, καὶ τὴν ὥραν τοῦ ἔτους χειμέριον, καὶ τὸ ἔργον οὐ μιᾶς οὐδὲ δευτέρας ἡμέρας ὑπάρχειν. ἀλλ’ οἵ τε ἡγεμόνες τούτοις καὶ οἱ συνοικοῦντες ταῖς ἀλλοφύλοις παραγενέσθωσαν λαβόντες χρόνον καὶ πρεσβυτέρους ἐξ οὗ ἂν θελήσωσιν τόπου τοὺς συνεπισκεψομένους τὸ τῶν γεγαμηκότων πλῆθος. καὶ ταῦτα δόξαν αὐτοῖς ἀρξάμενοι τῇ νουμηνίᾳ τοῦ δεκάτου μηνὸς ἀναζητεῖν τοὺς συνοικοῦντας ταῖς ἀλλοεθνέσιν εὗρον ἕως τῆς τοῦ μηνὸς τοῦ ἐχομένου νουμηνίας ποιησάμενοι τὴν ἔρευναν πολλοὺς ἔκ τε τῶν Ἰησοῦ ἐκγόνων τοῦ ἀρχιερέως καὶ τῶν ἱερέων καὶ τῶν Λευιτῶν καὶ τῶν Ἰσραηλιτῶν, οἳ καὶ τὰς γυναῖκας καὶ τὰ ἐξ αὐτῶν γεγενημένα τῆς τῶν νόμων φυλακῆς ἢ τῶν πρὸς αὐτὰ φίλτρων ποιούμενοι πλείονα λόγον εὐθὺς ἐξέβαλον καὶ θυσίας ἐξευμενίζοντες τὸν θεὸν ἐπήνεγκαν κριοὺς καταθύσαντες αὐτῷ. τὰ δὲ ὀνόματα αὐτῶν λέγειν οὐκ ἔδοξεν ἡμῖν ἀναγκαῖον εἶναι. τὸ μὲν οὖν ἁμάρτημα τὸ περὶ τοὺς γάμους τῶν προειρημένων οὕτως ἐπανορθώσας Ἔζδρας ἐκαθάρισεν τὴν περὶ ταῦτα συνήθειαν, ὥστ’ αὐτὴν τοῦ λοιποῦ μόνιμον εἶναι.", "st": "11.5.4"}, {"sp": "N", "t": "Τῷ δ’ ἑβδόμῳ μηνὶ τὴν σκηνοπηγίαν ἑορτάζοντες καὶ σχεδὸν ἅπαντος τοῦ λαοῦ συνεληλυθότος ἐπ’ αὐτήν, ἀνελθόντες εἰς τὸ ἀνειμένον τοῦ ναοῦ πρὸς τὴν πύλην τὴν ἐπὶ τὴν ἀνατολὴν ἀποβλέπουσαν ἐδεήθησαν τοῦ Ἔζδρα τοὺς νόμους αὐτοῖς ἀναγνῶναι τοὺς Μωυσέως. ὁ δὲ μέσος τοῦ πλήθους σταθεὶς ἀνέγνω καὶ τοῦτ’ ἐποίησεν ἀπ’ ἀρχομένης ἡμέρας ἕως μεσημβρίας· οἱ δὲ ἀκούσαντες ἀναγινωσκομένων τῶν νόμων δίκαιοι μὲν πρὸς τὸ παρὸν καὶ τὸ μέλλον ἐδιδάσκοντο εἶναι, περὶ δὲ τῶν παρῳχημένων ἐδυσφόρουν καὶ μέχρι τοῦ δακρύειν προήχθησαν ἐνθυμούμενοι πρὸς αὑτούς, ὅτι μηδὲν ἂν τῶν πεπειραμένων κακῶν ἔπαθον, εἰ τὸν νόμον διεφύλαττον. ὁ δὲ Ἔζδρας οὕτως ὁρῶν αὐτοὺς ἔχοντας ἐκέλευσεν ἀπιέναι πρὸς αὑτοὺς καὶ μὴ δακρύειν· εἶναι γὰρ ἑορτὴν καὶ μὴ δεῖν ἐν αὐτῇ κλαίειν· οὐ γὰρ ἐξεῖναι· προυτρέπετο δὲ μᾶλλον πρὸς εὐωχίαν ὁρμήσαντας ποιεῖν τὰ πρόσφορα τῇ ἑορτῇ καὶ κεχαρισμένα, καὶ τὴν μετάνοιαν καὶ λύπην τὴν ἐπὶ τοῖς ἔμπροσθεν ἐξημαρτημένοις ἀσφάλειάν τε ἕξειν καὶ φυλακὴν τοῦ μηδὲν ὅμοιον συμπεσεῖν. οἱ δὲ ταῦτα Ἔζδρα παραινοῦντος ἑορτάζειν ἤρξαντο καὶ τοῦτο ποιοῦντες ἐφ’ ἡμέρας ὀκτὼ ἐν ταῖς σκηναῖς ἀνεχώρησαν εἰς τὰ οἰκεῖα μετὰ ὕμνων τοῦ θεοῦ τῆς ἐπανορθώσεως τῶν περὶ τὸ πολίτευμα παρανομηθέντων Ἔζδρᾳ χάριν εἰδότες. ᾧ συνέβη μετὰ τὴν παρὰ τῷ λαῷ δόξαν γηραιῷ τελευτῆσαι τὸν βίον καὶ ταφῆναι μετὰ πολλῆς φιλοτιμίας ἐν Ἱεροσολύμοις. ὑπὸ δὲ τὸν αὐτὸν καιρὸν καὶ Ἰωακείμου τοῦ ἀρχιερέως ἀποθανόντος παῖς αὐτοῦ Ἐλεάσιβος τὴν ἀρχιερωσύνην διεδέξατο.", "st": "11.5.5"}, {"sp": "N", "t": "Τῶν δ’ αἰχμαλωτισθέντων τις Ἰουδαίων οἰνοχόος τοῦ βασιλέως Ξέρξου Νεεμίας ὄνομα περιπατῶν πρὸ τῆς μητροπόλεως τῶν Περσῶν Σούσων, ξένων τινῶν ἀπὸ μακρᾶς ὁδοιπορίας εἰς τὴν πόλιν εἰσιόντων ἐπακούσας ἑβραϊστὶ πρὸς ἀλλήλους ὁμιλούντων προσελθὼν αὐτοῖς ἐπυνθάνετο, πόθεν εἶεν παραγενόμενοι. ἀποκριναμένων δ’ ἥκειν ἐκ τῆς Ἰουδαίας, πῶς αὐτῶν ἔχει τὸ πλῆθος καὶ ἡ μητρόπολις Ἱεροσόλυμα, πάλιν ἤρξατο πυνθάνεσθαι. κακῶς δ’ ἔχειν εἰπόντων, καθῃρῆσθαι γὰρ εἰς ἔδαφος τὰ τείχη καὶ τὰ πέριξ ἔθνη πολλὰ διατιθέναι κακὰ τοὺς Ἰουδαίους, ἡμέρας μὲν κατατρεχόντων τὴν χώραν καὶ διαρπαζόντων, τῆς δὲ νυκτὸς κακῶς ἀπεργαζομένων, ὡς πολλοὺς ἐκ τῆς χώρας καὶ ἐξ αὐτῶν τῶν Ἱεροσολύμων αἰχμαλώτους ἀπῆχθαι καὶ τὰς ὁδοὺς πλήρεις εὑρίσκεσθαι καθ’ ἡμέραν νεκρῶν, ἐδάκρυσεν ὁ Νεεμίας ἐλεήσας τῆς συμφορᾶς τοὺς ὁμοφύλους, καὶ ἀναβλέψας εἰς τὸν οὐρανόν, ἄχρι τίνος, εἶπεν, ὦ δέσποτα, περιόψει ταῦτα πάσχον τὸ ἔθνος ἡμῶν οὕτως ἅρπαγμα πάντων καὶ λάφυρον γενόμενον; διατρίβοντος δ’ αὐτοῦ πρὸς τῇ πύλῃ καὶ ταῦτα ἀποδυρομένου προελθών τις ἤγγειλεν αὐτῷ μέλλειν ἤδη κατακλίνεσθαι τὸν βασιλέα. ὁ δ’ εὐθὺς ὡς εἶχεν μηδὲ ἀπολουσάμενος διακονήσων ἔσπευσεν τῷ βασιλεῖ τὴν ἐπὶ τοῦ πότου διακονίαν. ὡς δὲ μετὰ τὸ δεῖπνον ὁ βασιλεὺς διεχύθη καὶ ἡδίων αὑτοῦ γενόμενος ἀπέβλεψεν εἰς τὸν Νεεμίαν, κατεσκυθρωπακότα θεασάμενος, διὰ τί κατηφὴς εἴη ἀνέκρινεν. ὁ δὲ τοῦ θεοῦ δεηθεὶς χάριν τινὰ καὶ πειθὼ παρασχεῖν αὐτῷ λέγοντι, πῶς, φησίν, ὦ βασιλεῦ, δύναμαί σοι μὴ βλέπεσθαι τοιοῦτος μηδὲ τὴν ψυχὴν ἀλγεῖν, ὅπου τῆς πατρίδος μου Ἱεροσολύμων, ἐν ᾗ τάφοι καὶ μνήματα προγόνων τῶν ἐμῶν εἰσιν, ἀκούω βεβλῆσθαι κατὰ τῆς γῆς τὰ τείχη καὶ τὰς πύλας ἐμπεπρησμένας αὐτῆς; ἀλλὰ χάρισαί μοι πορευθέντι τὸ τεῖχος ἀνεγεῖραι καὶ τοῦ ἱεροῦ τὸ λεῖπον προσοικοδομῆσαι. ὁ δὲ βασιλεὺς διδόναι τε τὴν δωρεὰν κατένευσεν καὶ πρὸς τοὺς σατράπας κομίσαι γράμματα, ὅπως τιμῆς τε αὐτὸν ἀξιώσωσι καὶ πᾶσαν παράσχωσιν χορηγίαν εἰς ἅπερ βούλεται. πέπαυσο δή, φησί, λυπούμενος καὶ χαίρων ἡμῖν τοῦ λοιποῦ διακόνει. ὁ μὲν οὖν Νεεμίας προσκυνήσας τῷ θεῷ καὶ τῷ βασιλεῖ τῆς ὑποσχέσεως εὐχαριστήσας τὸ κατηφὲς τοῦ προσώπου καὶ συγκεχυμένον ἀπεκάθηρεν τῇ περὶ τῶν ἐπηγγελμένων ἡδονῇ. καλέσας δὲ αὐτὸν τῇ ἐπιούσῃ δίδωσιν αὐτῷ πρὸς Ἀδδαῖον ἐπιστολὴν κομίσαι τὸν τῆς Συρίας καὶ Φοινίκης καὶ Σαμαρείας ἔπαρχον, ἐν ᾗ περί τε τῆς τιμῆς τοῦ Νεεμίου καὶ χορηγίας τῆς εἰς τὴν οἰκοδομίαν ἐπεστάλκει.", "st": "11.5.6"}, {"sp": "N", "t": "Γενόμενος οὖν ἐν Βαβυλῶνι καὶ πολλοὺς τῶν ὁμοφύλων ἐθελοντὶ ἀκολουθοῦντας αὐτῷ παραλαβὼν ἧκεν εἰς Ἱεροσόλυμα πέμπτον καὶ εἰκοστὸν ἔτος ἤδη βασιλεύοντος Ξέρξου, καὶ δείξας τῷ θεῷ τὰς ἐπιστολὰς ἀποδίδωσιν τῷ Ἀδδαίῳ καὶ τοῖς ἄλλοις ἐπάρχοις, καὶ συγκαλέσας πάντα τὸν λαὸν εἰς Ἱεροσόλυμα στὰς ἐν μέσῳ τῷ ἱερῷ τοιούτους ἐποιήσατο πρὸς αὐτὸν τοὺς λόγους· ἄνδρες Ἰουδαῖοι, τὸν μὲν θεὸν ἴστε μνήμῃ τῶν πατέρων Ἀβράμου καὶ Ἰσάκου καὶ Ἰακώβου παραμένοντα καὶ διὰ τῆς ἐκείνων δικαιοσύνης οὐκ ἐγκαταλείποντα τὴν ὑπὲρ ὑμῶν πρόνοιαν· ἀμέλει συνήργησέν μοι παρὰ τοῦ βασιλέως λαβεῖν ἐξουσίαν, ὅπως ὑμῶν τὸ τεῖχος ἀναστήσω καὶ τὸ λείψανον τοῦ ἱεροῦ τελειώσω. βούλομαι δ’ ὑμᾶς τὴν τῶν γειτονευόντων ἡμῖν ἐθνῶν δυσμένειαν σαφῶς εἰδότας, καὶ ὅτι πρὸς τὴν οἰκοδομίαν, εἰ μάθοιεν περὶ ταύτην ἡμᾶς φιλοτιμουμένους, ἐνστήσονται καὶ πολλὰ πραγματεύσονται πρὸς αὐτὴν ἡμῖν ἐμπόδια, θαρρεῖν μὲν τῷ θεῷ πρῶτον ὡς καὶ πρὸς τὴν ἐκείνων ἀπέχθειαν στησομένους, μήτε δ’ ἡμέρας μήτε νυκτὸς αὐτοὺς ἀνιέναι τῆς οἰκοδομίας, ἀλλὰ πάσῃ σπουδῇ χρωμένους συνέχειν τὸ ἔργον, ὥς γε καιρὸς ἴδιός ἐστιν. ταῦτ’ εἰπὼν ἐκέλευσεν εὐθὺς τοὺς ἄρχοντας μετρῆσαι τὸ τεῖχος καὶ διανεῖμαι τὴν ἐργασίαν αὐτοῦ τῷ λαῷ κατὰ κώμας τε καὶ πόλεις κατὰ τὸ ἑκάστοις δυνατόν, ὑποσχόμενος δὲ καὶ αὐτὸς μετὰ τῶν οἰκετῶν συλλήψεσθαι πρὸς τὴν οἰκοδομίαν διέλυσε τὴν ἐκκλησίαν. καὶ οἱ Ἰουδαῖοι πρὸς τὸ ἔργον παρεσκευάζοντο. ἐκλήθησαν δὲ τὸ ὄνομα ἀφ’ ἧς ἡμέρας ἐκ Βαβυλῶνος ἀνέβησαν ἐκ τῆς Ἰούδα φυλῆς, ἧς πρώτης ἐλθούσης εἰς ἐκείνους τοὺς τόπους αὐτοί τε καὶ ἡ χώρα τὴν προσηγορίαν αὐτοῖς μετέλαβον.", "st": "11.5.7"}, {"sp": "N", "t": "Ἀκούσαντες δὲ τὴν τῶν τειχῶν οἰκοδομὴν σπευδομένην Ἀμμανῖται καὶ Μωαβῖται καὶ Σαμαρεῖται καὶ πάντες οἱ ἐν τῇ [κοίλῃ] Συρίᾳ νεμόμενοι χαλεπῶς ἔφερον καὶ διετέλουν ἐπιβουλὰς αὐτοῖς συντιθέντες τὴν προαίρεσιν αὐτῶν ἐμποδίζοντες, πολλούς τε τῶν Ἰουδαίων ἀπέκτειναν καὶ αὐτὸν ἐζήτουν τὸν Νεεμίαν διαφθεῖραι μισθούμενοί τινας τῶν ἀλλοφύλων, ἵν’ αὐτὸν ἀνέλωσιν. εἰς φόβον δὲ καὶ ταραχὴν αὐτοὺς ἐνέβαλλον καὶ φήμας αὐτοῖς διέστελλον ὡς πολλῶν ἐπιστρατεύειν αὐτοῖς μελλόντων ἐθνῶν, ὑφ’ ὧν ἐκταρασσόμενοι μικροῦ τῆς οἰκοδομίας ἀπέστησαν. τὸν δὲ Νεεμίαν οὐδὲν τούτων ἐξέστησεν τῆς σπουδῆς τῆς περὶ τὸ ἔργον, ἀλλὰ στῖφός τι φυλακῆς ἕνεκα τοῦ σώματος περιβαλλόμενος ἀτρύτως ὑπέμενεν, ὑπὸ τῆς περὶ τὸ ἔργον ἐπιθυμίας ἀναισθητῶν καὶ τῆς ταλαιπωρίας. οὕτως δὲ καὶ συντεταμένως καὶ προνοητικῶς αὐτοῦ τῆς σωτηρίας εἶχεν οὐχὶ φοβούμενος τὸν θάνατον, ἀλλὰ πεπεισμένος, ὅτι μετὰ τὴν αὐτοῦ τελευτὴν οὐκέτ’ αὐτοῦ τοῖς πολίταις ἀναστήσεται τὰ τείχη. ἐκέλευσεν δὲ ἑξῆς τοὺς οἰκοδομοῦντας ὅπλα περιζωννυμένους ἐργάζεσθαι, καὶ ὁ μὲν οἰκοδόμος μάχαιραν εἶχεν καὶ ὁ τὴν ὕλην παρακομίζων, θυρεοὺς δ’ ἔγγιστα αὐτῶν ἐκέλευσεν κεῖσθαι καὶ σαλπιγκτὰς ἀπὸ πεντακοσίων ἔστησεν ποδῶν προστάξας, ἂν ἐπιφανῶσιν οἱ πολέμιοι, τοῦτο σημῆναι τῷ λαῷ, ἵν’ ὁπλισάμενοι μάχωνται καὶ μὴ γυμνοῖς αὐτοῖς ἐπιπέσωσιν. αὐτὸς δὲ νύκτωρ περιήρχετο τῆς πόλεως τὸν κύκλον οὐδὲν κάμνων οὔτε τοῖς ἔργοις οὔτε τῇ διαίτῃ οὔτε τοῖς ὕπνοις· οὐδενὶ γὰρ τούτων πρὸς ἡδονὴν ἀλλὰ πρὸς ἀνάγκην ἐχρῆτο. καὶ ταύτην ὑπέμεινε τὴν ταλαιπωρίαν ἐπὶ ἔτη δύο καὶ μῆνας τέσσαρας· ἐν τούτῳ γὰρ τῷ χρόνῳ τοῖς Ἱεροσολύμοις ἀνῳκοδομήθη τὸ τεῖχος, ὀγδόῳ καὶ εἰκοστῷ τῆς Ξέρξου βασιλείας ἔτει μηνὶ ἐνάτῳ. τέλος δὲ τῶν τειχῶν λαβόντων Νεεμίας καὶ τὸ πλῆθος ἔθυσαν τῷ θεῷ ὑπὲρ τῆς τούτων οἰκοδομίας καὶ διῆγον ἐφ’ ἡμέρας ὀκτὼ εὐωχούμενοι. τὰ μὲν οὖν ἔθνη τὰ ἐν τῇ Συρίᾳ κατῳκημένα τῆς τῶν τειχῶν οἰκοδομίας πέρας ἔχειν ἀκουσθείσης ἐδυσφόρει. Νεεμίας δὲ τὴν πόλιν ὁρῶν ὀλιγανθρωπουμένην τοὺς ἱερεῖς τε καὶ Λευίτας παρεκάλεσεν τὴν χώραν ἐκλιπόντας μετελθεῖν εἰς τὴν πόλιν καὶ μένειν ἐν αὐτῇ κατασκευάσας τὰς οἰκίας αὐτοῖς ἐκ τῶν ἰδίων ἀναλωμάτων· τόν τε γεωργοῦντα λαὸν τὰς δεκάτας τῶν καρπῶν ἐκέλευσε φέρειν εἰς Ἱεροσόλυμα, ἵνα τρέφεσθαι διηνεκῶς ἔχοντες οἱ ἱερεῖς καὶ Λευῖται μὴ καταλείπωσι τὴν θρησκείαν. καὶ οἱ μὲν ἡδέως ὑπήκουσαν οἷς Νεεμίας διετάξατο, πολυανθρωποτέραν δὲ τὴν τῶν Ἱεροσολυμιτῶν πόλιν οὕτως συνέβη γενέσθαι. πολλὰ δὲ καὶ ἄλλα καλὰ καὶ ἐπαίνων ἄξια φιλοτιμησάμενος ὁ Νεεμίας ἐτελεύτησεν εἰς γῆρας ἀφικόμενος. ἀνὴρ δὲ ἐγένετο χρηστὸς τὴν φύσιν καὶ δίκαιος καὶ περὶ τοὺς ὁμοεθνεῖς φιλοτιμότατος, μνημεῖον αἰώνιον αὐτῷ καταλιπὼν τὰ τῶν Ἱεροσολύμων τείχη. ταῦτα μὲν οὖν ἐπὶ Ξέρξου βασιλέως ἐγένετο.", "st": "11.5.8"}, {"sp": "N", "t": "Τελευτήσαντος δὲ Ξέρξου τὴν βασιλείαν εἰς τὸν υἱὸν Κῦρον, ὃν Ἀρταξέρξην Ἕλληνες καλοῦσιν, συνέβη μεταβῆναι. τούτου τὴν Περσῶν ἔχοντος ἡγεμονίαν ἐκινδύνευσεν τὸ τῶν Ἰουδαίων ἔθνος ἅπαν σὺν γυναιξὶ καὶ τέκνοις ἀπολέσθαι. τὴν δ’ αἰτίαν μετ’ οὐ πολὺ δηλώσομεν· πρέπει γὰρ τὰ τοῦ βασιλέως διηγεῖσθαι πρῶτον, ὡς ἔγημεν Ἰουδαίαν γυναῖκα τοῦ γένους οὖσαν τοῦ βασιλικοῦ, ἣν καὶ σῶσαι τὸ ἔθνος ἡμῶν λέγουσιν. παραλαβὼν γὰρ τὴν βασιλείαν ὁ Ἀρταξέρξης καὶ καταστήσας ἀπὸ Ἰνδίας ἄχρι Αἰθιοπίας τῶν σατραπειῶν ἑκατὸν καὶ εἰκοσιεπτὰ οὐσῶν ἄρχοντας, τῷ τρίτῳ τῆς βασιλείας ἔτει τούς τε φίλους καὶ τὰ Περσῶν ἔθνη καὶ τοὺς ἡγεμόνας αὐτῶν ὑποδεξάμενος ἑστιᾷ πολυτελῶς, οἷον εἰκὸς παρὰ βασιλεῖ τοῦ πλούτου παρασκευαζομένῳ τὴν ἐπίδειξιν ποιήσασθαι, ἐπὶ ἡμέρας ἑκατὸν ὀγδοήκοντα. ἔπειτα τὰ ἔθνη καὶ τοὺς πρεσβευτὰς αὐτῶν ἐν Σούσοις ἐπὶ ἡμέρας κατευώχησεν ἑπτά. τὸ δὲ συμπόσιον ἦν αὐτοῖς τὸν τρόπον τοῦτον γεγενημένον· σκήνωμα πηξάμενος ἐκ χρυσέων καὶ ἀργυρέων κιόνων ὕφη λίνεα καὶ πορφύρεα κατ’ αὐτῶν διεπέτασεν, ὥστε πολλὰς μυριάδας κατακλίνεσθαι. διηκονοῦντο δ’ ἐκπώμασι χρυσέοις καὶ τοῖς διὰ λίθου πολυτελοῦς εἰς τέρψιν ἅμα καὶ θέαν πεποιημένοις. προσέταττεν δὲ καὶ τοῖς διακόνοις μὴ βιάζεσθαι πίνειν τὸ ποτὸν αὐτοῖς συνεχῶς προσφέροντας, ὡς καὶ παρὰ Πέρσαις γίγνεται, ἀλλ’ ἐπιτρέπειν αὐτοῖς καὶ πρὸς ὃ βούλεται τῶν κατακειμένων ἕκαστος φιλοφρονεῖσθαι. διαπέμψας δὲ καὶ κατὰ τὴν χώραν παρήγγειλεν ἀνεῖσθαι τῶν ἔργων ἀφιεμένους καὶ ἑορτάζειν ὑπὲρ τῆς βασιλείας αὐτοῦ πολλαῖς ἡμέραις. ὁμοίως τε τῶν γυναικῶν ἡ βασίλισσα Ἄστη συνήγαγεν συμπόσιον ἐν τοῖς βασιλείοις, ἣν ἐπιδεῖξαι βουλόμενος τοῖς ἑστιωμένοις ὁ βασιλεὺς πέμψας ἐκέλευσεν αὐτὴν εἰς τὸ συμπόσιον ἥκειν κάλλει τὰς γυναῖκας ἁπάσας ὑπερβάλλουσαν. ἡ δὲ φυλακῇ τῶν παρὰ Πέρσαις νόμων, οἳ τοῖς ἀλλοτρίοις βλέπεσθαι τὰς γυναῖκας ἀπηγορεύκασιν, οὐκ ἐπορεύετο πρὸς τὸν βασιλέα, καὶ πολλάκις τοὺς εὐνούχους ἀποστέλλοντος πρὸς αὐτὴν οὐδὲν ἧττον ἐνέμεινεν παραιτουμένη τὴν ἄφιξιν, ὡς εἰς ὀργὴν παροξυνθέντα τὸν βασιλέα λῦσαι μὲν τὸ συμπόσιον, ἀναστάντα δὲ καὶ τοὺς ἑπτὰ τῶν Περσῶν, οἳ τὴν τῶν νόμων ἐξήγησιν ἔχουσι παρ’ αὐτοῖς, καλέσαντα κατηγορεῖν τῆς γυναικὸς καὶ λέγειν, ὡς ὑβρισθείη πρὸς αὐτῆς· κληθεῖσα γὰρ ὑπ’ αὐτοῦ πολλάκις εἰς τὸ συμπόσιον ὑπήκουσεν οὐδὲ ἅπαξ. προσέταξεν οὖν δηλοῦν, τίνα κατ’ αὐτῆς νόμον ὁρίζουσιν. ἑνὸς δ’ ἐξ αὐτῶν Μουχαίου ὄνομα εἰπόντος οὐκ αὐτῷ μόνῳ ταύτην γεγονέναι τὴν ὕβριν, ἀλλὰ πᾶσι Πέρσαις, οἷς κινδυνεύεται καταφρονουμένοις ὑπὸ τῶν γυναικῶν αἴσχιστα διαγεγονέναι τὸν βίον· οὐδεμία γὰρ τοῦ συνοικοῦντος ἀνδρὸς αἰδῶ ποιήσεται παράδειγμα τὴν τῆς βασιλίσσης ὑπερηφανίαν πρὸς σὲ τὸν κρατοῦντα ἁπάντων ἔχουσα. παρακελευομένου δὲ τὴν οὕτως ἐνυβρίζουσαν αὐτῷ ζημιῶσαι μεγάλην ζημίαν καὶ τοῦτο ποιήσαντα διαγγεῖλαι τοῖς ἔθνεσιν τὰ περὶ τῆς βασιλίσσης κεκυρωμένα, ἔδοξε τὴν Ἄστην ἐκβαλεῖν καὶ δοῦναι τὴν ἐκείνης τιμὴν ἑτέρᾳ γυναικί.", "st": "11.6.1"}, {"sp": "N", "t": "Διακείμενος δὲ πρὸς αὐτὴν ἐρωτικῶς καὶ μὴ φέρων τὴν διάζευξιν, καταλλαγῆναι μὲν αὐτῇ διὰ τὸν νόμον οὐκ ἐδύνατο, λυπούμενος δὲ ὡς ἐπ’ ἀδυνάτοις οἷς ἤθελεν διετέλει. βλέποντες δ’ αὐτὸν οὕτως ἔχοντα χαλεπῶς οἱ φίλοι συνεβούλευον τὴν μὲν τῆς γυναικὸς μνήμην καὶ τὸν ἔρωτα μηδὲν ὠφελούμενον ἐκβαλεῖν, ζητῆσαι δὲ περιπέμψαντα καθ’ ὅλην τὴν οἰκουμένην παρθένους εὐπρεπεῖς, ὧν τὴν προκριθεῖσαν ἕξειν γυναῖκα· σβέννυσθαι γὰρ τὸ πρὸς τὴν προτέραν φιλόστοργον ἑτέρας ἐπεισαγωγῇ, καὶ τὸ πρὸς ἐκείνην εὔνουν ἀποσπώμενον κατὰ μικρὸν γίνεσθαι τῆς συνούσης. πεισθεὶς δὲ τῇ συμβουλίᾳ ταύτῃ προσέταξέ τισιν ἐπιλεξαμένους τὰς εὐδοκιμούσας ἐπ’ εὐμορφίᾳ τῶν ἐν τῇ βασιλείᾳ παρθένων ἀγαγεῖν πρὸς αὐτόν. συναχθεισῶν δὲ πολλῶν εὑρέθη τις ἐν Βαβυλῶνι κόρη τῶν γονέων ἀμφοτέρων ὀρφανὴ παρὰ τῷ θείῳ Μαρδοχαίῳ, τοῦτο γὰρ ἦν ὄνομα αὐτῷ, τρεφομένη· οὗτος δ’ ἦν ἐκ τῆς Βενιαμίτιδος φυλῆς, τῶν δὲ πρώτων παρὰ τοῖς Ἰουδαίοις. πασῶν δὲ τὴν Ἐσθῆρα συνέβαινεν, τοῦτο γὰρ ἦν αὐτῇ τοὔνομα, τῷ κάλλει διαφέρειν καὶ τὴν χάριν τοῦ προσώπου τὰς ὄψεις τῶν θεωμένων μᾶλλον ἐπάγεσθαι. παραδοθεῖσα δὲ αὕτη τινὶ τῶν εὐνούχων εἰς ἐπιμέλειαν πάσης ἐτύγχανε προνοίας ἀρωμάτων ἀφθονίᾳ καὶ πολυτελείᾳ τῶν ἀλειμμάτων ὧν χρῄζει τὰ σώματα καταρδομένη, καὶ τούτων ἀπέλαυον ἐπὶ μῆνας ἓξ τετρακόσιαι τὸν ἀριθμὸν οὖσαι. ὅτε δ’ ἐνόμιζεν ἀποχρώντως τῷ προειρημένῳ χρόνῳ τὴν ἐπιμέλειαν ἔχειν τὰς παρθένους καὶ τοῦ βαδίζειν αὐτὰς ἐπὶ κοίτην βασιλέως ἀξίας ἤδη γεγονέναι, καθ’ ἑκάστην ἡμέραν μίαν ἔπεμπεν τῷ βασιλεῖ συνεσομένην. ὁ δὲ πλησιάζων εὐθὺς ἀπέπεμπεν πρὸς τὸν εὐνοῦχον. ἀφικομένης δὲ τῆς Ἐσθήρας πρὸς αὐτὸν ἡσθεὶς αὐτῇ καὶ πεσὼν τῆς κόρης εἰς ἔρωτα νομίμως αὐτὴν ἄγεται γυναῖκα καὶ γάμους αὐτῇ ποιεῖται δωδεκάτῳ μηνὶ ἑβδόμου ἔτους τῆς αὐτοῦ βασιλείας, Ἀδέρῳ δὲ καλουμένῳ. διέπεμψε δὲ τοὺς ἀγγάρους λεγομένους εἰς πᾶν ἔθνος ἑορτάζειν τοὺς γάμους παραγγέλλων, αὐτὸς δὲ Πέρσας [καὶ τοὺς Μήδους] καὶ τοὺς πρώτους τῶν ἐθνῶν ἑστιᾷ ἐπὶ μῆνα ὅλον ὑπὲρ τῶν γάμων αὐτοῦ, εἰσελθούσῃ δὲ εἰς τὸ βασίλειον περιτίθησι τὸ διάδημα, καὶ συνῴκησεν οὕτως Ἐσθήρα μὴ ποιήσασα φανερὸν αὐτῷ τὸ ἔθνος, ἐξ οὗπερ εἴη τυγχάνουσα. μεταβὰς δὲ ὁ θεῖος αὐτῆς ἐκ Βαβυλῶνος εἰς Σοῦσα τῆς Περσίδος αὐτόθι διῆγεν ἑκάστης ἡμέρας πρὸς τοῖς βασιλείοις διατρίβων καὶ πυνθανόμενος περὶ τῆς κόρης, τίνα διάγει τρόπον· ἔστεργεν γὰρ αὐτὴν ὡς αὑτοῦ θυγατέρα.", "st": "11.6.2"}, {"sp": "N", "t": "Ἔθηκε δὲ καὶ νόμον ὁ βασιλεὺς ὥστε μηδένα τῶν ἰδίων αὐτῷ προσιέναι μὴ κληθέντα, ὁπηνίκα ἐπὶ τοῦ θρόνου καθέζοιτο. περιεστήκεσαν δὲ τὸν θρόνον αὐτοῦ πελέκεις ἔχοντες ἄνθρωποι πρὸς τὸ κολάζειν τοὺς προσιόντας ἀκλήτους τῷ θρόνῳ. καθῆστο μέντοι λύγον χρυσέαν ἔχων αὐτὸς ὁ βασιλεύς, ἣν ὅτε τινὰ σώζειν ἤθελεν τῶν ἀκλήτων προσιόντων ἐξέτεινεν πρὸς αὐτόν· ὁ δὲ ἁπτόμενος αὐτῆς ἀκίνδυνος ἦν. καὶ περὶ μὲν τούτων ἀρκούντως ἡμῖν δεδήλωται.", "st": "11.6.3"}, {"sp": "N", "t": "Χρόνῳ δ’ ὕστερον ἐπιβουλευσάντων τῷ βασιλεῖ Βαγαθώου καὶ Θεοδοσίτου Βαρνάβαζος τῶν εὐνούχων οἰκέτης τοῦ ἑτέρου τὸ γένος ὢν Ἰουδαῖος συνεὶς τὴν ἐπιβουλὴν τῷ θείῳ κατεμήνυσε τῆς γυναικὸς τοῦ βασιλέως, Μαρδοχαῖος δὲ διὰ τῆς Ἐσθήρας φανεροὺς ἐποίησε τῷ βασιλεῖ τοὺς ἐπιβουλεύοντας. ταραχθεὶς δὲ ὁ βασιλεὺς τἀληθὲς ἐξεῦρεν καὶ τοὺς μὲν εὐνούχους ἀνεσταύρωσεν, τῷ δὲ Μαρδοχαίῳ τότε μὲν οὐδὲν παρέσχεν ὡς αἰτίῳ τῆς σωτηρίας γεγονότι, μόνον δὲ αὐτοῦ τὸ ὄνομα τοῖς τὰ ὑπομνήματα συγγραφομένοις ἐκέλευσε σημειώσασθαι καὶ προσμένειν αὐτὸν τοῖς βασιλείοις ὄντα φίλον ἀναγκαιότατον τῷ βασιλεῖ.", "st": "11.6.4"}, {"sp": "N", "t": "Ἀμάνην δὲ Ἀμαδάθου μὲν υἱὸν τὸ γένος δὲ Ἀμαληκίτην εἰσιόντα πρὸς τὸν βασιλέα προσεκύνουν οἵ τε ξένοι καὶ Πέρσαι ταύτην αὐτῷ τὴν τιμὴν παρ’ αὐτῶν Ἀρταξέρξου κελεύοντος γενέσθαι. Μαρδοχαίου δὲ διὰ σοφίαν καὶ τὸν οἴκοθεν αὐτοῦ νόμον οὐ προσκυνοῦντος ἄνθρωπον, παραφυλάξας ὁ Ἀμάνης ἐπυνθάνετο, πόθεν εἴη. μαθὼν δ’ αὐτὸν ὄντα Ἰουδαῖον ἠγανάκτησεν καὶ πρὸς ἑαυτὸν εἶπεν, ὡς οἱ μὲν ἐλεύθεροι Πέρσαι προσκυνοῦσιν αὐτόν, οὗτος δὲ δοῦλος ὢν οὐκ ἀξιοῖ τοῦτο ποιεῖν. καὶ τιμωρήσασθαι θελήσας τὸν Μαρδοχαῖον αὐτὸν μὲν αἰτήσασθαι πρὸς κόλασιν παρὰ τοῦ βασιλέως μικρὸν ἡγήσατο, τὸ ἔθνος δὲ αὐτοῦ διέγνω πᾶν ἀφανίσαι· καὶ γὰρ φύσει τοῖς Ἰουδαίοις ἀπηχθάνετο, ὅτι καὶ τὸ γένος τῶν Ἀμαληκιτῶν, ἐξ ὧν ἦν αὐτός, ὑπ’ αὐτῶν διέφθαρτο. προσελθὼν οὖν τῷ βασιλεῖ κατηγόρει λέγων ἔθνος εἶναι πονηρόν, διεσπάρθαι δὲ τοῦτο κατὰ τῆς ὑπ’ αὐτοῦ βασιλευομένης οἰκουμένης, ἄμικτον ἀσύμφυλον οὔτε θρησκείαν τὴν αὐτὴν τοῖς ἄλλοις ἔχον οὔτε νόμοις χρώμενον ὁμοίοις, ἐχθρὸν δὲ καὶ τοῖς ἔθεσι καὶ τοῖς ἐπιτηδεύμασιν τῷ σῷ λαῷ καὶ ἅπασιν ἀνθρώποις. τοῦτο τὸ ἔθνος, εἴ τινα θέλεις τοῖς ὑπηκόοις εὐεργεσίαν καταθέσθαι, κελεύσεις πρόρριζον ἀπολέσθαι μηδέ τι αὐτοῦ λείψανον καταλιπεῖν μήτ’ εἰς δουλείαν τινῶν φυλαχθέντων μήτε αἰχμαλωσίᾳ. ἵνα μέντοι μὴ ζημιωθῇς τοὺς φόρους τοὺς παρ’ αὐτῶν γινομένους, ἐκ τῆς ἰδίας οὐσίας αὐτὸς ἐπηγγείλατο μυριάδας δώσειν ταλάντων ἀργυρίου τέσσαρας, ὅπου ἂν κελεύσῃ. ταῦτα δὲ τὰ χρήματα παρέχειν ἡδέως ἔλεγεν, ἵν’ ἀπὸ τούτων εἰρηνευθῇ τῶν κακῶν ἡ βασιλεία.", "st": "11.6.5"}, {"sp": "N", "t": "Ταῦτα τοῦ Ἀμάνου ἀξιώσαντος ὁ βασιλεὺς καὶ τὸ ἀργύριον αὐτῷ χαρίζεται καὶ τοὺς ἀνθρώπους, ὥστε ποιεῖν αὐτοὺς ὅ τι βούλεται. τυχὼν δὲ ὧν ἐπεθύμει Ἀμάνης παραχρῆμα πέμπει διάταγμα ὡς τοῦ βασιλέως εἰς ἅπαντα τὰ ἔθνη περιέχον τοῦτον τὸν τρόπον· βασιλεὺς μέγας Ἀρταξέρξης τοῖς ἀπὸ Ἰνδικῆς ἕως τῆς Αἰθιοπίας ἑπτὰ καὶ εἴκοσι καὶ ἑκατὸν σατραπειῶν ἄρχουσι τάδε γράφει. πολλῶν ἐθνῶν ἄρξας καὶ πάσης ἧς ἐβουλήθην κρατήσας οἰκουμένης καὶ μηδὲν ὑπὸ τῆς ἐξουσίας ὑπερήφανον μηδὲ σκαιὸν εἰς τοὺς ἀρχομένους ἀναγκασθεὶς ἁμαρτεῖν, ἀλλ’ ἐπιεικῆ καὶ πρᾷον ἐμαυτὸν παρασχὼν καὶ προνοησάμενος εἰρήνης καὶ εὐνομίας αὐτοῖς, ἐζήτουν πῶς εἰς ἅπαντα τούτων ἀπολαύειν αὐτοῖς γένοιτο. τοῦ δὲ διὰ σωφροσύνην καὶ δικαιοσύνην παρ’ ἐμοὶ τὴν πρώτην μοῖραν δόξης καὶ τιμῆς ἔχοντος καὶ μετ’ ἐμὲ δευτέρου διὰ πίστιν καὶ βέβαιον εὔνοιαν Ἀμάνου κηδεμονικῶς ὑποδείξαντός μοι παντάπασιν ἀνθρώποις ἀναμεμῖχθαι δυσμενὲς ἔθνος καὶ τοῖς νόμοις ἀλλόκοτον καὶ τοῖς βασιλεῦσιν ἀνυπότακτον καὶ παρηλλαγμένον τοῖς ἔθεσι καὶ τὴν μοναρχίαν μισοῦν καὶ δύσνουν τοῖς ἡμετέροις πράγμασι, κελεύω τοὺς δηλουμένους ὑπὸ τοῦ δευτέρου μου πατρὸς Ἀμάνου πάντας σὺν γυναιξὶ καὶ τέκνοις ἀπολέσαι μηδεμίαν φειδῶ ποιησαμένους, μηδ’ ἐλέῳ πλέον ἢ τοῖς ἐπεσταλμένοις πεισθέντας παρακοῦσαι τῶν γεγραμμένων. καὶ τοῦτο γενέσθαι βούλομαι τῇ τετράδι καὶ δεκάτῃ τοῦ δωδεκάτου μηνὸς τοῦ ἐνεστῶτος ἔτους, ὅπως οἱ πανταχόθεν ἡμῖν πολέμιοι μιᾷ ἡμέρᾳ διαφθαρέντες τοῦ λοιποῦ μετ’ εἰρήνης ἡμῖν τὸν βίον διάγειν παρέχωσι. τούτου κομισθέντος τοῦ προστάγματος εἰς τὰς πόλεις καὶ τὴν χώραν ἕτοιμοι πάντες ἐπὶ τὴν τῶν Ἰουδαίων ἀπώλειαν εἰς τὴν προειρημένην ἡμέραν ἐγίνοντο· ἐσπεύδετο δὲ τοῦτο καὶ ἐν τῇ Σούσῃ. ὁ μὲν οὖν βασιλεὺς καὶ ὁ Ἀμάνης πρὸς εὐωχίαις καὶ πότοις ἦσαν, ἐν ταραχῇ δ’ ἦν ἡ πόλις.", "st": "11.6.6"}, {"sp": "N", "t": "Ὁ δὲ Μαρδοχαῖος μαθὼν τὸ γινόμενον περιρρηξάμενος τὴν ἐσθῆτα καὶ σάκκον ἐνδυσάμενος καὶ καταχεάμενος σποδιὰν διὰ τῆς πόλεως ἐφέρετο βοῶν, ὅτι μηδὲν ἀδικῆσαν ἔθνος ἀναιρεῖται, καὶ τοῦτο λέγων ἕως τῶν βασιλείων ἦλθεν καὶ πρὸς αὐτοῖς ἔστη· οὐ γὰρ ἐξῆν εἰσελθεῖν αὐτῷ τοιοῦτον περικειμένῳ σχῆμα. τὸ δ’ αὐτὸ καὶ πάντες ἐποίησαν οἱ ἐν ταῖς πόλεσιν Ἰουδαῖοι, ἐν αἷς τὰ περὶ τούτων προετέθη γράμματα, θρηνοῦντες καὶ τὰς κατηγγελμένας αὐτοῖς συμφορὰς ὀδυρόμενοι. ὡς δ’ ἀπήγγειλάν τινες τῇ βασιλίσσῃ τὸν Μαρδοχαῖον ἐν οὕτως οἰκτρῷ σχήματι πρὸ τῆς αὐλῆς ἑστῶτα, ταραχθεῖσα πρὸς τὴν ἀκοὴν ἐξέπεμπεν τοὺς μεταμφιάσοντας αὐτόν. οὐ πεισθέντος δὲ ἀποδύσασθαι τὸν σάκκον, οὐ γὰρ ἐφ’ ᾧ τοῦτον ἀναγκασθείη λαβεῖν δεινῷ πεπαῦσθαι τοῦτο, προσκαλεσαμένη τὸν εὐνοῦχον Ἀχράθεον, καὶ γὰρ ἔτυχεν αὐτῇ παρών, ἀπέστειλεν Μαρδοχαίῳ γνωσόμενον, τίνος συμβεβηκότος αὐτῷ σκυθρωποῦ πενθεῖ καὶ τὸ σχῆμα τοῦτο περικείμενος οὐδ’ αὐτῆς παρακαλούσης ἀπέθετο. ὁ δὲ Μαρδοχαῖος ἐπέδειξε τῷ εὐνούχῳ τὴν αἰτίαν τό τε γράμμα τὸ κατὰ τῶν Ἰουδαίων εἰς ἅπασαν τὴν ὑπὸ τῷ βασιλεῖ χώραν διαπεμφθὲν καὶ τὴν τῶν χρημάτων ὑπόσχεσιν, ᾗ τὴν ἀπώλειαν τοῦ ἔθνους ᾐτεῖτο παρὰ τοῦ βασιλέως Ἀμάνης. δοὺς δὲ αὐτῷ καὶ τὸ ἀντίγραφον τῶν ἐν Σούσοις προτεθέντων κομίσαι τῇ Ἐσθῆρι καὶ περὶ τούτων δεηθῆναι τοῦ βασιλέως ἐνετέλλετο καὶ σωτηρίας ἕνεκεν τοῦ ἔθνους μὴ ἀδοξῆσαι λαβεῖν σχῆμα ταπεινόν, ᾧ παραιτήσεται τοὺς Ἰουδαίους κινδυνεύοντας ἀπολέσθαι· τὸν γὰρ τὴν δευτέραν ἔχοντα τῷ βασιλεῖ τιμὴν Ἀμάνην κατηγορήσαντ’ αὐτῶν παρωξυγκέναι κατ’ αὐτῶν τὸν βασιλέα. ταῦτα γνοῦσα πέμπει πάλιν πρὸς Μαρδοχαῖον δηλοῦσα, ὅτι μήτε κληθείη πρὸς τοῦ βασιλέως καὶ ὁ εἰσερχόμενος πρὸς αὐτὸν ἄκλητος ἀποθνήσκει, πλὴν εἰ μή τινα σώζειν βουλόμενος προτείνειεν τὸν χρυσῆν ῥάβδον· ᾧ γὰρ τοῦτο ποιήσειεν ὁ βασιλεὺς ἀκλήτῳ προσελθόντι, οὗτος οὐκ ἀποθνήσκει μόνος, ἀλλὰ συγγνώμης τυχὼν σώζεται. Μαρδοχαῖος δὲ τούτους κομίσαντος αὐτῷ τοῦ εὐνούχου παρὰ τῆς Ἐσθῆρος τοὺς λόγους ἀπαγγέλλειν ἐκέλευσεν αὐτῇ, μὴ τὴν ἰδίαν οὕτως σκοπεῖν σωτηρίαν, ἀλλὰ τὴν κοινὴν τοῦ ἔθνους· εἰ γὰρ ἀμελήσειεν τούτου νῦν, ἔσεσθαι μὲν αὐτῷ βοήθειαν παρὰ τοῦ θεοῦ πάντως, αὐτὴν δὲ καὶ τὸν πατρῷον οἶκον αὐτῆς ὑπὸ τῶν ὀλιγωρηθέντων διαφθαρήσεσθαι. ἡ δὲ Ἐσθήρα ἐπέστειλεν μὲν τῷ Μαρδοχαίῳ τὸν αὐτὸν πέμψασα διάκονον εἰς Σοῦσα πορευθέντι τοὺς ἐκεῖ Ἰουδαίους εἰς ἐκκλησίαν συναγαγεῖν καὶ νηστεῦσαι πάντων ἀποσχομένους ὑπὲρ αὐτῆς ἐπὶ τρεῖς ἡμέρας, τὸ δ’ αὐτὸ ποιήσασα μετὰ τῶν θεραπαινίδων τότε προσελεύσεσθαι τῷ βασιλεῖ παρὰ τὸν νόμον ὑπισχνεῖτο, κἂν ἀποθανεῖν δέῃ τοῦτο ὑπομενεῖν.", "st": "11.6.7"}, {"sp": "N", "t": "Καὶ Μαρδοχαῖος μὲν κατὰ τὰς Ἐσθῆρος ἐντολὰς τόν τε λαὸν ἐποίησεν νηστεῦσαι καὶ τὸν θεὸν αὐτὸς ἱκέτευσε μηδὲ νῦν ὑπεριδεῖν αὐτοῦ τὸ ἔθνος ἀπολλύμενον, ἀλλ’ ὡς καὶ πρότερον αὐτοῦ πολλάκις προενόησεν καὶ ἁμαρτόντι συνέγνω, καὶ νῦν αὐτὸ ῥύσασθαι τῆς κατηγγελμένης ἀπωλείας· οὐδὲ γὰρ ἁμαρτόν τι κινδυνεύειν ἀκλεῶς ἀποθανεῖν, ἀλλ’ αὐτὸν γὰρ εἶναι τὴν αἰτίαν τῆς Ἀμάνου ὀργῆς, ὅτι μὴ προσεκύνησα μηδ’ ἣν σοί, δέσποτα, φησίν, τιμὴν παρεῖχον, ταύτην ἐκείνῳ παρασχεῖν ὑπέμενον, ὀργισθεὶς ταῦτα κατὰ τῶν μὴ παραβαινόντων τοὺς σοὺς νόμους ἐμηχανήσατο. τὰς δ’ αὐτὰς ἠφίει καὶ τὸ πλῆθος φωνάς, παρακαλοῦν προνοῆσαι τὸν θεὸν τῆς σωτηρίας αὐτῶν καὶ τοὺς ἐν ἁπάσῃ τῇ γῇ Ἰσραηλίτας ἐξελέσθαι τῆς μελλούσης συμφορᾶς· καὶ γὰρ πρὸ ὀφθαλμῶν αὐτὴν εἶχον ἤδη καὶ προσεδόκων. ἱκέτευε δὲ καὶ Ἐσθήρα τὸν θεὸν τῷ πατρίῳ νόμῳ ῥίψασα κατὰ τῆς γῆς ἑαυτὴν καὶ πενθικὴν ἐσθῆτα περιθεμένη, καὶ τροφῇ καὶ ποτῷ καὶ τοῖς ἡδέσιν ἀποταξαμένη τρισὶν ἡμέραις ᾔτει τὸν θεὸν ἐλεηθῆναι μὲν αὐτήν, δόξαι δ’ ὀφθεῖσαν τῷ βασιλεῖ πιθανὴν μὲν τοὺς λόγους παρακαλοῦσαν τὸ δὲ εἶδος εὐπρεπεστέραν τῆς τάχιον οὖσαν, ἵν’ ἀμφοτέροις καὶ πρὸς τὴν παραίτησιν ὀργῆς, εἴ τι παροξυνθείη πρὸς αὐτὴν ὁ βασιλεύς, χρήσαιτο καὶ πρὸς τὴν συνηγορίαν τῶν ὁμοεθνῶν ἐν τοῖς ἐσχάτοις σαλευόντων, μῖσός τε γενέσθαι τῷ βασιλεῖ πρὸς τοὺς ἐχθροὺς τῶν Ἰουδαίων καὶ τὴν ἀπώλειαν αὐτοῖς τὴν μέλλουσαν, ἐὰν ὀλιγωρηθῶσιν ὑπ’ αὐτοῦ, κατασκευάσοντας.", "st": "11.6.8"}, {"sp": "N", "t": "Ταῦθ’ ἱκετεύουσα τὸν θεὸν ἐπὶ τρεῖς ἡμέρας ἀποδύεται μὲν τὴν ἐσθῆτα ἐκείνην καὶ τὸ σχῆμα μεταβάλλει, κοσμησαμένη δ’ ὡς ἐχρῆν τὴν βασίλισσαν σὺν δυσὶν θεραπαίναις, ὧν ἡ μὲν ἐπερειδομένην αὐτὴν κούφως ἔφερεν, ἡ δὲ ἑπομένη τὸ βαθὺ τοῦ ἐνδύματος καὶ μέχρι τῆς γῆς κεχυμένον ἄκροις ἀπῃώρει τοῖς δακτύλοις, ἥκει πρὸς τὸν βασιλέα, μεστὴ μὲν τὸ πρόσωπον ἐρυθήματος, προσηνὲς δὲ καὶ σεμνὸν ἐπικειμένη τὸ κάλλος. εἰσῄει δὲ πρὸς αὐτὸν μετὰ δέους. ὡς δὲ κατὰ πρόσωπον αὐτοῦ καθεζομένου ἐπὶ τοῦ θρόνου γίνεται τὸν βασιλικὸν περικειμένου κόσμον, οὗτος δ’ ἦν ἐκ ποικίλης μὲν ἐσθῆτος, χρυσοῦ δὲ καὶ λίθου πολυτελοῦς, φοβερώτερον καὶ δι’ αὐτὰ μᾶλλον θεασαμένη καί τι κἀκείνου προσιδόντος αὐτὴν ἀπηνέστερον καὶ διακεκαυμένῳ ὑπὸ τῆς ὀργῆς τῷ προσώπῳ, πάρεσις αὐτὴν εὐθὺς λαμβάνει καὶ τοῖς παρὰ πλευρὸν οὖσιν ἀχανὴς ἐπέπεσεν. ὁ δὲ βασιλεὺς κατὰ βούλησιν οἶμαι τοῦ θεοῦ τὴν διάνοιαν μετέβαλεν καὶ δείσας περὶ τῇ γυναικί, μὴ καὶ πάθῃ τι τῶν χειρόνων ὑπὸ τοῦ φόβου, ἀνεπήδησεν ἐκ τοῦ θρόνου, καὶ ταῖς ἀγκάλαις αὐτὴν ὑπολαβὼν ἀνεκτᾶτο κατασπαζόμενός τε καὶ προσομιλῶν ἡδέως καὶ θαρρεῖν παρακαλῶν καὶ μηδὲν ὑποπτεύειν σκυθρωπόν, ὅτι πρὸς αὐτὸν ἄκλητος ἔλθοι· τὸν γὰρ νόμον τοῦτον πρὸς τοὺς ὑπηκόους κεῖσθαι, τὴν δὲ ὁμοίως αὐτῷ βασιλεύουσαν πᾶσαν ἔχειν ἄδειαν. ταῦτα λέγων τὸ σκῆπτρον αὐτῆς ἐνετίθει τῇ χειρὶ καὶ τὴν ῥάβδον ἐξέτεινεν ἐπὶ τὸν αὐχένα αὐτῆς διὰ τὸν νόμον εὐλαβείας αὐτὴν ἀπολύων. ἡ δ’ ὑπὸ τούτων ἀναζωπυρήσασα, δέσποτ’, εἶπεν, οὐκ ἔχω σοι τὸ αἰφνίδιον τοῦ συμβεβηκότος μοι ῥᾳδίως εἰπεῖν· ὡς γὰρ εἶδόν σε μέγαν καὶ καλὸν καὶ φοβερόν, εὐθὺς ὑπεχώρει μου τὸ πνεῦμα καὶ κατελειπόμην ὑπὸ τῆς ψυχῆς. μόλις δ’ αὐτῆς καὶ ταῦτα φθεγγομένης καὶ μετὰ ἀσθενείας αὐτόν τε ἀγωνία καὶ ταραχὴ κατελάμβανεν καὶ τὴν Ἐσθῆρ’ εὐψυχεῖν καὶ τὰ κρείττω προσδοκᾶν παρεθάρρυνεν, ὡς αὐτοῦ καὶ τὰ ἡμίση τῆς βασιλείας, εἰ δέοιτο τούτων, παραχωρήσοντος αὐτῇ. ἡ δὲ Ἐσθήρα ἐφ’ ἑστίασιν αὐτὸν μετὰ Ἀμάνου τοῦ φίλου πρὸς αὐτὴν ἐλθεῖν ἠξίωσεν· παρεσκευακέναι γὰρ αὐτὴν δεῖπνον ἔλεγεν. ὡς δ’ ἐπένευσεν καὶ παρῆσαν, μεταξὺ πίνων τὴν Ἐσθῆρα ἐκέλευσε δηλοῦν αὐτῷ, τί βούλεται· μηδενὸς γὰρ ἀτυχήσειν, μηδ’ ἂν τὸ μέρος τῆς βασιλείας ἐθελήσῃ [λαβεῖν]. ἡ δὲ εἰς τὴν ἐπιοῦσαν ἀνεβάλλετο φράζειν αὐτῷ τὴν αὐτῆς βούλησιν, εἰ πάλιν ἔλθοι πρὸς αὐτὴν μετὰ Ἀμάνου ἐφ’ ἑστίασιν.", "st": "11.6.9"}, {"sp": "N", "t": "Τοῦ δὲ βασιλέως ὑποσχομένου ὁ Ἀμάνης ἐξῆλθεν περιχαρὴς ἐπὶ τῷ μόνον ἠξιῶσθαι συνδειπνεῖν τῷ βασιλεῖ παρὰ τῇ Ἐσθήρᾳ, καὶ ὅτι μηδεὶς τοσαύτης ἄλλος τυγχάνει παρὰ τοῖς βασιλεῦσι τιμῆς. ἰδὼν δ’ ἐν τῇ αὐλῇ Μαρδοχαῖον ὑπερηγανάκτησεν· οὐδὲν γὰρ αὐτῷ παρ’ αὐτοῦ θεασαμένου πρὸς τιμὴν ἐγένετο. καὶ παρελθὼν πρὸς αὑτὸν τὴν γυναῖκα Γάζασαν ἐκάλεσεν καὶ τοὺς φίλους. ὧν παρόντων διηγεῖτο τὴν τιμήν, ἧς οὐ παρὰ τοῦ βασιλέως ἀπολαύοι μόνον, ἀλλὰ καὶ παρὰ τῆς βασιλίσσης· καὶ γὰρ τήμερον ὡς δειπνήσειεν παρ’ αὐτῇ μόνος σὺν τῷ βασιλεῖ, κληθείη πάλιν εἰς τὴν ἐπιοῦσαν. ἔλεγέν τε μὴ ἀρέσκεσθαι Μαρδοχαῖον ὁρῶντα ἐν τῇ αὐλῇ τὸν Ἰουδαῖον. τῆς δὲ γυναικὸς αὐτοῦ Γαζάσης εἰπούσης κελεῦσαι ξύλον κοπῆναι πηχῶν ἑξήκοντα καὶ πρωὶ παρὰ τοῦ βασιλέως αἰτησάμενον ἀνασταυρῶσαι τὸν Μαρδοχαῖον, ἐπαινέσας τὴν γνώμην προσέταξεν τοῖς οἰκέταις ξύλον ἑτοιμασαμένους στῆσαι τοῦτο ἐν τῇ αὐλῇ πρὸς τιμωρίαν Μαρδοχαίῳ. καὶ τοῦτο μὲν ἦν ἕτοιμον· ὁ δὲ θεὸς κατεγέλα τῆς Ἀμάνου πονηρᾶς ἐλπίδος καὶ τὸ συμβησόμενον εἰδὼς ἐτέρπετο τῷ γενησομένῳ· τοῦ γὰρ βασιλέως διὰ νυκτὸς ἐκείνης ἀφαιρεῖται τὸν ὕπνον. ὁ δ’ οὐ βουλόμενος ἀργῶς ἀπολέσαι τὴν ἀγρυπνίαν, ἀλλ’ εἴς τι τῶν τῇ βασιλείᾳ διαφερόντων αὐτὴν ἀναλῶσαι, τὸν γραμματέα κομίσαντα καὶ τῶν πρὸ αὐτοῦ βασιλέων τὰ ὑπομνήματα καὶ τῶν ἰδίων πράξεων ἀναγινώσκειν αὐτῷ προσέταξεν. κομίσαντος δὲ καὶ ἀναγινώσκοντος εὑρέθη τις δι’ ἀριστείαν ἔν τινι γέρας εἰληφὼς χώραν, ἧς καὶ τὸ ὄνομα ἐγέγραπτο. ἕτερον δὲ διὰ πίστιν τετυχηκότα δωρεᾶς μηνύων ἦλθεν καὶ ἐπὶ Γαβαταῖον καὶ Θεοδέστην τοὺς ἐπιβουλεύσαντας εὐνούχους τῷ βασιλεῖ, ὧν μηνυτὴς Μαρδοχαῖος ἦν γεγενημένος. φράσαντος δὲ τοῦτο μόνον τοῦ γραμματέως καὶ μεταβαίνοντος εἰς ἑτέραν πρᾶξιν ἐπέσχεν ὁ βασιλεὺς πυνθανόμενος, εἰ μὴ ἔχει γέρας αὐτῷ δοθὲν ἀναγεγραμμένον. ὁ δ’ ὡς ἔφη μηδὲν εἶναι, κελεύσας ἡσυχάζειν, τίς ἡ τῆς νυκτὸς ὥρα, παρὰ τῶν ἐπὶ τούτῳ τεταγμένων ἐπυνθάνετο. μαθὼν δ’, ὡς ὄρθρος ἐστὶν ἤδη, προσέταξεν τῶν φίλων ὃν ἂν πρὸ τῆς αὐλῆς εὕρωσιν ἤδη παρόντα τοῦτον αὐτῷ δηλοῦν. ἔτυχέν τε ὥστε Ἀμάνην εὑρεθῆναι· θᾶττον γὰρ τῆς συνήθους ὥρας ἐληλύθει περὶ τοῦ Μαρδοχαίου θανάτου δεησόμενος αὐτοῦ. τῶν οὖν θεραπόντων εἰπόντων, ὅτι Ἀμάνης εἴη πρὸ τῆς αὐλῆς, ἐκέλευσεν αὐτὸν εἰσκαλέσαι. εἰσελθόντος δέ φίλον, εἶπεν, εἰδὼς ἐμαυτῷ σὲ μόνον εὔνουν συμβουλεῦσαί μοι παρακαλῶ, πῶς ἂν τιμήσαιμι τινὰ στεργόμενον ὑπ’ ἐμοῦ σφόδρα τῆς ἐμαυτοῦ μεγαλοφροσύνης ἀξίως. ὁ δὲ Ἀμάνης λογισάμενος, ἣν ἂν δῷ γνώμην ταύτην δώσειν ὑπὲρ αὐτοῦ, φιλεῖσθαι γὰρ ἑαυτὸν ὑπὸ τοῦ βασιλέως μόνον, ἣν ᾤετο ἀρίστην εἶναι ταύτην φανερὰν ἐποίησεν. εἶπεν γάρ εἰ βούλοιο τὸν ἄνθρωπον ὃν φῂς ἀγαπᾶν δόξῃ περιβαλεῖν, ποίησον ἐφ’ ἵππου βαδίζειν τὴν αὐτὴν ἐσθῆτά σοι φοροῦντα καὶ περιαυχένιον χρυσοῦν ἔχοντα καὶ προάγοντα τῶν ἀναγκαίων φίλων ἕνα κηρύσσειν δι’ ὅλης τῆς πόλεως, ὅτι ταύτης τυγχάνει τῆς τιμῆς ὃν ἂν ὁ βασιλεὺς τιμήσῃ. ὁ μὲν οὖν Ἀμάνης ταῦτα συνεβούλευσεν οἰόμενος εἰς αὐτὸν ἥξειν τοῦτο τὸ γέρας. ὁ δὲ βασιλεὺς ἡσθεὶς τῇ παραινέσει προελθών. φησίν, ἔχεις γὰρ καὶ τὸν ἵππον καὶ τὴν στολὴν καὶ τὸν στρεπτόν. ἐπιζήτησον Μαρδοχαῖον τὸν Ἰουδαῖον καὶ ταῦτα ἐκείνῳ δοὺς προάγων αὐτοῦ τὸν ἵππον, σὺ γάρ, ἔφη, μοι φίλος ἀναγκαῖος, ἴσθι διάκονος ὧν χρηστὸς σύμβουλος ἐγένου. ταῦτα δὲ αὐτῷ παρ’ ἡμῶν ἔσται σώσαντί μου τὴν ψυχήν. τούτων ἀκούσας παρὰ πᾶσαν ἐλπίδα τὴν διάνοιαν συνεχύθη καὶ πληγεὶς ὑπὸ ἀμηχανίας ἔξεισιν ἄγων τὸν ἵππον καὶ τὴν πορφύραν καὶ τὸ χρυσοῦν περιαυχένιον, καὶ τὸν Μαρδοχαῖον εὑρὼν πρὸ τῆς αὐλῆς σάκκον ἐνδεδυμένον ἐκέλευσεν ἀποθέμενον ἐνδύσασθαι τὴν πορφύραν. ὁ δὲ οὐκ εἰδὼς τἀληθές, ἀλλὰ χλευάζεσθαι νομίζων ὦ κάκιστε πάντων ἀνθρώπων, εἶπεν, οὕτως ἡμῶν ταῖς συμφοραῖς ἐπεγγελᾷς; πεισθεὶς δ’, ὡς ὁ βασιλεὺς αὐτῷ γέρας τοῦτ’ εἴη δεδωκὼς ἀντὶ τῆς σωτηρίας, ἣν αὐτῷ παρέσχεν τοὺς ἐπιβουλεύσαντας εὐνούχους ἐλέγξας, ἐνδύεται τὴν πορφύραν, ἣν ὁ βασιλεὺς φορῶν ἀεὶ διετέλει, καὶ περιτίθεται τὸ περιαυχένιον, καὶ ἐπιβὰς ἐπὶ τὸν ἵππον ἐν κύκλῳ περιῄει τὴν πόλιν Ἀμάνου προάγοντος καὶ κηρύσσοντος, ὅτι τοῦτ’ ἔσται παρὰ τοῦ βασιλέως ᾧ ἂν στέρξῃ καὶ τιμῆς ἄξιον δοκιμάσῃ. ἐπεὶ δ’ ἐκπεριῆλθον τὴν πόλιν, ὁ μὲν Μαρδοχαῖος εἰσῄει πρὸς τὸν βασιλέα, Ἀμάνης δ’ ὑπ’ αἰσχύνης πρὸς αὑτὸν παραγίνεται καὶ μετὰ δακρύων τῇ γυναικὶ καὶ τοῖς. φίλοις τὰ συμβεβηκότα διηγεῖτο. οἱ δ’ οὐκέτ’ ἀμύνασθαι τὸν Μαρδοχαῖον ἔλεγον δυνήσεσθαι· τὸν γὰρ θεὸν εἶναι σὺν αὐτῷ.", "st": "11.6.10"}, {"sp": "N", "t": "Ταῦτα δὲ τούτων ἔτι πρὸς ἀλλήλους ὁμιλούντων ἧκον οἱ τῆς Ἐσθήρας εὐνοῦχοι τὸν Ἀμάνην ἐπὶ τὸ δεῖπνον ἐπισπεύδοντες. Σαβουχάδας δὲ τῶν εὐνούχων εἷς ἰδὼν τὸν σταυρὸν ἐν τῇ Ἀμάνου οἰκίᾳ πεπηγότα, ὃν ἐπὶ Μαρδοχαῖον παρεσκευάκεισαν, καὶ πυθόμενος παρά τινος τῶν οἰκετῶν, ἐπὶ τίνα τοῦτον ἦσαν ἑτοιμασάμενοι, γνούς, ὡς ἐπὶ τὸν τῆς βασιλίσσης θεῖον, τὸν γὰρ Ἀμάνην μέλλειν αὐτὸν αἰτεῖσθαι παρὰ τοῦ βασιλέως πρὸς τιμωρίαν, τότε μὲν ἡσυχίαν ἦγεν. ὡς δὲ ὁ βασιλεὺς μετὰ τοῦ Ἀμάνου εὐωχηθεὶς ἠξίου τὴν βασίλισσαν λέγειν αὐτῷ, τίνος βούλεται δωρεᾶς τυχεῖν, ὡς ληψομένην οὗπερ ἂν ἐπιθυμίαν ἔχῃ, τὸν τοῦ λαοῦ κίνδυνον ἀπωδύρετο καὶ πρὸς ἀπώλειαν ἔλεγεν μετὰ τοῦ ἔθνους ἐκδεδόσθαι, διὸ καὶ ποιεῖσθαι περὶ τούτων τοὺς λόγους· οὐ γὰρ ἂν ἠνωχληκέναι αὐτῷ, εἰ πρὸς δουλείαν πικρὰν ἐκέλευσεν αὐτοὺς ἀπεμποληθῆναι· μέτριον γὰρ τοῦτο τὸ κακόν· παρεκάλει τε τούτων ἀπαλλαγῆναι. ἐρωτήσαντος δὲ τοῦ βασιλέως, ὑπὸ τίνος εἴη ταῦτα γεγενημένα, κατηγόρει τὸ λοιπὸν ἤδη φανερῶς τοῦ Ἀμάνου καὶ τοῦτον ὄντα πονηρὸν ἐπ’ αὐτοὺς κατεσκευακέναι τὴν ἐπιβουλὴν ἤλεγχεν. ταραχθέντος δὲ πρὸς τοῦτο τοῦ βασιλέως καὶ ἀναπηδήσαντος εἰς τοὺς κήπους ἐκ τοῦ συμποσίου, τῆς Ἐσθήρας ὁ Ἀμάνης ἤρξατο δεῖσθαι καὶ παρακαλεῖν συγγνῶναι τῶν ἡμαρτημένων· συνῆκε γὰρ αὐτὸς ἐν κακοῖς ὤν· ἐπί τε τῆς κλίνης αὐτοῦ πεσόντος καὶ τὴν βασίλισσαν παρακαλοῦντος ἐπεισελθὼν ὁ βασιλεὺς καὶ πρὸς τὴν ὄψιν μᾶλλον παροξυνθεὶς εἶπεν, ὦ κάκιστε πάντων, καὶ βιάζεσθαί μου τὴν γυναῖκα ἐπιχειρεῖς; Ἀμάνου δὲ πρὸς τοῦτο καταπλαγέντος καὶ μηδὲν ἔτι φθέγξασθαι δυνηθέντος, καὶ Σαβουζάνης ὁ εὐνοῦχος παρελθὼν κατηγόρει τοῦ Ἀμάνου, ὡς εὕροι σταυρὸν ἐπὶ τῆς οἰκίας αὐτοῦ παρεσκευασμένον ἐπὶ Μαρδοχαῖον τοῦτο γὰρ αὐτῷ πυνθανομένῳ τὸν οἰκέτην εἰπεῖν, ὅτε καλέσων αὐτὸν ἐπὶ τὸ δεῖπνον ἔλθοι πρὸς αὐτόν. εἶναι δὲ τὸν σταυρὸν ἔλεγεν ἑξήκοντα πήχεων τὸ ὕψος. ὁ δὲ βασιλεὺς ἀκούσας οὐκ ἄλλῃ τιμωρίᾳ περιβάλλειν ἔκρινεν τὸν Ἀμάνην ἢ τῇ κατὰ Μαρδοχαίου νενοημένῃ, καὶ κελεύει παραχρῆμα αὐτὸν ἐξ ἐκείνου τοῦ σταυροῦ κρεμασθέντα ἀποθανεῖν. ὅθεν ἐπέρχεταί μοι τὸ θεῖον θαυμάζειν καὶ τὴν σοφίαν αὐτοῦ καὶ δικαιοσύνην καταμανθάνειν, μὴ μόνον τὴν Ἀμάνου κολάσαντος πονηρίαν, ἀλλὰ καὶ τὴν κατ’ ἄλλου μεμηχανημένην τιμωρίαν ταύτην ἐκείνου ποιήσαντος εἶναι καὶ τοῖς ἄλλοις μαθεῖν οὕτως [γνῶναι] παρεσχηκότος, ὡς ἃ καθ’ ἑτέρου τις παρεσκεύασε ταῦτα λανθάνει καθ’ ἑαυτοῦ πρῶτον ἑτοιμασάμενος.", "st": "11.6.11"}, {"sp": "N", "t": "Ἀμάνης μὲν οὖν ἀμετρήτως τῇ παρὰ τοῦ βασιλέως χρώμενος τιμῇ τοῦτον διεφθάρη τὸν τρόπον, τὴν δὲ οὐσίαν αὐτοῦ ἐχαρίσατο τῇ βασιλίσσῃ. Μαρδοχαῖον δὲ προσκαλεσάμενος, καὶ γὰρ ἐδήλωσεν αὐτῷ τὴν πρὸς αὐτὸν συγγένειαν Ἐσθήρα, ὃν ἔδωκεν Ἀμάνῃ δακτύλιον τοῦτον Μαρδοχαίῳ δίδωσι. δωρεῖται δὲ καὶ ἡ βασίλισσα Μαρδοχαίῳ τὴν Ἀμάνου κτῆσιν καὶ δεῖται τοῦ βασιλέως ἀπαλλάξαι τοῦ περὶ τῆς ζωῆς φόβου τὸ τῶν Ἰουδαίων ἔθνος, δηλοῦσα τὰ γραφέντα κατὰ πᾶσαν τὴν χώραν ὑπὸ Ἀμάνου τοῦ Ἀμαδάθου· τῆς γὰρ πατρίδος αὐτῇ διαφθαρείσης καὶ τῶν ὁμοφύλων ἀπολομένων οὐκ ἂν ὑπομένειν τὸν βίον. ὁ δὲ βασιλεὺς ὑπέσχετο μηδὲν ἄχαρι αὐτὴν μηδ’ οἷς ἐσπούδακεν ἐναντίον ἔσεσθαι, γράφειν δὲ ἃ βούλεται προσέταξε περὶ τῶν Ἰουδαίων ἐκείνην ἐκ τοῦ βασιλέως ὀνόματος καὶ σημηναμένην αὐτοῦ τῇ σφραγῖδι πέμπειν εἰς πᾶσαν τὴν βασιλείαν· τοὺς γὰρ ἀναγνωσομένους τὰς ὑπὸ τοῦ βασιλικοῦ σημαντῆρος ἠσφαλισμένας ἐπιστολὰς οὐδὲν περὶ τῶν ἐγγεγραμμένων ἐναντιώσεσθαι. μεταπεμφθέντας οὖν τοὺς βασιλικοὺς γραμματεῖς ἐκέλευσε γράφειν τοῖς ἔθνεσι περὶ τῶν Ἰουδαίων τοῖς τε οἰκονόμοις καὶ ἄρχουσιν ἀπὸ Ἰνδικῆς ἕως τῆς Αἰθιοπίας ἑκατὸν εἰκοσιεπτὰ σατραπειῶν ἡγουμένοις. τὰ δὲ γραφέντα τοῦτον ἔχει τὸν τρόπον· βασιλεὺς μέγας Ἀρταξέρξης τοῖς ἄρχουσι καὶ τὰ ἡμέτερα φρονοῦσι χαίρειν. πολλοὶ διὰ μέγεθος εὐεργεσίας καὶ τιμῆς, ἣν δι’ ὑπερβολὴν χρηστότητος τῶν παρεχόντων ἐκαρποῦντο, οὐκ εἰς τοὺς ὑποδεεστέρους μόνον ἐξυβρίζουσιν, ἀλλ’ οὐδ’ αὐτοὺς ἀδικεῖν ὤκνησαν τοὺς εὐεργετοῦντας τὸ εὐχάριστον ἐξ ἀνθρώπων ἀναιροῦντες, καὶ δι’ ἀπειροκαλίαν τῶν οὐκ ἐξ ὧν προσεδόκησαν ἀγαθῶν κόρον εἰς τοὺς αἰτίους ἀφέντες λήσεσθαι τὸ θεῖον ἐπὶ τούτοις νομίζουσι καὶ τὴν ἐξ αὐτοῦ διαφεύξεσθαι δίκην. ἔνιοι δὲ ἐκ τούτων προστασίαν πραγμάτων ἐπιτραπέντες παρὰ τῶν φίλων καὶ μῖσος ἴδιον ἔχοντες πρός τινας, παραλογισάμενοι τοὺς κρατοῦντας ψευδέσιν αἰτίαις καὶ διαβολαῖς ἔπεισαν κατὰ μηδὲν ἀδικούντων ὀργὴν ἀναλαβεῖν, ὑφ’ ἧς ἐκινδύνευσαν ἀπολέσθαι. τοῦτο δὲ οὐκ ἐκ τῶν ἀρχαιοτέρων οὐδ’ ἀκοῇ γνωρίμων ἡμῖν οὕτως ἰδεῖν ἔστιν ἔχον, ἀλλ’ ἐκ τῶν παρὰ τὰς ἡμετέρας ὄψεις τετολμημένων, ὡς διαβολαῖς μὲν καὶ κατηγορίαις μὴ προσέχειν ἔτι τοῦ λοιποῦ μηδ’ οἷς ἕτεροι πείθειν ἐπιχειροῦσιν, κρίνειν δ’ ὅσα τις αὐτὸς οἶδεν πεπραγμένα, καὶ κολάζειν μὲν ἂν ᾖ τοιαῦτα, χαρίζεσθαι δ’ ἂν ἑτέρως ἔχῃ, τοῖς ἔργοις αὐτοῖς ἀλλὰ μὴ τοῖς λέγουσι προστιθέμενον. ὡς μὲν Ἀμάνης, Ἀμαδάθου μὲν παῖς Ἀμαληκίτης δὲ τὸ γένος, ἀλλότριος ὢν τοῦ Περσῶν αἵματος, ἐπιξενωθεὶς ἡμῖν ἀπέλαυσεν τῆς πρὸς ἅπαντας χρηστότητος ἐπὶ τοσοῦτον, ὡς πατέρα μου τὸ λοιπὸν προσαγορεύεσθαι καὶ προσκυνούμενον διατελεῖν καὶ μεθ’ ἡμᾶς τὰ δεύτερα τῆς βασιλικῆς παρὰ πάντων τιμῆς ἀποφέρεσθαι, τὴν εὐτυχίαν οὐκ ἤνεγκεν οὐδὲ σώφρονι λογισμῷ τὸ μέγεθος τῶν ἀγαθῶν ἐταμίευσεν, ἀλλὰ τῆς βασιλείας ἐπεβούλευσέ με καὶ τῆς ψυχῆς τὸν αἴτιον αὐτῷ τῆς ἐξουσίας ἀφελέσθαι, τὸν εὐεργέτην μου καὶ σωτῆρα Μαρδοχαῖον καὶ τὴν κοινωνὸν ἡμῖν τοῦ τε βίου καὶ τῆς ἀρχῆς Ἐσθῆρα κακούργως καὶ μετὰ ἀπάτης πρὸς ἀπώλειαν αἰτησάμενος· τούτῳ γάρ με τῷ τρόπῳ τῶν εὐνοούντων ἐρημώσας ἐβούλετο τὴν ἀρχὴν εἰς ἄλλους μεταβαλεῖν. ἐγὼ δὲ τοὺς ὑπὸ τοῦ ἀλιτηρίου πρὸς ἀπώλειαν ἐκδοθέντας Ἰουδαίους οὐ πονηροὺς κατανοήσας, ἀλλὰ τὸν ἄριστον πολιτευομένους τρόπον καὶ τῷ θεῷ προσανέχοντας, ὃς ἐμοί τε καὶ τοῖς προγόνοις ἡμῶν τὴν βασιλείαν διεφύλαξεν, οὐ μόνον ἀπολύω τῆς ἐκ τῶν προαπεσταλμένων τιμωρίας, οἷς ποιήσετε καλῶς μὴ προσέχοντες, ἀλλὰ καὶ τιμῆς αὐτοὺς ἁπάσης τυγχάνειν βούλομαι, καὶ τὸν ταῦτα κατ’ αὐτῶν μηχανησάμενον πρὸ τῶν πυλῶν τῶν ἐν Σούσοις ἀνεσταύρωσα μετὰ τῆς γενεᾶς, τοῦ πάντα ἐφορῶντος θεοῦ ταύτην αὐτῷ τὴν δίκην ἐπιβαλόντος. κελεύω δὲ ὑμᾶς τὸ ἀντίγραφον τῆς ἐπιστολῆς ἐκθέντας εἰς ἅπασαν τὴν βασιλείαν τοὺς Ἰουδαίους ἀφεῖναι τοῖς ἰδίοις νόμοις χρωμένους ζῆν μετ’ εἰρήνης καὶ βοηθεῖν αὐτοῖς, ὅπως τοὺς ἐν οἷς ἠτύχησαν καιροῖς ἀδικήσαντας αὐτοὺς ἀμύνωνται, τῇ τρισκαιδεκάτῃ τοῦ δωδεκάτου μηνός, ὅς ἐστιν Ἄδαρ, τῇ αὐτῇ ἡμέρᾳ· ταύτην γὰρ αὐτοῖς ὁ θεὸς ἀντὶ ὀλεθρίας σωτήριον πεποίηκεν. ἔστι δ’ ἀγαθὴ τοῖς εὐνοοῦσιν ἡμῖν ὑπόμνησις δὲ τῆς τῶν ἐπιβουλευσάντων κολάσεως. εἰδέναι μέντοι γε βούλομαι καὶ πόλιν καὶ πᾶν ἔθνος, ἐὰν τῶν γεγραμμένων τινὸς παρακούσῃ, ὅτι καὶ πυρὶ καὶ σιδήρῳ δαπανηθήσεται. τὰ μέντοι γεγραμμένα προτεθήτω καθ’ ὅλης τῆς ἡμῖν ὑπηκόου χώρας, καὶ παρασκευαζέσθωσαν πάντως εἰς τὴν προγεγραμμένην ἡμέραν, ἵνα τοὺς ἐχθροὺς μετέλθωσιν.", "st": "11.6.12"}, {"sp": "N", "t": "Οἱ μὲν οὖν ἱππεῖς οἱ τὰς ἐπιστολὰς διακομίζοντες εὐθὺς ἐξορμήσαντες τὴν προκειμένην ὁδὸν ἤνυον. ὁ δὲ Μαρδοχαῖος ὡς ἀναλαβὼν τὴν βασιλικὴν στολὴν καὶ τὸν στέφανον τὸν χρυσοῦν καὶ τὸν στρεπτὸν περιθέμενος προῆλθεν, ἰδόντες αὐτὸν οὕτως τετιμημένον ὑπὸ τοῦ βασιλέως οἱ ἐν Σούσοις ὄντες Ἰουδαῖοι κοινὴν ὑπέλαβον τὴν εὐπραγίαν αὐτοῦ. χαρὰ δὲ καὶ σωτήριον φέγγος ἐκτιθεμένων τῶν τοῦ βασιλέως γραμμάτων καὶ τοὺς κατὰ πόλιν τῶν Ἰουδαίων καὶ τοὺς κατὰ χώραν ἐπεῖχεν, ὡς πολλὰ καὶ τῶν ἄλλων ἐθνῶν διὰ τὸν ἐκ τῶν Ἰουδαίων φόβον περιτεμνόμενα τὴν αἰδῶ τὸ ἀκίνδυνον αὐτοῖς ἐκ τούτου πραγματεύσασθαι. καὶ γὰρ τοῦ δωδεκάτου μηνὸς τῇ τρισκαιδεκάτῃ, ὃς κατὰ μὲν Ἑβραίους Ἄδαρ καλεῖται κατὰ δὲ Μακεδόνας Δύστρος, οἱ κομίσαντες τὰ τοῦ βασιλέως γράμματα ἐδήλουν, ὅπως καθ’ ἣν ἡμέραν αὐτοὶ κινδυνεύσειν ἤμελλον ἐν ταύτῃ τοὺς ἐχθροὺς ἀπολέσωσιν. οἱ δὲ ἄρχοντες τῶν σατραπειῶν καὶ οἱ τύραννοι καὶ οἱ βασιλεῖς καὶ οἱ γραμματεῖς εἶχον ἐν τιμῇ τοὺς Ἰουδαίους· ὁ γὰρ ἐκ Μαρδοχαίου φόβος ἠνάγκαζεν αὐτοὺς σωφρονεῖν. τοῦ δὲ γράμματος τοῦ βασιλικοῦ διὰ πάσης τῆς ὑπ’ αὐτὸν χώρας γενομένου συνέπεσεν ὥστε καὶ τοὺς ἐν Σούσοις Ἰουδαίους ἀποκτεῖναι τῶν ἐχθρῶν περὶ πεντακοσίους. τοῦ δὲ βασιλέως τῶν ἀπολωλότων δηλώσαντος τὸν ἀριθμὸν Ἐσθήρᾳ καὶ περὶ τῶν ἐπὶ τῆς χώρας τί ποτ’ εἴη γεγονὸς διαποροῦντος καὶ τί πρὸς τούτοις ἔτ’ αὐτοῦ γενέσθαι βούλεται πυνθανομένου, πραχθήσεσθαι γάρ, παρεκάλεσεν ἐπιτραπῆναι τοῖς Ἰουδαίοις καὶ τὴν ἐπιοῦσαν ἡμέραν οὕτως χρήσασθαι τοῖς ὑπολειπομένοις τῶν ἐχθρῶν καὶ τοὺς δέκα τοὺς Ἀμάνου παῖδας ἀνασταυρῶσαι. καὶ τοῦτο μὲν προσέταξε τοῖς Ἰουδαίοις ὁ βασιλεὺς μηδὲν ἀντιλέγειν Ἐσθῆρι δυνάμενος· οἱ δὲ πάλιν συστραφέντες τῇ τετράδι καὶ δεκάτῃ τοῦ Δύστρου μηνὸς ἀπέκτειναν τῶν ἐναντίων ὡς τριακοσίους, καὶ οὐδενὸς τῶν ἐκείνοις ὑπαρχόντων ἥψαντο κτημάτων. ἀπέθανον δὲ καὶ ὑπὸ τῶν ἐν τῇ χώρᾳ καὶ ταῖς ἄλλαις πόλεσιν Ἰουδαίων τῶν ἐχθρῶν αὐτοῖς ἑπτακισμύριοι καὶ πεντακισχίλιοι. καὶ τούτους μὲν ἀπέκτειναν τῇ τρισκαιδεκάτῃ τοῦ μηνός, τὴν δὲ ἐχομένην ἑορτάσιμον ἐποίησαν. ὁμοίως δὲ καὶ οἱ ἐν Σούσοις Ἰουδαῖοι τὴν τετράδα καὶ δεκάτην καὶ τὴν ἐχομένην τοῦ αὐτοῦ μηνὸς συναθροισθέντες εὐωχήθησαν. ὅθεν καὶ νῦν οἱ ἐν τῇ οἰκουμένῃ Ἰουδαῖοι πάντες τὰς ἡμέρας ταύτας ἑορτάζουσιν διαπεμπόμενοι μερίδας ἀλλήλοις. ἔγραψεν δὲ Μαρδοχαῖος τοῖς ἐν τῇ Ἀρταξέρξου βασιλείᾳ [ζῶσιν] Ἰουδαίοις ταύτας παραφυλάσσειν τὰς ἡμέρας καὶ ἑορτὴν ἄγειν αὐτὰς καὶ τοῖς ἐκγόνοις παραδοῦναι τοῦ πρὸς πάντα διαμεῖναι τὸν χρόνον τὴν ἑορτὴν ἕνεκα καὶ μὴ λήθῃ παραπολέσθαι· μελλήσαντας γὰρ αὐτοὺς ἐν ταύταις διαφθείρεσθαι ταῖς ἡμέραις ὑπὸ Ἀμάνου δίκαια ποιήσειν, εἰ διαφυγόντες μὲν ἐν αὐταῖς τὸν κίνδυνον τοὺς δ’ ἐχθροὺς τιμωρησάμενοι παρατηρήσουσιν αὐτὰς εὐχαριστοῦντες τῷ θεῷ. διὰ ταῦτα μὲν οἱ Ἰουδαῖοι τὰς προειρημένας ἡμέρας ἑορτάζουσιν προσαγορεύσαντες αὐτὰς φρουρέας. ὁ δὲ Μαρδοχαῖος μέγας τε ἦν καὶ λαμπρὸς παρὰ τῷ βασιλεῖ καὶ συνδιεῖπεν αὐτῷ τὴν ἀρχὴν ἀπολαύων ἅμα καὶ τῆς κοινωνίας τοῦ βίου τῇ βασιλίσσῃ. ἦν δὲ καὶ τοῖς Ἰουδαίοις τὰ πράγματα δι’ αὐτοὺς ἀμείνω πάσης ἐλπίδος. καὶ τὰ μὲν τούτοις βασιλεύοντος Ἀρταξέρξου συμβάντα τοῦτον εἶχεν τὸν τρόπον.", "st": "11.6.13"}, {"sp": "N", "t": "Ἀποθανόντος δὲ τοῦ ἀρχιερέως Ἐλεασίβου τὴν ἀρχιερωσύνην Ἰώδας ὁ παῖς αὐτοῦ διεδέξατο. τελευτήσαντος δὲ καὶ τούτου τὴν τιμὴν Ἰωάννης υἱὸς ὢν αὐτοῦ παρέλαβεν, δι’ ὃν καὶ Βαγώσης ὁ στρατηγὸς τοῦ [ἄλλου] Ἀρταξέρξου τὸν ναὸν ἐμίανεν καὶ φόρους ἐπέταξε τοῖς Ἰουδαίοις, πρὶν τὰς καθημερινὰς ἐπιφέρειν θυσίας ὑπὲρ ἀρνὸς ἑκάστου τελεῖν αὐτοὺς δημοσίᾳ δραχμὰς πεντήκοντα. τούτου δὲ τὴν αἰτίαν τοιαύτην συνέβη γενέσθαι· ἀδελφὸς ἦν τῷ Ἰωάννῃ Ἰησοῦς· τούτῳ φίλῳ τυγχάνοντι ὁ Βαγώσης ὑπέσχετο τὴν ἀρχιερωσύνην παρέξειν. ἀπὸ ταύτης οὖν τῆς πεποιθήσεως Ἰησοῦς ἐν τῷ ναῷ διενεχθεὶς τῷ Ἰωάννῃ παρώξυνεν τὸν ἀδελφὸν ὥστ’ αὐτὸν ἀνελεῖν καὶ διὰ τὴν ὀργὴν τηλικοῦτο ἀσέβημα δρᾶσαι κατ’ ἀδελφοῦ τὸν Ἰωάννην ἐν τῷ ἱερῷ ὡς δεινὸν ἦν καὶ πρότερον, ὡς μήτε παρ’ Ἕλλησιν μήτε παρὰ βαρβάροις ὠμὸν οὕτως καὶ ἀσεβὲς ἔργον γεγονέναι. τὸ μέντοι θεῖον οὐκ ἠμέλησεν, ἀλλὰ καὶ ὁ λαὸς δι’ αὐτὴν τὴν αἰτίαν ἐδουλώθη καὶ ὁ ναὸς ἐμιάνθη ὑπὸ Περσῶν. Βαγώσης δὲ ὁ στρατηγὸς Ἀρταξέρξου γνούς, ὅτι Ἰωάννης ὁ ἀρχιερεὺς τῶν Ἰουδαίων τὸν ἴδιον ἀδελφὸν Ἰησοῦν ἐν τῷ ἱερῷ ἐφόνευσεν, εὐθὺς ἐπιστὰς τοῖς Ἰουδαίοις μετὰ θυμοῦ ἤρξατο λέγειν· ἐτολμήσατε ἐν τῷ ἱερῷ φόνον ἐργάσασθαι. πειρωμένου δ’ αὐτοῦ εἰσελθεῖν εἰς τὸν ναὸν ἐκώλυον αὐτόν. ὁ δὲ πρὸς αὐτοὺς ἔφη· πῶς οὐκ ἐγὼ καθαρώτερός εἰμι τοῦ ἀνῃρημένου ἐν τῷ ναῷ; καὶ τούτους ποιησάμενος τοὺς λόγους εἰς τὸν ναὸν εἰσέρχεται. ταύτῃ μὲν οὖν χρησάμενος τῇ ἐπινοίᾳ Βαγώσης τοὺς Ἰουδαίους ἔτεσιν ἑπτὰ ὑπὲρ τῆς Ἰησοῦ τελευτῆς μετῆλθεν.", "st": "11.7.1"}, {"sp": "N", "t": "Καταστρέψαντος δὲ τοῦ Ἰωάννου τὸν βίον διαδέχεται τὴν ἀρχιερωσύνην ὁ υἱὸς αὐτοῦ Ἰαδδοῦς. ἦν δὲ καὶ τούτῳ ἀδελφὸς Μανασσῆς ὄνομα, ᾧ Σαναβαλλέτης ὁ πεμφθεὶς εἰς Σαμάρειαν ὑπὸ Δαρείου τοῦ τελευταίου βασιλέως σατράπης Χουθαῖος τὸ γένος, ἐξ ὧν καὶ οἱ Σαμαρεῖς εἰσιν, εἰδὼς λαμπρὰν οὖσαν τὴν πόλιν Ἱεροσόλυμα καὶ πολλὰ τοῖς Ἀσσυρίοις καὶ τοῖς ἐν τῇ κοίλῃ Συρίᾳ κατοικοῦσιν τοὺς ἐν αὐτῇ βασιλεῖς πράγματα παρασχόντας, ἀσμένως συνῴκισεν τὴν αὐτοῦ θυγατέρα Νικασὼ καλουμένην, οἰόμενος τὴν ἐπιγαμίαν ὅμηρον αὐτῷ γενήσεσθαι πρὸς τὴν ἀπὸ τοῦ τῶν Ἰουδαίων ἔθνους παντὸς εὔνοιαν.", "st": "11.7.2"}, {"sp": "N", "t": "Κατὰ τοῦτον δὴ τὸν καιρὸν καὶ Φίλιππος ὁ Μακεδόνων βασιλεὺς ἐν Αἰγαῖς ὑπὸ Παυσανίου τοῦ Κεράστου ἐκ δὲ τοῦ τῶν Ὀρεστῶν γένους δολοφονηθεὶς ἀπέθανεν. παραλαβὼν δ’ ὁ παῖς αὐτοῦ τὴν βασιλείαν Ἀλέξανδρος καὶ διαβὰς τὸν Ἑλλήσποντον, νικᾷ μὲν τοὺς Δαρείου στρατηγοὺς ἐπὶ Γρανίκῳ συμβαλὼν αὐτοῖς, ἐπελθὼν δὲ τὴν Λυδίαν καὶ τὴν Ἰωνίαν δουλωσάμενος καὶ τὴν Καρίαν ἐπιδραμὼν τοῖς ἐν Παμφυλίᾳ τόποις ἐπέβαλεν, καθὼς ἐν ἄλλοις δεδήλωται.", "st": "11.8.1"}, {"sp": "N", "t": "Οἱ δὲ τῶν Ἱεροσολυμιτῶν πρεσβύτεροι δεινοπαθοῦντες ἐπὶ τῷ τὸν Ἰαδδοῦ τοῦ ἀρχιερέως ἀδελφὸν ἀλλοφύλῳ συνοικοῦντα μετέχειν τῆς ἀρχιερωσύνης ἐστασίαζον πρὸς αὐτόν· ἡγοῦντο γὰρ τὸν τούτου γάμον ἐπιβάθραν τοῖς παρανομεῖν περὶ τὰς τῶν γυναικῶν συνοικήσεις βουλησομένοις γενέσθαι καὶ τῆς πρὸς τοὺς ἀλλοφύλους αὐτοῖς κοινωνίας ἀρχὴν τοῦτο ἔσεσθαι. ὑπάρξαι μέντοι καὶ τῆς προτέρας αἰχμαλωσίας αὐτοῖς καὶ τῶν κακῶν αἴτιον τὸ περὶ τοὺς γάμους πλημμελῆσαί τινας καὶ ἀγαγέσθαι γυναῖκας οὐκ ἐπιχωρίας. ἐκέλευον οὖν τὸν Μανασσῆν διαζεύγνυσθαι τῆς γυναικὸς ἢ μὴ προσιέναι τῷ θυσιαστηρίῳ. τοῦ δ’ ἀρχιερέως τῷ λαῷ συναγανακτοῦντος καὶ εἴργοντος τὸν ἀδελφὸν τοῦ βωμοῦ, παραγενόμενος ὁ Μανασσῆς πρὸς τὸν πενθερὸν Σαναβαλλέτην στέργειν μὲν ἔλεγεν αὐτοῦ τὴν θυγατέρα Νικασώ, τῆς μέντοι γε ἱερατικῆς τιμῆς μεγίστης οὔσης ἐν τῷ ἔθνει καὶ τῷ γένει παραμενούσης οὐ βούλεσθαι δι’ αὐτὴν στέρεσθαι. τοῦ δὲ Σαναβαλλέτου μὴ μόνον τηρήσειν αὐτῷ τὴν ἱερωσύνην, ἀλλὰ καὶ τὴν ἀρχιερατικὴν παρέξειν δύναμιν καὶ τιμὴν ὑπισχνουμένου καὶ πάντων ἀποδείξειν ὧν αὐτὸς ἐπῆρχεν τόπων ἡγεμόνα βουλόμενον συνοικεῖν αὐτοῦ τῇ θυγατρί, καὶ λέγοντος οἰκοδομήσειν ναὸν ὅμοιον ὄντα τῷ ἐν τοῖς Ἱεροσολύμοις ἐπὶ τοῦ Γαριζεὶν ὄρους, ὃ τῶν κατὰ τὴν Σαμάρειαν ὀρῶν ἐστιν ὑψηλότατον, καὶ ταῦτα ποιήσειν ἐπαγγελλομένου μετὰ τῆς Δαρείου γνώμης τοῦ βασιλέως, ἐπαρθεὶς ταῖς ὑποσχέσεσιν ὁ Μανασσῆς παρέμενεν τῷ Σαναβαλλέτῃ τὴν ἀρχιερωσύνην οἰόμενος ἕξειν Δαρείου δόντος· καὶ γὰρ συνέβαινεν τὸν Σαναβαλλέτην ἤδη πρεσβύτερον εἶναι. πολλῶν δὲ ἱερέων καὶ Ἰσραηλιτῶν τοιούτοις γάμοις ἐπιπεπλεγμένων κατεῖχεν οὐ μικρὰ ταραχὴ τοὺς Ἱεροσολυμίτας· ἀφίσταντο γὰρ ἅπαντες πρὸς τὸν Μανασσῆν τοῦ Σαναβαλλέτου χορηγοῦντος αὐτοῖς καὶ χρήματα καὶ χώραν εἰς γεωργίαν καὶ κατοίκησιν ἀπομερίζοντος καὶ παντὶ τρόπῳ τῷ γαμβρῷ συμφιλοκαλοῦντος.", "st": "11.8.2"}, {"sp": "N", "t": "Κατὰ δὲ τοῦτον τὸν καιρὸν Δαρεῖος ἀκούσας, ὅτι τὸν Ἑλλήσποντον διαβὰς Ἀλέξανδρος καὶ τοὺς σατράπας αὐτοῦ τῇ κατὰ Γράνικον μάχῃ κρατήσας προσωτέρω χωρεῖ, στρατιὰν ἱππικήν τε καὶ πεζικὴν συνήθροιζεν ἀπαντῆσαι διαγνοὺς τοῖς Μακεδόσιν πρὶν ἢ πᾶσαν αὐτοὺς ἐπιόντας καταστρέψασθαι τὴν Ἀσίαν. περαιωσάμενος οὖν τὸν Εὐφράτην ποταμὸν καὶ τὸν Ταῦρον τὸ Κιλίκιον ὄρος ὑπερελθὼν ἐν Ἰσσῷ τῆς Κιλικίας τοὺς πολεμίους ὡς ἐκεῖ μαχησόμενος αὐτοῖς ἐξεδέχετο. ἡσθεὶς δὲ τῇ Δαρείου καταβάσει ὁ Σαναβαλλέτης εὐθὺς ἔλεγεν τῷ Μανασσῇ τὰς ὑποσχέσεις τελέσειν, ὡς ἂν Δαρεῖος κρατήσας τῶν πολεμίων ὑποστρέψῃ· πέπειστο γὰρ οὐκ αὐτὸς μόνος ἀλλὰ καὶ πάντες οἱ ἐν τῇ Ἀσίᾳ μηδ’ εἰς χεῖρας τοῖς Πέρσαις ἥξειν τοὺς Μακεδόνας διὰ τὸ πλῆθος. ἀπέβη δ’ οὐχ ὡς προσεδόκων· συμβαλὼν γὰρ ὁ βασιλεὺς τοῖς Μακεδόσιν ἡττήθη καὶ πολλὴν τῆς στρατιᾶς ἀπολέσας ληφθέντων αἰχμαλώτων αὐτοῦ τῆς μητρὸς καὶ γυναικὸς καὶ τῶν τέκνων ἔφυγεν εἰς Πέρσας. Ἀλέξανδρος δ’ εἰς Συρίαν παραγενόμενος Δαμασκὸν αἱρεῖ καὶ Σιδῶνος κρατήσας ἐπολιόρκει Τύρον, ἠξίου τε ἀποστείλας γράμματα πρὸς τὸν τῶν Ἰουδαίων ἀρχιερέα συμμαχίαν τε αὐτῷ πέμπειν καὶ ἀγορὰν τῷ στρατεύματι παρασχεῖν καὶ ὅσα Δαρείῳ πρότερον ἐτέλουν δῶρα τούτῳ διδόναι τὴν Μακεδόνων φιλίαν ἑλομένους· οὐ γὰρ μετανοήσειν ἐπὶ τούτοις. τοῦ δ’ ἀρχιερέως ἀποκριναμένου τοῖς γραμματοφόροις, ὡς ὅρκους εἴη δεδωκὼς Δαρείῳ μὴ βαστάζειν ὅπλα κατ’ αὐτοῦ, καὶ τούτους ἕως ἂν ᾖ Δαρεῖος ἐν τοῖς ζῶσιν μὴ παραβήσεσθαι φήσαντος, ἀκούσας Ἀλέξανδρος παρωξύνθη, καὶ τὴν μὲν Τύρον οὐκ ἔκρινεν καταλιπεῖν ὅσον οὐδέπω μέλλουσαν αἱρεῖσθαι, παραστησάμενος δὲ ταύτην ἠπείλει στρατεύσειν ἐπὶ τὸν τῶν Ἰουδαίων ἀρχιερέα καὶ διδάξειν πάντας, πρὸς τίνας δὴ αὐτοῖς φυλακτέον τοὺς ὅρκους· ὅθεν πονικώτερον χρησάμενος τῇ πολιορκίᾳ λαμβάνει τὴν Τύρον. καταστησάμενος δὲ τὰ ἐν αὐτῇ ἐπὶ τὴν τῶν Γαζαίων πόλιν ἦλθεν καὶ τήν τε Γάζαν καὶ τὸν ἐν αὐτῇ φρούραρχον ὄνομα Βαβημάσιν ἐπολιόρκει.", "st": "11.8.3"}, {"sp": "N", "t": "Νομίσας δὲ καιρὸν ἐπιτήδειον ἔχειν ὁ Σαναβαλλέτης τῆς ἐπιβολῆς Δαρείου μὲν ἀπέγνω, λαβὼν δὲ ὀκτακισχιλίους τῶν ἀρχομένων ὑπ’ αὐτοῦ πρὸς Ἀλέξανδρον ἧκεν καὶ καταλαβὼν αὐτὸν ἀρχόμενον τῆς Τύρου πολιορκίας, ὧν τε αὐτὸς ἄρχει τόπων ἔλεγεν αὐτῷ παραδιδόναι τούτους καὶ δεσπότην αὐτὸν ἡδέως ἔχειν ἀντὶ Δαρείου τοῦ βασιλέως. ἀσμένως δ’ αὐτὸν προσδεξαμένου θαρρῶν ἤδη περὶ τῶν προκειμένων ὁ Σαναβαλλέτης αὐτῷ λόγους προσέφερεν δηλῶν, ὡς γαμβρὸν μὲν ἔχοι Μανασσῆ τοῦ τῶν Ἰουδαίων ἀρχιερέως Ἰαδδοῦ ἀδελφόν, πολλοὺς δὲ καὶ ἄλλους αὐτῷ συμπαρόντας τῶν ὁμοεθνῶν θέλειν ἱερὸν ἐν τοῖς ὑπ’ ἐκείνῳ τόποις ἤδη κατασκευάσαι. τοῦτο δ’ εἶναι καὶ τῷ βασιλεῖ συμφέρον εἰς δύο διῃρῆσθαι τὴν Ἰουδαίων δύναμιν, ἵνα μὴ ὁμογνωμονοῦν τὸ ἔθνος μηδὲ συνεστός, εἰ νεωτερίσειέν ποτε, χαλεπὸν ᾖ τοῖς βασιλεῦσιν, καθὼς καὶ πρότερον τοῖς Ἀσσυρίων ἄρξασιν ἐγένετο. συγχωρήσαντος δὲ Ἀλεξάνδρου πᾶσαν εἰσενεγκάμενος σπουδὴν ᾠκοδόμησεν ὁ Σαναβαλλέτης τὸν ναὸν καὶ ἱερέα τὸν Μανασσῆ κατέστησεν, μέγιστον γέρας ἡγησάμενος τοῖς ἐκ τῆς θυγατρὸς γενησομένοις τοῦτ’ ἔσεσθαι. μηνῶν δ’ ἑπτὰ τῇ Τύρου πολιορκίᾳ διεληλυθότων καὶ δύο τῇ Γάζης ὁ μὲν Σαναβαλλέτης ἀπέθανεν. Ἀλέξανδρος δ’ ἐξελὼν τὴν Γάζαν ἐπὶ τὴν τῶν Ἱεροσολυμιτῶν πόλιν ἀναβαίνειν ἐσπουδάκει. ὁ δ’ ἀρχιερεὺς Ἰαδδοῦς τοῦτ’ ἀκούσας ἦν ἐν ἀγωνίᾳ καὶ δέει, πῶς ἀπαντήσει τοῖς Μακεδόσιν ἀμηχανῶν ὀργιζομένου τοῦ βασιλέως ἐπὶ τῇ πρότερον ἀπειθείᾳ. παραγγείλας οὖν ἱκεσίαν τῷ λαῷ καὶ θυσίαν τῷ θεῷ μετ’ αὐτοῦ προσφέρων ἐδεῖτο ὑπερασπίσαι τοῦ ἔθνους καὶ τῶν ἐπερχομένων κινδύνων ἀπαλλάξαι. κατακοιμηθέντι δὲ μετὰ τὴν θυσίαν ἐχρημάτισεν αὐτῷ κατὰ τοὺς ὕπνους ὁ θεὸς θαρρεῖν καὶ στεφανοῦντας τὴν πόλιν ἀνοίγειν τὰς πύλας, καὶ τοὺς μὲν ἄλλους λευκαῖς ἐσθῆσιν, αὐτὸν δὲ μετὰ τῶν ἱερέων ταῖς νομίμοις στολαῖς ποιεῖσθαι τὴν ὑπάντησιν μηδὲν προσδοκῶντας πείσεσθαι δεινὸν προνοουμένου τοῦ θεοῦ. διαναστὰς δὲ ἐκ τοῦ ὕπνου ἔχαιρέν τε μεγάλως αὐτὸς καὶ τὸ χρηματισθὲν αὐτῷ πᾶσι μηνύσας καὶ ποιήσας ὅσα κατὰ τοὺς ὕπνους αὐτῷ παρηγγέλη τὴν τοῦ βασιλέως παρουσίαν ἐξεδέχετο.", "st": "11.8.4"}, {"sp": "N", "t": "Πυθόμενος δ’ αὐτὸν οὐ πόρρω τῆς πόλεως ὄντα πρόεισι μετὰ τῶν ἱερέων καὶ τοῦ πολιτικοῦ πλήθους, ἱεροπρεπῆ καὶ διαφέρουσαν τῶν ἄλλων ἐθνῶν ποιούμενος τὴν ὑπάντησιν εἰς τόπον τινὰ Σαφειν λεγόμενον. τὸ δὲ ὄνομα τοῦτο μεταφερόμενον εἰς τὴν Ἑλληνικὴν γλῶτταν σκοπὸν σημαίνει· τά τε γὰρ Ἱεροσόλυμα καὶ τὸν ναὸν συνέβαινεν ἐκεῖθεν ἀφορᾶσθαι. τῶν δὲ Φοινίκων καὶ τῶν ἀκολουθούντων Χαλδαίων ὅσα βασιλέως ὀργὴν εἰκὸς ἦν ἐπιτρέψειν αὐτοῖς τήν τε πόλιν διαρπάσειν καὶ τὸν ἀρχιερέα μετ’ αἰκίας ἀπολέσειν λογιζομένων, τὰ ἐναντία τούτων ἐγένετο. ὁ γὰρ Ἀλέξανδρος ἔτι πόρρωθεν ἰδὼν τὸ μὲν πλῆθος ἐν ταῖς λευκαῖς ἐσθῆσιν, τοὺς δὲ ἱερεῖς προεστῶτας ἐν ταῖς βυσσίναις αὐτῶν, τὸν δὲ ἀρχιερέα ἐν τῇ ὑακινθίνῳ καὶ διαχρύσῳ στολῇ καὶ ἐπὶ τῆς κεφαλῆς ἔχοντα τὴν κίδαριν καὶ τὸ χρυσοῦν ἐπ’ αὐτῆς ἔλασμα, ᾧ τὸ τοῦ θεοῦ ἐγέγραπτο ὄνομα, προσελθὼν μόνος προσεκύνησεν τὸ ὄνομα καὶ τὸν ἀρχιερέα πρῶτος ἠσπάσατο. τῶν δὲ Ἰουδαίων ὁμοῦ πάντων μιᾷ φωνῇ τὸν Ἀλέξανδρον ἀσπασαμένων καὶ κυκλωσαμένων αὐτόν, οἱ μὲν τῆς Συρίας βασιλεῖς καὶ οἱ λοιποὶ τοῦτο ποιήσαντος κατεπλάγησαν καὶ διεφθάρθαι τῷ βασιλεῖ τὴν διάνοιαν ὑπελάμβανον, Παρμενίωνος δὲ μόνου προσελθόντος αὐτῷ καὶ πυθομένου, τί δήποτε προσκυνούντων αὐτὸν ἁπάντων αὐτὸς προσκυνήσειεν τὸν Ἰουδαίων ἀρχιερέα; οὐ τοῦτον, εἶπεν, προσεκύνησα, τὸν δὲ θεόν, οὗ τὴν ἀρχιερωσύνην οὗτος τετίμηται· τοῦτον γὰρ καὶ κατὰ τοὺς ὕπνους εἶδον ἐν τῷ νῦν σχήματι ἐν Δίῳ τῆς Μακεδονίας τυγχάνων, καὶ πρὸς ἐμαυτὸν διασκεπτομένῳ μοι, πῶς ἂν κρατήσαιμι τῆς Ἀσίας, παρεκελεύετο μὴ μέλλειν ἀλλὰ θαρσοῦντα διαβαίνειν· αὐτὸς γὰρ ἡγήσεσθαί μου τῆς στρατιᾶς καὶ τὴν Περσῶν παραδώσειν ἀρχήν. ὅθεν ἄλλον μὲν οὐδένα θεασάμενος ἐν τοιαύτῃ στολῇ, τοῦτον δὲ νῦν ἰδὼν καὶ τῆς κατὰ τοὺς ὕπνους ἀναμνησθεὶς ὄψεώς τε καὶ παρακελεύσεως, νομίζω θείᾳ πομπῇ τὴν στρατείαν πεποιημένος Δαρεῖον νικήσειν καὶ τὴν Περσῶν καταλύσειν δύναμιν καὶ πάνθ’ ὅσα κατὰ νοῦν ἐστί μοι προχωρήσειν. ταῦτ’ εἰπὼν πρὸς τὸν Παρμενίωνα καὶ δεξιωσάμενος τὸν ἀρχιερέα τῶν Ἰουδαίων παραθεόντων εἰς τὴν πόλιν παραγίνεται. καὶ ἀνελθὼν ἐπὶ τὸ ἱερὸν θύει μὲν τῷ θεῷ κατὰ τὴν τοῦ ἀρχιερέως ὑφήγησιν, αὐτὸν δὲ τὸν ἀρχιερέα καὶ τοὺς ἱερεῖς ἀξιοπρεπῶς ἐτίμησεν. δειχθείσης δ’ αὐτῷ τῆς Δανιήλου βίβλου, ἐν ᾗ τινα τῶν Ἑλλήνων καταλύσειν τὴν Περσῶν ἀρχὴν ἐδήλου, νομίσας αὐτὸς εἶναι ὁ σημαινόμενος τότε μὲν ἡσθεὶς ἀπέλυσε τὸ πλῆθος, τῇ δ’ ἐπιούσῃ προσκαλεσάμενος ἐκέλευσεν αὐτοὺς αἰτεῖσθαι δωρεάς, ἃς ἂν αὐτοὶ θέλωσιν. τοῦ δ’ ἀρχιερέως αἰτησαμένου χρήσασθαι τοῖς πατρίοις νόμοις καὶ τὸ ἕβδομον ἔτος ἀνείσφορον εἶναι, συνεχώρησεν πάντα. παρακαλεσάντων δ’ αὐτόν, ἵνα καὶ τοὺς ἐν Βαβυλῶνι καὶ Μηδίᾳ Ἰουδαίους τοῖς ἰδίοις ἐπιτρέψῃ νόμοις χρῆσθαι, ἀσμένως ὑπέσχετο ποιήσειν ἅπερ ἀξιοῦσιν. εἰπόντος δ’ αὐτοῦ πρὸς τὸ πλῆθος, εἴ τινες αὐτῷ βούλονται συστρατεύειν τοῖς πατρίοις ἔθεσιν ἐμμένοντες καὶ κατὰ ταῦτα ζῶντες, ἑτοίμως ἔχειν ἐπάγεσθαι, πολλοὶ τὴν σὺν αὐτῷ στρατείαν ἠγάπησαν.", "st": "11.8.5"}, {"sp": "N", "t": "Ὁ μὲν οὖν Ἀλέξανδρος ταῦτα διοικησάμενος ἐν τοῖς Ἱεροσολύμοις ἐξεστράτευσεν ἐπὶ τὰς ἐχομένας πόλεις. πάντων δ’ αὐτὸν πρὸς οὓς ἀφίκοιτο φιλοφρόνως ἐκδεχομένων, Σαμαρεῖται μητρόπολιν τότε τὴν Σίκειμαν ἔχοντες κειμένην πρὸς τῷ Γαριζεὶν ὄρει καὶ κατῳκημένην ὑπὸ τῶν ἀποστατῶν τοῦ Ἰουδαίων ἔθνους, ἰδόντες ὅτι τοὺς Ἰουδαίους Ἀλέξανδρος οὕτω λαμπρῶς τετίμηκεν ἔγνωσαν αὑτοὺς Ἰουδαίους ὁμολογεῖν. εἰσὶν γὰρ οἱ Σαμαρεῖς τοιοῦτοι τὴν φύσιν, ὡς ἤδη που καὶ πρότερον δεδηλώκαμεν· ἐν μὲν ταῖς συμφοραῖς ὄντας τοὺς Ἰουδαίους ἀρνοῦνται συγγενεῖς ὁμολογοῦντες τότε τὴν ἀλήθειαν, ὅταν δέ τι λαμπρὸν περὶ αὐτοὺς ἴδωσιν ἐκ τύχης, ἐπιπηδῶσιν αὐτῶν τῇ κοινωνίᾳ προσήκειν αὐτοῖς λέγοντες καὶ ἐκ τῶν Ἰωσήπου γενεαλογοῦντες αὑτοὺς ἐκγόνων Ἐφραίμου καὶ Μανασσοῦς. μετὰ λαμπρότητος οὖν καὶ πολλὴν ἐνδεικνύμενοι τὴν περὶ αὐτὸν προθυμίαν ἀπήντησαν τῷ βασιλεῖ μικροῦ δεῖν ἐγγὺς τῶν Ἱεροσολύμων. ἐπαινέσαντος δὲ αὐτοὺς Ἀλεξάνδρου οἱ Σικιμῖται προσῆλθον αὐτῷ προσπαραλαβόντες καὶ οὓς Σαναβαλλέτης πρὸς αὐτὸν στρατιώτας ἀπέστειλεν καὶ παρεκάλουν παραγενόμενον εἰς τὴν πόλιν αὐτῶν τιμῆσαι καὶ τὸ παρ’ αὐτοῖς ἱερόν. ὁ δ’ ἐκεῖνο μὲν αὖθις ὑποστρέφων ἰδεῖν ὑπέσχετο πρὸς αὐτούς, ἀξιούντων δὲ ἀφεῖναι τὸν φόρον αὐτοῖς τοῦ ἑβδοματικοῦ ἔτους, οὐδὲ γὰρ αὐτοὺς ἐν αὐτῷ σπείρειν, τίνες ὄντες ταῦτα παρακαλοῦσιν ἐπυνθάνετο. τῶν δ’ εἰπόντων Ἑβραῖοι μὲν εἶναι, χρηματίζειν δ’ οἱ ἐν Σικίμοις Σιδώνιοι, πάλιν αὐτοὺς ἐπηρώτησεν, εἰ τυγχάνουσιν Ἰουδαῖοι. τῶν δ’ οὐκ εἶναι φαμένων ἀλλ’ ἔγωγε ταῦτ’, εἶπεν, Ἰουδαίοις ἔδωκα, ὑποστρέψας μέντοι γε καὶ διδαχθεὶς ὑφ’ ὑμῶν ἀκριβέστερον ποιήσω τὰ δόξαντα. τοῖς μὲν οὖν Σικιμίταις οὕτως ἀπετάξατο. τοὺς δὲ τοῦ Σαναβαλλέτου στρατιώτας ἐκέλευσεν ἕπεσθαι εἰς Αἴγυπτον· ἐκεῖ γὰρ αὐτοῖς δώσειν κλήρους γῆς· ὃ καὶ μετ’ ὀλίγον ἐποίησεν ἐν τῇ Θηβαΐδι φρουρεῖν τὴν χώραν αὐτοῖς προστάξας.", "st": "11.8.6"}, {"sp": "N", "t": "Τελευτήσαντος δὲ Ἀλεξάνδρου ἡ μὲν ἀρχὴ εἰς τοὺς διαδόχους ἐμερίσθη, τὸ δὲ ἐπὶ τοῦ Γαριζεὶν ὄρους ἱερὸν ἔμεινεν. εἰ δέ τις αἰτίαν ἔσχεν παρὰ τοῖς Ἱεροσολυμίταις κοινοφαγίας ἢ τῆς ἐν σαββάτοις παρανομίας ἤ τινος ἄλλου τοιούτου ἁμαρτήματος, παρὰ τοὺς Σικιμίτας ἔφευγεν λέγων ἀδίκως ἐκβεβλῆσθαι. τετελευτήκει δὲ κατ’ ἐκεῖνον ἤδη τὸν καιρὸν καὶ ὁ ἀρχιερεὺς Ἰαδδοῦς καὶ τὴν ἀρχιερωσύνην Ὀνίας ὁ παῖς αὐτοῦ παρειλήφει. τὰ μὲν δὴ περὶ τοὺς Ἱεροσολυμίτας ἐν τούτοις ἐτύγχανεν ὄντα.", "st": "11.8.7"}], []);})();
